INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(264595, 'ه', '<span class=\"hlight\">ه .</span> <font color=\"DarkGreen\"><b>[ هَِ<span class=\"hlight\" dir=\"rtl\">/</span> ها ]</font></b> (ع حرف، ضمیر) در عربی بر حسب لهجه های مختلف گاهی این حرف به حروف دیگری تبدیل شود یا بدل از آنها آید.<br>اَ: هَثَر، اَثَر. هراق، اراق . هراقه، اَراقَه ... هناره، اناره . هیم اﷲ، ایم اﷲ. ث : لُهاة، لثاة. ج : ماه، ماج .ح : گناه، جُناح . خ : بهباه، بخباخ . ف : جوهر، جوفر. ی : زهرفوه، زیرفوه . و در تعریب های غیرملفوظ یا مختفی به این حروف بدل شود: ج : بابونه، بابونج . برنامه، برنامج . بهرامه، بهرامج . بنفشه، بنفسج . پُرزه، بُرزَج .پالوده، فالوذج . پیشاره، فیشارج . شبه، شبج . شهدانه، شهدانج . کره، کرج . لوزینه، لوزینج . گوزینه، جوزینج .می پخته، می فختج . ح : اَبه، ابح . ق : پسته، فستق . بیجاده، بیجادق . خیوه، خیوق . شاهدانه، شاهدانق . حرف «هَ» در عربی بر پنج گونه است : <span class=\"hlight\" dir=\"rtl\">١</span>- ضمیر غایب است و در موقع نصب و جر استعمال میشود، مانند: قال له صاحبه وهو یحاوره، و تلفظ این هاء بعد از کسره با یاء ساکن هنگامی که پس از آن حرف الف نباشد به کسر و در جز این موارد به ضم است . <span class=\"hlight\" dir=\"rtl\">٢</span>- حرف غیبت باشد مانند «هاء» در کلمه ٔ ایاه . <span class=\"hlight\" dir=\"rtl\">٣</span>- هاء سکت و آن برای بیان حرکت و یا حرفی به آخر کلمه ملحق میشود، مانند: ماهیه و هاهناه و از یداه و اصل این است که بر آن وقف کنند و بعضی از اوقات به نیت وقف وصل میشود. <span class=\"hlight\" dir=\"rtl\">٤</span>- هاء بدل از الف استفهام، مانند <span class=\"hlight\">:</span> <br>و اتی صواحبها فقلن هذا الذی <br>منح المودة غیرنا و جفانا.<br>یعنی اَذا و بعضی گفته اند در اصل هذا بوده و حرف الف به ضرورت وزن افتاده است . <span class=\"hlight\" dir=\"rtl\">٥</span>- هاء تأنیث است، مانند رحمة در حال وقف و این قول کوفیان است که گمان کرده اند هاء اصل است و تاء، در حال وصل بدل از هاء میباشد و عقیده ٔ بصریان برعکس این است و حقیقت امر این است که اگر به قول کوفیان قائل شویم هاء را به شمارنیاوریم زیرا حرف مستقلی نیست، بلکه جزء کلمه میباشد. (از اقرب الموارد از مغنی به تصرف ).<br>ضمیرهای عربی هنگامی که ماقبل مکسور باشدکسره ٔ «هاء» اشباع میشود و به صورت «یا» تلفظ میگردد و هنگامی که ماقبل آن مضموم باشد ضمه ٔ «هاء» پس ازاشباع به «واو» بدل میشود و به همین سبب اینگونه رادر فارسی با کلمه های مختوم به «و» و «ی » قافیه کنند:<br>فهم نان کردن نه حکمت ای رهی <br>زآنکه حق گفتت کُلو مِن رزقه .<br> <font color=\"Red\">مولوی .</font><br>بار دیگر بایدم جستن ز جو<br>کل شی ٔ هالک الا وجهه .<br> <font color=\"Red\">مولوی .</font><br>های تأنیث در حال نسبت : در اسمهای مؤنث منسوب «تاء» (علامت تأنیث ) در نسبت می افتد، مانند: ناصرة، ناصری . همچنین در کلمه هائی که بر وزن «فَعیلَة» یا «فُعَیْلَة» باشد نیز «ة» حذف میشود: اُمَیْمَة، اُمَیْمی ّ. طَویلة، طَویلی ّ. غَریزة، غَریزی ّ. فَریضة، فَرَضی ّ. قُلَیْلَة، قُلَیْلی ّ. مَدینة، مَدَنی ّ. کلمات زیر از قاعده ٔ فوق مستثناست : اُمَیَّة، اَمَوی ّ. بادیة، بَدَوی ّ. تِهامة، تِهامی ّ و تَهام . خُزَیْنَة، خُزَیْنی ّ. رُدَیْنَة، رُدَیْنی ّ. سَلیقة، سَلیقی ّ. سُلَیْم، سُلَمی ّ. لِحْیَة، لِحْیانی ّ. ناصِرَة، نَصْرانی ّ. در فرهنگ آنندراج آمده است : های هر کلمه ای که در آخر آن بود چون یای نسبت بدان ملحق کنند آن «هاء» به واو بدل شود، چون : تنوی (از تنة) و زهروی (از زهرة) و کروی (از کرة) و گاهی «و» را حذف کنند و گویند «کری ». از اوحدالدین انوری :<br>داد یک عالم بهشتی روی ازرق پوش را<br>خوشترین رنگی منور بهترین شکلی کری .<br>تا بُوَد بزم زهروی را گل <br>تا بُوَد نیش  عقربی را خار.<br></font></div>'),
(264596, 'ه', '<span class=\"hlight\">ه.</span> (حرف ) حرف سی ویکم است از حروف هجای فارسی و بیست وهفتم از حروف هجای عربی . نام آن «ها» ونشانه ٔ آن در تحریر «هَ، ه » است و به حساب جمل آن را به پنج دارند. و آن از حروف حلقی و ناریه و مرفوع و مصمته است و در علم نجوم و معما رمز و نشانه ٔ زهره و رمز سنه ٔ هجری و رمز برج سنبله است . «ه » بر دو قسم است : های مختفی، و های غیرمختفی . و های غیرمختفی آن است که تلفظ شود، مانند: چاه، راه، رهی . های مختفی آن است که تلفظ نشود و برای بیان حرکت (فتحه و گاه کسره ٔ) حرف ماقبل خود باشد، مانند: خانه . کاشانه .<br>ابدالها:<br>الف - های غیرمختفی گاهی برحسب لهجه های گوناگون به حرف دیگر بدل شود و گاه بدل از حرف دیگری آید واینک مثال آنها و شواهدی برای برخی از آنها:<br>ابدالها:<br>> گاه تبدیل به همزه شود، چون :<br>هیچ = ایچ .<br>هپیون = ابیون .<br>هزاره = ازاره .<br>هست = است .<br>همباز =انباز.<br>هنگامه = انگامه <span class=\"hlight\">:</span> <br>چو گرسیوز از چاه او بازگشت <br>منیژه ابا درد انباز گشت .<br> <font color=\"Red\">فردوسی (شاهنامه چ بروخیم ص <span class=\"hlight\" dir=\"rtl\">١٠٩١</span>)</font><br>علم با تو نگوید ایچ سخن <br>زآنکه داند تویی نه مرد و نه زن <br>خلق خود بهره مند وهیچ نیند<br>همه را آزمودم ایچ نبیند.<br> <font color=\"Red\">سنایی </font><br>انگامه ای است گرم ز شکر عواطفت <br>هر کوی و برزنی که من آنجافرارسم .<br> <font color=\"Red\">کمال اسماعیل </font><br>> گاه تبدیل به «ب » شود:<br>شناه = شناب <span class=\"hlight\">:</span> <br>در آن زمین که یکی روز رزم ساخته ای <br>پلنگ و شیر به خون اندرون کنند شناه .<br> <font color=\"Red\">قطران (از احوال و اشعار رودکی تألیف نفیسی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥٩</span>).</font><br>> گاه تبدیل به «ت » شود:<br>بارهنگ = بارتنگ .<br>> گاه تبدیل به «ج » شود:<br>ماه = ماج .<br>ناگاه = ناگاج <span class=\"hlight\">:</span> <br>چو تو شاه ننشست برتخت عاج <br>فروغ از تو گیرد همه مهر و ماج .<br> <font color=\"Red\">فردوسی (شاهنامه چ بروخیم ص <span class=\"hlight\" dir=\"rtl\">١٤٠٧</span>)</font><br>بی فکرت مداحی صدر تو همه عمر<br>حاشا که زنم یک مژه را بر مژه ناکاج .<br> <font color=\"Red\">حکیم سوزنی (از آنندراج ).</font><br>> گاه تبدیل به «چ » شود:<br>خروه = خروچ <span class=\"hlight\">:</span> <br>سگالنده ٔ چرخ  مانند قوچ <br>تبر برده بر سر چو تاج خروچ .<br> <font color=\"Red\">رودکی (احوال و اشعار رودکی تألیف نفیسی ص <span class=\"hlight\" dir=\"rtl\">١٠٩٧</span>)</font><br>تو نزد همه کس چو ماکیانی <br>اکنون تن خود را خروه کردی .<br> <font color=\"Red\">رودکی (احوال و اشعار رودکی تألیف نفیسی ص <span class=\"hlight\" dir=\"rtl\">١١٩٥</span>).</font><br>> گاه تبدیل به «خ » شود:<br>هاک = خاک .<br>هجیر = خجیر.<br>هژیر = خجیر.<br>هستو = خستو.<br>هسته ٔ خرما = خسته ٔ خرما.<br>هلالوش = خلالوش <br>هیری = خیری <span class=\"hlight\">:</span> <br>گرد گل سرخ اندر خطی بکشیدی <br>تا خلق جهان را بفکندی به خلالوش .<br> <font color=\"Red\">رودکی (از لغت فرس ص <span class=\"hlight\" dir=\"rtl\">٢١</span>).</font><br>بر فضل او گوا گذراند دل <br>گرچه گوا نخواهند از خستو .<br> <font color=\"Red\">فرخی </font><br>هلالوش خوبان ز دین بی هشند<br>تو بیهوش را در هلالوش کن .<br> <font color=\"Red\">ناصرخسرو.</font><br>اگر به فضل بگویم مرا مشابه نیست <br>به صدق دعوی من آید آسمان خستو.<br> <font color=\"Red\">منصور شیرازی (از آنندراج ).</font><br>به هستیش خستو شوی از نخست <br>اگر خویشتن را شناسی درست .<br> <font color=\"Red\">عبدالقادر نائینی (ازآنندراج ).</font><br>> گاه تبدیل به «ز» شود، چون :<br>باهو = بازو.<br>خروه = خروز.<br>ستیهش =ستیزش <span class=\"hlight\">:</span> <br>به حیله چو روبه فریبنده بود<br>به کینه چو شیر ستیهنده بود.<br> <font color=\"Red\">رودکی (احوال و اشعاررودکی تألیف نفیسی ص <span class=\"hlight\" dir=\"rtl\">١١٦٧</span>)</font><br>آن رفت کتان خویش  من رفتم و پردختم <br>چون گرد بماندستم  تنها من و این باهو.<br> <font color=\"Red\">رودکی (از لغت فرس ).</font><br>شب ازحمله ٔ روز گردد ستوه <br>شود پر زاغش چو پر خروه .<br> <font color=\"Red\">عنصری .</font><br>اندر ستیهش است به من این زن <br>مینازدی به چادر و شلوارش .<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٠٨</span>)</font><br>> گاه تبدیل به «س » شود، چون :<br>آماه = آماس .<br>آماهیدن = آماسیدن .<br>آهن دار = آسوندار.<br>اهمند = اسمند.<br>براماهانیدن =براماسانیدن .<br>پاهنگ = پاسنگ .<br>پلاه = پلاس .<br>خروه (مخفف آن خره ) = خروس  <span class=\"hlight\">:</span> <br>سرد و تاریک شد ای پور سپیده دم دین <br>خره ٔ عرش هم اکنون بکند بانگ نماز.<br> <font color=\"Red\">ناصرخسرو.</font><br>> گاه تبدیل به «غ » شود، چون :<br>آهاردن = آغاردن .<br>اسپرهم = اسپرغم .<br>گیاه = گیاغ .<br>مه = میغ.<br>> گاه تبدیل به «ک » شود، چون :<br>ته = تک (قعر) <br>> گاه تبدیل به «ی » شود، چون :<br>برناه = برنای .<br>تاه = تای .<br>فربه = فربی <span class=\"hlight\">:</span> <br>اعدای شاه گیتی فربه شدند و لاغر<br>از تن شدند لاغر وز غم شدند فربی .<br> <font color=\"Red\">امیرمعزی (از آنندراج ).</font><br>اگر شگفت نماید ز کلک تو نه شگفت <br>که لاغر است و تن فضل شد بدو فربی .<br> <font color=\"Red\">امیرمعزی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٧٢٨</span>).</font><br>خانه ٔ تو سست و لاغر است ولیکن <br>ملک و خزانه به توست محکم و فربی .<br> <font color=\"Red\">امیرمعزی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٧٣٣</span>).</font><br>ب - های مختفی با حروف ذیل بدل شود و گاه بدل از آنها آید:<br>> تبدیل به «الف » شود، چون :<br>بوزینه = بوزینا.<br>خاره = خارا.<br>گونه = گونا.<br>یاوه = یاوا <span class=\"hlight\">:</span> <br>حلوا نخورد چو جو بیابد خر<br>دیبا نبود به کار بوزینا.<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٧</span>)</font><br>او را مجوی و علم طلب زیرا<br>بس کس که او فریضه ٔ یاوا شد.<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٤٠</span>)</font><br>گر تو سنگ خاره و مرمر بوی <br>چون به صاحبدل رسی گوهر شوی .<br> <font color=\"Red\">؟</font><br>> تبدیل به «خ » شود، چون :<br>بنده = بندخ <span class=\"hlight\">:</span> <br>گر نه عشقت بدی ز لعب فلک <br>بندخی یا فرسی داشتمی (؟).<br> <font color=\"Red\">شرف شفروه (از آنندراج ).</font><br>> تبدیل به «د» شود، چون :<br>زاغه = زاغد.<br>شنبه = شنبد <span class=\"hlight\">:</span> <br>به فال نیک به روز مبارک شنبد<br>نبید گیر و مده روزگار خویش به بد.<br> <font color=\"Red\">منوچهری (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span>).</font><br> <br>گاو لاغر به زاغذ اندر کرد<br>توده ٔ زر به کاغذ اندر کرد.<br> <font color=\"Red\">؟ (از لغت فرس ص <span class=\"hlight\" dir=\"rtl\">١٢٠</span>).</font><br>> تبدیل به «ک » شود، چون :<br>جفته = جفتک .<br>چنبره = چنبرک .<br>چوبه = چوبک .<br>> تبدیل به «م » شود، چون :<br>باسره = باسرم <span class=\"hlight\">:</span> <br>پیوسته گشت زار امیدش ز آب کام <br>سیراب باد تا که بود نام باسره .<br> <font color=\"Red\">شمس فخری (از فرهنگ نظام ).</font><br><BR><font color=\"Blue\">◄</font> برخی از کلمات عربی با ضمیر «ه » در فارسی متداول شده اند که روی هم رفته غالباً به جای قید در جمله به کار میروند، مانند: بنفسه، یعنی به تن خویش .فی ذاته . بذاته . برأسه . بعینه .<br> <BR><font color=\"Blue\">◄</font> های زاید در وسط کلمه : خان آرزو در غیاث اللغات چنین آورده است : هائی که در وسط کلمه ٔ زائد آید، چنانچه رستم و رستهم  نام پسر زال بن سام و زردشت و زردهشت . (از فرهنگ نظام ). در فرهنگ آنندراج آمده است : و زائده نیز آید، چون میان و همیان، یعنی کمر، و رستم و روستهم  به اشباع و او نام پسر زال بن سام و زردشت و زردهشت و زرتهشت  لقب حکیمی از بلخ ... و بعضی این لغت را سریانی گفته اند و به هر تقدیر زرهدشت و زرهتشت به تقدیم هاء علی الدال و التاء قلب اوست و کنانه و کهنانه بالفتح کهنه و قدیم .<br>فردوسی <span class=\"hlight\">:</span> <br>ببوسید رستهم تخت ای شگفت <br>جهان آفرین را ستایش گرفت .<br>کمال اسماعیل راست <span class=\"hlight\">:</span> <br>به روزگار تو نو شد ز سر جهان کهن <br>کنانه گر شودآن هم به روزگار تو باد.<br>بهرام پژدوی <span class=\"hlight\">:</span> <br>یکی تازه کن قصه ٔ زرتهشت <br>به نظم دری و به خط درشت .<br>شیوای طوس <span class=\"hlight\">:</span> <br>اگر شاه باشم وگر زردهشت <br>نهالین ز خاک است و بالین ز خشت .<br>میرخسرو <span class=\"hlight\">:</span> <br>تو باش نازک و سرمست عشق چند روی <br>که نازکی است بهمیان و مستی اندر جام .<br>شیخ اوحدی گوید <span class=\"hlight\">:</span> <br>نو نشود ماه عیش و روز نشاطت <br>جز به می سالخورده ٔ کهنانه .<br>و حق این است که مثال صحیح زیادت «ها» همین لفظ است و سائر کلمات احتمال اصالت هم دارند. هر اسم جامد که در آخر او های ملفوظه و ماقبل ها الف باشد اگر آن اسم بدون الف نیز مستعمل است پس های مذکور اصلی است چون کاه و چاه و ماه و مانند آن که بدون الف هم آمده مگر لفظ داه بدال به معنی پرستار و کنیز که با وجود جواز به حذف مستعمل نشده و اگر بدون الف مستعمل نیست پس های مذکور زائده است چون دیباه و دوتاه و برناه و آشناه و شناه که گذشت، و حتی قبا که لفظ عربی است در آخر آن هایی زیاده کرده اند. میرمعزی راست <span class=\"hlight\">:</span> <br>ز بهر جامه ٔ خصمان و نیکخواهانت <br>همی کنند شب و روز صنعت جولاه <br>به دست قدرت بر کارگاه ظلمت نور<br>یکی گلیم همی بافد و یکی دیباه .<br>خواجه جمال الدین سلمان راست <span class=\"hlight\">:</span> <br>ترا همیشه تفاخر به گوهری اصلی است <br>حسود را به کلاه گهرنگار و قباه <br>زهی سپهر جهاندیده با همه پیری <br>ترا متابع و محکوم دولت برناه <br>ز زخم سیلی حکم تو روی کوه کبود<br>ز بار منت جود تو پشت چرخ دوتاه .<br>و در لفظ گواه و گیاه و پادشاه و کلاه و سیاه  می تواند که های زائده باشد و می تواند که اصلی باشد، زیرا که بدون الف و بدون «ها» هر دو آمده .<br>حکیم ازرقی راست <span class=\"hlight\">:</span> <br>زمرد و گیه سبز هر دو همرنگند<br>ولیک این به نگین دان برند و آن به جوال .<br>کمال اسماعیل راست <span class=\"hlight\">:</span> <br>ز صبح تیغ تو گردد به یک نفس رسوا<br>اگرچه سازد خصمت شب سیا پرده .<br>شیخ شیراز راست <span class=\"hlight\">:</span> <br>گوا کرد بر خود خدا و رسول <br>که دیگر نگردم به گرد فضول .<br>خواجه ٔ شیراز راست <span class=\"hlight\">:</span> <br>وام حافظ بگو که بازدهد<br>کرده ای اعتراف و ماگوهیم .<br>گاهی حرف «های » ملفوظ از آخر کلمه به منظور تخفیف یا ضرورت شعری لفظاً و خطاً حذف شود، مانند پادشا <span class=\"hlight\">:</span> <br>پادشا بر کامهای دل که باشد پارسا<br>پارسا شو تا شوی بر هر مرادی پادشا.<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>).</font><br>وز رنج روزگار چو جانم ستوه گشت <br>یک چند با ثنا به در پادشا شدم .<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٧٢</span>).</font><br>سیا <span class=\"hlight\">:</span> <br>ای برادر جز به زیر این ردا اندر نشد<br>این همه بوی و مزه ٔ بسیار با خاک سیا.<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>).</font><br>گوا <span class=\"hlight\">:</span> <br>حجتی بپذیر برهانی ز من زیرا که نیست <br>آن دبیرستان کلی را جز این جزوی گوا.<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>).</font><br>اگر دیو بستد خراسان ز من <br>گوای منی ای علیم قدیر.<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span>).</font><br>گیا <span class=\"hlight\">:</span> <br>گاو راگرچه گیا نیست چو لوزینه ٔ تر<br>بگوارد به همه حال ز لوزینه گیاش .<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٢١</span>).</font><br>چون بقای هر دو علت را نباشد جز غذا<br>نیست باقی در حقیقت نی ستور و نی گیا.<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>).</font><br>«های » غیرملفوظ از آخر «که » و «چه » موصول در رسم الخط قدیم حذف میشد، مانند:<br>آنک و آنچ و هرک و هرچ <span class=\"hlight\">:</span> <br>گر دیانت نیست آنچ آموخت پیغمبر به خلق <br>آنچه خصمان داشتندش جز دیانت چیست پس .<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span>).</font><br>نه هرچ آن تو ندانی آن نه علم است <br>که داند حکمت یزدان سراسر.<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span>).</font><br>و در غیر «که » و «چه » گاه خطاً حذف شود، چنانکه از کلمه ٔ «نه »هنگامی که به «از» متصل شود به تخفیف حذف شود <span class=\"hlight\">:</span> <br>برخاستم از جای و سفر پیش گرفتم <br>نز خانم یاد آمد و نز گلشن و منظر.<br> <font color=\"Red\">ناصرخسرو (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٧٤</span>).</font><br>صاحب غیاث نوشته است : باید دانست در کلمه ای که آخر آن «های » مختفی باشد، وقت اضافت و توصیف آن «ها» را به همزه ٔ ملینه بدل کنند، چون : خوشه ٔ انگور و باده ٔ صاف - انتهی . حقیقت امر این است که همزه در آخر و وسط کلمه های فارسی یافت نمی شود و به کار نمی رود و در این مورد چون آوردن کسره ٔ اضافه به آخر اینگونه کلمه ها متعذر است از این رو که «ها» غیرملفوظ است و نمی توان به آخر آن کسره پیوست و حرف ماقبل «ها» نیز تغییرناپذیر یا (مبنی بر فتح یا کسر است ) بنابراین به قیاس کلمه هایی نظیر کلمه های مختوم به های غیرملفوظ، یعنی کلمه های مختوم به الف و واو ساکن ماقبل مضموم برای ظهور کسره ٔ اضافه «یا» یی پس از «ها» می آورند و در مثال مزبور خوشه ٔانگور، علامت بالای «ها» که در رسم الخط متداول است همزه نیست، بلکه یای کوچک است که در تلفظ نیز نمودار است . چون «هاء» در آخر کلمه باشد در شعر فتحه ٔ حرف ماقبل آن را می توان ساکن خواند <span class=\"hlight\">:</span> <br>این لاله رخان که اصلشان از چگل است <br>یارب که سرشت پاکشان از چه گل است <br>دل را ببرند و قصد جان نیز کنند<br>این است بلا وگرنه زیشان چه گله ست .<br> <font color=\"Red\">شیخ نجم الدین کبری .</font><br>محمد معین نوشته است : در کلماتی که مختوم به «های » غیرملفوظند، در شعر - آنگاه که ضرورت ایجاب کند - یکی از دو قاعده ٔ ذیل را مراعات کنند: الف - مؤلف غیاث این مورد را یکی از موارد فک اضافت یاد کرده، گوید: «مثال فک اضافت از های مختفی » مولوی فرماید <span class=\"hlight\">:</span> <br>گر خدا خواهد که پرده ی ْ کس درد<br>میلش اندر طعنه ٔ نیکان برد.<br>فروزانفر نوشته است : هرگاه آخر مضاف های مختفی باشد، حذف کسره ٔ اضافه رواست، و حذف حرکت اضافه از آخر هدیه دراین بیت مولوی بنابر همین قاعده صورت گرفته است <span class=\"hlight\">:</span> <br>گفت ای هدیه حق و دفع حرج <br>معنی الصبر مفتاح الفرج .<br>ب - به جای «ی » مکسور، «ی » ساکن تلفظ کنند. غالب فاضلان معاصر از جمله علامه دهخدا این وجه را ترجیح دهند <span class=\"hlight\">:</span> <br>پذیره ی ْ فرامرز شد <font color=\"DarkGreen\"><b>[ پادشاه کابل ]</font></b> با سپاه <br>بشد روشنائی زخورشید و ماه .<br> <font color=\"Red\">فردوسی (شاهنامه چ بروخیم ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٤٣</span>).</font><br>زندواف زندخوان چون عاشق هجرآزمای <br>دوش بر گلبن همی تا روز ناله ی ْ زارکرد.<br> <font color=\"Red\">فرخی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٤٢٩</span>).</font><br>جمله بدین داوری بر در عنقا شدند<br>کوست خلیفه ی ْ طیور، داور مالک رقاب .<br> <font color=\"Red\">خاقانی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).</font><br>دمدمه ی ْ این نای از دمهای اوست <br>های و هوی روح از هیهای اوست .<br> <font color=\"Red\">مولوی (مثنوی چ <span class=\"hlight\" dir=\"rtl\">١٣٠٧</span> دفتر <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٥</span>).</font><br> <br>گر تو علامه ی ْ زمانی درجهان <br>نک فنای این جهان در این زمان .<br> <font color=\"Red\">مولوی (ایضاً دفتر <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٥</span>).</font><br>پیش چشمت داشتی شیشه ی ْ کبود<br>زآن سبب عالم کبودت مینمود.<br> <font color=\"Red\">مولوی (ایضاً دفتر <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٨٢</span>).</font><br>بهمنیار نوشته است : در شعر گاهی کسره ی «یاء» بعد از «هاء» ملین به طور صریح تلفظ نمی شود، لیکن یاء را باید رسم کرد، مانند: عقده ی سخت است بر کیسه ی تهی . (اضافه تألیف معین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>). در فرهنگ نظام آمده است : در زبان فارسی آخر اسماء عموماً ساکن است، مثل دل و جان و بدن و باران و میان و همانها گاهی در تکلم با کسر آخر تلفظ میشوند و با هاء نوشته می شوند که نشان آن کسره است، مثل دله جانه و بدنه و بارانه و میانه . و نیز بیان متحرک بودن آخر لفظ تا اشتباه به لفظ دیگر نشود، مثل جامه و خامه و بنده و گفته تا اشتباه به جام و خام و بند و گفت نشود. محمدبن خلف تبریزی در دیباچه ٔ برهان آورده : هاء ملفوظ خواه ماقبل آن مفتوح و خواه مضموم و خواه ساکن باشد که در جمع به حال خود میماند، همچو «رهها» و «اندهها» و «گرهها» و در تصغیر مفتوح گردد، همچو «رهک » و «گرهک » و «اندهک » و در اضافت مکسور شود، همچو «ره من » و «انده من » و «زره من » . برخی از لغویان و دستورنویسان گویند: های مختفی یا غیرملفوظ در جمع به «ها» از آخر کلمه حذف شود، چون نامها و جامها. ولی گروهی بر آنند که حذف «ها» هنگامی رواست که به جمع کلمه ٔ دیگری مشتبه نشود، مثلاً «نامها» و «جامها» هم ممکن است جمع«نامه » و «جامه » و هم جمع «نام » و «جام » باشد از این رو به عقیده ٔ این دسته حذف «ها» در کلماتی، مانند:تشنه و گرسنه که به جمع کلمه ٔ دیگری اشتباه نمیشوندرواست و در غیر این کلمات جایز نیست، اما متأخران بطور کلی های مختفی را در جمع به «ها» حذف نمی کنند وکلیه ٔ کلمات را در جمع بدینسان با «ها» آرند: تشنه ها، نامه ها و غیره .<br>های عطف - در غیاث اللغات آمده است : های عاطفه که موصله نیز نامند، چنانچه خورده رفت، و کشیده برد، و از طعام فراغت یافته سوار خواهم شد و بعضی این ها را های تعقیبیه نیز نامند. در فرهنگ آنندراج آمده است : «و افاده ٔ معنی عطف هم کند، چنانکه گوئی زید طعام پخته خورد و خوردن متفرع است بر پختن و طعام پخته رخصت گرفت که در اینجا همین قدر مدعا میشود که بعد آن کاراین کارکرد و در این صورت اسناد هر دو فعل به یک فاعل میباشد، چنانکه در مثال اول فاعل پختن هم زید است و فاعل خوردن هم اوست . در مثال ثانی فاعل پختن و رخصت گرفتن نیز یکی است . در فرهنگ نظام چنین آمده است :هائی که حرف عطف است، مانند زید غذای خود را پخته خورد و کار خود را کرده رفت که به معنی پخت و خورد و کرد و رفت است .<br>در اتصال به یای حاصل مصدر- در اتصال به «ی » حاصل مصدر «ها» به اصل خود بازگردد، یعنی به جای آن کاف فارسی آید. بیگانه، بیگانگی . پسرخوانده، پسرخواندگی . دوساله، دوسالگی <span class=\"hlight\">:</span> <br>پس از نه سالگی مکتب رها کرد<br>حساب جنگ شیر و اژدها کرد<br>چو بر ده سالگی افکند بنیاد<br>سر سی سالگان میداد بر باد.<br> <font color=\"Red\">نظامی .</font><br>دیرآمده، دیرآمدگی . نجیب زاده، نجیب زادگی . دیوانه، دیوانگی <span class=\"hlight\">:</span> <br>مرو پیش او جز به بیگانگی <br>مگردان زبان جز به دیوانگی .<br> <font color=\"Red\">فردوسی (شاهنامه چ بروخیم ص <span class=\"hlight\" dir=\"rtl\">٦٧٦</span>).</font><br>در اتصال به کاف تصغیر- در اتصال به کاف تصغیر به آخر کلمه ٔمختوم به «ها» ها تبدیل به «گ » شود: جوجه، جوجگک <span class=\"hlight\">:</span> <br>آبی چو یکی جوجگک  از خایه بجسته <br>چون جوجگکان از تن او موی برسته .<br> <font color=\"Red\">منوچهری (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٢٠</span>).</font><br>دایه، دایگک . شانه، شانگک <span class=\"hlight\">:</span> <br>شانگکی ز آبنوس، هدهد بر سر زده ست <br>بر دو بناگوش کبک غالیه ٔ تر زده ست .<br> <font color=\"Red\">منوچهری (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٤٧</span>).</font><br>سفره، سفرگک <span class=\"hlight\">:</span> <br>نارماند به یکی سفرگک دیبا<br>آستردیبه زرد اِبره ٔ آن حمرا.<br> <font color=\"Red\">منوچهری (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٦١</span>).</font><br>ماسوره، ماسورگک <span class=\"hlight\">:</span> <br>سر او بسته به پنهان ز درون عمدا<br>سر ماسورگکی در سر اوپیدا.<br> <font color=\"Red\">منوچهری (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٦١</span>).</font><br>و در نسبت : باره، بارگی <span class=\"hlight\">:</span> <br>ز خرگاه و از خیمه ٔ بارگی <br>بسازید پیران به یکبارگی .<br> <font color=\"Red\">فردوسی (شاهنامه چ بروخیم ص <span class=\"hlight\" dir=\"rtl\">٧٠٣</span>).</font><br>خانه، خانگی <span class=\"hlight\">:</span> <br>بمالید پس خانگی رخ به خاک <br>همی گفت کای داور داد پاک .<br> <font color=\"Red\">فردوسی (شاهنامه چ بروخیم ص <span class=\"hlight\" dir=\"rtl\">٢٨٦١</span>).</font><br>بسی آفرین گفت بر خانگی <br>بدو گفت بس کن ز بیگانگی .<br> <font color=\"Red\">فردوسی (شاهنامه چ بروخیم ص <span class=\"hlight\" dir=\"rtl\">٢٨٦٤</span>).</font><br>یکی خلعت افکند بر خانگی <br>فزون تر ز خویشی و بیگانگی .<br> <font color=\"Red\">فردوسی (شاهنامه چ بروخیم ص <span class=\"hlight\" dir=\"rtl\">٢٨٦٨</span>).</font><br>در جمع - محمد معین نوشته است : در کلمات (اسماء و صفاتی که به جای اسماء نشینند)، مختوم به هاء غیرملفوظ به هنگام جمع به «َان » های آنها به گاف (کاف فارسی ) تبدیل شود : زنده، زندگان . بنده، بندگان .تشنه، تشنگان <span class=\"hlight\">:</span> و ما بندگان را اندر جهان پدیدار کرد <font color=\"DarkGreen\"><b>[ خدای ]</font></b> . (مقدمه ٔ شاهنامه ٔ ابومنصوری هزاره ٔ فردوسی ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>). و درود بر برگزیدگان و پاکان ودینداران باد. (مقدمه ٔ شاهنامه ٔ ابومنصوری ایضاً ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>). و مأمون ... یک روز با فرزانگان نشسته بود. (مقدمه ٔ شاهنامه ٔ ابومنصوری ص <span class=\"hlight\" dir=\"rtl\">١٣٥</span>). و اندر نامه ٔ پسر مقفع و حمزه ٔ اصفهانی و مانندگان ایدون شنیدیم ... (مقدمه ٔ شاهنامه ٔ ابومنصوری ص <span class=\"hlight\" dir=\"rtl\">١٤٠</span>).<br>پیش شاه جهان شما گویید<br>سخن بندگان شاه جهان .<br> <font color=\"Red\">فرخی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٦٩</span>).</font><br>اورا قریب چهل پسر بوده و فرزندزادگان بیشمار از ایشان منشعب گشته اند... اما آنچ از پسران و پسرزادگان اومعروف و مشهورند... (جامع التواریخ رشیدالدین فضل اﷲج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٠</span>).<br>به مژگان سیه کردی هزاران رخنه در دینم <br>بیا کز چشم بیمارت هزاران درد برچینم .<br> <font color=\"Red\">حافظ (دیوان چ قزوینی ص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span>).</font><br>چه غم از تابش خورشید قیامت دارد<br>هرکه در سایه ٔ مژگان تو در خواب رود؟<br> <font color=\"Red\">صائب (از جنگی خطی ).</font><br>خنک گرسنگان و تشنگان ازبرای طاعت و تقوی، زیرا سیری و خجستگی یابند. (انجیل معظم ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>). و شبانگاه آوردند پیش وی <font color=\"DarkGreen\"><b>[ عیسی ]</font></b> دیوانگان بسیار، و دیوها از ایشان بدر کرد بسخن خود و شفا داد... (انجیل معظم چ مسینا چ رم <span class=\"hlight\" dir=\"rtl\">٢</span> <span class=\"hlight\" dir=\"rtl\">١٩٥١</span> ص <span class=\"hlight\" dir=\"rtl\">٨٨</span>). فرشتگان آسمان تبسم کنان در کنار کودک خواب و بیدار زمین خم گردیده با نفس مشک بیز خود عارض نازنین او را... نوازش میدادند. (هفت قصه جمالزاده ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>). و در میان همسایگان دیگر خود آنها را از همه پست تر و خوارتر میشمرده اند. (خاندان نوبختی عباس اقبال ص ط). یک عده ازنوادگان ابوسهل بن نوبخت بواسطه ٔ قبول مذهب جعفری ازمدافعین جدی این آئین شده ... (خاندان نوبختی عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">١</span>). و زمزمه ٔ جویبار و خنده ٔ چمن و درخشیدن ماه و خورشید و ستارگان و سرود مرغان و گویندگان ایران جفت کرده، آنچه را از خوبی میهن به گفتن درنمی گنجد بیابند. (اندیشه محمد حجازی ص <span class=\"hlight\" dir=\"rtl\">٢</span>).<br>تبصره ٔ <span class=\"hlight\" dir=\"rtl\">١</span>- باید دانست که در زبان تخاطب، در جمع این گونه کلمات به جای «َان »، «َها» به کار برند: زنده، زنده ها. مرده، مرده ها. ستاره، ستاره ها. و از قدیم نیز گاه نویسندگان ما، این شیوه را به کار برده اند <span class=\"hlight\">:</span> و ایمان نیاورده ام به فرشته های خدا و کتابهای او... (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٣٥</span>).<br>تبصره ٔ <span class=\"hlight\" dir=\"rtl\">٢</span>- جمع پله (پهلوی ) پلکان و پله ها آید. (قاعده های جمع در زبان فارسی تألیف معین صص <span class=\"hlight\" dir=\"rtl\">٢٦</span>-<span class=\"hlight\" dir=\"rtl\">٢٨</span>). های اصلی و وصلی - شمس قیس آورده است : شخصی از جمله ٔ استادان شعرای عجم در تقسیم هاآت اصلی و وصلی گفته است که هاء اصلی، آن است که کلمه بی آن معنی خویش ندهد، و وصلی، آن است که کلمه را در اصل معنی احتیاج نباشد (و) این تقسیم راست مانند است اما در تفسیر آن نظری هست، زیرا که گفته است هاء شانه  و بهانه اصلی است که اگر <font color=\"DarkGreen\"><b>[ هاء ]</font></b> ساقط گردانند شان و بهان ماند و هیچ معنی ندهد و همچنین هاء جامه و نامه اصلی است که اگرهاء بیندازند <font color=\"DarkGreen\"><b>[ جام و نام ماند ]</font></b> و آن معنی که از جامه و نامه مطلوب است ندهد و هاء کرانه و میانه و نشانه اصلی نیست از <font color=\"DarkGreen\"><b>[ بهر آنک ]</font></b> اگر هاء بیندازند کران و میان و نشان ماند و همان معنی اول بدهد و این غلط است از بهر آنکه بناء این کلمات بر فتح  است و این هاآت در کل احوال از لفظ ساقطند و جز دلالت حرکت ماقبل در معنی کلمه هیچ مدخل ندارند. پس اختلال معانی این کلمات از تسکین حرف متحرک میخیزد نه از اسقاط هاء غیرملفوظ از کتابت به دلیل آنکه اگر مبتدئی که بر دقایق علم خط وقوف ندارد و ندانسته باشد که در خط فارسی هر کجا کلمه ٔ مفتوح الاَّخر افتد هائی بدان الحاق باید کرد چون مثل این کلمات در قلم خواهد آورد البته بی هاء نویسد «و درست » خواند، زیرا که سبحان َ و ان ّ و کأن ّ در قرآن دیده باشد و خوانده و در آن هیچ حرف زاید ندیده و آنچ گفته است که کران و میان و نشان همان معنی می دهد <font color=\"DarkGreen\"><b>[ که کرانه و میانه و نشانه ]</font></b> (هم ) غلط است از بهر آنکه نشانه دیگر است و نشان دیگر همچنانکه دندانه دیگر است ودندان دیگر و زبانه دیگر است و زبان دیگر پس گوییم هاء اصلی آن است که در کل احوال ملفوظ باشد علی الخصوص در اضافت و جمع و تصغیر و نسبت چنانکه زره من و زرهها و زرهک <font color=\"DarkGreen\"><b>[ و زرهی ]</font></b> و هاء وصلی آن است که جز ضرورت قافیت را در لفظ نیاید و در تقطیع به حرفی محسوب نباشد و در اضافت به همزه ای ملینه بدل شود و در جمع از کتابت نیز ساقط شود و در تصغیر و نسبت به کاف اعجمی بدل شود، اما در شعر و تقطیع چنانکه <span class=\"hlight\">:</span> <br>خسته دارم دیده در هجرت همیشه .<br><font color=\"DarkGreen\"><b>[ که ]</font></b> هاء خسته و دیده از تقطیع ساقطند و هاء همیشه برای ضرورت وقف ملفوظ است و به حرفی محسوب و اما در اضافت چنانکه دایه ٔ من و بنده ٔ تو و در جمع چنانکه شانها و بهانها و در تصغیر چنانکه بندگک و دایگک و در نسبت چنانکه بندگی و دایگی، و چون شرح ماآت اصلی و وصلی بر نهج صواب معلوم شد، بدانکه هاآت وصلی دو نوع است : نوع اول آن است که در اواخر کلمات جز دلالت حرکت ماقبل هیچ فایده ندهد و آن را هاء سکت خوانند، یعنی هائی است که متکلم در وقف بر آن خاموش شود و این هاء در لغت عرب روشن در لفظ آید، چنانکه ما أغنی عنی مالیه هلک عنی سلطانیه (قرآن <span class=\"hlight\" dir=\"rtl\">٢٨/٦٩</span> و <span class=\"hlight\" dir=\"rtl\">٢٩</span>) و در پارسی هاآت زایده به هیچ وجه در لفظ نیارند مگر که قافیت باشد <font color=\"DarkGreen\"><b>[ و ]</font></b> به ضرورت شعر آن را به حرفی ساکن شمارند و پوشیده در لفظ آرند، چنانکه <span class=\"hlight\">:</span> <br>ای شمع رخت را دل من پروانه <br>وز عشق توام به خویشتن پروا، نه .<br>و مثال هاآت سکت در پارسی هاء شانه و بهانه و جامه و نامه و خامه وسرکه و سینه و سفره و خنده و گریه و امثال آن است واگرچه بر این تفسیر جمله هاآت وصلی هاء سکت باشد، اما چون در این کلمات جز دلالت حرکت ماقبل هیچ فایده ٔ دیگر را متضمّن نیست آن را بدین نام خواندیم تا موافق لغت تازی باشد. نوع دوم آن است که جز حرکت ماقبل معنی خاص را مستلزم باشد زاید بر اصل آن کلمه و آن چهارگونه است : در علم قافیه <span class=\"hlight\" dir=\"rtl\">١</span>- هاء تخصیص . <span class=\"hlight\" dir=\"rtl\">٢</span>- هاء صفت .<span class=\"hlight\" dir=\"rtl\">٣</span>- هاء فاعل . <span class=\"hlight\" dir=\"rtl\">٤</span>- هاء لیاقت و نسبت، و هیچیک از این هاآت نشاید که روی سازند و سنائی هاآت زایده را روی ساخته است، چنانکه می گوید <span class=\"hlight\">:</span> <br>نیک نادان در اصل نیکو نه <br>بد دانا ز نیک نادان به .<br>های «به » اصلی است و های «نه » زایدو هم او گفته <font color=\"DarkGreen\"><b>[ است ]</font></b> <span class=\"hlight\">:</span> <br>هرکه بشنید بخ بخ او را به <br>وآنکه نشنید خیره  ما را چه .<br>و هم او گفته است <font color=\"DarkGreen\"><b>[ و هر دو قافیت هائی زایده کرده ]</font></b> <span class=\"hlight\">:</span> <br>بر زبان صوت و حرف و ذوقی نه <br>غافل از معنیش که از به چه .<br>و هم او گفته است <span class=\"hlight\">:</span> <br>هر کجا ذکر او بود تو که ای <br>جمله تسلیم <font color=\"DarkGreen\"><b>[ کن ]</font></b> بدو تو چه ای .<br>در این بیت <font color=\"DarkGreen\"><b>[ خود ]</font></b> آنچ ملفوظ است از قافیت کاف و جیم است و لفظ <font color=\"DarkGreen\"><b>[ ای ]</font></b> خود ردیف است و به تقلید او مهستی دبیر گفته است <span class=\"hlight\">:</span><br>با روی چو نوبهار و با خوی دیی <br>با ما چو خمار و با دگر کس چو میی <br>بخت بد ما همی کند سست پیی <br>ورنه تو چنین سخت کمان نیز نه ای .<br>قافیت یائی است و روی در دی و می <font color=\"DarkGreen\"><b>[ و پی ]</font></b> درست <font color=\"DarkGreen\"><b>[ است ]</font></b> اما <font color=\"DarkGreen\"><b>[ قافیت ]</font></b> نی ای درست نیست و در قوافی هائی و آنگاه <font color=\"DarkGreen\"><b>[ و خرگاه ]</font></b>و درگاه بهم شاید <font color=\"DarkGreen\"><b>[ و آگاه و ناگاه بهم شاید و یازده و دوازده و ده بهم شاید ]</font></b> و سحرگاه و شبانگاه <font color=\"DarkGreen\"><b>[ بهم نشاید ]</font></b> و خرمن گاه و منزل گاه بهم نشاید و شاه و شاهانشاه بهم نشاید الا که یکی اسم باشد، و جمهور شعراءبگاه و بیگاه بهم جایز ندارند و اگر کسی روا دارد «جواز آن را» وجهی توان نهاد چه بیگاه و بگاه به معنی دیر و زود مستعمل است نه به معنی وقت و ناوقت به دلیل آنکه اگر کسی حاجتی به بزرگی رفع کند و در محل اجابت افتد او را نگویند که این <font color=\"DarkGreen\"><b>[ سخن ]</font></b> بگاه گفتی، بلکه گویند به وقت گفتی یا به هنگام گفتی و اگر گویند بگاه گفتی چنان فهم کند که زود گفتی و دیرتر از این می بایست گفت و اگر در آن تعویقی افکند و به اسعاف مقرون ندارد نگویند که این سخن بیگاه گفتی <font color=\"DarkGreen\"><b>[ بل که ]</font></b> گویند بی وقت گفتی یا بی هنگام گفتی و اگر گویند بیگاه گفتی چنان فهم کند که دیر گفتی و زودتر از این می بایست گفت . پس معلوم شد که بگاه و بیگاه به معنی زود و دیراست نه به معنی باوقت و بی وقت و چون اختلاف معنی آمد باید که اگر کسی هر دو بهم قافیت سازد خطا نباشد. و بعضی شعراء در آخر برنا ویکتا و دیبا و قبا حرف هاء درمی آرند و در قوافی هائی استعمال می کنند، چنانکه انوری گفته است <span class=\"hlight\">:</span> <br>شعله ٔ صبح از آفتاب دورنگ <br>درزد آتش به آسمان دو تاه .<br>و دیگری گفته است <span class=\"hlight\">:</span> <br>ماه است بتم اگر نهد ماه کلاه <br>سرو است اگر زیبد بر سرو قباه .<br>و دیگری گفته است <span class=\"hlight\">:</span> <br>پیشم آمد بگاه در راهی <br>نغزمردی شگرف برناهی .<br> <font color=\"Red\">(از المعجم فی معاییر اشعار العجم صص <span class=\"hlight\" dir=\"rtl\">١٨٣</span>-<span class=\"hlight\" dir=\"rtl\">١٨٧</span>).</font><br> <BR><font color=\"Blue\">◄</font> های نسبت - شمس قیس آرد: هاء نسبت و لیاقت آن هائی است که در اواخر جموع اسمی معنی لیاقت و نسبت دهد، چنانکه : «شاهانه » و «زیرکانه » و «مردانه » و «زنانه ». (المعجم ص <span class=\"hlight\" dir=\"rtl\">١٨٥</span>). هدایت در فرهنگ انجمن آرا چنین آورده است : هاء مفید معنی نسبت است، چون : یکساله و یکروزه و دینه و فرزانه، یعنی منسوب به فرزان به معنی حکمت و از این مقوله است شبانه ومغانه و دیوانه و عروسانه که هاء این کلمات برای نسبت است . نجم الغنی در نهج الادب چنین آورده : های نسبت که در پهلوی الفاظ درآید و افاده ٔ معنی نسبت کند، چون : جامه به معنی صراحی که هاء برای نسبت است به جام . حکیم منجیک ترمذی گفته <span class=\"hlight\">:</span> <br>چو می ز جامه به جام اندرون فروریزی <br>هوای ساغر صهبا کند دل ابدال .<br>بدرالدین جاجرمی راست <span class=\"hlight\">:</span> <br>از جامه ٔ شرابت یک نم هزار دریا<br>وز خامه ٔ خطابت یک خط هزار کشور.<br>و دیگری گفته است <span class=\"hlight\">:</span> <br>خلق بر یاد خلق او خورده <br>هرچه در جام کرده از جامه .<br>و باده که های نسبت افزوده بنابر لطافت او را منسوب به باد کرده اند، زیرا که خوردنش اکثر باد و غرور</font></div>'),
(264597, 'ها', '<span class=\"hlight\">ها.</span> (اِ) نام حرف هَ : آتش افتاد روی چادر دو تا گل مثل چشم «ها» سوخت . الهی چشمهاشان را مرده شور درآرد... (چرند و پرند تألیف دهخدا از روزنامه ٔ ایران کنونی ). <BR><font color=\"Blue\">◄</font> هاء دوچشم، در تداول عامه هاء هوز است .<br></font></div>'),
(264598, 'ها', '<span class=\"hlight\">ها.</span> (ع اِ) حرفی است از حروف مهموسه و گاهی زائد آید و مبدل شود. (منتهی الارب ). نام حرف «هَ». ج، هاآت . (ناظم الاطباء).<br></font></div>'),
(264599, 'ها', '<span class=\"hlight\">ها.</span> (اِ) سفیدی روی مرغ . (برهان ).<br></font></div>'),
(264600, 'ها', '<span class=\"hlight\">ها.</span> (اِ) تپانچه بروی کسی زدن . (برهان ) (ناظم الاطباء).<br></font></div>'),
(264601, 'ها', '<span class=\"hlight\">ها.</span> (اِ) هر یک از هفتادودو فصل یسنا را در فارسی «ها» گوئیم . در اوستا هائیتی  به معنی باب و فصل مطابق کلمه ٔ ساتی  سانسکریت میباشد. درپهلوی هات  گفته اند. اصلاًاین کلمه به معنی پیوند و بستگی است، مشتق از فعل ها که به معنی بهم پیوستن و بستن است، در سانسکریت سیاتی . در هر جا که کلمه ٔ «ها» آمده از آن فصل یسنا اراده کرده اند، چنانکه کلمه ٔ «کرده » از برای تعیین فصل «وسپرد» و «فرگرد» از برای تعیین فصل «وندیداد» اختصاص یافته است . کلمه ٔ «ها» بخصوص به هر یک از هفده فصل گاتها که جزو یسناست اطلاق میشود. در انجام هر یک از هفده فصل منظوم گاتها به نثر افزوده شده : اهیاس ها میستائیم . خشماویه گئوش اُوروهار میستائیم ... (یسنا پورداود ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٢٥</span>-<span class=\"hlight\" dir=\"rtl\">٢٦</span>).<br></font></div>'),
(264602, 'ها', '<span class=\"hlight\">ها.</span> (ع صوت ) به معنی اینک می آید چنانکه هرگاه به مردی گویند: این انت، جواب میگوید: ها انا ذا؛ یعنی اینک منم .و اگر به زنی گویند: این انت، گوید ها انا ذه، و اگر به کسی گویند: این فلان، هرگاه نزدیک باشد، میگوید:ها هو ذا. هرگاه دور باشد میگوید: ها هو ذاک . و در زن هرگاه نزدیک بود، میگوید: ها هی ذه، و اگر دور بود، میگوید: ها هی تلک . و ضمیر «ها» استعمال میگردد در موضع جر و نصب هر دو. قوله : فألهمها فجورها و تقویها. (قرآن <span class=\"hlight\" dir=\"rtl\">٨/٩١</span>). و در قسم و سوگند گویند: لاهااﷲ مافعلت ؛ یعنی سوگند به خدا نکردم من . (ناظم الاطباء).<br></font></div>'),
(264603, 'ها', '<span class=\"hlight\">ها.</span> (صوت ) اشاره به قریب و نزدیک . (برهان ). کلمه ٔ اشاره به معنی اینک که بدان به چیز نزدیک اشاره میکنند. (ناظم الاطباء). به معنی اینک باشد که مصغر این است . (برهان ) <span class=\"hlight\">:</span> <br>چو من ناورد پانصد سال هجرت <br>دروغی نیست ها برهان من ها.<br> <font color=\"Red\">خاقانی .</font><br>کعبه چه کنی با حجرالاسود و زمزم <br>ها عارض و زلف و لب  ترکان سرائی .<br> <font color=\"Red\">خاقانی (دیوان چ عبدالرسولی ص <span class=\"hlight\" dir=\"rtl\">٤٤٣</span>).</font><br>نزد سلیمان شهم ستود چو آصف <br>گفت که ها هدهد سبای صفاهان .<br> <font color=\"Red\">خاقانی (دیوان چ عبدالرسولی ص <span class=\"hlight\" dir=\"rtl\">٣٦٠</span>).</font><br>پس از صد سال اگر گوئی کجا او<br>ز هر بیتی ندا خیزد که هااو.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(264604, 'ها', '<span class=\"hlight\">ها.</span> (صوت ) در مواردی «ها» به معنی بنگر، ببین، بهوش باش و مانند اینها به کار میرود که در این صورت از اصوات تنبیه و تحذیر به شمار میرود و ممکن است مخفف هان باشد، چنانکه صاحب نهج الادب در ذیل حروف تنبیه پس از ذکر هان آرد: «ها چون هادرویش  و می تواند که ها بخصوصه مخفف هان بود که هم برای این معنی آید، چنانکه هادوری  به معنی گدای مبرم یعنی شخصی که دوری از او بهتر است، در محل تخصیص و آگاه کردن مستعمل شده اولاً بعد از آن به معنی گدای مبرم آمده  مجازاً. اثیر اخسیکتی گفته <span class=\"hlight\">:</span> <br>معیشتی نه که با عزت و قناعت آن <br>به هر دری نروم چون گدای هادوری .<br>و همچنین ها درویش نام دشت شده که در ترکستان است و اگر گویند قلب است پس در اصل دوری ها و درویش ها بوده می تواند شد، لیکن نظائر آن در مستعلات دیده نشد هرچند قلب در فارسی به انواع حدی و شماری ندارد. (نهج الادب ص <span class=\"hlight\" dir=\"rtl\">٥٧٠</span>).<br>ها ثریا نه خوشه ٔ عنب است <br>دست برکن ز خوشه می بفشار.<br> <font color=\"Red\">خاقانی .</font><br>از مهرخ من شدی خبر پرس <br>ها مهرخ مهربانم این است .<br> <font color=\"Red\">نظامی .</font><br>گفتی که کجاست دلستانت <br>ها دلبر دلستانم این است .<br> <font color=\"Red\">نظامی .</font><br>نروی ها. نکنی ها.<br></font></div>'),
(264605, 'ها', '<span class=\"hlight\">ها.</span> (ق ) (در تداول ) آری ؛ در مقابل نه : یا ها یا نه . نه ها، نه، نه . نه ها گفت نه نه ؛ یعنی هیچ نگفت <span class=\"hlight\">:</span> <br>پریرویان مه سیما سلامی ها علیکی نه .<br></font></div>'),
(264606, 'ها', '<span class=\"hlight\">ها.</span> (پیشوند) گاهی به معنی «وا» و «به » می آید: هاگرفتن = واگرفتن <span class=\"hlight\">:</span> گفت این خواری به خود ها نگیرم . (اسکندرنامه ). قاتل عظیم بترسید و پشت ها داد. (اسکندرنامه ). گفت برو بپرس که طفغاچ کدام است و دست او هاگیر. (اسکندرنامه ).<br>وگر گوید بگیرم زلف و خالش <br>به کوتا هانگیری هاممالش .<br><BR><font color=\"Blue\">◄</font> گاه در بعضی لهجه ها در اول پاره ای افعال درآید و ظاهراً تغییری در معنی نمی دهد: هادادن : خدا وقتی هامیده وَر وَرِ جماران هم هامیده .<br></font></div>'),
(264607, 'ها', '<span class=\"hlight\">ها.</span>(پسوند) محمد معین نوشته است : دومین نشانه ٔ جمع در پهلوی «ایها» است مثال :<br>مفرد<br> <font color=\"Red\">جمع</font><br>در<br> <font color=\"Red\">دریها(دره ها)</font><br>کوست (جانب، طرف، ناحیه )<br>کوستیها (جوانب، اطراف، نواحی ) <a id=\"fn١٧١٤٣٧\" href=\"#\" onmouseover=\"javascript:ShowTip(\'\' <span class=\"><span class=\"hlight\" dir=\"rtl\">k٠٠l</span>)_&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">rb</span>&<span class=\"hlight\" dir=\"rtl\">tg</span>; &<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">naps</span> <span class=\"hlight\" dir=\"rtl\">ssalc</span>=\\\'\'<span class=\"hlight\" dir=\"rtl\">tnedni</span>\\\'\'&<span class=\"hlight\" dir=\"rtl\">tg</span>;&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">naps</span> <span class=\"hlight\" dir=\"rtl\">ssalc</span>=\\\'\'<span class=\"hlight\" dir=\"rtl\">thgilhgih</span>\\\'\' <span class=\"hlight\" dir=\"rtl\">rid</span>=\\\'\'<span class=\"hlight\" dir=\"rtl\">rtl</span>\\\'\'&<span class=\"hlight\" dir=\"rtl\">tg</span>;<span class=\"hlight\" dir=\"rtl\">radahirad</span>&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">naps/</span>&<span class=\"hlight\" dir=\"rtl\">tg</span>;&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">naps/</span>&<span class=\"hlight\" dir=\"rtl\">tg</span>;&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">rb</span>&<span class=\"hlight\" dir=\"rtl\">tg</span>;&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">naps</span> <span class=\"hlight\" dir=\"rtl\">ssalc</span>=\\\'\'<span class=\"hlight\" dir=\"rtl\">tnedni</span>\\\'\'&<span class=\"hlight\" dir=\"rtl\">tg</span>;&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">naps</span> <span class=\"hlight\" dir=\"rtl\">ssalc</span>=\\\'\'<span class=\"hlight\" dir=\"rtl\">thgilhgih</span>\\\'\' <span class=\"hlight\" dir=\"rtl\">rid</span>=\\\'\'<span class=\"hlight\" dir=\"rtl\">rtl</span>\\\'\'&<span class=\"hlight\" dir=\"rtl\">tg</span>;<span class=\"hlight\" dir=\"rtl\">tsukahitsuk</span>&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">naps/</span>&<span class=\"hlight\" dir=\"rtl\">tg</span>;&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">naps/</span>&<span class=\"hlight\" dir=\"rtl\">tg</span>;&<span class=\"hlight\" dir=\"rtl\">tl</span>;<span class=\"hlight\" dir=\"rtl\">rb</span>&<span class=\"hlight\" dir=\"rtl\">tg</span>;\'\');\"> <<span class=\"hlight\" dir=\"rtl\">a/</font></div>'),
(264608, 'ها', '<span class=\"hlight\">ها.</span> (ع حرف ) حرف تنبیه است و بر چهار لفظ درآید:<br><span class=\"hlight\" dir=\"rtl\">١</span>- اسم اشاره، مانند: «ذا» و «ذی » و جز آن . مخصوص اشاره ٔ به دور نباشد، مانند: «هذا»، «هذه »، «هذاک » و «هذیک ».<br><span class=\"hlight\" dir=\"rtl\">٢</span>- بر ضمیر رفعی که بوسیله ٔ اسم اشاره از آن خبر داده شده است، کقوله تعالی : ها أنتم هؤلاء. (قرآن <span class=\"hlight\" dir=\"rtl\">٦٦/٣</span> و <span class=\"hlight\" dir=\"rtl\">١٠٩/٤</span> و <span class=\"hlight\" dir=\"rtl\">٣٨/٤٧</span>). (ضمیر انتم بین دو «هاء» تنبیه برای تأکید است ) و مانند آن «الا هولاء».<br><span class=\"hlight\" dir=\"rtl\">٣</span>- نعت «ای ّ» در ندا و از آن جدا نمیشود، مانند: ایها الرجل . و «ها» در «هذا» برای تنبیه واجب است برای اینکه مقصود از آن نداست و در «هذا» در لغت بنی اسد جائز است که الف آن حذف شود و ضمه داده شود، «هاء» آن از جهت اتباع و قرائت ابن عامر در «آیةالثقلان » بر این سیاق است .<br><span class=\"hlight\" dir=\"rtl\">٤</span>- بر نام خدادر قسم با حذف حرف قسم گفته میشود: ها اﷲ مافعلت . با قطع همزه و وصل آن، و در هر دو صورت اثبات الف و حذف آن . و آن مبدل از واو قسم است . (منتهی الارب ). حرف تنبیه است در اینجا نیز اغلب بعد از «ها» همزه ای بیفزایند و «هاءالتنبیه » گویند. ولی صواب آن است که همزه ای افزوده نشود، زیرا های تنبیه حرف هجای «هَ» نیست بلکه حرف معنائی است مرکب از هاء و الف (ها)، چنانکه «لم » مثلاً حرفی است مرکب از لام (ل ) و میم (م ). بنابراین افزودن همزه موردی ندارد، باید الف «ها» را بالتقاء ساکنین حذف کرد و «ها التنبیه » گفت . (خیام پورنشریه ٔ دانشکده ٔ ادبیات تبریز).<br></font></div>'),
(264609, 'ها', '<span class=\"hlight\">ها.</span> (ع اِ فعل ) به معنی خذ (بگیر)، مانند هع اصل آن ها (بوده ) الف به اجتماع ساکنین حذف شده است . و هائی مانند (هاعی ) برای زن و (هاآ) مانند (هاعا) برای تثنیه و هائوا وهأن (هعن ) و هرگاه ترا گفته شود هاء میگوئی : مااهاء؛یعنی نمی گیرم (ای مااخذ) و لا هاء اﷲ ذا؛ یعنی سوگندبه خدای و یا فصیح تر آن لا هااﷲ ذابترک مد است . و یامد لحن است و اصل آن لا و اﷲ هذا است یعنی ما اقسم به، پس اسم اﷲ بین ها و ذا داخل شود. (منتهی الارب ).<br></font></div>'),
(264610, 'ها', '<span class=\"hlight\">ها.</span> (ع ضمیر) ضمیر مفرد غایب مؤنث و به معنی آن، او و خویش است . باثرها، بعینها، بنفسها، دنیا و مافیها. فاطمه سلام اﷲ علیها.<br></font></div>'),
(264611, 'ها دادن', '<span class=\"hlight\">هادادن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص مرکب ) وادادن <span class=\"hlight\">:</span> بترسید و پشت هاداد و آهنگ قلعه کرد. (اسکندرنامه ٔ نسخه ٔ سعید نفیسی ). رجوع به معانی «ها» (پیشوند) شود.<br></font></div>'),
(264612, 'ها زدن', '<span class=\"hlight\">ها زدن .</span> <font color=\"DarkGreen\"><b>[ زَ دَ ]</font></b> (مص مرکب ) پیاپی و بسیار زدن . مکرر زدن . (یادداشت مؤلف ) <span class=\"hlight\">:</span> مردم دست به پشت او ها میزدند و او را می انداختند و او واپس می نگرید تا مگر رسول علیه السلام رحمت کناد. (تفسیر ابوالفتوح رازی ).<br></font></div>'),
(264613, 'هاب', '<span class=\"hlight\">هاب .</span> (ع اِ) مار. (منتهی الارب ) (از اقرب الموارد) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کلمه ای است که شتر را بدان خوانند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اسب را بدان خوانند. <BR><font color=\"Blue\">◄</font> اسب را بدان رانند. (منتهی الارب ) (از اقرب الموارد) (آنندراج ) (ناظم الاطباء).<br></font></div>'),
(264614, 'هاب', '<span class=\"hlight\">هاب .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) قلعه ٔ عظیمی است از عواصم . (از معجم البلدان ).<br></font></div>'),
(264615, 'هاب', '<span class=\"hlight\">هاب .</span> <font color=\"DarkGreen\"><b>[ ها بِن ْ ]</font></b> (ع ص ) رجوع به هابی شود.<br></font></div>'),
(264616, 'هاب هاب', '<span class=\"hlight\">هاب هاب .</span> (ع اِ صوت ) کلمه ای است که بدان شتر را در وقت راندن زجر کنند. (از اقرب الموارد) (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br></font></div>'),
(264617, 'هابخت', '<span class=\"hlight\">هابخت .</span> (اِخ ) مکسیملیانون (<span class=\"hlight\" dir=\"rtl\">١٧٧٥</span>-<span class=\"hlight\" dir=\"rtl\">١٨٣٩</span> م .). مدرس زبان عربی در مدرسه ٔ بزرگ پادشاهی برسلاویه ٔ پروس و مولدش در شهر برسلا بود و در زمان «دوساسی » (خاورشناس ) به پاریس رفت و نزد وی درس خواند و همچنین زبان عربی را در نزد کشیش رفائیل مصری فراگرفت . کتابی منتشر کرد که آن را در کتابخانه ٔ دانشمند ادیب محمود بک السبع که اکنون در محکمه ٔ استیناف محلی مستشار است دیدم و آن کتاب از نوادر کتب به شمار است . جناء الفواکه و الاثمار فی جمع بعض مکاتیب الاحباب الاحرار من عدة امصار و أقطار. و آن به زبان لاتینی ترجمه و در سال <span class=\"hlight\" dir=\"rtl\">١٨٢٤</span> م . در برسلاو طبع شده است و فرهنگی برای لغات عربی و ترجمه ٔ آنها به زبان لاتینی در این کتاب ترتیب داده شده . و نامه های آن به لهجه ٔ اهل مصر و شام و مراکش است و بیشتر آنها نامه هایی است که در زمان جنگهای ناپلئون اول نوشته شده است . این مستشرق نیز برگزیده ای از امثال میدانی را جمع کرده است . واو نخستین کسی است که کتاب الف لیلة و لیلة را در اروپا به طبع رسانیده است . مباشرت آن کتاب در سال <span class=\"hlight\" dir=\"rtl\">١٨٢٥</span> با خود وی بوده است و نه جلد از آن قبل از مرگش طبع شده است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ستون <span class=\"hlight\" dir=\"rtl\">١٨٨٦</span> - <span class=\"hlight\" dir=\"rtl\">١٨٨٧</span>).<br></font></div>'),
(264618, 'هابر', '<span class=\"hlight\">هابر.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) ضرب هابر؛ ضرب که گوشت را ببرد. (منتهی الارب ) (آنندراج ). زدنی که گوشت را ببرد. (ناظم الاطباء). ضرب هبرو هبیر. هابر یعنی قاطع گوشت . (تاج العروس ). <BR><font color=\"Blue\">◄</font> نام مردی است . (منتهی الارب ).<br></font></div>'),
(264619, 'هابروبراکون برویکورنیس', '<span class=\"hlight\">هابروبراکون برویکورنیس .</span> <font color=\"DarkGreen\"><b>[ رُ ک ُ رِ ک ُ]</font></b> (لاتینی، اِ مرکب ) حشره ای است . (بیولوژی وراثت تألیف عزت اﷲ خبیری ص <span class=\"hlight\" dir=\"rtl\">١١٠</span>).<br></font></div>');
