INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(268128, 'هم', '<span class=\"hlight\">هم .</span> <font color=\"DarkGreen\"><b>[ هََ م م ]</font></b> (ع اِ) اندوه .ج، هموم . (منتهی الارب ) (از اقرب الموارد). یکی از اعراض شش گانه ٔ نفسانیه . (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>برداشته خزینه و انباشته به زر<br>صندوقهای پیل، و نه در دل هم و نه غم .<br> <font color=\"Red\">فرخی .</font><br>زآرزوها که داشت خاقانی <br>هیچ همّی به جز وصال تو نیست .<br> <font color=\"Red\">خاقانی .</font><br>اگر در این مهم عظیم و هم ّ جسیم تهاون و توانی جایز شمرد و روی به مدافعت ننهد، ملک موروث برباد آید. (ترجمه ٔ تاریخ یمینی ). <BR><font color=\"Blue\">◄</font> آنچه بدان قصد کنند. (منتهی الارب ) (از اقرب الموارد). بستن دل به انجام کاری قبل از انجام، چه نیک و چه بد. (تعریفات ). <BR><font color=\"Blue\">◄</font> قصد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) بسنده و کافی . (منتهی الارب ) (از اقرب الموارد): هذا الرجل همک من رجل ؛ یعنی تو را کافی است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (مص ) اندوهگین کردن کار کسی را. <BR><font color=\"Blue\">◄</font> گداختن بیماری اندام کسی راو لاغر کردن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> در خواب کردن ِ زن کودک را به آواز. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گداختن پیه را. <BR><font color=\"Blue\">◄</font> شیردوشیدن . <BR><font color=\"Blue\">◄</font> رنجور گردانیدن بسیاری ِ شیر ناقه را. <BR><font color=\"Blue\">◄</font> آهنگ کردن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ذوب کردن برف را. (اقرب الموارد).<br></font></div>'),
(268129, 'هم', '<span class=\"hlight\">هم .</span> <font color=\"DarkGreen\"><b>[ هَِ م م ]</font></b> (ع ص ) پیر فانی . ج، اهمام . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نازک و نحیف، و در این معنی مشتق از «همته النار» است، یعنی آتش ذوبش کرد. <BR><font color=\"Blue\">◄</font> قدح هم ؛ قدح شکسته . (از اقرب الموارد).<br></font></div>'),
(268130, 'هم آخر', '<span class=\"hlight\">هم آخر.</span> <font color=\"DarkGreen\"><b>[ هََ خ ُ ]</font></b> (ص مرکب ) رجوع به هم آخور شود.<br></font></div>'),
(268131, 'هم آخور', '<span class=\"hlight\">هم آخور.</span> <font color=\"DarkGreen\"><b>[ هََ خُرْ ]</font></b> (ص مرکب ) دو چارپای را گویند که در یک آخور علوفه خورند. <BR><font color=\"Blue\">◄</font> به کنایه دودوست صمیمی را گویند به حالت تحقیر و خوار شمردن .<br></font></div>'),
(268132, 'هم آرایشی', '<span class=\"hlight\">هم آرایشی .</span> <font color=\"DarkGreen\"><b>[ هََ ی ِ ]</font></b> (حامص مرکب ) دارای نظام مشترک بودن . هم روشی . هم راهی <span class=\"hlight\">:</span> <br>از هم آرایشی وهمکاری <br>هر یکی را یکی کند یاری .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268133, 'هم آشیان', '<span class=\"hlight\">هم آشیان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) دو مرغ یا حیوان که در یک آشیان زیست کنند، و به کنایه دو یار همنشین و همخانه را گویند <span class=\"hlight\">:</span> <br>باز سپید با مگس سگ هم آشیان <br>خاک سیاه بر سر بخت نژند او.<br> <font color=\"Red\">خاقانی .</font><br>میخواستمی کز این جهانم <br>باشدچو توئی هم آشیانم .<br> <font color=\"Red\">نظامی .</font><br>اول شب نظاره گاهم نور<br>وآخر شب هم آشیانم حور.<br> <font color=\"Red\">نظامی .</font><br>ما را نمی برازدبا وصلت آشنایی <br>مرغی نکوتر از من باید هم آشیانت .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(268134, 'هم آشیانی', '<span class=\"hlight\">هم آشیانی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) هم آشیان بودن <span class=\"hlight\">:</span> هر مرغی را که چینه ٔ تربیت او دهد با سیمرغ هم عنانی و با طاووس هم آشیانی نماید. (سندبادنامه ).<br></font></div>'),
(268135, 'هم آغوش', '<span class=\"hlight\">هم آغوش .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) دو تن که در آغوش یکدیگر خسبند. همدم <span class=\"hlight\">:</span> <br>گهی میکرد شهد باربد نوش <br>گهی می بود با شیرین هم آغوش .<br> <font color=\"Red\">نظامی .</font><br>چو شیرین ساقیی باشد هم آغوش <br>نه شیر، ار زهر باشد هم شود نوش .<br> <font color=\"Red\">نظامی .</font><br>گربا دگری شدی هم آغوش <br>ما را به زبان مکن فراموش .<br> <font color=\"Red\">نظامی .</font><br>یکی را دست حسرت بر بناگوش <br>یکی با آنکه میخواهد هم آغوش .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> بسیار نزدیک . نظیر و مانند <span class=\"hlight\">:</span> <br>تا چو هم آغوش غیوران شوم <br>محرم دستینه ٔ حوران شوم .<br> <font color=\"Red\">نظامی .</font><br>شاه را غارپرده دار شده <br>او هم آغوش یار غار شده .<br> <font color=\"Red\">نظامی .</font><br>سکندر هم آغوش دارا شدی <br>چه بودی که مرگ آشکارا شدی ؟<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268136, 'هم آغوشی', '<span class=\"hlight\">هم آغوشی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) همخوابی .هم آغوش شدن . اعتناق . معانقه . (یادداشتهای مؤلف ).<br></font></div>'),
(268137, 'هم آهنگ', '<span class=\"hlight\">هم آهنگ .</span> <font color=\"DarkGreen\"><b>[ هََ هََ ]</font></b> (ص مرکب ) دمساز. هم آواز. موافق . (یادداشت مؤلف ). دو تن که یک اندیشه و یک آهنگ دارند <span class=\"hlight\">:</span> <br>که چندان سپه کرد آهنگ من <br>هم آهنگ این نامدار انجمن .<br> <font color=\"Red\">فردوسی .</font><br>در این پرده با آسمان جنگ نیست <br>که این پرده با کس هماهنگ نیست .<br> <font color=\"Red\">نظامی .</font><br>در این پرده گر سازگاری کنی <br>هم آهنگ را به که یاری کنی .<br> <font color=\"Red\">نظامی .</font><br>گر سیاه است و هم آهنگ تو است <br>تو سفیدش خوان که همرنگ تو است .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(268138, 'هم آهنگی', '<span class=\"hlight\">هم آهنگی .</span> <font color=\"DarkGreen\"><b>[ هََ هََ ]</font></b> (حامص مرکب ) هم قصدی . همراهی . موافقت . (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>در آن پرده که شیرین ساختی ساز<br>هم آهنگیش کردی شه به آواز.<br> <font color=\"Red\">نظامی .</font><br>رجوع به هم آهنگ شود.<br></font></div>'),
(268139, 'هم آوا', '<span class=\"hlight\">هم آوا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم صدا. دو چیز که صدایشان هم آهنگ و به موازات یکدیگر برآید، یا دو کس که با یکدیگر آواز خوانند <span class=\"hlight\">:</span> <br>بر گلت آشفته ام، بگذار تا در باغ وصل <br>زاغ بانگی می کنم بلبل هم آواییم نیست .<br> <font color=\"Red\">سعدی .</font><br>رجوع به هم آواز شود.<br></font></div>'),
(268140, 'هم آواز', '<span class=\"hlight\">هم آواز.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم آوا. دو چیز یا دو تن که با هم آواز خوانند و هم صدا شوند. (یادداشت مؤلف ). آنکه آواز او موافق آواز دیگری باشد. (برهان ) <span class=\"hlight\">:</span> <br>با هرکه در این رهی هم آواز<br>در پرده ٔ او نوا همی ساز.<br> <font color=\"Red\">نظامی .</font><br>خبر ما برسانید به مرغان چمن <br>که هم آواز شما در قفسی افتاده ست .<br> <font color=\"Red\">سعدی .</font><br>ای بلبل اگر نالی، من با تو هم آوازم <br>تو عشق گلی داری، من عشق گل اندامی .<br> <font color=\"Red\">سعدی .</font><br>چون تنگ نباشد دل مسکین حمامی <br>که ش یار هم آواز بگیرند به دامی .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> دو چیز یا دو کس که یک رای و آهنگ دارند. هم آهنگ . (یادداشت مؤلف ). موافق و رفیق . (برهان ) <span class=\"hlight\">:</span> <br>هم آواز شد رای زن با دبیر<br>نبشتند پس نامه ای بر حریر.<br> <font color=\"Red\">فردوسی .</font><br>تو با لشکرت رزم را ساز کن <br>سپه را بر این بر هم آواز کن .<br> <font color=\"Red\">فردوسی .</font><br>که بودند هر ده هم آواز اوی <br>نگه داشتندی به دل راز اوی .<br> <font color=\"Red\">فردوسی .</font><br>دلم چون دید دولت را هم آواز<br>ز دولت کرد بردولت یکی ناز.<br> <font color=\"Red\">نظامی .</font><br>ای بر ازلیتت ز آغاز<br>خلق ازل و ابد هم آواز.<br> <font color=\"Red\">نظامی .</font><br>به روزگار همایون خسرو عادل <br>که گرگ و میش به توفیق او هم آوازند.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(268141, 'هم آوازی', '<span class=\"hlight\">هم آوازی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) هم آواز شدن یا بودن . هم صدا شدن . <BR><font color=\"Blue\">◄</font> برابری . هم سنگی <span class=\"hlight\">:</span> <br>برون ز حکمت و انواع آن که در هر باب <br>تو را رسد که کنی با فلک هم آوازی .<br><font color=\"Red\">ظهیر فاریابی .</font><br></font></div>'),
(268142, 'هم آورد', '<span class=\"hlight\">هم آورد.</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (ص مرکب ) چون دو کس با هم جنگ کنند هر یک مرد دیگری را هم آورد باشد یعنی همتا وهم کوشش . (برهان ). آورد به معنی جنگ است <span class=\"hlight\">:</span> <br>هم آورد را دید گردآفرید<br>که بر سان آتش همی بردمید.<br> <font color=\"Red\">فردوسی .</font><br>چه سازیم و درمان این درد چیست <br>به ایران هم آورد این مرد کیست ؟<br> <font color=\"Red\">فردوسی .</font><br>نشست از بر پشت پیل سپید<br>هم آوردش از بخت شد ناامید.<br> <font color=\"Red\">فردوسی .</font><br>کس این پهلوان را هم آورد نیست <br>همه لشکر او را یکی مرد نیست .<br> <font color=\"Red\">اسدی .</font><br>هم آورد او گر بود زنده پیل <br>کم از قطره باشد برِ رود نیل .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">هم آوردجوی </span> ؛ آنکه حریف و هم جنگ خواهد <span class=\"hlight\">:</span> <br>به میدان ز خون چون درآورد جوی <br>میان دو صف شد هم آوردجوی .<br><font color=\"Red\">اسدی .</font><br></font></div>'),
(268143, 'هم آویز', '<span class=\"hlight\">هم آویز.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم آورد. هماویز. رجوع به هماویز شود.<br></font></div>'),
(268144, 'هم آگوش', '<span class=\"hlight\">هم آگوش .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم آغوش . نزدیک . همدم .<br>- <span class=\"hlight\">هم آگوش دل </span> ؛ دوتن که دلشان به یکدیگر نزدیک است <span class=\"hlight\">:</span> <br>زین دو هم آگوش دل آمد پدید<br>آن خلفی کاو به خلافت رسید.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268145, 'هم آیین', '<span class=\"hlight\">هم آیین .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب )دو تن که یک آیین و یک کیش دارند. هم مذهب . هم روش .<br></font></div>'),
(268146, 'هم رفتن', '<span class=\"hlight\">هم رفتن .</span> <font color=\"DarkGreen\"><b>[ هََ رَ ت َ ]</font></b> (مص مرکب ) بسته شدن و التیام زخم، یا بسته شدن شکاف زمین و جز آن . (یادداشت مؤلف ).<br>- <span class=\"hlight\">امثال </span> :<br><span class=\"hlight\">باران آمد، ترک ها هم رفت </span> ؛ کنایه از کسی است که ثروتمند شود و عیب های او را بپوشاند. (یادداشت مؤلف ).<br></font></div>'),
(268147, 'هم ریختن', '<span class=\"hlight\">هم ریختن .</span> <font color=\"DarkGreen\"><b>[ هََ ت َ ]</font></b> (مص مرکب ) به هم ریختن . در هم ریختن . آشفتن . رجوع به ترکیبات ِ «هم » شود.<br></font></div>'),
(268148, 'هم زدن', '<span class=\"hlight\">هم زدن .</span> <font color=\"DarkGreen\"><b>[ هََ زَ دَ ]</font></b> (مص مرکب ) مخلوط کردن . مایعی را که از مواد مختلف باشد با آلتی در هم آمیختن، چنانکه آش را با چمچه یا قاشق هم زنند. (یادداشت مؤلف ).<br></font></div>'),
(268149, 'هم مالیدن', '<span class=\"hlight\">هم مالیدن .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (مص مرکب ) به هم مالیدن : رختها را هم مالید. (یادداشت مؤلف ).<br></font></div>'),
(268150, 'هم و غم', '<span class=\"hlight\">هم و غم .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ م ُ غ َ م م <span class=\"hlight\" dir=\"rtl\">/</span> غ َ ]</font></b> (ترکیب عطفی، اِ مرکب ) غصه واندوه . غم و اندوه . رجوع به هم و ترکیبات آن شود.<br></font></div>'),
(268151, 'هم کردن', '<span class=\"hlight\">هم کردن .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ دَ ]</font></b> (مص مرکب ) در زبان کودکان، خوردن . (یادداشت مؤلف ).<br></font></div>'),
(268152, 'هم کشیدن', '<span class=\"hlight\">هم کشیدن .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ <span class=\"hlight\" dir=\"rtl\">/</span>ک ِ دَ ]</font></b> (مص مرکب ) دوختن لباس بدون دقت و ظرافت : هرطور بود هم کشیدم و تنم کردم . (یادداشتهای مؤلف ).<br></font></div>'),
(268153, 'هم گذاشتن', '<span class=\"hlight\">هم گذاشتن .</span> <font color=\"DarkGreen\"><b>[ هََ گ ُ ت َ ]</font></b> (مص مرکب ) بستن . بر هم گذاشتن کتاب را یا چشم را. (یادداشتهای مؤلف ).<br></font></div>'),
(268154, 'هما', '<span class=\"hlight\">هما.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از بخش الیگودرز شهرستان بروجرد که <span class=\"hlight\" dir=\"rtl\">٤٢٢</span> تن سکنه دارد. آب آن از قنات و چاه . محصول عمده اش غله، پنبه و لبنیات و کاردستی زنان قالی بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268155, 'هما', '<span class=\"hlight\">هما.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) میرزا صادق دیباچه نگار، از مردم مرو. (دانشوران خراسان ص <span class=\"hlight\" dir=\"rtl\">٢٥١</span>).<br></font></div>'),
(268156, 'هما', '<span class=\"hlight\">هما.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع صوت ) هما واﷲ؛ به معنی اما واﷲ است . برای تحقیق تالی خود آید. تقول : هما ان زیداً عاقل ؛ یعنی درحقیقت او عاقل است . (منتهی الارب ).<br></font></div>'),
(268157, 'هما', '<span class=\"hlight\">هما.</span> <font color=\"DarkGreen\"><b>[ هَُ]</font></b> (اِ) مرغی است که استخوان میخورد. بر سر هرکه سایه ٔ او افتد به دولت و سلطنت رسد. (غیاث ). همای . پشتش سیاه مایل به خاکستری، سینه اش حنایی بی نقش، دو شاخ مانند شاخ بوم و ریش زیبا و بالهایی از قره قوش بلندتر دارد. (یادداشت مؤلف ). در ادبیات فارسی او را مظهر فرّ و شکوه دانند و به فال نیک گیرند <span class=\"hlight\">:</span> <br>تو فرّ همایی و زیبای گاه <br>تو تاج کیانی و پشت سپاه .<br> <font color=\"Red\">فردوسی .</font><br>درفشی ز پیل سیه پیکرش <br>همایی ز یاقوت سرخ از برش .<br> <font color=\"Red\">فردوسی .</font><br>نیکوتر از بهاری، زیباتر از نگاری <br>چابک تر از تذروی فرخ تر از همایی .<br> <font color=\"Red\">فرخی .</font><br>زاغ حرص و همای همت را<br>ریزه ٔ استخوان نمی یابم .<br> <font color=\"Red\">خاقانی .</font><br>خوانده به چتر شاه بر چرخ آیةالکرسی ز بر<br>چترش همایی زیر پر عرش معلا داشته .<br> <font color=\"Red\">خاقانی .</font><br>تا همایم خوانده ای در کام دل <br>هرنواله استخوان می آیدم .<br> <font color=\"Red\">خاقانی .</font><br>با جهل مجوی زهد ازیرا<br>کز جغد نیامدت همایی .<br> <font color=\"Red\">نظامی .</font><br>فرّهمای ملکی داشتی <br>اوج هوای فلکی داشتی .<br> <font color=\"Red\">نظامی .</font><br>چون تو همایی شرف کار باش <br>کم خور و کم گوی و کم آزار باش .<br> <font color=\"Red\">نظامی .</font><br>که هریک بود در میدان همایی <br>به دعوی گاه نخجیر اژدهایی .<br> <font color=\"Red\">نظامی .</font><br>بدین طاوس کرداری، همایی <br>روان شد چون تذروی در هوایی .<br> <font color=\"Red\">نظامی .</font><br>و رجوع به همای شود.<br></font></div>'),
(268158, 'هما', '<span class=\"hlight\">هما.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع ضمیر) ضمیر است برای تثنیه ٔ مؤنث و مذکر. (یادداشت مؤلف ). ایشان دو مرد یا ایشان دو زن . (ترجمان علامه ٔ جرجانی ترتیب عادل بن علی ).<br></font></div>'),
(268159, 'هماآباد', '<span class=\"hlight\">هماآباد.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) رجوع به هماباد (بالا، پائین ) شود.<br></font></div>'),
(268160, 'هماباد بالا', '<span class=\"hlight\">هماباد بالا.</span> <font color=\"DarkGreen\"><b>[ هَُ دِ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان نایین که <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268161, 'هماتروپین', '<span class=\"hlight\">هماتروپین .</span> <font color=\"DarkGreen\"><b>[ هَِ رُ ]</font></b> (فرانسوی، اِ) ترکیبی از این دارو را به نام «برومیدرات دُ هماتروپین » در چشم پزشکی به صورت محلول <span class=\"hlight\" dir=\"rtl\">٢</span> در هزار به کار میبرند. (از درمانشناسی ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(268162, 'هماجلگه', '<span class=\"hlight\">هماجلگه .</span> <font color=\"DarkGreen\"><b>[ هَُ ؟ ]</font></b> (اِخ ) دهی است از بخش ثلاث شهرستان کرمانشاهان که <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه دارد. آب آن از رود زمکان و محصول عمده اش لبنیات، سقز، کتیرا ومیوه ٔ جنگلی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268163, 'هماد', '<span class=\"hlight\">هماد.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ضمیر مبهم ) همه و جمیع و کل . (برهان ).<br></font></div>'),
(268164, 'همادی', '<span class=\"hlight\">همادی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص نسبی ) کلی و همگی . (انجمن آرا). همگی و تمامی . (برهان ).<br></font></div>'),
(268165, 'هماذی', '<span class=\"hlight\">هماذی .</span> <font color=\"DarkGreen\"><b>[ هََ ذی ی ]</font></b> (ع ص، اِ) شتر تیزرو و سبک رفتار. <BR><font color=\"Blue\">◄</font> شتابی . <BR><font color=\"Blue\">◄</font> سختی گرما. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268166, 'همار', '<span class=\"hlight\">همار.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ق ) همارا. رجوع به همارا و هماره شود.<br></font></div>'),
(268167, 'همار', '<span class=\"hlight\">همار.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) اندازه باشد. (برهان ). <BR><font color=\"Blue\">◄</font> حساب را نیز گویند که شمردن چیزی باشد. (برهان ). رجوع به آمار شود.<br></font></div>'),
(268168, 'همار', '<span class=\"hlight\">همار.</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ما ]</font></b> (ع ص ) ابر نیک روان . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268169, 'همارا', '<span class=\"hlight\">همارا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ق ) همواره و همیشه . (اسدی ). همواره و همیشه و دائم . (برهان ) <span class=\"hlight\">:</span> <br>گزیده چهار توست بدو درج ها نهان <br>همارا به آخشیج همارا به کارزار.<br> <font color=\"Red\">رودکی (از فرهنگ فارسی معین ).</font><br>تو با من نسازی که از صحبت من <br>ملالت فزاید همارا و تاسه .<br> <font color=\"Red\">انوری .</font><br>رجوع به همواره و هماره و همار شود.<br></font></div>'),
(268170, 'هماره', '<span class=\"hlight\">هماره .</span> <font color=\"DarkGreen\"><b>[ هََ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) همار که اندازه و شمار و حساب باشد. (برهان ). رجوع به همار شود.<br></font></div>'),
(268171, 'هماره', '<span class=\"hlight\">هماره .</span> <font color=\"DarkGreen\"><b>[ هََ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ق ) مخفف همواره، یعنی همیشه و دائم . (برهان ). پیوسته . هموار. همواره . دائماً. (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>فضل او خوان گر همه توحیدخواهی گفت تو<br>زآنکه فضل او هماره قدرت یزدان بود.<br> <font color=\"Red\">مجلدی گرگانی .</font><br>وین خیمه ٔ کبود نبینند و این دو مرغ <br>کایشان هماره از پس دیگر همی پرند.<br> <font color=\"Red\">ناصرخسرو.</font><br>رجوع به همواره و همار شود.<br></font></div>'),
(268172, 'هماز', '<span class=\"hlight\">هماز.</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ما ]</font></b> (ع ص ) عیب کننده . <BR><font color=\"Blue\">◄</font> سخن چین . (منتهی الارب ) (اقرب الموارد). لماز. غماز. (یادداشت مؤلف ).<br></font></div>'),
(268173, 'هماس', '<span class=\"hlight\">هماس .</span> <font color=\"DarkGreen\"><b>[هَُ ]</font></b> (اِ) همتا و انباز و شریک و رفیق . (برهان ).<br></font></div>'),
(268174, 'هماس', '<span class=\"hlight\">هماس .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ما ]</font></b> (ع اِ) شیر بیشه ٔ سخت شکننده . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268175, 'همال', '<span class=\"hlight\">همال .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَُ ]</font></b> (اِ) قرین و همتا و شریک و انباز. (برهان ). دو چیز که در کنار هم به مناسبت قرار گیرند <span class=\"hlight\">:</span> <br>دل من پرآزار از آن بدسگال <br>نبد دست من چیره بر بدهمال .<br> <font color=\"Red\">بوشکور.</font><br>میان ما دو تن آمیخته دو گونه سرشک <br>چو لؤلؤی که کنی با عقیق سرخ همال .<br> <font color=\"Red\">آغاجی .</font><br>فضل او خوان گر همه توحید خواهی گفت تو<br>زآنکه فضل او همال قدرت یزدان بود.<br> <font color=\"Red\">مجلدی .</font><br>ز شیده یکی بود کهتر به سال <br>برادر بد او را و فرخ همال .<br> <font color=\"Red\">فردوسی .</font><br>تو مهراب را کهتری یا همال <br>مر آن دخت او را کجا دید زال ؟<br> <font color=\"Red\">فردوسی .</font><br>هر آن کس که بد باشد و بدسگال <br>نخواهد شدن شاه خود را همال .<br> <font color=\"Red\">فردوسی .</font><br>خسرو گیتی ملک مسعود محمود، آنکه نیست <br>از ملوک او را همال و از شهان او را قرین .<br> <font color=\"Red\">فرخی .</font><br>نگر تا نگویی که در فعل بد<br>هزاران مرا هست یار و همال .<br> <font color=\"Red\">ناصرخسرو.</font><br>من نشوم گر بشود جان من <br>پیش کسی که ش نپسندم همال .<br> <font color=\"Red\">ناصرخسرو.</font><br>غره مشو به دولت و اقبال روزگار<br>زیرا که با زوال همال است دولتش .<br> <font color=\"Red\">ناصرخسرو.</font><br>نسازد با همالان همنشستی <br>کند چون موبدان آتش پرستی .<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> شبه و مانند. (برهان ) <span class=\"hlight\">:</span> <br>بدین برز و بالا و این شاخ و یال <br>نداری کس از پهلوانان همال .<br> <font color=\"Red\">فردوسی .</font><br>چنین گفت : کاین شیده خال من است <br>به بالا و مردی همال من است .<br> <font color=\"Red\">فردوسی .</font><br>ای امیری که تو را دهر نپرورده قرین <br>ای سواری که تو را دیده ندیده ست همال .<br> <font color=\"Red\">فرخی .</font><br>نه چون او به همه باب توان یافت نظیری <br>نه چون او ز همه خلق توان یافت همالی .<br> <font color=\"Red\">فرخی .</font><br>نبودی تو را در جوانی همال <br>کنون چون بُوی که ت بفرسود سال ؟<br> <font color=\"Red\">فرخی .</font><br>ز شاهان کسی بدسگالم نبود<br>به گنج و به لشکر همالم نبود.<br> <font color=\"Red\">اسدی .</font><br>چون که بشناختش همالش بود<br>در تجارت شریک مالش بود.<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> حریف . هم آورد. طرف <span class=\"hlight\">:</span> <br>نگه دار جان ازبد پور زال <br>به جنگت نباشد جز او کس همال .<br> <font color=\"Red\">فردوسی .</font><br> <BR><font color=\"Blue\">◄</font> همسر. شریک زندگی <span class=\"hlight\">:</span> <br>مرا گر همی داد خواهی به کس <br>همالم گشسب سوار است و بس .<br> <font color=\"Red\">فردوسی .</font><br>تو را مژده از دخت مهراب و زال <br>که باشند هر دو دو فرخ همال .<br> <font color=\"Red\">فردوسی .</font><br>چو در پرده ناجنس باشد همال <br>ز تهمت بسی نقش بندد خیال .<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> برابر. هم زور. مساوی، در مقام یا قدرت <span class=\"hlight\">:</span> <br>نخواهم خراج از جهان هفت سال <br>اگر زیردستی بود گر همال .<br> <font color=\"Red\">فردوسی .</font><br>به سان همالان نشستم به خوان <br>که اندر تنم پاره باداستخوان .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268176, 'همال', '<span class=\"hlight\">همال .</span> <font color=\"DarkGreen\"><b>[ هَُ م ْ ما ]</font></b> (ع ص، اِ) ج ِ هامل . (منتهی الارب ) (اقرب الموارد). رجوع به هامل شود.<br></font></div>'),
(268177, 'همال', '<span class=\"hlight\">همال .</span> <font color=\"DarkGreen\"><b>[ هَُ م ْ ما ]</font></b> (ع ص ) نرم و سست از هر چیزی . <BR><font color=\"Blue\">◄</font> زمین ویران و خراب شده از جنگ که کسی آباد نکند آن را. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268178, 'همالی', '<span class=\"hlight\">همالی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص ) همال بودن (شدن ). قرین شدن . همطرازی . برابری <span class=\"hlight\">:</span> <br>فرزند ضیاءالدین کز همت والا<br>خورشید فلک را نپسندد به همالی .<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(268179, 'همالیج', '<span class=\"hlight\">همالیج .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص، اِ) ج ِ هملاج . (منتهی الارب ). رجوع به هملاج شود.<br></font></div>'),
(268180, 'همالیل', '<span class=\"hlight\">همالیل .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص، اِ) گیاههای باقیمانده ٔ ضعیف . <BR><font color=\"Blue\">◄</font> مرغان ضعیف . <BR><font color=\"Blue\">◄</font> جامه ٔ پاره پاره شده . (منتهی الارب ) (اقرب الموارد). مفرد ندارد. (منتهی الارب ).<br></font></div>'),
(268181, 'همام', '<span class=\"hlight\">همام .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع ص، اِ) پیه که از کوهان گداخته شود. <BR><font color=\"Blue\">◄</font> آب برف روان شده . <BR><font color=\"Blue\">◄</font> مرد و پادشاه بزرگ همت . <BR><font color=\"Blue\">◄</font> مهتر دلیر جوانمرد، خاص است به مردان . ج، هِمام . (منتهی الارب ) (اقرب الموارد). مهتر. سر. سرور. سید. رئیس . بزرگ . (یادداشتهای مؤلف ) <span class=\"hlight\">:</span> <br>هم موفق شهریاری، هم مظفر پادشاه <br>هم مؤیدرای میری هم همایون فر همام .<br> <font color=\"Red\">فرخی .</font><br>بلند نام همام از بلند نام گهر<br>بزرگوار امیر از بزرگوار تبار.<br> <font color=\"Red\">فرخی .</font><br>بجوی امام همامی ز اهل بیت رسول <br>که خویشتنْت چنویی همام باید کرد.<br> <font color=\"Red\">ناصرخسرو.</font><br>مرا دانی از وی که کرده ست ایمن ؟<br>حکیمی، کریمی، امامی، همامی .<br> <font color=\"Red\">ناصرخسرو.</font><br>تشبیه کرد چشم تو با چشم خود رسول <br>یعنی که از من است و به من ماند این همام .<br><font color=\"Red\">سوزنی .</font><br>ای هزاران شاعر پخته سخن را همت آنک <br>مدح آرایند بر نام تو ممدوح همام .<br> <font color=\"Red\">سوزنی .</font><br>تا کارهای من شود از اهتمام تو<br>روشن چو رای پاک تو فرزانه و همام .<br> <font color=\"Red\">سوزنی .</font><br>آرزوی جان ملک، عدل و همم بود<br>از ملک عادل همام برآمد.<br> <font color=\"Red\">خاقانی .</font><br>گر زهر جانگزای فراقش دلم بسوخت <br>پازهر خواهم از همم سید همام .<br> <font color=\"Red\">خاقانی .</font><br>عادل همام دولت و دین مرزبان ملک <br>کز عدل، او مبشر عهد و زمان ماست .<br> <font color=\"Red\">خاقانی .</font><br>چون ز گرمابه بیامد آن غلام <br>سوی خویشش خواند آن شاه همام .<br> <font color=\"Red\">مولوی .</font><br>گفت اگر از مکر ناید در کلام <br>حیله را دانسته باشد آن همام .<br> <font color=\"Red\">مولوی .</font><br>گفت تا گوشش نباشد ای همام <br>گوش را بگذارو کوته کن کلام .<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> شیر بیشه . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268182, 'همام', '<span class=\"hlight\">همام .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع اِ) ج ِ هُمام .(منتهی الارب ) (اقرب الموارد). رجوع به هُمام شود.<br></font></div>'),
(268183, 'همام', '<span class=\"hlight\">همام .</span> <font color=\"DarkGreen\"><b>[ هََ م ِ ]</font></b> (ع اِ فعل ) لاهمام ؛ قصد نمی کنم (منتهی الارب )، بدان همت نگمارم یا آن را انجام نمیدهم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> جاءزید همام ؛ ای یهمم . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268184, 'همام', '<span class=\"hlight\">همام .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ما ]</font></b> (ع ص ) سخن چین . (منتهی الارب ). نمام . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) روز سیُم از روزهای سرما. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268185, 'همام', '<span class=\"hlight\">همام .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ما ]</font></b>(اِخ ) ابن غالب . رجوع به فرزدق (شاعر معروف ) شود.<br></font></div>'),
(268186, 'همام', '<span class=\"hlight\">همام .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) تبریزی . خواجه همام الدین بن علایی تبریزی، از شعرا و سخنگویان نامبردار آذربایجان است و در فنون نظم به خصوص در غزلسرایی سبک سعدی را به خوبی تتبع کرده است . خود نیز لطافت سخن خود را دریافته و گفته است :<br>همام را سخن دلفریب و شیرین است <br>ولی چه سود که بیچاره نیست شیرازی .<br>دیوان غزلیات همام در حدود دوهزار بیت دارد. نیز منظومه ای بنام صحبت نامه از او مانده است که به نام شرف الدین هارون پسر شمس الدین محمد صاحبدیوان جوینی ساخته شده است . این غزل معروف از اوست :<br>دانی چگونه باشد از عاشقان جدایی <br>چون دیده ای که ماند خالی ز روشنایی <br>سهل است عاشقان را از جان خود بریدن <br>لیکن ز روی جانان مشکل بود جدایی <br>در دوستی نیاید هرگز خلل ز دوری <br>گر در میان یاران مهری بودخدایی <br>هر زر که خالص آید بر یک عیار باشد<br>صد بار اگر در آتش آن را بیازمایی .<br> <font color=\"Red\">(ازتاریخ ادبیات تألیف رضازاده ٔ شفق ص <span class=\"hlight\" dir=\"rtl\">٣١١</span> به بعد).</font><br>وفات او را به سال <span class=\"hlight\" dir=\"rtl\">٧١٤</span> هَ . ق . ضبط کرده اند. این دو غزل از او نقل میشود:<br>اینان که آرزوی دل و نور دیده اند<br>تَنْشان مگر ز روح لطیف آفریده اند<br>در جسمشان که جان خجل است از لطافتش <br>جانی دگر ز نور الهی دمیده اند<br>از چشم مست و روی و لب باده رنگشان <br>جانها به ذوق، ساغر می درکشیده اند<br>آب حیات بودو نبات و شکر به هم <br>آن شیر مادران که به طفلی مکیده اند<br>مرغان سدره بهر تماشای این گروه <br>از آسمان به منزل دنیا پریده اند<br>در حیرتم از این همه گلهای دلفریب <br>تا در کدام آب و زمین پروریده اند.<br> <font color=\"Red\">#</font><br>این خاک توده منزل دیوان رهزن است <br>بگذر ز منزلی که در او جای دشمن است <br>مغرور عشوه های جهانی و بی خبر<br>کاین غول را چه خون عزیزان به گردن است <br>تا کی کنی عمارت این دامگاه دیو<br>کآخر تو را به عالم علوی نشیمن است <br>سیمرغ جان کجا کند از گلخن آشیان <br>کاو را هوای تربت آن سبز گلشن است <br>از منجنیق دهر شود عاقبت خراب <br>بنیاد این وجود گر از سنگ و آهن است <br>در زیر ران حکم تو گر ابلق زمان <br>رهوار میرود، مشو ایمن که توسن است .<br><font color=\"Red\">(از گنج سخن تألیف صفا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٤</span> به بعد).</font><br></font></div>'),
(268187, 'همام', '<span class=\"hlight\">همام .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از بخش فلاورجان شهرستان اصفهان که <span class=\"hlight\" dir=\"rtl\">٤٥٩</span> تن سکنه دارد. آب آن از قنات و زاینده رود و محصول عمده اش غله، پنبه، برنج و کاردستی زنان کرباس بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268188, 'همام', '<span class=\"hlight\">همام .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ما ]</font></b> (اِخ ) ابن یزید. از صحابه ٔ رسول است . (یادداشت مؤلف ).<br></font></div>'),
(268189, 'همام', '<span class=\"hlight\">همام .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ما ]</font></b> (اِخ ) ابن حارث . از صحابه ٔ معروف رسول . (یادداشت مؤلف ).<br></font></div>'),
(268190, 'همام آباد', '<span class=\"hlight\">همام آباد.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) قریه ای است میان جنوب و مشرق ارسنجان . (فارسنامه ٔ ناصری ).<br></font></div>'),
(268191, 'همامة', '<span class=\"hlight\">همامة.</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (ع مص ) پیر شدن .(منتهی الارب ) (اقرب الموارد). رجوع به همومة شود.<br></font></div>'),
(268192, 'همامیه', '<span class=\"hlight\">همامیه .</span> <font color=\"DarkGreen\"><b>[ هَُ می ی َ ]</font></b> (اِخ ) شهری بین واسط و خوزستان و از اعمال واسط است و نهری دارد که منشعب از دجله می باشد. منسوب به همام الدولةبن مزید است . (معجم البلدان ). شهری است به واسط همام الدوله منصور دبیس را. (منتهی الارب ).<br></font></div>'),
(268193, 'همان', '<span class=\"hlight\">همان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ضمیر مرکب، ص مرکب ) اشارت است به چیزی که در خاطر ملحوظ است . (آنندراج ). مرکب است از هم + آن . در جمله بدین معنی است : این آن چیزی است که بوده است و متکلم و مخاطب میدانند <span class=\"hlight\">:</span> <br>کنون همانم و خانه همان و شهر همان <br>مرا نگویی کز چه شده ست شادی سوک ؟<br> <font color=\"Red\">رودکی .</font><br>دگر شوی تو ولیکن همان بود شب و روز<br>دگر شوی تو ولیکن همان بود مه و سال .<br> <font color=\"Red\">رودکی .</font><br>همی دربه در خشک نان بازجست <br>مر او را همان پیشه بود از نخست .<br> <font color=\"Red\">بوشکور.</font><br>سخن هرچه گویی همان بشنوی <br>نگر تا چه کاری همان بدروی .<br> <font color=\"Red\">فردوسی .</font><br>تا برنزنی بر زمیَش بچه نزاید<br>چون زاد بچه زادن و مردنْش همان است .<br> <font color=\"Red\">منوچهری .</font><br>همی تا بماند زمان و زمین <br>به فرمانْش بادا همان و همین .<br> <font color=\"Red\">اسدی .</font><br>همان خواه بیگانه و خویش را<br>که خواهی روان و تن خویش را.<br> <font color=\"Red\">اسدی .</font><br>همان است گیتی و یزدان همان <br>دگرگونه ماییم و گشت ِ زمان .<br> <font color=\"Red\">اسدی .</font><br>جهان را نوبه نو چند آزمایی <br>همان است او که دیدستیش صد بار.<br> <font color=\"Red\">ناصرخسرو.</font><br>آن گوی مرا که دوست داری <br>تا خلق تو را همان بگویند.<br> <font color=\"Red\">ناصرخسرو.</font><br>وز آن خرمی جان دهد در زمان <br>همان دیدن و دادن جان همان .<br> <font color=\"Red\">نظامی .</font><br>چو حسرت خورد از پرواز آن باز<br>همان باز آمدی بر دست او باز.<br> <font color=\"Red\">نظامی .</font><br>تو را گر دوستی با ما همین بود<br>وفای ما و عهد ما همان است .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">همان خر است ویک کیله جو</span> ؛ تغییر نکرده است . تربیت در او اثری نمی کند. آدم نمیشود.<br> <span class=\"hlight\">همان خر سیاه است و همان راه آسیا</span> ؛ معنی آن مانند مثل قبل است .<br>- <span class=\"hlight\">همان به که </span> ؛ بهتر که . مصلحت این است که <span class=\"hlight\">:</span> <br>دست رنج تو همان به که شود صرف به کام <br>دانی آخر که به ناکام چه خواهد بودن .<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">همانجا</span> ؛ جایی که در جمله های قبل از آن سخن رفته است . جایی که مخاطب میداند <span class=\"hlight\">:</span> <br>بفرمود کاین رابه هروانه گه <br>برید و همانجا کنیدش تبه .<br> <font color=\"Red\">فردوسی .</font><br>- <span class=\"hlight\">هماندرنگ </span>؛ بی درنگ . همان لحظه . فی الفور <span class=\"hlight\">:</span> <br>گر لطف و مردمیت به مردم گیا رسد<br>مردم گیاه مردم گردد هماندرنگ .<br> <font color=\"Red\">سوزنی .</font><br>- <span class=\"hlight\">هماندم </span> ؛ بی درنگ . فوراً. همان لحظه <span class=\"hlight\">:</span> <br>یکی گرز زد ترک را بر هباک <br>کز اسب اندرآمدهمان دم به خاک .<br> <font color=\"Red\">فردوسی .</font><br>پروانه ٔ او گررسدم در طلب جان <br>چون شمع هماندم به دمی جان بسپارم .<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">همانطور، همانطور که </span> ؛ درست مانند دیگری . عین همان .<br>- <span class=\"hlight\">هم آنگاه </span> ؛ درست در همان هنگام . درست در همان لحظه <span class=\"hlight\">:</span> <br>هم آنگاه شد شاه را دلپذیر<br>که گنجور او رفت با اردشیر.<br> <font color=\"Red\">فردوسی .</font><br>بیامد همانگاه مهتر دبیر<br>که رفته ست بیگاه دوش اردشیر.<br> <font color=\"Red\">فردوسی .</font><br>همانگاه کوهی برآمد ز آب <br>تر و تازه و زرد چون آفتاب .<br> <font color=\"Red\">فردوسی .</font><br>- <span class=\"hlight\">همانگه </span> ؛ همانگاه . همان هنگام <span class=\"hlight\">:</span> <br>تهمتن همانگه زبان برگشاد<br>پیام سپهدار ایران بداد.<br> <font color=\"Red\">فردوسی .</font><br>به فرمان یزدان چو این گفته شد<br>نیایش همانگه پذیرفته شد.<br> <font color=\"Red\">فردوسی .</font><br>همانگه ز کوه اندرآمد سپاه <br>جهان شد ز گردسواران سیاه .<br> <font color=\"Red\">فردوسی .</font><br>همانگه سپاه اندرآمد به جنگ <br>سپه همچو دریا و دریا چو گنگ .<br> <font color=\"Red\">عنصری .</font><br> <BR><font color=\"Blue\">◄</font> مرادف لفظ «دیگر» هم آمده است . (آنندراج ). <BR><font color=\"Blue\">◄</font> (حرف ربط مرکب ) باز هم . علاوه بر این . و نیز. و همچنین <span class=\"hlight\">:</span> <br>بفرمای تا اسب و زین آورند<br>کمان و کمند گزین آورند<br>همان نیزه و خود وخفتان جنگ <br>یکی ترکش آکنده تیر خدنگ .<br> <font color=\"Red\">فردوسی .</font><br>همان از منوچهر و از کیقباد<br>که مازندران را نکردند یاد.<br> <font color=\"Red\">فردوسی .</font><br>بیاور سپاه و درفش مرا<br>همان تخت و زرینه کفش مرا.<br> <font color=\"Red\">فردوسی .</font><br>چو رامین آن درخش تیغ او دید<br>همان در کینه بازی میغ او دید.<br> <font color=\"Red\">فخرالدین اسعد.</font><br> <BR><font color=\"Blue\">◄</font> اعم از این یا آن . (یادداشت مؤلف ). چه این و چه آن <span class=\"hlight\">:</span> <br>نیاسود یک تن ز خود و شکار<br>همان یکسواره همان شهریار.<br> <font color=\"Red\">فردوسی .</font><br>دروگر زمان است و ما چون گیا<br>همانش نبیره همانش نیا.<br> <font color=\"Red\">فردوسی .</font><br> <BR><font color=\"Blue\">◄</font> بی درنگ .به محض اینکه . تا. به مجرد اینکه <span class=\"hlight\">:</span> <br>شب تیره مست آمد از بزم سور<br>همان تا مرا دید جوشان ز دور<br>یکی خنجر آبگون برکشید<br>همی خواست از تن سرم را برید.<br> <font color=\"Red\">فردوسی .</font><br> <BR><font color=\"Blue\">◄</font> (ق مرکب ) حتماً. بی شک . همانا <span class=\"hlight\">:</span> <br>دل زن همان دیو را هست جای <br>ز گفتار باشند جوینده رای .<br> <font color=\"Red\">فردوسی .</font><br>چو پیمانه تن مردم هماره عمر پیماید<br>بیاید زیر پیمودن همان یک روز پیمانه .<br> <font color=\"Red\">کسائی .</font><br>پست بنشین که تو را روزی از این قافله گاه <br>گرچه دیر است همان آخر باید برخاست .<br> <font color=\"Red\">ناصرخسرو.</font><br>رجوع به همانا شود.<br></font></div>'),
(268194, 'همان', '<span class=\"hlight\">همان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش خداآفرین شهرستان تبریز که <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه دارد. آب آن از چشمه و محصول عمده اش غله است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268195, 'همانا', '<span class=\"hlight\">همانا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ق ) مانا. گویا. پنداری . گمان بری . فرق مانا و همانا این است که «همانا» به تحقیق نزدیکتر است و بعضی گویند به معنی «ظاهراً» و «یقین » باشد و مانا به معنی پنداری و گمان بری . (از برهان ). مانا. گویی . گوییا. ظاهراً. علی الظاهر. (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>شکوفه همچو شکاف است و میغ دیباباف <br>مه و خور است همانا به باغ در صراف .<br> <font color=\"Red\">ابوالمؤید بلخی .</font><br>درخش ار نخندد به گاه بهار<br>همانا نگرید چنین ابرزار.<br> <font color=\"Red\">بوشکور.</font><br>دلت همانا زنگار معصیت دارد<br>به آب توبه ٔ خالص بشویش از عصیان .<br> <font color=\"Red\">خسروانی .</font><br>گویی همچون فلان شدم نه همانا<br>هرگز چون عود کی تواند شد توغ ؟<br> <font color=\"Red\">منجیک .</font><br>همانا که با زال پیمان من <br>شنیده ست شاه جهانبان من .<br> <font color=\"Red\">فردوسی .</font><br>همانا فراموش کردی ز من <br>دلیری نمودن به هر انجمن .<br> <font color=\"Red\">فردوسی .</font><br>سخن هرچه گفتم به مادر بگوی <br>نبیند همانا مرا نیز روی .<br> <font color=\"Red\">فردوسی .</font><br>سپاهی و جنگی و شهری سوار<br>همانا که بودند سیصدهزار.<br> <font color=\"Red\">فردوسی .</font><br>با چنین خلق و چنین رسم گر او را گویند<br>که فرشته ست، همانا که نباشد بهتان .<br> <font color=\"Red\">فرخی .</font><br>بدان دیار همانا که موج خون عدو<br>به سالها ننشیند ز دشت در کردر.<br> <font color=\"Red\">عنصری .</font><br>همانا که چون تو فژاک آمدم <br>دگر چون تو ابله فغاک آمدم .<br> <font color=\"Red\">اسدی .</font><br>آز تو نهنگی است همانا که نپرسد<br>از گُرْسنگی خویش حرامی ز حلالی .<br> <font color=\"Red\">ناصرخسرو.</font><br>مرا گفت : همانا همی اندیشی حدیث ترکمانان و فرودگرفتن ایشان . (تاریخ بیهقی ). قاید گفت که همانا که مرا بگیرد. (تاریخ بیهقی ). من گفتم : نه همانا که وی این کند و حق خداوند ماضی نگه دارد. (تاریخ بیهقی ).<br>گر این فضل بر کوه خوانی همانا<br>که جز بارک اللَّه صدائی نیابی .<br> <font color=\"Red\">خاقانی .</font><br>ای تیغ ملک در کف رخشانْش همانا<br>در چشمه ٔ حیوان ولا زهرگیایی .<br> <font color=\"Red\">خاقانی .</font><br>بر درد دل دوا چه بود تا من آن کنم <br>گویند صبر کن، نه همانا من آن کنم .<br> <font color=\"Red\">خاقانی .</font><br>همانا سالها اسباب مناصحت و مخالصت میان ایشان ممهد و مؤکد بود. (ترجمه ٔ تاریخ یمینی ).<br>همانا که بر جای ترکیب خاک <br>ز ترکیب گوگرد بود آن مغاک .<br> <font color=\"Red\">نظامی .</font><br>گفت همانا که در این همرهان <br>صورت این حال نماند نهان .<br> <font color=\"Red\">نظامی .</font><br>سعدی گلت شکفت همانا که صبحدم <br>فریاد بلبلان سحرخیز می کنی .<br> <font color=\"Red\">سعدی .</font><br>حدیث آرزومندی که در این نامه ثبت افتاد<br>همانا بی غلط باشد که حافظ داد تلقینم .<br> <font color=\"Red\">حافظ.</font><br><BR><font color=\"Blue\">◄</font> (اِ) به معنی شبه و نظیر هم آمده است . (برهان ). شاهد برای این معنی به دست نیامد.<br></font></div>'),
(268196, 'همانان', '<span class=\"hlight\">همانان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) <font color=\"DarkGreen\"><b>[ شهری است به هندوستان ]</font></b>، جای زاهدان هند است و ایشان بر همانند که گویند: مااز ابراهیم پیغمبریم صلوات اﷲعلیه . (حدود العالم ).<br></font></div>'),
(268197, 'هماناک', '<span class=\"hlight\">هماناک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ق مرکب ) همانا گویی . همانا که ... <span class=\"hlight\">:</span> <br>در کار تو شد سر سنائی <br>زین نیست تو را خبر هماناک .<br><font color=\"Red\">سنائی .</font><br></font></div>'),
(268198, 'همانند', '<span class=\"hlight\">همانند.</span> <font color=\"DarkGreen\"><b>[ هََ ن َن ْ ]</font></b> (ص مرکب ) مخفف هم مانند است که به معنی شبیه و نظیر و مانند یکدیگر باشد. (برهان ). نیز مرخم هماننده است <span class=\"hlight\">:</span> <br>به رای و به گفتار و نیکی گمان <br>نبینی همانند او در زمان .<br> <font color=\"Red\">فردوسی .</font><br>ز کارآزموده گزیده مهان <br>همانند تو نیست اندر جهان .<br> <font color=\"Red\">فردوسی .</font><br>مرا با صنوبر همانند کردی <br>به قد و به رخ با ستاره برابر.<br> <font color=\"Red\">فرخی .</font><br>که از چهر و بالا و فرّ و شکوه <br>همانند او کس نبد زآن گروه .<br> <font color=\"Red\">اسدی .</font><br>همانند بس یابی از مردمان <br>ولیکن درستی نباشد همان .<br> <font color=\"Red\">اسدی .</font><br>ای خوب نهال ار ز خرد بار نگیری <br>با بید و سپیدار همانند و همالی .<br> <font color=\"Red\">ناصرخسرو.</font><br>رجوع به هماننده شود.<br></font></div>'),
(268199, 'هماننده', '<span class=\"hlight\">هماننده .</span> <font color=\"DarkGreen\"><b>[ هََ ن َن ْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب ) همانند. مانند. شبیه . نظیر. قرین <span class=\"hlight\">:</span> <br>هماننده ٔ شهریاراردشیر<br>فزاینده و فرخ و دلپذیر.<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268200, 'همانندی', '<span class=\"hlight\">همانندی .</span> <font color=\"DarkGreen\"><b>[ هََ ن َن ْ ]</font></b> (حامص مرکب ) شباهت . به یکدیگر مانستن . مماثلت . تشابه . (یادداشت مؤلف ).<br></font></div>'),
(268201, 'همانی', '<span class=\"hlight\">همانی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص نسبی ) منسوب به همان که ظاهراً قریه ای است در عراق . (سمعانی ).<br></font></div>'),
(268202, 'همانی آسمان', '<span class=\"hlight\">همانی آسمان .</span> <font color=\"DarkGreen\"><b>[ هََ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ مرکب ) فلک کلی را گویند، و همانی آسمانها افلاک کلیه . و فلک کلی به قول مشهور نُه است به عدد حرکات محسوسه ٔ مختلفه، چه نُه حرکت مختلف یافته شده : هفت از سبعه ٔ سیاره، یکی از فلک ثوابت و دیگر فلک معدل النهار که حرکت یومیه باشد و مجموع ثوابت و سیارات در آن شریک و انبازند. (انجمن آرا).<br></font></div>'),
(268203, 'هماهم', '<span class=\"hlight\">هماهم .</span> <font color=\"DarkGreen\"><b>[ هََ هَِ ]</font></b> (ع اِ) هموم و اندوهها. (منتهی الارب ). ج ِ هم ّ. رجوع به هم ّ و هموم شود.<br></font></div>'),
(268204, 'هماور', '<span class=\"hlight\">هماور.</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (اِخ ) مخفف هاماوران است که ولایت عربستان و یمن باشد. (انجمن آرا). سراسر ولایت شام و یمن را گویند. (برهان ) <span class=\"hlight\">:</span> <br>چو شاه هماور به شهراندرون <br>بیامد بننشست با رهنمون .<br> <font color=\"Red\">فردوسی .</font><br>رجوع به هاماوران شود.<br></font></div>'),
(268205, 'هماور', '<span class=\"hlight\">هماور.</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (ص مرکب ) مخفف هم آورد. (انجمن آرا). رجوع به هم آورد شود. <BR><font color=\"Blue\">◄</font> به معنی خواجه تاش هم هست که هم صاحب و هم خداوند باشد یعنی دو کس یا بیشتر که یک صاحب و یک خداوند دارند، چه آور به معنی خداوند و صاحب هم آمده است . (برهان ).<br></font></div>'),
(268206, 'هماوران', '<span class=\"hlight\">هماوران .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (اِخ ) هماور. هاماوران . رجوع به هاماوران شود.<br></font></div>'),
(268207, 'هماون', '<span class=\"hlight\">هماون .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (اِخ ) کوهی در ایران . (برهان ). کوهی است مشهور از جبال خراسان که در آنجا میان طوس سردار ایران و پسران سپهدار توران جنگ عظیمی واقع شدو شکست به سپاه طوس افتاد. (انجمن آرا) <span class=\"hlight\">:</span> <br>دو روز این یکی رنج بر تن نهیم <br>دو دیده به کوه هماون نهیم .<br> <font color=\"Red\">فردوسی .</font><br>علف تنگ بوداندر آن رزمگاه <br>از آن بر هماون کشیدم سپاه .<br> <font color=\"Red\">فردوسی .</font><br>بیچاره عدو بر تو کند سود به چاره <br>گر کوه هماون بتوان سود به هاون .<br> <font color=\"Red\">قطران .</font><br>شکرلب نوش از بوم هماون <br>سمن رنگ و سمن بوی و سمن تن .<br><font color=\"Red\">فخرالدین اسعد.</font><br></font></div>'),
(268208, 'هماوندی', '<span class=\"hlight\">هماوندی .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (اِخ ) از ایلات کرد. (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٥٧</span>).<br></font></div>'),
(268209, 'هماویز', '<span class=\"hlight\">هماویز.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم آویز. هم آورد. هم کوشش . همتا. کفو. (برهان ) <span class=\"hlight\">:</span> <br>به هرمز نعره ای برزد که مگریز<br>بیا کآمد به میدانت هماویز.<br> <font color=\"Red\">نزاری .</font><br>چنان جنگ بر جنگیان تیز شد<br>که دست و گریبان هماویز شد.<br><font color=\"Red\">نزاری .</font><br></font></div>'),
(268210, 'هماک', '<span class=\"hlight\">هماک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) در رساله ٔ خویشتاب که به گرزن دانش موسوم است، به معنی اشاره آمده و عبارت را به دستان سام که زال زر باشد و شاگرد سیمرغ حکیم (!) بوده، نسبت داده که در اثبات ذات ایزد گفتا که : چون واجب الوجود را مکان و جهت نباشد باید که پذیرای هماک یعنی قابل اشارت نبود. یعنی اشارت بدو نتوان کرد الا از روی عقل . (انجمن آرا). این کلمه در مآخذ قدیم لغت ظاهراً ضبط نشده است .<br></font></div>'),
(268211, 'هماکوه', '<span class=\"hlight\">هماکوه .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از بخش الیگودرز شهرستان بروجرد که <span class=\"hlight\" dir=\"rtl\">٢٦٠</span> تن سکنه دارد. آب آن از چشمه و قنات و محصول عمده اش غله و لبنیات است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268212, 'همای', '<span class=\"hlight\">همای .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از بخش سعادت آباد شهرستان بندرعباس که <span class=\"hlight\" dir=\"rtl\">٤٥٩</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و خرماست . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268213, 'همای', '<span class=\"hlight\">همای .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از بخش ورزقان شهرستان اهر که <span class=\"hlight\" dir=\"rtl\">٥٦٢</span> تن سکنه دارد.آب آن از چشمه ها و محصول عمده اش غله و سردرختی است .شامل دو قسمت همای بالا و همای پائین است . همای بالا <span class=\"hlight\" dir=\"rtl\">٢٢١</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268214, 'همای', '<span class=\"hlight\">همای .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) نام موبد بهرام گور. (یادداشت مؤلف ) (فهرست ولف ) <span class=\"hlight\">:</span> <br>ز ایران بیامد خجسته همای <br>خود و نامداران پاکیزه رای .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268215, 'همای', '<span class=\"hlight\">همای .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) نام قیصر روم که زن بهرام گور بوده است . (برهان ) <span class=\"hlight\">:</span> <br>از فرنگیس و کتایون و همای <br>باستان را نام و آوا دیده ام .<br> <font color=\"Red\">خاقانی .</font><br>دختر قیصر همایون رای <br>هم همایون وهم به نام همای .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268216, 'همای', '<span class=\"hlight\">همای .</span><font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) نام پادشاه زاده ای که به همایون عاشق بود، و قصه ٔ همای و همایون مشهور است . (برهان ). رجوع به منظومه ٔ همای و همایون اثر خواجوی کرمانی شود.<br></font></div>'),
(268217, 'همای', '<span class=\"hlight\">همای .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) نام دختر بهمن که در حباله ٔ نکاح پدر خودبود. (برهان ). همای آزاد. رجوع به همای آزاد شود.<br></font></div>'),
(268218, 'همای', '<span class=\"hlight\">همای .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) نام یکی ازخواهران اسفندیار است که ارجاسپ او را اسیر کرده درقلعه ٔ رویین دژ نگه داشته بود. (برهان ) <span class=\"hlight\">:</span> <br>که هرکز میانه نهد پیش، پای <br>مر او را دهم دختر خود همای .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268219, 'همای', '<span class=\"hlight\">همای .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) گردون بازی اطفال را گویند یعنی چرخی سازند از چوب و خلاشه و در کنار آب روان نصب کنند تا آب بر آن خورده آن را به گردش درآورد. (برهان ).<br></font></div>'),
(268220, 'همای', '<span class=\"hlight\">همای .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِ) مرغی است که او را مبارک دارند و چون پیدا شود مردم به تفأل در زیر سایه ٔ او روند. (صحاح الفرس ). مرغی است معروف و مشهور که استخوان خورد. (برهان ). هما <span class=\"hlight\">:</span> <br>به هامون کشیدند پرده سرای <br>درفشی کجا پیکرش بُد همای .<br> <font color=\"Red\">فردوسی .</font><br>همای سپهری بگسترد پر<br>همی بر سرش داشت سایه ز فر.<br> <font color=\"Red\">فردوسی .</font><br>بپوشید رخشنده رومی قبای <br>به تاج اندر آویخت پرّ همای .<br> <font color=\"Red\">فردوسی .</font><br>تا نبود چون همای فرخ کرکس <br>همچو نباشد به شبه باز خشین پند.<br> <font color=\"Red\">فرخی .</font><br>گوید ای بارخدای ملکان <br>ای همایون تر از بال همای .<br> <font color=\"Red\">فرخی .</font><br>بینی آن بیجاده عارض لعبت حمری قبای <br>سنبلش چون پرّ طوطی، روی چون پرّ همای .<br> <font color=\"Red\">منوچهری .</font><br>ملکا در ملکی فرّ همای است تو را<br>تا به جای است جهان ملک به جای است تو را.<br> <font color=\"Red\">منوچهری .</font><br>خود راهمای دولت خوانند و غافلند<br>کالاّ غراب ریمن و جغد دمن نیند.<br> <font color=\"Red\">خاقانی .</font><br>فرشته شو، ار نه پری باش باری <br>که همکاسه الاّ همایی نیابی .<br> <font color=\"Red\">خاقانی .</font><br>همای عدل تو چون پرّو بال باز کند<br>تذرو دانه برون آرد از جلاجل باز.<br> <font color=\"Red\">سوزنی .</font><br>کبک وش آن باز کبوترنمای <br>فاخته رو گشت به فرّ همای .<br> <font color=\"Red\">نظامی .</font><br>این کعبه را به جای کبوتر همای بخت <br>کاندر حرم مجاورت این دیار کرد.<br> <font color=\"Red\">نظامی .</font><br>همچون مگس به ریزه ٔ کس ننگریستم <br>هرچند چون همای همایون نیامدم .<br> <font color=\"Red\">عطار.</font><br>تو کوته نظر بودی و سست رای <br>که مشغول گشتی به جغد از همای .<br> <font color=\"Red\">سعدی .</font><br>خرد گفت دولت نبخشد همای <br>گر اقبال خواهی در این سایه آی .<br> <font color=\"Red\">سعدی .</font><br>کس نیاید به زیر سایه ٔبوم <br>ور همای از جهان شود معدوم .<br> <font color=\"Red\">سعدی .</font><br>همای گو مفکن سایه ٔ شرف هرگز<br>بر آن دیار که طوطی کم از زغن باشد.<br> <font color=\"Red\">حافظ.</font><br>و رجوع به هما شود. <BR><font color=\"Blue\">◄</font> علم و نشانی را نیز گویند که بر سر آن صورت همای ساخته یا نقش کرده باشند. (برهان ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(268221, 'همای آزاد', '<span class=\"hlight\">همای آزاد.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) نام دختر بهمن است که زن پدر خود بوده به شریعت زردشت و داراب از او تولد یافته . (برهان ). دختر بهمن بن اسفندیار بوده که سی سال پادشاهی ایران نموده پس داراب پسر خودرا ولی عهد نمود. او را چهرآزاد نیز می گفتند. از بناهای او شهر چهرازادگان است که آن را معرب کردند و جرفادقان گویند و بعضی گلپایگان خوانند. (انجمن آرا).<br></font></div>'),
(268222, 'همای شیرازی', '<span class=\"hlight\">همای شیرازی .</span> <font color=\"DarkGreen\"><b>[ هَُ ی ِ شی ]</font></b> (اِخ ) میرزا محمدعلی . از آغاز زندگی نزد علمای فارس تحصیل کرده سپس به بلاد عراق آمد و در تهران ساکن شد و مدتی بعد به اصفهان رفت . وی از معاصران رضاقلیخان هدایت مؤلف مجمعالفصحاء بوده است . این غزل از اوست :<br>زاهد که از حلال شناسد حرام را<br>اواز چه خورد خون دل خاص و عام را<br>شربت به دست غیر و به دست حبیب زهر<br>انصاف ده که من بستانم کدام را<br>ساقی بهای جام ز ما ملک جم گرفت <br>زآن پیش تر که جم بزند نقش جام را<br>خام است شیخ صومعه، ساقی بیار جام <br>لیکن ز آتشی که کند پخته خام را.<br>رجوع به مجمعالفصحا چ سنگی تهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٦٦</span> شود.<br></font></div>'),
(268223, 'همای مروزی', '<span class=\"hlight\">همای مروزی .</span> <font color=\"DarkGreen\"><b>[ هَُ ی ِ م َرْ وَ ]</font></b> (اِخ ) میرزا محمدصادق . از مردم مرو و در خدمت محمدحسین خان پسر بیرامعلی خان قاجار ملقب به فخرالدوله بوده است . از مرو به مشهد رضوی آمده و سپس به نجف رفته وپس از بازگشت در کاشان متوطن شده است و سپس در پایتخت داروغه ٔ دفترخانه ٔ همایونی گردیده و نگارش وقایع روزانه ٔ دربار به عهده ٔ او محول شده است، چند بار ازطرف شاه به سفارت به سرحدات خراسان و عراق رفته است . او را کتابی به نام تاریخ جهان آرا بوده است که به امر شاه تألیف شده بود. زینت المدایح اثر دیگر او و شامل مدایح شعرای دربار ناصرالدین شاه است . درگذشت او را هدایت در مجمعالفصحاء بدون ذکر تاریخ یاد کرده است . رجوع به مجمعالفصحاء چ سنگی تهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٧٢</span> شود.<br></font></div>'),
(268224, 'همای چهرآزاد', '<span class=\"hlight\">همای چهرآزاد.</span> <font color=\"DarkGreen\"><b>[ هَُ چ ِ ]</font></b> (اِخ ) رجوع به همای آزاد شود.<br></font></div>'),
(268225, 'همای کش', '<span class=\"hlight\">همای کش .</span> <font color=\"DarkGreen\"><b>[ هَُ ک ُ ]</font></b> (نف مرکب ) آنکه دشمن بزرگان و بلندطبعان بود. کشنده ٔ طبایع عالی . دشمن مردم دانا و هشیار <span class=\"hlight\">:</span> <br>همای کش تراز این کرکسان جیفه نهاد<br>ندیده ام که ز عنقا کنند طعم عقاب .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(268226, 'همایجان', '<span class=\"hlight\">همایجان .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهستانی است از بخش اردکان شهرستان شیراز که دارای هشت هزار تن سکنه و شامل <span class=\"hlight\" dir=\"rtl\">٣٥</span> آبادی است . قراء مهم آن عبارتند از: خلار، سنگر، شول، برشنه، تل کوه، سرتلی، بیدحرکت . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(268227, 'همایون', '<span class=\"hlight\">همایون .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) رجوع به همای و نیز رجوع به منظومه ٔ همای و همایون شود.<br></font></div>'),
(268228, 'همایون', '<span class=\"hlight\">همایون .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) نام دختر فغفور چین بوده که نریمان بدو عاشق شده و او به جهت اینکه دختر خاقان بوده با او سر فرودنمی آورده . (انجمن آرا) <span class=\"hlight\">:</span> <br>کتایون خاقان تو را یار بس <br>سخن از همایون مران بیش و بس .<br><font color=\"Red\">اسدی .</font><br></font></div>'),
(268229, 'همایون', '<span class=\"hlight\">همایون .</span> <font color=\"DarkGreen\"><b>[ هَُ]</font></b> (ص ) در اصل به معنی مبارک و فرخنده است . (انجمن آرا). خجسته . فرخنده . فرخ . فرخجسته . میمون <span class=\"hlight\">:</span> <br>سپاه جهاندار بیرون شدند<br>ز کاخ همایون به هامون شدند.<br> <font color=\"Red\">فردوسی .</font><br>بفرمود بردن به پیش سپاه <br>درفش همایون فرخنده شاه .<br> <font color=\"Red\">فردوسی .</font><br>به قلب اندرآمد میان را ببست <br>گرفت آن درفش همایون به دست .<br> <font color=\"Red\">فردوسی .</font><br>پشت سپه میر یوسف آنکه ز رویش <br>روز بزرگان خجسته گشت و همایون .<br> <font color=\"Red\">فرخی .</font><br>جشن فریدون خجسته باد و همایون <br>بر عضد دولت آن بدیل فریدون .<br> <font color=\"Red\">فرخی .</font><br>همیشه بر سر او سایه ٔ همای بود<br>تو هیچ سایه همایون تر از همای مدان .<br> <font color=\"Red\">فرخی .</font><br>آیین عجم، رسم جهاندار فریدون <br>بر شاه جهاندار فری باد و همایون .<br> <font color=\"Red\">عنصری .</font><br>بدین همایون سور و بدین مبارک جشن <br>تو شاد و خلق جهان شاد و دین و دولت شاد.<br><font color=\"Red\">مسعودسعد.</font><br>یکی سرو با خسروانی قبای <br>به فرّ و به فال همایون همای .<br> <font color=\"Red\">اسدی .</font><br>دوزخ تنور شاید مرخس را<br>گل در بهشت باغ همایون است .<br> <font color=\"Red\">ناصرخسرو.</font><br>روزی بس همایون است و مجلسی مبارک . (تاریخ بیهقی ). تاریخ روزگار همایون او را برانم . (تاریخ بیهقی ). کارنامه ٔ این خاندان بزرگ را برانم و روزگار همایون این پادشاه . (تاریخ بیهقی ). ایزدتعالی خیرات بر این عزیمت همایون مقرون گرداناد. (کلیله و دمنه ). نام و آوازه ٔ عهد همایون ... بر امتداد ایام مؤبّد و مخلد گردانید. (کلیله و دمنه ).<br>خداوند را دیدم و روز بر من <br>به دیدار میمون او شد همایون .<br> <font color=\"Red\">سوزنی .</font><br>تارک گشتاسب یافت افسرلهراسب <br>زال همایون به تخت سام برآمد.<br> <font color=\"Red\">خاقانی .</font><br>مبارک باد و میمون باد و خرم <br>همایون خلعت سلطان عالم .<br> <font color=\"Red\">انوری .</font><br>صاحبا جنتت همایون باد<br>عید نوروز بر تو میمون باد.<br> <font color=\"Red\">انوری .</font><br>من که این صفه ٔ همایونم <br>دایه ٔ خاک و طفل گردونم .<br> <font color=\"Red\">انوری .</font><br>در فصل گلی چنین همایون <br>لیلی ز وثاق رفته بیرون .<br> <font color=\"Red\">نظامی .</font><br>به خود کم شوم خلق را رهنمای <br>همایون ز کم دیدن آمد همای .<br> <font color=\"Red\">نظامی .</font><br>علی الخصوص که دیباچه ٔ همایونش <br>به نام سعد ابوبکر سعدبن زنگی است .<br> <font color=\"Red\">سعدی .</font><br>ز مشرق سر کوی آفتاب طلعت تو<br>اگر طلوع کند طالعم همایون است .<br> <font color=\"Red\">حافظ.</font><br>دولت ازمرغ همایون طلب و سایه ٔ او<br>زآنکه با زاغ و زغن شهپر دولت نبود.<br> <font color=\"Red\">حافظ.</font><br>ترکیب ها:<br>- <span class=\"hlight\">همایون آثار</span> . همایون بال . همایون بخت . همایون پی . همایون پیکر. همایون چهر. همایون رای . همایون سریرت . همایون شدن . همایون شکار. همایون فر. همایون کردن . همایون کن . همایون گاه . همایون نظر. همایونی . رجوع به هر یک از این مدخل ها شود.<br></font></div>'),
(268230, 'همایون', '<span class=\"hlight\">همایون .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) از شعرای دربار سلطان یعقوب خان است و طبع نظم او نیکوست و خلق حمیده دارد و این مطلع از اوست :<br>افتاده ام به کویش از آب دیده در گل <br>دستی نهاده بر دست، دستی نهاده بر دل .<br><font color=\"Red\">(از مجالس النفائس ص <span class=\"hlight\" dir=\"rtl\">٣٠٣</span> از ترجمه ٔ فارسی ).</font><br></font></div>'),
(268231, 'همایون', '<span class=\"hlight\">همایون .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان زنجان که <span class=\"hlight\" dir=\"rtl\">٥٣١</span> تن سکنه دارد. آب آن از قنات و چشمه و محصول عمده اش غله و سیب زمینی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(268232, 'همایون', '<span class=\"hlight\">همایون .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از بخش پیرتاج شهرستان بیجار که <span class=\"hlight\" dir=\"rtl\">٣٨٠</span> تن سکنه دارد. آب آن از چشمه و قنات و محصولش غله، لبنیات و انگور است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268233, 'همایون', '<span class=\"hlight\">همایون .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از بخش درمیان شهرستان بیرجند که <span class=\"hlight\" dir=\"rtl\">٣٢</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268234, 'همایون آثار', '<span class=\"hlight\">همایون آثار.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ص مرکب ) آنکه دارای صفات مبارک و فرخنده یا آثار و کارهای مبارک و سودمند باشد <span class=\"hlight\">:</span> <br>آخر ای خاتم جمشید همایون آثار<br>گر فتد عکس تو بر لعل نگینم چه شود؟<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(268235, 'همایون اسفراینی', '<span class=\"hlight\">همایون اسفراینی .</span> <font color=\"DarkGreen\"><b>[ هَُ ن ِ اِ ف َ ی ِ ]</font></b> (اِخ ) از مردم اسفراین بوده و طبع شعری داشته و ظاهراً منحرف و دیوانه مزاج بوده است . رجوع به مجمعالفصحاء چ سنگی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٥</span> و نیز رجوع به مجالس النفائس ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span> از ترجمه ٔ فارسی شود.<br></font></div>'),
(268236, 'همایون بال', '<span class=\"hlight\">همایون بال .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ص مرکب ) مبارک . مرغی که پرواز او خجسته و مبارک است <span class=\"hlight\">:</span> همای همایون بال جاه و جلال ... (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(268237, 'همایون بخت', '<span class=\"hlight\">همایون بخت .</span> <font color=\"DarkGreen\"><b>[ هَُ یوم ْ ب َ ]</font></b> (ص مرکب ) خوش بخت . خجسته بخت . کامیاب . موفق <span class=\"hlight\">:</span> <br>از سر طالع همایون بخت <br>رفت سلطان مشرقی بر تخت .<br> <font color=\"Red\">نظامی .</font><br>آمد آن بانوی همایون بخت <br>چوعروسان نشست بر سر تخت .<br> <font color=\"Red\">نظامی .</font><br>من اول بس همایون بخت بودم <br>که هم باتاج و هم باتخت بودم .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268238, 'همایون رای', '<span class=\"hlight\">همایون رای .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ص مرکب ) دارای رای نیک و اندیشه ٔ بلند. نیک اندیش <span class=\"hlight\">:</span> <br>پاسخش داد کای همایون رای <br>نیک مردی ز بندگان خدای ...<br> <font color=\"Red\">نظامی .</font><br>دختر قیصر همایون رای <br>هم همایون و هم به نام همای .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268239, 'همایون سریرت', '<span class=\"hlight\">همایون سریرت .</span> <font color=\"DarkGreen\"><b>[ هَُ س َری رَ ]</font></b> (ص مرکب ) دارای درون همایون . دارای سعه ٔ صدر. بزرگ اندیشه . بلندنظر <span class=\"hlight\">:</span> اگر در محامد اخلاق و مآثر اعراق این پادشاه میمون سیرت و همایون سریرت خوض افتد، ابتدا به انتهای آن نرسد. (سندبادنامه ).<br></font></div>'),
(268240, 'همایون شکار', '<span class=\"hlight\">همایون شکار.</span> <font color=\"DarkGreen\"><b>[ هَُ ش ِ ]</font></b> (ص مرکب ) صیادی که هر صید را شکار نکند و شکار گران و باشکوه گیرد <span class=\"hlight\">:</span> <br>امروز طبع در پی فکر بلند نیست <br>شهباز ما همیشه همایون شکار بود.<br><font color=\"Red\">شیخ العارفین (از آنندراج ).</font><br></font></div>'),
(268241, 'همایون فر', '<span class=\"hlight\">همایون فر.</span> <font color=\"DarkGreen\"><b>[ هَُ ف َ ]</font></b> (ص مرکب ) دارای فرّ و شکوه . باشکوه <span class=\"hlight\">:</span> <br>هم موفق پادشاهی هم مظفر شهریار<br>هم مؤیدرای میری، هم همایون فر همام .<br> <font color=\"Red\">فرخی .</font><br>عید همایون فر نگر سیمرغ زرین پر نگر<br>ابروی زال زر نگر، بر فرق کهسار آمده .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(268242, 'همایون فریدنی', '<span class=\"hlight\">همایون فریدنی .</span> <font color=\"DarkGreen\"><b>[ هَُ ن ِ ف ِ دَ]</font></b> (اِخ ) از اولاد شیخ علی عبدالعال عرب معاصر صفویه و خود نیز موسوم به عبدالعال بوده است . مردی یاوه گوی و هزال بوده و به تحریک بزرگانی که وی آنها را هجا می گفته در خوابگاه خود به قتل رسیده است . او راست :<br>ماه صیام است گاه ترک مدام است <br>ترک مدام ازبرای ماه صیام است <br>ساقی دوران شکسته ساغر مینا<br>بر افق اینک نگون شکسته ٔ جام است <br>پیر مغان، آنکه گفت باده حلال است <br>میکده را در ببست و گفت حرام است .<br><font color=\"Red\">(از مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٧١</span>).</font><br></font></div>'),
(268243, 'همایون میرزا', '<span class=\"hlight\">همایون میرزا.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) رجوع به همایونشاه شود.<br></font></div>'),
(268244, 'همایون ناصرالدین', '<span class=\"hlight\">همایون ناصرالدین .</span><font color=\"DarkGreen\"><b>[ هَُ ص ِ رُدْ دی ]</font></b> (اِخ ) رجوع به همایونشاه شود.<br></font></div>'),
(268245, 'همایون نظر', '<span class=\"hlight\">همایون نظر.</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ظَ ]</font></b> (ص مرکب ) دارای نظر مبارک و خجسته، یا بلندنظر. آنکه از منظری بلند، نظر افکند <span class=\"hlight\">:</span> <br>الا ای همای همایون نظر<br>خجسته سروش مبارک خبر.<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(268246, 'همایون وند', '<span class=\"hlight\">همایون وند.</span> <font color=\"DarkGreen\"><b>[ هَُ وَ ]</font></b> (اِخ ) ایل کرد از طوایف پشتکوه . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٧٠</span>).<br></font></div>'),
(268247, 'همایون پی', '<span class=\"hlight\">همایون پی .</span> <font color=\"DarkGreen\"><b>[ هَُ یوم ْ پ َ <span class=\"hlight\" dir=\"rtl\">/</span> پ ِ ]</font></b> (ص مرکب ) فرخنده پی . فرخ پی . خجسته پی . مبارک قدم <span class=\"hlight\">:</span> <br>دیدن ماه نو و عید بدو فرخ باد<br>که همایون پی و فرخ رخ و فرخنده لقاست .<br><font color=\"Red\">فرخی .</font><br></font></div>'),
(268248, 'همایون پیکر', '<span class=\"hlight\">همایون پیکر.</span> <font color=\"DarkGreen\"><b>[ هَُ یوم ْ پ َ <span class=\"hlight\" dir=\"rtl\">/</span> پ ِ ک َ ]</font></b> (ص مرکب ) دارای پیکر زیبا و باشکوه . خوش اندام <span class=\"hlight\">:</span> <br>همایون پیکری نغز و خردمند<br>فرستاده به من دارای دربند.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268249, 'همایون چهر', '<span class=\"hlight\">همایون چهر.</span> <font color=\"DarkGreen\"><b>[ هَُ چ ِ ]</font></b> (ص مرکب ) خوش روی . خوش سیما. زیبا <span class=\"hlight\">:</span> <br>تا شبی خلوت آن همایون چهر<br>فرصتی یافت، با شه از سر مهر...<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268250, 'همایون کردن', '<span class=\"hlight\">همایون کردن .</span> <font color=\"DarkGreen\"><b>[ هَُ ک َ دَ ]</font></b> (مص مرکب ) مبارکباد دادن .(آنندراج از غوامض سخن ). رجوع به همایون کنان شود.<br></font></div>'),
(268251, 'همایون کش', '<span class=\"hlight\">همایون کش .</span> <font color=\"DarkGreen\"><b>[ هَُ ک ُ ]</font></b> (اِخ ) دهی است از بخش کنگاور شهرستان کرمانشاهان که <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه دارد. آب آن از چشمه و محصول عمده اش غله است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268252, 'همایون کن', '<span class=\"hlight\">همایون کن .</span> <font color=\"DarkGreen\"><b>[ هَُ ک ُ ]</font></b> (نف مرکب ) آنکه سبب شکوه و فرّ چیزی باشد <span class=\"hlight\">:</span> <br>همایون کن تاج و گاه و سریر<br>فرودآمد از تاجگاه سریر.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268253, 'همایون کنان', '<span class=\"hlight\">همایون کنان .</span> <font color=\"DarkGreen\"><b>[ هَُ ک ُ ]</font></b> (نف مرکب، ق مرکب ) در حال مبارک باد گفتن <span class=\"hlight\">:</span> <br>رسولان رسیدند با ساو و باج <br>همایون کنان شاه را تخت و تاج .<br> <font color=\"Red\">نظامی .</font><br>رجوع به همایون کردن شود.<br></font></div>'),
(268254, 'همایون گاه', '<span class=\"hlight\">همایون گاه .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِ مرکب ) دارالملک . پای تخت شاهان . (برهان ).<br></font></div>'),
(268255, 'همایونشاه', '<span class=\"hlight\">همایونشاه .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) یکی از شاهان بابری (تیموریان هند) است . وی معاصر شاه تهماسب صفوی بوده است . (از تاریخ ادبی ایران تألیف براون ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٥</span> و <span class=\"hlight\" dir=\"rtl\">٤٦٤</span> از ترجمه ٔ فارسی ).وی فرزند ظهیرالدین بابر و پشت ششم تیمور گورکانی است . تسلط او بر دهلی و هندوستان از سال <span class=\"hlight\" dir=\"rtl\">٩٣٢</span> هَ . ق . آغاز شده است . وی در <span class=\"hlight\" dir=\"rtl\">٩٣٨</span> کالنجر و در <span class=\"hlight\" dir=\"rtl\">٩٤٥</span> قندهار را تصرف کرد. صاحب مجمعالفصحا در باب اول کتاب خود وی را در شمار شاهان اهل شعر و سخن نام برده و نقل کرده است که پس از آنکه وی بکمک شاه تهماسب صفوی بر یاغیان دیار خود چیره شد این قطعه را برای تهماسب ساخت :<br>دشمنم شیر است و عمری پشت بر من کرده است <br>حالیا از روی خصمی روی بر من کرده است <br>خسروا عمری است تا عنقای عالی همتم <br>قله ٔ قاف قناعت را نشیمن کرده است <br>روزگار سفله ٔ گندم نمای جوفروش <br>طوطی طبع مرا قانع به ارزن کرده است <br>دارم اکنون التماس از شه که تا با من کند<br>آنچه با سلمان علی در دشت ارژن کرده است .<br>و گویا در همان هنگام نیز برای خوش آمد شاه صفی این رباعی را ساخته است :<br>گشتیم به جان بنده ٔ اولاد علی <br>هستیم همیشه شاد با یاد علی <br>چون سرّ ولایت از علی ظاهر شد<br>کردیم همیشه ورد خود نادعلی .<br>رجوع به مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢</span> و نیز رجوع به تاریخ ادبیات براون ج <span class=\"hlight\" dir=\"rtl\">٤</span> ترجمه ٔ رشید یاسمی شود.<br></font></div>'),
(268256, 'همایونک افشاری', '<span class=\"hlight\">همایونک افشاری .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ک ِ اَ ]</font></b> (اِخ ) از توابع قزوین و دارای معدن زغال سنگ و مس است . (یادداشت مؤلف ).<br></font></div>'),
(268257, 'همایونی', '<span class=\"hlight\">همایونی .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ص نسبی ) بلندمرتبه . والامقام . عالی . <BR><font color=\"Blue\">◄</font> از القاب خاص شاه در سلسله ٔ پهلوی .<br></font></div>'),
(268258, 'همایی', '<span class=\"hlight\">همایی .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ص نسبی ) منسوب به همای . بلندپایه . همایون . همایونی . <BR><font color=\"Blue\">◄</font> (حامص ) همای بودن . بلندپروازی . آزادی و آزادگی <span class=\"hlight\">:</span> <br>جغد به دور تو همایی کند<br>سر که رسد پیش تو پایی کند.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268259, 'همایی', '<span class=\"hlight\">همایی .</span> <font color=\"DarkGreen\"><b>[هَُ ]</font></b> (اِخ ) دهی است از بخش کدکن شهرستان تربت حیدریه که <span class=\"hlight\" dir=\"rtl\">١٧٥</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و پنبه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268260, 'همایی', '<span class=\"hlight\">همایی .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) معلوم نیست که مولدش کجاست . اکثر عمر خود را در عراق گذراند. یک بار به خراسان سفر کرد. مردی کم سخن بود و این مطلع از اوست :<br>جانا منم ز دست فراق تو مرده ای <br>خون در تنم نمانده چو نار فشرده ای .<br>(از مجالس النفائس امیر علیشیر نوایی ص <span class=\"hlight\" dir=\"rtl\">١٢٠</span> از ترجمه ٔ فارسی ).<br>وی از معاصران نوایی و از شعرای قرن نهم هجری بوده است .<br></font></div>'),
(268261, 'همایی', '<span class=\"hlight\">همایی .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از بخش الیگودرز شهرستان بروجرد که <span class=\"hlight\" dir=\"rtl\">١١٥</span> تن سکنه دارد. آب آن از قنات و چاه و محصول عمده اش غله و لبنیات و پنبه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268262, 'همایی', '<span class=\"hlight\">همایی .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) نام یکی از دهستانهای بخش ششتمد شهرستان سبزوار که تابستانی گرم و آبهایی تلخ و شور دارد. به علت دوری از مرکز شهر اغلب کمینگاه سارقان است . آبادیها در میان تپه ماهورها واقع شده است . تعداد قراء آن <span class=\"hlight\" dir=\"rtl\">٢٣</span> و سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٨٩٥٠</span> تن است . زراعت قابل ملاحظه ندارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268263, 'همایی', '<span class=\"hlight\">همایی .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) ده مرکزی دهستان همایی بخش ششتمد شهرستان سبزوار دارای <span class=\"hlight\" dir=\"rtl\">٣٥٧</span> تن سکنه . محصول عمده اش پنبه و زیره است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268264, 'همایی', '<span class=\"hlight\">همایی .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ )ده کوچکی است از بخش بروجن شهرستان شهرکرد که دارای <span class=\"hlight\" dir=\"rtl\">٢٩</span> تن سکنه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268265, 'همایین', '<span class=\"hlight\">همایین .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) ج ِ همیان . (منتهی الارب ). رجوع به همیان شود.<br></font></div>'),
(268266, 'همباز', '<span class=\"hlight\">همباز.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم باز. شریک . همتا. انباز. حریف .نظیر. مانند. همانند. (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>خروشان از آن جایگه بازگشت <br>تو گفتی که با باد همباز گشت .<br> <font color=\"Red\">فردوسی .</font><br>ز توران سزاوار و همباز تو<br>نیابم کسی نیز دمساز تو.<br> <font color=\"Red\">فردوسی .</font><br>چو کسری بیامد برِ تخت خویش <br>گرازان و همباز با بخت خویش .<br> <font color=\"Red\">فردوسی .</font><br>بنده را بواحمد خلیل گویند پدر بومطیع که همباز ملک است . (تاریخ بیهقی ). ای امیرالمؤمنین از خدای عزوجل بترس که یکی است و همباز ندارد.(تاریخ بیهقی ).<br>بلندیش با چرخ همباز بود<br>سطبریش بیش از چهل باز بود.<br><font color=\"Red\">اسدی .</font><br>ابوالحسن و ابونصر هر دو همباز بودنددر قضاء پارس . (ابن بلخی ). وزیر مانند همباز ملک است و در پادشاهی و مال و مملکت او متصرف . (ابن بلخی ).<br></font></div>'),
(268267, 'همبازی', '<span class=\"hlight\">همبازی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) شریک بودن . همباز بودن . انبازی . شرکت . رجوع به همباز شود.<br></font></div>'),
(268268, 'همبان آباد', '<span class=\"hlight\">همبان آباد.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ )دهی است از بخش سلماس شهرستان خوی که <span class=\"hlight\" dir=\"rtl\">٦١٠</span> تن سکنه دارد. آب آن از چشمه و محصول عمده اش غله و کاردستی مردم جاجیم بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268269, 'همبر', '<span class=\"hlight\">همبر.</span> <font color=\"DarkGreen\"><b>[ هَُ ب َ ]</font></b> (اِخ ) دهی است از دهستان بالای شهرستان اردستان که <span class=\"hlight\" dir=\"rtl\">١٤٥</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و خشکبار است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268270, 'همبر', '<span class=\"hlight\">همبر.</span> <font color=\"DarkGreen\"><b>[ هََ ب َ ]</font></b> (ص مرکب ) هم بر. همراه و قرین و نظیر. (برهان ). برابر <span class=\"hlight\">:</span> <br>بدو داد یک دست از آن لشکرش <br>که شیر ژیان نامدی همبرش .<br> <font color=\"Red\">دقیقی .</font><br>چو سروی که با ماه همبر بود<br>بر آن مه بر از مشک افسر بود.<br> <font color=\"Red\">فردوسی .</font><br>یکی از شما سوی لشکر شوید<br>بکوشید و با باد همبر شوید.<br> <font color=\"Red\">فردوسی .</font><br>به شادی به روئین دژ اندر شویم <br>نشینیم و با ماه همبر شویم .<br> <font color=\"Red\">فردوسی .</font><br>تا وزارت را بدو شاه زمانه بازخواند<br>زو وزارت با نبوت هر زمان همبر شود.<br> <font color=\"Red\">فرخی .</font><br>خم چوگان به گوی برزد و شد<br>گوی او با ستارگان همبر.<br> <font color=\"Red\">فرخی .</font><br>دولتی دارد چندان که براندیشد دل <br>دولت عالی با همت عالی همبر.<br> <font color=\"Red\">فرخی .</font><br>گر شکر خوردی پریر و دی یکی نان جوین <br>همبر است امروز ناچار این جوین با آن شکر.<br> <font color=\"Red\">ناصرخسرو.</font><br>هرچند که بر منبر نادان بنشیند<br>هرگز نشود همبر با دانا نادان .<br> <font color=\"Red\">ناصرخسرو.</font><br>سر هفته برداشت و جایی رسید<br>کهی چند را همبر مه بدید.<br> <font color=\"Red\">اسدی .</font><br> <BR><font color=\"Blue\">◄</font> همسر. همدم <span class=\"hlight\">:</span> <br>نگارا تا تو بودی همبر من <br>ز نوشین خواب بودی بستر من .<br> <font color=\"Red\">فخرالدین اسعد.</font><br> <BR><font color=\"Blue\">◄</font> روبه رو <span class=\"hlight\">:</span> <br>نهاده زهر برِ نوش و خار همبر گل <br>چنانکه باشد جیلانش از برِ عناب .<br> <font color=\"Red\">بوطاهر.</font><br>فاختگان همبر بنشاستند<br>نای زنان بر سر شاخ چنار.<br> <font color=\"Red\">منوچهری .</font><br> <BR><font color=\"Blue\">◄</font> با هم . همراه <span class=\"hlight\">:</span> <br>بدی و بهی نیش و نوش است همبر<br>تو بردار از آن نوش و از نیش بگذر.<br> <font color=\"Red\">ناصرخسرو.</font><br>سپارم به تو گنج و هم دخترم <br>بر اورنگ بنشانمت همبرم .<br> <font color=\"Red\">اسدی .</font><br>بزرگی که با آسمان همبر است <br>ز تخم براهیم پیغمبر است .<br> <font color=\"Red\">اسدی .</font><br>دری بست و دری هم زود بگشاد<br>چراغی برد و شمعی باز بنهاد.<br> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>).</font><br>بوده با ایوب همسر در گه صبر و شکیب <br>گشته با جبریل همبر در گه خوف و رجا.<br> <font color=\"Red\">مسعودسعد.</font><br>ماه نو دیدی ؟ لبت بین، رشته ٔ جانم نگر<br>کاین سه را از بس که باریکند همبر ساختند.<br> <font color=\"Red\">خاقانی .</font><br>زخم که جانان زند همسر مرهم شناس <br>زهر که سلطان دهد همبر تریاق نه .<br> <font color=\"Red\">خاقانی .</font><br>علم دین، علم کفر مشمارید<br>هرمان  همبر طلل منهید.<br> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span>).</font><br>ترکیب ها:<br>- <span class=\"hlight\">همبر آمدن </span> . همبری . رجوع به این دو مدخل ها شود.<br></font></div>'),
(268271, 'همبر آمدن', '<span class=\"hlight\">همبر آمدن .</span> <font color=\"DarkGreen\"><b>[ هََ ب َ م َ دَ ]</font></b> (مص مرکب ) برابر شدن . (آنندراج ) <span class=\"hlight\">:</span> <br>با سیاهی سنگ کعبه همبر آمد از شرف <br>سرخی سنگ منا کز خون حیوان دیده اند.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(268272, 'همبری', '<span class=\"hlight\">همبری .</span> <font color=\"DarkGreen\"><b>[ هََ ب َ ]</font></b> (حامص مرکب ) هم بری . مطابقت . برابری . همسری . هم طرازی <span class=\"hlight\">:</span> <br>شیر بیابان را با مرد جنگ <br>همسری و همبری و شرکت است .<br> <font color=\"Red\">ناصرخسرو.</font><br>رجوع به همبر شود.<br></font></div>'),
(268273, 'همبستگی', '<span class=\"hlight\">همبستگی .</span> <font color=\"DarkGreen\"><b>[ هََ ب َ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) هم بستگی . بستگی . پیوند. اتصال و ارتباط بین دو چیز یا دو تن .<br></font></div>'),
(268274, 'همبه', '<span class=\"hlight\">همبه .</span> <font color=\"DarkGreen\"><b>[ هَُ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ) در تداول، شکم یا هر چیز برجسته و پیش آمده : همبه اش بالا آمده ؛ آبستن است . (یادداشت مؤلف ).<br></font></div>'),
(268275, 'همبوی', '<span class=\"hlight\">همبوی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) زنی که در زمان ضحاک برادر خود را از بند ضحاک نجات داد. (برهان ).<br></font></div>'),
(268276, 'همة', '<span class=\"hlight\">همة.</span> <font color=\"DarkGreen\"><b>[ هََ م ْم َ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ م ْ م َ ]</font></b> (ع اِ) کاری که قصد کردن آن نمایند. <BR><font color=\"Blue\">◄</font> قصد. (منتهی الارب ) (اقرب الموارد). ج، هِمَم . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> هوی . ج، همم . (اقرب الموارد). خواهش . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پیر فانی . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> زن پیر فانی . (اقرب الموارد). گنده پیر. (منتهی الارب ). ج، همات، همائم . (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(268277, 'همت', '<span class=\"hlight\">همت .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش داراب شهرستان فسا که <span class=\"hlight\" dir=\"rtl\">٦٥</span> تن سکنه دارد. آب آن از چشمه و محصول عمده اش غله و توتون و کاردستی مردم قالی بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(268278, 'همت', '<span class=\"hlight\">همت .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) تخلص برادر وصال شیرازی است . (از تاریخ ادبی براون ج <span class=\"hlight\" dir=\"rtl\">٤</span> ترجمه ٔ رشید یاسمی ص <span class=\"hlight\" dir=\"rtl\">١٩٤</span>).<br></font></div>'),
(268279, 'همت', '<span class=\"hlight\">همت .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) در روغن نهان شدن . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268280, 'همت', '<span class=\"hlight\">همت .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (ع اِمص، اِ) همة. اراده و آرزو و خواهش و عزم . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>همت او بر فلک ز فلخ بنا کرد<br>بر سر ایوان فکند بن پی ایوان .<br> <font color=\"Red\">خسروانی .</font><br>منوچهر کردی بدین پیش دست <br>نکردی بدین همت خویش پست .<br> <font color=\"Red\">فردوسی .</font><br>که باران وی در بهاران بود<br>نه چون همت شهریاران بود.<br> <font color=\"Red\">فردوسی .</font><br>همت های فلکی بینمش <br>سیرتهای ملکی بینمش .<br> <font color=\"Red\">منوچهری .</font><br>همه به کردن خیر است مر ورا همت <br>همه به دادن مال است مر ورا وسواس .<br> <font color=\"Red\">منوچهری .</font><br>در سرش همت ملک نیست . (تاریخ بیهقی ). از بزرگی همت و سماحت اخلاق وی سزد. (تاریخ بیهقی ).<br>تو را که همت دانستن خدای بود<br>مشو مخالف قول محمد مختار.<br> <font color=\"Red\">ناصرخسرو.</font><br>شاید که همتم نبود صحبت جهان <br>چون نیست جز که مالش من هیچ همتش .<br> <font color=\"Red\">ناصرخسرو.</font><br>وگرنه مزد طاعت نیست همت <br>به مزدش هر کسی باید رسیدن .<br> <font color=\"Red\">ناصرخسرو.</font><br>مرد همت نه مرد تهمت باش <br>چون پیمبر نه ای، ز امت باش .<br> <font color=\"Red\">سنائی .</font><br>همت او را ورای جزء و کل است <br>که همه آبها به زیر پل است .<br> <font color=\"Red\">سنائی .</font><br>همت برفراغ شیر مقصور گردانیدم . (کلیله و دمنه ). هرکه همت او از دنیا قاصر باشد حسرت او به وقت مفارقت اندک بود. (کلیله و دمنه ). همت بر اکتساب ثواب آخرت مقصور گردان . (کلیله و دمنه ).<br>هر کجا گشت همتی مبذول <br>بی گمان لعنتی شود پیدا.<br> <font color=\"Red\">ادیب صابر.</font><br>خاقانیا ز جیب تجرد برآر سر<br>وز روزگار دامن همت فروفشان .<br> <font color=\"Red\">خاقانی .</font><br>من همه همت بر اسباب سفر دارم مرا<br>در حضر ساز مهیا برنتابد بیش از این .<br> <font color=\"Red\">خاقانی .</font><br>دامن جمع آورید و همت برگمارید. (ترجمه ٔ تاریخ یمینی ). همه اثر برکت همت و نتیجه ٔ هیبت سلطان بود. (ترجمه ٔ تاریخ یمینی ).<br>ساخت از او همت قارون کلاه <br>از سر آن رخنه فروشُد به چاه .<br> <font color=\"Red\">نظامی .</font><br>اوج بلند است در او می پرم <br>باشد کز همت خود برخورم .<br> <font color=\"Red\">نظامی .</font><br>هرکه را یک ذره همت داد دست <br>کرد اوخورشید را زآن ذره پست .<br> <font color=\"Red\">عطار.</font><br>قدر همت باشد آن جهد دعا<br>لیس للانسان الا ما سعی .<br> <font color=\"Red\">مولوی .</font><br>چو همت است چه حاجت به گرز مغفرکوب <br>چو دولت است چه حاجت به تیر جوشن خای ؟<br> <font color=\"Red\">سعدی .</font><br>به همت مدد کن که شمشیر و تیر<br>نه در هر وغایی بود دستگیر.<br> <font color=\"Red\">سعدی .</font><br>به همت برآر از ستیزنده شور<br>که بازوی همت به از دست زور.<br> <font color=\"Red\">سعدی .</font><br>همت عالی ز فلک بگذرد<br>مرد به همت ز ملک بگذرد.<br> <font color=\"Red\">خواجو.</font><br>همت اگر سلسله جنبان شود<br>مور تواند که سلیمان شود.<br> <font color=\"Red\">وحشی .</font><br>همت بلند دار که با همت بلند<br>هر جا روی به توسن گردون سواره ای .<br> <font color=\"Red\">صائب .</font><br> <BR><font color=\"Blue\">◄</font> شجاعت ودلیری . <BR><font color=\"Blue\">◄</font> زور و قوت و نیرو و طاقت . (ناظم الاطباء). رجوع به همة شود. <BR><font color=\"Blue\">◄</font> فال نیک . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> وسعت نظر. بلندنظری . بلندطبعی <span class=\"hlight\">:</span> <br>آدم برای گندمی از روضه دور ماند<br>من دور ماندم از در همت برای نان .<br> <font color=\"Red\">خاقانی .</font><br>کاری نه به قدر همت افتاد<br>راهی نه به پای مرکب آمد.<br> <font color=\"Red\">خاقانی .</font><br>مرا همت چو خورشید است شاهنشاه زنداستا<br>که چرخش زیر ران است و سر عیسی است بر رانش .<br> <font color=\"Red\">خاقانی .</font><br>مرکب همت به تاز یک ره و بیرون جهان <br>از سر طاق فلک تا به حد استوا.<br> <font color=\"Red\">خاقانی .</font><br>همت خاصان و دل عامیان <br>شیفته زآن نور چو سرسامیان .<br> <font color=\"Red\">نظامی .</font><br>همت مسکینان و ضعیفان زخم زیادت تر زند و سخت تر که بازوی پهلوانان . (مجالس سعدی ). از آنجا که همت درویشان است و صدق معاملت ایشان ... (گلستان ).<br>اهل همت را ز ناهمواری گردون چه باک <br>سیر انجم را چه غم کاندر زمین چون و چراست ؟<br> <font color=\"Red\">میر علیشیر نوائی .</font><br>همت آن است کز آواره ٔ احسان گذرد<br>هرکه این بادیه را طی نکند حاتم نیست .<br> <font color=\"Red\">صائب .</font><br>- <span class=\"hlight\">توانگرهمت </span> ؛ آنکه همتش قوی باشد. که نفس گرم و مؤثر دارد <span class=\"hlight\">:</span> مقربان درگاه حق سبحانه و تعالی توانگرانند درویش سیرت و درویشانند توانگرهمت . (گلستان ).<br>- <span class=\"hlight\">دون همت </span> ؛ دارای طبع پست .کوتاه اندیشه <span class=\"hlight\">:</span> <br>چو خرمن برگرفتی گاو مفروش <br>که دون همت کند نعمت فراموش .<br> <font color=\"Red\">سعدی .</font><br>کرم ورزد آن سر که مغزی در اوست <br>که دون همتانند بی مغزوپوست .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">ضعیف همت </span> ؛ کوتاه نظر <span class=\"hlight\">:</span> <br>به در خدای قربی طلب ای ضعیف همت <br>که نماند این تقرب که به پادشاه داری .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">عالی همت </span> ؛ بلندنظر. دارای طبع بلند <span class=\"hlight\">:</span> <br>گراز شمشیر برگردی نه عالی همتی سعدی <br>تو کز نیشی بیازردی نخواهی انگبین رفتن .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">قاصرهمت </span> ؛ کوتاه همت . دون همت . نظرپست <span class=\"hlight\">:</span> طایفه ای هستند بر این صفت که بیان کردی، قاصرهمت و کافرنعمت . (گلستان ).<br>- <span class=\"hlight\">ناچیزهمت </span> ؛ قاصرهمت . دون همت <span class=\"hlight\">:</span> <br>کنون پنداری ای ناچیزهمت <br>که روزی خواهدت کردن فراموش ؟<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> (اصطلاح تصوف ) عبارت است از توجه قلب با تمام قوای روحانی خود به جانب حق، برای حصول کمال در خود یا دیگری، به نحوی که به غیر مقصود حقیقی ملتفت نشود... (از فرهنگ مصطلحات عرفا تألیف جعفر سجادی ). توجه پیر برای امر وجودی یا عدمی . نفس پیر. درویشان امروز به جای همت کردن، نفس کردن میگویند. (یادداشت مؤلف ). نفوذ ناپیدای شیخ در مریدان <span class=\"hlight\">:</span> اهل صلاح دستها به دعا برداشتند و همت برگماشتند. (ترجمه ٔ تاریخ یمینی ).<br>همت از آنجا که نظر کرده بود<br>گفت جوانی که در آن پرده بود.<br> <font color=\"Red\">نظامی .</font><br>بهر آسایش سخن کوتاه کن <br>در عوضْمان همتی همراه کن .<br> <font color=\"Red\">مولوی .</font><br>هم شدی توزیع کودک دانگ چند<br>همت شیخ آن سخا را کرد بند.<br> <font color=\"Red\">مولوی .</font><br>همت از صاحبدلی کن التماس <br>پس به صاحب دولتی کن التجا.<br> <font color=\"Red\">سلمان ساوجی .</font><br>دریا و کوه در ره و من خسته و ضعیف <br>ای خضر پی خجسته مدد کن به همتم .<br> <font color=\"Red\">حافظ.</font><br>همتم بدرقه ٔ راه کن ای طایر قدس <br>که دراز است ره مقصد و من نوسفرم .<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">همت خواستن </span> ؛ مدد خواستن از روح پیر یا مرشد برای سوق به سوی کمال . رجوع به همت خواستن شود.<br></font></div>'),
(268281, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش کهنوج شهرستان جیرفت که <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و خرماست . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268282, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش شهداد شهرستان کرمان که <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله، خرما و حبوب است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268283, 'همت آباد', '<span class=\"hlight\">همت آباد.</span><font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش فهرج شهرستان بم که <span class=\"hlight\" dir=\"rtl\">٢٤٩</span> تن سکنه دارد. آب آن از قنات و محصول آن غله، خرما و حناست . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(268284, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ باختری شهرستان رفسنجان که <span class=\"hlight\" dir=\"rtl\">٢٤١</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله، پسته و پنبه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268285, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان آباده که <span class=\"hlight\" dir=\"rtl\">٩٥</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش لبنیات، غله، خربزه، انگور و کاردستی مردم بافتن گیوه و قالی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(268286, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش دلفان شهرستان خرم آباد که <span class=\"hlight\" dir=\"rtl\">٩٠</span>تن سکنه دارد. آب آن از چشمه و محصول عمده اش غله و لبنیات و پشم است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268287, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهستانی است از بخش حومه ٔ شهرستان بروجرد که دارای هوای معتدل و شامل <span class=\"hlight\" dir=\"rtl\">٢٦</span> آبادی است و روی هم <span class=\"hlight\" dir=\"rtl\">٥٣٠٠</span> تن سکنه دارد. آب آن از قنوات تأمین میشود و مهمترین قراء آن دو قریه ٔ جهان آباد و طبریجان است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268288, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان بروجرد و مرکز دهستان همت آباد که <span class=\"hlight\" dir=\"rtl\">١٤٥</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله، لبنیات و چغندر، و هنر دستی مردم قالی بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268289, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b>(اِخ ) دهی است از بخش صحنه ٔ شهرستان کرمانشاهان که <span class=\"hlight\" dir=\"rtl\">١٤٧</span> تن سکنه دارد. آب آن از چشمه و محصول عمده اش غله ٔ دیمی و چوب است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268290, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان آمل که <span class=\"hlight\" dir=\"rtl\">٨٥</span> تن سکنه دارد. آب آن از رودخانه ٔ هراز و محصول عمده اش غله، حبوب، کنف و پنبه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(268291, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان ساری که <span class=\"hlight\" dir=\"rtl\">٥٧٠</span> تن سکنه دارد. آب آن از رود تجن و محصول عمده اش برنج، غله، پنبه و صیفی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(268292, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان قزوین که <span class=\"hlight\" dir=\"rtl\">١٢٧</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و عدس، و کاردستی مردم بافتن جاجیم، گلیم و جوراب است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(268293, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ )دهی است از بخش ساوجبلاغ شهرستان کرج که <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله، بنشن، چغندرقند و صیفی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(268294, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b>(اِخ ) دهی است از بخش ورامین شهرستان تهران که <span class=\"hlight\" dir=\"rtl\">٩٥</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله، صیفی و چغندرقند است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(268295, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) ده کوچکی است از دهستان قهاب از بخش حومه ٔ شهرستان اصفهان که دارای <span class=\"hlight\" dir=\"rtl\">٣٦</span> تن سکنه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268296, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان تربت حیدریه که <span class=\"hlight\" dir=\"rtl\">١٥٣</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و کاردستی مردم کرباس بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268297, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش خاش شهرستان زاهدان که <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و لبنیات است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268298, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش جغتای شهرستان سبزوار که <span class=\"hlight\" dir=\"rtl\">٤٤٦</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله، پنبه و زیره است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268299, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش طیبات شهرستان مشهد که <span class=\"hlight\" dir=\"rtl\">٨٥١</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و بنشن است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268300, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش گرمسیر شهرستان اردستان که <span class=\"hlight\" dir=\"rtl\">٧٢</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و انار است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268301, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از دهستان گنبگی از بخش فهرج شهرستان بم که دارای <span class=\"hlight\" dir=\"rtl\">١٥</span> تن سکنه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268302, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ]</font></b> (اِخ ) دهی است از دهستان نوق شهرستان رفسنجان که <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله، پسته و پنبه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268303, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش قاین شهرستان بیرجند که <span class=\"hlight\" dir=\"rtl\">١٣٨</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و لبنیات و کاردستی مردم قالی بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268304, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش نهارجانات شهرستان بیرجند. آب آن از قنات و محصول عمده اش غله، میوه و ابریشم است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268305, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْم َ ]</font></b> (اِخ ) دهی است از بخش فهرج شهرستان بم که دارای <span class=\"hlight\" dir=\"rtl\">٣٥</span> تن سکنه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268306, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش جنت آباد شهرستان مشهد که <span class=\"hlight\" dir=\"rtl\">٤٥٨</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و پنبه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268307, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش طبس شهرستان فردوس که <span class=\"hlight\" dir=\"rtl\">١٢٥</span>تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و گاورس و پنبه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268308, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش فیض آباد و محولات شهرستان تربت حیدریه که دارای <span class=\"hlight\" dir=\"rtl\">٤١٢</span> تن سکنه است . آب آن از قنات و محصول عمده اش غله و بنشن است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268309, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش طبس شهرستان فردوس . آب آن از قنات و محصول عمده اش غله است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268310, 'همت آباد', '<span class=\"hlight\">همت آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) دهی است از بخش اشکذر شهرستان یزد که <span class=\"hlight\" dir=\"rtl\">٦٧٠</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و کاردستی زنان کرباس بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268311, 'همت آباد بالا', '<span class=\"hlight\">همت آباد بالا.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ دِ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ خاوری شهرستان رفسنجان که <span class=\"hlight\" dir=\"rtl\">٢٦٦</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله، پسته، پنبه و لبنیات است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268312, 'همت آباد حومه', '<span class=\"hlight\">همت آباد حومه .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ دِ حُوم ِ ]</font></b> (اِخ ) دهی است از بخش زرند شهرستان کرمان که <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله، پسته و پنبه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268313, 'همت آباد خیرآباد', '<span class=\"hlight\">همت آباد خیرآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ دِخ ِ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان نائین که <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268314, 'همت آباد زمان آباد', '<span class=\"hlight\">همت آباد زمان آباد.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ دِ زَ ]</font></b> (اِخ ) دهی است از بخش فدیشه ٔ شهرستان نیشابور که <span class=\"hlight\" dir=\"rtl\">١٩٤</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و کاردستی مردم کرباس بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268315, 'همت آباد سلطان نصیر', '<span class=\"hlight\">همت آباد سلطان نصیر.</span><font color=\"DarkGreen\"><b>[ هَِ م ْ م َ دِ س ُ ن َ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان نائین . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268316, 'همت آباد شهرکهنه', '<span class=\"hlight\">همت آباد شهرکهنه .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ دِ ش َ رِ ک ُ ن ِ ]</font></b> (اِخ ) دهی است از دهستان فدیشه ٔ شهرستان نیشابور که <span class=\"hlight\" dir=\"rtl\">٣٤٨</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و کاردستی مردم کرباس بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268317, 'همت آباد شور', '<span class=\"hlight\">همت آباد شور.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ دِ ]</font></b> (اِخ ) نام دیگرش ده نو آصفی، و ده کوچکی است از بخش زرند شهرستان کرمان که دارای <span class=\"hlight\" dir=\"rtl\">٤</span> تن سکنه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268318, 'همت آباد میربیک', '<span class=\"hlight\">همت آباد میربیک .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ دِ ب ِ ]</font></b> (اِخ ) دهی است از بخش دلفان شهرستان خرم آباد که <span class=\"hlight\" dir=\"rtl\">٢٧٠</span> تن سکنه دارد. آب آن از چشمه ها و محصول عمده اش غله و پشم و کاردستی مردم بافتن سیاه چادر است . ساکنان از طایفه ٔ مال موله اند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268319, 'همت بستن', '<span class=\"hlight\">همت بستن .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ب َ ت َ ]</font></b> (مص مرکب ) ابراز بلندنظری <span class=\"hlight\">:</span> <br>کف نیاز به حق برگشای و همت بند<br>که دست فتنه ببندد خدای کارگشای .<br><font color=\"Red\">سعدی .</font><br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(268320, 'همت خواستن', '<span class=\"hlight\">همت خواستن .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ت َ ]</font></b> (مص مرکب ) یاری طلبیدن . دعای خیر و مدد و عطف توجه خواستن از مرشد و پیر برای کمال خود یا برای توفیق در کاری <span class=\"hlight\">:</span> به خدمت علما و صلحا و عبادقیام نماید و همت خواهد. (مجالس سعدی ). این بگفت و پدر را وداع کرد و همت خواست و روان شد. (گلستان ).<br>بر سر تربت ما چون گذری همت خواه <br>که زیارتگه رندان جهان خواهد بود.<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> نیرو و اراده خواستن . دیگران را وادار به کارهای بزرگ کردن <span class=\"hlight\">:</span> <br>به بازو توانا نباشد سپاه <br>برو همت از ناتوانان بخواه .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(268321, 'همت پرست', '<span class=\"hlight\">همت پرست .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ پ َ رَ ]</font></b> (نف مرکب ) باهمت . بلندهمت <span class=\"hlight\">:</span> <br>من غلام آن مس همت پرست <br>که به غیر از کیمیا نارد شکست .<br> <font color=\"Red\">مولوی .</font><br>رجوع به همت شود.<br></font></div>'),
(268322, 'همتا', '<span class=\"hlight\">همتا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) همتای . همزاد. همجنس . (برهان ). <BR><font color=\"Blue\">◄</font> نظیر و مانند. (برهان ). عدیل . همانند. قرین . شبیه . (یادداشتهای مؤلف ) <span class=\"hlight\">:</span> <br>شه نیمروز آنکه رستَمْش نام <br>سوار جهاندیده همتای سام .<br> <font color=\"Red\">فردوسی .</font><br>به پور گرامی سپرد آن سپاه <br>که فرزند او بود و همتای شاه .<br> <font color=\"Red\">فردوسی .</font><br>نیابم دگر نیز همتای او<br>به رفتار و زور و به بالای او.<br> <font color=\"Red\">فردوسی .</font><br>ایا شاهی که از شاهان نیامد کس تو را همسر<br>ایا میری که از میران نباشد کس تو را همتا.<br> <font color=\"Red\">فرخی .</font><br>برِ من بیهده تر زآن به جهان کس نبود<br>که خداوند مرا جوید همتای و قرین .<br> <font color=\"Red\">فرخی .</font><br>زهی خسروی کز همه ی ْ خسروان <br>به مردی تو را نیست همتا و یار.<br> <font color=\"Red\">فرخی .</font><br>خبر هرگز نه مانند عیان است <br>یقین دل نه همتای گمان است .<br> <font color=\"Red\">فخرالدین گرگانی .</font><br>خداوند بزرگ است و نیست او را همتا.(تاریخ بیهقی ). فلان خیلتاش را... که همتا نداشت بگوی تا ساخته آید. (تاریخ بیهقی ).<br>تأویلش از خزانه تو آن یابی <br>کز خلق نیست هیچ کسش همتا.<br> <font color=\"Red\">ناصرخسرو.</font><br>نشناخته مر خلق را، چه جویی <br>آن را که ندارد وزیر و همتا.<br> <font color=\"Red\">ناصرخسرو.</font><br>تا چنان گشتی که او را همتا نبود. (مجمل التواریخ و القصص ).<br>آبنوسم در بن دریا نشستم با صدف <br>خس نیَم تا بر سر آیم کف شود همتای من .<br> <font color=\"Red\">خاقانی .</font><br>عقل چه همتای توست کز تو زند لاف عشق <br>می نشناسد حریف، خیره سری می کند.<br> <font color=\"Red\">خاقانی .</font><br>ظل حق است اخستان همتاش مهدی چون نهی <br>ظل حق فرداست همتا برنتابد بیش از این .<br> <font color=\"Red\">خاقانی .</font><br>بکر معانیم که همتاش نیست <br>جامه به اندازه ٔ بالاش نیست .<br> <font color=\"Red\">نظامی .</font><br>گفت گفتم آن شکایتهای تو<br>با گروه طوطیان همتای تو.<br> <font color=\"Red\">مولوی .</font><br>پس تو همتای نقش دیواری <br>که همین چشم و گوش و لب داری .<br> <font color=\"Red\">سعدی .</font><br>دو صورت که گفتی یکی نیست بیش <br>نمودی در آیینه همتای خویش .<br> <font color=\"Red\">سعدی .</font><br>دیگری نیست که مهر تو در او شاید بست <br>هم در آیینه توان دید مگر همتایت .<br> <font color=\"Red\">سعدی .</font><br>ضرورت است بلا دیدن و جفا بردن <br>ز دست آنکه ندارد به حسن همتایی .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">بی همتا</span> ؛ بی مانند. بی نظیر <span class=\"hlight\">:</span> مردمان چنان دانند که میان من و آن مهتر بی همتا ناخوشی است . (تاریخ بیهقی ).<br>بی نظیری چو عقل بی همتا<br>ناگزیری چو جان ناگذران .<br> <font color=\"Red\">عطار.</font><br>- <span class=\"hlight\">نیست همتا</span> ؛ بی همتا<span class=\"hlight\">:</span> جالینوس ... نیست همتاتر آمد در علم طب و... نیز بی همتاتر بود در معالجت اخلاق . (تاریخ بیهقی ).<br> <BR><font color=\"Blue\">◄</font> متناسب . جور. هم آهنگ <span class=\"hlight\">:</span> <br>خانه ٔ خود بازرود هر یکی <br>اطلس کی باشد همتای برد؟<br> <font color=\"Red\">رودکی .</font><br>به ایران نه مردی به بالای او<br>نبینم همی اسب همتای او.<br> <font color=\"Red\">فردوسی .</font><br>کنیزی را که هم بالای او بود<br>به حسن و چابکی همتای او بود.<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> همنشین . دوست . مصاحب <span class=\"hlight\">:</span> <br>چون یار موافق نبود تنها بهتر<br>تنها به صد بار چو نادانت همتا.<br> <font color=\"Red\">ناصرخسرو.</font><br> <BR><font color=\"Blue\">◄</font> همسر. (برهان ). جفت . یار <span class=\"hlight\">:</span> <br>کدام آهو افکند خواهی به تیر<br>که ماده جوان است و همتاش پیر.<br> <font color=\"Red\">فردوسی .</font><br>بدو گفت سودابه همتای شاه <br>ندیدند بر گاه شاه و سپاه .<br> <font color=\"Red\">فردوسی .</font><br>یگانه گهر گرچه والا بود<br>نکوتر چو جفتیش همتا بود.<br> <font color=\"Red\">اسدی .</font><br>جهانجوی بر رسم آبای خویش <br>پریزاده را کرد همتای خویش .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268323, 'همتا شدن', '<span class=\"hlight\">همتا شدن .</span> <font color=\"DarkGreen\"><b>[ هََ ش ُدَ ]</font></b> (مص مرکب ) برابر شدن . همپایه شدن <span class=\"hlight\">:</span> <br>نفس مردم را خداوندان عقل از روی هوش <br>برکشد تا با کرام الکاتبین همتا شود.<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(268324, 'همتاب', '<span class=\"hlight\">همتاب .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم تاب . هم زور (تاب به معنی مقاومت و توانایی است ) <span class=\"hlight\">:</span> <br>در ایران جز او نیست هم تاب من <br>ندارد هم او نیز پایاب من .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268325, 'همتاه', '<span class=\"hlight\">همتاه .</span> <font color=\"DarkGreen\"><b>[هََ ]</font></b> (ص مرکب ) همتا. (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>دین از تو منظم شد چون رشته ٔ لؤلؤ<br>چون جنس به جنس آمد و همتاه به همتاه .<br> <font color=\"Red\">سوزنی .</font><br>همتای شه شرق ز کس نشنود این ماه <br>زیرا ملک شرق ز همتاهان تاه است .<br><font color=\"Red\">سوزنی (دیوان چ <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨</span>).</font><br></font></div>'),
(268326, 'همتایی', '<span class=\"hlight\">همتایی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) همتا بودن . نظیر بودن . (یادداشت مؤلف ). برابری کردن <span class=\"hlight\">:</span> <br>غزال اگر به تو میکرد لاف همتایی <br>برآمده ست کنون شاخش از پشیمانی .<br> <font color=\"Red\">؟</font><br><BR><font color=\"Blue\">◄</font> انبازی و شرکت . (آنندراج ).<br></font></div>'),
(268327, 'همتی', '<span class=\"hlight\">همتی .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (ص نسبی ) منسوب به همت . رجوع به همت (ع اِمص، اِ) شود.<br></font></div>'),
(268328, 'همتی', '<span class=\"hlight\">همتی .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (اِخ ) در دفترخانه ٔ یوسف خان افشار می بود و شعرش بد نیست . این ابیات از اوست :<br>دلی ز کوی تو ناآشنا نمی آید<br>که صد جهان ستمش در قفا نمی آید.<br> <font color=\"Red\">#</font><br>الفت میان این دل و غمهای عشق او<br>جایی رسیده است که من هیچکاره ام .<br> <font color=\"Red\">#</font><br>به آشنایی ِ بیگانه ای دلم گرم است <br>که خویش را به من از ننگ آشنا نکند.<br>(از مجمعالخواص صادقی کتابدار ص <span class=\"hlight\" dir=\"rtl\">٢٤٢</span> از ترجمه ٔ فارسی ).<br>همتی از شعرای دوره ٔ شاه عباس صفوی است .<br></font></div>'),
(268329, 'همج', '<span class=\"hlight\">همج .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (ع اِمص ) گرسنگی . <BR><font color=\"Blue\">◄</font> تدبیر بد در معاش . <BR><font color=\"Blue\">◄</font> (مص ) گرسنه گردیدن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بدزندگانی گردیدن . (منتهی الارب ).<br></font></div>'),
(268330, 'همج', '<span class=\"hlight\">همج .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) به یک بار آب خوردن شتر چنانکه بشکند تشنگی را. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268331, 'همج', '<span class=\"hlight\">همج .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (ع اِ) ج ِ همجة. (منتهی الارب ). مگس کوچکی که بر روی خر نشیند و نیز بر چشم خر. (اقرب الموارد). خرمگس، که نیز بر گوسپند نشیند. (یادداشت مؤلف ). <BR><font color=\"Blue\">◄</font> (ص ) احمق : همج الرعاع ؛ مردم احمق . (اقرب الموارد). اراذل . بی سروپاها. (یادداشت مؤلف ).<br></font></div>'),
(268332, 'همجا', '<span class=\"hlight\">همجا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) ملامت و ایذا. (آنندراج ) (برهان ).<br></font></div>'),
(268333, 'همجی', '<span class=\"hlight\">همجی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) جانوری است کوچک مانند ملخ که پیوسته بر روی علفها میگردد. (برهان ).<br></font></div>'),
(268334, 'همخان', '<span class=\"hlight\">همخان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) از نواحی گرمسیر قدیم فارس بوده است . رجوع به فارسنامه ٔ ابن بلخی ص <span class=\"hlight\" dir=\"rtl\">١٣٥</span> شود.<br></font></div>'),
(268335, 'همداستانی', '<span class=\"hlight\">همداستانی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) هم داستانی . توافق . اتحاد عقیده . هم اندیشی <span class=\"hlight\">:</span> <br>بجنبیدش به دل در مهربانی <br>نمود از خامشی همداستانی .<br> <font color=\"Red\">فخرالدین گرگانی .</font><br>- <span class=\"hlight\">همداستانی کردن </span> ؛ موافقت کردن . پذیرفتن . قبول کردن <span class=\"hlight\">:</span> <br>... که همداستانی مکن روز و شب <br>که در پیش خسرو گشایند لب .<br> <font color=\"Red\">فردوسی .</font><br>جهاندار همداستانی نکرد<br>ز ایران و توران برآورد گرد.<br> <font color=\"Red\">فردوسی .</font><br>نه هرگز بدان را به بد داده یاری <br>نه هرگز به بد کرده همداستانی .<br> <font color=\"Red\">فرخی .</font><br>ایا خواجه همداستانی مکن <br>که بر من تحمل کند ابتری .<br> <font color=\"Red\">منوچهری .</font><br><BR><font color=\"Blue\">◄</font> (اِ) زری را گویند که از رعایا در وجه خراج و مال گیرند، و به عربی مال الرضا خوانند. (برهان ) <span class=\"hlight\">:</span> این خراج بر خلق انوشیروان نهاد که ملک را از خواسته چاره نیست . و رعیت را گرد کرد و همه ٔ زمینها را مساحت کرد و به همداستانی رعیت آن خراج نهاد. (تاریخ بلعمی ). و این خراج را خراج همداستانی نام کردند یعنی مال الرضا. (تاریخ بلعمی ).<br></font></div>'),
(268336, 'همدان', '<span class=\"hlight\">همدان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) حی چهارم کهلان و ایشان فرزندان همدان بن مالک بن ... کهلان اند که جای آنها در مشرق یمن بوده است و همدانیان از پیروان علی بن ابی طالب و شیعه بودند. (ترجمه به اختصار از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٨</span>).<br></font></div>'),
(268337, 'همدان', '<span class=\"hlight\">همدان .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (اِخ ) یکی از پنج ناحیه ٔ پهله است . (ابن الندیم ). راجع به همدان لازم است گفته شود: اول دفعه ای که اسم این محل در کتیبه ٔ تیگلات پالسر <font color=\"DarkGreen\"><b>[ = تیگلات پیلسر ]</font></b> اول در حدود <span class=\"hlight\" dir=\"rtl\">١١٠٠</span> ق . م . آمده است این پادشاه آسور اسم آن را امدانه ذکر کرده . درکتیبه های هخامنشی اسم این شهر را هگمتان نوشته اند ولی بعضی تصور می کنند که هنگمتان تلفظ می شده . هردوت اسم آن را اگباتان ضبط کرده است . بنابراین تاریخ شهر مزبور تا قرن یازدهم ق . م . صعود می کند و در میان شهرهای قدیم که اکنون هم ایستاده اند نظایر همدان نادر است و تاریخ بنای رم هم چنانکه معلوم است از اواسط قرن هشتم ق . م . بالا نمیرود. همدان در پای کوه الوند واقع و کوه مزبور از سنگ خاراست . مورخان ارمنی و اخیراً راولینسن انگلیسی عقیده داشتند که اگباتان ِ هردوت، همدان کنونی نیست و محل پایتخت قدیم ماد را باید در تخت سلیمان امروز، در <span class=\"hlight\" dir=\"rtl\">٢٥</span>فرسنگی دریاچه ٔ ارومیه از طرف جنوب شرقی، جستجو کرد. ولی دمرگان که حفریات شوش را اداره میکرد شخصاً تحقیقاتی به عمل آورده و ثابت کرده که اگباتان هردوت همان محل همدان امروزی است و از برآمدگی های زمین و تپه ها جاهای هفت قلعه قصر همدان را تشخیص داد. (از ایران باستان پیرنیا صص <span class=\"hlight\" dir=\"rtl\">١٧٨</span>-<span class=\"hlight\" dir=\"rtl\">١٧٩</span>). شهرستان همدان یکی از شهرستانهای استان پنجم و از بزرگترین شهرستانهای ایران است . شمال آن حوزه ٔ شهرستانهای بیجار و زنجان، خاور شهرستان قزوین، جنوب خاوری شهرستان اراک و ساوه، جنوب تویسرکان و ملایر، و باختر آن شهرستانهای کرمانشاهان و سنندج است . هوای بخش های این شهرستان به نسبت پستی و بلندی متفاوت و در دره های الوند و دیگر نقاط مرتفع سردسیر است . همدان در دره ٔ وسیعی واقع شده که تقریباً تمام اطراف آن کوههای بلند قرار دارد و عظیم ترین آنها کوه معروف الوند ودیگر نقاط مرتفع سردسیر است . در دره های آن هزاران چشمه جاری است و همین چشمه ها سرچشمه ٔ اصلی رودخانه های قره چای و کرخه است . بلندترین قله ٔ الوند از دریای آزاد <span class=\"hlight\" dir=\"rtl\">٣٥٧٤</span> گز ارتفاع دارد و گردنه ٔ معروف اسدآباد که بر سر راه کرمانشاه و همدان است <span class=\"hlight\" dir=\"rtl\">٢٢٤١</span> گز مرتفعتر از دریاست . در اطراف شهرستان و دامنه های کوهها رودخانه های سیلابی و فصلی بسیار است . تعدادی از رودهای کوچک در بخش مرکزی به هم می پیوندند و سیمینه رود را تشکیل میدهند و مهمترین آنها عبارتند از: قورچای، خاکو، دره مرادبیک، عباس آباد، وفرجین، سیمین، اسدآباد، همه کسی، دمق وایگده لو، درجزین، شهاب و خرم رود. از شهرستان همدان راه های شوسه ٔ اسفالته ای به قزوین و تهران و کرمانشاه و ملایر و راههای شوسه ٔ خاکی به سنندج و بیجارمیرود که تعدادی از بخش ها و دهستانها و قصبات همدان نیز در مسیر همین شوسه ها قرار دارند. بخش های مهم آن عبارتند از: سیمینه رود، کبودرآهنگ، اسدآباد و رزن . محصول عمده ٔ بخش ها در قسمتهای کوهستانی انواع میوه وسردرختی به خصوص سیب و گلابی و آلبالو و در دامنه ها انگور، غله، حبوب، صیفی، کتان و پنبه است . لبنیات متنوع نیز در اغلب بخشها به دست می آید. از جمله ٔ صادرات این شهرستان میوه، چوب، سیب زمینی، پیاز، لبنیات، ظروف زیبای سفالین، چرم و کتیراست و در دهات، زنان قالیچه و گلیم و کرباس می بافند. با تحقیقات ناقصی که انجام شده وجود معادن گرافیت، طلا، طلای سفید، آنتیمون، آهن و املاح معدنی در حومه ٔ این شهرستان به اثبات رسیده است . این شهر سه بار به ترتیب در حملات اسکندر، اعراب و مغول ویران و بازساخته شده است . طول جغرافیایی <span class=\"hlight\" dir=\"rtl\">٤٨</span> درجه و <span class=\"hlight\" dir=\"rtl\">٣١</span> دقیقه ٔ شرق گرینویچ و عرض آن <span class=\"hlight\" dir=\"rtl\">٣٤</span> درجه و<span class=\"hlight\" dir=\"rtl\">٤٨</span> دقیقه ٔ شمال استواست . در این شهر اکنون تعدادی آثار تاریخی کهن وجود دارد که مهمترین آنها عبارتند از: مقبره ٔ استر و مردخای، مقبره ٔ باباطاهر عریان، گنبد علویان، آرامگاه بوعلی سینا که اخیراً ساختمان آن تجدید شده است، سنگ شیر <font color=\"DarkGreen\"><b>[ = شیرسنگی ]</font></b> که میگویند درزمان آبادی همدان قدیم بر دروازه ٔ شهر نصب شده بوده است، گنجنامه که در ده هزارگزی جنوب باختری همدان است و کتیبه ای است به خط میخی بر روی سنگ و فتوحات داریوش بر آن نوشته شده است و نیز برج معروفی به نام برج قربان در همدان وجود دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>). همدان اکنون فرمانداری کل است و تابع مرکز استان کرمانشاهان نیست .<br></font></div>'),
(268338, 'همدان', '<span class=\"hlight\">همدان .</span><font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (اِخ ) دهی است از بخش خداآفرین شهرستان تبریز که <span class=\"hlight\" dir=\"rtl\">١٧٨</span> تن سکنه دارد. آب آن از رود ارس و محصول عمده اش غله است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268339, 'همدان', '<span class=\"hlight\">همدان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی از بخش شهربابک شهرستان یزد که <span class=\"hlight\" dir=\"rtl\">١٣٧</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268340, 'همدان گشسب', '<span class=\"hlight\">همدان گشسب .</span> <font color=\"DarkGreen\"><b>[ هََ گ ُ ش َ ]</font></b> (اِخ ) از سران سپاه بهرام چوبینه در جنگ با ساوه شاه خاقان ترکستان <span class=\"hlight\">:</span> <br>به پیش اندرون بود همدان گشسب <br>که در نی زدی آتش از نعل اسب .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268341, 'همدانک', '<span class=\"hlight\">همدانک .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ن َ ]</font></b> (اِخ ) دهی است از بخش شهریار شهرستان تهران که <span class=\"hlight\" dir=\"rtl\">٥١</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله، صیفی، چغندرقند و انگور است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(268342, 'همدانی', '<span class=\"hlight\">همدانی .</span> <font color=\"DarkGreen\"><b>[ هََ م َ]</font></b> (ص نسبی ) منسوب به شهر همدان . (یادداشت مؤلف ).<br></font></div>'),
(268343, 'همدانی', '<span class=\"hlight\">همدانی .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (اِخ ) بدیعالزمان، نگارنده ٔ معروف مقامات . رجوع به بدیعالزمان احمد شود.<br></font></div>'),
(268344, 'همدانی', '<span class=\"hlight\">همدانی .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (اِخ )محمدبن عبدالملک، مکنی به ابوالحسن . مورخ و عالم فرائض بود. در <span class=\"hlight\" dir=\"rtl\">٥٢١</span> هَ . ق . درگذشت . (از اعلام زرکلی ).<br></font></div>'),
(268345, 'همدانی', '<span class=\"hlight\">همدانی .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (اِخ ) حسن بن احمد، مکنی به ابوالعلاء. رجوع به ابوالعلاء حسن بن احمد شود.<br></font></div>'),
(268346, 'همدانیان', '<span class=\"hlight\">همدانیان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) قبیله ای از عرب در نجران، و از وی دزدان بیایند و به حدود یمن راه برند. (حدود العالم ).<br></font></div>'),
(268347, 'همدایگی', '<span class=\"hlight\">همدایگی .</span> <font color=\"DarkGreen\"><b>[ هََ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (حامص مرکب ) هم دایگی . همشیربودن . نسبت دو طفل که آنها را یک دایه پرورد. همشیرگی <span class=\"hlight\">:</span> من اول شیر بنهادم تا سبب همدایگی و حق همشیرگی و تأکید محبت و مودت گردد. (تاریخ قم ).<br></font></div>'),
(268348, 'همدم', '<span class=\"hlight\">همدم .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (ص مرکب ) هم دم . هم نفس . ندیم . قرین . دوست . (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>از دو همدم که در جهان یابم <br>ناگزیر است و از جهان گذر است .<br> <font color=\"Red\">خاقانی .</font><br>جز ناله کسی همدم من نیست ز مردم <br>جز سایه کسی همره من نیست ز اصحاب .<br> <font color=\"Red\">خاقانی .</font><br>در این دامگه ارچه همدم ندارم <br>بحمداللَّه از هیچ غم، غم ندارم .<br> <font color=\"Red\">خاقانی .</font><br>بسا هم صحبت و همدم که گفتم <br>که کار من از او همچون نگار است .<br> <font color=\"Red\">مجیر بیلقانی .</font><br>مباش همدم کس چون دل تو یافت صفا<br>که آینه سیه از هم نفس شود ناچار.<br> <font color=\"Red\">مجیر بیلقانی .</font><br>ز یاران هیچ کس محرم ندارد<br>در این محنت کسی همدم ندارد.<br> <font color=\"Red\">نظامی .</font><br>شهنشاه برخاست هم درزمان <br>عنان تاب گشت از بر همدمان .<br> <font color=\"Red\">نظامی .</font><br>فروبسته کاری پیاپی غمی <br>نه کس غمگساری، نه کس همدمی .<br> <font color=\"Red\">نظامی .</font><br>با طایفه ٔ جوانان صاحبدل همدم و همقدم بودم . (گلستان ).<br>رفیق مهربان و یار همدم <br>همه کس دوست میدارند و من هم .<br> <font color=\"Red\">سعدی .</font><br>چنین گفتش از کاروان همدمی :<br>مگر تنگ ترکان ندانی همی ؟<br> <font color=\"Red\">سعدی .</font><br>ز پرده ناله ٔ حافظ برون کی افتادی <br>اگر نه همدم مرغان صبح خوان بودی .<br> <font color=\"Red\">حافظ.</font><br>سینه مالامال درد است ای دریغا مرهمی <br>دل ز تنهایی به جان آمدخدا را همدمی .<br> <font color=\"Red\">حافظ.</font><br>گر کسی همدم ددان باشد<br>به که هم صحبت بدان باشد.<br> <font color=\"Red\">مکتبی .</font><br>- <span class=\"hlight\">همدم شدن </span> ؛ همنشین شدن . دوستی کردن <span class=\"hlight\">:</span> <br>سرو چمان من چرا میل چمن نمی کند<br>همدم گل نمی شود یاد سمن نمی کند؟<br> <font color=\"Red\">حافظ.</font><br>دل به امید روی او همدم جان نمیشود<br>جان به هوای کوی او خدمت تن نمی کند.<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">همدم گشتن </span> ؛ همدم شدن . همنشین شدن <span class=\"hlight\">:</span> <br>هر آن کاو خاطر مجموع و یار نازنین دارد<br>سعادت همدم او گشت و دولت همنشین دارد.<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> همکار. دو نفر که با هم کاری را انجام دهند <span class=\"hlight\">:</span> <br>همدم هاروت و هم طبع زن بربطزنم <br>افعی ضحاکم و ریم آهن آهنگرم .<br> <font color=\"Red\">خاقانی .</font><br>آن صنم رفت با هزار هراس <br>پیش آن همدمان پرده شناس .<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> رازدار. همراز <span class=\"hlight\">:</span> <br>ای دریغا مرغ خوش آواز من <br>ای دریغا همدم و همراز من .<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">همدم ماندن </span> ؛ رازداری کردن . همرازی کردن <span class=\"hlight\">:</span><br>مزن دم پیش کس از سرّ این کار<br>که یک همدم تو را همدم نماند.<br> <font color=\"Red\">عطار.</font><br><BR><font color=\"Blue\">◄</font> دو غواص را نیز گفته اند که دم و نفس هر دو موافق باشد یعنی وقتی که دم نگاه دارند هر دو برابر نگاه توانند داشت، تا چون دم شخصی که در بیرون دریاست تمام شود آن را که درون دریاست فی الحال برآورند تا هلاک نشود. (برهان ). رجوع به هم نفس شود. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) پیاله ٔ شراب خوری . (برهان ).<br></font></div>'),
(268349, 'همدم سمنانی', '<span class=\"hlight\">همدم سمنانی .</span> <font color=\"DarkGreen\"><b>[ هََ دَ م ِ س ِ ]</font></b> (اِخ ) محمدعلی، فرزند محمدرضی منشی محمدولی میرزا، والی سمنان و خراسان بوده و صندوق دار و وقایعنگار دستگاه او شده است و اشعاری نیز از او نقل شده است . (از مجمعالفصحاء رضاقلیخان هدایت چ سنگی تهران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٧١</span>).<br></font></div>'),
(268350, 'همدم شیرازی', '<span class=\"hlight\">همدم شیرازی .</span> <font color=\"DarkGreen\"><b>[ هََ دَ م ِ ]</font></b> (اِخ ) نجفعلی، برادر میرزا ابراهیم منظور و از نزدیکان حسینعلی میرزا، فرمانفرمای فارس بوده و شبها در بزمهای او قصه میخوانده است و غزلهایی نیز سروده . (از مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٧١</span>).<br></font></div>'),
(268351, 'همدملو', '<span class=\"hlight\">همدملو.</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (اِخ ) دهی است کوچک از بخش کلیبر شهرستان اهر. آب آن از چشمه ها و محصول عمده اش غله است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268352, 'همدمی', '<span class=\"hlight\">همدمی .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (ص نسبی ) منسوب به همدم . رجوع به همدم (ص مرکب ) شود.<br></font></div>'),
(268353, 'همدمی', '<span class=\"hlight\">همدمی .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (اِخ ) همدمی مشهدی . به صنعت کاسه گری منسوب است . این مطلع از اوست :<br>بی رخت ماتم غمی دارم <br>ماتمی و چه ماتمی دارم .<br>(از مجالس النفائس میر علیشیر ص <span class=\"hlight\" dir=\"rtl\">٧٩</span> از ترجمه ٔ فارسی ).<br>وی در قرن نهم هجری میزیسته است .<br></font></div>'),
(268354, 'همدمی', '<span class=\"hlight\">همدمی .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (حامص مرکب ) هم دمی . همدم شدن . یار بودن . دوستی . مهربانی . هم نفسی . همنشینی . مصاحبت <span class=\"hlight\">:</span> <br>ای صبا طرف در گلستان کن <br>همدمی با هزاردستان کن .<br> <font color=\"Red\">سیدحسن غزنوی .</font><br>بگذار مرا در این خرابی <br>کز من دم همدمی نیابی .<br> <font color=\"Red\">نظامی .</font><br>از سر همدمی و همسالی <br>نشدی یک زمان از او خالی .<br> <font color=\"Red\">نظامی .</font><br>گفتم از همدمی و هم کیشی <br>نامها را بود به هم خویشی .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">همدمی کردن </span> ؛ موافقت . همکاری کردن <span class=\"hlight\">:</span> <br>چرا مر اهل عصیان را به عصیان همدمی کردی <br>نرفتی یک قدم با اهل ایمان در ره ایمان .<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(268355, 'همدگر', '<span class=\"hlight\">همدگر.</span> <font color=\"DarkGreen\"><b>[ هََ دِ گ َ ]</font></b> (ضمیر مبهم مرکب ) همدیگر. یک دیگر. (یادداشت مؤلف ). با هم . (آنندراج ) <span class=\"hlight\">:</span> <br>برنیایم یک تنه با سه نفر<br>پس ببرّمْشان نخست از همدگر.<br> <font color=\"Red\">مولوی .</font><br>خرده کاری بود و تفریقش خطر<br>همچو اوصال بدن با همدگر.<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(268356, 'همدیگر', '<span class=\"hlight\">همدیگر.</span> <font color=\"DarkGreen\"><b>[ هََ گ َ ]</font></b> (ضمیر مبهم مرکب ) همدگر. گویا در استعمال قدما از «همدیگر» معنی همه و جماعت ملحوظ است و از یکدیگر از هر سو یک تن . (یادداشت به خط مؤلف ). یکدیگر. رجوع به همدگر شود.<br></font></div>'),
(268357, 'همذان', '<span class=\"hlight\">همذان .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (اِخ ) همدان .شهری است که همذان بن فلوح بن سام بن نوح آن را بنا کرد. (منتهی الارب ). رجوع به همدان (مدخل ِ نخست ) شود.<br></font></div>'),
(268358, 'همذان', '<span class=\"hlight\">همذان .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b>(ع اِ) رفتاری که در آن نشان پا بر زمین بماند. (ناظم الاطباء). الرسمان فی السیر. (از اقرب الموارد).<br></font></div>'),
(268359, 'همذانی', '<span class=\"hlight\">همذانی .</span> <font color=\"DarkGreen\"><b>[ هََ م َ نی ی ]</font></b> (ع ص ) مرد بسیارسخن . <BR><font color=\"Blue\">◄</font> رفتار آمیخته از انواع رفتارها. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268360, 'همذانی', '<span class=\"hlight\">همذانی .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (ص نسبی ) منسوب به همذان . همدانی . رجوع به همدانی شود.<br></font></div>'),
(268361, 'همذانی', '<span class=\"hlight\">همذانی .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (اِخ ) بدیعالزمان . رجوع به بدیعالزمان احمد ... شود.<br></font></div>'),
(268362, 'همر', '<span class=\"hlight\">همر.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) ریختن چیزی را. <BR><font color=\"Blue\">◄</font> ریخته شدن چیزی . <BR><font color=\"Blue\">◄</font> دوشیدن شیر پستان . <BR><font color=\"Blue\">◄</font> سخن بسیار گفتن . <BR><font color=\"Blue\">◄</font> سخت سم به زمین زدن اسب . <BR><font color=\"Blue\">◄</font> رنج دادن بسیاری ِ شیر ناقه را. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دادن . (منتهی الارب ). دادن از مال . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شکستن چیزی را. <BR><font color=\"Blue\">◄</font> ویران ساختن چیزی را. (منتهی الارب ). ویران ساختن بنا. (از اقرب الموارد).<br></font></div>'),
(268363, 'همر', '<span class=\"hlight\">همر.</span> <font color=\"DarkGreen\"><b>[ هََ م ِ ]</font></b> (ع ص ) درشت اندام فربه . <BR><font color=\"Blue\">◄</font> ریگ بسیار. (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(268364, 'همر', '<span class=\"hlight\">همر.</span> <font color=\"DarkGreen\"><b>[ هَُ م ِ ]</font></b> (اِخ ) هومر. اُمروس . امیروس . اومرس . اومیروس . شاعر ملی یونان کهن است که ایلیاد واودیسه دو اثر معروف منسوب به اوست . محققان و منتقدان این دو اثر را از یک گوینده نمیدانند. (از فرهنگ بیوگرافی وبستر). زندگی او را در قرن نهم ق . م . نوشته اند. وی در اواخر عمر با چشم نابینا در شهرها می گشت و اشعار خود را بر مردم میخواند. (اعلام المنجد).<br></font></div>'),
(268365, 'همراد', '<span class=\"hlight\">همراد.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) دو کس را گویند که در همت و سخاوت و شجاعت و جوانمردی و کرم همچو هم باشند. (برهان ).<br></font></div>'),
(268366, 'همراز', '<span class=\"hlight\">همراز.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم راز. محرم اسرار. شخصی که از او هیچ چیز پنهان نکنند. (برهان ). دو تن که رازهای خود را به یکدیگر میگویند <span class=\"hlight\">:</span> <br>مر این هر دو با رستم نامدار<br>شب و روز بودند همراز و یار.<br> <font color=\"Red\">فردوسی .</font><br>سرافیل همرازش و هم نشست <br>براق اسب و جبریل فرمان پرست .<br> <font color=\"Red\">اسدی .</font><br>ز شست خدنگ افکنان خاست جوش <br>کمان گوشه ها گشت همراز چوش .<br> <font color=\"Red\">اسدی .</font><br>بر بستر خاک بی ندیم و همراز و خود خداوند کشور و امیر لشکر بود. (ترجمه ٔ تاریخ یمینی ).<br>تا کی دم اهل، اهل دم کو<br>همراز کجا و همدمم کو؟<br> <font color=\"Red\">نظامی .</font><br>به روزش آهوان دمساز بودند<br>گوزنانش به شب همرازبودند.<br> <font color=\"Red\">نظامی .</font><br>کاین غزل گفته شد چو دمسازان <br>زو خبر یافتند همرازان .<br> <font color=\"Red\">نظامی .</font><br>رفیقان همراز را کن وداع <br>عزیزان همدرد را کن درود.<br> <font color=\"Red\">عطار.</font><br>ای دریغا مرغ خوش آواز من <br>ای دریغا همدم و همراز من .<br> <font color=\"Red\">مولوی .</font><br>آن زمان که بحث عقلی ساز بود<br>این عمر با بوالحکم همراز بود.<br> <font color=\"Red\">مولوی .</font><br>گاهی سموم قهر تو همدست با خزان <br>گاهی نسیم لطف تو همراز با صبا.<br> <font color=\"Red\">سعدی .</font><br>آری به هر کجا که روم خرقةالادب <br>باشد مرا ملازم و همراز و یار غار.<br> <font color=\"Red\">ابن یمین .</font><br>ما بی غمان مست دل از دست داده ایم <br>همراز عشق و هم نفس جام باده ایم .<br> <font color=\"Red\">حافظ.</font><br>کارم بدان رسید که همراز خود کنم <br>هر شام برق لامع و هر بامداد باد.<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">همراز شدن </span> ؛ با یکدیگر راز گفتن <span class=\"hlight\">:</span> <br>چو بشنید زن درزمان بازشد<br>تو گفتی که با باد همراز شد.<br> <font color=\"Red\">فردوسی .</font><br>با کبوتر باز کی شد هم نفس <br>کی شود همراز عنقا با مگس ؟<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">همراز گشتن </span> ؛ همراز شدن <span class=\"hlight\">:</span> <br>چو او رفت شاه جهان بازگشت <br>ابا موبد خویش همراز گشت .<br> <font color=\"Red\">فردوسی .</font><br>بدیشان گفت اگر ما بازگردیم <br>وگر با آسمان همراز گردیم .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">همرازی </span> . رجوع به این مدخل شود.<br></font></div>'),
(268367, 'همرافته', '<span class=\"hlight\">همرافته .</span> <font color=\"DarkGreen\"><b>[ هََ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (اِ) مفهوم . آنچه به فهم درآید. (برهان ). از برساخته های دساتیر است . (از حواشی معین بر برهان ).<br></font></div>'),
(268368, 'همران', '<span class=\"hlight\">همران .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش سردشت شهرستان مهاباد که <span class=\"hlight\" dir=\"rtl\">٩٤</span> تن سکنه دارد. آب آن از رودخانه و محصول عمده اش غله و حبوب و توتون و کاردستی مردم گلیم بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268369, 'همراه', '<span class=\"hlight\">همراه .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) آنکه در راه با کسی رود <span class=\"hlight\">:</span> <br>مبادا به جز بخت همراهتان <br>شود تیره دیدار بدخواهتان .<br> <font color=\"Red\">فردوسی .</font><br>ز بدها تو بودی مرا دستگیر<br>چرا راه جستی ز همراه پیر؟<br> <font color=\"Red\">فردوسی .</font><br>همی بود همراهشان چار سگ <br>سگانی که نخجیر کردی به تگ .<br> <font color=\"Red\">فردوسی .</font><br>چرا همراه بد جستی و بدخواه <br>تو نشنیدی که همراه است و پس راه ؟<br> <font color=\"Red\">فخرالدین اسعد.</font><br>که نتوان بر این کوه تنها شدن <br>دو همراه باید به یک جا شدن .<br> <font color=\"Red\">نظامی .</font><br>بر آن ره که نارفته باشی بسی <br>مرو گرچه همراه باشد کسی .<br> <font color=\"Red\">نظامی .</font><br>لباسی پوش چون خورشید و چون ماه <br>که باشد تا تو باشی با تو همراه .<br> <font color=\"Red\">نظامی .</font><br>شوریده ای همراه ما بود، نعره ای بزد و راه بیابان گرفت . (گلستان ). پیاده ای سر و پا برهنه از کوفه با کاروان حجاز همراه شد. (گلستان ).<br>دیده ٔ سعدی و دل همراه توست <br>تا نپنداری که تنها میروی .<br> <font color=\"Red\">سعدی .</font><br>میروی با دل تو همراه است <br>می نشینی ز جانت آگاه است .<br> <font color=\"Red\">اوحدی .</font><br> <BR><font color=\"Blue\">◄</font> قرین . همدم . مونس <span class=\"hlight\">:</span> <br>که همواره شاه جهان شاه باد<br>سخندان و با بخت همراه باد.<br> <font color=\"Red\">فردوسی .</font><br>با این همه چهار دشمن متضاد از طبایع با وی همراه، بلکه همخواب .(کلیله و دمنه ).<br>چو زآن گم گشته گنج آگاه گشتم <br>دگر ره با طرب همراه گشتم .<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> متفق . موافق . هم عقیده و هم پیمان <span class=\"hlight\">:</span> <br>از ایرا که همراه و یار توایم <br>بر این پهن میدان سوار توایم .<br> <font color=\"Red\">فردوسی .</font><br>با او ددگان به عهد همراه <br>چون لشکر نیک عهد با شاه .<br> <font color=\"Red\">نظامی .</font><br>به تو مشغول و با تو همراهم <br>وز تو بخشایش تو میخواهم .<br> <font color=\"Red\">سعدی .</font><br>ترکیب ها:<br>- <span class=\"hlight\">همراه شدن </span> . همراه کردن . همراهی . رجوع به این سه مدخل شود.<br></font></div>'),
(268370, 'همراه بودن', '<span class=\"hlight\">همراه بودن .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (مص مرکب ) قرین بودن . پیوسته بودن دو یا چند چیز به هم . <BR><font color=\"Blue\">◄</font> گرفتار چیزی بودن چون رنج و درد.<br>- <span class=\"hlight\">تا خون همراه بودن </span> ؛ کنایه از کمال عداوت و دشمنی است <span class=\"hlight\">:</span> <br>بی همنفسی در سفر عشق نبودم <br>تا خون همه جا همره من بخت زبون بود.<br> <font color=\"Red\">دانش (از آنندراج ).</font><br>- <span class=\"hlight\">تا قتل همراه بودن </span>؛ تا خون همراه بودن . کنایه از کمال عداوت و دشمنی .در خصومت پای فشردن و دست بردار نبودن <span class=\"hlight\">:</span> <br>با محرمان عشق توام سینه صاف نیست <br>تا قتل همرهم چه نسیم و چه شانه را<br> <font color=\"Red\">کلیم (از آنندراج ).</font><br>با ما به سیر باغ نیایند دوستان <br>نازم به خصم خویش که تا قتل همره است .<br><font color=\"Red\">طاهر وحید (از تذکره ٔ نصرآبادی ). </font><br></font></div>'),
(268371, 'همراه شدن', '<span class=\"hlight\">همراه شدن .</span> <font color=\"DarkGreen\"><b>[ هََ ش ُ دَ ]</font></b> (مص مرکب ) متفق شدن . همرای شدن <span class=\"hlight\">:</span> <br>شیر با خرگوش چون همراه شد<br>پرغضب پرکینه و بدخواه شد.<br> <font color=\"Red\">مولوی .</font><br> <BR><font color=\"Blue\">◄</font> قرین شدن . گرفتار چیزی شدن، چون رنج و درد <span class=\"hlight\">:</span> <br>ز کهرم چو لهراسب آگاه شد<br>غمی گشت و با رنج همراه شد.<br> <font color=\"Red\">فردوسی .</font><br>در غم ما روزها بیگاه شد<br>روزها با سوزها همراه شد.<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(268372, 'همراه کردن', '<span class=\"hlight\">همراه کردن .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ دَ ]</font></b> (مص مرکب ) مقابل همراه شدن . قرین ساختن . دو چیز را به هم پیوستن <span class=\"hlight\">:</span> <br>مادر فرقان چه دانی تو که هفت آیت چراست <br>یا شهادت را چرا همراه کردستند لا؟<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(268373, 'همراهی', '<span class=\"hlight\">همراهی .</span> <font color=\"DarkGreen\"><b>[ هََ]</font></b> (حامص مرکب ) معیت . همراه بودن (شدن ) <span class=\"hlight\">:</span> <br>هوایی بد است آنکه بر چشم زد<br>بد آرد به همراهی چشم بد.<br> <font color=\"Red\">نظامی .</font><br>اگر شبدیز با ماه تمام است <br>به همراهیش گلگون تیزگام است .<br> <font color=\"Red\">نظامی .</font><br><BR><font color=\"Blue\">◄</font> مساعدت . معاضدت و دستگیری، به خصوص نسبت به کسی که فقیر باشد. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) کنایه از اعضای بدن نیز هست . (آنندراج از فرهنگ اسکندرنامه : همراهیان ).<br></font></div>'),
(268374, 'همرج', '<span class=\"hlight\">همرج .</span> <font color=\"DarkGreen\"><b>[ هََ م َرْ رَ ]</font></b> (ع ص ) درگذرنده در امور. <BR><font color=\"Blue\">◄</font> رسا. (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) اختلاط و فتنه . (از اقرب الموارد).<br></font></div>'),
(268375, 'همرجان', '<span class=\"hlight\">همرجان .</span> <font color=\"DarkGreen\"><b>[ هَُ رُ ]</font></b> (ع اِ) فریاد و غوغای مردم . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268376, 'همرجل', '<span class=\"hlight\">همرجل .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ج َ ]</font></b> (ع ص ) شتر نیکو تیزرو. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناقه ٔ تیزرو. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سبک و چست و تیزرو از هر چیزی . (از اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(268377, 'همرجلة', '<span class=\"hlight\">همرجلة.</span> <font color=\"DarkGreen\"><b>[ هََ م َ ج َ ل َ ]</font></b> (ع ص ) ناقه ٔ گزیده ٔ نیکو. (منتهی الارب ). ج، همرجلات . (از اقرب الموارد).<br></font></div>'),
(268378, 'همرس', '<span class=\"hlight\">همرس .</span> <font color=\"DarkGreen\"><b>[ هََ رَ ]</font></b> (اِ) درم و دینار. (برهان ). برساخته ٔ دساتیر است . (حواشی معین بر برهان ).<br></font></div>'),
(268379, 'همرش', '<span class=\"hlight\">همرش .</span> <font color=\"DarkGreen\"><b>[ هََ رَ ]</font></b> (ع اِمص ) حرکت . (از اقرب الموارد).<br></font></div>'),
(268380, 'همرش', '<span class=\"hlight\">همرش .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ م َ رِ ]</font></b> (ع ص، اِ) گنده پیر کلانسال . <BR><font color=\"Blue\">◄</font> شترماده ٔ بسیارشیر. <BR><font color=\"Blue\">◄</font> سگ ماده . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268381, 'همرفشده', '<span class=\"hlight\">همرفشده .</span> <font color=\"DarkGreen\"><b>[ هََ رَ ش ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) اسبی که داخل در پنج سالگی شده و همه ٔ دندانهایش برآمده باشد، و به جای فا، واو هم گفته اند که همروشده باشد، و به عربی قارح خوانند. (برهان ).<br></font></div>'),
(268382, 'همره', '<span class=\"hlight\">همره .</span> <font color=\"DarkGreen\"><b>[ هََ رَه ْ ]</font></b> (ص مرکب ) دو تن که به یک راه روند. همراه <span class=\"hlight\">:</span> <br>دراز است راهش وگر کوته است <br>پراکندگانیم اگر همره است .<br> <font color=\"Red\">فردوسی .</font><br>تو چنگ فزونی زدی در جهان <br>گذشتند از تو بسی همرهان .<br> <font color=\"Red\">فردوسی .</font><br>بدانید و سرتاسر آگه بوید<br>همه ساله با بخت همره بوید.<br> <font color=\"Red\">فردوسی .</font><br>به ره چون روی هیچ تنهامپوی <br>نخستین یکی نیک همره بجوی .<br> <font color=\"Red\">اسدی .</font><br>راستی با علم چون همره شدند<br>این از آن پیدا نباشد آن ازاین .<br> <font color=\"Red\">ناصرخسرو.</font><br>هرکه را هست انده بیشی <br>همره اوست کفر و درویشی .<br> <font color=\"Red\">سنائی .</font><br>مروزی و رازی افتد در سفر<br>همره و هم سفره پیش همدگر.<br> <font color=\"Red\">مولوی .</font><br>گفت ای ناقه چو هر دو عاشقیم <br>ما دو ضد، بس همره نالایقیم .<br> <font color=\"Red\">مولوی .</font><br>همره عقل و یار جان علم است <br>در دو گیتی حصار جان علم است .<br> <font color=\"Red\">اوحدی .</font><br>با وی رقیب همره و آری چنین بود<br>دائم خمار با می و خار است با رطب .<br> <font color=\"Red\">ابن یمین .</font><br>آن سفرکرده که صد قافله دل همره اوست <br>هر کجا هست خدایا به سلامت دارش .<br><font color=\"Red\">حافظ.</font><br>ملول از همرهان بودن دلیل کاردانی نیست <br>بکش دشواری منزل به یاد عهد آسانی .<br> <font color=\"Red\">حافظ.</font><br>رجوع به همراه شود.<br></font></div>'),
(268383, 'همرهی', '<span class=\"hlight\">همرهی .</span> <font color=\"DarkGreen\"><b>[ هََ رَ ]</font></b> (حامص مرکب )همراهی . همراه بودن . رفیق راه کسی شدن <span class=\"hlight\">:</span> <br>سوی رومیه باز با فرّهی <br>شد و کرد با کاروان همرهی .<br> <font color=\"Red\">اسدی .</font><br>مدار اسب و ناآزموده رهی <br>مکن جز که با مهربان همرهی .<br> <font color=\"Red\">اسدی .</font><br>قطع این مرحله بی همرهی خضر مکن <br>ظلمات است بترس از خطر گمراهی .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(268384, 'همرو', '<span class=\"hlight\">همرو.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) امرود. نوعی از درختهای شمال ایران . (یادداشت مؤلف ).<br></font></div>'),
(268385, 'همری', '<span class=\"hlight\">همری .</span> <font color=\"DarkGreen\"><b>[ هََ را ]</font></b> (ع ص ) زن بابانگ وفریاد درشت آواز پلیدزبان . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268386, 'همز', '<span class=\"hlight\">همز.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) اشاره کردن به چشم . <BR><font color=\"Blue\">◄</font> درخستن و فشردن به پنجه و جز آن . <BR><font color=\"Blue\">◄</font> سپوختن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> عیب کردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> . همزه آوردن در کلمه . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دور کردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زدن . <BR><font color=\"Blue\">◄</font> گزیدن . <BR><font color=\"Blue\">◄</font> شکستن . <BR><font color=\"Blue\">◄</font> بر زمین زدن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> همزالشیطان ؛ دیوانگی، زیرا که از اغوای شیطان سر زند. (منتهی الارب ). وسواس انداختن شیطان در دل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> حرف را به هم کردن . (تاج المصادربیهقی ). <BR><font color=\"Blue\">◄</font> (اِ) خطره ای که شیطان در دل اندازد. ج، همزات . (منتهی الارب ). رجوع به همزة شود.<br></font></div>'),
(268387, 'همزاد', '<span class=\"hlight\">همزاد.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم سن . همسال . (برهان ) <span class=\"hlight\">:</span> <br>که پیوند شاه است و همزاد اوی <br>سواری است جنگاور و نامجوی .<br> <font color=\"Red\">فردوسی .</font><br>سه پیر بودند ندیمان وی و همزاد او. (تاریخ بیهقی ).<br>مرا رامین نه خویش است و نه پیوند<br>نه هم گوهر نه همزاد و نه فرزند.<br> <font color=\"Red\">فخرالدین اسعد.</font><br>همزادبود آزر نمرودش <br>استاد بود یوسف نجارش .<br> <font color=\"Red\">خاقانی .</font><br>پس آنگه کردشان در پهلوی باد<br>که احسنت ای جهان پهلو دو همزاد.<br> <font color=\"Red\">نظامی .</font><br>به حکم آنکه گلگون سبک خیز<br>بدو بخشم ز همزادان شبدیز.<br> <font color=\"Red\">نظامی .</font><br>فرمود به دوستان همزاد<br>تا از پس او دوند چون باد.<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> توأم . دوقلو. کودکی که با کودک دیگراز یک مادر بزاید. (یادداشت مؤلف ). <BR><font color=\"Blue\">◄</font> دوست . رفیق . (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>ملک همزاد تو آمد پس بناز<br>در تن این نازنین همزاد باش .<br> <font color=\"Red\">مسعودسعد.</font><br>همیشه تیغ تو بی نصرت و ظفر نبود<br>که هست تیغ تو با نصرت و ظفر همزاد.<br> <font color=\"Red\">مسعودسعد.</font><br>بار دل به ز صبر ننهادند<br>ظفر و صبر هر دو همزادند.<br> <font color=\"Red\">سنائی .</font><br>که ما هر دو به چین همزاد بودیم <br>دو شاگرد از یکی استاد بودیم .<br> <font color=\"Red\">نظامی .</font><br>کآشنایی مرا ز همزادان <br>برد مهمان که خاکش آبادان .<br> <font color=\"Red\">نظامی .</font><br><BR><font color=\"Blue\">◄</font> مشهور است که چون فرزندی متولد شد جنی هم با او به وجود می آید و با آن شخص همراه می باشد. آن جن را نیز همزاد میگویند. (برهان ).<br></font></div>'),
(268388, 'همزاد', '<span class=\"hlight\">همزاد.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) رفیقی که در زاد و راحله شریک باشد. (از برهان ). گمان نمیرود که جزء دوم این ترکیب، زاد (واژه ٔ عربی به معنی توشه ) باشد و مؤلف برهان با معنی دوم همزاد چنین تعبیری برای لفظ «زاد» کرده است .<br></font></div>'),
(268389, 'همزاده', '<span class=\"hlight\">همزاده .</span> <font color=\"DarkGreen\"><b>[ هََ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب ) همزاد. دو تن که با هم زاده باشند. همسال <span class=\"hlight\">:</span> ... و دیگران که همزادگان ایشان بودندی بخواندی . (تاریخ بیهقی ).<br>وز زنانی که کسی دست بر ایشان ننهاد<br>همه دوشیزه و همزاده به یک صورت شاب .<br> <font color=\"Red\">ناصرخسرو.</font><br>کودکی ازجمله ٔ آزادگان <br>رفت برون با دو سه همزادگان .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268390, 'همزانگ', '<span class=\"hlight\">همزانگ .</span> <font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (اِخ ) دهی است از بخش میناب شهرستان بندرعباس که <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن سکنه دارد. آب آن از چاه و محصول عمده اش غله و خرماست . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268391, 'همزبانی', '<span class=\"hlight\">همزبانی .</span> <font color=\"DarkGreen\"><b>[ هََ زَ ]</font></b> (حامص مرکب ) همدردی . زبان یکدیگر را فهمیدن <span class=\"hlight\">:</span> <br>پس زبان محرمی خود دیگر است <br>همدلی از همزبانی بهتر است .<br> <font color=\"Red\">مولوی .</font><br>همزبانی خویشی و پیوندی است <br>مرد با نامحرمان چون بندی است .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(268392, 'همزه', '<span class=\"hlight\">همزه .</span> <font color=\"DarkGreen\"><b>[ هََ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (از ع، اِ) نام نخستین حرف از حروف الفبای فارسی و عربی است . آن را از حروف حلق خوانند و گاه آن را پس از الف، دومین حرف به حساب آورند. شکل آن در آغاز کلمه چون الف است با این تفاوت که همزه خود حرکت میگیرد. در وسط و آخرِ کلمه به صورت شبیه عین (ء) نوشته میشود. در حساب جُمَّل مانند الف برابر یک به شمار آید. (از یادداشتهای مؤلف ). حرف اول از حروف مبانی . ج، همزات . (از اقرب الموارد) <span class=\"hlight\">:</span> <br>آن برگهای شاسپرم بین و شاخ او<br>چون صدهزار همزه که بر طرف مد بُوَد.<br> <font color=\"Red\">منوچهری .</font><br><BR><font color=\"Blue\">◄</font> کندگی، مانند هزمة. (از اقرب الموارد).<br></font></div>'),
(268393, 'همزه آباد', '<span class=\"hlight\">همزه آباد.</span> <font color=\"DarkGreen\"><b>[ هََ زِ ]</font></b> (اِخ ) دهی است از بخش کنگاور شهرستان کرمانشاهان دارای <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه . آب آن از رود کبوترلانه و محصول عمده اش غله و حبوب و چغندرقند است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268394, 'همزه کلا', '<span class=\"hlight\">همزه کلا.</span> <font color=\"DarkGreen\"><b>[ هََ زَ ک َ ]</font></b> (اِخ ) نام محلی در کنار راه بابل به چالوس میان بابل و امیرکلا. (یادداشت مؤلف ).<br></font></div>'),
(268395, 'همزی', '<span class=\"hlight\">همزی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (نف مرکب ) هم زی . دو تن که با هم زیست کنند. (یادداشت مؤلف ).<br></font></div>'),
(268396, 'همزی', '<span class=\"hlight\">همزی .</span> <font color=\"DarkGreen\"><b>[ هََ م َ زا ]</font></b> (ع ص ) ریح همزی ؛ باد سخت آواز. <BR><font color=\"Blue\">◄</font> قوس همزی ؛ کمان سخت دوراندازنده تیر را. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268397, 'همزیان', '<span class=\"hlight\">همزیان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش قره ضیاءالدین شهرستان خوی که <span class=\"hlight\" dir=\"rtl\">٣٢٠</span> تن سکنه دارد. آب آن از قنات و چشمه و محصول عمده اش غله و حبوب است . کاردستی مردم بافتن جاجیم است . دو قسمت بالا و پائین دارد که سکنه ٔ همزیان بالا <span class=\"hlight\" dir=\"rtl\">٤٥</span> نفر است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268398, 'همزیستی', '<span class=\"hlight\">همزیستی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) هم زیستی . با هم زیستن . زندگی دو تن یا دو گروه با یکدیگر درحالی که شاید مناسب یکدیگر نباشند.<br></font></div>'),
(268399, 'همس', '<span class=\"hlight\">همس .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) آواز نرم . <BR><font color=\"Blue\">◄</font> هرچیز خفی . <BR><font color=\"Blue\">◄</font> آواز خفی تر از آواز قدم . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آواز نرم دهن بی آمیزش آواز سینه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (مص ) فشردن . (منتهی الارب ). فشردن انگور. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شکستن . <BR><font color=\"Blue\">◄</font> لب بند کرده داشتن، خاییدن طعام را. <BR><font color=\"Blue\">◄</font> نیک رفتن به شب . رفتن با اندک سستی و فتور به شب و روزی . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خفی کردن صوت . <BR><font color=\"Blue\">◄</font> وسوسه کردن شیطان کسی را. (اقرب الموارد).<br></font></div>'),
(268400, 'همسال', '<span class=\"hlight\">همسال .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم سال . هم سن . (آنندراج ). دو تن که به یک اندازه عمر کرده باشند. (یادداشت مؤلف ). همزاد <span class=\"hlight\">:</span> <br>کنون صد پسر گیر همسال او<br>به بالا و چهر و بر و یال او.<br> <font color=\"Red\">فردوسی .</font><br>سیاوش مرا بود همسال و دوست <br>روانم پر ازدرد و اندوه اوست .<br> <font color=\"Red\">فردوسی .</font><br>به بازی به کوی اند همسال من <br>به خاک اندر آمد چنین یال من .<br> <font color=\"Red\">فردوسی .</font><br>همسال آدم آهنش در حله ٔ آدم تنش <br>آن نقطه بر پیراهنش چون شیرحوا ریخته .<br> <font color=\"Red\">خاقانی .</font><br>بخشود بر آن غریب همسال <br>همسال تهی نه، بلکه هم حال .<br> <font color=\"Red\">نظامی .</font><br>شد نفس آن دو سه همسال او<br>تنگ تر از حادثه ٔ حال او.<br> <font color=\"Red\">نظامی .</font><br>غمی کآن با دل نالان شود جفت <br>به همسالان و هم حالان توان گفت .<br> <font color=\"Red\">نظامی .</font><br>داغ فرزند و هجر همسالان <br>همه دیدی نمیشوی نالان ؟<br><font color=\"Red\">اوحدی .</font><br></font></div>'),
(268401, 'همسالی', '<span class=\"hlight\">همسالی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) هم سالی . همسال بودن . هم سن بودن <span class=\"hlight\">:</span> <br>از سر همدمی و همسالی <br>نشدی یک زمان از او خالی .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(268402, 'همسان', '<span class=\"hlight\">همسان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم سان . مساوی . (آنندراج ). مانند. همانند <span class=\"hlight\">:</span> <br>گر کسی گوید که در گیتی کسی همسان اوست <br>گر همه پیغمبری باشد، بود یافه درای .<br> <font color=\"Red\">منوچهری .</font><br>نگاری تن جانور صدهزار<br>کز ایشان دو همسان ندارد نگار.<br> <font color=\"Red\">اسدی .</font><br>ملکت چو ملک سام و سکندر، نشان تو<br>همسان سام و همسر اسکندر آمده .<br> <font color=\"Red\">خاقانی .</font><br><BR><font color=\"Blue\">◄</font> مستوی و مسطح . (آنندراج ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(268403, 'همسایه', '<span class=\"hlight\">همسایه .</span> <font color=\"DarkGreen\"><b>[ هََ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (ص مرکب )هم دیوار. (آنندراج ). دو تن یا دو خانواده که در کنار هم خانه دارند یا در دو قسمت یک خانه زندگی کنند، و به کنایه، قرین و مجاور. ج، همسایگان <span class=\"hlight\">:</span> <br>بخواند آنگهی زرگر دند را<br>ز همسایگان مر تنی چند را.<br> <font color=\"Red\">بوشکور.</font><br>ز همسایگان گاو و خر خواستند<br>همه دشت یکسر بیاراستند.<br> <font color=\"Red\">فردوسی .</font><br>چو همسایه آمد به خیمه درون <br>بدانست کاو دست یازد به خون .<br> <font color=\"Red\">فردوسی .</font><br>از آواز ما خفته همسایگان <br>بی آرام گشتند در خوابها.<br> <font color=\"Red\">منوچهری .</font><br>از دل همسایه گر می کَنْد خواهی کین خویش <br>از دل خویش ای نفایه کین همسایه بکن .<br> <font color=\"Red\">ناصرخسرو.</font><br>همسایه ٔ نیک است تن تیره ت را جان <br>همسایه ز همسایه برد قیمت و مقدار.<br> <font color=\"Red\">ناصرخسرو.</font><br>موش، مردم را همسایه و همخانه است . (کلیله و دمنه ). همسایگان درآمدند واو را ملامت کردند. (کلیله و دمنه ).<br>همسایه شنید آه من گفت :<br>خاقانی را مگر تب آمد؟<br> <font color=\"Red\">خاقانی .</font><br>خاصه همسایگان نسطوری <br>که مرا عیسی دوم خوانند.<br> <font color=\"Red\">خاقانی .</font><br>در سایه ٔ زلف تو دل من <br>همسایه ٔ نور آسمانی است .<br> <font color=\"Red\">خاقانی .</font><br>از بس که به سایه راز می گفت <br>همسایه ٔ او به شب نمی خفت .<br> <font color=\"Red\">نظامی .</font><br>خانه ای را که چون تو همسایه ست <br>ده درم سیم کم عیار ارزد.<br> <font color=\"Red\">سعدی .</font><br>آتش از خانه ٔ همسایه ٔ درویش مخواه <br>کآنچه بر روزن او میگذرد دوددل است .<br> <font color=\"Red\">سعدی .</font><br>تا ندانی که کیست همسایه <br>به عمارت تلف مکن مایه .<br> <font color=\"Red\">اوحدی .</font><br>حق همسایگان بزرگ شمار<br>باطلی گر کنند یاد میار.<br> <font color=\"Red\">اوحدی .</font><br>بیگانگی نگر که من و یار چون دو چشم <br>همسایه ایم و خانه ٔ هم را ندیده ایم .<br> <font color=\"Red\">؟</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">بچه ٔ خودش را میزند که چشم همسایه بترسد</span> ؛در تداول این سخن را درباره ٔ کسی گویند که به خود آسیب رساند تا دیگران کاری به کارش نداشته باشند.<br> <span class=\"hlight\">مرغ همسایه غازاست </span> ؛ درباره ٔ کسی گویند که همواره چشمش به مال و مقام و فرزند دیگران است و می پندارد آنچه دیگران دارند بهتر از آن ِ اوست .<br> <span class=\"hlight\">مرگ همسایه واعظ تو بس است </span> ؛ از آنچه بر سر دیگران می آید باید عبرت گرفت .<br> <span class=\"hlight\">هرکه به امیدهمسایه نشست، گرسنه میخوابد</span> ؛ یعنی باید به خود متکی بود، و تکیه به دیگران سرانجامش ناکامی است .<br> <span class=\"hlight\">همسایه را بپرس، خانه را بخر</span> ؛ یعنی جوانب هر کار را باید پیش از اقدام به آن بررسی کرد.<br> <span class=\"hlight\">همسایه ٔ نزدیک به از برادر دور</span> ؛ یعنی اگر یکدلی و صمیمیت نباشد برادری ارزشی ندارد.<br> <span class=\"hlight\">همسایه ها یاری کنند تا من شوهرداری کنم </span> ؛ درباره ٔ کسی گویند که خود لیاقت اداره ٔ خانه و زندگیش را ندارد.<br>- <span class=\"hlight\">همسایه آزار</span> ؛ کسی که همسایگان خود را ناراحت می کند.<br>- <span class=\"hlight\">همسایه پرس </span> ؛ آنکه به حال و روز همسایگان خود توجه دارد.<br>- <span class=\"hlight\">همسایه پرسی </span> ؛ رسیدگی به حال و وضع همسایگان و رفت وآمد با آنها <span class=\"hlight\">:</span> <br>گفت : زحمت نیست ؟ گفتا: منت است <br>در خبر همسایه پرسی سنت است .<br> <font color=\"Red\">؟ (از یادداشت مؤلف ).</font><br>- <span class=\"hlight\">همسایه داری </span> ؛ همسایگی . همسایه بودن : در خانه ٔ همسایه داری راحتی نیست .<br>- <span class=\"hlight\">همسایه ٔ مسیح </span> . رجوع به این مدخل شود.<br> <BR><font color=\"Blue\">◄</font> متفق . موافق <span class=\"hlight\">:</span> <br>دلت با زبان هیچ همسایه نیست <br>روان تو را از خرد مایه نیست .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268404, 'همسایگی', '<span class=\"hlight\">همسایگی .</span> <font color=\"DarkGreen\"><b>[ هََ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (حامص مرکب ) همسایه بودن . جوار. مجاورت . (یادداشتهای مؤلف ).<br>- <span class=\"hlight\">همسایگی جستن </span> ؛ همسایه شدن با کسی <span class=\"hlight\">:</span> <br>مجویید همسایگی با بدان <br>مدارید افسوس نابخردان .<br> <font color=\"Red\">اسدی .</font><br>- <span class=\"hlight\">همسایگی گرفتن </span> ؛ همسایه شدن . منزل گرفتن در جایی <span class=\"hlight\">:</span> <br>که از بینوایی و بیمایگی <br>گرفتم در این خانه همسایگی .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268405, 'همستگان', '<span class=\"hlight\">همستگان .</span> <font color=\"DarkGreen\"><b>[هََ م َ ت َ ]</font></b> (اِ) برزخ . (از فرهنگ ایران باستان ).<br></font></div>'),
(268406, 'همسر', '<span class=\"hlight\">همسر.</span> <font color=\"DarkGreen\"><b>[ هََ س َ ]</font></b> (ص مرکب )برابر. عدیل . (آنندراج ). نظیر. همانند <span class=\"hlight\">:</span> <br>به گوهر سیاوخش را همسر است <br>برادَرْش و زآن تخم و آن گوهر است .<br> <font color=\"Red\">فردوسی .</font><br>که بالاش با چرخ همسر بود<br>تنش خون خورد بار خنجر بود.<br> <font color=\"Red\">فردوسی .</font><br>حال آدم چو حال من بوده ست <br>این دو حال است همسر و یکسان .<br> <font color=\"Red\">فرخی .</font><br>به آزادمردی و مردانگی <br>تو کس دیده ای همسر خویشتن ؟<br> <font color=\"Red\">فرخی .</font><br>ای خسروی که بخت تو را چرخ همسر است <br>تو با بلند چشمه ٔ خورشید همسری .<br> <font color=\"Red\">فرخی .</font><br>چو سروی که با ماه همسر بود<br>بر آن مه بر از مشک افسر بود.<br> <font color=\"Red\">اسدی .</font><br>خواب و خور است کار خر ای نادان <br>با خر به خواب و خور چه شوی همسر؟<br> <font color=\"Red\">ناصرخسرو.</font><br>نیست بر من پادشاهی آز را<br>میر خویشم، نیست میری همسرم .<br> <font color=\"Red\">ناصرخسرو.</font><br>زآن مقام اندیش کآنجا همسر است <br>با رعیت هم امیر و هم زعیم .<br> <font color=\"Red\">ناصرخسرو.</font><br>از نیاز ماست اینجا زر عزیز<br>ورنه زر با سنگ سوده همسر است .<br><font color=\"Red\">ناصرخسرو.</font><br>قدر تو همسر سپهر بود<br>رای تو همره قدر باشد.<br> <font color=\"Red\">مسعودسعد.</font><br>در ترازوی جهان از دعوی همسر مرنج <br>هر کجا زرّی است با او جو برابر یافتند.<br> <font color=\"Red\">ظهیر.</font><br>عالمان چون خضر پوشیده برهنه پای و سر<br>نعل پی شان همسر تاج خضرخان آمده .<br> <font color=\"Red\">خاقانی .</font><br>در پای هر برهنه سری خضر سرفشان <br>نعلین پای، همسر تاج سکندرش .<br> <font color=\"Red\">خاقانی .</font><br>زخم که جانان زند همسر مرهم شناس <br>زهر که سلطان دهد همبر تریاق نه .<br> <font color=\"Red\">خاقانی .</font><br>همسری یافتم که همسر او<br>نیست اندر دیار و کشور او.<br> <font color=\"Red\">نظامی .</font><br>گفتمش همسر تو سایه ٔ توست <br>تاج مه جای تخت پایه ٔ توست .<br> <font color=\"Red\">نظامی .</font><br>وگر همسری را دریدم جگر<br>ندادم به درّندگان دگر.<br> <font color=\"Red\">نظامی .</font><br>همسر آسمان و هم کف ابر<br>هم به تن شیر و هم به نام هزبر.<br> <font color=\"Red\">نظامی .</font><br>با بدان کم نشین که همسر بد<br>گرچه پاکی، تو را پلید کند.<br> <font color=\"Red\">سعدی .</font><br>ترکیب ها:<br>- <span class=\"hlight\">همسر آمدن </span> . همسر داشتن . همسر شدن . همسر کردن . همسر گردیدن . همسری . رجوع به این مدخل ها شود.<br> <BR><font color=\"Blue\">◄</font> شریک زندگی . هر یک از زن و شوهر <span class=\"hlight\">:</span> <br>سزا باشد و سخت درخور بود<br>که با زال رودابه همسر بود.<br> <font color=\"Red\">فردوسی .</font><br>وز آن پس چنان خواهم از کردگار<br>که با من شود همسر و نیک یار.<br> <font color=\"Red\">فردوسی .</font><br>همه چیز داری که آن درخور است <br>نداری یکی چیز و آن همسر است .<br> <font color=\"Red\">نظامی .</font><br>همخوابه ٔ عشق و همسر ناز<br>هم خازن و هم خزینه پرداز.<br> <font color=\"Red\">نظامی .</font><br>تو را من همسرم در هم نشینی <br>به چشم زیردستانم چه بینی ؟<br> <font color=\"Red\">نظامی .</font><br>وآن همسر عزیز که از عده دست داشت <br>خواهدکه بازبسته ٔ عقد فلان شود.<br> <font color=\"Red\">سعدی .</font><br>یکی پیر درویش در خاک کیش <br>نکو گفت با همسر زشت خویش ...<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> هم سخن . رفیق راه <span class=\"hlight\">:</span> با غلامان سلطانی که بر اشتران سوار می بودند همسر می گشتند و سخن می گفتند. (تاریخ بیهقی ).<br></font></div>'),
(268407, 'همسر آمدن', '<span class=\"hlight\">همسر آمدن .</span> <font color=\"DarkGreen\"><b>[ هََ س َ م َ دَ ]</font></b> (مص مرکب ) برابر بودن . همسری کردن <span class=\"hlight\">:</span> <br>اَیا شاهی که از شاهان نیاید کس تو را همسر<br>ایا میری که از میران نباشد کس تو را همتا.<br><font color=\"Red\">فرخی .</font><br></font></div>'),
(268408, 'همسر داشتن', '<span class=\"hlight\">همسر داشتن .</span> <font color=\"DarkGreen\"><b>[ هََ س َ ت َ ]</font></b> (مص مرکب ) یکسان شمردن . مانند یکدیگر تصور کردن <span class=\"hlight\">:</span> <br>بشناس مبدع را ز خالق تا نداری همسرش <br>حیدر همین کرده ست اشارت خلق را بر منبرش .<br> <font color=\"Red\">ناصرخسرو.</font><br><BR><font color=\"Blue\">◄</font> در تداول امروز، تأهل . زن داشتن .<br></font></div>'),
(268409, 'همسر شدن', '<span class=\"hlight\">همسر شدن .</span> <font color=\"DarkGreen\"><b>[ هََ س َ ش ُدَ ]</font></b> (مص مرکب ) برابر شدن . برابر بودن <span class=\"hlight\">:</span> <br>روشنی در آسمان زین آتش جشن سده ست <br>کز سرای خواجه با گردون همی همسر شود.<br> <font color=\"Red\">فرخی .</font><br>خواب و خور است کار خر ای نادان <br>با خر به خواب و خور چه شوی همسر؟<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(268410, 'همسر کردن', '<span class=\"hlight\">همسر کردن .</span> <font color=\"DarkGreen\"><b>[ هََ س َ ک َ دَ ]</font></b> (مص مرکب ) قرین ساختن . روبه رو کردن <span class=\"hlight\">:</span> <br>در پای توام به سرفشانی <br>همسر مکنم به سرگرانی .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268411, 'همسر گردیدن', '<span class=\"hlight\">همسرگردیدن .</span> <font color=\"DarkGreen\"><b>[ هََ س َ گ َ دی دَ ]</font></b> (مص مرکب ) به همسری درآمدن . زناشویی با کسی را پذیرفتن <span class=\"hlight\">:</span> <br>تا همسر تو نگردد آن ماه <br>از وی نکنم کمند کوتاه .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268412, 'همسری', '<span class=\"hlight\">همسری .</span> <font color=\"DarkGreen\"><b>[ هََ س َ ]</font></b> (حامص مرکب ) برابری و مساوات . (آنندراج ) <span class=\"hlight\">:</span> <br>شیربیابان را با مرد جنگ <br>همسری و همبری و شرکت است .<br><font color=\"Red\">ناصرخسرو.</font><br>نی زرّ خالصی ؟ ز پی همسری ّ جو<br>موقوف حکم پله وشاهین چه مانده ای ؟<br> <font color=\"Red\">خاقانی .</font><br>برون آرش از دعوی همسری <br>کز این پایه دارا کند سروری .<br> <font color=\"Red\">نظامی .</font><br>درخت کدو تا نه بس روزگار<br>کند دعوی همسری با چنار.<br> <font color=\"Red\">نظامی .</font><br>سران را گوش بر مالش نهاده <br>مرا در همسری بالش نهاده .<br> <font color=\"Red\">نظامی .</font><br>نحس شاگردی که با استاد خویش <br>همسری آغازد و آید به پیش .<br> <font color=\"Red\">مولوی .</font><br>همسری با انبیا برداشتند<br>اولیا را همچو خود پنداشتند.<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">همسری جستن </span> ؛ خود را برتر از دیگری دیدن، یا کوشش برای برابر شدن با کسی <span class=\"hlight\">:</span> <br>کسی کاو با من اندر علم و حکمت همسری جوید<br>همی خواهد که گِل بر آفتاب روشن انداید.<br> <font color=\"Red\">ناصرخسرو.</font><br> <BR><font color=\"Blue\">◄</font> زناشویی .ازدواج <span class=\"hlight\">:</span> <br>پذیرفت شاهنشه از مادرش <br>نهاد افسر همسری بر سرش .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268413, 'همسیراز', '<span class=\"hlight\">همسیراز.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) ترجمه . (برهان ). برساخته ٔ دساتیر است . (از حواشی برهان چ معین ).<br></font></div>'),
(268414, 'همسیچ', '<span class=\"hlight\">همسیچ .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش زرند شهرستان کرمان دارای <span class=\"hlight\" dir=\"rtl\">٣٥</span> تن سکنه . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268415, 'همش', '<span class=\"hlight\">همش .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) نوعی از دوشیدن شیر. <BR><font color=\"Blue\">◄</font> گرد کردن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> فراهم آوردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گَزیدن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخن بسیار گفتن . <BR><font color=\"Blue\">◄</font> در یکدیگر درآمدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> جنبش نمودن . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268416, 'همش', '<span class=\"hlight\">همش .</span> <font color=\"DarkGreen\"><b>[ هََ م ِ ]</font></b> (ع ص ) آنکه به انگشتان کارنیکو زودتر کند. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268417, 'همشاگردی', '<span class=\"hlight\">همشاگردی .</span> <font color=\"DarkGreen\"><b>[ هََ گ ِ ]</font></b> (ص مرکب ) هم شاگردی . آنکه با دیگری در یک مدرسه شاگردی کند. هم مدرسه . همدرس . همکلاس . رجوع به این مدخل ها شود.<br></font></div>'),
(268418, 'همشور', '<span class=\"hlight\">همشور.</span> <font color=\"DarkGreen\"><b>[ هََ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> شُو ]</font></b> (ص مرکب ) هم شور. آنکه دیگری با وی شور کند. مشاور. (یادداشت مؤلف ).<br></font></div>'),
(268419, 'همشکل', '<span class=\"hlight\">همشکل .</span> <font color=\"DarkGreen\"><b>[ هََ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) هم شکل . همانند. به شکل یکدیگر <span class=\"hlight\">:</span> این مرد هم شکل و هم هیأت من است . (سندبادنامه ).<br></font></div>'),
(268420, 'همشی', '<span class=\"hlight\">همشی .</span> <font color=\"DarkGreen\"><b>[ هََ م َ شا ]</font></b> (ع ص ) امراءة همشی ؛ زن بسیارسخن و بسیارفریاد. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268421, 'همشیر', '<span class=\"hlight\">همشیر.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم شیر. برادر رضاعی . (آنندراج ). دو کودک (دختر یا پسر) که از یک پستان شیر خورند. رضیع. رضیعة.<br></font></div>'),
(268422, 'همشیره', '<span class=\"hlight\">همشیره .</span> <font color=\"DarkGreen\"><b>[ هََ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص مرکب ) آنکه با دیگری بدون قرابت نسبت، از یک پستان شیر خورد. (یادداشت مؤلف ). هر پسر و یا دختری که با دیگری از پستان یک دایه شیر خورد. در تداول امروز به معنی خواهر به کار میرود. ج، همشیرگان <span class=\"hlight\">:</span> پیغامبر علیه السلام را همشیره ای بود از این دایه، روزی این همشیره گوسفندان برگرفت و بر کوه برد. (تاریخ بلعمی ).<br>ابا آنکه همشیره بودی ورا<br>کجا آب از او تیره بودی ورا.<br> <font color=\"Red\">فردوسی .</font><br>که هستند همشیرگان پدر<br>سزد گر بجویی از ایشان خبر.<br> <font color=\"Red\">فردوسی .</font><br>که من چون ز همشیرگان برترم <br>همی بآسمان اندر آید سرم .<br> <font color=\"Red\">فردوسی .</font><br>پروردگار دینی آموزگار فضلی <br>هم پیشه ٔ وفایی همشیره ٔ سخایی .<br> <font color=\"Red\">فرخی .</font><br>دولتش همشیره و دل همره و دین همنشین <br>نصرتش هم زانو و اقبال همروی سرای .<br> <font color=\"Red\">منوچهری .</font><br>نه بر شیرین نه بر من مهربان است <br>نه با همشیرگان شیرین زبان است .<br> <font color=\"Red\">فردوسی .</font><br>بسی بود همشیره با شاخ گل <br>بسی بودهمخوابه با شیر نر.<br> <font color=\"Red\">مسعودسعد.</font><br>خاقان اعظم آنکه بقا با سعادتش <br>همشیره ٔ ابد شد و پیمان تازه کرد.<br> <font color=\"Red\">خاقانی .</font><br>نیز چون همشیره با شروان رسید<br>کار شروان دست بالادیده ام .<br> <font color=\"Red\">خاقانی .</font><br>آن می که محیطبخش گشته ست <br>همشیره ٔ شیره ٔ بهشت است .<br> <font color=\"Red\">نظامی .</font><br>شکر همشیره ٔ دندان من شد<br>وفا همشهری پیمان من شد.<br> <font color=\"Red\">نظامی .</font><br>تا تو تاریک و ملول و تیره ای <br>دان که با دیو لعین همشیره ای .<br> <font color=\"Red\">مولوی .</font><br>همشیره ٔ جادوان بابِل <br>همسایه ٔ لعبتان کشمیر.<br> <font color=\"Red\">سعدی .</font><br>رجوع به همشیر و همشیرگی شود.<br></font></div>'),
(268423, 'همشیرگی', '<span class=\"hlight\">همشیرگی .</span> <font color=\"DarkGreen\"><b>[ هََ رَ <span class=\"hlight\" dir=\"rtl\">/</span>رِ ]</font></b> (حامص مرکب ) هم شیرگی . همشیر بودن برادر و خواهر یا دو برادر یا دو خواهر از طریق رضاع و شیرخوارگی . <BR><font color=\"Blue\">◄</font> کنایه از سازش و صمیمیت <span class=\"hlight\">:</span> <br>در دشت و کوه وبیشه به همشیرگی چرند<br>شیرو پلنگ و سرهان، گور و گوزن و رنگ .<br> <font color=\"Red\">سوزنی .</font><br>من اول شیر بنهادم تا سبب تأکید همدایگی و حق همشیرگی و تأکید محبت و مودت گردد. (تاریخ قم ).<br></font></div>'),
(268424, 'همص', '<span class=\"hlight\">همص .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) گوشت خوردن . <BR><font color=\"Blue\">◄</font> بر زمین افکندن کسی را. <BR><font color=\"Blue\">◄</font> برنشستن بر کسی و کشتن . (از منتهی الارب ).<br></font></div>'),
(268425, 'همط', '<span class=\"hlight\">همط.</span><font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) ستم کردن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخت زدن . <BR><font color=\"Blue\">◄</font> پاسپر کردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بی اندازه گرفتن . <BR><font color=\"Blue\">◄</font> بی باکانه سخن گفتن و خوردن . <BR><font color=\"Blue\">◄</font> به غضب و ستم گرفتن آب و جز آن را. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> حق را به باطل آمیختن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ضبط کردن . (اقرب الموارد).<br></font></div>'),
(268426, 'همع', '<span class=\"hlight\">همع.</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> هََ ]</font></b> (ع مص ) فرودویدن اشک . (آنندراج ) (اقرب الموارد).<br></font></div>'),
(268427, 'همعان', '<span class=\"hlight\">همعان .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (ع مص ) فرودویدن اشک و آب و جز آن . (تاج المصادر بیهقی ). همع. (اقرب الموارد). رجوع به همع شود.<br></font></div>'),
(268428, 'همغ', '<span class=\"hlight\">همغ.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) شکستن سر کسی را. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268429, 'همق', '<span class=\"hlight\">همق .</span> <font color=\"DarkGreen\"><b>[ هََ م ِ ]</font></b> (ع ص ) گیاه نرم و تازه . <BR><font color=\"Blue\">◄</font> گیاه بسیار. <BR><font color=\"Blue\">◄</font> گیاه خشک . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268430, 'همق', '<span class=\"hlight\">همق .</span> <font color=\"DarkGreen\"><b>[ هَِ م َق ق ]</font></b> (ع ص ) گول مضطرب خلقت . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268431, 'همقاق', '<span class=\"hlight\">همقاق .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَُ ]</font></b> (ع اِ) دانه ای است که در کوه بلعم پیدا گردد و جهت قوه ٔ باه آن را بریان کرده خورند.(منتهی الارب ). دانه ای است به مانند دانه ٔ پنبه . نیز شبیه خشخاش که سخت و شکاف دار است . (اقرب الموارد).<br></font></div>'),
(268432, 'همقاوند', '<span class=\"hlight\">همقاوند.</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان کرمان که <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش حبوب و غله و کاردستی مردم قالی بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268433, 'همقع', '<span class=\"hlight\">همقع.</span> <font color=\"DarkGreen\"><b>[ هَُ م َ ق ِ <span class=\"hlight\" dir=\"rtl\">/</span> هَُ م ْ م َ ق ِ ]</font></b>(ع ص ) مرد گول . <BR><font color=\"Blue\">◄</font> برِ درخت تنصب . <BR><font color=\"Blue\">◄</font> برِ عضاه . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268434, 'همقی', '<span class=\"hlight\">همقی .</span> <font color=\"DarkGreen\"><b>[ هَِ م ِق ْ قا <span class=\"hlight\" dir=\"rtl\">/</span> هَِ م َق ْ قا ]</font></b> (ع اِمص ) نوعی از رفتار، یعنی گاهی به چپ خمیدن در رفتن . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268435, 'همقیق', '<span class=\"hlight\">همقیق .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) گیاهی است . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268436, 'همل', '<span class=\"hlight\">همل .</span> <font color=\"DarkGreen\"><b>[ هَِ م ِل ل ]</font></b> (ع ص ) کلانسال . (از اقرب الموارد).<br></font></div>'),
(268437, 'همل', '<span class=\"hlight\">همل .</span> <font color=\"DarkGreen\"><b>[ هََ م َل ل ]</font></b> (ع اِ) خانه ٔ کوچک . (از اقرب الموارد).<br></font></div>'),
(268438, 'همل', '<span class=\"hlight\">همل .</span> <font color=\"DarkGreen\"><b>[ هََ م َ]</font></b> (ع اِ) پوست برکنده از درخت خرما. <BR><font color=\"Blue\">◄</font> آب روان که او را بازدارنده نباشد. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اشتری که روز و شب بی راعی به چرا گذاشته شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ج ِ هامل . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268439, 'همل', '<span class=\"hlight\">همل .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع اِ) گلیم سطبر که اعراب پوشند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خیمه ٔ کهنه ٔ پشمینه . (منتهی الارب ). پاره . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جامه ٔ درپی کرده . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268440, 'همل', '<span class=\"hlight\">همل .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) بر سر خود به چرا گذاشته شدن شتران بی راعی . <BR><font color=\"Blue\">◄</font> روان گردیدن اشک چشم کسی . <BR><font color=\"Blue\">◄</font> پیوسته باریدن آسمان . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268441, 'هملاج', '<span class=\"hlight\">هملاج .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص ) ستور نیک رو.ج، همالیج . (منتهی الارب ). اصل آن فارسی است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شاة هملاج ؛ گوسپند بی مغز استخوان از لاغری . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268442, 'هملان', '<span class=\"hlight\">هملان .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (ع مص ) روان گردیدن اشک چشم کسی . <BR><font color=\"Blue\">◄</font> پیوسته باریدن آسمان . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به چرا گذاشته شدن شتر بی راعی . (از اقرب الموارد).<br></font></div>'),
(268443, 'هملج', '<span class=\"hlight\">هملج .</span> <font color=\"DarkGreen\"><b>[ هََ ل َ ]</font></b> (اِ) نوعی از ذباب مشهور به خرمگس . (مخزن الادویه ).<br></font></div>'),
(268444, 'هملس', '<span class=\"hlight\">هملس .</span> <font color=\"DarkGreen\"><b>[ هََ م َل ْ ل َ ]</font></b> (ع ص ) مرد استوارساق نیک تیزرو. (منتهی الارب ). مانند عملس . (اقرب الموارد).<br></font></div>'),
(268445, 'هملع', '<span class=\"hlight\">هملع.</span> <font color=\"DarkGreen\"><b>[هََ م َل ْ ل َ ]</font></b> (ع ص ) مرد سخت نیک تیزرو که گام سخت زند جهت چستی . <BR><font color=\"Blue\">◄</font> مرد سخت گریز خبیث . <BR><font color=\"Blue\">◄</font> مرد بی وفا که بر یک جهتی برادری نپاید. <BR><font color=\"Blue\">◄</font> شتر تیزرو. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268446, 'همله', '<span class=\"hlight\">همله .</span> <font color=\"DarkGreen\"><b>[ هَِ ل َ ]</font></b> (اِخ ) قریه ای است به چهارفرسنگی میان جنوب و مغرب منامه . (فارسنامه ٔ ناصری ). در بحرین است .<br></font></div>'),
(268447, 'هملک', '<span class=\"hlight\">هملک .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) قصبه ٔ ختلان است و مستقر پادشاه . شهری است به براکوه نهاده، بسیارمردم، با روستاهای بسیار. (از حدود العالم ).<br></font></div>'),
(268448, 'هملی', '<span class=\"hlight\">هملی .</span><font color=\"DarkGreen\"><b>[ هََ لا ]</font></b> (ع ص، اِ) ج ِ هامل . (منتهی الارب ) (اقرب الموارد). شتران به چراگذاشته ٔ بی شتربان . (آنندراج ).<br></font></div>'),
(268449, 'هملی', '<span class=\"hlight\">هملی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) از طوایف ناحیه ٔ بمپور بلوچستان که مرکب از <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> خانوار است . (از جغرافیای سیاسی کیهان ).<br></font></div>'),
(268450, 'همم', '<span class=\"hlight\">همم .</span> <font color=\"DarkGreen\"><b>[ هَِ م َ ]</font></b> (ع اِ) ج ِ هِمّة. (منتهی الارب ) (اقرب الموارد). همت ها. اندیشه های بلند <span class=\"hlight\">:</span> <br>اندر دلش دیانت و اندر کفش سخا<br>اندر تنش مروت و اندر سرش همم .<br> <font color=\"Red\">فرخی .</font><br>هرکه را بینی با بخشش و با خلعت اوست <br>همتی دارد در کار سخا، به ز همم .<br> <font color=\"Red\">فرخی .</font><br>همم بقایای امم در مهاوی قصور و نقصان قرار گرفته . (تاریخ بیهقی ).<br>گردش گردون نیارد همچو تو نیکوسیر<br>دیده ٔ گردون نبیند همچو تو عالی همم .<br> <font color=\"Red\">مسعودسعد.</font><br>آرزوی جان ملک عدل و همم بود<br>از ملک عادل همام برآمد.<br> <font color=\"Red\">خاقانی .</font><br> <BR><font color=\"Blue\">◄</font> آرزوها <span class=\"hlight\">:</span> <br>یک همت تو حاصل گرداندم همم <br>یک فکرت تو زایل گرداندم فکر.<br><font color=\"Red\">مسعودسعد.</font><br></font></div>'),
(268451, 'همند', '<span class=\"hlight\">همند.</span> <font color=\"DarkGreen\"><b>[ هَُ م َ ]</font></b> (اِخ ) دهی است از بخش خوسف شهرستان بیرجند که <span class=\"hlight\" dir=\"rtl\">٢٢٨</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و پنبه و کار مردم چوب فروشی و مالداری است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268452, 'همند', '<span class=\"hlight\">همند.</span> <font color=\"DarkGreen\"><b>[ هَُ م َ ]</font></b> (اِخ ) دهی است از بخش شوسف شهرستان بیرجند که <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268453, 'همند', '<span class=\"hlight\">همند.</span> <font color=\"DarkGreen\"><b>[ هَُ م َ ]</font></b> (اِخ ) دهی است از بخش درمیان شهرستان بیرجند که هشت تن سکنه دارد. آب آن از قنات و محصول عمده اش غله است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268454, 'همنشین', '<span class=\"hlight\">همنشین .</span> <font color=\"DarkGreen\"><b>[ هََ ن ِ ]</font></b> (اِخ ) دهی است از بخش خداآفرین شهرستان تبریز که <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آب آن از چشمه و محصول عمده اش غله است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268455, 'همنشینی', '<span class=\"hlight\">همنشینی .</span> <font color=\"DarkGreen\"><b>[ هََ ن ِ ]</font></b> (حامص مرکب ) هم نشینی . همنشین شدن . با کسی نشستن <span class=\"hlight\">:</span> <br>پای درکش ز همنشینی شان <br>دیده بردوز تا نبینی شان .<br> <font color=\"Red\">سنائی .</font><br>- <span class=\"hlight\">همنشینی کردن </span> ؛ با کسی همنشین و دوست شدن . مجالسه . (یادداشت مؤلف ).<br></font></div>'),
(268456, 'همه', '<span class=\"hlight\">همه .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (ضمیر مبهم، ص، ق ) برای احاطه ٔ افراد و شمول اجزا می آید و جمع کردن آن با یای وحدت غرابتی دارد، چنانکه سعدی گوید <span class=\"hlight\">:</span> <br>همه تخت و ملکی پذیرد زوال .<br><font color=\"Red\">(از غیاث ).</font><br>یکی از موارد استعمال لفظ همه در معنی «هر» و شاهد منقول از سعدی از این مورد است . (یادداشت مؤلف ). فرق لفظ «هر» و «همه » آن است که «هر» برای شمول افراد است من حیث المجموع و «همه » من حیث الافراد، لهذا خبر هر دو مفرد و جمع واقع میشود. (غیاث ). در این مورد نیز باید گفت که صحیح آن است که : خبر «هر» مفرد و خبر و فعل برای «همه » جمع استعمال شود و «هر» به معنی یک یک از افراد است و «همه » معمولاً به معنی «کل » و «تمام » افراد با هم است . با این حال گاه «همه » به معنی «هر» به کار میرود: همه کس یا همه جا یا همه چیز <span class=\"hlight\">:</span> <br>برگزیدم به خانه تنهائی <br>ازهمه کس درم ببستم چست .<br> <font color=\"Red\">شهید بلخی .</font><br>همه نیوشه ٔخواجه به نیکویی و به صلح <br>همه نیوشه ٔ نادان به جنگ و کار نغام .<br> <font color=\"Red\">رودکی .</font><br>کنون کنده و سوخته خانه هاشان <br>همه بازبرده به تابوت و زنبر.<br> <font color=\"Red\">رودکی .</font><br>هر کسی پژمرده گردد زو نه دیر<br>مرگ بفشارد همه در زیر غن .<br> <font color=\"Red\">رودکی .</font><br>بت پرستی گرفته ایم همه <br>این جهان چون بت است و ما شمنیم .<br> <font color=\"Red\">رودکی .</font><br>از آبنوس، دری اندر او فراشته بود<br>بجای آهن، سیمین همه بش و مسمار.<br> <font color=\"Red\">ابوالمؤید بلخی .</font><br>چون کلاژه همه دزدند و رباینده چو خاد<br>شوم چون بوم بدآغال و چو دمنه محتال .<br> <font color=\"Red\">معروفی .</font><br>همه کبر و لافی به دست تهی <br>به نان کسان زنده ای سال و ماه .<br> <font color=\"Red\">معروفی .</font><br>همه بازبسته بدین آسمان <br>که بر پرده بینی بسان کیان .<br> <font color=\"Red\">ابوشکور.</font><br>اگر روزی از تو پژوهش کنند<br>همه مردمانت نکوهش کنند.<br> <font color=\"Red\">ابوشکور.</font><br>و این قوم را با همه قومی که گرداگرد ایشان است جنگ است و دشمنی است . (حدود العالم ). و همه طیبی که آنجا برند از هوای آنجا بوی او برود. (حدودالعالم ).<br>خروشان و کفک افکنان و سلیحش <br>همه ماردی گشته و خنگش اشقر.<br> <font color=\"Red\">خسروی سرخسی .</font><br>چشم چون جامه ٔ غوک است گرفته همه سال <br>لفج چون موزه ٔ خواجه حسن عیسی کج .<br> <font color=\"Red\">منجیک .</font><br>تو نزد همه کس چو ماکیانی <br>اکنون تن خود را خروس کردی .<br> <font color=\"Red\">عماره .</font><br>همه یاوه همه خام و همه سست <br>معانی با حکایت تا پساوند. <br> <font color=\"Red\">لبیبی .</font><br>ایا ز بیم زبانم نژند گشته و هاژ<br>کجا شد آن همه دعوی کجا شد آن همه ژاژ؟<br> <font color=\"Red\">لبیبی .</font><br>همه سر آرد بار آن سنان نیزه ٔ او<br>هرآینه که همی خون خورد سر آرد بار.<br> <font color=\"Red\">دقیقی .</font><br>همه نامداران آن مرز را<br>چو طوس و چو کاووس و گودرز را.<br> <font color=\"Red\">فردوسی .</font><br>چو دیدند ایرانیان روی او<br>همه برنهادند بر خاک رو.<br> <font color=\"Red\">فردوسی .</font><br>ز رنجی که ایدر شهنشاه برد<br>همه رومیان آن ندارند خرد.<br> <font color=\"Red\">فردوسی .</font><br>همه عالم ز فتوح تو نگارین گشته ست <br>همچو آگنده به صد رنگ نوآیین سیرنگ .<br> <font color=\"Red\">فرخی .</font><br>با هنر او همه هنرها یافه <br>با سخن او همه سخنها ترفند.<br> <font color=\"Red\">فرخی .</font><br>گفت کاین مردمان بی باکند<br>همه همواره دزد و چالاکند.<br> <font color=\"Red\">عنصری .</font><br>به همه شهر بوداز او آذین <br>در بریشم چو کرم پیله زمین .<br> <font color=\"Red\">عنصری .</font><br>گر کسی گوید که در گیتی کسی برسان اوست <br>گر همه پیغمبری باشد بود یافه درای .<br> <font color=\"Red\">منوچهری .</font><br>عاشق از دور به معشوقه ٔ خود درنگرید<br>بخروشید و خروشش همه گوشی بشنید.<br> <font color=\"Red\">منوچهری .</font><br>بدان نامه بیارامید و همه نفرتها زائل گشت . (تاریخ بیهقی ). آن نظام بگسست و کارها همه دیگر شد. (تاریخ بیهقی ). من از بهر عباسیان انگشت درکرده ام در همه جهان و قرمطی میجویم . (تاریخ بیهقی ).<br>همه عدل ورز و همه مکرمت کن <br>همه مال بخش و همه محمدت خر.<br> <font color=\"Red\">ناصرخسرو.</font><br>جانم همه در اضطراب بندد<br>چشمم همه در انتظار دارد.<br> <font color=\"Red\">مسعودسعد.</font><br>گرچه ایشان اقارب اند همه <br>در اقارب عقارب اندهمه .<br> <font color=\"Red\">سنائی .</font><br>همه نقود خانه پیش چشم من آمدی . (کلیله و دمنه ).<br>تنگ چشمی ز تنگ چشمی دور<br>همه سروی ز خاک و او از نور.<br> <font color=\"Red\">نظامی .</font><br>چون که مرا زین همه دشمن نهند<br>تهمت این واقعه بر من نهند.<br> <font color=\"Red\">نظامی .</font><br>ورای همه گوهری بودِ او<br>همه رشته ای گوهرآمود او.<br> <font color=\"Red\">نظامی .</font><br>یک مؤذن داشت بس آواز بد<br>شب همه شب میدریدی حلق خود.<br> <font color=\"Red\">مولوی .</font><br>نه کمال حسن باشد ترشی و روی شیرین <br>همه بد مکن که مردم همه نیکخواه داری .<br> <font color=\"Red\">سعدی .</font><br>امید تو بیرون برد از دل همه امیدی <br>سودای تو بیرون کرد از سر همه سودایی .<br> <font color=\"Red\">سعدی .</font><br>از در خویشم مران کاین نه طریق وفاست <br>در همه شهری غریب در همه ملکی گداست .<br> <font color=\"Red\">سعدی .</font><br>ناچار هرکه صاحب روی نکو بود<br>هر جا که بگذرد همه چشمی بر او بود.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">این همه </span> ؛ مقدار زیاد. این مقدار <span class=\"hlight\">:</span> <br>این همه شهد و شکر کز سخنم میریزد<br>اجر صبری ست کز آن شاخ نباتم دادند.<br><font color=\"Red\">حافظ.</font><br>حاصل کارگه کون و مکان این همه نیست <br>باده پیش آر که اسباب جهان این همه نیست .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(268457, 'همه ایاز', '<span class=\"hlight\">همه ایاز.</span> <font color=\"DarkGreen\"><b>[ هََ م ِ اَ ]</font></b> (اِخ ) دهی است از بخش گوران شهرستان شاه آباد. دارای <span class=\"hlight\" dir=\"rtl\">٣٥</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268458, 'همه جا', '<span class=\"hlight\">همه جا.</span> <font color=\"DarkGreen\"><b>[ هََ م ِ ]</font></b> (اِخ ) دهی است از توابع شهرستان کرج . دارای <span class=\"hlight\" dir=\"rtl\">٢٩٣</span> تن سکنه، آب آن از چشمه سار و محصول عمده اش غله، لبنیات و عسل است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(268459, 'همه جانبه', '<span class=\"hlight\">همه جانبه .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ن ِ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (ص مرکب ) کاری که از همه طرف با آن روی موافق نشان داده شود. مورد اتفاق . دارای جنبه های گوناگون .<br></font></div>'),
(268460, 'همه رهه', '<span class=\"hlight\">همه رهه .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ رَ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (ق مرکب ) یکسره . یکره . یکسر. (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>حرکاتش همه رهه هنر است <br>برم از جان من عزیزتر است .<br><font color=\"Red\">عنصری .</font><br></font></div>'),
(268461, 'همه روزه', '<span class=\"hlight\">همه روزه .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ص نسبی )آنچه در همه ٔ روزها باشد یا انجام پذیرد و مکرر باشد. <BR><font color=\"Blue\">◄</font> (ق مرکب ) به تکرار. پیوسته . همیشه .<br></font></div>'),
(268462, 'همه ساله', '<span class=\"hlight\">همه ساله .</span> <font color=\"DarkGreen\"><b>[ هََم َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ق مرکب ) همیشه و پیوسته . (آنندراج ). در تمام مدت سال . (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>اندازد ابروانت همه ساله تیر غوش <br>وآن گاه گویدم که خروشان مشو خموش .<br> <font color=\"Red\">خسروی سرخسی .</font><br>ز گیتی ستمکاره را دور دار<br>ز بیمش همه ساله رنجور دار.<br> <font color=\"Red\">فردوسی .</font><br>گر گنهکار نشد زلف تو در عارض تو<br>چون پسندی که همه ساله نگونسار بود؟<br> <font color=\"Red\">امیرمعزی .</font><br>نگویمت که همه ساله می پرستی کن <br>سه ماه می خور و نه ماه پارسا می باش .<br> <font color=\"Red\">حافظ.</font><br><BR><font color=\"Blue\">◄</font> (ص نسبی، اِ مرکب )در زمان صفویه نام قسمی مواجب مقرری بوده است . ج، همه سالجات . رجوع به تذکرةالملوک ص <span class=\"hlight\" dir=\"rtl\">١١</span> و <span class=\"hlight\" dir=\"rtl\">٤١</span> شود.<br></font></div>'),
(268463, 'همه سین', '<span class=\"hlight\">همه سین .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (اِخ ) یا ترکمانده . دهی است از توابع شهرستان شمیرانات . در شش هزارگزی جنوب راه دماوند واقع، دارای <span class=\"hlight\" dir=\"rtl\">١٩١</span> تن سکنه است . آب آن از چشمه سار و محصول عمده اش غله و صیفی است . ساکنان ترکمن هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(268464, 'همه شان', '<span class=\"hlight\">همه شان .</span> <font color=\"DarkGreen\"><b>[ هََ م ِ ]</font></b> (اِخ ) دهی است از بخش گرمی شهرستان اردبیل . دارای <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268465, 'همه فن حریف', '<span class=\"hlight\">همه فن حریف .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِف َ ح َ ]</font></b> (ص مرکب ) کسی که تن به هر کار میدهد یا از عهده ٔ هر کار خوب یا بد برمی آید. (یادداشت مؤلف ).<br></font></div>'),
(268466, 'همه چان', '<span class=\"hlight\">همه چان .</span> <font color=\"DarkGreen\"><b>[ هَِ م ِ ]</font></b> (اِخ ) دهی است از بخش چهاردانگه ٔ شهرستان ساری . دارای <span class=\"hlight\" dir=\"rtl\">١٠٥</span> تن سکنه، آب آن از چشمه و رودخانه ٔ نکا، محصول عمده اش غله، برنج، لبنیات، عسل و ارزن و کار دستی زنان بافتن شال و کرباس است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(268467, 'همه کاره', '<span class=\"hlight\">همه کاره .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص مرکب ) آنکه از عهده ٔ هر کاری برآید یا همه ٔ کارها به دست او باشد. مقتدر. بانفوذ. <BR><font color=\"Blue\">◄</font> کسی که همه ٔ کارهای مربوط به دیگری را انجام دهد: فلان کس همه کاره ٔ وزیر است . (یادداشت مؤلف ).<br></font></div>'),
(268468, 'همه کسی', '<span class=\"hlight\">همه کسی .</span> <font color=\"DarkGreen\"><b>[ هََ م ِ ک َ ]</font></b> (اِخ ) دهی است از بخش رزن شهرستان همدان . دارای <span class=\"hlight\" dir=\"rtl\">٢٩٤</span> تن سکنه، آب آن از قنات و محصول عمده اش غله و لبنیات وحبوب و صیفی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268469, 'همه کسی', '<span class=\"hlight\">همه کسی .</span> <font color=\"DarkGreen\"><b>[ هََ م ِ ک َ ]</font></b> (اِخ ) دهی است از بخش سیمینه رود شهرستان همدان . دارای <span class=\"hlight\" dir=\"rtl\">١٥٢١</span> تن سکنه، آب آن از چشمه و رودخانه ٔ محلی و چاه و محصول عمده اش غله، حبوب، لبنیات و انگور است . کار دستی مردم قالی بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268470, 'همه کوشتی', '<span class=\"hlight\">همه کوشتی .</span> <font color=\"DarkGreen\"><b>[ هََ م ِ ]</font></b> (اِخ ) نام محلی کنار راه شاه آباد و مهران میان توراب و دره ٔبادام در هیجده هزارگزی شاه آباد. (یادداشت مؤلف ).<br></font></div>'),
(268471, 'همهام', '<span class=\"hlight\">همهام .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) مرد دلیر جوانمرد. <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه .(منتهی الارب ) (اقرب الموارد). رجوع به همهوم شود.<br></font></div>'),
(268472, 'همهامة', '<span class=\"hlight\">همهامة.</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (ع اِ) گله ٔ بزرگ از شتران . (منتهی الارب ) (اقرب الموارد). همهومة. رجوع به همهومة شود.<br></font></div>'),
(268473, 'همهمة', '<span class=\"hlight\">همهمة.</span> <font color=\"DarkGreen\"><b>[ هََ هََ م َ ]</font></b> (ع مص ) خوابانیدن زن کودک را به آواز. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> برگردانیدن آواز در سینه از اندوه . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بانگ کردن شیر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بانگ کردن رعد. <BR><font color=\"Blue\">◄</font> (اِ) سخن نرم و آواز خفی که فهمیده نشود مثل آواز گاو و پیل و مانند آن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> هر آواز که با گرفتگی از گلو آید. (منتهی الارب ). ج، هماهم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> در تداول فارسی زبانان، آوازهای بسیار درهم افتاده که تمیز آن از یکدیگر نتوان داد. (یادداشت مؤلف ).<br></font></div>'),
(268474, 'همهوم', '<span class=\"hlight\">همهوم .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع اِ) شیر بیشه . <BR><font color=\"Blue\">◄</font> (ص ) باصدا. <BR><font color=\"Blue\">◄</font> نی هنگامی که باد آن را بجنباند. (اقرب الموارد).<br></font></div>'),
(268475, 'همهومة', '<span class=\"hlight\">همهومة.</span> <font color=\"DarkGreen\"><b>[ هَُ م َ ]</font></b> (ع اِ) گله ٔ بزرگ از شتران . (منتهی الارب ) (اقرب الموارد). رجوع به همهامة شود.<br></font></div>'),
(268476, 'همهیم', '<span class=\"hlight\">همهیم .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع اِ) شیر بیشه . <BR><font color=\"Blue\">◄</font> (ص ) خر برگردانیده آواز در سینه . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268477, 'همو', '<span class=\"hlight\">همو.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ق + ضمیر) (از: هم + او) نیز او. همچنین او <span class=\"hlight\">:</span> <br>با نکوکردگان نکو می کرد<br>قهر بدگوهران همو می کرد.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268478, 'همو', '<span class=\"hlight\">همو.</span> <font color=\"DarkGreen\"><b>[ هََ م ْوْ ]</font></b> (ع مص ) روان شدن اشک . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268479, 'همو', '<span class=\"hlight\">همو.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش کلیبر شهرستان اهر که <span class=\"hlight\" dir=\"rtl\">١٠</span> تن سکنه دارد. آب آن از چشمه و محصول عمده اش غله است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268480, 'هموار', '<span class=\"hlight\">هموار.</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ]</font></b> (ص ) مستوی . هم سطح . (یادداشت مؤلف ). آنچه قسمتهای مختلف آن در یک سطح باشد از زمین و جز آن <span class=\"hlight\">:</span> <br>آشکوخد بر زمین هموار بر<br>همچنان چون بر زمین دشخوار بر.<br> <font color=\"Red\">رودکی .</font><br>چو پشته پشته شد از کشته پیش روی ملک <br>فراخ دشتی چون روی آینه هموار.<br> <font color=\"Red\">فرخی .</font><br>بس بناهاکه او برآورده ست <br>باز کرده ست با زمین هموار.<br> <font color=\"Red\">مسعودسعد.</font><br>می کند هموار سوهان تیغ ناهموار را<br>هرکجا باید درشتی کرد همواری چه سود.<br> <font color=\"Red\">صائب .</font><br> <BR><font color=\"Blue\">◄</font> موافق مقام . مناسب . موافق میل <span class=\"hlight\">:</span> <br>سخن را جای باید جست هموار<br>به میدان در رود خوش اسب رهوار.<br> <font color=\"Red\">ناصرخسرو.</font><br>نه همه سال کار هموار است <br>نه به هر وقت حال یکسان است .<br> <font color=\"Red\">مسعودسعد.</font><br>- <span class=\"hlight\">هموار کردن </span> ؛ موافق کردن . مناسب کردن <span class=\"hlight\">:</span> <br>هموار کرد خواهی گیتی را؟<br>گیتی است کی پذیرد همواری ؟<br> <font color=\"Red\">رودکی .</font><br>و رجوع به مدخل هموار کردن شود.<br>- <span class=\"hlight\">ناهموار</span> ؛ ناموافق . نامناسب . تحمل ناپذیر <span class=\"hlight\">:</span> <br>مرنجان جان ما را گر توانی <br>بدین گفتار ناهموار هموار.<br> <font color=\"Red\">رودکی .</font><br> <BR><font color=\"Blue\">◄</font> برابر و یکسان و به یک طریق . (برهان ). <BR><font color=\"Blue\">◄</font> (ق ) همیشه و دائم . (برهان ). پیوسته . همواره . هماره <span class=\"hlight\">:</span> <br>مرنجان جان ما را گر توانی <br>بدین گفتار ناهموار هموار.<br> <font color=\"Red\">رودکی </font><br>دیدن شاه برتو فرخ باد<br>همچو بر شاه دیدنت هموار.<br> <font color=\"Red\">فرخی .</font><br>آن کیست که این لفظ همی گوید با تو<br>جز من که به هر شعر همی گویم هموار.<br> <font color=\"Red\">فرخی .</font><br>وگر بیابد روزی هزارسنگ درم <br>هزار و صد بدهد کارش این بود هموار.<br> <font color=\"Red\">فرخی .</font><br>همچون سر پستان عروسان پری روی <br>وندر سر پستان بر شیر آمده هموار.<br> <font color=\"Red\">منوچهری .</font><br>زیرا که نزاده ست شما را کس هموار<br>بر خاک همی زاده ٔ زاینده بزایید.<br> <font color=\"Red\">ناصرخسرو.</font><br>از تو هموار همی دزددعمرت را<br>چرخ بیدادگر و گشتن هموارش .<br> <font color=\"Red\">ناصرخسرو.</font><br>صبا باز با گل چه بازار دارد؟<br>که هموارش از خواب بیدار دارد.<br> <font color=\"Red\">ناصرخسرو.</font><br>مر مرا دولت تو فرماید<br>که همیشه همی رود هموار.<br> <font color=\"Red\">مسعودسعد.</font><br>خوب حالی و خوش نشاطی بود<br>دوش با روی او مرا هموار.<br> <font color=\"Red\">مسعودسعد.</font><br>شمس نزد اسد رود مادام <br>روح سوی جسد رود هموار.<br> <font color=\"Red\">خاقانی .</font><br>که صاحبدلی بر پلنگی نشست <br>همی راند هموار و ماری به دست .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> یکسر.همه با هم <span class=\"hlight\">:</span> <br>تو را به اصل بزرگ ای بزرگوار کریم <br>زیادتی است بر آزادگان همه هموار.<br> <font color=\"Red\">فرخی .</font><br> <BR><font color=\"Blue\">◄</font> (ص ) یکدست . در همه ٔ قسمتها به یک نسبت .<br>- <span class=\"hlight\">هموار شدن </span> ؛ یکدست شدن <span class=\"hlight\">:</span> باید کوفت و می سرشتن تا هموار شود. (ذخیره ٔ خوارزمشاهی ). در شراب تر باید کردن و حل کردن و در هاون بمالیدن تا هموار شود. (ذخیره ٔ خوارزمشاهی ).<br></font></div>'),
(268481, 'هموار داشتن', '<span class=\"hlight\">هموار داشتن .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ت َ ]</font></b> (مص مرکب ) یکسان کردن <span class=\"hlight\">:</span> <br>مر این هر دو را هیچ دهقان عادل <br>چه گویی که یکسان و هموار دارد.<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(268482, 'هموار کردن', '<span class=\"hlight\">هموار کردن .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ک َ دَ ]</font></b> (مص مرکب ) صاف کردن . تسطیح کردن . (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>هموار کرد موی و بیفکند موی زرد<br>چون بچه ٔ کبوتر منقار سخت کرد.<br> <font color=\"Red\">ابوشکور.</font><br>تربت وی را با زمین هموار کردند. (قصص الانبیاء).<br>می کند هموار سوهان تیغ ناهموار را<br>هرکجا باید درشتی کرد همواری چه سود.<br> <font color=\"Red\">صائب .</font><br> <BR><font color=\"Blue\">◄</font> تحمل کردن <span class=\"hlight\">:</span> <br>این درد نه دردی است که بیرون رود از دل <br>این داغ نه داغی است که هموارتوان کرد.<br> <font color=\"Red\">صائب .</font><br>- <span class=\"hlight\">بر خود هموار کردن </span> ؛ تحمل کردن .<br> <BR><font color=\"Blue\">◄</font> موافق کردن <span class=\"hlight\">:</span> <br>هموار کرد خواهی گیتی را؟<br>گیتی است کی پذیرد همواری ؟<br><font color=\"Red\">رودکی .</font><br></font></div>'),
(268483, 'همواران', '<span class=\"hlight\">همواران .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ]</font></b> (اِخ ) شهرکی است به نزدیکی رود کسوان نهاده است <font color=\"DarkGreen\"><b>[از ماوراءالنهر ]</font></b> و مردم اندک اند. (حدود العالم ).<br></font></div>'),
(268484, 'همواره', '<span class=\"hlight\">همواره .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ق ) پیوسته و همیشه و مدام . (برهان ). هماره . هموار <span class=\"hlight\">:</span> <br>به خط و آن لب و دندانْش بنگر<br>که همواره مرا دارند در تاب .<br> <font color=\"Red\">پیروز مشرقی .</font><br>خواسته تاراج گشته سر نهاده بر زیان <br>لشکرت همواره یافه چون رمه ی ْ رفته شبان .<br> <font color=\"Red\">رودکی .</font><br>کردم روان و دل را بر جان او نگهبان <br>همواره گردش اندر گردان بوند و کاوان .<br> <font color=\"Red\">دقیقی .</font><br>همواره پراپیخ است آن چشم فژاکن <br>گویی که دو بوم آنجا بر خانه گرفته ست .<br> <font color=\"Red\">عماره .</font><br>همی بود همواره با من درشت <br>برآشفت یکبار و بنمود پشت .<br> <font color=\"Red\">فردوسی .</font><br>چه گویی کنون کار فرشیدورد<br>که بوده ست همواره با داغ و درد.<br> <font color=\"Red\">فردوسی .</font><br>بر او آفرین کرد گشتاسب و گفت <br>که با توخرد باد همواره جفت .<br> <font color=\"Red\">فردوسی .</font><br>این بود ملک را به جهان وقتی آرزو<br>وین بود خلق را همه همواره در ضمیر.<br> <font color=\"Red\">فرخی .</font><br>همواره پادشاه جهان بادا<br>آن حق شناس حق ده حرمت دان .<br> <font color=\"Red\">فرخی .</font><br>گفت کاین مردمان بی باکند<br>همه همواره دزد و چالاکند.<br> <font color=\"Red\">عنصری .</font><br>همواره باش مهتر و همواره جاودان <br>مه باش جاودانه و همواره باش حی .<br> <font color=\"Red\">منوچهری .</font><br>رازدار من تویی همواره یار من تویی <br>غمگسار من تویی من آن تو، تو آن من .<br> <font color=\"Red\">منوچهری .</font><br>جهان همواره گرد آمد بر او بر<br>نه بر رامین که بر دینار و گوهر.<br> <font color=\"Red\">فخرالدین اسعد.</font><br>گر رسم و خوی دیو گرفتند لاجرم <br>همواره پیش دیو بداندیش چاکرند.<br> <font color=\"Red\">ناصرخسرو.</font><br>با طاعت و ترس باش همواره <br>تا از تو به دل حسد برد ترسا.<br> <font color=\"Red\">ناصرخسرو.</font><br>امروز همواره عبادت می کنند. (کلیله و دمنه ).<br>نه پیوسته باشد روان در بدن <br>نه همواره باشد زبان در دهن .<br> <font color=\"Red\">سعدی .</font><br>عزیزی در اقصای تبریز بود<br>که همواره بیدار و شبخیز بود.<br> <font color=\"Red\">سعدی .</font><br>تا گنج غمت در دل ویرانه مقیم است <br>همواره مرا کوی خرابات مقام است .<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> یکسر. تماماً <span class=\"hlight\">:</span> <br>شب است اکنون که خورشیدم برفته ست <br>جهان همواره تاریکی گرفته ست .<br> <font color=\"Red\">فخرالدین اسعد.</font><br>رجوع به هموار شود.<br></font></div>'),
(268485, 'هموارکندی', '<span class=\"hlight\">هموارکندی .</span> <font color=\"DarkGreen\"><b>[ هََم ْ ک َ ]</font></b> (اِخ ) دهی است از دهستان گرمی شهرستان اردبیل . دارای <span class=\"hlight\" dir=\"rtl\">٩٦٠</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268486, 'هموارگی', '<span class=\"hlight\">هموارگی .</span> <font color=\"DarkGreen\"><b>[ هََ م ْرَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص نسبی ) همیشگی و دائمی . (انجمن آرا).<br></font></div>'),
(268487, 'همواری', '<span class=\"hlight\">همواری .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ]</font></b> (حامص ) برابری . تساوی . استواء.(یادداشت مؤلف ). <BR><font color=\"Blue\">◄</font> هموار بودن یا شدن . یکدستی . برابری سطح قسمتهای مختلف چیزی <span class=\"hlight\">:</span> اندر کشکاب لزوجتی است با نرمی و لغزانی و پیوستگی یعنی همواری قوام . (ذخیره ٔ خوارزمشاهی ). <BR><font color=\"Blue\">◄</font> مناسبت . با خواست کسی جور آمدن . موافقت <span class=\"hlight\">:</span> <br>هموار کرد خواهی گیتی را؟<br>گیتی است کی پذیرد همواری ؟<br> <font color=\"Red\">رودکی .</font><br>چیزی که تو پنداری در حضرت و در غربت <br>کاری که تو اندیشی در کژی و همواری .<br> <font color=\"Red\">منوچهری .</font><br> <BR><font color=\"Blue\">◄</font> نرمی و ملایمت <span class=\"hlight\">:</span> <br>می کند هموار سوهان تیغ ناهموار را<br>هرکجا باید درشتی کرد همواری چه سود؟<br><font color=\"Red\">صائب .</font><br></font></div>'),
(268488, 'هموخ', '<span class=\"hlight\">هموخ .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) شمع و مشعل و چراغ . (انجمن آرا).<br></font></div>'),
(268489, 'همود', '<span class=\"hlight\">همود.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع مص ) فرومردن آتش یا رفتن حرارت آن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مردن قوم از گرسنگی .<br></font></div>'),
(268490, 'همورابی', '<span class=\"hlight\">همورابی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) پادشاه توانای بابل است که از <span class=\"hlight\" dir=\"rtl\">٢١٢٣</span> تا <span class=\"hlight\" dir=\"rtl\">٢٠٨١</span> ق . م . سلطنت کرده و قوانین او مشهور است . رجوع به فرهنگ ایران باستان تألیف پورداود ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span> و رجوع به حامورابی شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(268491, 'هموس', '<span class=\"hlight\">هموس .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) به شب رونده . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیر شکننده شکار را. <BR><font color=\"Blue\">◄</font> شیر نرم گیرنده . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268492, 'هموص', '<span class=\"hlight\">هموص .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) رجل هموص الفؤاد؛ مرد شوریده دل . (منتهی الارب ).<br></font></div>'),
(268493, 'هموع', '<span class=\"hlight\">هموع .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع مص ) دویدن اشک . (تاج المصادر بیهقی ). اشک ریختن چشم . (اقرب الموارد).<br></font></div>'),
(268494, 'همول', '<span class=\"hlight\">همول .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع مص ) روان گردیدن اشک چشم کسی . <BR><font color=\"Blue\">◄</font> پیوسته باریدن آسمان . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268495, 'همولة', '<span class=\"hlight\">همولة.</span> <font color=\"DarkGreen\"><b>[ هَُ ل َ ]</font></b> (ع ص، اِ) ج ِ هامل . (منتهی الارب ) (اقرب الموارد). رجوع به هامل شود.<br></font></div>'),
(268496, 'هموم', '<span class=\"hlight\">هموم .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع اِ) ج ِ هَم ّ. (منتهی الارب ) (اقرب الموارد). رجوع به هم شود.<br></font></div>'),
(268497, 'هموم', '<span class=\"hlight\">هموم .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) شترماده ٔ خوش رفتار. <BR><font color=\"Blue\">◄</font> چاه بسیارآب . <BR><font color=\"Blue\">◄</font> نی و نیزه، چون باد بجنباند آن را. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ابر باران ریز. (اقرب الموارد).<br></font></div>'),
(268498, 'همومة', '<span class=\"hlight\">همومة.</span> <font color=\"DarkGreen\"><b>[ هَُ م َ ]</font></b> (ع مص ) پیر شدن . (منتهی الارب ). همامة. (اقرب الموارد).<br></font></div>'),
(268499, 'همونه', '<span class=\"hlight\">همونه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) شهری است در نزدیکی وادی جمهور که در حوالی آن استخوان را دفن میکردند. (قاموس کتاب مقدس ).<br></font></div>'),
(268500, 'هموژن', '<span class=\"hlight\">هموژن .</span> <font color=\"DarkGreen\"><b>[ هَُ م ُ ژِ ]</font></b> (فرانسوی، ص ) یکنواخت . ماده ای که از مولکولهای همانند ساخته شده باشد. سلولهای مشابه و همانند بافت مزوفیل در برگ اغلب نباتات یک لپه ای و کاجها و بعضی از دولپه ای ها که ساختمانی یکنواخت و مشابه دارند. (از گیاه شناسی حبیب اﷲ ثابتی ص <span class=\"hlight\" dir=\"rtl\">٣٣٦</span>).<br></font></div>'),
(268501, 'هموگلبین', '<span class=\"hlight\">هموگلبین .</span> <font color=\"DarkGreen\"><b>[ هَِ م ُ گْل ُ <span class=\"hlight\" dir=\"rtl\">/</span> گ ُ ل ُ ]</font></b> (فرانسوی، اِ) ماده ٔ آهن دار قرمزرنگ گلبولهای سرخ خون . (فرهنگ فرانسه به فارسی نفیسی ). که مرکب از هماتین و گلوبین است . (از گیاه شناسی ثابتی ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>).<br></font></div>'),
(268502, 'هموگلوبین', '<span class=\"hlight\">هموگلوبین .</span> <font color=\"DarkGreen\"><b>[ هَِ م ُ گْل ُ <span class=\"hlight\" dir=\"rtl\">/</span> گ ُ ل ُ ]</font></b> (فرانسوی، اِ) رجوع به هموگلبین شود.<br></font></div>'),
(268503, 'همپا', '<span class=\"hlight\">همپا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش ترک شهرستان میانه که <span class=\"hlight\" dir=\"rtl\">٣٤</span> تن سکنه دارد. آب آن از چشمه و محصول عمده اش غله است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(268504, 'همپا', '<span class=\"hlight\">همپا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش تکاب شهرستان مراغه که <span class=\"hlight\" dir=\"rtl\">٨٧٩</span> تن سکنه دارد. آب آن از چشمه ها و محصول عمده اش غله، بادام، حبوب و کرچک و کاردستی مردم گلیم بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268505, 'همپوست', '<span class=\"hlight\">همپوست .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b>(ص مرکب ) هم پوست . دو چیز که در یک پوست گنجد (یادداشت مؤلف )، چون دانه ٔ خشکبار یا مغز هسته ٔ میوه ها.<br></font></div>'),
(268506, 'همچ', '<span class=\"hlight\">همچ .</span><font color=\"DarkGreen\"><b>[ هََ م ِ ]</font></b> (اِخ ) دهی است از بخش خوسف شهرستان بیرجند که <span class=\"hlight\" dir=\"rtl\">٧١</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و پنبه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268507, 'همچ', '<span class=\"hlight\">همچ .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ غربی شهرستان رفسنجان . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268508, 'همچنو', '<span class=\"hlight\">همچنو.</span> <font color=\"DarkGreen\"><b>[ هََ چ ُ ]</font></b> (حرف اضافه + ضمیر) هم چنو. هم چون او. مانند او <span class=\"hlight\">:</span> <br>که بهرام فرزند او همچنوست <br>از آب پدر یافت او مغز و پوست .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268509, 'همچنین', '<span class=\"hlight\">همچنین .</span> <font color=\"DarkGreen\"><b>[ هََ چ ُ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (ق مرکب ) هم چنین . هم چون این . به معنی نیز و هم است . بدینگونه . هم بدین وضع. (یادداشتهای مؤلف ) <span class=\"hlight\">:</span> <br>دگر دست لشکَرْش را همچنین <br>سپاهی بیاراست گرد و گزین .<br> <font color=\"Red\">فردوسی .</font><br>که ماهوی را بادتن همچنین <br>فکنده پر از خون به روی زمین .<br> <font color=\"Red\">فردوسی .</font><br>ببر همچنین نزد آن پهلوان <br>بدان تا شود شاد و روشن روان .<br> <font color=\"Red\">فردوسی .</font><br>بپوشید رویش به دیبای چین <br>که مرگ بزرگان بود همچنین .<br> <font color=\"Red\">فردوسی .</font><br>تا بدین هفت فلک سیر کند هفت اختر<br>همچنین هفت پدیدار کند هفت اورنگ .<br> <font color=\"Red\">فرخی .</font><br>هندو جواب داد که همچنین است . (کلیله و دمنه ).<br>مرا همچنین چهره گلفام بود.<br> <font color=\"Red\">سعدی (بوستان ).</font><br>همچنین در زمره ٔ توانگران . (گلستان ).<br>اگر همچنین سر به خوددربرم <br>چه دانند مردم که دانشورم ؟<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(268510, 'همچو', '<span class=\"hlight\">همچو.</span> <font color=\"DarkGreen\"><b>[ هََ چ ُ ]</font></b> (حرف اضافه ٔ مرکب ) افاده ٔ معنی تشبیه کند. (آنندراج ). چون . مانند <span class=\"hlight\">:</span> <br>جز به مادندر نماند این جهان کینه جوی <br>با پسندر کینه دارد همچو با دختندرا.<br> <font color=\"Red\">رودکی .</font><br>ایستاده میان گرمابه <br>همچو آسغده در میان تنور.<br> <font color=\"Red\">معروفی بلخی .</font><br>ای همچو سگ پلید و چنو دیده ٔ برون <br>مانند آن کسی که مر او را کنی خپک .<br> <font color=\"Red\">دقیقی .</font><br>طفل را چون شکم به درد آید<br>همچو افعی ز رنج او برپیخت .<br> <font color=\"Red\">پروین خاتون .</font><br>که ای ناسزایان چه پیش آمده ست <br>که بدخواهتان همچو خویش آمده ست .<br> <font color=\"Red\">فردوسی .</font><br>سیاوش مرا همچو فرزند بود<br>که با فرّ و با برز و اورند بود.<br> <font color=\"Red\">فردوسی .</font><br>همه راغها شد چو پشت پلنگ <br>زمین همچو دیبای رومی به رنگ .<br> <font color=\"Red\">فردوسی .</font><br>آبی چو من مگر ز غم عشق زرد گشت <br>وز شاخ همچو چوک بیاویخت خویشتن .<br> <font color=\"Red\">بهرامی سرخسی .</font><br>همچو نوباوه برنهد برچشم <br>نامه ٔ او خلیفه ٔ بغداد.<br> <font color=\"Red\">فرخی .</font><br>گرچه زرد است همچو زرّ، پشیز<br>یا سپید است همچو سیم ارزیز.<br> <font color=\"Red\">لبیبی .</font><br>خواجه و سید سادات و رئیس رؤسا<br>همچو خورشید ببخشندگی و رخشانی .<br> <font color=\"Red\">منوچهری .</font><br>همی رفت جم پیش آن سعتری <br>چمان بر چمن همچو کبک دری .<br> <font color=\"Red\">اسدی .</font><br>همچو لؤلؤ کند ای پور تو را علم و عمل <br>ره باب تو همین است برو بر ره باب .<br> <font color=\"Red\">ناصرخسرو.</font><br>لاجرم خلق همه همچو امامان شده اند<br>یکسره مسخره و مطرب طرار و طناز.<br> <font color=\"Red\">ناصرخسرو.</font><br>سپس ِ بیهشان دهر مرو<br>گر نخوردی تو همچو ایشان بنگ .<br> <font color=\"Red\">ناصرخسرو.</font><br>همچو کتابی است جهان جامع احکام نهان <br>جان تو سردفتر آن فهم کن این مسأله را.<br> <font color=\"Red\">مولوی .</font><br>همچو ابلیسی که گفت : «اغویتنی »<br>تو شکستی جام و ما را میزنی .<br> <font color=\"Red\">مولوی .</font><br>بیا که رونق این کارخانه کم نشود<br>ز زهد همچو تویی یا ز فسق همچو منی .<br> <font color=\"Red\">حافظ.</font><br>همچو گلبرگ طری هست وجود تو لطیف <br>همچو سرو چمن خلد سراپای تو خوش .<br> <font color=\"Red\">حافظ.</font><br>همچو دیده به سوی خویش مبین <br>خویش را از دگران بیش مبین .<br> <font color=\"Red\">جامی .</font><br>همچو خورشید به ذرات جهان قسمت کن <br>گر نصیب تو ز گردون همه یک نان باشد.<br> <font color=\"Red\">صائب .</font><br> <BR><font color=\"Blue\">◄</font> (حرف ربط مرکب ) نیز. (آنندراج ). هم . همچنین <span class=\"hlight\">:</span> <br>تا نبود چون همای فرخ کرکس <br>همچو نباشد به شبه باز خشین پند.<br><font color=\"Red\">فرخی .</font><br></font></div>'),
(268511, 'همچون', '<span class=\"hlight\">همچون .</span> <font color=\"DarkGreen\"><b>[ هََ چُن ْ ]</font></b> (حرف اضافه ٔ مرکب ) همچو. مانند. چون . نظیر <span class=\"hlight\">:</span> <br>ایستاده دید آنجا دزد غول <br>روی زشت و چشمها همچون دغول .<br> <font color=\"Red\">رودکی .</font><br>انگِشت برِ رویش مانند بلور است <br>پولاد برِ گردن او همچون لاد است .<br> <font color=\"Red\">خسروانی .</font><br>گویی همچون فلان شدم نه همانا<br>هرگز چون عود کی تواند شد توغ ؟<br> <font color=\"Red\">منجیک .</font><br>فلک مر جامه ای را ماند ازرق <br>ورا همچون طراز خوب کرکم .<br> <font color=\"Red\">منجیک .</font><br>ای عشق ز من دور که بر من همه رنجی <br>همچون زبر چشم یکی محکم بالو.<br> <font color=\"Red\">شاکری .</font><br>یکی بیشه ای دید همچون بهشت <br>که گفتی سپهر اندر او لاله کشت .<br> <font color=\"Red\">فردوسی .</font><br>چو بشنید مهراب شد شادمان <br>به رخ گشت همچون گل ارغوان .<br> <font color=\"Red\">فردوسی .</font><br>چو بیرون شد از شهر خود با سپاه <br>بر او روز همچون شب آمد سیاه .<br> <font color=\"Red\">فردوسی .</font><br>همچون رطب اندام و چو روغَنْش سراپای <br>همچون شبه زلفان وچو پیلسته ش آلست .<br> <font color=\"Red\">عسجدی .</font><br>بیش بین چون کرکس و جولان کننده چون عقاب <br>راهوار ایدون چو کبک و راست رو همچون کلنگ .<br> <font color=\"Red\">منوچهری .</font><br>تاک رز را دید آبستن چون داهان <br>شکمش خاسته همچون دم روباهان .<br> <font color=\"Red\">منوچهری .</font><br>مردم اندرخور زمانه شده ست <br>نرد چون شاخ و شاخ همچون نرد.<br> <font color=\"Red\">کسائی .</font><br>... بیشتری از جهان گرفته و میگیرد، تو نیز همچون پدر باشی . (تاریخ بیهقی ).<br>چه مرد است آنکه همچون هم نباشد<br>مر او را در جهان گفتار و کردار.<br> <font color=\"Red\">مسعودسعد.</font><br>هیچ جنبنده نیست اندر زمین و نه هیچ پرنده اندر هوا که نه ایشان نیز همچون امتی اند. (ترجمه ٔ تفسیر طبری ). همچون کسانی نباشند که مشت در تاریکی زنند. (کلیله و دمنه ). بادی پیدا آید و آن را در حرکت آرد تا همچون آب پنیر گردد. (کلیله و دمنه ).<br>زیر آن اژدهای همچون قیر<br>می شد از ریزش آب معنی گیر.<br> <font color=\"Red\">نظامی .</font><br>لیکن برِ کوه قاف پیکر<br>همچون الف است هیچ در بر.<br> <font color=\"Red\">نظامی .</font><br>شب روشن روان ماه جهانتاب <br>گدازان گشت همچون برف در آب .<br> <font color=\"Red\">نظامی .</font><br>عمر همچون جوی نونو میرسد<br>مستمری مینماید در جسد.<br> <font color=\"Red\">مولوی .</font><br>دفتر صوفی سواد و حرف نیست <br>جز دل اسپید همچون برف نیست .<br> <font color=\"Red\">مولوی .</font><br>دگر با ما مگو ای باد گلبوی <br>که همچون بلبلم دیوانه کردی .<br> <font color=\"Red\">سعدی .</font><br>به گیتی بتر زین نباشد بدی <br>جفابردن از دست همچون خودی .<br> <font color=\"Red\">سعدی .</font><br>کافر ار قامت همچون بت زیبای تو بیند<br>بار دیگر نکند سجده ٔ بتهای رخامی .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(268512, 'همچونین', '<span class=\"hlight\">همچونین .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ق مرکب ) همچنین <span class=\"hlight\">:</span> <br>جهان این است و چونین بود تا بود<br>و همچونین بوداینند بارا.<br> <font color=\"Red\">رودکی .</font><br>و همچونین تا به آخر دیارمغرب بگرفت و فلسطین بگشاد. (فارسنامه ٔ ابن بلخی ). رجوع به همچنین شود.<br></font></div>'),
(268513, 'همک', '<span class=\"hlight\">همک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) ستیهانیدن کسی را در کار. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268514, 'همکار', '<span class=\"hlight\">همکار.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) شریک و هم پیشه . (آنندراج ) <span class=\"hlight\">:</span> <br>نه ز همدستان ماننده به هم دستی <br>نه ز همکاران ماننده بدو یک تن .<br> <font color=\"Red\">فرخی .</font><br>مشو یار بدخواه و همکار بد<br>که تنها بسی به که با یار بد.<br> <font color=\"Red\">اسدی .</font><br>هرکه را اختیار کند همکاران او رامطیع باشند. (تاریخ بیهقی ).<br>حدیث مدعیان و خیال همکاران <br>همان حکایت زردوز و بوریاباف است .<br> <font color=\"Red\">حافظ.</font><br>کار را بی کارفرما پیش بردن مشکل است <br>کارفرمایی به من از غیرت همکار ده .<br> <font color=\"Red\">صائب .</font><br>بیستون سینه را ناخن کند روی مسیح <br>پر به چشم کم مبین، همکار فرهاد است این .<br><font color=\"Red\">مسیح کاشی .</font><br></font></div>'),
(268515, 'همکاری', '<span class=\"hlight\">همکاری .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) هم پیشگی . <BR><font color=\"Blue\">◄</font> شرکت در کاری . (آنندراج ) <span class=\"hlight\">:</span> <br>از هم آرایشی و همکاری <br>هر یکی را دگر کند یاری .<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> رقابت <span class=\"hlight\">:</span> <br>یک دم از رشک تو آرام ندارد خورشید<br>هیچ دردی بتر از غیرت همکاری نیست .<br><font color=\"Red\">صائب .</font><br></font></div>'),
(268516, 'همکلام', '<span class=\"hlight\">همکلام .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ ]</font></b> (ص مرکب ) هم کلام . هم سخن . دو تن که با هم گفتگوکنند. <BR><font color=\"Blue\">◄</font> لقب مأمورانی که نادرشاه در هرشهر می گماشت تا اعمال و خیالات حکام را گزارش کنند وکارها به استصواب ایشان می گذشت . (یادداشت مؤلف ).<br></font></div>'),
(268517, 'همگان', '<span class=\"hlight\">همگان .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (ضمیر مبهم ) ج ِ همه . و به معنی همه و مجموع . (برهان ) <span class=\"hlight\">:</span> <br>مر مرا حاجت آمده ست امروز<br>به سخن گفتن شما همگان .<br> <font color=\"Red\">فرخی .</font><br>همگان حال من شنیدستید<br>بلکه دانسته اید و دیده عیان .<br> <font color=\"Red\">فرخی .</font><br>چند گاهی است که در آرزوی روی تو بود<br>صدر دیوان و بزرگان خراسان همگان .<br> <font color=\"Red\">فرخی .</font><br>بود آن همگان را غرض و مصلحت خویش <br>این را غرض و مصلحت شاه جهان است .<br> <font color=\"Red\">منوچهری .</font><br>نیست یک تن به میان همگان اندر به <br>این چنین زانیه باشند بچه ی ْ هر عنبی .<br> <font color=\"Red\">منوچهری .</font><br>همگان می گفتند که حال بوسعید چون شود با حاصلی بدین عظیمی ؟ (تاریخ بیهقی ). پس از آنکه حصار ستده آمد لشکر دیگر دررسید و همگان آفرین کردند. (تاریخ بیهقی ). مقرر گشت همگان را که کار وزارت قرار گرفت . (تاریخ بیهقی ).<br>پرکینه مباش از همگان دایم چون خار<br>نه نیز زبون باش به یک بار چو خرما.<br> <font color=\"Red\">ناصرخسرو.</font><br>ازبهر قضا خواستن و خوردن رشوت <br>فتنه همگان بر کتب بیع و شرااند.<br> <font color=\"Red\">ناصرخسرو.</font><br>عقل و معقول هر دوان جفتند<br>همگان جفت کرده ٔ سبحان .<br> <font color=\"Red\">ناصرخسرو.</font><br>با هرکس منشین و مَبُر از همگان نیز<br>بر راه خرد رو، نه مگس باش و نه عنقا.<br> <font color=\"Red\">ناصرخسرو.</font><br>همه چیز را همگان دانند. (قابوسنامه ).<br>ازتو شادی است قسمت همگان <br>غم دل قسم من چرا باشد؟<br> <font color=\"Red\">مسعودسعد.</font><br>چون بخواند همگان خیره بماندند. (کلیله و دمنه ). لیکن همگان را بنده ٔ دینار و درم می بینم . (کلیله و دمنه ).<br>سر من دار که چشم از همگان بردارم <br>دست من گیر که دست از دوجهان بردارم .<br> <font color=\"Red\">سعدی .</font><br>از همگان بی نیاز و بر همه مشفق <br>از همه عالم نهان و بر همه پیدا.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(268518, 'همگانی', '<span class=\"hlight\">همگانی .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (ص نسبی ) کلی . عمومی و متعلق به همه . (یادداشتهای مؤلف ).<br></font></div>'),
(268519, 'همگر', '<span class=\"hlight\">همگر.</span> <font color=\"DarkGreen\"><b>[ هََ گ َ ]</font></b> (ص مرکب ) به هم کننده و پیونددهنده ٔ چیزها. (انجمن آرا). جولاهه و بافنده . (برهان ).<br></font></div>'),
(268520, 'همگر', '<span class=\"hlight\">همگر.</span> <font color=\"DarkGreen\"><b>[ هََ گ َ ]</font></b> (اِخ ) مجدالدین . از شعرای قرن هفتم هجری است . او را در ادبیات فارسی غالباً از روی حکمی که در مقایسه ٔ امامی هروی و سعدی کرده است می شناسند. سه شاعر معاصر بوده اند. نوشته اند که بعضی از معاصران عقیده ٔ او را درباره ٔ امامی هروی و سعدی و رجحان یکی بر دیگری پرسیده اند و او گفته است :<br>در شیوه ٔ شاعری به اجماع امم <br>هرگز من وسعدی به امامی نرسیم .<br>و میگویند سعدی این شعر را شنیده و رنجیده و به طنز گفته است :<br>همگر که به عمر خود نکرده ست نماز<br>آری چه عجب گر به امامی نرسد؟<br>آگاهی از او و زندگیش بسیار نیست . همگر به معنی بافنده و جولاهه است و این شاید شغل خانوادگی او یا شغل نخستین خودش بوده است . اصل او از یزد بوده و در حمایت بهاءالدین جوینی حکمران عراق و فارس میزیسته است که در سال <span class=\"hlight\" dir=\"rtl\">٦٧٨</span> هَ . ق . وفات یافت . از زندگی او جز این چیزی نمی دانیم . عبید زاکانی یکی دو حکایت مزاح آمیز درباره ٔ او و بهاءالدین جوینی صاحبدیوان آورده است . تاریخ وفات او را به سال <span class=\"hlight\" dir=\"rtl\">٦٨٦</span> نوشته اند. از بیت های معدودی که در جُنگها و تذکره ها از او نقل کرده اند پیداست که شاعری پرمایه و لطیف طبع بوده است . او راست :<br>باز این مخالفان که ره جنگ میزنند<br>بر ساز ما نوای کج آهنگ میزنند.<br>بر عشق خوب ما رقم زشت می کشند<br>بر نام وننگ ما دغل ننگ میزنند.<br>سنگین دلان تیره ضمیر از خلاف عهد<br>بر آبگینه ٔ دل ما سنگ میزنند<br>هر لحظه از گشاد ملامت هزار تیر<br>بر قلب این شکسته ٔ دلتنگ میزنند<br>می ننگرندعیب گریبان خویشتن <br>در دامن حکایت ما چنگ میزنند<br>بر آستان صلح نهادیم سر چو سگ <br>وین سگدلان هنوز ره جنگ میزنند.<br>نیز این غزل از اوست :<br>عالم پر از حکایت درد دل من است <br>در قصه ٔ من اندر اگر مرد اگر زن است <br>گر دشمن است بر من مظلوم خرم است <br>ور دوست است بر من محروم بدظن است <br>عشق از ازل درآمد و شد با جهان کهن <br>این رسم عاشقی نه نوآورده ٔ من است <br>مسکین دلم ز تاب غم و سرزنش گداخت <br>گر دل دل من است نه از سنگ و آهن است <br>چون شمع نیم سوخته نادیده صبح وصل <br>در شامگاه هجر مرا بیم کشتن است <br>گردن نهاده ام به قضا زآنکه عشق را<br>خون دوصدهزار به از من بگردن است .<br>رجوع به مجله ٔ سخن دوره ٔ <span class=\"hlight\" dir=\"rtl\">١٦</span> شماره ٔ <span class=\"hlight\" dir=\"rtl\">١</span> شود.<br></font></div>'),
(268521, 'همگن', '<span class=\"hlight\">همگن .</span> <font color=\"DarkGreen\"><b>[ هََ گ ِ ]</font></b> (ص مرکب ) همگین . انباز. شریک .(یادداشت مؤلف ). ج، همگنان . رجوع به همگنان شود.<br></font></div>'),
(268522, 'همگنان', '<span class=\"hlight\">همگنان .</span> <font color=\"DarkGreen\"><b>[ هََ گ ِ ]</font></b> (ضمیر مبهم مرکب ) جمع همگن (= همگینان، ج ِ همگین ). در پهلوی هموگن  یا همغن  به معنی همه است و بنابراین کسانی که این کلمه را به ضم کاف تازی تلفظ کنند در اشتباه اند. (از حواشی معین بر برهان ). ج ِ همگن . همگینان . (یادداشت مؤلف ). گروه و جماعت حاضر. <BR><font color=\"Blue\">◄</font> همه و مجموع . (برهان ). رجوع به همگن و همگین شود. <BR><font color=\"Blue\">◄</font> همجنسان و هم چشمان و همکاران . (برهان ). کسانی که با هم رتبه و درجه ٔ برابر دارند <span class=\"hlight\">:</span> <br>همه همگنان خاک دادند بوس <br>چو رهام و گرگین و گودرز و طوس .<br> <font color=\"Red\">فردوسی .</font><br>شما سربه سر همگنان همگروه <br>مباشید از آن نامداران ستوه .<br> <font color=\"Red\">فردوسی .</font><br>همه همگنان رزمساز آمدیم <br>به یاری ز راه دراز آمدیم .<br><font color=\"Red\">فردوسی .</font><br>چونین تو بتا ز همگنان برمگذر<br>نتوان به تکی به طوس شد جان پدر.<br> <font color=\"Red\">فرخی .</font><br>همگنان را منفعت حاصل می آید و او از آن بی خبر. (کلیله و دمنه ).<br>بر پای نشستم آخرالامر.<br>چونان که مراد همگنان بود.<br> <font color=\"Red\">انوری .</font><br>چو خنجر تو همه ابر رحمت است چرا<br>هزار صاعقه در جان همگنان افکند؟<br> <font color=\"Red\">ظهیر فاریابی .</font><br>بزرگوارا من در میان اهل عراق <br>به نعمت تو چه محسود همگنان بودم .<br> <font color=\"Red\">ظهیر فاریابی .</font><br>همگنان دانند که از صفای نیت و صرف همت به کار تو هرگز خالی نبوده ام . (مرزبان نامه ). نفوس همگنان را در کربت آمیخت . (ترجمه ٔ تاریخ یمینی ). همگنان را به مدد میعادکرد که آن جایگاه مجتمع شوند. (ترجمه ٔ تاریخ یمینی ). همگنان مجتمعالهمّه و متفق الکلمه گشتند. (ترجمه ٔ تاریخ یمینی ).<br>بفرمود ترتیب کردند خوان <br>نشستندبر هر طرف همگنان .<br> <font color=\"Red\">سعدی .</font><br>در دولت خداوندی همگنان را راضی کردم مگر حسود را. (گلستان ). اگر به یک بیت از من قناعت کنید بگویم، همگنان به رغبت گفتند: بگوی . (گلستان ). رجوع به همگنان شود.<br></font></div>'),
(268523, 'همگونه', '<span class=\"hlight\">همگونه .</span> <font color=\"DarkGreen\"><b>[ هََ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب ) هم گونه . مانند. همانند <span class=\"hlight\">:</span> <br>چه برسان پرّنده و چارپای <br>چه همگونه ٔ دیو مردم نمای .<br> <font color=\"Red\">اسدی .</font><br>ماننده و همگونه ٔ جد و پدرخویش <br>در صدر چو پیغمبر و در حرب چو حیدر.<br> <font color=\"Red\">ناصرخسرو.</font><br> <BR><font color=\"Blue\">◄</font> همرنگ <span class=\"hlight\">:</span> <br>از آن شد رنگ من همگونه ٔ برد<br>تو کندی جوی و آبش دیگری برد.<br> <font color=\"Red\">فخرالدین اسعد.</font><br>رخم ز چشمم همچهره ٔ تذرو شود<br>چو تیره شب را همگونه ٔ غراب کنند.<br><font color=\"Red\">مسعودسعد.</font><br></font></div>'),
(268524, 'همگویه', '<span class=\"hlight\">همگویه .</span><font color=\"DarkGreen\"><b>[ هََ ی َ ]</font></b> (اِخ ) دهی است از بخش زرند شهرستان کرمان که <span class=\"hlight\" dir=\"rtl\">٦٦٠</span> تن سکنه دارد. آب آن از قنات و محصول عمده اش غله و حبوب است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268525, 'همگی', '<span class=\"hlight\">همگی .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (ضمیر مبهم، ق ) تمامی و همه . (از غیاث ). جملگی . کلاً. یکسر. یکسره . (یادداشت مؤلف ) <span class=\"hlight\">:</span> جبرئیل بیامد و پری بزد قصر ملک و همه ٔ حشم را بر زمین فروبرد و همگی هلاک شدند. (قصص الانبیاء).<br>خیز نظامی نه گه خفتن است <br>وقت به ترک همگی گفتن است .<br> <font color=\"Red\">نظامی .</font><br>شاه بدان صید چنان صید شد<br>که ش همگی بسته ٔ آن قید شد.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268526, 'همگین', '<span class=\"hlight\">همگین .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) هم گین . همگن . مانند هم . <BR><font color=\"Blue\">◄</font> دوست . قرین . نزدیک . رجوع به همگن و همگنان شود.<br></font></div>'),
(268527, 'همگین', '<span class=\"hlight\">همگین .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ <span class=\"hlight\" dir=\"rtl\">/</span> هََ ]</font></b> (ضمیر مبهم، ق ) همگی . همه . (از آنندراج ) <span class=\"hlight\">:</span> <br>دل سپاه و رعیت بدوگرفت قرار<br>بدو فتاد امید جهانیان همگین .<br> <font color=\"Red\">فرخی .</font><br>زرّ تو و سیم تو همه خلق جهان راست <br>وین حال بدانند همه گیتی همگین .<br> <font color=\"Red\">فرخی .</font><br>بی گمان گردی اگر نیک بیندیشی <br>که بدل خفته ست این خلق همی همگین .<br> <font color=\"Red\">ناصرخسرو.</font><br>شاخها ازبرای خدمت را<br>کوژ کردند پشتها همگین .<br> <font color=\"Red\">مسعودسعد.</font><br>در هم شدند لشکر، بر هم زدند همگین <br>آن تاجهای زرین وآن تختهای سیمین .<br><font color=\"Red\">امیرمعزی .</font><br></font></div>'),
(268528, 'همگین', '<span class=\"hlight\">همگین .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان شهرضا. <span class=\"hlight\" dir=\"rtl\">٨١٤</span> تن سکنه دارد. آب آن از چشمه و قنات و محصولش غله، پنبه، لبنیات، میوه، و کاردستی زنان جاجیم بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268529, 'همی', '<span class=\"hlight\">همی .</span> <font color=\"DarkGreen\"><b>[ هََ م ْی ْ <span class=\"hlight\" dir=\"rtl\">/</span> هَُ می ی ]</font></b> (ع مص ) روان گشتن آب و اشک . <BR><font color=\"Blue\">◄</font> ریختن چشم اشک را. <BR><font color=\"Blue\">◄</font> رمیدن و پراکنده رفتن ماشیه به چراگاه . <BR><font color=\"Blue\">◄</font> اوفتادن چیزی . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268530, 'همی', '<span class=\"hlight\">همی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (پیشوند) به جهت استمرار و امتداد در فعل آید و پیش یا پس از فعل قرار گیرد. (از آنندراج ) <span class=\"hlight\">:</span> <br>بوی جوی مولیان آید همی <br>یاد یار مهربان آیدهمی .<br> <font color=\"Red\">رودکی .</font><br>به راه اندر همی شد، شاهراهی <br>همی شد تا بنزد پادشاهی .<br> <font color=\"Red\">رودکی .</font><br>همی گفت کاین رسم گهبذ نهاد<br>از او دل بگردان که بس بد نهاد.<br> <font color=\"Red\">ابوشکور.</font><br>به کردار، نیکی همی کردمی <br>وز الفغده ٔ خود همی خوردمی .<br> <font color=\"Red\">ابوشکور.</font><br>خورشید تیغ تیز تو را آب میدهد<br>مریخ نوک نیزه ٔ تو سان همی زند.<br> <font color=\"Red\">ابوشکور.</font><br>همی حسد کنم و سال و ماه رشک برم <br>به مرگ بوالمثل و مرگ شاکر جلاب .<br> <font color=\"Red\">ابوطاهر خسروانی .</font><br>آس شدم زیر آسیای زمانه <br>نیست بخواهم شدن همی به کرانه .<br> <font color=\"Red\">کسایی .</font><br>پدرْت از غم او بکاهد همی <br>کنون کین او خواست خواهد همی .<br> <font color=\"Red\">فردوسی .</font><br>همی گفت بدروز و بداخترم <br>بد از دانش آمد همی بر سرم .<br> <font color=\"Red\">فردوسی .</font><br>برفتند گردان تازی ز جای <br>همی سر ندانست جنگی ز پای .<br> <font color=\"Red\">فردوسی .</font><br>از پدر چون از پدندر دشمنی بیند همی <br>مادر از کینه بر او مانند مادندر شود.<br> <font color=\"Red\">لبیبی .</font><br>زو دوست ترم هیچ کسی نیست وگر هست <br>آنم که همی گویم پازند قران است .<br> <font color=\"Red\">فرخی (از لغت فرس اسدی ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span>).</font><br>همی نگون شود از هیبت نهیب تو را<br>به ترک، خانه ٔ خان و به هند رایت رای .<br> <font color=\"Red\">عنصری .</font><br>رزبان گفت چه رای است و چه تدبیر همی <br>مادر این بچگکان را ندهد شیر همی ؟<br> <font color=\"Red\">منوچهری .</font><br>همی دوم به جهان اندر از پی روزی <br>دو پای پر شغه و مانده با دلی بریان .<br> <font color=\"Red\">عسجدی .</font><br>ایشان در زیر قبای من همی پریدندی . (تاریخ بیهقی ). همی گوید ابوالفضل محمدبن حسین البیهقی ... (تاریخ بیهقی ).<br>همچو ماهی یکی گروه از حرص <br>یکدگر را همی بیوبارند.<br> <font color=\"Red\">ناصرخسرو.</font><br>همی تا جهان است و این چرخ اخضر<br>بگردد همی گرد این گوی اغبر.<br> <font color=\"Red\">ناصرخسرو.</font><br>روزی و عمر خلق به تقدیر ایزدی <br>این دستها همی بنویسند و بسترند.<br> <font color=\"Red\">ناصرخسرو.</font><br>ایوان کسری به مداین ... شاپور ذوالاکتاف بنا افکند و بعد از او چند پادشاه عمارت همی کردند تا بر دست انوشیروان عادل تمام شد. (نوروزنامه ).<br>در فراق آن نگار گلرخ شمشادقد<br>لاله ٔ رخسار من چون زعفران گردد همی .<br> <font color=\"Red\">رشید وطواط.</font><br>سنگی است که گوهری را همی شکند. (گلستان ).<br>خیز تا خاطر بدان ترک سمرقندی دهیم <br>کز نسیمش بوی جوی مولیان آید همی .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(268531, 'همی جان', '<span class=\"hlight\">همی جان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش بافق شهرستان یزد. دارای <span class=\"hlight\" dir=\"rtl\">٣٦٢</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله، گردو، بادام و زردآلو، و کار دستی زنان کرباس بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268532, 'همیان', '<span class=\"hlight\">همیان .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (ع مص ) روان گشتن آب و اشک . <BR><font color=\"Blue\">◄</font> ریختن چشم اشک را. <BR><font color=\"Blue\">◄</font> رمیدن و پراکنده رفتن ماشیه به چراگاه .(منتهی الارب ) (اقرب الموارد). رجوع به هَمْی شود.<br></font></div>'),
(268533, 'همیان', '<span class=\"hlight\">همیان .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ ]</font></b> (ع اِ) اِزاربند. <BR><font color=\"Blue\">◄</font> کمربند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کیسه ای که در آن درهم نهند. (منتهی الارب ). ج، همایین . (اقرب الموارد). گویند: له همیان ؛ یعنی سرین بزرگی دارد. (از ناظم الاطباء). در معنی کیسه ٔ هزینه ظاهراً معرب همیان فارسی به فتح اول است .<br></font></div>'),
(268534, 'همیان', '<span class=\"hlight\">همیان .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ]</font></b> (اِ) بر وزن انبان، کیسه ای باشد طولانی که بر کمر بندند و به عربی صره خوانند. (برهان ) <span class=\"hlight\">:</span> <br>قیمت همیان و کیسه از زر است <br>بی زری همیان و کیسه ابتر است .<br> <font color=\"Red\">مولوی .</font><br>خواجه هر جا قصه ٔ پیراهن یوسف شنید<br>پیش چشمش جلوه ٔ همیان درهم می کند.<br> <font color=\"Red\">کلیم .</font><br>دنیاطلب از موی میانان نشد آگاه <br>بس دیده که او حسن کمر در همیان یافت .<br> <font color=\"Red\">کلیم (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٤٩</span>).</font><br>رجوع به انبان شود.<br></font></div>'),
(268535, 'همیانه', '<span class=\"hlight\">همیانه .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ن ِ ]</font></b> (اِخ ) دهی است از بخش دورود شهرستان بروجرد. دارای <span class=\"hlight\" dir=\"rtl\">٣٢٨</span> تن سکنه، آب آن از قنات، محصول عمده اش غله و لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268536, 'همیانک', '<span class=\"hlight\">همیانک .</span> <font color=\"DarkGreen\"><b>[ هََ م ْ ن َ ]</font></b> (اِخ ) دهی از بخش کنگاور شهرستان کرمانشاهان . دارای <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268537, 'همیج', '<span class=\"hlight\">همیج .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) آهوی ماده ٔ جوانه ٔباریک شکم . <BR><font color=\"Blue\">◄</font> آهوی ماده ای که در دو تهیگاه وی دو خط باشد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268538, 'همیدون', '<span class=\"hlight\">همیدون .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ق مرکب ) مخفف هم ایدون است یعنی همین دم و همین زمان و همین ساعت و هم اکنون . (برهان ). اکنون . حالا <span class=\"hlight\">:</span> <br>کنون کشتن رستم آریم پیش <br>ز دفتر همیدون به گفتار خویش .<br> <font color=\"Red\">فردوسی .</font><br>سزد گر نیاری به جانشان گزند<br>سپاری همیدون به من شان، به بند.<br> <font color=\"Red\">فردوسی .</font><br>ز گردنده گردون نداری خبر<br>که اخگرْت ریزد همیدون به سر.<br> <font color=\"Red\">فردوسی .</font><br> <BR><font color=\"Blue\">◄</font> همچنین . نیز. هم . (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>همی رفت با او همیدون به راه <br>بر او راز نگشاد تا چند گاه .<br> <font color=\"Red\">فردوسی .</font><br>کشوری خالی نخواهد بود از عمال او<br>ور همیدون هفت کشور هفتصد کشور شود.<br> <font color=\"Red\">فرخی .</font><br>ای بوالفرخج ساوه همیدون همه فرخج <br>نامت فرخج و کنیت ملعونت بوالفرخج .<br> <font color=\"Red\">لبیبی .</font><br>و آن نار همیدون به زنی حامله ماند<br>وندر شکم حامله مشتی پسران است .<br><font color=\"Red\">منوچهری .</font><br>پاینده همی بادا هرچ آن تو نهادی <br>همواره همیدون به سلامت بزیادی .<br> <font color=\"Red\">منوچهری .</font><br>هزار سال همیدون بزی به پیروزی <br>به مردمی و به آزادگی و نیکی خوی .<br> <font color=\"Red\">منوچهری .</font><br>ز گرگان آبنوش ماه پیکر<br>همیدون از دهستان ناز دلبر.<br> <font color=\"Red\">فخرالدین اسعد.</font><br>نبید خورده ناید بازجامت <br>همیدون مرغ جسته باز دامت .<br> <font color=\"Red\">فخرالدین اسعد.</font><br>سپردم مشک خود باد وزان را<br>همیدون میش خود گرگ ژیان را.<br> <font color=\"Red\">فخرالدین اسعد.</font><br>به یک مرد گردد شکسته سپاه <br>همیدونش یک مرد دارد نگاه .<br> <font color=\"Red\">اسدی .</font><br>همیدون تموز و دیش چاکر است <br>بهارش مثال خزان زرگر است .<br> <font color=\"Red\">اسدی .</font><br>کهن بهتر از رنگ یاقوت و زر<br>همیدون می از نو کهن نیک تر.<br> <font color=\"Red\">اسدی .</font><br>نبد چیز از آغاز و او بود و بس <br>نماند همیدون جز او هیچ کس .<br> <font color=\"Red\">اسدی .</font><br>نه آشوب گیتی به هنگام توست <br>که تا بد همیدون بدی از نخست .<br> <font color=\"Red\">اسدی .</font><br>که پرسد زین غریب خوار محزون <br>خراسان را که بی من حال تو چون ؟<br>همیدونی که من دیدم به نوروز؟<br>خبر بفرست اگر هستی همیدون .<br> <font color=\"Red\">ناصرخسرو.</font><br>ملک جهان گر به دست دیوان بد<br>باز کنون حالها همیدون شد.<br> <font color=\"Red\">ناصرخسرو.</font><br>وصفت نمی کنم به زبانی که هم بدان <br>بر شاه شرق و غرب همیدون ثنا کنم .<br> <font color=\"Red\">مسعودسعد.</font><br>آری جوان و پیر همیدون چنین بوند<br>کاین راز خود پدید کند و آن کند نهان .<br> <font color=\"Red\">مسعودسعد.</font><br>ای پیشه کرده نوحه به درد گذشته عمر<br>با خویشتن همیشه همیدون همی ژکی .<br> <font color=\"Red\">لؤلؤیی .</font><br>چنین گوید همیدون مرد فرهنگ <br>که شبدیز آمده ست از نسل آن سنگ .<br> <font color=\"Red\">نظامی .</font><br>گرایدون که آید فریدون به من <br>گرفتار گردد همیدون به من .<br> <font color=\"Red\">نظامی .</font><br>همیدون شیر اگر شیرین نبودی <br>به طفلی خلق را تسکین نبودی .<br> <font color=\"Red\">نظامی .</font><br>همیدون جام گیتی خوشگوار است <br>به اول مستی و آخر خمار است .<br> <font color=\"Red\">نظامی .</font><br>ز دانا بپرسید کاین چشمه چیست ؟<br>همیدون نگهبان این چشمه کیست ؟<br> <font color=\"Red\">نظامی .</font><br>وز انعامت همیدون چشم داریم <br>که دیگر بازنستانی عطا را.<br> <font color=\"Red\">سعدی .</font><br>همیدون بود منفعت در نبات <br>اگر خواجه را مانده باشد حیات .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(268539, 'همیدیگان', '<span class=\"hlight\">همیدیگان .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از بخش کنارک شهرستان چاه بهار. دارای <span class=\"hlight\" dir=\"rtl\">١٢٥</span> تن سکنه، آب آن از چاه و باران و محصول عمده اش غله، ذرت و لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268540, 'همیر', '<span class=\"hlight\">همیر.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) پیرزن میرنده . <BR><font color=\"Blue\">◄</font> ظبی همیر؛ آهوی خوش اندام . (اقرب الموارد). ظبیة همیر؛ آهوی ماده ٔ نیکواندام . (منتهی الارب ).<br></font></div>'),
(268541, 'همیری', '<span class=\"hlight\">همیری .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش قشم شهرستان بندرعباس . دارای <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه، آب آن از چاه و باران و محصول عمده اش خرما است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268542, 'همیری', '<span class=\"hlight\">همیری .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش قصرقند شهرستان چاه بهار. دارای <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> تن سکنه، آب آن از رودخانه و محصول عمده اش غله، برنج، خرما و لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268543, 'همیز', '<span class=\"hlight\">همیز.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) رجل همیزالفؤاد؛ مرد تیزخاطر. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268544, 'همیز', '<span class=\"hlight\">همیز.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) به لغت زندو پازند به معنی تابستان باشد و به جای زا، نون هم به نظر آمده است که همین باشد بر وزن زمین . (برهان ).<br></font></div>'),
(268545, 'همیس', '<span class=\"hlight\">همیس .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) آواز نعل سپل شتر. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268546, 'همیسع', '<span class=\"hlight\">همیسع.</span> <font color=\"DarkGreen\"><b>[ هََ م َ س َ ]</font></b> (ع ص ) مرد توانا ونیک قوی که کسی نتواند او را بر زمین افکند. <BR><font color=\"Blue\">◄</font> مرد درازبالا. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268547, 'همیسع', '<span class=\"hlight\">همیسع.</span> <font color=\"DarkGreen\"><b>[ هََ م َ س َ ]</font></b> (اِخ ) پدر حِمْیَربن سباء. (اقرب الموارد). رجوع به حِمْیَر و سباء شود.<br></font></div>'),
(268548, 'همیسع', '<span class=\"hlight\">همیسع.</span> <font color=\"DarkGreen\"><b>[ هََ م َ س َ ]</font></b> (اِخ ) نام جد بیست وسوم حضرت رسول اکرم . (از سمعانی ).<br></font></div>'),
(268549, 'همیشه', '<span class=\"hlight\">همیشه .</span> <font color=\"DarkGreen\"><b>[ هََ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ق ) دائم . همواره . همه ٔ اوقات <span class=\"hlight\">:</span> <br>بتا، نگارا! از چشم بد بترس و مکن <br>چرا نداری با خود همیشه چشم پنام ؟<br> <font color=\"Red\">شهید بلخی .</font><br>بخل همیشه چنان ترابد از آن روی <br>کآب چنان از سفال نو بترابد.<br> <font color=\"Red\">خسروانی .</font><br>همیشه کفش و پیش را کفیده بینم من <br>به جای کفش و پیش دل کفیده بایستی .<br> <font color=\"Red\">معروفی بلخی .</font><br>ایا نشسته به اندیشگان حزین و نژند<br>همیشه اختر تو پست و همت تو بلند.<br> <font color=\"Red\">آغاجی .</font><br>به ابر رحمت ماند همیشه دست امیر<br>چگونه ابر؟ کجا توتکیش باران است .<br> <font color=\"Red\">عماره ٔ مروزی .</font><br>شنیدم که گشتاسب را خویش بود<br>پسر را همیشه بداندیش بود.<br> <font color=\"Red\">فردوسی .</font><br>خردمند گفت ای گرانمایه شاه <br>همیشه به تو تازه بادا کلاه .<br> <font color=\"Red\">فردوسی .</font><br>چو او را به رزم اندرون دیدمی <br>همیشه از این روز ترسیدمی .<br> <font color=\"Red\">فردوسی .</font><br>باغبان شد به سوی رز به سحرگاهان <br>که دلش بود همیشه سوی رز خواهان .<br> <font color=\"Red\">منوچهری .</font><br>اگر عقل فانی نگردد تو عقلی <br>وگر جان همیشه بماند تو جانی .<br> <font color=\"Red\">منوچهری .</font><br>همیشه در فزع از وی سپاهیان ملوک <br>چنان کجا به نواحی عقاب بر خرچال .<br> <font color=\"Red\">زینبی .</font><br>همیشه این دولت بزرگ پاینده باد و هر روزی فزونتر. (تاریخ بیهقی ). همیشه میخواستم که آن را بشنوم از معتمدی که آن را به رأی العین دیده باشد. (تاریخ بیهقی ). همیشه چشم نهاده بود تا پادشاهی بزرگ و جبار بر چاکری خشم گرفتی آنگاه او از کرانه بجستی و گفتی ... فلان را من فروگرفتم . (تاریخ بیهقی ). ایزدتعالی همیشه ملک رادوستکام داراد. (کلیله و دمنه ). همیشه حکمای هر صنف از اهل علم میکوشند تا... (کلیله و دمنه ). و به حال خردمند آن لایقتر که همیشه طلب آخرت را بر دنیا مقدم دارد. (کلیله و دمنه ).<br>چو چشم بد همیشه دورم از تو<br>چو بدخواه لبت رنجورم از تو.<br> <font color=\"Red\">نظامی .</font><br>از آن به دیرمغانم عزیز میدارند<br>که آتشی که نمیرد همیشه در دل ماست .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(268550, 'همیشه بهار', '<span class=\"hlight\">همیشه بهار.</span> <font color=\"DarkGreen\"><b>[ هََ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ب َ]</font></b> (اِ مرکب ) حی العالم . همیشک . همیشک جوان . (یادداشت مؤلف ). رجوع به این کلمات و نیز رجوع به همیشه جوان شود. <BR><font color=\"Blue\">◄</font> قسمی بابونه . (ناظم الاطباء). دارای گلهای زرد و نارنجی است که گلبرگ های متعدد دارد.<br></font></div>'),
(268551, 'همیشه بور', '<span class=\"hlight\">همیشه بور.</span> <font color=\"DarkGreen\"><b>[ هََ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِخ ) دهی است از بخش خرم آباد شهرستان شهسوار. دارای <span class=\"hlight\" dir=\"rtl\">١٩٠</span> تن سکنه، آب آن از رودخانه ٔ چشمه ٔ کیله، محصول عمده اش برنج و مرکبات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(268552, 'همیشه جوان', '<span class=\"hlight\">همیشه جوان .</span> <font color=\"DarkGreen\"><b>[ هََ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ج َ ]</font></b> (اِ مرکب ) ابرون . (مخزن الادویه ). رجوع به همیشک جوان شود.<br></font></div>'),
(268553, 'همیشه هست', '<span class=\"hlight\">همیشه هست .</span> <font color=\"DarkGreen\"><b>[ هََ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ هََ ]</font></b> (اِخ ) اسم پاک لفظ الباقی است یعنی ذاتی که فنا را در ساحت کبریای او راه نیست . (انجمن آرا). خداوند. اﷲ.<br></font></div>'),
(268554, 'همیشه کشیک', '<span class=\"hlight\">همیشه کشیک .</span> <font color=\"DarkGreen\"><b>[ هََ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (اِ مرکب ) نام گروهی از سپاهیان قزلباش . (یادداشت مؤلف ). رجوع به تذکرةالملوک چ <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩</span> و <span class=\"hlight\" dir=\"rtl\">٤٠</span> شود.<br></font></div>'),
(268555, 'همیشک', '<span class=\"hlight\">همیشک .</span> <font color=\"DarkGreen\"><b>[ هََ ش َ ]</font></b> (اِ) نامی است که در نور و کجور به نوعی درخت دهند و در مازندران قَلَم (به فتح اول و ثانی ) و در گرگان چلم و در رامیان مازرا گویندو در نقاط مختلف گیلان نامهای دیگر بر آن نهاده اند. بوته ای زینتی است که همیشه سبز است . اردشیرجان . حی العالم . (از یادداشت مؤلف ). رجوع به همیشک جوان شود.<br></font></div>'),
(268556, 'همیشک جوان', '<span class=\"hlight\">همیشک جوان .</span> <font color=\"DarkGreen\"><b>[ هََ ش َ ج َ ]</font></b> (اِ مرکب ) درختی است که برگهایش همیشه سبز باشد و به تازی حی العالم خوانند و آن راهمیشه بهار نیز گویند. (انجمن آرا). و در دواها به کار برند. (آنندراج ). رجوع به همیشه بهار شود. <BR><font color=\"Blue\">◄</font> نام یک جزو از اجزای اکسیر هم هست . (برهان ).<br></font></div>'),
(268557, 'همیشگی', '<span class=\"hlight\">همیشگی .</span> <font color=\"DarkGreen\"><b>[ هََ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (حامص ) مداومت و پیوستگی . (آنندراج ). دوام . دیمومت . (السامی ). <BR><font color=\"Blue\">◄</font> ازلیت . قدم . (السامی ). <BR><font color=\"Blue\">◄</font> (ق ) برای همیشه . دائما. به طور دائم <span class=\"hlight\">:</span> <br>به سرای سپنج مهمان را<br>دل نهادن همیشگی نه رواست .<br> <font color=\"Red\">رودکی .</font><br> <BR><font color=\"Blue\">◄</font> (ص نسبی ) دائمی . جاودان <span class=\"hlight\">:</span> <br>بقاش باد و دولت همیشگی <br>رسیده در حسود او بلای او.<br> <font color=\"Red\">منوچهری .</font><br>رجوع به همیشه شود.<br></font></div>'),
(268558, 'همیع', '<span class=\"hlight\">همیع.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ ی َ ]</font></b> (ع ص ) همیغ. رجوع به همیغ شود.<br></font></div>'),
(268559, 'همیغ', '<span class=\"hlight\">همیغ.</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ ی َ ]</font></b> (ع ص ) مرگ شتاب کش . (منتهی الارب ). و به عین مهمله تصحیف است . (اقرب الموارد).<br></font></div>'),
(268560, 'همیلا', '<span class=\"hlight\">همیلا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام یکی ازندیمه های شیرین در خسرو و شیرین نظامی <span class=\"hlight\">:</span> <br>فرنگیس و سهیل سروبالا<br>عجب نوش و فلکناز و همیلا.<br> <font color=\"Red\">نظامی .</font><br>همیلا گفت : آبی بود روشن <br>روان گشته میان سبز گلشن .<br> <font color=\"Red\">نظامی .</font><br>رجوع به خسرو و شیرین چ وحید ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span> شود.<br></font></div>'),
(268561, 'همیم', '<span class=\"hlight\">همیم .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) نرم رفتن حشرات به زمین و خزیدن . <BR><font color=\"Blue\">◄</font> (ص، اِ) باران سست و نرم . <BR><font color=\"Blue\">◄</font> شیر که در مشک اندازند وخورند و دوغ نزنند. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268562, 'همیمة', '<span class=\"hlight\">همیمة.</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (ع ص، اِ) باران سست و نرم . (منتهی الارب ). ج، همائم . (اقرب الموارد).<br></font></div>'),
(268563, 'همین', '<span class=\"hlight\">همین .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب، ق مرکب ) (از: هم + این ) فقط این . این بس است . تنها این <span class=\"hlight\">:</span> <br>همی دربدر خشک نان بازجست <br>مر او را همین پیشه بود از نخست .<br> <font color=\"Red\">ابوشکور.</font><br>جز ایشان به بلخ اندرون نیست کس <br>از آن نامداران همین است و بس .<br> <font color=\"Red\">فردوسی .</font><br>همه پرسش این بود و پاسخ همین <br>که بر شاه بادا هزار آفرین .<br> <font color=\"Red\">فردوسی .</font><br>جهان جاودانه نماند به کس <br>همین جاودان نام نیک است و بس .<br> <font color=\"Red\">فردوسی .</font><br>که فرمانده هفت شهر زمین <br>همین یک تن آمد ز شاهان، همین .<br> <font color=\"Red\">نظامی .</font><br>چوبر دشمنی باشدت دسترس <br>مرنجانْش کو را همین غصه بس .<br> <font color=\"Red\">سعدی .</font><br>چه میخواهم از طارم افراشتن <br>همینم بس از بهر بگذاشتن .<br> <font color=\"Red\">سعدی .</font><br>بر حدیث من و حسن تو نیفزاید کس <br>حد همین است سخندانی و زیبایی را.<br> <font color=\"Red\">سعدی .</font><br>مجال من همین باشد که پنهان عشق او ورزم <br>کنار و بوس و آغوشش چگونه ؟ چون نخواهد شد.<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> (شبه جمله ) کلمه ٔ «همین » با لحن استفهام در تداول امروز به صورت شبه جمله به کار میرود به معنی اینکه : آیا کافی است ؟ دیگر لازم نیست ؟ <BR><font color=\"Blue\">◄</font> (حرف ربط مرکب ) نیز. ایضاً. (یادداشت مؤلف ). هم <span class=\"hlight\">:</span><br>چه باید مرا بی تو گنج و سپاه <br>همین تخت شاهی و زرین کلاه .<br> <font color=\"Red\">فردوسی .</font><br>همین گرز و این نیزه و بادپای <br>همین جوشن و ترگ و رومی قبای .<br> <font color=\"Red\">فردوسی .</font><br>تو را دادم ای زال این جایگاه <br>همین پادشاهی و تخت و کلاه .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268564, 'همینه', '<span class=\"hlight\">همینه .</span> <font color=\"DarkGreen\"><b>[ هََن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) قطره ٔ آب . (انجمن آرا) (آنندراج ).<br></font></div>'),
(268565, 'همیوبول', '<span class=\"hlight\">همیوبول .</span> <font color=\"DarkGreen\"><b>[ هَِ بُل ْ ]</font></b> (اِ)سکه ٔ اشکانی معادل دوازده درهم . (یادداشت مؤلف ).<br></font></div>'),
(268566, 'همیون', '<span class=\"hlight\">همیون .</span> <font color=\"DarkGreen\"><b>[ هَُ ما ]</font></b> (ص ) همایون <span class=\"hlight\">:</span> خاک بارگاه همیون را سجده گاه شاهان دنیا کناد. (کلیله و دمنه ). رجوع به همایون شود.<br></font></div>'),
(268567, 'هن', '<span class=\"hlight\">هن .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) منت . (برهان ). مؤلف انجمن آرانویسد: به فتح اول در جهانگیری و رشیدی و برهان به معنی منت آورده اند و گفته اند رودکی گفته <span class=\"hlight\">:</span> <br>گر همه نعمت یک روز به ما بخشد<br>ننهد منت بر ما و پذیرد هن .<br>و این سه بزرگوار هر یک سه خطا کرده اند. اول آن که هن نیست و مَن ّ عربی است که به معنی منت آمده ؛ دیگر آنکه پارسی نیست و عربی است ؛ دیگر آنکه شعر رودکی نیست و شعر فرخی است ... و این سهو از صاحب جهانگیری شده و رشیدی و برهان به وی اقتفا کرده اند... و هن به پارسی، خاصه زبان شیرازی و دری، به معنی هست است . (انجمن آرا). در لهجه های فارس به صورت هَن یا فقط به صورت نون ماقبل مفتوح معادل با لفظ «هست » یا «است » هنوز به کار میرود.<br></font></div>'),
(268568, 'هن', '<span class=\"hlight\">هن .</span> <font color=\"DarkGreen\"><b>[ هََ ن ن ]</font></b> (ع مص ) گریستن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نالیدن . (منتهی الارب ). حن . (اقرب الموارد). رجوع به حن شود.<br></font></div>'),
(268569, 'هن', '<span class=\"hlight\">هن .</span> <font color=\"DarkGreen\"><b>[ هَُ ن ْ ن َ ]</font></b> (ع ضمیر) ایشان . گروهی زنان .(ترجمان جرجانی ). ضمیر مغایب جمع است برای مؤنث .<br></font></div>'),
(268570, 'هن', '<span class=\"hlight\">هن .</span> <font color=\"DarkGreen\"><b>[ هََ ن ن <span class=\"hlight\" dir=\"rtl\">/</span> هََ ]</font></b> (ع اِ) شرم زن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> یکی از اسماء سته است . <BR><font color=\"Blue\">◄</font> در شعر کنایه از هر اسم جنس است به معنی چیزی : هذا هنک ؛ یعنی این چیز توست و به صورت هنة مؤنث آید. (اقرب الموارد).<br></font></div>'),
(268571, 'هن و هن', '<span class=\"hlight\">هن و هن .</span> <font color=\"DarkGreen\"><b>[ هَِ ن ْ ن ُ هَِ ن ن ]</font></b> (اِ صوت ) کنایه از نفس نفس زدن حاصل از خستگی و یا بیماری است .<br></font></div>'),
(268572, 'هن کردن', '<span class=\"hlight\">هن کردن .</span> <font color=\"DarkGreen\"><b>[ هَِ ک َ دَ ]</font></b> (مص مرکب ) راندن ستور با گفتن لفظ هن . (یادداشت مؤلف ).<br></font></div>'),
(268573, 'هنا', '<span class=\"hlight\">هنا.</span> <font color=\"DarkGreen\"><b>[هَُ نا <span class=\"hlight\" dir=\"rtl\">/</span> هَُ ن ْ نا ]</font></b> (ع ق ) اینجا. (منتهی الارب ).<br></font></div>'),
(268574, 'هنا', '<span class=\"hlight\">هنا.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع مص ) عطا دادن . (تاج المصادر بیهقی ).<br></font></div>'),
(268575, 'هنا', '<span class=\"hlight\">هنا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) نسب پست . (از اقرب الموارد).<br></font></div>'),
(268576, 'هنا', '<span class=\"hlight\">هنا.</span> <font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (ع ضمیر) لغتی است در انا. (اقرب الموارد). من، ضمیر متکلم مفرد. رجوع به انا شود.<br></font></div>'),
(268577, 'هناء', '<span class=\"hlight\">هناء.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع اِ) قطران . <BR><font color=\"Blue\">◄</font> خوشه ٔ خرما که باران خورده باشد. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268578, 'هناء', '<span class=\"hlight\">هناء.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) بطنی از قبیله ٔ طی و آنان فرزندان هنأبن عمروبن غوث بن طی هستند. (صبح الاعشی ).<br></font></div>'),
(268579, 'هنابذ', '<span class=\"hlight\">هنابذ.</span> <font color=\"DarkGreen\"><b>[ هََ ب ِ ]</font></b> (ع اِ) ج ِ هنبذة. (منتهی الارب ). به معنی کار سخت . (از اقرب الموارد). رجوع به هنبذة شود.<br></font></div>'),
(268580, 'هنابیر', '<span class=\"hlight\">هنابیر.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) جای هلاک . <BR><font color=\"Blue\">◄</font> دوزخ . <BR><font color=\"Blue\">◄</font> زمین بلند. (منتهی الارب ). ریگزار بلند، واحد آن هنبورة است و خود مقلوب نهابیر است . (اقرب الموارد).<br></font></div>'),
(268581, 'هنادسة', '<span class=\"hlight\">هنادسة.</span> <font color=\"DarkGreen\"><b>[ هََ دِ س َ ]</font></b> (ع ص، اِ) ج ِ هُندوس . (منتهی الارب ). به معنی دانای امور.(آنندراج ) (از اقرب الموارد). رجوع به هندوس شود.<br></font></div>'),
(268582, 'هنادک', '<span class=\"hlight\">هنادک .</span> <font color=\"DarkGreen\"><b>[ هََ دِ ]</font></b> (ع اِ) ج ِ هندکی . مردان هند.(منتهی الارب ) (اقرب الموارد). رجوع به هندکی شود.<br></font></div>'),
(268583, 'هناسه', '<span class=\"hlight\">هناسه .</span> <font color=\"DarkGreen\"><b>[ هََ س َ<span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ) آه . باد سرد کشیدن . (یادداشت مؤلف ).<br></font></div>'),
(268584, 'هناف', '<span class=\"hlight\">هناف .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع مص ) به فسوس خندیدن . (منتهی الارب ). مهانفة. (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بازی و ملاعبه با دوست . (از اقرب الموارد).<br></font></div>'),
(268585, 'هنالک', '<span class=\"hlight\">هنالک .</span> <font color=\"DarkGreen\"><b>[ هَُ ل ِ ک َ ]</font></b> (ع ق مرکب ) آنجا. (ترجمان علامه ٔ جرجانی ترتیب عادل ). اسم اشاره برای مکان دور، مرکب از هنا + ک خطاب + لام برای افاده ٔ بعد مکان .<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(268586, 'هنام', '<span class=\"hlight\">هنام .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِ) به لغت زند و پازند به معنی اندام باشد که در برابر بی اندام است . (برهان ). مصحف هندام پهلوی به معنی اندام است . (از حاشیه ٔ برهان چ معین ).<br></font></div>'),
(268587, 'هنام و بسطام', '<span class=\"hlight\">هنام و بسطام .</span> <font color=\"DarkGreen\"><b>[ هَُ م ُ ب َ ]</font></b> (اِخ ) دهستانی است از بخش سلسله ٔ شهرستان خرم آباد. در خاور بخش واقع شده و منطقه ای کوهستانی و سردسیر است . آب آن از رودخانه های هنام، کاکارضا، سیل برجه و چشمه های مختلف تأمین میشود. این دهستان شامل <span class=\"hlight\" dir=\"rtl\">٣٤</span> آبادی و جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">٤٩٠٠</span> تن است . قراء مهم آن عبارتند از: برمسک، کاکارضا، چهارتخته، خسروآباد و سراب هنم . ساکنان آنجا از طایفه ٔ حسنوند هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268588, 'هنامه', '<span class=\"hlight\">هنامه .</span> <font color=\"DarkGreen\"><b>[ هَُ م ِ ]</font></b> (اِخ ) دهی است از بخش شیروان شهرستان قوچان . <span class=\"hlight\" dir=\"rtl\">٤٩٠</span> تن سکنه دارد.آب آن از رودخانه و محصول عمده اش غله و انگور، و کار دستی مردم قالی بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268589, 'هنانة', '<span class=\"hlight\">هنانة.</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ]</font></b> (ع اِ) پیه درون چشم که زیر مقله باشد. <BR><font color=\"Blue\">◄</font> باقی مانده ٔ مغز و پیه شتر. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268590, 'هناهین', '<span class=\"hlight\">هناهین .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) گفتگو و هجوم مردمان و صدای اسبان وقتی که لشکری و جماعتی بسیار سوار شده میرفته باشند. (برهان ).<br></font></div>'),
(268591, 'هنایش', '<span class=\"hlight\">هنایش .</span><font color=\"DarkGreen\"><b>[ هَِ ی ِ ]</font></b> (اِ) تأثیر و اثر داده شده . (برهان ).<br></font></div>'),
(268592, 'هنب', '<span class=\"hlight\">هنب .</span> <font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (ع اِمص ) گولی . (منتهی الارب ).<br></font></div>'),
(268593, 'هنباز', '<span class=\"hlight\">هنباز.</span> <font color=\"DarkGreen\"><b>[ هَم ْ ]</font></b> (ص ) انباز. شریک . <BR><font color=\"Blue\">◄</font> نظیر. (برهان ). رجوع به انباز و همباز شود.<br></font></div>'),
(268594, 'هنباغ', '<span class=\"hlight\">هنباغ .</span> <font color=\"DarkGreen\"><b>[ هِم ْ ]</font></b>(ع اِ) گرسنگی سخت . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268595, 'هنبان', '<span class=\"hlight\">هنبان .</span> <font color=\"DarkGreen\"><b>[ هَم ْ ]</font></b> (اِ) انبان . پوستی باشد که درست از گوسفند برآورده باشند و دباغت کنند و چیزها در آن نهند. <BR><font color=\"Blue\">◄</font> زنبیل درویشان را نیز گفته اند که سفره ٔ گرد چرمین باشد. (برهان ).<br></font></div>'),
(268596, 'هنبتة', '<span class=\"hlight\">هنبتة.</span> <font color=\"DarkGreen\"><b>[ هَم ْ ب َ ت َ ]</font></b> (ع مص ) فروهشته شدن . <BR><font color=\"Blue\">◄</font> سستی و درنگی کردن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) سستی . <BR><font color=\"Blue\">◄</font> فروهشتگی . (منتهی الارب ).<br></font></div>'),
(268597, 'هنبر', '<span class=\"hlight\">هنبر.</span> <font color=\"DarkGreen\"><b>[ هَِ ن ْ ن َ ]</font></b> (ع اِ) کفتار ماده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گاو نر. <BR><font color=\"Blue\">◄</font> اسب . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پوست هیچکاره یا کرانه ٔ آن . (منتهی الارب ). جرم پوست یا کرانه های آن . (اقرب الموارد).<br></font></div>'),
(268598, 'هنبر', '<span class=\"hlight\">هنبر.</span> <font color=\"DarkGreen\"><b>[ هِم ْ ب ِ ]</font></b> (ع اِ) خر کره . <BR><font color=\"Blue\">◄</font> بچه کفتار. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268599, 'هنبر', '<span class=\"hlight\">هنبر.</span> <font color=\"DarkGreen\"><b>[ هِم ْ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (ع اِ) کفتار ماده . (منتهی الارب ). رجوع به هنبرة شود.<br></font></div>'),
(268600, 'هنبرد', '<span class=\"hlight\">هنبرد.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام چند ده از توابع قم بوده است که اکنون در مآخذ جغرافیایی نام آنها نیست . و نوشته اند که مطبخهای اردشیر در آن جا بوده است و هنبرد یعنی سیری از طعام . رجوع به ترجمه ٔ تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٦٩</span>، <span class=\"hlight\" dir=\"rtl\">٧٠</span>، <span class=\"hlight\" dir=\"rtl\">٧١</span>، <span class=\"hlight\" dir=\"rtl\">١١٧</span> شود.<br></font></div>'),
(268601, 'هنبسة', '<span class=\"hlight\">هنبسة.</span> <font color=\"DarkGreen\"><b>[ هَم ْ ب َ س َ ]</font></b> (ع مص ) خبر جستن . (منتهی الارب ).<br></font></div>'),
(268602, 'هنبص', '<span class=\"hlight\">هنبص .</span> <font color=\"DarkGreen\"><b>[ هِم ْ ب ِ ]</font></b> (ع ص ) مرد سست حقیر هیچکاره . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268603, 'هنبص', '<span class=\"hlight\">هنبص .</span> <font color=\"DarkGreen\"><b>[ هُم ْ ب ُ]</font></b> (ع ص ) کلان شکم . (منتهی الارب ). رجوع به هنبض شود.<br></font></div>'),
(268604, 'هنبض', '<span class=\"hlight\">هنبض .</span> <font color=\"DarkGreen\"><b>[ هُم ْ ب ُ ]</font></b> (ع ص ) کلان شکم . (از منتهی الارب ). و ابن عباد آن را در هنبص با صاد مهمله آورده است . (اقرب الموارد). رجوع به هنبص شود.<br></font></div>'),
(268605, 'هنبع', '<span class=\"hlight\">هنبع.</span> <font color=\"DarkGreen\"><b>[ هُم ْ ب ُ ]</font></b> (ع اِ) روبندی است دختران را شبیه مقنعه که مقدم آن را میدوزند. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268606, 'هنبغ', '<span class=\"hlight\">هنبغ.</span> <font color=\"DarkGreen\"><b>[ هُم ْ ب ُ ]</font></b>(ع ص، اِ) سختی گرسنگی . (منتهی الارب ). و در لسان العرب آمده است که به صورت وصف نیز به کار رود. گویند: جوع ٌ هنبغ و هنباغ و هنبوغ ؛ أی شدید. <BR><font color=\"Blue\">◄</font> خاکی که به کمتر بادی به هوا خیزد. <BR><font color=\"Blue\">◄</font> شیربیشه . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن ضعیف حمله . (از اقرب الموارد). زن سست گیر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن گول . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن تبهکار. (از اقرب الموارد).<br></font></div>'),
(268607, 'هنبلة', '<span class=\"hlight\">هنبلة.</span> <font color=\"DarkGreen\"><b>[ هَم ْ ب َ ل َ ]</font></b> (ع مص ) لنگیدن و به رفتار ددان رفتن مرد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268608, 'هنبه', '<span class=\"hlight\">هنبه .</span> <font color=\"DarkGreen\"><b>[ هُم ْ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ) در تداول شکم را گویند. (یادداشت مؤلف ).<br></font></div>'),
(268609, 'هنبی', '<span class=\"hlight\">هنبی .</span> <font color=\"DarkGreen\"><b>[ هَُ ن ْ ن َ با <span class=\"hlight\" dir=\"rtl\">/</span> هََ ن َ با ]</font></b> (ع ص ) زن گول و نادان که در کار زیرکی و استادی کردن نتواند. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268610, 'هنبی', '<span class=\"hlight\">هنبی .</span> <font color=\"DarkGreen\"><b>[ هِم ْ بی ی ]</font></b> (ص نسبی ) منسوب به هنب که بطنی است از ربیعه . (سمعانی ).<br></font></div>'),
(268611, 'هنة', '<span class=\"hlight\">هنة.</span> <font color=\"DarkGreen\"><b>[ هََ ن ْ ن َ ]</font></b> (ع اِ) مؤنث هَن ّ. (منتهی الارب ).<br></font></div>'),
(268612, 'هنتاتی', '<span class=\"hlight\">هنتاتی .</span> <font color=\"DarkGreen\"><b>[ هََ تی ی ]</font></b> (ص نسبی ) منسوب به هنتاتة که از قبیله ٔ مصمودة است . رجوع به صبح الاعشی شود.<br></font></div>'),
(268613, 'هنتبة', '<span class=\"hlight\">هنتبة.</span> <font color=\"DarkGreen\"><b>[ هََ ت َ ب َ ]</font></b> (ع مص ) سستی و درنگی نمودن در کار. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268614, 'هنج', '<span class=\"hlight\">هنج .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِمص ) به معنی کشیدن باشد و امر به این معنی هم هست یعنی بکش . <BR><font color=\"Blue\">◄</font> به معنی انداختن هم گفته اند. <BR><font color=\"Blue\">◄</font> (ص ) دو چیز را نیز گویند که بحسب کیفیت یک قدر داشته باشند، همچو آوازی که با سازی کوک شده باشد. <BR><font color=\"Blue\">◄</font> دو شخص که بر یک قصد و یک عزم و یک اراده باشند. (برهان ).<br></font></div>'),
(268615, 'هنجار', '<span class=\"hlight\">هنجار.</span> <font color=\"DarkGreen\"><b>[ هَِ <span class=\"hlight\" dir=\"rtl\">/</span> هََ ]</font></b> (اِ) راه و روش و طریق و طرز و قاعده و قانون . (برهان ). در سنسکریت سمکارا به معنی گشتن و گردیدن و راه است . (حاشیه ٔ برهان چ معین ) <span class=\"hlight\">:</span> <br>به آخر شکیبایی آورد پیش <br>که جز آن نمی دید هنجارخویش .<br> <font color=\"Red\">فردوسی .</font><br>همی شدند به بیچارگی هزیمتیان <br>گسسته پشت گرفته گریغ را هنجار.<br> <font color=\"Red\">عنصری .</font><br>خوشا راهی که باشد راه آنان <br>که دارند از سفر هنجار جانان .<br> <font color=\"Red\">فخرالدین اسعد.</font><br>ره و هنجار ستمکاره همه زشت است <br>ای خردمند مرو بر ره و هنجارش .<br> <font color=\"Red\">ناصرخسرو.</font><br>مهمان کند خزینه تو و من را<br>مهمان کشی است شیوه و هنجارش .<br> <font color=\"Red\">ناصرخسرو.</font><br>قصه ای را که نظم خواهم کرد<br>برطرازم سخن بدین هنجار.<br> <font color=\"Red\">مسعودسعد.</font><br>چیستی ؟ مرغی، ستوری، آدمستی ؟ بازگرد<br>ور به راه آدمی چون آدمت هنجار کو؟<br> <font color=\"Red\">سنایی .</font><br>نیکان ملت را به دین یاد تو تسبیح مهین <br>پیکان نصرت را به کین عزم تو هنجار آمده .<br> <font color=\"Red\">خاقانی .</font><br>دلیری است هنجار لشکرکشی <br>سرافکندگی نیست در سرکشی .<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> جاده و راه راست و بعضی راه غیرجاده را هم گفته اند. (برهان )<span class=\"hlight\">:</span> <br>گرفته هر دو هنجار خراسان <br>بر ایشان گشت رنج راه آسان .<br> <font color=\"Red\">فخرالدین اسعد.</font><br>همواره پشت و یار من پوینده بر هنجار من <br>خاراشکن رهوار من، شبدیز خال و رخش عم .<br> <font color=\"Red\">لامعی .</font><br>گر از دنیا به رنجی راه اوگیر<br>کز این بهترنه راه است و نه هنجار.<br> <font color=\"Red\">ناصرخسرو.</font><br>شعاع کوکب ثابت به چرخ بر رهبر<br>مسیر دیو دژآگه به خاک بر هنجار.<br> <font color=\"Red\">مسعودسعد.</font><br>نه هرگز کسی دیده هنجار قبله <br>نه هرگز شنیده کس اﷲ اکبر.<br> <font color=\"Red\">عمعق .</font><br>چو دیدم که هنجاراو دور بود<br>شب از جمله شبهای دیجور بود.<br> <font color=\"Red\">نظامی .</font><br>وز ایشان به هنجارهای درست <br>سوی ربع مسکون نشان بازجست .<br> <font color=\"Red\">نظامی .</font><br>مرغی که نه اوج خویش گیرد<br>هنجار هلاک پیش گیرد.<br> <font color=\"Red\">نظامی .</font><br>از راه رحیل خار برداشت <br>هنجار دیار یار برداشت .<br> <font color=\"Red\">نظامی .</font><br>نهفته بازمیپرسید جایش <br>به دست آورد هنجار سرایش .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">بهنجار</span> ؛ دارای راه و روش . آشنا به رموز. ماهر <span class=\"hlight\">:</span> <br>در فسق و قمار نیز استادیم <br>در دیر مغان مغی بهنجاریم .<br> <font color=\"Red\">عطار.</font><br>تا بجنباند بهنجار و به فن <br>تا بدانم من که پنهان بودمن .<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">بهنجار رفتن </span> ؛ درست رفتن . از راه درست و راست رفتن <span class=\"hlight\">:</span> <br>هم در سلوک گام بتدریج مینهند<br>هم در طریق عشق بهنجار میروند.<br> <font color=\"Red\">عطار.</font><br>- <span class=\"hlight\">هنجار بردن </span> ؛ راه بردن <span class=\"hlight\">:</span> <br>هم بدین تعبیه بران که ظفر<br>سپهت را نکو برد هنجار.<br> <font color=\"Red\">مسعودسعد.</font><br>- <span class=\"hlight\">هنجار بریدن </span> ؛ طی طریق کردن . راه پیمودن <span class=\"hlight\">:</span> <br>به قلعه ای که از او باد کم رود بیرون <br>به بیشه ای که در او دیو بد برد هنجار.<br> <font color=\"Red\">مسعودسعد.</font><br>هر کجا روی آری از نصرت <br>پیش نصرت همی برد هنجار.<br> <font color=\"Red\">مسعودسعد.</font><br>- <span class=\"hlight\">هنجارجوی </span> ؛ جوینده ٔ راه . راه یاب <span class=\"hlight\">:</span> <br>نوند شتابنده هنجارجوی <br>چنان شد که بادش نه دریافت بوی .<br> <font color=\"Red\">اسدی .</font><br>کم آسای و دمساز و هنجارجوی <br>سبک پای و آسان دو و تیزپوی .<br> <font color=\"Red\">اسدی .</font><br>- <span class=\"hlight\">هنجار کردن </span> ؛ راه پیمودن . پوییدن یا راه یافتن <span class=\"hlight\">:</span> ... و به شب اندر آتش کردی بر میلها تا لشکر بدان هنجار راه کردندی . (مجمل التواریخ و القصص ).<br>گر تو در دهر همدمی جویی <br>در ره جست کم کنی هنجار.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">هنجارنمای </span> ؛ راه نمای . راه دان <span class=\"hlight\">:</span> <br>در راه و روش چو خضر پویان <br>هنجارنمای و راه جویان .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268616, 'هنجام', '<span class=\"hlight\">هنجام .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص ) مردم بیکار و تنبل وکاهل و باطل و مهمل را گویند. (برهان ) <span class=\"hlight\">:</span> <br>در دنیا سخت سختی و در دین <br>پی سست و میانه کار و هنجامی .<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(268617, 'هنجل', '<span class=\"hlight\">هنجل .</span> <font color=\"DarkGreen\"><b>[ هَُ ج ُ ]</font></b> (ع ص ) گران سنگ . (منتهی الارب ). ج، هناجل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد گران که صحبتش را ناخوش دارند. (منتهی الارب ).<br></font></div>'),
(268618, 'هنجمک', '<span class=\"hlight\">هنجمک .</span> <font color=\"DarkGreen\"><b>[ هَِ ج َ م َ ]</font></b> (اِ) برغست را گویند و آن علفی است شبیه به اسفناج که در آش ها آرد کنند و به عربی تملول خوانند. (آنندراج ).<br></font></div>'),
(268619, 'هنجن', '<span class=\"hlight\">هنجن .</span> <font color=\"DarkGreen\"><b>[ هََ ج َ ]</font></b> (اِخ ) دهی است از بخش نطنز شهرستان کاشان . دارای <span class=\"hlight\" dir=\"rtl\">٩٤٠</span> تن سکنه، آب آن از رودخانه ٔ ابیانه و<span class=\"hlight\" dir=\"rtl\">٩</span> رشته قنات، محصول عمده اش غله، حبوب، انار، انجیر، سیب و کار دستی زنان گیوه بافی است . قلعه ٔ خرابه ای از آثار قدیم دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(268620, 'هنجیدن', '<span class=\"hlight\">هنجیدن .</span><font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (مص ) بیرون کشیدن و برآوردن . (برهان ).<br>- <span class=\"hlight\">برهنجیدن </span> ؛ گستردن . (یادداشت مؤلف ). گشودن <span class=\"hlight\">:</span> <br>چنان که مرغ هوا پرّ و بال برهنجد<br>تو بر خلایق بر، پرّ مردمی برهنج .<br> <font color=\"Red\">ابوشکور.</font><br>- <BR><font color=\"Blue\">◄</font> بیرون آمدن <span class=\"hlight\">:</span> <br>دل اندر مهر می برهنجد از تن <br>چنان چون سنگ مغناطیس و آهن .<br><font color=\"Red\">فخرالدین اسعد.</font><br></font></div>'),
(268621, 'هنجیرکی', '<span class=\"hlight\">هنجیرکی .</span> <font color=\"DarkGreen\"><b>[ هََ رَ ]</font></b>(اِخ ) دهی است از بخش قصرقند شهرستان چاه بهار. دارای <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268622, 'هند', '<span class=\"hlight\">هند.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دختر عتبةبن ربیعةبن عبدشمس بن عبدمناف . از زنان قریش و مادر معاویةبن ابی سفیان است . نیز از شاعره های عهد جاهلیت است و از زنان باتدبیر و گشاده سخن به شمار میرود. وی در فتح مکه اسلام پذیرفت و بتی را که پیش از آن می پرستید در زیر پای خرد کرد.درگذشت او به سال <span class=\"hlight\" dir=\"rtl\">١٤</span> هجری واقع شد. (از اعلام زرکلی ). وی در جنگ احد حاضر بود و پس از قتل حمزه عموی پیامبر پاره ای از جگر او را به دندان گرفت و بدین سبب به هند جگرخواره یا آکلةالاکباد معروف شد <span class=\"hlight\">:</span> <br>عاجزم از چنگ این هند جگرخوارم برآر<br>یا رسول اﷲ مسلمانی ز کافر میخری .<br><font color=\"Red\">نظیری .</font><br></font></div>'),
(268623, 'هند', '<span class=\"hlight\">هند.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) (اقیانوس ...) نام دریای عظیمی است که در جنوب کشور هند و قاره ٔ آسیا قرار گرفته است و از مشرق به اقیانوس آرام می پیوندد و ساحل غربی آن کناره های شرقی قاره ٔ افریقااست . دریای عمان و خلیج فارس در جنوب ایران از انشعابات این اقیانوس هستند. رجوع به اقیانوس هند شود.<br></font></div>'),
(268624, 'هند', '<span class=\"hlight\">هند.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) گروهی است از اولاد لوطبن حام بن نوح . (منتهی الارب ).<br></font></div>'),
(268625, 'هند', '<span class=\"hlight\">هند.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) پارسی باستان هندو همریشه با سند، در کتیبه های عیلامی هی ایندویش، اوستا هندو، سنسکریت سینذو به معنی نهر، جویبار، رود سند یا ناحیه ٔ گرداگرد رود سند است و در شاهنامه گاه به فتح اول با کلماتی چون پرند قافیه شده است . (حاشیه ٔ برهان چ معین ). این کشور را در ممالک انگلیسی زبان ایندیامیگویند. کشوری است در جنوب آسیا و جنوب سلسله کوههای هیمالایا در کنار دریای عمان و بحر بنگال . این نام قبلاً به تمام سرزمینی که هند و پاکستان کنونی را تشکیل میداد اطلاق می شد و ایالات متعددی را شامل بود که هر کدام به نامی خوانده می شد. این سرزمین شبه قاره ای است که از قسمتهای دیگر آسیا با جبال عظیم هیمالایا جدا میشود. نام کهن این سرزمین بهاراته است . وسعت شبه قاره <span class=\"hlight\" dir=\"rtl\">٣٢٨٨٨١٨</span> کیلومتر مربع و جمعیت آن قریب چهارصد وچهل ملیون است . کشور هند از ممالک مشترک المنافع بریتانیای کبیر است . این کشور شامل <span class=\"hlight\" dir=\"rtl\">٢٧</span> ایالت است که مهمترین آنها عبارتند از: ایالت های دهلی (ایالت مرکزی )، بمبئی، حیدرآباد، مدرس، میسور، پنجاب، سیکیم و بوتان . این سرزمین از شمال شرقی به چین و برمه و از شمال به تبت و نپال و در شمال غربی به پاکستان محدود است و در شرق پاکستان سرزمین «نتوآ» واقع شده که در شمال شرقی هند قرار دارد. هند فرانسوی و هند پرتقالی عبارتند از مناطق کوچکی که دو ساحل شرقی و غربی اراضی هند آن را احاطه کرده است . نیمه ٔ جنوبی از شبه جزیره ٔ هند میان بحر عمان و خلیج «بنگال » واقع است . بزرگترین رودخانه ٔ هند رود گنگ و «براهابترا» و «سند» میباشد. محصولات زراعتی هند که کفایت تغذیه و مایحتاج سکنه ٔ آن را نمیکند عبارت است از: برنج، کنف، پنبه و چای . سرمایه های طبیعی هند را جنگل های انبوه که از درختهای آن جهت کشتی سازی و غیر آن استفاده میشود، و معادن منیزیم و ذغال سنگ و مس و آهن تشکیل میدهد. ایالت «جمشیدپور» مرکز صنعت آهن و فولاد، و «بمبئی » مرکز کارخانجات نساجی و «کلکته » مرکز تولیدات کنف میباشند. شهرهای بزرگ مرزی عبارتند از: بمبئی و کلکته و مدرس . زندگی اجتماعی سکنه ٔ هند بر اساس اختلافات طبقات مردم پی ریزی شده که بسیاری ازقوانین دولتی برای مبارزه با آن است و تعصبات خشک مذهبی سبب فقر و گرسنگی اکثر سکنه ٔ هند است . هندیها توجه خاصی به زیارت اماکن و شهرهای مقدس مذهبی از جمله شهرهای بنارس و اﷲآباد دارند. تمدن هندوستان از حدود دو تا چهار هزار سال پیش از میلاد شروع میشود، قبائل آریائی از شمال هند در حدود <span class=\"hlight\" dir=\"rtl\">١٥٠٠</span> ق . م . وارد آن سرزمین شده اند، و تمدن برهمایی را آغاز کرده اند و درنتیجه اصول مذهب «هندویی » به وجود آمده است . در قرن ششم قبل از میلاد، «بودا» ظهور کرد، و پیش از آن مذهب «هندویی » مذهب رسمی پادشاهان «موری » بود ولی «آسوکا» در قرن سوم قبل از میلاد دین «بودا» را دین رسمی کرد. فرهنگ هندی از زمان شاهان جوبتو (<span class=\"hlight\" dir=\"rtl\">٣٢٠</span> تا <span class=\"hlight\" dir=\"rtl\">٥٤٤</span> م .)رونق یافت و سپس هنگامی که راجبوتی ها بر مناطق شمال غربی هند تسلط یافتند و به ایجاد حکومت ملوک طوایف پرداختند، آنها و خاندانهای پیش، از تشکیلات همدیگر تجاربی مفید به دست آوردند. این ملوک الطوایفی زمینه را برای فتوحات اسلامی در قرن <span class=\"hlight\" dir=\"rtl\">١١</span> بوسیله ٔ سلطان محمود غزنوی فراهم کرد. در سال <span class=\"hlight\" dir=\"rtl\">١٥٢٦</span> «بابر» پادشاه مغول برهند تسلط یافت . هند در روزگار اکبرشاه و شاه جهان و اورنگ زیب سیر تمدن را آغاز کرد و در همین روزگار بودکه پرتقالیها بر «جاوه » دست یافتند (<span class=\"hlight\" dir=\"rtl\">١٥١٠</span> م .). هنگامی که طوایف «مراتی » و «سیک » علیه حکومت پادشاهان مغول قیام کردند، انگلیسی ها و فرانسوی ها در قرن <span class=\"hlight\" dir=\"rtl\">١٨</span> مناطقی برای خود از هند جدا کردند، پس از پیروزی «روبرت کلایف » بر «دیلکس » افسر فرانسوی، افراد انگلیسی در هند بیشتر شدند. و واران هستینگز فرمانروای انگلیسی بنیاد حکومت بریطانیا را در هند استوار گردانید. دولت بریتانیا در سال <span class=\"hlight\" dir=\"rtl\">١٨٧٥</span> م . بر اثر شورشی که در آن تاریخ در هند بوقوع پیوست، کمپانی هند شرقی را که گرداننده ٔ هند بود منحل کرد و به این سرزمین خودمختاری داده شد و در سال <span class=\"hlight\" dir=\"rtl\">١٨٧٧</span> ملکه ویکتوریا امپراطور بریتانیا به هند دعوت شد و در آن هنگام نماینده ٔ مخصوص ملکه که از طرف حکومت بریتانیا تعیین میشد، بر هند فرمانروایی میکرد، و یک هیأت (اجرائی ) مرکب از افراد عالی رتبه ٔ دولت بریتانیا او را راهنمائی می نمودند. هند به تدریج از خواب غفلت بیدار شد و عده ای از رهبران هندی در سال <span class=\"hlight\" dir=\"rtl\">١٨٨٤</span> دستجات و سازمانهای ملی را تشکیل دادند که هدف اصلی آنان رسیدن به استقلال تام بود. در سالهای <span class=\"hlight\" dir=\"rtl\">١٩٠٦</span> تا <span class=\"hlight\" dir=\"rtl\">١٩١٥</span>، دولت انگلیس ناچار شد که اداره ٔبعضی از امور کشور را به مردم هند ارجاع نماید. در این هنگام بود که رهبر بزرگ هند «گاندی » قیام کرد و علیه استبداد بریتانیا به مبارزه پرداخت، اگرچه «گاندی » با یارانش چند مرتبه زندانی شد ولی باز به مبارزات خود ادامه داد تا در سال <span class=\"hlight\" dir=\"rtl\">١٩٣٠</span> تا <span class=\"hlight\" dir=\"rtl\">١٩٣٣</span> دولت بریتانیا زعمای هند را به کنفرانس میزگرد دعوت نمود، لکن از مذاکرات آن کنفرانس نتیجه به دست نیامد. در آغاز جنگ دوم جهانی فرمانروایان بریتانیا در هند حکومت نظامی اعلام کردند و در حدود دو ملیون هندی را به سربازی دعوت نمودند و آنها را به جبهه ٔ جنگ فرستادند. پس از تجاوز ارتش ژاپن در سال <span class=\"hlight\" dir=\"rtl\">١٩٤٢</span> به کشورهای سیام و مالایا و برمه، اختلاف شدیدی در بین سران هند و سران مسلمانان هند که رهبر آنها محمدعلی جناح بود بوجود آمد. مسلمانان میخواستند کشوری مرکب از مناطق مسلمان هند تشکیل دهند. در آن هنگام که حزب کارگر انگلیس حکومت را به دست گرفت و هیأت وزیران خود را تشکیل داد، حکومت بریتانیا قوانینی وضع نمود که به موجب آن به هند و سیلان و پاکستان استقلال داده شد، و در ماه اوت <span class=\"hlight\" dir=\"rtl\">١٩٤٧</span> م . آخرین سرباز انگلیس خاک هند را ترک گفت، و در تاریخ ژانویه ٔ <span class=\"hlight\" dir=\"rtl\">١٩٥٠</span> هند حکومت جمهوری مستقل خود را اعلام نمود و به عضویت اتحادیه ٔ کشورهای مشترک المنافع بریتانیا درآمد. هند در تاریخ <span class=\"hlight\" dir=\"rtl\">١٩٥٢</span> برنامه های پنجساله ٔ خود را برای عمران و آبادانی شروع کرد، ولی روابطآن کشور با همسایه ٔ بزرگ خود پاکستان بر سر مسئله ٔ کشمیر رو به وخامت نهاد و همچنین با کشور چین در مسائل مرزی اختلاف نظر پیدا کرد. البته پس از آنکه چین کمونیست در تاریخ <span class=\"hlight\" dir=\"rtl\">١٩٥٩</span> بر تبت مستولی شد و تجاوزات مرزی خود را به خاک هند آغاز کرد، ناحیه ٔ ماکماهون خط مرزی بین چین و هند شد. در تاریخ <span class=\"hlight\" dir=\"rtl\">٣١</span> اکتبر <span class=\"hlight\" dir=\"rtl\">١٩٦١</span> م . هند همسایه ٔ خود را به تجاوزهای پیاپی به پادگانهای نظامی متهم ساخت و در تاریخ <span class=\"hlight\" dir=\"rtl\">١٨</span> دسامبر <span class=\"hlight\" dir=\"rtl\">١٩٦١</span> نیروهای هند مستعمرات پرتقال را که شامل «داماو» و «جوا» و «دیو» واقع در ساحل غربی بود، به تصرف درآوردند. سپس در تاریخ اکتبر <span class=\"hlight\" dir=\"rtl\">١٩٦٢</span> نیروهای چین به مرکز «لونجو» حمله کردند و مناطق شمال شرقی هند را اشغال نمودند و بانیروهای هند به زد و خورد پرداختند. نیروهای هند دراین جنگ آسیب دیدند، و چون در برابر سربازان چین تاب نیاوردند عقب نشینی کردند و منطقه ٔ لاداخ واقع در شمال شرقی و قسمتهای دیگر مرزی تبت در نواحی شمال شرقی به تصرف نیروهای چین درآمد، و سربازان هند به طرف «نامکاشو» واقع در جنوب «ماکماهون » عقب نشستند. و همچنین پادگانهای دیگری در نزدیک مرز کشمیر را تخلیه نمودند. ارتش هند بار دیگر به پیشروی خود ادامه داد و سه مرکز مهم دیگر را در نوار مرزی اشغال نمود. در نوامبر <span class=\"hlight\" dir=\"rtl\">١٩٦٢</span> کریشنامنون که وزیر جنگ هند بود از منصب خود استعفا کرد، و جواهر لعل نهرو نخست وزیر وقت شخصاً پست وزارت جنگ را به عهده گرفت . در هفتم نوامبر نیروهای چین مجدداً به اراضی هند تجاوز نمودند. در این هنگام بود که حکومت هند از کشورهای بریتانیا و ایالات متحده و کانادا تقاضای کمک کرد که مقدار لازمی اسلحه و هواپیمای جدید به آن کشور بدهند. دولتهای مذکور درخواست هند را پذیرفتند. در <span class=\"hlight\" dir=\"rtl\">١٦</span> نوامبر دولت چین حملات نظامی را دوباره به مرزهای هند آغاز کرد و خط دفاعی هند را در جبهه ٔ شرقی کوههای «هیمالایا» منهدم ساخت . و در <span class=\"hlight\" dir=\"rtl\">١٩</span> نوامبر سربازان چین در طول <span class=\"hlight\" dir=\"rtl\">٣٥</span> کیلومتر به داخل خاک هند در امتداد رودخانه ٔ «لوهیت » به طرف دشتهای «آسام » پیشروی کردند. در بیستم نوامبر دولت چین قرارداد آتش بس را در سرتاسر مرزهای هند و چین اعلام کرد و تعهد کرد که نیروهای خود را تا اول دسامبر به داخل خاک چین در بیست کیلومتری خط مرزی که قبلاً آن را اشغال کرده بود، فراخواند و پیشنهاد کرد که منطقه ای غیرنظامی به فاصله ٔ بیست کیلومتر در بین دو کشور بوجود بیاید تا زمینه برای مذاکرات دو کشور در مورد اختلافات موجود فراهم شود. هند در این مذاکرات اصرار داشت که نیروهای چین به مواضعی که در <span class=\"hlight\" dir=\"rtl\">٨</span> سپتامبر در آن متمرکز بودند، عقب نشینی کنند. در <span class=\"hlight\" dir=\"rtl\">٢٦</span> نوامبر هند پیشنهادهای چین را در مورد آتش بس رد کرد، و روز بعد قرارداد کمکهای نظامی را با دولت انگلیس امضاء کرد. روز دهم دسامبر <span class=\"hlight\" dir=\"rtl\">١٩٦٢</span> کنفرانس کولومبو به منظور رفع اختلافات مرزی دو کشور چین و هند تشکیل شد. (از فرهنگ جغرافیائی وبستر) (از الموسوعة العربیة المیسرة). اختلافات مرزی چین و پاکستان با دولت هند هنوز برطرف نشده و یکی از نگرانی های قابل توجه جهان سیاست است <span class=\"hlight\">:</span> <br>پدر بوده در ناز و خزّ و پرند<br>مرا برده سیمرغ در کوه هند.<br> <font color=\"Red\">فردوسی .</font><br>گر از کابل و زابل و مرز هند<br>شود روی گیتی چو چینی پرند.<br><font color=\"Red\">فردوسی .</font><br>مرا شاه ایران فرستد به هند<br>به چین آیم از بهر چینی پرند.<br> <font color=\"Red\">فردوسی .</font><br>تا روم ز هند لاجرم شاها<br>گیتی همه زیر باج و سا کردی .<br> <font color=\"Red\">عسجدی .</font><br>همی نگون شود از هیبت نهیب تو را<br>به ترک خانه ٔ خان و به هند رایت رای .<br> <font color=\"Red\">عنصری .</font><br>پر از شاره و تلک و خز و پرند<br>هم از مخمل و هر طرایف ز هند.<br> <font color=\"Red\">اسدی .</font><br>این کتاب کلیله و دمنه فراهم آورده ٔ علما و براهمه ٔ هند است . (کلیله و دمنه ). در خزاین ملوک هند کتابی است که از زبان بهایم و وحوش و سباع و حشرات جمع کرده اند. (کلیله و دمنه ).<br>من همی در هند معنی راست همچون آدمم <br>وین خران در چین صورت راست چون مردم گیا.<br> <font color=\"Red\">خاقانی .</font><br>بر خط دستش که هند و چین در اوست <br>هفت گنج شایگان خواهم فشاند.<br> <font color=\"Red\">خاقانی .</font><br>هم بر آن آتش ز هند و چین و بغداد آمده <br>ماه ذی القعده به روی دجله تابان دیده اند.<br> <font color=\"Red\">خاقانی .</font><br>رجوع به هندوستان شود.<br></font></div>'),
(268626, 'هند', '<span class=\"hlight\">هند.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع اِ) گله ٔ صد شتر یا اندکی زائد از صد یا اندکی کم از آن یا دو صد. ج، اهند، اهناد، هنود. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268627, 'هند', '<span class=\"hlight\">هند.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) راه و طریق و هنجار و قاعده و قانون . (برهان ) <span class=\"hlight\">:</span> <br>گشاده بر ایشان و بر کار من <br>به هر نیک و بد هند و هنجار من .<br> <font color=\"Red\">فردوسی .</font><br> <BR><font color=\"Blue\">◄</font> (فعل ) یعنی هستند و موجودند. (برهان ). اند. صورتی از فعل بودن است برای جمع سوم شخص . هست مفرد آن است <span class=\"hlight\">:</span> <br>از مردخرد بپرس ازیرا<br>جز تو به جهان خردوران هند.<br> <font color=\"Red\">ناصرخسرو (دیوان چ تقوی ص <span class=\"hlight\" dir=\"rtl\">٩٠</span>).</font><br>با تو فردا چه بماند جز دریغ؟<br>چون برد میراث خوار آنچت که هند.<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(268628, 'هند', '<span class=\"hlight\">هند.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) هندبن عمرو. از تابعین و از یاران علی بن ابیطالب بود و در جنگ جمل شرکت کرد و به دست ابن یثربی به سال <span class=\"hlight\" dir=\"rtl\">٣٦</span> هجری کشته شد. (از اعلام زرکلی ).<br></font></div>'),
(268629, 'هند جگرخوار', '<span class=\"hlight\">هند جگرخوار.</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ج ِ گ َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (اِخ ) رجوع به هند دختر عتبة شود.<br></font></div>'),
(268630, 'هند حنا', '<span class=\"hlight\">هند حنا.</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ح َ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از سیاهی حنا باشد. (آنندراج ).<br></font></div>'),
(268631, 'هند غربی', '<span class=\"hlight\">هند غربی .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ غ َ ]</font></b> (اِخ ) نامی است که نخستین مکتشفان نیمکره ٔ جدید به سرزمینهای امریکا داده اند زیرا ابتدا تصور میکردند که به هند رسیده اند.<br></font></div>'),
(268632, 'هند پرتقال', '<span class=\"hlight\">هند پرتقال .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ پ ُ ت ِ ]</font></b> (اِخ ) نام یکی از مستعمرات کشور پرتقال در شبه قاره ٔ هند بوده است که ایالات کنونی داماو، جوا، و دیو را دربرداشته است . در سال <span class=\"hlight\" dir=\"rtl\">١٩٥٤</span> م . دولت هندوستان تصمیم گرفت که این ایالات را ضمیمه ٔ کشور اصلی هند کند و زد و خوردهای خونینی بر سر این مسئله درگرفت و سرانجام در سال <span class=\"hlight\" dir=\"rtl\">١٩٦١</span> م . دولت هند موفق شد این ایالات را از تصرف پرتقال به درآورد. (از فرهنگ جغرافیایی وبستر) (از المنجد).<br></font></div>'),
(268633, 'هندآباد', '<span class=\"hlight\">هندآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان نیشابور. دارای <span class=\"hlight\" dir=\"rtl\">٦٧</span> تن سکنه، آب آن از قنات و محصول عمده اش غله است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268634, 'هندآباد', '<span class=\"hlight\">هندآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از بخش سردشت شهرستان مهاباد. دارای <span class=\"hlight\" dir=\"rtl\">٣١٩</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله، توتون و عسل و کار دستی مردم جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268635, 'هندات', '<span class=\"hlight\">هندات .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع اِ) ج ِهند. (منتهی الارب ). گله های شتر. رجوع به هند شود.<br></font></div>'),
(268636, 'هنداز', '<span class=\"hlight\">هنداز.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (معرب، اِ) اندازه . (منتهی الارب ). معرب اندازه ٔ فارسی است . رجوع به هندسه شود.<br></font></div>'),
(268637, 'هندام', '<span class=\"hlight\">هندام .</span> <font color=\"DarkGreen\"><b>[هَِ ]</font></b> (معرب، اِ) اندام . (منتهی الارب ) <span class=\"hlight\">:</span> از هندام بیرون افتاده نباشد. (ذخیره ٔ خوارزمشاهی ).<br>- <span class=\"hlight\">بهندام </span> ؛ به اندام . مهندم . به اندازه <span class=\"hlight\">:</span> آنکه ترکیب اندامهای او مرکب درست و بهندام و بر شکل و عدد طبیعی باشد... (ذخیره ٔ خوارزمشاهی ). خرقه های بسیار بگیرند و بر شکل گویی بدوزند و گرد کنند بهندام و اندر بغل او نهند. (ذخیره ٔ خوارزمشاهی ).<br></font></div>'),
(268638, 'هندانه', '<span class=\"hlight\">هندانه .</span> <font color=\"DarkGreen\"><b>[ هَِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) هندوانه . خربزه ٔ شامی . (یادداشت مؤلف ). رجوع به هندوانه شود.<br></font></div>'),
(268639, 'هندب', '<span class=\"hlight\">هندب .</span> <font color=\"DarkGreen\"><b>[ هَِ دَ ]</font></b> (ع اِ) کاسنی . (منتهی الارب ). دانه ٔ معروفی است که خورده میشود. هندبا. هندباء. (اقرب الموارد).<br></font></div>'),
(268640, 'هندبا', '<span class=\"hlight\">هندبا.</span> <font color=\"DarkGreen\"><b>[ هَِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ع اِ) هندب . کاسنی . هندباة. بَرّی بود و بستانی . و آن دو نوع بود:یکی ورق آن پهن بود نزدیک به کاهو و نوعی دیگر ورق آن باریک بود. طعم برّی آن تلخ و نوع نیکوی آن بستانی، تر شیرین بود. بهترین نوع آن شامی است که به یونانی انطوبیا خوانند. (تحفه ٔ حکیم مؤمن ) <span class=\"hlight\">:</span> <br>تو یکی هندبا بِنَدْهی شان <br>چون دهدْشان خدای، حور و قصور؟<br> <font color=\"Red\">ناصرخسرو.</font><br>رجوع به کاسنی شود.<br></font></div>'),
(268641, 'هندبار', '<span class=\"hlight\">هندبار.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ناحیت هند. (یادداشت مؤلف ).<br></font></div>'),
(268642, 'هندباری', '<span class=\"hlight\">هندباری .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ص نسبی ) هندی . از هند. مربوط به هند <span class=\"hlight\">:</span> فرمود تا از هندباری فرجی ساختند. در آن ولایت جامه ٔ هندباری اهل عزا می پوشیدند. (مناقب العارفین ).<br>چو ماسوره ٔ هندباری به رنگ <br>میان آگنیده به تیر خدنگ .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268643, 'هندبی', '<span class=\"hlight\">هندبی .</span> <font color=\"DarkGreen\"><b>[ هَِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ با ]</font></b>(ع اِ) کاسنی . (منتهی الارب ). رجوع به هندباء شود.<br></font></div>'),
(268644, 'هندبید', '<span class=\"hlight\">هندبید.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِ) هندبا. کاسنی . (برهان ). رجوع به هندبا شود.<br></font></div>'),
(268645, 'هندخاله', '<span class=\"hlight\">هندخاله .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ل ِ ]</font></b> (اِخ ) رجوع به هنده خاله شود.<br></font></div>'),
(268646, 'هندر', '<span class=\"hlight\">هندر.</span> <font color=\"DarkGreen\"><b>[ هَُ دُ ]</font></b> (اِخ ) دهی است در بخش الیگودرز شهرستان بروجرد. دارای <span class=\"hlight\" dir=\"rtl\">٤٥٣</span> تن سکنه، آب آن از قنات و چاه، محصول عمده اش غله و کار دستی مردم بافتن قالیچه و جاجیم است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268647, 'هندزمین', '<span class=\"hlight\">هندزمین .</span> <font color=\"DarkGreen\"><b>[ هَِ زَ ]</font></b>(اِخ ) دهی است از بخش سیردان شهرستان زنجان که دارای <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(268648, 'هندس', '<span class=\"hlight\">هندس .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ]</font></b> (ع ص ) شیر دلیر. <BR><font color=\"Blue\">◄</font> مرد آزموده کار نیک نگرنده در امور. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268649, 'هندسان', '<span class=\"hlight\">هندسان .</span> <font color=\"DarkGreen\"><b>[ هَِ دُ ]</font></b> (اِخ ) مخفف هندوستان . (برهان ) <span class=\"hlight\">:</span> <br>گر ز جور تو نسیمی بگذرد بر زنگبار<br>ور ز خشم تو سمومی بروزد بر هندسان .<br><font color=\"Red\">فرخی .</font><br></font></div>'),
(268650, 'هندستان', '<span class=\"hlight\">هندستان .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ]</font></b> (اِخ ) هندوستان . هند <span class=\"hlight\">:</span> <br>هندو ز چه مغز پیل خارد؟<br>تا هندستان به یاد نارد.<br> <font color=\"Red\">نظامی .</font><br>درآمدقاصدی از ره به تعجیل <br>ز هندستان حکایت کرد با پیل .<br> <font color=\"Red\">نظامی .</font><br>چون سهی سرو برد از آن بستان <br>رفت از آنجا به ملک هندستان .<br> <font color=\"Red\">نظامی .</font><br>تا مرا ز اینجا به هندستان برد<br>بوکه بنده کآن طرف شد جان برد.<br> <font color=\"Red\">مولوی .</font><br>بر سر بخت سیه خاک سیه زیبنده است <br>ما به هندستان نه بهر مال دنیا میرویم .<br> <font color=\"Red\">صائب .</font><br>رجوع به هند و هندوستان شود.<br></font></div>'),
(268651, 'هندسه', '<span class=\"hlight\">هندسه .</span> <font color=\"DarkGreen\"><b>[ هََ دَ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ دِس َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (معرب، اِ) و در عربی به فتح اول به معنی اندازه و شکل باشد. (برهان ). از اصول علوم ریاضی است و علمی است که در آن از احوال مقدارها و اندازه ها بحث شود. (از کشاف اصطلاحات الفنون ). دانستن اندازه ها است و چندی یک از دیگر و خاصیت صورتها و شکلها که اندر جسم موجود است . (التفهیم ابوریحان بیرونی ص <span class=\"hlight\" dir=\"rtl\">٣</span>). هندسه آن رشته از ریاضیات است که مطالعه در فضا و اشکال و اجسام قابل تصور در این فضا می نماید <span class=\"hlight\">:</span> <br>ستاره شمر نیست از ما کسی <br>که از هندسه بهره دارد بسی .<br> <font color=\"Red\">فردوسی .</font><br>در چنین ادوات خصوصاً در هندسه آیتی بود. (تاریخ بیهقی ). و هیچ پادشاه چنین بنا نفرمود و همه به دانش و هندسه ٔ خویش ساخت . (تاریخ بیهقی ).<br>به علم هندسه سر برکشیده <br>به سند و هند و اطراف خراسان .<br> <font color=\"Red\">ناصرخسرو.</font><br>جمشید ملک هیأت، خورشید فلک هیبت <br>یک هندسه ٔ رایش معمار همه عالم .<br> <font color=\"Red\">خاقانی .</font><br>گر به زمین افتدی هندسه ٔ رای تو<br>قوس قزح سازدی طاق پل رود زم .<br> <font color=\"Red\">خاقانی .</font><br>ترکیب ها:<br>- <span class=\"hlight\">هندسه باز</span> . هندسه ٔ تحلیلی . هندسه ٔ ترسیمی . هندسه ٔ دیفرانسیل . هندسه ٔ رقومی . هندسه ٔ سینماتیک . هندسه ٔ غیراقلیدسی . هندسه ٔ فضایی . هندسه ٔ مسطحه . هندسه ٔ مقدماتی . رجوع به این مدخل ها شود.<br></font></div>'),
(268652, 'هندسه باز', '<span class=\"hlight\">هندسه باز.</span> <font color=\"DarkGreen\"><b>[ هَِ دِ س َ <span class=\"hlight\" dir=\"rtl\">/</span>س ِ ]</font></b> (نف مرکب ) کنایه از محیل و مکار. (آنندراج ).<br></font></div>'),
(268653, 'هندسی', '<span class=\"hlight\">هندسی .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ]</font></b> (ص نسبی ) منسوب به هندسه . مربوط به علم هندسه <span class=\"hlight\">:</span> <br>فکند از هیأت نُه حرف افلاک <br>رقوم هندسی بر تخته ٔ خاک .<br> <font color=\"Red\">نظامی .</font><br>از طبیعی و هندسی و نجوم <br>همه در دست او چو مهره ٔ موم .<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> دارای شکل هندسی . بروفق علم هندسه .بر اساس علمی <span class=\"hlight\">:</span> <br>برانوش را گفت گر هندسی <br>پلی سازی آن جایگه چون رسی .<br> <font color=\"Red\">فردوسی .</font><br>یکی از ریاضی برافراخت یال <br>یکی هندسی برگشاد از خیال .<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> داننده ٔ علم هندسه . عالم هندسه <span class=\"hlight\">:</span> <br>هست طبیب بزرگ و هست منجم <br>فلسفی و هندسی و صاحب سؤدد.<br> <font color=\"Red\">منوچهری .</font><br>- <span class=\"hlight\">تیر هندسی </span> ؛ عطارد، بدان جهت که دبیر فلک است <span class=\"hlight\">:</span> <br>ز اوصاف تو تیر هندسی را<br>یار طرف اللسان ببینم .<br> <font color=\"Red\">خاقانی .</font><br>ز اشکال تیغ او قلم تیر هندسی <br>بر سطح ماه خطِّ معما برافکند.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(268654, 'هندل', '<span class=\"hlight\">هندل .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (اِ) نامی است که در آستارا به درخت تمشک دهند. (یادداشت مؤلف ). رجوع به تمشک شود.<br></font></div>'),
(268655, 'هندل', '<span class=\"hlight\">هندل .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ]</font></b> (انگلیسی، اِ) میله ای است آهنی که در طول آن دو زاویه ٔ قائمه تشکیل شده و در سر بازوی بلند آن گیره ای تعبیه شده که به محور پروانه ٔ اتومبیل بند میشود و با گرداندن هندل پروانه به گردش درمی آید. این وسیله در اتومبیل های جدید به کار نمیرود. اصل کلمه در انگلیسی به فتح اول تلفظ میشود.<br></font></div>'),
(268656, 'هندل', '<span class=\"hlight\">هندل .</span> <font color=\"DarkGreen\"><b>[ هََ دِ ]</font></b> (اِخ ) گئورگ فریدریش . متولد <span class=\"hlight\" dir=\"rtl\">١٦٨٥</span> و متوفی به سال <span class=\"hlight\" dir=\"rtl\">١٧٥٩</span> م . موسیقی دان معروف آلمانی است . وی با اینکه پدرش اصرار داشت پزشک شود، به موسیقی علاقه نشان داد و مدتی در کلیسا نوازنده ٔ ارگ بود. در سال <span class=\"hlight\" dir=\"rtl\">١٧٠٥</span> م . نخستین اپرای خود را به نام آلمیرا نوشت و دو سال پس ازآن به ایتالیا عزیمت کرد و در آنجا اپرای رودریگو را عرضه کرد و پس از آن چند اپرا و آهنگ معروف دیگر ساخت و به ریاست موزیک مخصوص دوک شاندوس و سرپرستی آکادمی موزیک امپراطوری رسید و در پایان عمر در انگلستان زیست و بر روی هم بیشتر عمر خود را در شهرت و محبوبیت و همراه با مقام ارجمند گذرانید. (از وبستر).<br></font></div>'),
(268657, 'هندل آباد', '<span class=\"hlight\">هندل آباد.</span> <font color=\"DarkGreen\"><b>[ هََ دِ ]</font></b> (اِخ ) دهی است از بخش حومه و ارداک شهرستان مشهد. دارای <span class=\"hlight\" dir=\"rtl\">٥٣٦</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و کار دستی مردم آن قالیچه بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268658, 'هندلان', '<span class=\"hlight\">هندلان .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ]</font></b> (اِخ ) دهی است از بخش ترک شهرستان میانه . دارای <span class=\"hlight\" dir=\"rtl\">٣٧٣</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268659, 'هندلیق', '<span class=\"hlight\">هندلیق .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (ع ص ) مرد بسیارسخن . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268660, 'هندمند', '<span class=\"hlight\">هندمند.</span> <font color=\"DarkGreen\"><b>[ هَِ م َ ]</font></b> (اِخ ) رود سجستان، و گویند هزار نهر در آن ریزد و آب آن نیفزاید و هزار نهر از وی جدا شود و نکاهد. (منتهی الارب ) (معجم البلدان ). رجوع به هیرمند شود.<br></font></div>'),
(268661, 'هندمینی', '<span class=\"hlight\">هندمینی .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ]</font></b> (اِخ )نام یکی از دهستانهای چهارگانه ٔ بخش بدره ٔ شهرستان ایلام . از ده آبادی بزرگ و کوچک تشکیل شده و روی هم <span class=\"hlight\" dir=\"rtl\">١٨٠٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268662, 'هنده', '<span class=\"hlight\">هنده .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ]</font></b> (اِخ ) دهی است از بخش الیگودرز شهرستان بروجرد. دارای <span class=\"hlight\" dir=\"rtl\">٤٢١</span> تن سکنه، آب آن از چشمه و قنات و محصول عمده اش غله و لبنیات و کار دستی مردم کرباس بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268663, 'هنده خاله', '<span class=\"hlight\">هنده خاله .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ل ِ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان فومن . دارای <span class=\"hlight\" dir=\"rtl\">٢٣٧٣</span> تن سکنه، آب آن از رودخانه ٔ پسیخان و محصول عمده اش برنج، کنف وتوتون سیگار است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(268664, 'هنده کوان', '<span class=\"hlight\">هنده کوان .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ک ُ ]</font></b> (اِخ ) رودخانه ای است که به بحر خزر میریزد و محل صید ماهی است . (جغرافیای کیهان ).<br></font></div>'),
(268665, 'هندو', '<span class=\"hlight\">هندو.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ص نسبی، اِ) در زبان پهلوی هندوک، به معنی اهل هند، خصوصاً پیروان آیین قدیم هند. (از حاشیه ٔ برهان چ معین ). هندی . مردم هند. (یادداشت مؤلف ) <span class=\"hlight\">:</span> و آنجا برده ٔ هندو و جهاز هندوستانی افتد بسیار. (حدود العالم ).<br>چون ملک الهند است آن دیدگانْش <br>گردش بر، خادم هندو دو دست . <br> <font color=\"Red\">خسروی سرخسی .</font><br>تو چنین فربه و آگنده چرایی ؟ پدرت <br>هندوی بود یکی لاغر و خشکانج و نحیف .<br> <font color=\"Red\">لبیبی .</font><br>نیم شبی ایشان را گسیل باید کرد با سیصد سوار هندو. (تاریخ بیهقی ). و سه غلام هندو باید خرید از بهر خدمت او را و حوائج کشیدن . (تاریخ بیهقی ). و مردی سیصد هندو آوردند و هم در باغ بنشستند. (تاریخ بیهقی ).<br>از پارسی وتازی و از هندو و از ترک <br>وز سندی و رومی و ز بحری همه یکسر.<br> <font color=\"Red\">ناصرخسرو.</font><br>و آن اصل که هندوان کرده اند ده باب است . (کلیله و دمنه ).<br>تیغ تو داند که چیست رمز و اشارات دین <br>طرفه بود هندویی وز عربی ترجمان .<br> <font color=\"Red\">خاقانی .</font><br>شنیدم که طغرل شبی در خزان <br>گذر کرد بر هندویی پاسبان .<br> <font color=\"Red\">سعدی (بوستان ).</font><br>ز هندستان مگر بودش نمونه <br>که باشد کار هندو باژگونه .<br> <font color=\"Red\">جامی .</font><br> <BR><font color=\"Blue\">◄</font> کسی که پیرو مذهب هندوان باشد <span class=\"hlight\">:</span> و اندر او مسلمانانند و هندوان و اندر اومزگت آدینه است و بتخانه . (حدود العالم ).<br>بل هندویی است برهمن آتش گرفته سر<br>چون آب، عیدنامه ٔ زردشتی از برش .<br> <font color=\"Red\">خاقانی .</font><br> <BR><font color=\"Blue\">◄</font> پاسبان . در قدیم پاسبانی را به غلامان هندو وامیگذاشتند. (از یادداشتهای مؤلف ) <span class=\"hlight\">:</span> <br>همه ترکان چین بادند هندوش <br>مباد از چینیان چینی بر ابروش .<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> غلام . بنده . زرخرید. بیشتر به غلامان سیاه اطلاق شده است و در مقابل ترک، رومی و بابلی به کار رفته است <span class=\"hlight\">:</span> <br>هندویی بد که تو را باشد و زآن ِ تو بود<br>بهتر از ترکی کآن ِ تو نباشد، صد بار.<br> <font color=\"Red\">فرخی .</font><br>سپاه روم را کز ترک شد بیش <br>به هندی تیغ کرده هندوی خویش .<br> <font color=\"Red\">نظامی .</font><br>ز هندو جستن آن ترکتازش <br>همه ترکان شده هندوی نازش .<br> <font color=\"Red\">نظامی .</font><br>خواجه ٔ ما چون ز سفر گشت باز<br>کرد بر آن هندوی خود ترکتاز.<br> <font color=\"Red\">نظامی .</font><br>سعدی از پرده ٔ عشاق چه خوش می نالد<br>ترک من پرده برانداز که هندوی توام .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> سیاه از هر چیز <span class=\"hlight\">:</span> <br>در شب خط ساخته سحر حلال <br>بابلی غمزه و هندوی خال .<br> <font color=\"Red\">نظامی .</font><br>اگر آن ترک شیرازی به دست آرد دل ما را<br>به خال هندویش بخشم سمرقند و بخارا را.<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">طفل هندو</span> ؛ مردمک چشم <span class=\"hlight\">:</span> <br>تا نترسند این دو طفل هندو اندر مهد چشم <br>زیر دامن پوشم اژدرهای جانفرسای من .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">هندوی چرخ (هندوی هفتم چرخ )</span> ؛ ستاره ٔ زحل <span class=\"hlight\">:</span> <br>ای به رسم خدمت از آغاز دوران داشته <br>طارم قدر تو را هندوی هفتم چرخ پاس .<br> <font color=\"Red\">انوری .</font><br>- <span class=\"hlight\">هندوی چشم </span> ؛ چشم سیاه یا مردمک چشم <span class=\"hlight\">:</span> <br>هندوی چشم مبیناد رخ ترک تو باز<br>گر به چین سر زلفت به خطا مینگرم .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هندوی نه چشم </span> . رجوع به این مدخل شود.<br></font></div>'),
(268666, 'هندوآباد', '<span class=\"hlight\">هندوآباد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان پائین شهرستان اردستان . دارای <span class=\"hlight\" dir=\"rtl\">٣٦٠</span> تن سکنه، آب آن از قنات و محصول عمده اش غله است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268667, 'هندوا', '<span class=\"hlight\">هندوا.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِ) نوعی از بیش است . (مخزن الادویه ). هندبا. رجوع به هندبا شود.<br></font></div>'),
(268668, 'هندوارک', '<span class=\"hlight\">هندوارک .</span> <font color=\"DarkGreen\"><b>[ هَِ دِرَ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان سبزوار. دارای <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه، آب آن از قنات و محصول عمده اش غله، بنشن و زیره است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268669, 'هندوالان', '<span class=\"hlight\">هندوالان .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از بخش درمیان شهرستان بیرجند. دارای <span class=\"hlight\" dir=\"rtl\">٤٨٢</span> تن سکنه، آب آن از قنات و محصول عمده اش غله، شلغم و چغندر است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268670, 'هندوان', '<span class=\"hlight\">هندوان .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ )دهی است از بخش حومه ٔ شهرستان خوی . دارای <span class=\"hlight\" dir=\"rtl\">١٧٥</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و هنر دستی مردم جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268671, 'هندوان', '<span class=\"hlight\">هندوان .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) نهری است بین خوزستان و ارجان و بر آن ولایتی واقع است . (معجم البلدان ).<br></font></div>'),
(268672, 'هندوان', '<span class=\"hlight\">هندوان .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از بخش حومه ٔشهرستان خوی . دارای <span class=\"hlight\" dir=\"rtl\">٩٠</span> تن سکنه، آب آن از رود قطور و محصول عمده اش غله، حبوب، کرچک، کدو و کار دستی مردم جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268673, 'هندوان', '<span class=\"hlight\">هندوان .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (اِخ ) نام قلعه ٔ بلخ است . (برهان ).<br></font></div>'),
(268674, 'هندوان', '<span class=\"hlight\">هندوان .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ )در زبان پهلوی هندوکان به معنی هندوستان به کار رفته است . (حاشیه ٔ برهان چ معین ). از: هندو + الف و نون نسبت . جای هندو. سرزمین هندو. هندوستان <span class=\"hlight\">:</span> <br>آن کو به هندوان شد یعنی که غازیم <br>از بهر بردگان نه ز بهر غزا شده ست .<br> <font color=\"Red\">ناصرخسرو.</font><br><BR><font color=\"Blue\">◄</font> (اِ) ج ِ هندو. رجوع به هندو شود.<br></font></div>'),
(268675, 'هندوانه', '<span class=\"hlight\">هندوانه .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) هندویانه . (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span>). از: هندوان + پساوند نسبت، لغةً یعنی میوه ای که از هند می آید... گیاهی است از تیره ٔ خیار که برگهای بریده و ساقه های گسترده دارد. دلاغ . بطیخ هندی . شامی . دابوغه . فج . خربزه ٔ شامی . (یادداشتهای مؤلف ). میوه های آن درشت و مواد قندی آن برخلاف خربزه در درون بر جمع میگردد و تخمه ها در آن پراکنده اند. (از گیاه شناسی گل گلاب ) <span class=\"hlight\">:</span> <br>داروغه هندوانه و سرده خیار سبز<br>کلونده شد محصل و بدران گزیر گشت .<br> <font color=\"Red\">بسحاق اطعمه .</font><br>- <span class=\"hlight\">با یک دست دو هندوانه برداشتن </span> ؛ کنایه از کار فوق طاقت و لیاقت به عهده گرفتن است .<br>- <span class=\"hlight\">هندوانه ٔ ابوجهل </span> . رجوع به این مدخل شود.<br>- <span class=\"hlight\">هندوانه افکندن </span> ؛ کمال بیم وترس . (از آنندراج ).<br>- <span class=\"hlight\">هندوانه ٔ تلخ </span> ؛ هندوانه ٔ ابوجهل . رجوع به هر دومدخل شود.<br>- <span class=\"hlight\">هندوانه در کون کسی غلطانیدن </span> ؛ بسیار ترسانیدن . (غیاث ).<br>- <span class=\"hlight\">هندوانه زیر بغل کسی گذاشتن </span> ؛ کسی را به منظور موافق کردن با خواسته های خود بیش از اندازه ستودن و صفات برجسته به او بستن .<br></font></div>'),
(268676, 'هندوانه پردسر', '<span class=\"hlight\">هندوانه پردسر.</span> <font color=\"DarkGreen\"><b>[ هَِ دِ ن ِ پ ُ س َ ]</font></b> (اِخ ) دهی است از بخش کوچصفهان شهرستان رشت . دارای <span class=\"hlight\" dir=\"rtl\">٤٢٥</span>تن سکنه، آب آن از نورود و سفیدرود و محصول عمده اش برنج و صیفی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(268677, 'هندوانی', '<span class=\"hlight\">هندوانی .</span> <font color=\"DarkGreen\"><b>[ هَِ دُ <span class=\"hlight\" dir=\"rtl\">/</span> هَُ دُ ]</font></b> (ص نسبی ) هندی . از هندوستان . هندو. (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>چو سوسن بود تیغ هندوانی <br>از او بارنده سیل ارغوانی .<br> <font color=\"Red\">فخرالدین اسعد.</font><br>ابوصالح بن شعیب از زبان هندوانی به تازی ترجمه کرده است . (مجمل التواریخ و القصص ). <BR><font color=\"Blue\">◄</font> شمشیر منسوب به هنود. (منتهی الارب ) <span class=\"hlight\">:</span> <br>دو دندان میان دو لب چون نیامی <br>که ناگه از او برکشی هندوانی .<br> <font color=\"Red\">منوچهری .</font><br><BR><font color=\"Blue\">◄</font> منسوب به ناحیه ٔ هندوان بلخ . (سمعانی ).<br></font></div>'),
(268678, 'هندوبار', '<span class=\"hlight\">هندوبار.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) از: هندو + بار (پساوند مکان ). کشور هندوان . (از حاشیه ٔ برهان چ معین ). هندوستان . (برهان ). جای هندوها <span class=\"hlight\">:</span> <br>به خاتم تو که دریاش در کمرگاه است <br>به خامه ات که به سر میرود به هندوبار.<br> <font color=\"Red\">کمال اسماعیل .</font><br>قلم به یمن یمینش چو گرم رومرغی است <br>که خط به روم برد دمبدم ز هندوبار.<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> (اِ مرکب ) کنایه از دوات سیاهی هم هست . (برهان ).<br></font></div>'),
(268679, 'هندوبچه', '<span class=\"hlight\">هندوبچه .</span> <font color=\"DarkGreen\"><b>[ هَِ ب َ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ مرکب ) بچه ٔ سیاه . بچه ٔ هندی <span class=\"hlight\">:</span> <br>هندوبچه ای سازد از این ترک ضمیرم <br>زآن تا نشناسند بگرداند جلباب .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(268680, 'هندوخال', '<span class=\"hlight\">هندوخال .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ص مرکب ) دارای خال سیاه <span class=\"hlight\">:</span> <br>کرد را بود دختری بجمال <br>لعبتی ترک چشم و هندوخال .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268681, 'هندوخاله', '<span class=\"hlight\">هندوخاله .</span> <font color=\"DarkGreen\"><b>[ هَِ ل َ ]</font></b> (اِخ ) رودخانه ای است که به بحر خزر میریزد و محل صید ماهی است . (جغرافیای سیاسی کیهان ). رجوع به هنده خاله شود.<br></font></div>'),
(268682, 'هندودر', '<span class=\"hlight\">هندودر.</span><font color=\"DarkGreen\"><b>[ هَِ دو دَ ]</font></b> (اِخ ) دهی است از بخش سربند شهرستان اراک . دارای <span class=\"hlight\" dir=\"rtl\">١٧٠١</span> تن سکنه، آب آن از چشمه و قنات و محصول عمده اش غله، بنشن، پنبه، انگور و کار دستی مردم قالیچه بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(268683, 'هندوراس', '<span class=\"hlight\">هندوراس .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) کشوری جمهوری در امریکای مرکزی است که پنجاه ونه هزار و یکصد و شصت کیلومتر مربع وسعت دارد و مطابق آمار <span class=\"hlight\" dir=\"rtl\">١٩٤٠</span> م . جمعیت آن یک میلیون و یکصد و پنج هزار و پانصد و چهار تن بوده و در <span class=\"hlight\" dir=\"rtl\">١٩٤٥</span> به یک میلیون و دویست و یک هزار و سیصد و ده تن رسیده است . این کشور از شمال محدود است به خلیج هندوراس و دریای کاراییب، از مشرق به دریای کاراییب، از جنوب به نیکاراگوئه و از جنوب غربی به السالوادور و از مغرب به گواتمالا. این سرزمین از نخستین زمینهای قاره ٔ امریکا است که بوسیله ٔ کریستف کلمب به سال <span class=\"hlight\" dir=\"rtl\">١٥٠٢</span> کشف گردید. (از وبستر).<br></font></div>'),
(268684, 'هندوزاد', '<span class=\"hlight\">هندوزاد.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ن مف مرکب <span class=\"hlight\" dir=\"rtl\">/</span> ص مرکب ) از نسل هندو. سیه چرده <span class=\"hlight\">:</span> <br>آهوی ترک چشم هندوزاد<br>نافه ٔ مشک را گره بگشاد.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268685, 'هندوزن', '<span class=\"hlight\">هندوزن .</span> <font color=\"DarkGreen\"><b>[ هَِ زَ]</font></b> (اِ مرکب ) زن ساحره . (غیاث از شرح اسکندرنامه ).<br></font></div>'),
(268686, 'هندوس', '<span class=\"hlight\">هندوس .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع ص ) دانای امور. ج، هنادسة. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268687, 'هندوستان', '<span class=\"hlight\">هندوستان .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از بخش قاین شهرستان بیرجند. دارای <span class=\"hlight\" dir=\"rtl\">٤٦</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و پنبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268688, 'هندوستان', '<span class=\"hlight\">هندوستان .</span><font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) هند. هندستان . کشور هند <span class=\"hlight\">:</span> <br>خورد خواهد شاهد و شاه فلک محروروار<br>آن همه کافور کز هندوستان افشانده اند.<br> <font color=\"Red\">خاقانی .</font><br>پیل آمد از هندوستان، آورده طوطی بیکران <br>اینک به صحرا بی نشان طوطی است مانا ریخته .<br> <font color=\"Red\">خاقانی .</font><br>از نظاره موی را جانی که هر مویی مرا<br>طوطی گویاست کز هندوستان آورده ام .<br> <font color=\"Red\">خاقانی .</font><br>مدتی از نیل خم آسمان <br>نیل گری کرد به هندوستان .<br> <font color=\"Red\">نظامی .</font><br>آن شنیدستی که در هندوستان <br>دید دانایی گروهی دوستان .<br> <font color=\"Red\">مولوی .</font><br>رجوع به هند شود.<br></font></div>'),
(268689, 'هندوستانی', '<span class=\"hlight\">هندوستانی .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ص نسبی ) هندی . از هندوستان . (یادداشت مؤلف ).<br></font></div>'),
(268690, 'هندوسرشت', '<span class=\"hlight\">هندوسرشت .</span> <font color=\"DarkGreen\"><b>[ هَِ س ِ رِ ]</font></b> (ص مرکب ) دارای سرشت هندوان <span class=\"hlight\">:</span> <br>مهی ترک رخساره، هندوسرشت <br>ز هندوستان داده شه را بهشت .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268691, 'هندومرز', '<span class=\"hlight\">هندومرز.</span> <font color=\"DarkGreen\"><b>[ هَِم َ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان نوشهر. دارای <span class=\"hlight\" dir=\"rtl\">٨٥</span> تن سکنه، آب آن از گچرود و محصول عمده اش برنج، غله و صیفی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(268692, 'هندونژاد', '<span class=\"hlight\">هندونژاد.</span> <font color=\"DarkGreen\"><b>[ هَِ دو ن ِ ]</font></b>(ص مرکب ) از نسل هندو. هندوزاده . هندی <span class=\"hlight\">:</span> <br>فرستادگان بازگشتند شاد<br>همان قاصد پیر هندونژاد.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268693, 'هندوچین', '<span class=\"hlight\">هندوچین .</span> <font color=\"DarkGreen\"><b>[ هَِ دُ ]</font></b> (اِخ ) قسمتی از خاک آسیا است که در جنوب شرقی این قاره و در مشرق هند قرار گرفته است و شامل برمه، سیام و فدراسیون هندوچین فرانسه است که قبلاً مستعمره ٔ کشور فرانسه بوده و نیز قسمتی از آن فدراسیون مالایا است . در این سرزمین از دیرباز میان پادشاهی های مختلف، زد و خورد بوده است . پس از نفوذ اروپائیان دراین منطقه قسمت شرقی آن به دست فرانسویان افتاد و هندوچین فرانسه به وجود آمد و مرکز کشور سیام و مغرب و جنوب هندوچین ازآن ِ انگلیس شد که در سالهای <span class=\"hlight\" dir=\"rtl\">١٩٤٠</span> تا <span class=\"hlight\" dir=\"rtl\">١٩٤٥</span> مورد هجوم ژاپن واقع گردید. (از فرهنگ جغرافیایی وبستر). پس از آن در سال <span class=\"hlight\" dir=\"rtl\">١٩٥٤</span> کشوری به نام ویتنام در این ناحیه به وجود آمد. رجوع به ویتنام شود.<br></font></div>'),
(268694, 'هندوک', '<span class=\"hlight\">هندوک .</span> <font color=\"DarkGreen\"><b>[ هَِ دُ وَ ]</font></b> (اِ مصغر) مصغر هندو. (آنندراج ) <span class=\"hlight\">:</span> <br>از چو من هندوک حلقه بگوش <br>گر کله نیست کمر بازمگیر.<br> <font color=\"Red\">خاقانی .</font><br>هم هندوکی بباید آخر<br>بر درگه تو غلام و دربان .<br> <font color=\"Red\">خاقانی .</font><br>هندوک لاله و ترک سمن <br>سهل عرب بود و سهیل یمن .<br> <font color=\"Red\">نظامی .</font><br>با اینکه از او سیاه رویم <br>هم هندوک سیاه اویم .<br> <font color=\"Red\">نظامی .</font><br>خورشیدپرست شد مسلمان <br>زین هندوکان ماه زاده .<br><font color=\"Red\">امیرخسرو.</font><br></font></div>'),
(268695, 'هندوکش', '<span class=\"hlight\">هندوکش .</span> <font color=\"DarkGreen\"><b>[ هَِ ک ُ ]</font></b> (اِخ ) رشته جبالی است در شمال افغانستان که از کشمیر تا افغانستان ادامه دارد و به رشته ٔ کوههای معروف به کوه بابا می پیوندد. (از فرهنگ جغرافیایی وبستر). رجوع به هندوکوه شود.<br></font></div>'),
(268696, 'هندوکش', '<span class=\"hlight\">هندوکش .</span> <font color=\"DarkGreen\"><b>[ هَِ دُ ]</font></b> (اِخ ) دهی است از بخش داران شهرستان فریمان . دارای <span class=\"hlight\" dir=\"rtl\">١٠٩٨</span> تن سکنه، آب آن از قنات، رودخانه و چشمه، محصول عمده اش غله و حبوب، و کار دستی مردم بافتن جاجیم و قالی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268697, 'هندوکلا', '<span class=\"hlight\">هندوکلا.</span> <font color=\"DarkGreen\"><b>[ هَِ ک َ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان آمل . دارای <span class=\"hlight\" dir=\"rtl\">٦٠٥</span> تن سکنه، آب آن از رود هراز و محصول عمده اش برنج و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(268698, 'هندوکه', '<span class=\"hlight\">هندوکه .</span> <font color=\"DarkGreen\"><b>[ هَِ ک ُه ْ ]</font></b>(اِخ ) هندوکوه . هندوکش . رجوع به این دو مدخل شود.<br></font></div>'),
(268699, 'هندوکوه', '<span class=\"hlight\">هندوکوه .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) نام کوهی در کابل . (غیاث ). رجوع به هندوکش شود.<br></font></div>'),
(268700, 'هندوی', '<span class=\"hlight\">هندوی .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ص نسبی، اِ) هندو <span class=\"hlight\">:</span> <br>عشق از دل سعدی به ملامت نتوان برد<br>گر رنگ توان برد به آب از رخ هندوی .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(268701, 'هندوی', '<span class=\"hlight\">هندوی .</span> <font color=\"DarkGreen\"><b>[ هَِ دُ ]</font></b> (ص نسبی ) هندویی . هندی <span class=\"hlight\">:</span> <br>رای تو هست برتر از رای هندوان <br>تیغ تو هست برتر از تیغهندوی .<br> <font color=\"Red\">رودکی .</font><br> <BR><font color=\"Blue\">◄</font> (اِ) آن است که زر به صراف دهند و از او تنخواه بجای دیگر نویسانده گیرند و این رسم هندوستان است و آن را به فارسی سفته گویند و سفتج معرب آن است . (آنندراج ).<br>ترکیب ها:<br>- <span class=\"hlight\">هندوی اژدها</span> . هندوی کردن . هندوی گوی . هندوی نسب . رجوع به این مدخل ها شود.<br></font></div>'),
(268702, 'هندوی اژدها', '<span class=\"hlight\">هندوی اژدها.</span> <font color=\"DarkGreen\"><b>[ هَِ دُ اِ دَ ]</font></b> (اِ مرکب ) کنایه از شمشیر است و تیغ هندی . (برهان ).<br></font></div>'),
(268703, 'هندوی باریک بین', '<span class=\"hlight\">هندوی باریک بین .</span> <font color=\"DarkGreen\"><b>[ هَِ ی ِ با ]</font></b> (اِخ ) کنایه از کوکب زحل است . (برهان ).<br></font></div>'),
(268704, 'هندوی ترکستانی', '<span class=\"hlight\">هندوی ترکستانی .</span> <font color=\"DarkGreen\"><b>[ هَِ ی ِ ت ُ ک ِ ]</font></b> (اِخ ) از شیخ زادگان ترکستان بوده و در جوانی جناب خواجه عبداﷲ نقشبند او را تربیت کرده بود و این رباعی در رشحات به نام وی ثبت است :<br>هر لحظه به صورتی رخ دوست ببین <br>در آینه روی تو همان روست ببین <br>تو دیده نداری که رخ او بینی <br>ورنه ز سرت تا به قدم اوست ببین .<br><font color=\"Red\">(از ریاض العارفین رضاقلی خان هدایت ص <span class=\"hlight\" dir=\"rtl\">١٦٠</span>).</font><br></font></div>'),
(268705, 'هندوی دریانشین', '<span class=\"hlight\">هندوی دریانشین .</span> <font color=\"DarkGreen\"><b>[ هَِ ی ِدَرْ ن ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از قلم است .(انجمن آرا). کنایه از قلم نویسندگی است . (برهان ).<br></font></div>'),
(268706, 'هندوی سپهر', '<span class=\"hlight\">هندوی سپهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ی ِ س ِ پ ِ ]</font></b> (اِخ ) زحل . هندوی چرخ . رجوع به این مدخل شود.<br></font></div>'),
(268707, 'هندوی نسب', '<span class=\"hlight\">هندوی نسب .</span> <font color=\"DarkGreen\"><b>[ هَِ دُ ن َ س َ ]</font></b> (ص مرکب ) آنکه نسبتش به هندوان میرسد <span class=\"hlight\">:</span> <br>زاغ جز هندوی نسب نبود<br>دزدی از هندوان عجب نبود.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268708, 'هندوی نه چشم', '<span class=\"hlight\">هندوی نه چشم .</span> <font color=\"DarkGreen\"><b>[ هَِ ی ِ ن ُه ْ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از نی سیاه نه سوراخ است <span class=\"hlight\">:</span> <br>جنبش ده ترک لرزه دار ز شادی <br>هندوی نه چشم را به بانگ درآورد.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(268709, 'هندوی پیر', '<span class=\"hlight\">هندوی پیر.</span> <font color=\"DarkGreen\"><b>[هَِ ی ِ پی ]</font></b> (اِخ ) هندوی باریک بین . زحل . (برهان ).<br></font></div>'),
(268710, 'هندوی چرخ', '<span class=\"hlight\">هندوی چرخ .</span> <font color=\"DarkGreen\"><b>[ هَِ ی ِ چ َ ]</font></b> (اِخ ) کوکب زحل . هندوی پیر. (برهان ). هندوی هفتم چرخ . هندوی باریک بین . رجوع به این مدخل ها شود.<br></font></div>'),
(268711, 'هندوی کردن', '<span class=\"hlight\">هندوی کردن .</span> <font color=\"DarkGreen\"><b>[ هَِ دُ ک َ دَ ]</font></b> (مص مرکب ) بندگی کردن . سر نهادن <span class=\"hlight\">:</span> <br>شاه تشنیع ترک خود بشناخت <br>هندوی کرد و پیش او درتاخت .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268712, 'هندوی گنبد گردان', '<span class=\"hlight\">هندوی گنبد گردان .</span><font color=\"DarkGreen\"><b>[ هَِ ی ِ گُم ْ ب َ دِ گ َ ]</font></b> (اِخ ) هندوی سپهر. زحل . هندوی چرخ . هندوی هفتم چرخ . رجوع به هندوی چرخ شود.<br></font></div>'),
(268713, 'هندوی گوی', '<span class=\"hlight\">هندوی گوی .</span> <font color=\"DarkGreen\"><b>[ هَِ دُ ]</font></b> (نف مرکب ) آنکه سخن به هندی گوید. هندی زبان <span class=\"hlight\">:</span> <br>ز رومی رخ هندوی گوی او<br>شه رومیان گشته هندوی او.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268714, 'هندچوب', '<span class=\"hlight\">هندچوب .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان نایین . دارای <span class=\"hlight\" dir=\"rtl\">٣١١</span> تن سکنه، آب آن از قنات و محصول عمده اش غله است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268715, 'هندک', '<span class=\"hlight\">هندک .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (معرب، اِ) خندق . کنده . (زمخشری ).<br></font></div>'),
(268716, 'هندکندی', '<span class=\"hlight\">هندکندی .</span> <font color=\"DarkGreen\"><b>[ هَِک َ ]</font></b> (اِخ ) دهی است از بخش سیردان شهرستان زنجان . دارای <span class=\"hlight\" dir=\"rtl\">٣٧٣</span> تن سکنه، آب آن از رود تشویر و محصول عمده اش غله و پنبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(268717, 'هندکی', '<span class=\"hlight\">هندکی .</span> <font color=\"DarkGreen\"><b>[ هَِ دِ کی ی ]</font></b> (ع ص نسبی ) منسوب به هند. ج، هنادکة.(منتهی الارب ). لفظ فارسی است . (از اقرب الموارد).<br></font></div>'),
(268718, 'هندگشای', '<span class=\"hlight\">هندگشای .</span> <font color=\"DarkGreen\"><b>[ هَِ گ ُ ]</font></b> (نف مرکب ) فاتح هند. که هند را تسخیر کند. این لقب بیشتر به سلطان محمود اطلاق شده است <span class=\"hlight\">:</span> <br>نزد محمودشاه هندگشای <br>قصه ٔ هندوی ایاز فرست .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(268719, 'هندی', '<span class=\"hlight\">هندی .</span> <font color=\"DarkGreen\"><b>[ هَُ ن ِ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان بجنورد. دارای <span class=\"hlight\" dir=\"rtl\">٨٤</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و بنشن است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268720, 'هندی', '<span class=\"hlight\">هندی .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان حسنوند از بخش سلسله ٔ شهرستان خرم آباد.دارای <span class=\"hlight\" dir=\"rtl\">١٦٠</span> تن سکنه، آب آن از رودخانه ٔ کهمان و محصول عمده اش غله، لبنیات، پشم و حبوب و کار دستی مردم بافتن قالیچه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268721, 'هندی', '<span class=\"hlight\">هندی .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ص نسبی ) هندوستانی . (برهان ). از: هند + یاء نسبت . (از حاشیه ٔ برهان چ معین ). منسوب به هند. (منتهی الارب ). منسوب به بلاد مختلفه ٔ هند. (سمعانی ) <span class=\"hlight\">:</span> <br>تبیره درآمد ز پرده سرای <br>خروشیدن زنگ و هندی درای .<br> <font color=\"Red\">فردوسی .</font><br>بیفکند شمشیر هندی ز دست <br>یکی اسب آسوده را برنشست .<br> <font color=\"Red\">فردوسی .</font><br>بدین تیغ هندی ببرم سرت <br>بگرید به تو جوشن و مغفرت .<br> <font color=\"Red\">فردوسی .</font><br>بود بهنگام زخم در صف میدان جنگ <br>حربه ٔ هندی او حرمت تیغ یمان .<br> <font color=\"Red\">خاقانی .</font><br>برهنه یکی تیغ هندی به دست <br>سوی پادشه رفت و پنهان نشست .<br> <font color=\"Red\">نظامی .</font><br>تیغهندی و درع داودی <br>کشتی جود راند بر جودی .<br> <font color=\"Red\">نظامی .</font><br>موحد، چه در پای ریزی زرش <br>چه شمشیر هندی نهی بر سرش .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> (اِ) کنایه از تیغ و شمشیر هندی هم هست . (برهان ). در این معنی صفت بجای موصوف به کار رفته است <span class=\"hlight\">:</span> <br>زآنکه زین پس تو به زخم هندی و تاب کمند<br>کرد خواهی گردن هر بدسگالی را ادب .<br> <font color=\"Red\">فرخی .</font><br>همان رومی رایت افراخته <br>ز هندی در آب آتش انداخته .<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> نیز به معنی روش محاسبه ٔ هندی است یا ارقام هندی <span class=\"hlight\">:</span> <br>هزار ار به هندی زنی در هزار<br>بود کس که خواند مرا شهریار.<br> <font color=\"Red\">فردوسی .</font><br><BR><font color=\"Blue\">◄</font> درختی است که از میوه ٔ آن در مازندران دوشاب گیرند ولیکن در دوشاب آن لزوجتی باشد و این درخت در بیشه ها بود. چوب آن محکم باشد و از آن تله ٔ مرغان سازند. (فلاحت نامه ).<br></font></div>'),
(268722, 'هندی بلاغ', '<span class=\"hlight\">هندی بلاغ .</span> <font color=\"DarkGreen\"><b>[ هَِ ب ُ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان سنندج . دارای <span class=\"hlight\" dir=\"rtl\">١٨٥</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و توتون و کار دستی مردم بافتن جاجیم و قالیچه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268723, 'هندیان', '<span class=\"hlight\">هندیان .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) قریه ای است از اراضی فارس که معدن گوگرد دارد. (ازانجمن آرا). ناحیه ای است از حوزه ٔ بنادر جنوب، حد شمالی و شرقی آن بهبهان، مغرب آن خوزستان و جنوبش خلیج فارس است . ساکنان آن از ایلات مختلف هستند. این محل نزدیک بندر معشور است . (از جغرافیای سیاسی کیهان ).<br></font></div>'),
(268724, 'هندیجان', '<span class=\"hlight\">هندیجان .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) از بخشهای چهارگانه ٔ شهرستان خرمشهر. دارای چهارده هزار تن سکنه است . این بخش در جنوب خاوری خرمشهر واقع و شامل هشت دهستان است به نام چم خلف عیسی، چم شعبان، عبادالهی، آسیاب، سویره، گدارچینی، ده ملا و صفائیه . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268725, 'هندیجان', '<span class=\"hlight\">هندیجان .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از مرکز بخش هندیجان شهرستان خرمشهر. دارای <span class=\"hlight\" dir=\"rtl\">٢٨٣٠</span> تن سکنه، آب آن از رودخانه ٔ زهره و محصول عمده اش غله و لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268726, 'هندیز', '<span class=\"hlight\">هندیز.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان سیرجان . دارای <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه، آب آن از قنات و محصول عمده اش غله، حبوب و میوه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268727, 'هندیز', '<span class=\"hlight\">هندیز.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از بخش پاریز شهرستان سیرجان . دارای <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه، آب آن از قنات و محصول عمده اش غله و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268728, 'هندیمن', '<span class=\"hlight\">هندیمن .</span> <font color=\"DarkGreen\"><b>[ هَِ م َ ]</font></b> (اِخ ) دهی است از بخش کامیاران شهرستان سنندج . دارای <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> تن سکنه، آب آن از رود طای و چشمه و محصول عمده اش غله و انواع لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268729, 'هنر', '<span class=\"hlight\">هنر.</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ]</font></b> (اِ) علم و معرفت و دانش و فضل و فضیلت و کمال . (از ناظم الاطباء) (یادداشت مؤلف ). کیاست . فراست . زیرکی . (یادداشت مؤلف ).این کلمه در واقع به معنی آن درجه از کمال آدمی است که هشیاری و فراست و فضل و دانش را دربردارد و نمود آن صاحب هنر را برتر از دیگران مینماید <span class=\"hlight\">:</span> <br>نکوهش رسیدی به هر آهویی <br>ستایش بد از هر هنر هر سویی .<br> <font color=\"Red\">بوشکور.</font><br>فزون بایدم نیز از ایشان هنر<br>جهانجوی باید سر تاجور.<br> <font color=\"Red\">فردوسی .</font><br>پس آنگاه سام از پی پور خویش <br>هنرهای شاهان بیاورد پیش .<br> <font color=\"Red\">فردوسی .</font><br>هزاریک زآن کاندر سرشت او هنر است <br>نگار خوب هماناک نیست درارتنگ .<br> <font color=\"Red\">فرخی .</font><br>از فتح و ظفر بینم بر نیزه ٔ تو عقد<br>وز فرّ و هنر بینم بر نیزه ٔ تو یون .<br> <font color=\"Red\">عنصری .</font><br>که بیوسد ز زهر طعم شکر؟<br>نکند میل بی هنر به هنر.<br> <font color=\"Red\">عنصری .</font><br>سلطان معظم ملک عادل مسعود<br>کمتر ادبش حلم و فروتر هنرش جود.<br> <font color=\"Red\">منوچهری .</font><br>هنر را بازدانستم ز آهو<br>همیدون نغز را از زشت و نیکو.<br> <font color=\"Red\">فخرالدین اسعد.</font><br>هر کجا عنایت آفریدگار، جل جلاله آمد، همه ٔ هنرها و بزرگیها ظاهر کرد. (تاریخ بیهقی ).عیب و هنر این کارها را بازنمود. (تاریخ بیهقی ).<br>که را با تو گویند بد بیشتر<br>چو نبود گنه دان که هستش هنر.<br> <font color=\"Red\">اسدی .</font><br>اینت پر برگ و بر درختانی <br>که هنر برگ و علم بر دارند.<br> <font color=\"Red\">ناصرخسرو.</font><br>نبود هرگز عیبی ز هنر هرچند<br>هنر زید سوی عمرو عوار آید.<br> <font color=\"Red\">ناصرخسرو.</font><br>با هزاران بدی و عیب یکیشان هنر است <br>گرچه ایشان چو خر از عیب و هنر بی خبرند.<br> <font color=\"Red\">ناصرخسرو.</font><br>به روزگار پیشین در اسب شناختن و هنر و عیب ایشان دانستن هیچ گروه به از عجم ندانستندی . (نوروزنامه ). دلاورترین اسبان کمیت است و باهنرتر سمند. (نوروزنامه ).<br>گوشت بر گاو ورزه نیکوتر<br>زینت مرد دانش است و هنر.<br> <font color=\"Red\">سنائی .</font><br>ازایشان به هنر و خرد مستغنی بود. (کلیله و دمنه ). هرگاه که ملک هنرهای من بدید، بر نواخت من حریص تر از آن باشد که من بر خدمت او و هرکه از فیض آسمانی و عقل غریزی بهره مند شد و بر کسب هنر مواظبت نمود، نیکبخت گردید. (کلیله و دمنه ). و حرص تو در طلب علم و کسب هنر، مقرر. (کلیله و دمنه ). <br>رو به هنر صدر جوی بر در صدر جهان <br>رو به صفت بازگرد بر در اصحاب ما.<br> <font color=\"Red\">خاقانی .</font><br>بر تن ناقصان قبای کمال <br>به طراز هنر ندوخته اند.<br> <font color=\"Red\">خاقانی .</font><br>هست صد عیب طالعم را لیک <br>یک هنر دیده ام ز طالع خویش .<br> <font color=\"Red\">خاقانی .</font><br>بزرگتر ز هنر در عراق عیبی نیست <br>مرا مپرس که این نام بر تو چون افتاد.<br> <font color=\"Red\">ظهیر فاریابی .</font><br>زهر تو را دوست چه خواند؟ شکر<br>عیب تو را دوست چه داند؟ هنر.<br> <font color=\"Red\">نظامی .</font><br>در دو جهان عیب هنر بسته اند<br>هر دو به فتراک تو بربسته اند.<br> <font color=\"Red\">نظامی .</font><br>در همه چیزی هنر و عیب هست <br>عیب مبین تا هنر آری به دست .<br> <font color=\"Red\">نظامی .</font><br>ظرافت بسیار هنر ندیمان است و عیب حکیمان . (گلستان ).<br>گر هنری داری و هفتاد عیب <br>دوست نبیند بجز آن یک هنر.<br> <font color=\"Red\">سعدی .</font><br>عیب یاران و دوستان هنر است <br>سخن دشمنان نه معتبراست .<br> <font color=\"Red\">سعدی .</font><br>تکیه بر تقوی و دانش در طریقت کافری است <br>راهرو گر صد هنر دارد، توکل بایدش .<br> <font color=\"Red\">حافظ.</font><br>عیب می جمله بگفتی هنرش نیز بگو<br>نفی حکمت مکن از بهر دل عامی چند.<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> خطر. اهمیت <span class=\"hlight\">:</span> نباید که خطایی افتد و هنر بزرگ این است که این جیحون در میان است . (تاریخ بیهقی ). آب از فراز رودخانه آهنگ بالا داد... و بزرگتر هنر آن است که پل را با دکانها از جا بکند. (تاریخ بیهقی ). هنر بزرگ آن است که روزی خواهدبود جزا و مکافات را در آن جهان . (تاریخ بیهقی ). <BR><font color=\"Blue\">◄</font> قابلیت . (ناظم الاطباء). لیاقت . کفایت . توانایی فوق العاده ٔ جسمی یا روحی <span class=\"hlight\">:</span> <br>به نیروی یزدان پیروزگر<br>به بخت و به شمشیر و تیغ و هنر.<br> <font color=\"Red\">فردوسی .</font><br>نخست آفرین کرد بر دادگر<br>کز اوی است نیرو و فر و هنر.<br> <font color=\"Red\">فردوسی .</font><br>چو مرد بر هنر خویش ایمنی دارد<br>رود به دیده ٔ دشمن به جستن پیکار.<br> <font color=\"Red\">عنصری .</font><br>ز همت و هنر تو شگفت ماندستم <br>که ایمنی تو بر او و بر آسمان نشوی .<br> <font color=\"Red\">منوچهری .</font><br>زنان را بود شوی کردن هنر<br>بر شوی زن به که نزد پدر.<br> <font color=\"Red\">اسدی .</font><br>سخن تو بر هنر تو راجح است . (کلیله و دمنه ).<br>هنر نظر به سراپای او اگر فکند<br>ز پای تا سر او را همه هنر یابد.<br> <font color=\"Red\">سیدحسن غزنوی .</font><br>آیت تأیید باد کز پی مدحش <br>خاطر خاقانی آیت هنر آورد.<br> <font color=\"Red\">خاقانی .</font><br>گر سفر از خاک نبودی هنر<br>چرخ شب و روز نکردی سفر.<br> <font color=\"Red\">نظامی .</font><br>در هنر من از کسی کم نیستم <br>تا به خدمت پیش دشمن بیستم .<br> <font color=\"Red\">مولوی .</font><br>خواجه ام من نیز خواجه زاده ام <br>صد هنر را قابل و آماده ام .<br> <font color=\"Red\">مولوی .</font><br>اگر مرد هست از هنر بهره ور<br>هنر خود بگوید نه صاحب هنر.<br> <font color=\"Red\">سعدی .</font><br>هنر بنمای اگر داری نه گوهر<br>گل از خار است و ابراهیم از آزر.<br> <font color=\"Red\">سعدی .</font><br>اگر به هر سرمویت هنردو صد باشد<br>هنر به کار نیاید چو بخت بد باشد.<br> <font color=\"Red\">سعدی .</font><br>هنر خود ندارم وگر نیز هست <br>چو طالع نباشد هنر هیچ نیست .<br> <font color=\"Red\">عبید.</font><br>- <span class=\"hlight\">پرهنر</span> ؛ دارای لیاقت و کفایت <span class=\"hlight\">:</span> <br>بکوشی و او را کنی پرهنر<br>تو بی بر شوی چون وی آید به بر.<br> <font color=\"Red\">فردوسی .</font><br>از چنان پرهنر پدر نشگفت <br>گر چنین پرهنر پسرباشد.<br> <font color=\"Red\">مسعودسعد.</font><br>پرهنر را نیز اگرچه شد نفیس <br>کم پرست و عبرتی گیر از بلیس .<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">صاحب هنر</span> ؛ باهنر. پرهنر. لایق . کافی <span class=\"hlight\">:</span> <br>صوفی و کنج خلوت، سعدی و طرف صحرا<br>صاحب هنر نگیرد بر بی هنر بهانه .<br><font color=\"Red\">سعدی .</font><br>ترکیب ها:<br>- <span class=\"hlight\">هنرآفرین </span> .هنرآموز. هنربخش . هنربین . هنرپرور. هنرپیشه . هنرتوشه . هنرجو. هنر داشتن . هنرریزه . هنرستان . هنرسرا. هنرسوار. هنرمند. هنرنامه . هنرنمای . هنر نمودن . هنرور. هنری . رجوع به هر یک از این مدخل ها شود.<br> <BR><font color=\"Blue\">◄</font> صنعت و حرفه و شغل و پیشه و کسب . <BR><font color=\"Blue\">◄</font> برات و حواله نامه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خاصیت .(یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>می آزاده پدید آرد از بداصل <br>فراوان هنر است اندراین نبید.<br> <font color=\"Red\">رودکی .</font><br>در هیچ طعامی و میوه ای این هنر و خاصیت نیست که در شراب است . (نوروزنامه ).<br></font></div>'),
(268730, 'هنر داشتن', '<span class=\"hlight\">هنر داشتن .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ت َ ]</font></b> (مص مرکب ) دارا بودن توانایی کارهای ابتکاری <span class=\"hlight\">:</span> <br>عوام عیب کنندم که عاشقی همه عمر<br>کدام عیب که سعدی همین هنر دارد.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(268731, 'هنر نمودن', '<span class=\"hlight\">هنر نمودن .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) هنر خود را نشان دادن . هنرنمایی کردن . <BR><font color=\"Blue\">◄</font> دلیری کردن و مهارت به خرج دادن <span class=\"hlight\">:</span> <br>ز سوی دگر گیو پرخاشخر<br>ز بازو نمودی به گردان هنر.<br> <font color=\"Red\">فردوسی .</font><br>به شمشیر هندی و رومی سپر<br>نمودند هر دو به بازو هنر.<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268732, 'هنر کردن', '<span class=\"hlight\">هنر کردن .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ک َ دَ ]</font></b> (مص مرکب ) کار مهم کردن . قدرت نمودن در کار <span class=\"hlight\">:</span> <br>ای دل شباب رفت و نچیدی گلی ز عیش <br>پیرانه سر بکن هنری ننگ و نام را.<br> <font color=\"Red\">حافظ.</font><br>فارس هنر کند نه فرس در دم نبرد<br>مرکب اگر سیاه کنندش و گر کُرنگ .<br><font color=\"Red\">کاتبی .</font><br></font></div>'),
(268733, 'هنرآفرین', '<span class=\"hlight\">هنرآفرین .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ف َ ]</font></b> (نف مرکب ) کارآموز دانشمند باوقوف . (ناظم الاطباء). آنکه کار هنرمندانه کند. آنکه در کارش ابتکار و ذوق باشد.<br></font></div>'),
(268734, 'هنرآموز', '<span class=\"hlight\">هنرآموز.</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ]</font></b> (نف مرکب ) کسی که هنری چون نقاشی، مجسمه سازی، و دیگر کارهای ظریف را به دیگران یاد می دهد یا آنکه خود هنر آموزد.<br></font></div>'),
(268735, 'هنرآموزی', '<span class=\"hlight\">هنرآموزی .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ]</font></b> (حامص مرکب ) آموختن کار هنری . یاد گرفتن هنر <span class=\"hlight\">:</span> <br>چون هنرمند شدبه گفت و شنید<br>هنرآموزی سلاح گزید.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268736, 'هنربخش', '<span class=\"hlight\">هنربخش .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ب َ ]</font></b> (نف مرکب )آنکه هنر نماید و به دیگران هنر آموزد <span class=\"hlight\">:</span> <br>کو آنکه سخندان مهین بود به حکمت <br>کو آنکه هنربخش بهین بود به آداب .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(268737, 'هنربین', '<span class=\"hlight\">هنربین .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ]</font></b> (نف مرکب ) هنرشناس . آنکه هنر را دریابد و داند <span class=\"hlight\">:</span> <br>چشم هنربین نه کسی را درست <br>جز خلل و عیب ندانند جست .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268738, 'هنرجوی', '<span class=\"hlight\">هنرجوی .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ]</font></b> (نف مرکب ) هنرآموز. هنردوست . جوینده ٔ هنر. <BR><font color=\"Blue\">◄</font> دلیر. مبارز <span class=\"hlight\">:</span> <br>ز دشمن کی حذر جوید هنرجوی <br>ز دریا کی بپرهیزد گهرجوی ؟<br><font color=\"Red\">فخرالدین اسعد.</font><br></font></div>'),
(268739, 'هنرستان', '<span class=\"hlight\">هنرستان .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ رِ ]</font></b> (اِ مرکب ) جای آموختن هنر. مدرسه ٔ متوسطه که در آن به دانش آموزان کارهای هنری می آموزند.<br></font></div>'),
(268740, 'هنرسرا', '<span class=\"hlight\">هنرسرا.</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ س َ ]</font></b> (اِ مرکب ) مدرسه ای که در آن انواع هنر را به شاگردان آموزند.<br>- <span class=\"hlight\">هنرسرای عالی </span> ؛ مدرسه ٔ عالی که در آن انواع هنرآموزند.<br></font></div>'),
(268741, 'هنرسوار', '<span class=\"hlight\">هنرسوار.</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ س َ ]</font></b> (ص مرکب ) آنکه گویی هنر را چون مرکبی رام کرده و بر آن سوار است . هنرمند <span class=\"hlight\">:</span> <br>هنرسواری دلیر که روی میدان از او<br>چو کاغذ از کلک او ز نعل گیرد نشان .<br> <font color=\"Red\">مسعودسعد.</font><br>مرد هنرسوار که یک باره از هنر<br>اندر جهان نماند که او زیر ران نداشت .<br><font color=\"Red\">مسعودسعد.</font><br></font></div>'),
(268742, 'هنرفروش', '<span class=\"hlight\">هنرفروش .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ف ُ ]</font></b> (نف مرکب ) آنکه عرض هنر کند. (آنندراج ) <span class=\"hlight\">:</span> <br>کمال کسب کن اما هنرفروش مباش <br>دکان خوش است کسی در دکان نمی باید.<br><font color=\"Red\">کلیم .</font><br></font></div>'),
(268743, 'هنرمند', '<span class=\"hlight\">هنرمند.</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ م َ ]</font></b> (ص مرکب ) باهنر <span class=\"hlight\">:</span> <br>ز گیتی هنرمند و خامش تویی <br>که پروردگار سیاوش تویی .<br> <font color=\"Red\">فردوسی .</font><br>آن خریدار سخندان و سخن <br>و آن هواخواه هنرمند و هنر.<br> <font color=\"Red\">فرخی .</font><br>مرد هنرمند کش خرد نبود یار<br>باشدچون دیده ای که باشد ارمد.<br> <font color=\"Red\">منوچهری .</font><br>طرفه آنکه افاضل و مردمان هنرمند از سعایت و بطر ایشان در رنج اند. (تاریخ بیهقی ). فرمود که مردی هنرمند باید طلبید. (کلیله و دمنه ). همیشه هنرمند به حسد بی هنران در معرض تلف افتد. (کلیله و دمنه ).<br>تو نیز به زیر ران درآری <br>آن رخش تکاور هنرمند.<br> <font color=\"Red\">خاقانی .</font><br>هنرمندکی زیر نادان نشیند<br>که بالای سرطان نشسته ست جوزا.<br> <font color=\"Red\">خاقانی .</font><br>چون دید سلیم کآن هنرمند<br>از نان به گیاه گشته خرسند.<br> <font color=\"Red\">نظامی .</font><br>بر این گفتار بر بگذشت یک چند<br>که شد در هر هنر خسرو هنرمند.<br><font color=\"Red\">نظامی .</font><br>چو بر شاه آفرین کرد آن هنرمند<br>جوابش دادکای گیتی خداوند.<br> <font color=\"Red\">نظامی .</font><br>گر بی هنرم و گر هنرمند<br>لطف است امیدم از خداوند.<br> <font color=\"Red\">سعدی .</font><br>حقایق شناسی، جهاندیده ای <br>هنرمندی، آفاق گردیده ای .<br> <font color=\"Red\">سعدی .</font><br>که دریافتم حاتم نامجوی <br>هنرمند و خوش منظر و خوبروی .<br> <font color=\"Red\">سعدی .</font><br>گر هنرمند گوشه گیر بود<br>کام دل از هنر کجا یابد؟<br> <font color=\"Red\">ابن یمین .</font><br> <BR><font color=\"Blue\">◄</font> دلیر و مبارز <span class=\"hlight\">:</span> <br>بدو گفت گرسیوز ای شهریار<br>هنرمند وز خسروان یادگار.<br> <font color=\"Red\">فردوسی .</font><br>ز پشت سیاوش یکی شهریار<br>هنرمند وز گوهر نامدار.<br> <font color=\"Red\">فردوسی .</font><br>بدو گفت بهرام : ای شهریار<br>جوان و هنرمند و گردو سوار.<br> <font color=\"Red\">فردوسی .</font><br>چه مرد است گفت این هنرمند گرد<br>هنرهاش گفتن بِنَتوان شمرد.<br> <font color=\"Red\">اسدی .</font><br><BR><font color=\"Blue\">◄</font> قوی . نیرومند <span class=\"hlight\">:</span> <br>همیشه هنرمند بادا تنت <br>رسیده به کام آن دل روشنت .<br> <font color=\"Red\">فردوسی .</font><br><BR><font color=\"Blue\">◄</font> در تداول، کسی که هنری چون شاعری، خوانندگی، نقاشی، نوازندگی، بازیگری و جز آن را پیشه ٔ خود سازد.<br></font></div>'),
(268744, 'هنرمندی', '<span class=\"hlight\">هنرمندی .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ م َ ]</font></b> (حامص مرکب ) دارای هنر بودن . چیره دستی . شگفتی در کار یا اشتغال به کارهای هنری چون نقاشی، پیکرسازی، شاعری، خوانندگی، نوازندگی و مانند آن و مهارت در آن هنرها <span class=\"hlight\">:</span> <br>هنرمندی ز تو نادر نباشد<br>چو ملک شاه باشد اوستادت .<br> <font color=\"Red\">مسعودسعد.</font><br> <BR><font color=\"Blue\">◄</font> دلیری . زورمندی <span class=\"hlight\">:</span> <br>هنرمندی و رای و پرهیز و دین <br>زبان چرب و جوینده ٔ آفرین .<br> <font color=\"Red\">فردوسی .</font><br>همان با هنرمندی و رای او<br>نبینیم کس نیز همتای او.<br> <font color=\"Red\">فردوسی .</font><br>رجوع به هنرمند شود.<br></font></div>'),
(268745, 'هنرنامه', '<span class=\"hlight\">هنرنامه .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ]</font></b> (اِ مرکب ) سرگذشت بزرگان و هنرمندان <span class=\"hlight\">:</span> <br>هنرنامه های عرب خوانده بود<br>در آن آرزو سالها مانده بود.<br> <font color=\"Red\">نظامی .</font><br>قدر اهل هنر کسی داند<br>که هنرنامه ها بسی خواند.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268746, 'هنرنمای', '<span class=\"hlight\">هنرنمای .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ ]</font></b> (نف مرکب ) آنکه هنر و کاردانی خود را به دیگران بنماید <span class=\"hlight\">:</span> دانا چو طبله ٔ عطار است، خاموش و هنرنمای . (گلستان ).<br></font></div>'),
(268747, 'هنرنمایی', '<span class=\"hlight\">هنرنمایی .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ ]</font></b> (حامص مرکب ) نشان دادن و اظهار کردن هنر <span class=\"hlight\">:</span> <br>چون در جهان نماندت آب هنرنمایی <br>ای سوخته توانی کاین خام کم درایی .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(268748, 'هنرور', '<span class=\"hlight\">هنرور.</span> <font color=\"DarkGreen\"><b>[هَُ ن َرْ وَ ]</font></b> (ص مرکب ) (از: هنر + ور، پساوند اتصاف و دارندگی ) دارای هنر. هنرمند. باهنر <span class=\"hlight\">:</span> <br>غماز را به حضرت سلطان که راه داد<br>هم صحبت تو همچو تو باید هنروری .<br> <font color=\"Red\">سعدی .</font><br>هنرور چنین زندگانی کند<br>جفا بیند و مهربانی کند.<br> <font color=\"Red\">سعدی .</font><br>هنرور که بختش نباشد بکام <br>به جایی رود کش ندانند نام .<br> <font color=\"Red\">سعدی .</font><br>رجوع به هنروری شود.<br></font></div>'),
(268749, 'هنروری', '<span class=\"hlight\">هنروری .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َرْ وَ ]</font></b> (حامص مرکب ) هنرمندی . هنر داشتن <span class=\"hlight\">:</span> از نفس پرور هنروری نیاید. (گلستان ).<br></font></div>'),
(268750, 'هنرپرور', '<span class=\"hlight\">هنرپرور.</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ پ َرْ وَ ]</font></b>(نف مرکب ) آنکه برای پیشرفت هنر بکوشد <span class=\"hlight\">:</span> <br>هنرپرور و رادو بخشنده گنج <br>از این تخمه هرگز نبد کس به رنج .<br> <font color=\"Red\">فردوسی .</font><br>وزیر جهاندار گیتی فروز<br>وزیر هنرپرور رایزن .<br> <font color=\"Red\">فرخی .</font><br>خسرو غازی محمود محمدسیرت <br>شاه دین ورز هنرپرور کامل فرهنگ .<br> <font color=\"Red\">فرخی .</font><br>حسن کجا شد و کو بایزید بسطامی <br>امیر ادهم و فرزند آن هنرپرور.<br> <font color=\"Red\">ناصرخسرو.</font><br>بر هر دو روی سکه ٔ ایام نام تو<br>خاقان عدل ورز هنرپرور آمده .<br> <font color=\"Red\">خاقانی .</font><br>پس آنگاه گفت ای هنرپروران <br>بسی کردم اندیشه در اختران .<br> <font color=\"Red\">نظامی .</font><br>نکردند رغبت هنرپروران <br>به شادی خویش از غم دیگران .<br> <font color=\"Red\">سعدی .</font><br>خردمند مردم هنرپرورند<br>که تن پروران از هنر لاغرند.<br> <font color=\"Red\">سعدی .</font><br>گر دیگری به شیوه ٔ حافظ زدی رقم <br>مقبول طبع شاه هنرپرور آمدی .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(268751, 'هنرپروری', '<span class=\"hlight\">هنرپروری .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ پ َرْ وَ ]</font></b> (حامص مرکب ) پروردن و تربیت کردن هنرمندان را. هنر را بزرگ داشتن . کوشش برای هنر <span class=\"hlight\">:</span> <br>نجوید کسی بر کسی برتری <br>مگر از طریق هنرپروری .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268752, 'هنرپیشه', '<span class=\"hlight\">هنرپیشه .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) هنرمند <span class=\"hlight\">:</span> <br>هنرپیشه آن است کز فعل نیک <br>سر خویش را تاج، خودبرنهد.<br> <font color=\"Red\">ناصرخسرو.</font><br>هنرپیشه فرزنداستاد او<br>که همدرس او بود و همزاد او.<br> <font color=\"Red\">نظامی .</font><br>بدان خوبروی هنرپیشه داد<br>هنرپیشه را دل به اندیشه داد.<br> <font color=\"Red\">نظامی .</font><br>هنرپیشه راپیش خواند اوستاد<br>که چون است از ما نیاری تو یاد؟<br> <font color=\"Red\">نظامی .</font><br>شبی سر فروشد به اندیشه ام <br>به دل برگذشت آن هنرپیشه ام .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> آنکه کاری بزرگ کند. دلیر. مبارز <span class=\"hlight\">:</span> <br>مرد هنرپیشه خود نگردد ساکن <br>کز پی کاری شده ست گردون گردان .<br> <font color=\"Red\">ابوحنیفه ٔ اسکافی .</font><br>ای خردمند هنرپیشه و بیدار و بصیر<br>کیست از خلق به نزدیک تو هشیار و خطیر؟<br> <font color=\"Red\">ناصرخسرو.</font><br>او که در این پایه هنرپیشه نیست <br>از سپر و تیغ وی اندیشه نیست .<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> دانشمند. دارای دانش بسیار <span class=\"hlight\">:</span> <br>که بود از ندیمان خسروخرام <br>هنرپیشه ای ارشمیدس به نام .<br> <font color=\"Red\">نظامی .</font><br><BR><font color=\"Blue\">◄</font> در تداول امروز، کسی که در سینما، تآتر، آواز و هنرهای نمایشی دیگر کار کند و آن هنر را حرفه ٔ خویش سازد.<br></font></div>'),
(268753, 'هنرکده', '<span class=\"hlight\">هنرکده .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) هنرستان . هنرسرا. جای آموزش هنر: هنرکده ٔ خیاطی، هنرکده ٔ نقاشی، هنرکده ٔ صنعتی .<br></font></div>'),
(268754, 'هنرگستر', '<span class=\"hlight\">هنرگستر.</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ گ ُ ت َ ]</font></b> (نف مرکب ) هنرمند. باهنر <span class=\"hlight\">:</span> <br>چنین گفت پس ای هنرگستران <br>مدارید دلها به من بر گران .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268755, 'هنری', '<span class=\"hlight\">هنری .</span> <font color=\"DarkGreen\"><b>[ هَُن َ ]</font></b> (ص نسبی ) اهل هنر. هنرمند. هنرور <span class=\"hlight\">:</span> <br>خواجه ٔ سید ابوسهل رئیس الرؤسا<br>احمدبن الحسن آن بارخدای هنری .<br> <font color=\"Red\">فرخی .</font><br>آن هنری خواجه ٔ جلیل چو دریاست <br>با هنربیشمار و گوهر بی عد.<br> <font color=\"Red\">منوچهری .</font><br>آفرین زآن هنری مرکب فرخ پی تو<br>که به یک شب ز بلاساغون آید به طراز.<br> <font color=\"Red\">منوچهری .</font><br>هنری سرفکنده چون لاله است <br>که کلاهش به سر ندوخته اند.<br> <font color=\"Red\">خاقانی .</font><br>هرکو هنری است و عیب خود گفت <br>با جان هنر قرین شمارش .<br> <font color=\"Red\">خاقانی .</font><br><BR><font color=\"Blue\">◄</font> دلیر <span class=\"hlight\">:</span> سام نریمان را پرسیدند که آرایش رزم چیست ؟ گفت : فر ارجمند شاه، دانش سپهبد بارای و مبارز هنری . (نوروزنامه ).<br></font></div>'),
(268756, 'هنری کردن', '<span class=\"hlight\">هنری کردن .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ک َ دَ ]</font></b>(مص مرکب ) هنرمند ساختن . باهنر کردن . <BR><font color=\"Blue\">◄</font> شجاعت در کسی به وجود آوردن . دلیر کردن <span class=\"hlight\">:</span> <br>بر سر من تاج دین نهاده شود<br>دین هنری کرد و بردبار مرا.<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(268757, 'هنریافته', '<span class=\"hlight\">هنریافته .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف مرکب ) باهنر. دارای هنر <span class=\"hlight\">:</span> <br>بماناد تا روز ماند جوان <br>هنریافته جان نوشین روان .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268758, 'هنزا', '<span class=\"hlight\">هنزا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است ازبخش مهریز شهرستان یزد. دارای <span class=\"hlight\" dir=\"rtl\">١٦٧٤</span> تن سکنه، آب آن از قنات و محصول عمده اش غله و کار دستی مردم کرباس بافی و نساجی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268759, 'هنزا', '<span class=\"hlight\">هنزا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهستانی است از بخش ساردوئیه ٔ شهرستان جیرفت . دارای دوهزار تن سکنه و شامل <span class=\"hlight\" dir=\"rtl\">٥١</span> آبادی . آب آن از رودخانه و چشمه و محصول عمده ٔ دهستان غله، حبوب و لبنیات است . مرکز دهستان قریه ٔ هنزا است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268760, 'هنزرپنزر', '<span class=\"hlight\">هنزرپنزر.</span> <font color=\"DarkGreen\"><b>[ هَِ زِ پ ِ زِ ]</font></b> (اِ مرکب، از اتباع ) خرت وپرت . اسباب بی ارزش . (یادداشت مؤلف ). آشغال . چیزهای بدردنخور. خرده ریز. (یادداشت مؤلف ). معمولاً به چیزهایی نیز اطلاق شود که آلوده باشد.<br></font></div>'),
(268761, 'هنزمن', '<span class=\"hlight\">هنزمن .</span> <font color=\"DarkGreen\"><b>[ هَِ زَ ]</font></b> (معرب، اِ) انجمن . (منتهی الارب ). در پهلوی ساسانی هنجمن به فتح اول و سوم و چهارم است . (فرهنگ فارسی معین ). رجوع به انجمن شود.<br></font></div>'),
(268762, 'هنزک', '<span class=\"hlight\">هنزک .</span> <font color=\"DarkGreen\"><b>[ هََ زَ ]</font></b> (اِخ ) دهی است از بخش افجه ٔ شهرستان تهران . دارای <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> تن سکنه، آب آن از رود گلندوک و محصول عمده اش غله، بنشن، میوه وچوب قلمستان است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(268763, 'هنزی', '<span class=\"hlight\">هنزی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان اهواز. دارای <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> تن سکنه، آب آن از چاه و محصولش غله است . ساکنان از طایفه ٔ حمید هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268764, 'هنشنش', '<span class=\"hlight\">هنشنش .</span> <font color=\"DarkGreen\"><b>[ هََ ن َ ن َ ]</font></b>(ع ص ) سبک . چست . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268765, 'هنشک', '<span class=\"hlight\">هنشک .</span> <font color=\"DarkGreen\"><b>[ هََ ن ُ ]</font></b> (اِخ ) دهی است از دهستان بافق شهرستان یزد. دارای <span class=\"hlight\" dir=\"rtl\">٨١</span> تن سکنه، آب آن از قنات و محصول عمده اش غله و برنج و کار دستی زنان آنجا کرباس بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268766, 'هنشگ', '<span class=\"hlight\">هنشگ .</span> <font color=\"DarkGreen\"><b>[ هَِ ن ِ ]</font></b> (اِخ ) دهی است از بخش بوانات و سرچهان شهرستان آباده . دارای <span class=\"hlight\" dir=\"rtl\">١٩٤</span>تن سکنه، آب آن از قنات و محصول عمده اش غله، حبوب، انار و انجیر است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(268767, 'هنشین', '<span class=\"hlight\">هنشین .</span> <font color=\"DarkGreen\"><b>[ هََ ن ِ ]</font></b> (اِخ ) دهی است از دهستان ساردوئیه ٔ شهرستان جیرفت . دارای یک خانوار سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268768, 'هنطه', '<span class=\"hlight\">هنطه .</span> <font color=\"DarkGreen\"><b>[ هََ طِ ]</font></b> (اِخ ) دهی است از بخش ساردوئیه ٔ شهرستان جیرفت . دارای <span class=\"hlight\" dir=\"rtl\">٥٥</span> تن سکنه، آب آن از قنات و محصول عمده اش غله و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268769, 'هنع', '<span class=\"hlight\">هنع.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) پیچیدن چیزی را و دوتا ساختن . <BR><font color=\"Blue\">◄</font> فروتنی کردن برای کسی . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268770, 'هنع', '<span class=\"hlight\">هنع.</span><font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (ع مص ) پست گردن گردیدن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خمیده قامت گردیدن . <BR><font color=\"Blue\">◄</font> (اِمص ) کجی قامت . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پستی گردن شتر به روشی که بیخ گردنش پست گردد و سر بلند، و میانه ٔ دو شانه برآمده باشد و نیز هنع در آهوان خاص است به آهوی سپیدی که کوتاه گردن باشد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268771, 'هنع', '<span class=\"hlight\">هنع.</span> <font color=\"DarkGreen\"><b>[ هَُ ن ْ ن َ ]</font></b> (ع ص، اِ) ج ِ هانع. (منتهی الارب ) (از اقرب الموارد). رجوع به هانع شود.<br></font></div>'),
(268772, 'هنق', '<span class=\"hlight\">هنق .</span> <font color=\"DarkGreen\"><b>[هََ ن َ ]</font></b> (ع اِمص ) تفتگی و بی آرامی از اندوه که به مردم عارض شود. حنق . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268773, 'هنقب', '<span class=\"hlight\">هنقب .</span> <font color=\"DarkGreen\"><b>[ هََ ق َ ]</font></b> (ع ص ) کوتاه . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268774, 'هنم', '<span class=\"hlight\">هنم .</span> <font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (اِخ ) دهی است از بخش پاپی شهرستان خرم آباد. دارای <span class=\"hlight\" dir=\"rtl\">١٦٠</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و لبنیات است و ساکنان آنجا از طایفه ٔ پاپی هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(268775, 'هنم', '<span class=\"hlight\">هنم .</span> <font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (ع اِ) خرما یا نوعی از آن . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268776, 'هنمة', '<span class=\"hlight\">هنمة.</span> <font color=\"DarkGreen\"><b>[ هَِ ن ْ ن َ م َ ]</font></b> (ع اِ) شبهی از شبه های زنان که جهت افسون با خود دارند. <BR><font color=\"Blue\">◄</font> (ص ) مرد زشت پیکر کوتاه . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268777, 'هنمد', '<span class=\"hlight\">هنمد.</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (اِ) سبزیی را گویند که بر روی آب بهم رسد. (برهان ).<br></font></div>'),
(268778, 'هننة', '<span class=\"hlight\">هننة.</span> <font color=\"DarkGreen\"><b>[ هََ ن َ ن َ ]</font></b> (ع اِ)نوعی از خارپشت . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268779, 'هنو', '<span class=\"hlight\">هنو.</span> <font color=\"DarkGreen\"><b>[ هَِ ن ْوْ ]</font></b> (ع اِ) هنگام . <BR><font color=\"Blue\">◄</font> (اِخ ) پدر قبیله ای است . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268780, 'هنوات', '<span class=\"hlight\">هنوات .</span> <font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (ع اِ) ج ِ هناة. (منتهی الارب ).<br></font></div>'),
(268781, 'هنوار', '<span class=\"hlight\">هنوار.</span> <font color=\"DarkGreen\"><b>[ هََ ن ْ ]</font></b> (ص ) هموار. (آنندراج ). با اینکه آنندراج شاهدی برای این صورت آورده است، گمان میرود که تغییر حرف میم به نون خطای کاتبان است .<br></font></div>'),
(268782, 'هنوتاس', '<span class=\"hlight\">هنوتاس .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) نزدیکان و مقربان درگاه احدیت را گویند. (برهان ). برساخته ٔ فرقه ٔ آذرکیوان است . (از حاشیه ٔ برهان چ معین ).<br></font></div>'),
(268783, 'هنوج', '<span class=\"hlight\">هنوج .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان خنامان شهرستان رفسنجان . دارای <span class=\"hlight\" dir=\"rtl\">٤١</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268784, 'هنود', '<span class=\"hlight\">هنود.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع اِ) ج ِ هند. (منتهی الارب ). ج ِ هندی . (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>پیل اندر خانه ٔتاریک بود<br>عرضه را آورده بودندش هنود.<br><font color=\"Red\">مولوی .</font><br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(268785, 'هنوز', '<span class=\"hlight\">هنوز.</span><font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ق ) تاکنون و تا حال . (برهان ) <span class=\"hlight\">:</span> <br>دلم پرآتش کردی و قد و قامت کوز<br>فرازنامد هنگام مردمیت هنوز؟<br> <font color=\"Red\">آغاجی .</font><br>هنوز از لبت شیر بوید همی <br>دلت ناز و شادی بجوید همی .<br> <font color=\"Red\">فردوسی .</font><br>بدو گفت نیرنگ سازی هنوز<br>نگردد همی پشت شوخ تو کوز؟<br> <font color=\"Red\">فردوسی .</font><br>هنوز آن کمربند نگشاده ام <br>همان تیغ پولاد ننهاده ام .<br><font color=\"Red\">فردوسی .</font><br>پیش من یک بار او شعر یکی دوست بخواند<br>زآن زمان باز هنوز این دل من پرهنر است .<br> <font color=\"Red\">لبیبی .</font><br>تهی نکرده بدم جام می هنوز ازمی <br>که کرده بودم ازخون دو دیده مالامال .<br> <font color=\"Red\">زینبی .</font><br>هنوز اندرآن خانه ٔ گبرکان <br>بمانده ست بر جای چون عرعری .<br> <font color=\"Red\">منوچهری .</font><br>باش که این پادشه هنوز جوان است <br>نیم رسیده یکی هزبردمان است .<br> <font color=\"Red\">منوچهری .</font><br>عصیر جوانه هنوز از قدح <br>همی زد به تعجیل پرتابها.<br> <font color=\"Red\">منوچهری .</font><br>هنوز ده روز برنیامده است که حصیری آب این کار را پاک بریخت . (تاریخ بیهقی ).<br>هنوز اندراین کار بد سرفراز<br>رسیدند دو پیر نزدش فراز.<br> <font color=\"Red\">اسدی .</font><br>بنی امیه شدند و ز بعد بن عباس <br>بسی شدند و از ایشان هنوز نیست اثر.<br> <font color=\"Red\">ناصرخسرو.</font><br>اگر هنوز شوری مانده باشد روزی دیگر در آب کنند. (ذخیره ٔ خوارزمشاهی ). و آن باغ که در او تخم انگور بکشتند هنوز برجاست . (نوروزنامه ). گفت : اگر نه آنستی که تو هنوز خردی و این ادب نیاموخته ای من تو را امروز مالشی دادمی . (نوروزنامه ).<br>کشمکش جور در اعضا هنوز<br>کن مکن عدل نه پیدا هنوز.<br> <font color=\"Red\">نظامی .</font><br>هنوز از عشقبازی گرم و داغ است <br>هنوزش شور شیرین در دماغ است .<br> <font color=\"Red\">نظامی .</font><br>هنوزم آب در جوی جوانی است <br>هنوزم لب پر آب زندگانی است .<br> <font color=\"Red\">نظامی .</font><br>هنوزم هندوان آتش پرستند<br>هنوزم چشم چون ترکان مستند.<br> <font color=\"Red\">نظامی .</font><br>اگر بیگانگان تشریف بخشند<br>هنوز از دوستان خوشتر گدایی .<br> <font color=\"Red\">سعدی .</font><br>هنوز با همه بدعهدیت دعا گویم <br>هنوز با همه بدمهریت طلبکارم .<br> <font color=\"Red\">سعدی .</font><br>آید هنوزشان ز لب لعل بوی شیر<br>شیرین لبان نه شیر که شکر مزیده اند.<br> <font color=\"Red\">سعدی .</font><br>برنیامد از تمنای لبت کامم هنوز<br>بر امید جام لعلت دردی آشامم هنوز<br>در ازل داده ست ما را ساقی لعل لبت <br>جرعه ٔ جامی که من مدهوش آن جامم هنوز<br>ساقیا یک جرعه ای زآن آب آتشگون که من <br>در میان پختگان عشق او خامم هنوز.<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> بهتر. از آن بهتر است <span class=\"hlight\">:</span> <br>عزی که آن ز فضل نباشد هنوزذل <br>فخری که آن ز فضل نباشد هنوز عار.<br> <font color=\"Red\">فرخی .</font><br> <BR><font color=\"Blue\">◄</font> تا این حد. باز. (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>گرنه به انصاف شوی پرده دوز<br>حیف بود در حق جاهل هنوز.<br><font color=\"Red\">امیرخسرو دهلوی .</font><br></font></div>'),
(268786, 'هنومرور', '<span class=\"hlight\">هنومرور.</span> <font color=\"DarkGreen\"><b>[ هََ م َرْ وَ ]</font></b> (اِخ ) دهی است از بخش خضرآباد شهرستان یزد. دارای <span class=\"hlight\" dir=\"rtl\">٤٢٨</span> تن سکنه، آب آن از قنات و محصول عمده اش غلات و هنر دستی زنان آنجا کرباس بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(268787, 'هنون', '<span class=\"hlight\">هنون .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) ج ِ هن . (منتهی الارب ).<br></font></div>'),
(268788, 'هنوند', '<span class=\"hlight\">هنوند.</span> <font color=\"DarkGreen\"><b>[ هََ ن ْ وَ ]</font></b> (اِ) حیا و شرم . (آنندراج ).<br></font></div>'),
(268789, 'هنوی', '<span class=\"hlight\">هنوی .</span> <font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (ص نسبی )منسوب به هنا که قبیله ای است از قضاعة. (سمعانی ).<br></font></div>'),
(268790, 'هنک', '<span class=\"hlight\">هنک .</span><font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان کرمان . دارای <span class=\"hlight\" dir=\"rtl\">١٢٥</span> تن سکنه، آب آن از قنات و محصول عمده اش غله و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268791, 'هنکوه', '<span class=\"hlight\">هنکوه .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان مهاباد. محصول عمده اش غله و حبوب و توتون و کار دستی مردم آنجابافتن جاجیم است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268792, 'هنگ', '<span class=\"hlight\">هنگ .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش درمیان شهرستان بیرجند. دارای <span class=\"hlight\" dir=\"rtl\">٤٤</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله، شلغم و چغندر است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268793, 'هنگ', '<span class=\"hlight\">هنگ .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِ) ذخیره . <BR><font color=\"Blue\">◄</font> توشه و قوت . <BR><font color=\"Blue\">◄</font> قدرت و توانایی . (ناظم الاطباء).<br></font></div>'),
(268794, 'هنگ', '<span class=\"hlight\">هنگ .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِ) زحیر و پیچش شکم . (برهان ). <BR><font color=\"Blue\">◄</font> بختیاری و بهره مندی . <BR><font color=\"Blue\">◄</font> ساعات خجسته و مبارک . <BR><font color=\"Blue\">◄</font> فهم و فراست و هوش . <BR><font color=\"Blue\">◄</font> انغوزه . (ناظم الاطباء). به هندی صمغ درخت اشترغار است . (برهان ).<br></font></div>'),
(268795, 'هنگ', '<span class=\"hlight\">هنگ .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) سنگینی و تمکین و وقار. (برهان ). سنگ . (حاشیه ٔ برهان چ معین ) <span class=\"hlight\">:</span> <br>ای زدوده سایه ٔ تو ز آینه ی ْ فرهنگ زنگ <br>بر خرد سرهنگ و فخر عالم و فرهنگ هنگ .<br> <font color=\"Red\">کسائی .</font><br>خداوندا ندیدم هیچ سالاری به سنگ تو<br>نه اندر کارها شاهی به آئین و به هنگ تو.<br> <font color=\"Red\">فرخی .</font><br>شجاعت از هنر و بازوی تو گیرد نام <br>مروت از سپر و همت تو گیرد هنگ .<br> <font color=\"Red\">فرخی .</font><br>ای رئیس مهربان این مهرگان خرم گذار<br>فرّ و فرمان فریدون ورز با فرهنگ و هنگ .<br> <font color=\"Red\">منوچهری .</font><br>مردمان زمانه بی هنرند<br>زانکه فرهنگشان ندارد هنگ .<br> <font color=\"Red\">مسعودسعد.</font><br>پر و بال از تو یافته رادی <br>فرّ و هنگ از تو یافته فرهنگ .<br> <font color=\"Red\">سنایی .</font><br>- <span class=\"hlight\">بهنگ </span> ؛ باهنگ . باوقار. متین <span class=\"hlight\">:</span> <br>یاری بودی سخت به آئین و بهنگ <br>همسایه ٔ تو بهانه جوی و دل سنگ .<br> <font color=\"Red\">فرخی .</font><br> <BR><font color=\"Blue\">◄</font> در زبان پهلوی، هنگ = فهم و معرفت . (حاشیه ٔ برهان چ معین ). دریافت و فهم و ادراک و فراست و هوش . (ناظم الاطباء). دانایی و هشیاری . (برهان ) <span class=\"hlight\">:</span> <br>که او را سپارم به فرهنگیان <br>که دارد سر مایه و هنگ آن .<br> <font color=\"Red\">فردوسی .</font><br>یکی پیلتن دیدم و شیرچنگ <br>نه هوش و نه دانش، نه رای و نه هنگ .<br> <font color=\"Red\">فردوسی .</font><br>برادر شد، آن مرد هنگ و خرد<br>سرانجام من هم بر این بگذرد.<br> <font color=\"Red\">فردوسی .</font><br>جهان به خدمت او میل دارد و نشگفت <br>که خدمتش طلبد هرکه هوش دارد و هنگ .<br> <font color=\"Red\">فرخی .</font><br>هوش و هنگت برد به گردون سر<br>که بدین یافت سروری هوشنگ .<br> <font color=\"Red\">ناصرخسرو.</font><br>گرت هوش است و هنگ دار حذر<br>ای خردمند از این عظیم نهنگ .<br> <font color=\"Red\">ناصرخسرو.</font><br>- <span class=\"hlight\">باهنگ </span> ؛ باهوش . هشیار <span class=\"hlight\">:</span> <br>به منذر چنین گفت روزی جوان <br>که ای مرد باهنگ روشن روان .<br> <font color=\"Red\">فردوسی .</font><br>- <span class=\"hlight\">بهنگ </span> ؛ باهنگ . باهوش <span class=\"hlight\">:</span> <br>همه به تیغ گرفته ست و از شهان ستده ست <br>شهان پردل جنگ آور بهوش و بهنگ .<br> <font color=\"Red\">فرخی .</font><br> <BR><font color=\"Blue\">◄</font> غم خواری . (ناظم الاطباء). نگاه داشتن و غم خواری کردن . (برهان ) <span class=\"hlight\">:</span> <br>بدو گفت شیده که این نیست هنگ <br>که ما زنده و تو درآیی به جنگ .<br> <font color=\"Red\">فردوسی .</font><br> <BR><font color=\"Blue\">◄</font> ضرب و صدمه و آسیب . (برهان ) <span class=\"hlight\">:</span> <br>وگرنه بیارای جنگ مرا<br>به گردن بپیمای هنگ مرا.<br> <font color=\"Red\">فردوسی .</font><br> <BR><font color=\"Blue\">◄</font> زور و قوت و قدرت . (برهان ). سنگ . (حاشیه ٔبرهان چ معین ) <span class=\"hlight\">:</span> <br>بدان سان همی زدْش با زور و هنگ <br>که از کُه به زخمش همی ریخت سنگ .<br> <font color=\"Red\">اسدی .</font><br> <BR><font color=\"Blue\">◄</font> غار و شکاف کوه .(برهان ). این معنی را از هنگ افراسیاب استنباط کرده اند. (حاشیه ٔ برهان چ معین ). رجوع به دژآهنگ افراسیاب شود <span class=\"hlight\">:</span> <br>ز هرشهر دور و بنزدیک آب <br>که خوانی همی هنگ افراسیاب .<br><font color=\"Red\">فردوسی .</font><br>بدین اندر آن هنگ افراسیاب <br>در او ساخته جای آرام و خواب .<br> <font color=\"Red\">فردوسی .</font><br>ز گیتی یکی غار بگزید راست <br>چه دانست کآن هنگ دام بلاست .<br> <font color=\"Red\">فردوسی .</font><br> <BR><font color=\"Blue\">◄</font> سپاه و لشکر و قوم و قبیله . (برهان ).در زبان کردی به ضم اول به معنی گروه است <span class=\"hlight\">:</span> <br>نک منم سرهنگ هنگت بشکنم <br>نک به نامش نام و ننگت بشکنم .<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">سرهنگ </span> ؛ فرمانده سپاه و لشکر <span class=\"hlight\">:</span> <br>کسی را که نزدیک او سنگ بود<br>ز چندین سپاه، آن دو سرهنگ بود.<br> <font color=\"Red\">نظامی .</font><br><BR><font color=\"Blue\">◄</font> در تداول امروز واحدی است در نیروهای انتظامی که شامل سه گردان و یک ستاد است . نفرات عادی هنگ <span class=\"hlight\" dir=\"rtl\">٩٦٠</span> تن و ستاد آن در حدود <span class=\"hlight\" dir=\"rtl\">٢٥</span> تن است که روی هم در حدود یک هزار تن میشوند. <BR><font color=\"Blue\">◄</font> قصد و اراده و آهنگ . (برهان ). در این معنی مخفف آهنگ است ولی پورداود نوشته است که هنگ به معنی قصد و نیت است و این معنی از زبان فارسی باستان است . <BR><font color=\"Blue\">◄</font> دم آبی که خورند. (برهان ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (ص ) زیرک و عاقل . (برهان ). تیزفهم و دانا و هوشیار. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بسیار و فراوان و وافر. (برهان ).<br></font></div>'),
(268796, 'هنگ دان', '<span class=\"hlight\">هنگ دان .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از بخش کنگان شهرستان بوشهر. دارای <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه، آب آن از قنات و محصول عمده اش غله و خرما و انار و میوه های دیگر است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(268797, 'هنگ چینه', '<span class=\"hlight\">هنگ چینه .</span> <font color=\"DarkGreen\"><b>[ هََ چی ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان سقز. دارای <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله، لبنیات و توتون است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268798, 'هنگ ژال', '<span class=\"hlight\">هنگ ژال .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش بانه ٔ شهرستان سقز. دارای <span class=\"hlight\" dir=\"rtl\">١٠٨</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله، توتون، ارزن و مازوج است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268799, 'هنگ ژاله', '<span class=\"hlight\">هنگ ژاله .</span> <font color=\"DarkGreen\"><b>[ هََ گ َ ل َ ]</font></b> (اِخ ) دهی است از بخش رزاب شهرستان سنندج . دارای <span class=\"hlight\" dir=\"rtl\">١٦٠</span> تن سکنه، آب آن از رودخانه های برده سفید، کوره دره و چشمه و محصول عمده اش غله، لبنیات، توتون و گردو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268800, 'هنگ کنگ', '<span class=\"hlight\">هنگ کنگ .</span> <font color=\"DarkGreen\"><b>[ هَُ ک ُ ]</font></b> (اِخ ) یکی از مستعمرات انگلیس در جنوب شرقی سرزمین چین است که در شرق رود مروارید و در <span class=\"hlight\" dir=\"rtl\">٩٠</span>میلی جنوب کانتن قرار دارد. <span class=\"hlight\" dir=\"rtl\">٣٩١</span> کیلومتر مربع وسعت و قریب دو میلیون نفر جمعیت دارد. (از فرهنگ جغرافیایی وبستر).<br></font></div>'),
(268801, 'هنگار', '<span class=\"hlight\">هنگار.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) تندی و تیزی .(برهان ). هنگارد. (آنندراج ). رجوع به هنگارد شود.<br></font></div>'),
(268802, 'هنگارد', '<span class=\"hlight\">هنگارد.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) هنگار. تندی و تیزی . (برهان ).<br></font></div>'),
(268803, 'هنگاریدن', '<span class=\"hlight\">هنگاریدن .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (مص ) زور و ستم ورزیدن . <BR><font color=\"Blue\">◄</font> تند و تیز و سخت شدن و از این فعل فقط سیوم شخص مفرد زمان حال و استقبال مستعمل است . (ناظم الاطباء).<br></font></div>'),
(268804, 'هنگام', '<span class=\"hlight\">هنگام .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) جزیره ای است از بخش قشم شهرستان بندرعباس . دارای <span class=\"hlight\" dir=\"rtl\">٧٨</span> تن سکنه و آب آن ازچاه و باران است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268805, 'هنگام', '<span class=\"hlight\">هنگام .</span> <font color=\"DarkGreen\"><b>[ هََ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان فیروزآباد. دارای <span class=\"hlight\" dir=\"rtl\">٣٥٦</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله، خرما، برنج، لیمو، تنباکو، کنجد و کار دستی مردم آنجا گلیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(268806, 'هنگام', '<span class=\"hlight\">هنگام .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) درپارسی باستان هَنْگام َ، ارمنی اَنْگَم . (حاشیه ٔ برهان چ معین ). وقت و زمان و گاه . (برهان ) <span class=\"hlight\">:</span> <br>ای دریغ آن حر هنگام سخا حاتم وش <br>ای دریغ آن گو هنگام وغا سام گرای .<br> <font color=\"Red\">رودکی .</font><br>دلم پرآتش کردی و قد و قامت کوز<br>فرازنامد هنگام مردمیت هنوز.<br> <font color=\"Red\">آغاجی .</font><br>به جاماسپ گفت ار چنین است کار<br>به هنگام رفتن سوی کارزار.<br> <font color=\"Red\">فردوسی .</font><br>بدان وقت هنگام آن بزم بود<br>اگرچند آن بزم با رزم بود.<br> <font color=\"Red\">فردوسی .</font><br>همی راند لشکر چوباد دمان <br>نجست ایچ هنگام رفتن زمان .<br> <font color=\"Red\">فردوسی .</font><br>تو را هزاران حسن است و صدهزار حسود<br>چرا ز خانه برون آمدی در این هنگام .<br> <font color=\"Red\">فرخی .</font><br>راه مخوف است ... و هنگام حرکت نامعلوم . (کلیله و دمنه ). وقت ثبات مردان و هنگام مکر خردمندان است . (کلیله و دمنه ). وچون مدت درنگ او سپری شود و هنگام وضع حمل و تولد فرزند باشد بادی بر رحم مستولی شود. (کلیله و دمنه ).<br>برده به هنگام زخم در صف میدان جنگ <br>حربه ٔ هندی او حرمت تیغ یمان .<br> <font color=\"Red\">خاقانی .</font><br>کرده به هنگام حال حله ٔ نه چرخ چاک <br>داده به وقت نوال نقد دو عالم عطا.<br> <font color=\"Red\">خاقانی .</font><br>هنگام بازگشت همه ره ز برکتت <br>شب بدروار بدرقه ٔ کاروان شده .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">بهنگام </span> ؛ در موقع مناسب <span class=\"hlight\">:</span> <br>هزیمت بهنگام بهتر ز جنگ <br>چو تنها شدی نیست جای درنگ .<br> <font color=\"Red\">فردوسی .</font><br>گریزی بهنگام با سر ز جای <br>به از پهلوانی و سر زیرپای .<br> <font color=\"Red\">فردوسی .</font><br>زین بهنگام تر نباشد وقت <br>زین دلارام تر نباشد یار.<br> <font color=\"Red\">فرخی .</font><br>گویند که هر چیز بهنگام بود خوش <br>ای عشق چه چیزی که خوشی در همه هنگام .<br> <font color=\"Red\">ادیب صابر.</font><br>شب که صبوحی نه بهنگام کرد<br>خون زیادش سیه اندام کرد.<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">بی هنگام </span> ؛ بی وقت . مقابل بهنگام <span class=\"hlight\">:</span> <br>مؤذن بانگ بی هنگام برداشت <br>نمیداند که چند از شب گذشته .<br> <font color=\"Red\">سعدی .</font><br>امشب سبکتر می زند این طبل بی هنگام را<br>یا وقت بیداری غلط بوده ست مرغ بام را.<br> <font color=\"Red\">سعدی .</font><br>خواب بی هنگامت از ره می برد<br>ورنه بانگ صبح بی هنگام نیست .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">پنج هنگام </span> ؛ پنج زمان معین برای نمازهای روزانه <span class=\"hlight\">:</span> <br>از صریر در اوچار ملایک به سه بعد<br>پنج هنگام دم صور به یک جا شنوند.<br> <font color=\"Red\">خاقانی .</font><br>دهر از فزعش به پنج هنگام <br>در ششدر امتحان ببینم .<br> <font color=\"Red\">خاقانی .</font><br> <BR><font color=\"Blue\">◄</font> موسم و فصل . (برهان ) <span class=\"hlight\">:</span> <br>هنگام بهار است و جهان چون بت فرخار<br>خیز ای بت فرخار و بیار آن گل بی خار.<br> <font color=\"Red\">منوچهری .</font><br>به هنگام خزان آید به ابخاز<br>کند در جستن نخجیر پرواز.<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> دوران . دوره . روزگار <span class=\"hlight\">:</span> <br>چنان هم که هنگام نوذر بدند<br>که با تاج و با تخت و افسر بدند.<br> <font color=\"Red\">فردوسی .</font><br>به هنگام شاهان باآفرین <br>پدر مادرش بود خاقان چین .<br> <font color=\"Red\">فردوسی .</font><br>نه آشوب گیتی به هنگام توست <br>که تا بد همیدون بدست از نخست .<br> <font color=\"Red\">اسدی .</font><br> <BR><font color=\"Blue\">◄</font> نوبت <span class=\"hlight\">:</span> <br>وز آن پس چو هنگام رستم رسید<br>که شمشیر تیز از میان برکشید.<br> <font color=\"Red\">فردوسی .</font><br>می را کنون آمده ست نوبت <br>مل را کنون آمده ست هنگام .<br> <font color=\"Red\">فرخی .</font><br> <BR><font color=\"Blue\">◄</font> مرگ . اجل . (یادداشت مؤلف ). <BR><font color=\"Blue\">◄</font> هنگامه . مجمع. انجمن . معرکه . (برهان ) <span class=\"hlight\">:</span> <br>ای شکسته حسن تو هنگام گل <br>باده ٔ عشرت فکن در جام گل .<br><font color=\"Red\">وصاف .</font><br></font></div>'),
(268807, 'هنگامه', '<span class=\"hlight\">هنگامه .</span> <font color=\"DarkGreen\"><b>[ هََ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ) مجمع و جمعیت مردم و معرکه ٔ بازیگران و قصه خوانان و خواص گویان و امثال آن باشد. (برهان ) <span class=\"hlight\">:</span> <br>چند گردی بسان بی ادبان <br>گرد هنگامه های بوالعجبان ؟<br><font color=\"Red\">سنائی .</font><br>در این چارسو هیچ هنگامه نیست <br>که کیسه برمرد خودکامه نیست .<br> <font color=\"Red\">نظامی .</font><br>نهادم در این شیوه هنگامه ای <br>مگر در سخن نو کنم خامه ای .<br> <font color=\"Red\">نظامی .</font><br>اشارت کرد خسرو کای جوانمرد<br>بگو گرم و مکن هنگامه را سرد.<br> <font color=\"Red\">نظامی .</font><br>هر جا که حکایتی و جمعی است <br>هنگامه ٔ توست و محفل من .<br> <font color=\"Red\">سعدی .</font><br>نامه ٔ اولیاست این نامه <br>مبر این را به شهر و هنگامه .<br> <font color=\"Red\">اوحدی .</font><br>هنگامه ٔ ارباب سخن چون نشود گرم <br>صائب سخن از مولوی روم درافگند.<br> <font color=\"Red\">صائب .</font><br> <BR><font color=\"Blue\">◄</font> هرگونه ازدحام و غوغا <span class=\"hlight\">:</span> <br>هنگامه ٔ شب گذشت و شد قصه تمام <br>طالع به کفم یکی نینداخت کجه .<br> <font color=\"Red\">رودکی .</font><br>هنگام صبوح و موکب صبح <br>هنگامه درید اختران را.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">هنگامه بلند شدن </span> ؛ سر و صدا به راه افتادن . سخن کسی یا داستانی بر زبانها افتادن <span class=\"hlight\">:</span> <br>نی همین هنگامه ٔ رسوایی من شد بلند<br>عشق دائم بر سر بازار مستور آورد.<br> <font color=\"Red\">نظیری .</font><br>- <span class=\"hlight\">هنگامه بند</span> ؛ هنگامه گیر. معرکه گیر. نقال یا درویشی که به سخن و داستان گوئی یا کارهای شگفت خودمردم را سرگرم دارد <span class=\"hlight\">:</span> <br>تماشا دلی و هزار آرزو<br>ز هنگامه بندان این چارسو.<br> <font color=\"Red\">ظهوری .</font><br>- <span class=\"hlight\">هنگامه بندی </span> ؛ نموداری . (غیاث ) (آنندراج ). آشکاری و برزبان افتادگی .<br>- <span class=\"hlight\">هنگامه جوی </span> ؛ آنکه در پی ایجاد معرکه باشد. هنگامه گیر.<br>- <span class=\"hlight\">هنگامه طراز</span> ؛ آنکه هنگامه برپا کند و آن را بیاراید <span class=\"hlight\">:</span> <br>صائب ! از خانه ٔ ما گلشن معنی بنواخت <br>باغ اگر بلبل هنگامه طرازی دارد.<br> <font color=\"Red\">صائب .</font><br>- <span class=\"hlight\">هنگامه ٔ طفلان </span> ؛کنایه از دنیا و عالم است . (برهان ).<br>- <span class=\"hlight\">هنگامه طلب </span> ؛ آنکه جدال و خلاف را با مردمان دوست دارد. هنگامه جوی . (یادداشت مؤلف ).<br>- <span class=\"hlight\">هنگامه فروز</span> ؛ مجلس آرا که هنگامه را گرم کند <span class=\"hlight\">:</span> <br>هر لاله ز باغ عارض او<br>هنگامه فروز صد بهار است .<br> <font color=\"Red\">ظهوری .</font><br>- <span class=\"hlight\">هنگامه کردن </span> ؛ مثل قیامت کردن، یعنی کاری را بسیار خوب انجام دادن . این ترکیب بیان کننده ٔ اهمیت کار کسی است، چه منفی و چه مثبت .<br>- <BR><font color=\"Blue\">◄</font> معرکه گرفتن . هنگامه برپاکردن <span class=\"hlight\">:</span> <br>جهان بر رهگذر هنگامه کرده ست <br>تو بگذر زآنکه این هنگامه سرد است .<br> <font color=\"Red\">عطار.</font><br>- <span class=\"hlight\">هنگامه گرفتن </span> ؛ هنگامه برپا کردن . معرکه گرفتن . (یادداشت مؤلف ).<br>- <span class=\"hlight\">هنگامه گیر</span>؛ معرکه گیر. بازیگر. (انجمن آرا) (از برهان ) <span class=\"hlight\">:</span> <br>مرغ به هنگام زد نعره ٔ هنگامه گیر<br>کز همه کاری صبوح خوش تر هنگام صبح .<br> <font color=\"Red\">خاقانی .</font><br>ما مهره ایم و هم جهت مهره حلقه ایم <br>هنگامه گیر و دلشده و هم نظاره ایم .<br> <font color=\"Red\">مولوی .</font><br>نگیرد خردمند روشن ضمیر<br>زبان بند دشمن ز هنگامه گیر.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هنگامه ٔ مانی </span> ؛ در تنها موردی که شاهد آن یافته شد، کنایه از ارژنگ یا ارتنگ مانی است <span class=\"hlight\">:</span> <br>از ساز مرا خیمه چو هنگامه ٔ مانی است <br>وز فرش مرا خانه چو بتخانه ٔ فرخار.<br> <font color=\"Red\">فرخی .</font><br> <BR><font color=\"Blue\">◄</font> هنگام . وقت . زمان <span class=\"hlight\">:</span> <br>به هنگامه ٔ بازگشتن زراه <br>همانا نکردی به لشکر نگاه .<br> <font color=\"Red\">فردوسی .</font><br>چو هنگامه ٔ رفتن آید فراز<br>زمانه نگردد به پرهیز باز.<br> <font color=\"Red\">فردوسی .</font><br>چو هنگامه ٔ زادن آمد پدید<br>یکی دختر آمد ز ماه آفرید.<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268808, 'هنگامی', '<span class=\"hlight\">هنگامی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص نسبی ) ترجمه ٔ خلق الساعه است، یعنی جانوری که درساعت موجود شود همچو پشه و مگس و مانند آن . (برهان ). ضد همیشگی است . (آنندراج ). به این معنی ظاهراً از برساخته های فرقه ٔ آذرکیوان است . (از حاشیه ٔ برهان چ معین ).<br></font></div>'),
(268809, 'هنگان', '<span class=\"hlight\">هنگان .</span> <font color=\"DarkGreen\"><b>[ هََ]</font></b> (اِخ ) دهی است از بخش سرباز شهرستان کرمان . دارای <span class=\"hlight\" dir=\"rtl\">٢٥</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268810, 'هنگروان', '<span class=\"hlight\">هنگروان .</span> <font color=\"DarkGreen\"><b>[ هََ گ ِرْ ]</font></b> (اِخ ) دهی است از بخش صومای شهرستان ارومیه . دارای <span class=\"hlight\" dir=\"rtl\">١١٢</span> تن سکنه، آب آن از کندوچشمه و محصول عمده اش غله و توتون و کار دستی مردم آنجا جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268811, 'هنگرپیاز', '<span class=\"hlight\">هنگرپیاز.</span> <font color=\"DarkGreen\"><b>[ هََ گ َ ]</font></b> (اِخ ) دهی است از بخش ساردوئیه ٔ شهرستان جیرفت . دارای <span class=\"hlight\" dir=\"rtl\">١٥</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268812, 'هنگری', '<span class=\"hlight\">هنگری .</span> <font color=\"DarkGreen\"><b>[ هَُ گ ِ ]</font></b> (اِخ ) مجارستان . یکی از کشورهای شبه جزیره ٔ بالکان در اروپا است که شمال آن کشور چکسلواکی، شمال غربی آن اتریش، و جنوب آن یوگوسلاوی و رومانی و مشرقش مجاور با خاک روسیه ٔ شوروی است و ایالت اوکراین روسیه همسایه ٔآن است . نام یونانی این سرزمین اونگرن  است که کلمه ٔ هنگری تغییریافته ٔ آن است . پایتخت آن شهر بوداپست است . وسعت این سرزمین پیش از جنگ جهانی دوم <span class=\"hlight\" dir=\"rtl\">٣٥٨٧٥</span> کیلومتر مربع بود. جمعیت این کشور مطابق آمار <span class=\"hlight\" dir=\"rtl\">١٩٣٩</span> م . <span class=\"hlight\" dir=\"rtl\">٩١٠٦٢٥٢</span> تن بوده است . بعد از جنگ وسعت خاک آن به <span class=\"hlight\" dir=\"rtl\">٦٦٠٠٠</span> کیلومتر مربع و جمعیت آن به حدود پانزده میلیون رسید. بلندترین نقطه ٔ این سرزمین <span class=\"hlight\" dir=\"rtl\">٣٣٠٠</span> متر از سطح دریا ارتفاع دارد. رودخانه ٔ دانوب از شمال به جنوب این کشور را قطع می کند و وارد کشور یوگسلاوی می شود. در مغرب آن دریاچه ای به نام بالاتن  وجود دارد. این سرزمینهای کنار گذرگاه دانوب در حدود سالهای <span class=\"hlight\" dir=\"rtl\">٨٩٣</span> تا <span class=\"hlight\" dir=\"rtl\">٩٠١</span> م .به تصرف قبایل مجار درآمد و پیش از آن اسلاونشین بود. در آن زمان اتو اول امپراطور آلمان در برابر مجارها مقاومت کرد. اما سرانجام در اواخر قرن دهم و قرون بعد مبارزه ٔ مجارها به نتیجه رسید و این سرزمینها به تصرف آنها درآمد. و در قرن شانزدهم، دولتی به این نام در مرکز اروپا وجود داشت که در <span class=\"hlight\" dir=\"rtl\">١٩٤٦</span> م . تبدیل به دولت جمهوری شد. (از فرهنگ جغرافیایی وبستر). رجوع به مجار و مجارستان شود.<br></font></div>'),
(268813, 'هنگفت', '<span class=\"hlight\">هنگفت .</span> <font color=\"DarkGreen\"><b>[ هََ گ ُ ]</font></b> (ص ) گنده و سطبر و ضخیم . (برهان ) <span class=\"hlight\">:</span> <br>بهترین جامه ای بود هنگفت <br>مر مرا اوستاد چونین گفت .<br> <font color=\"Red\">سنائی .</font><br>فرستادم به خدمت رقعه ٔ وی <br>به دست پهلوی هنگفت و لمتر.<br> <font color=\"Red\">ابن یمین .</font><br><BR><font color=\"Blue\">◄</font> کنایه از بسیار هم هست و صاحب مؤیدالفضلا بجای نون تا آورده است که هتگفت باشد. (برهان ).<br></font></div>'),
(268814, 'هنگمتان', '<span class=\"hlight\">هنگمتان .</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (اِخ ) رجوع به همدان شود.<br></font></div>'),
(268815, 'هنگه', '<span class=\"hlight\">هنگه .</span> <font color=\"DarkGreen\"><b>[ هََ گ َ <span class=\"hlight\" dir=\"rtl\">/</span> گ ِ ]</font></b>(اِ) مخفف هنگامه که مجمع و معرکه باشد. (برهان ).<br></font></div>'),
(268816, 'هنگو', '<span class=\"hlight\">هنگو.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش نشتای شهرستان شهسوار. دارای <span class=\"hlight\" dir=\"rtl\">١٢٥</span> تن سکنه، آب آن از آزاررود و محصول عمده اش برنج و مرکبات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(268817, 'هنگویه', '<span class=\"hlight\">هنگویه .</span> <font color=\"DarkGreen\"><b>[ هَِ ی َ ]</font></b> (اِخ ) دهی است از بخش بستک شهرستان لار. دارای <span class=\"hlight\" dir=\"rtl\">٨٩٨</span> تن سکنه، آب آن از چاه و محصول عمده اش غله، خرما و صیفی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(268818, 'هنی', '<span class=\"hlight\">هنی .</span> <font color=\"DarkGreen\"><b>[ هََ ن ْی ْ ]</font></b> (ع مص ) کردن . (منتهی الارب ): ذهبت و هنیت ؛ کنایه از رفتم و کاری را کردم . (از اقرب الموارد).<br></font></div>'),
(268819, 'هنی', '<span class=\"hlight\">هنی .</span> <font color=\"DarkGreen\"><b>[ هََ نی ی ]</font></b> (ع ص ) خوشگوار و گوارنده . (غیاث ). هنی ٔ <span class=\"hlight\">:</span> <br>محلش سنی باد و دولت هنی <br>جهانش رهی باد و گردون غلام .<br> <font color=\"Red\">مسعودسعد.</font><br>لشکر او از خصب آن قلعه به مرتعی هنی و مربعی سنی رسیدند. (ترجمه ٔ تاریخ یمینی ). سلطان را آن فتح سنی و نجح هنی تمام گشت . (ترجمه ٔ تاریخ یمینی ).<br>روزی بی رنج می دانی که چیست <br>قوت ارواح و ارزاق هنی است .<br> <font color=\"Red\">مولوی .</font><br>در نظر دشمنان نوش نباشد هنی <br>وز قبل دوستان نیش نباشد گزند.<br> <font color=\"Red\">سعدی .</font><br>مطلب گر توانگری خواهی <br>جز قناعت که دولتی است هنی .<br> <font color=\"Red\">سعدی .</font><br>به عجب علم نتوان شد ز اسباب طرب محروم <br>بیا ساقی که جاهل را هنی تر میرسد روزی .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(268820, 'هنیات', '<span class=\"hlight\">هنیات .</span> <font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (ع عدد، ص، اِ)عشرات الوف الوف الوف . مراتب شانزده گانه ٔ عدد نزد فیثاغوریان . (یادداشت مؤلف از رسائل اخوان الصفا).<br></font></div>'),
(268821, 'هنیاندر', '<span class=\"hlight\">هنیاندر.</span> <font color=\"DarkGreen\"><b>[ هَُ دَ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان کرمانشاهان . دارای <span class=\"hlight\" dir=\"rtl\">٣٧٠</span> تن سکنه، آب آن از زه آب دره ٔ محلی و محصول عمده اش غله، حبوب، توتون، میوه و چوب و کار دستی مردم آنجا بافتن قالیچه و گلیم و جاجیم است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268822, 'هنیز', '<span class=\"hlight\">هنیز.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ق ) هنوز. تا حال . تا اکنون . (برهان ) <span class=\"hlight\">:</span> <br>که ای فر گیتی یکی لخت نیز<br>یکایک نبایست آمد هنیز.<br> <font color=\"Red\">فردوسی .</font><br>کسی را که درویش باشد هنیز<br>ز گنج نهاده ببخشیم چیز.<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268823, 'هنیز', '<span class=\"hlight\">هنیز.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از بخش معلم کلایه ٔ شهرستان قزوین . دارای <span class=\"hlight\" dir=\"rtl\">٢٥٢</span> تن سکنه، آب آن از چشمه سار و محصول عمده اش غله، سیب، شلغم، گردو، بادام و کرچک و کار دستی مردم آنجا جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(268824, 'هنیع', '<span class=\"hlight\">هنیع.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) رجل هنیع؛ مرد کج قامت . <BR><font color=\"Blue\">◄</font> مرد پست و کوتاه گردن . (منتهی الارب ).<br></font></div>'),
(268825, 'هنیفقان', '<span class=\"hlight\">هنیفقان .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ف َ ]</font></b> (اِخ ) قریه ای است میانه ٔجنوب و مغرب رنجبران به فارس . (فارسنامه ٔ ناصری ).<br></font></div>'),
(268826, 'هنین', '<span class=\"hlight\">هنین .</span> <font color=\"DarkGreen\"><b>[ هَُ ن َ ]</font></b> (ع اِ مصغر) مصغر هن . (منتهی الارب ).<br></font></div>'),
(268827, 'هنین', '<span class=\"hlight\">هنین .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) گریستن و نالیدن . (منتهی الارب ) (از اقرب الموارد). حنین .<br></font></div>'),
(268828, 'هنیکس', '<span class=\"hlight\">هنیکس .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) یکی از چهار تن خاورشناسی که در سال <span class=\"hlight\" dir=\"rtl\">١٨٥٧</span> م . از طرف انجمن آسیایی وابسته به دربار بریتانیا دعوت شدند تا هر کدام یکی از کتیبه های آسوری را بخوانند. (از ایران باستان پیرنیا ص <span class=\"hlight\" dir=\"rtl\">٤٧</span>).<br></font></div>'),
(268829, 'هه', '<span class=\"hlight\">هه .</span> <font color=\"DarkGreen\"><b>[ هََ ه ْ ]</font></b> (ع اِ صوت ) تذکره است و وعید. (منتهی الارب ) (آنندراج ). اسم صوت است برای تذکره و وعید. (اقرب الموارد).<br></font></div>'),
(268830, 'هه', '<span class=\"hlight\">هه .</span> <font color=\"DarkGreen\"><b>[ هََ ه ه ]</font></b> (ع مص ) لثغه عارض شدن کسی را و بند شدن زبان در سخن . (آنندراج ) (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268831, 'هه', '<span class=\"hlight\">هه .</span> <font color=\"DarkGreen\"><b>[ هََ ه ْ ]</font></b> (اِ صوت ) صدایی است که در وقتی که خواهند دهن شخصی را بوی کنند از آن شخص بر گوش میخورد. (برهان ).<br></font></div>'),
(268832, 'ههارمونیه', '<span class=\"hlight\">ههارمونیه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام زن موهومی در افسانه های یونان و گویا همسر هرمس بود و در زمره ٔ ارباب انواع کبیر به شمار میرفت . <BR><font color=\"Blue\">◄</font> کنایه ازتوازن عالم نیز بوده است . (از قاموس الاعلام ترکی ).<br></font></div>'),
(268833, 'ههة', '<span class=\"hlight\">ههة.</span> <font color=\"DarkGreen\"><b>[ هََ هَْهََ ]</font></b> (ع مص ) بند شدن زبان و لثغه عارض شدن . (اقرب الموارد) (منتهی الارب ) (آنندراج ). رجوع به هه شود.<br></font></div>'),
(268834, 'ههنا', '<span class=\"hlight\">ههنا.</span> <font color=\"DarkGreen\"><b>[ ها هَُ ]</font></b> (ع ق ) اینجا. (غیاث اللغات ) (آنندراج ). رجوع به هیهنا شود.<br></font></div>'),
(268835, 'هو', '<span class=\"hlight\">هو.</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ]</font></b> (اِ) زردآب و ریمی را گویند که از زخم و جراحت برمی آید. <BR><font color=\"Blue\">◄</font> آب دزدیدن زخم و جراحت را نیز گفته اند. (برهان ). و در این صورت هو مبدل اَو و آب است . (از انجمن آرا). <BR><font color=\"Blue\">◄</font> ماه . قمر. <BR><font color=\"Blue\">◄</font> ابر. (ناظم الاطباء).<br></font></div>'),
(268836, 'هو', '<span class=\"hlight\">هو.</span> (اِ) آه و نفس . (برهان ). هوی .رجوع به هوی شود. <BR><font color=\"Blue\">◄</font> (اِ صوت ) کلمه ای است که از برای آگاهانیدن و خبر کردن گویند. (برهان ).<br>- <span class=\"hlight\">های و هو یا هیاهو</span> ؛ به معنی هلالوش و بانگ و فریاد و مشغله است <span class=\"hlight\">:</span> <br>چه عاشق است که فریاد دردناکش نیست <br>چه مجلس است کز او های و هو نمی آید.<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> در اصطلاح عرفا و اهل معنی به معنی ناله و زاری به درگاه حق تعالی است <span class=\"hlight\">:</span> <br>چون گوزنان هویی از جان برکشم <br>کآن شکار آهوان بدرود باد.<br> <font color=\"Red\">خاقانی .</font><br>در آن ساعت که ما مانیم و هویی <br>ز بخشایش فرومگذار مویی .<br> <font color=\"Red\">نظامی .</font><br>گه به یک حمله سپاهی می شکست <br>گه به هویی قلب گاهی می درید.<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(268837, 'هو', '<span class=\"hlight\">هو.</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ]</font></b> (اِ) خبر بی اصل . خبر دروغ . سروصدا درباره ٔ چیزی که حقیقت ندارد. چُو.<br>- <span class=\"hlight\">هو انداختن </span> ؛ خبری بی اساس را در میان مردم شایع کردن .<br>- <span class=\"hlight\">هوچی </span> ؛ کسی که خبرهای بی اساس را برای منافع خود شایع کند.<br>- <span class=\"hlight\">هو کردن </span> ؛ درباره ٔ کسی خبر بی اساس و زیان آور انتشار دادن و او رادر نظر مردم پست کردن .<br>- <span class=\"hlight\">یک هو</span> ؛ غفلةً. بی خبر. ناگاه .<br></font></div>'),
(268838, 'هو', '<span class=\"hlight\">هو.</span> <font color=\"DarkGreen\"><b>[ هَُ وَ ]</font></b> (ع ضمیر) ضمیر واحد مذکر غایب یعنی او و آن . (ناظم الاطباء).<br></font></div>'),
(268839, 'هو', '<span class=\"hlight\">هو.</span> (اِخ ) در تداول صوفیان مخفف هُوَ و مراد خدای تعالی است : یا هو؛ ای خدا. (یادداشت به خط مؤلف ). پنهانی است که مشاهده ٔ آن غیر را درست نیاید. (تعریفات میرسیدشریف ) <span class=\"hlight\">:</span> <br>صبغةاﷲ چیست ؟ رنگ خُم ّ هو<br>پیسه ها یک رنگ گردد اندر او.<br> <font color=\"Red\">مولوی .</font><br>فکر ما تیری است از هو در هوا<br>در هوا کی پایدار آید ندا؟<br> <font color=\"Red\">مولوی .</font><br>باد در مردم هوا و آرزوست <br>چون هوا بگذاشتی پیغام هوست .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(268840, 'هو', '<span class=\"hlight\">هو.</span> <font color=\"DarkGreen\"><b>[ هََ وو ]</font></b> (ع اِ) کرانه . <BR><font color=\"Blue\">◄</font> روزن خانه . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268841, 'هو و جنجال', '<span class=\"hlight\">هو و جنجال .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو وُ ج َ ]</font></b> (ترکیب عطفی، اِ مرکب ) هیاهو. سر و صدا. جار و جنجال .<br></font></div>'),
(268842, 'هو کردن', '<span class=\"hlight\">هو کردن .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ک َ دَ ]</font></b> (مص مرکب ) با هیاهو و اشتلم و دروغ و نسبت های ناروا و گاه دسته جمعی، کسی را بد جلوه دادن و مایه ٔ آبروریزی او را فراهم ساختن .<br></font></div>'),
(268843, 'هو کشیدن', '<span class=\"hlight\">هو کشیدن .</span> <font color=\"DarkGreen\"><b>[هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) جراحت یا قرحه بدتر شدن . سیم کشیدن جراحت یا آب دزدیدن قرحه و ریش .<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">شاه خانم میزاید ماه خانم درد میکشد</span> <br> <span class=\"hlight\">خاله م زاییده خاله زام هو کشیده </span> .<br><BR><font color=\"Blue\">◄</font> هو انداختن به آوازی بلند و دراز هو گفتن برای خواندن کسی از دور چنانکه رسم کشاورزان و اویاران است . (یادداشت مؤلف ).<br></font></div>'),
(268844, 'هوا', '<span class=\"hlight\">هوا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) هواء. جسم لطیف و روان که گرداگرد زمین را فراگرفته وجانداران و گیاهان از آن تنفس می کنند. (حاشیه ٔ برهان چ معین ). ترکیبی از نیتروژن (ازت ) و اکسیژن و به نسبت کمی از گازهای دیگر که گرد زمین را احاطه کرده است . جَوّ میان زمین و آسمان . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> به مناسبت اعتقاد قدما به قرار گرفتن سیال غیرمرئی (هوا) فوق خاک معنی بالا و فوق و بر بودن از آن برآید و مرادف آسمان به کار رود و شواهد ذیل از این معنی با التفات به معنی اصلی حکایت دارد <span class=\"hlight\">:</span> <br>فاخته گون شد هوا ز گردش خورشید<br>جامه ٔ خانه به رنگ فاخته گون شد.<br> <font color=\"Red\">رودکی .</font><br>چنان که مرغ هوا پرّ و بال برهنجد<br>تو بر خلایق بر پرّ مردمی برهنج .<br> <font color=\"Red\">ابوشکور.</font><br>دلی را کز هوی جستن چو مرغ اندر هوا یابی <br>به حاصل مرغ وار او را به آتش گردنا یابی .<br> <font color=\"Red\">کسائی .</font><br>تا دیو چه افکند هوا بر زنخ سیب <br>مهتاب به گلگونه بیالودش رخسار.<br> <font color=\"Red\">شریف مجلدی .</font><br>ز روی هوا ابر شد ناپدید<br>به ایران کسی برف و باران ندید.<br> <font color=\"Red\">فردوسی .</font><br>شد از سم ّ اسبان زمین سنگ رنگ <br>ز نیزه هوا شد چو پشت پلنگ .<br> <font color=\"Red\">فردوسی .</font><br>ز لشکر چوگرد اندرآمد به گرد<br>زمین شد سیاه و هوا لاجورد.<br> <font color=\"Red\">فردوسی .</font><br>تو گفتی ز خون دشت دریا شده ست <br>ز خنجر هوا چون ثریا شده ست .<br> <font color=\"Red\">فردوسی .</font><br>ای غوک چنگلوک چو پژمرده برگ کوک <br>خواهی که چون چکوک بپرّی سوی هوا؟<br> <font color=\"Red\">لبیبی .</font><br>با سبزه زمین به رنگ بوقلمون شد<br>وز میغ هوا به صورت پشت پلنگ .<br> <font color=\"Red\">منوچهری .</font><br>بر هوا رفتی چون مریم بی معجز<br>یا چو قارون به زمین وین نبود جایز.<br> <font color=\"Red\">منوچهری .</font><br>مدبری که سنگ منجنیق را<br>بدارد اندر این هوا دهای او.<br> <font color=\"Red\">منوچهری .</font><br>چو شب رفت و بر دشت پستی گرفت <br>هوا چون مغ آتش پرستی گرفت .<br> <font color=\"Red\">عنصری .</font><br>هوا بینی همه ارواح بی تن <br>زمین بینی همه اجسام بی جان .<br> <font color=\"Red\">ناصرخسرو.</font><br>تو را خدای زبهر بقا پدید آورد<br>تو را ز خاک و هواو نبات و حیوان را.<br> <font color=\"Red\">ناصرخسرو.</font><br>ای چون هوا لطیف ! ز رنج هوای تو<br>شبها دو دست خویش همی بر هوا کنم .<br> <font color=\"Red\">مسعودسعد.</font><br>هرکه اندر هوای تو نبود<br>بر تن او هوا حصار شود.<br> <font color=\"Red\">مسعودسعد.</font><br>گفتم هوا به مرکب خالی توان گذاشت ؟<br>گفتا توان اگر به ریاضت کنیش رام .<br> <font color=\"Red\">خاقانی .</font><br>من آبم که چون آتشی زیر دارم <br>ز ننگ زمین در هوا می گریزم .<br> <font color=\"Red\">خاقانی .</font><br>در هوا چند معلق زنی و جلوه کنی <br>ای کبوتر نگران باش که شاهین آمد.<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">آب و هوا</span> ؛ شرایط طبیعی یک محیط <span class=\"hlight\">:</span> <br>جان من زنده به تأثیر هوای لب توست <br>سازگاری نکند آب و هوای دگرم .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">بی هوا</span>؛ بازیگوش . سربهوا. لاابالی .<br>- <span class=\"hlight\">پا در هوا</span> ؛ افتادنی . متزلزل . ناپایدار. نااستوار.<br>- <span class=\"hlight\">در هوا</span> ؛ آویحته . معلق . رجوع شود به همین مدخل . <br>- <span class=\"hlight\">سر به هوا</span> ؛ لاابالی . بی اعتنا به مقررات و شرایط.<br>- <span class=\"hlight\">سر در هوا</span> ؛ بسیار بلند. برکشیده <span class=\"hlight\">:</span> <br>همی رفت چون باد فرمانروا<br>یکی کوه را دید سر در هوا.<br> <font color=\"Red\">فردوسی .</font><br>- <span class=\"hlight\">گشاده هوا</span> ؛ هوای صاف و روشن . (ناظم الاطباء).<br>- <span class=\"hlight\">هوای تند</span> ؛ باد سخت و تند.<br>- <span class=\"hlight\">هوای سنجابی یا خفتانی </span> ؛ هوای ابری و آسمان باابر. (ناظم الاطباء).<br> <BR><font color=\"Blue\">◄</font> باد. نسیم . <BR><font color=\"Blue\">◄</font> آهنگ و آواز و صدا و نغمه و سرود. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (ص ) هر چیزخالی . (اقرب الموارد) <span class=\"hlight\">:</span> افئدتهم هواء (قرآن <span class=\"hlight\" dir=\"rtl\">٤٣/١٤</span>)؛ أی خالیة. <BR><font color=\"Blue\">◄</font> آدم ترسو را گویند به سبب تهی بودن قلب از جرأت . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) هوی . هوس . میل . تمایل . خواهش نفس <span class=\"hlight\">:</span> <br>چنین گفت بهرام کاری رواست <br>هوا بر دل هرکسی پادشاست .<br> <font color=\"Red\">فردوسی .</font><br>اگر چیره گردد هوا بر خرد<br>خردمندت از مردمان نشمرد.<br><font color=\"Red\">فردوسی .</font><br>دو هفته در این خانه ٔ بی نوا<br>نباشی گر آید دلت در هوا.<br> <font color=\"Red\">فردوسی .</font><br>با بتانی که می ندانم گفت <br>که از ایشان هوای من به کدام .<br> <font color=\"Red\">فرخی .</font><br>ایزد امروز همه کار برای تو کند<br>همه عالم به مراد و به هوای تو کند.<br> <font color=\"Red\">منوچهری .</font><br>زآن سخنها که بدان طبعتو را میل و هواست <br>گوش مالش توبه انگشت بدانسان که سزاست .<br> <font color=\"Red\">منوچهری .</font><br>مبر گفت غم کآن کنم کت هواست <br>به هر روی فرمان و رایت رواست .<br> <font color=\"Red\">اسدی .</font><br>از او مر مرا هست فرمان روا<br>که جفت آن گزینم کم آید هوا.<br> <font color=\"Red\">اسدی .</font><br>با دو عاقل هوا نیامیزد<br>یک هوا از دو عقل بگریزد.<br> <font color=\"Red\">سنائی .</font><br>عاقل را هیچ ضرر و سهو چون تبع هوا نیست . (کلیله و دمنه ). زیرا که آدمیان بیشتر از راه هوا در هاویه شوند. (کلیله و دمنه ). همت بر متابعت رای و هوای او مقصور گردانم . (کلیله و دمنه ).<br>مجروح هوانی ز هوا دست بیفشان <br>زیرا که هوان نیست هر آنجا که هوا نیست .<br> <font color=\"Red\">اثیر اخسیکتی .</font><br>در بهاری که گل جمال دهد<br>خوش نباشد هوای صحبت خس .<br> <font color=\"Red\">ظهیر فاریابی .</font><br>هوای دل رهش میزد که برخیز<br>گل خود را بدین شکر برآمیز.<br> <font color=\"Red\">نظامی .</font><br>بی هوا نهی از هوا ممکن نبود<br>هم غزا با مردگان نتوان نمود.<br> <font color=\"Red\">مولوی .</font><br>نیم بهر حق شد و نیمی هوا<br>شرکت اندر کار حق نبود روا.<br> <font color=\"Red\">مولوی .</font><br>مر سفیهان را رباید هر هوا<br>زانکه نبودشان گرانی قوا.<br> <font color=\"Red\">مولوی .</font><br>نظر خدای بینان ز سر هوا نباشد<br>سفر نیازمندان به ره خطا نباشد.<br> <font color=\"Red\">سعدی .</font><br>تفرج کنان بر هوا و هوس <br>گذشتیم بر خاک بسیار کس .<br> <font color=\"Red\">سعدی .</font><br>من از ورع می و مطرب ندیدمی زین پیش <br>هوای مغبچگانم در این و آن انداخت .<br> <font color=\"Red\">حافظ.</font><br>مفلسانیم و هوای می و مطرب داریم <br>آه اگر خرقه ٔ پشمین به گرو نستانند.<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">دوهوایی </span> ؛ دنبال دو یا چند هوای گوناگون رفتن . تلون مزاج <span class=\"hlight\">:</span> <br>خلق گویند برو دل به هوای دگری ده <br>نکنم خاصه در ایام اتابک دوهوایی .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هوا جستن </span> ؛ دنبال هوس رفتن . هوسبازی <span class=\"hlight\">:</span> <br>دلی راکز هوا جستن چو مرغ اندر هوا یابی <br>به حاصل مرغ وار او را به آتش گردنا یابی .<br> <font color=\"Red\">کسایی .</font><br>رجوع به هوی شود.<br> <BR><font color=\"Blue\">◄</font> عشق <span class=\"hlight\">:</span> <br>هوای تو را زآن گزیدم ز عالم <br>که پاکیزه تر از سرشک هوایی .<br> <font color=\"Red\">زینبی .</font><br>هوا درد است و می درمان درد است <br>غمان گرد است و می باران گرد است .<br> <font color=\"Red\">فخرالدین اسعد.</font><br>ز مهر تو دیر است تا خسته ام <br>به بند هوای تو دل بسته ام .<br> <font color=\"Red\">اسدی .</font><br>دل به هوای تو داده ام من و جز من <br>هیچ کسی گرگ را نداده شبانی .<br> <font color=\"Red\">ادیب صابر.</font><br>ای به هزار جان دلم، مست وفای روی تو<br>خانه ٔجان به چار حد، وقف هوای روی تو.<br> <font color=\"Red\">خاقانی .</font><br> <BR><font color=\"Blue\">◄</font> (اِمص ) هواداری . طرفداری <span class=\"hlight\">:</span> <br>هوای او چو شهادت پس از خلاف عدو<br>به هر دل اندر مأوی گرفت و گشت مکین .<br> <font color=\"Red\">فرخی .</font><br>رضای او کند روشن، ثنای او کند نیکو<br>هوای او کند بینا، سخای او کند فربی .<br><font color=\"Red\">منوچهری .</font><br>و اعیان نواحی در هوای ما مطیع وی گشته . (تاریخ بیهقی ). در هوای من بسیار خواری دیده است . (تاریخ بیهقی ). در هوای ما محنتی بزرگ کشیده . (تاریخ بیهقی ).<br>بی هوای تو نیست هیچ دلی <br>بی ثنای تو نیست هیچ سری .<br> <font color=\"Red\">مسعودسعد.</font><br>لیکن هوای تو به اظهار آن رخصت نمی داد. (کلیله و دمنه ).<br>از عقل همه هوات خواهم <br>وز نفس همه ثنات جویم .<br> <font color=\"Red\">خاقانی .</font><br>باشد چو طبع مهر من اندر هوای تو<br>چون تاب گیرد از حرکات خور آینه .<br> <font color=\"Red\">خاقانی .</font><br>غم جمله خور در هوای یکی <br>مراعات صد کن برای یکی .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> (اِ) آرزو. تمنی . مراد و کام . امید. (یادداشت بخط مؤلف ) <span class=\"hlight\">:</span> <br>گفتم : ثواب خدمت او چیست خلق را؟<br>گفت : این جهان هوای دل و آن جهان جنان .<br> <font color=\"Red\">فرخی .</font><br>مردمی زنده بدوی است و سخا زنده بدو<br>وین دو چیز است که او را به جهان کام و هواست .<br> <font color=\"Red\">فرخی .</font><br>شادمان باد و یافته ز خدای <br>هرچه او را مراد و کام و هواست .<br> <font color=\"Red\">فرخی .</font><br>در جسمها هوای بقای تو چون روان <br>در چشمها جمال لقای تو چون بصر.<br> <font color=\"Red\">مسعودسعد.</font><br>مرغ سان از قفس خاک هوایی گشتم <br>به هوایی که مگر صید کند شهبازم .<br> <font color=\"Red\">حافظ.</font><br>شهباز دست پادشهم این چه حالت است <br>کز یاد برده اند هوای نشیمنم ؟<br> <font color=\"Red\">حافظ.</font><br>امید خواجگیم بود بندگی تو جستم <br>هوای سلطنتم بود خدمت تو گزیدم .<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> آهنگ . آواز. لحن . راه . (یادداشت بخط مؤلف ) <span class=\"hlight\">:</span> <br>خروش رباب و هواهای نای <br>ره چنگ و دستان بربطسرای .<br> <font color=\"Red\">اسدی .</font><br>بربط اگر دم از هوا زد به زبان بی دهان <br>نی به دهان بی زبان دم ز هوای تو زند.<br> <font color=\"Red\">خاقانی .</font><br>چه ساز بود که در پرده میزد آن مطرب <br>که رفت عمر و هنوزم دماغ پر ز هواست .<br> <font color=\"Red\">حافظ.</font><br>رجوع به هواء و هوی شود.<br></font></div>'),
(268845, 'هوا خوردن', '<span class=\"hlight\">هوا خوردن .</span> <font color=\"DarkGreen\"><b>[ هََ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ دَ ]</font></b> (مص مرکب ) استنشاق هوا. فروبردن هوای پاک به درون ریه ها. هواخوری .<br>- <span class=\"hlight\">هوا خوردن باده </span> ؛ کنایه از زایل شدن کیفیت شراب است، چه تصرف هوا مزیل نشأه ٔ شراب است . (غیاث از مصطلحات ) <span class=\"hlight\">:</span> <br>رنگ نماند در لبش از نفس فسردگان <br>باده هوا چو می خورد پا به رکاب می دهد.<br> <font color=\"Red\">صائب .</font><br> <BR><font color=\"Blue\">◄</font> تصرف هوا درمزاج . (آنندراج ) <span class=\"hlight\">:</span> <br>آن چشم ناتوان غم مردم کجا خورد<br>کز بازگشتن نگه خود هوا خورد.<br><font color=\"Red\">میرصیدی .</font><br></font></div>'),
(268846, 'هوا دادن', '<span class=\"hlight\">هوا دادن .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (مص مرکب ) اتاق یا هر جای بسته را با هوای خارج مربوط کردن . <BR><font color=\"Blue\">◄</font> هوابه درون ریه فرستادن با وسایل . <BR><font color=\"Blue\">◄</font> در مجاورت هوا قرار دادن جراحت و موجب سیم کشیدگی آن شدن .<br></font></div>'),
(268847, 'هوا داشتن', '<span class=\"hlight\">هوا داشتن .</span> <font color=\"DarkGreen\"><b>[ هََ ت َ ]</font></b> (مص مرکب ) غرور داشتن . خیال های باطل داشتن <span class=\"hlight\">:</span> حسین زندیق است و هوا دارد. (تاریخ سیستان ). <BR><font color=\"Blue\">◄</font> هوای کسی را داشتن ؛ مراقب او بودن . او را از خطر حفظ کردن .<br></font></div>'),
(268848, 'هوا در هوا', '<span class=\"hlight\">هوا در هوا.</span> <font color=\"DarkGreen\"><b>[ هََ دَ هََ ]</font></b> (ق مرکب ) بیهوده . هوسبازانه <span class=\"hlight\">:</span> <br>صرف شد آن بدره هوا در هوا<br>مفلس و بدره ز کجا تا کجا.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268849, 'هوا پختن', '<span class=\"hlight\">هوا پختن .</span> <font color=\"DarkGreen\"><b>[ هََ پ ُ ت َ ]</font></b> (مص مرکب ) به فکر چیزی بودن . آرزو کردن <span class=\"hlight\">:</span> <br>کنون هوای عمل می پزد کبوتر نفس <br>که دست جور زمانش نه پر گذاشت نه بال .<br> <font color=\"Red\">سعدی .</font><br>هرکه هوایی نپخت یا به فراقی نسوخت <br>آخر عمر از جهان چون برود، خام رفت .<br><font color=\"Red\">سعدی (غزلیات ص <span class=\"hlight\" dir=\"rtl\">٤٠٣</span>).</font><br></font></div>'),
(268850, 'هوا کردن', '<span class=\"hlight\">هوا کردن .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ دَ ]</font></b> (مص مرکب ) به هوا بالا بردن چیزی را چون بالن و بادبادک .<br></font></div>'),
(268851, 'هوا گرفتن', '<span class=\"hlight\">هوا گرفتن .</span> <font color=\"DarkGreen\"><b>[ هََ گ ِ رِ ت َ ]</font></b> (مص مرکب ) بر هوا رفتن . پرواز کردن . اوج گرفتن <span class=\"hlight\">:</span> <br>پس نیاری هیچ جنبیدن ز جا<br>تا نگیرد مرغ خوب تو هوا.<br> <font color=\"Red\">مولوی .</font><br>بسم از هوا گرفتن که پری نماند و بالی <br>به کجا روم ز دستت که نمی دهی مجالی .<br> <font color=\"Red\">سعدی .</font><br>گرد ارچه بسی هوا بگیرد<br>هرگز نرسد به گرد افلاک .<br> <font color=\"Red\">سعدی .</font><br>به بال و پر مرو از ره که تیر پرتابی <br>هوا گرفت زمانی ولی به خاک نشست .<br> <font color=\"Red\">حافظ.</font><br>ز خاکدان تعلق گرفته ایم هوا<br>غبار دست ندارد به طرف دامن ما.<br> <font color=\"Red\">صائب .</font><br>رجوع به هواگیر شود.<br></font></div>'),
(268852, 'هوا یافتن', '<span class=\"hlight\">هوا یافتن .</span> <font color=\"DarkGreen\"><b>[ هََ ت َ ]</font></b> (مص مرکب ) هوا خوردن . فاسد شدن چیزی در مجاورت هوا. (یادداشت مؤلف ). <BR><font color=\"Blue\">◄</font> تصرف کردن هوا در مزاج . (غیاث ) <span class=\"hlight\">:</span> <br>با دم جان پرور شمشیر عادت کرده ست <br>از دم عیسی هوا یابددل بیمار من .<br><font color=\"Red\">صائب .</font><br></font></div>'),
(268853, 'هواء', '<span class=\"hlight\">هواء.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) میان آسمان و زمین . ج، اهویة. <BR><font color=\"Blue\">◄</font> (ص ) خالی هرچه باشد. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بددل . (منتهی الارب ). ترسو. که دلش از جرأت تهی است . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) میل و رغبت و طرفداری <span class=\"hlight\">:</span> چون منتصر بدان حدود رسید به هواء دولت او برخاست . (ترجمه ٔ تاریخ یمینی ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(268854, 'هواباره', '<span class=\"hlight\">هواباره .</span> <font color=\"DarkGreen\"><b>[ هََرَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص مرکب ) هواپرست . پیرو هوس <span class=\"hlight\">:</span> <br>من گرنه همچو ذره هواباره بودمی <br>گرد جهان چرا شده آواره بودمی ؟<br><font color=\"Red\">اثیر اومانی .</font><br></font></div>'),
(268855, 'هوابج', '<span class=\"hlight\">هوابج .</span> <font color=\"DarkGreen\"><b>[ هََ ب ِ ]</font></b> (اِخ ) مرغزارهایی است به یمامه . (منتهی الارب ).<br></font></div>'),
(268856, 'هوابد', '<span class=\"hlight\">هوابد.</span> <font color=\"DarkGreen\"><b>[ هََ ب ِ ]</font></b> (ع ص، اِ) ج ِ هابدة. (منتهی الارب ). رجوع به هابدة شود.<br></font></div>'),
(268857, 'هواجر', '<span class=\"hlight\">هواجر.</span> <font color=\"DarkGreen\"><b>[ هََ ج ِ ]</font></b> (ع اِ) ج ِ هاجرة، به معنی هجر، قطع. هاجرة از مصدرهای سماعی است مثل عافیة و عاقبة. (از اقرب الموارد) <span class=\"hlight\">:</span> بسبب احتدام هواجربه معسکر جناشک تحویل کرد. (ترجمه ٔ تاریخ یمینی ).<br></font></div>'),
(268858, 'هواجس', '<span class=\"hlight\">هواجس .</span> <font color=\"DarkGreen\"><b>[ هََ ج ِ ]</font></b> (ع اِ) ج ِهاجس . (منتهی الارب ) (اقرب الموارد). وساوس . وسوسه ها.(یادداشت بخط مؤلف ). خطرات شیطانی که در دل گذرند و این ج ِ هاجسة است به معنی چیزی که در دل گذرد. (غیاث ) <span class=\"hlight\">:</span> وساوس و هواجس بر دماغ و دلش مستولی شد. (سندبادنامه ). هواجس آن وحشت و وساوس آن محنت مسامر نجوم و مساور رجوم بودم . (ترجمه ٔ تاریخ یمینی ).<br></font></div>'),
(268859, 'هواجو', '<span class=\"hlight\">هواجو.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b>(نف مرکب ) کام جو. (یادداشت بخط مؤلف ) <span class=\"hlight\">:</span> <br>نگارا تا تو باشی مانده در راه <br>هواجوی تو باشد مانده در چاه .<br> <font color=\"Red\">فخرالدین اسعد.</font><br>رجوع به هواجوی شود.<br></font></div>'),
(268860, 'هواجوی', '<span class=\"hlight\">هواجوی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (نف مرکب ) طالب و عاشق . (برهان ). رجوع به هواجو شود.<br></font></div>'),
(268861, 'هواخواه', '<span class=\"hlight\">هواخواه .</span> <font color=\"DarkGreen\"><b>[ هََ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) یار و دوست و محب . (برهان ). هوادار. طرفدار. جانب دار. موافق . (از یادداشتهای بخط مؤلف ) <span class=\"hlight\">:</span> <br>آن خریدار سخندان و سخن <br>وآن هواخواه هنرمند و هنر.<br> <font color=\"Red\">فرخی .</font><br>پادشا باش و رخ از شادی ماننده ٔ گل <br>رخ بدخواه هواخواه تو ماننده ٔکاه .<br> <font color=\"Red\">فرخی .</font><br>بنده وفادار و هواخواه توست <br>بنده هواخواه و وفادار، دار.<br> <font color=\"Red\">منوچهری .</font><br>چوهم دل بود او را، هم درم بود<br>هوادار و هواخواهش نه کم بود.<br> <font color=\"Red\">فخرالدین اسعد.</font><br>دل اختر از جان هواخواه توست <br>زبان زمانه ثناخواه توست .<br> <font color=\"Red\">اسدی .</font><br>هرکه زبان او خوشتر هواخواه اوبیشتر. (قابوسنامه ).<br>تا بود قضا، بود وفادار یمینش <br>تا هست قدر، هست هواخواه شمالش .<br> <font color=\"Red\">ناصرخسرو.</font><br>در کهن انصاف نوان کم بود<br>پیر هواخواه جوان کم بود.<br> <font color=\"Red\">نظامی .</font><br>دلیران ارمن هواخواه او<br>کمربسته بر رسم و بر راه او.<br><font color=\"Red\">نظامی .</font><br>دو بهره جهان را در آن شهر یافت <br>هواخواه خود را یکی بهر یافت .<br> <font color=\"Red\">نظامی .</font><br>چو دیدند کاوصاف و خلقش نکوست <br>به طبعش هواخواه گشتند و دوست .<br> <font color=\"Red\">سعدی .</font><br>بازآی ساقیا که هواخواه خدمتم <br>مشتاق بندگی و دعاگوی دولتم .<br> <font color=\"Red\">حافظ.</font><br>من کز وطن سفر نگزیدم به عمر خویش <br>در عشق دیدن تو هواخواه غربتم .<br> <font color=\"Red\">حافظ.</font><br>هواخواه توام جانا و میدانم که میدانی <br>که هم نادیده می بینی و هم ننوشته میخوانی .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(268862, 'هواخواهی', '<span class=\"hlight\">هواخواهی .</span> <font color=\"DarkGreen\"><b>[ هََ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (حامص مرکب ) طرفداری . دوستی . علاقه . مساعدت . معاضدت . (یادداشت بخط مؤلف ) <span class=\"hlight\">:</span> آن میل ها و هواخواهی ها که دیده آمده بود بنشست . (تاریخ بیهقی ). از جانب وی همه راستی و یکدلی واعتقاد راست و هواخواهی بوده است . (تاریخ بیهقی ).<br>گر ببینی ز مرغ تا ماهی <br>همه را باشد این هواخواهی .<br> <font color=\"Red\">نظامی .</font><br>گل کمر بسته در شهنشاهی <br>خاک چون باد در هواخواهی .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(268863, 'هواخور', '<span class=\"hlight\">هواخور.</span> <font color=\"DarkGreen\"><b>[ هََ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (اِ مرکب ) هواکش . مجرایی که هوای خارج را به درون ساختمان می کشد.<br></font></div>'),
(268864, 'هواخورده', '<span class=\"hlight\">هواخورده .</span> <font color=\"DarkGreen\"><b>[ هََ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) فاسدشده . تغییریافته <span class=\"hlight\">:</span> <br>چاره ز می کن دل افسرده را<br>گرم نگه دار هواخورده را.<br><font color=\"Red\">اسماعیل ایما (از آنندراج ).</font><br></font></div>'),
(268865, 'هواخوری', '<span class=\"hlight\">هواخوری .</span> <font color=\"DarkGreen\"><b>[ هََ خوَ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ ]</font></b> (حامص مرکب ) تنفس هوا. استنشاق هوای پاک .<br>- <span class=\"hlight\">هواخوری رفتن </span> ؛ در تداول یعنی رفتن به جای خوش آب و هوا برای آسایش .<br></font></div>'),
(268866, 'هوادار', '<span class=\"hlight\">هوادار.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (نف مرکب ) هواخواه . (آنندراج ). دوست . طرفدار. مساعد. معاضد. (یادداشت بخط مؤلف ) <span class=\"hlight\">:</span> <br>چو هم دل بود او را هم درم بود<br>هوادار و هواخواهش نه کم بود.<br><font color=\"Red\">فخرالدین اسعد.</font><br>هرکه طلبکار اوست روی نتابد به تیغ<br>وآنکه هوادار اوست بازنگردد به تیر.<br> <font color=\"Red\">سعدی .</font><br>هوادار نکورویان نیندیشد ز بدگویان <br>بیا گر روی آن داری که طعنت در قفا ماند.<br> <font color=\"Red\">سعدی .</font><br>می سوزد و همچنان هوادار<br>می میرد و همچنان دعاگوست .<br> <font color=\"Red\">سعدی .</font><br>از صبا هر دم مشام جان معطر می شود<br>آری آری طیب انفاس هواداران خوش است .<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> عاشق . شیفته . دلداده <span class=\"hlight\">:</span> <br>مرغ دل باز هوادار کمان ابرویی است <br>ای کبوتر نگران باش که شاهین آمد.<br> <font color=\"Red\">حافظ.</font><br>زلف دل دزدش، صبا را بند بر گردن نهاد<br>با هواداران رهرو حیله ٔ هندو ببین .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(268867, 'هواداری', '<span class=\"hlight\">هواداری .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) دوستداری و محبت ورزی . (آنندراج ). پشتی . هواخواهی . مظاهرت . مساعدت . معاضدت . (یادداشت بخطمؤلف ) <span class=\"hlight\">:</span> امیر یوسف را هواداری امیر محمد از بهر نگاهداشت دل سلطان محمود بر آن جانب کشید. (تاریخ بیهقی ). از روی سلامت نیت و استقامت عزیمت و استمرار هواداری در این باب ... (تاریخ بیهقی ). به قدم راسخ و عزم ثابت در هواداری و حفظ و حراست کریم ایده اﷲ تعصب نمود و حق گزاری کرد. (ترجمه ٔ تاریخ یمینی ).<br>هواداری مکن شب را چو خفاش <br>چو باز جره ٔ خود روزرو باش .<br> <font color=\"Red\">نظامی .</font><br>نه من انگشت نمایم به هواداری رویت <br>که تو انگشت نمایی و خلایق نگرانت .<br> <font color=\"Red\">سعدی .</font><br>من قلب ولسانم به هواداری صحبت <br>اینها همه قلب اند که پیش تو لسانند.<br> <font color=\"Red\">سعدی .</font><br>در چمن باد بهاری ز کنار گل و سرو<br>به هواداری آن عارض و قامت برخاست .<br> <font color=\"Red\">حافظ.</font><br>چون صبا با تن بیمار و دل بی طاقت <br>به هواداری آن سرو خرامان بروم .<br> <font color=\"Red\">حافظ.</font><br>رسید باد صبا، غنچه در هواداری <br>ز خود برون شد و بر خود درید پیراهن .<br> <font color=\"Red\">حافظ.</font><br>از هواداری ما و تو چو مستغنی است یار<br>ای رقیب این چاپلوسی و نوندی تا به کی .<br><font color=\"Red\">کمال خجندی .</font><br></font></div>'),
(268868, 'هوادج', '<span class=\"hlight\">هوادج .</span> <font color=\"DarkGreen\"><b>[ هََ دِ ]</font></b> (ع اِ) ج ِ هودج . رجوع به هودج شود.<br></font></div>'),
(268869, 'هوادر', '<span class=\"hlight\">هوادر.</span> <font color=\"DarkGreen\"><b>[ هََ دِ ]</font></b> (ع ص، اِ) ج ِ هادرة. (منتهی الارب ).<br></font></div>'),
(268870, 'هوادرق', '<span class=\"hlight\">هوادرق .</span> <font color=\"DarkGreen\"><b>[ هََ دَ رَ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان اردبیل . دارای <span class=\"hlight\" dir=\"rtl\">٢٩٦</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268871, 'هوار', '<span class=\"hlight\">هوار.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) خاک و خشت و آنچه از خراب شدن سقف یا قسمتهای دیگر بنایی فروریزد. (یادداشت بخط مؤلف ). آوار. <BR><font color=\"Blue\">◄</font> فریادی است برای استمداد واستعانت هنگامی که حریق یا خرابی در جایی پدید آید و یا مصیبتی دیگر روی نماید. (یادداشت بخط مؤلف ).<br>- <span class=\"hlight\">هوار کردن (کشیدن )</span> ؛ فریاد برآوردن و کمک خواستن .<br></font></div>'),
(268872, 'هوار برزه', '<span class=\"hlight\">هوار برزه .</span> <font color=\"DarkGreen\"><b>[ هََ رِ ب َ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِخ ) رجوع به هواره برزه شود.<br></font></div>'),
(268873, 'هوارت', '<span class=\"hlight\">هوارت .</span> (اِخ ) کلمان (<span class=\"hlight\" dir=\"rtl\">١٨٥٤</span>-<span class=\"hlight\" dir=\"rtl\">١٩٢٦</span> م .). از خاورشناسان فرانسوی زبان است که در ژورنال آسیایی مقالاتی در باب آثار ادبی ایران و به خصوص حروفیه دارد و نیز تحقیقات دیگری درباره ٔ مشرق زمین کرده است . رجوع به ج <span class=\"hlight\" dir=\"rtl\">٣</span> تاریخ ادبیات براون (از سعدی تا جامی ) ترجمه ٔ حکمت شود.<br></font></div>'),
(268874, 'هوارم', '<span class=\"hlight\">هوارم .</span> <font color=\"DarkGreen\"><b>[ هََ رِ ]</font></b> (ع ص، اِ) ج ِ هارم . (منتهی الارب ). رجوع به هارم شود.<br></font></div>'),
(268875, 'هواره برزه', '<span class=\"hlight\">هواره برزه .</span> <font color=\"DarkGreen\"><b>[ هََ رِ ب َ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِخ ) دهی است از بخش بوکان شهرستان مهاباد. دارای <span class=\"hlight\" dir=\"rtl\">١٠٧</span> تن سکنه، آب آن ازچشمه و محصول عمده اش غله، توتون و کار دستی مردم آنجا جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268876, 'هواره خال', '<span class=\"hlight\">هواره خال .</span> <font color=\"DarkGreen\"><b>[ هََ رِ ]</font></b> (اِخ ) دهی است از بخش بانه ٔ شهرستان سقز. دارای <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله، توتون، ارزن، زغال، مازوج و کتیرا است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268877, 'هوارپان', '<span class=\"hlight\">هوارپان .</span> <font color=\"DarkGreen\"><b>[هََ ]</font></b> (اِخ ) دهی است از بخش کامیاران شهرستان سنندج . دارای <span class=\"hlight\" dir=\"rtl\">١٧٤</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268878, 'هواری', '<span class=\"hlight\">هواری .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) خیمه ٔ بزرگ و بارگاه سلاطین را گویند. (برهان ).<br></font></div>'),
(268879, 'هوازن', '<span class=\"hlight\">هوازن .</span> <font color=\"DarkGreen\"><b>[ هََ زِ ]</font></b> (اِخ ) نام قبیله ای است از نسل سبا. (سمعانی ). قبیله ای است از قیس . (منتهی الارب ). از قبایل قیس و آنان فرزندان هوازن بن منصوربن عکرمةبن حفصةبن قیس عیلان اند. (صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span>).<br></font></div>'),
(268880, 'هوازن', '<span class=\"hlight\">هوازن .</span> <font color=\"DarkGreen\"><b>[ هََ زِ ]</font></b> (اِخ ) نام پدر شیخ ابوالقاسم قشیری عارف معروف است . رجوع به ابوالقاسم شود.<br></font></div>'),
(268881, 'هوازی', '<span class=\"hlight\">هوازی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (نف مرکب ) زیست کننده در هوا. این ترکیب اخیراً در کتاب های زیست شناسی به معنی هر موجودی که برای ادامه ٔ زندگی نیازمند هوا باشد به کار رفته است .<br></font></div>'),
(268882, 'هوازی', '<span class=\"hlight\">هوازی .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (ق ) بیکبار. ناگاه . (برهان ) <span class=\"hlight\">:</span> <br>مردمان از خرد سخن گویند<br>تو هوازی حدیث غاب کنی .<br> <font color=\"Red\">رودکی .</font><br>هوازی برآمد برم آن نگار<br>مرا تنگ بگرفت اندر کنار.<br> <font color=\"Red\">آغاجی .</font><br>هوازی مرا گوید آن شکرین لب <br>که ای شاعراندر سخن ژرف بنگر.<br> <font color=\"Red\">فرخی .</font><br>به مهمان هوازی شاد گردم <br>ز دست رنج و غم آزاد گردم .<br> <font color=\"Red\">فرخی (از سروری ).</font><br>هوازی جهان پهلوان را بدید<br>که در سایه ٔ گل همی مل کشید.<br> <font color=\"Red\">اسدی .</font><br>او مرا شیرین چو جان است و گرامی چون سخن <br>از جهان و جان هوازی کس ندارد دست باز.<br> <font color=\"Red\">قطران .</font><br>خزینه ی ْ علم فرقان است اگر نه بر هوایی تو<br>که بردت پس هوازی، جز هوا، زی شعر اهوازی ؟<br> <font color=\"Red\">ناصرخسرو.</font><br><BR><font color=\"Blue\">◄</font> (اِ) بارگاه . (برهان ). در این معنی ظاهراً مصحف هواری است یا به عکس . رجوع به هواری شود.<br></font></div>'),
(268883, 'هواس', '<span class=\"hlight\">هواس .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِمص ) خواهانی گشن . (منتهی الارب ).<br></font></div>'),
(268884, 'هواس', '<span class=\"hlight\">هواس .</span> <font color=\"DarkGreen\"><b>[ هََوْ وا ]</font></b> (ع ص ) گشن تیزشهوت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شیر نیک درنده . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268885, 'هواسة', '<span class=\"hlight\">هواسة.</span> <font color=\"DarkGreen\"><b>[ هََ وْ وا س َ ]</font></b> (ع ص ) شیر نیک درنده . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد دلیر. (منتهی الارب ). شجاع مجرب . (اقرب الموارد).<br></font></div>'),
(268886, 'هواسنج', '<span class=\"hlight\">هواسنج .</span> <font color=\"DarkGreen\"><b>[ هََ س َ ]</font></b> (نف مرکب ) سنجنده ٔ هوا. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) ابزاری که فشار هوا و به همین مناسبت ارتفاعات و تغییرات آتمسفریک را بدان سنجند.<br></font></div>'),
(268887, 'هواسیدن', '<span class=\"hlight\">هواسیدن .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (مص ) سوختن از بی آبی و تشنگی . (یادداشت مؤلف ). <BR><font color=\"Blue\">◄</font> پژمرده و گندمگون شدن . کم خون گردیدن چنانکه لب از بیماری . (یادداشت مؤلف ).<br></font></div>'),
(268888, 'هواسیده', '<span class=\"hlight\">هواسیده .</span> <font color=\"DarkGreen\"><b>[ هََ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف <span class=\"hlight\" dir=\"rtl\">/</span> نف ) لبی را گویند که خون آن کم شده و خشک گردیده و گندمگون شده باشد. (برهان ).<br></font></div>'),
(268889, 'هواشات', '<span class=\"hlight\">هواشات .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع اِ) گروههای مردم . <BR><font color=\"Blue\">◄</font> شتران با هم آمیخته . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اموال حرام . (منتهی الارب ).آنچه از مال حرام و حلال گرد آید. (اقرب الموارد).<br></font></div>'),
(268890, 'هواشانق', '<span class=\"hlight\">هواشانق .</span> <font color=\"DarkGreen\"><b>[هََ ن َ ]</font></b> (اِخ ) دهی است از بخش سنجبد شهرستان هروآباد، دارای <span class=\"hlight\" dir=\"rtl\">١٨٢</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268891, 'هواشناسی', '<span class=\"hlight\">هواشناسی .</span> <font color=\"DarkGreen\"><b>[ هََ ش ِ ]</font></b> (حامص مرکب ) شناختن هوا. در اصطلاح عنوان دانشی است که هوا یا پدیده های جوی را بررسی می کند. (از وبستر). کار این فن یا این دانش بررسی تغییرات جو و تأثیر آنها در شرایط محیط زندگی از نظر مقدار باران، برف، باد، آفتاب و مانند آن است .<br></font></div>'),
(268892, 'هواع', '<span class=\"hlight\">هواع .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع مص ) قی کردن . <BR><font color=\"Blue\">◄</font> (اِ) قی . <BR><font color=\"Blue\">◄</font> ماه ذیقعده .ج، هواعات، اَهوعة. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268893, 'هواعات', '<span class=\"hlight\">هواعات .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع اِ) ج ِ هواع . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268894, 'هواعة', '<span class=\"hlight\">هواعة.</span> <font color=\"DarkGreen\"><b>[ هَُ ع َ ]</font></b> (ع اِ) آنچه از گلوی قی کننده برآید. (اقرب الموارد).<br></font></div>'),
(268895, 'هوافی', '<span class=\"hlight\">هوافی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص، اِ) ج ِ هافی و هافیة: هوافی الابل ؛ شتران گم شده درچراگاه . (منتهی الارب ). هوامی . رجوع به هوامی شود.<br></font></div>'),
(268896, 'هوالة', '<span class=\"hlight\">هوالة.</span> <font color=\"DarkGreen\"><b>[ هََ وْ وا ل َ ]</font></b> (ع ص ) هولناک . (غیاث ). در فرهنگهای عربی این صیغه دیده نشد.<br></font></div>'),
(268897, 'هوالس', '<span class=\"hlight\">هوالس .</span> <font color=\"DarkGreen\"><b>[ هََ ل ِ ]</font></b> (ع ص، اِ) مردم سبک اندام . (منتهی الارب ). ج ِ هالس . (از اقرب الموارد).<br></font></div>'),
(268898, 'هوالک', '<span class=\"hlight\">هوالک .</span> <font color=\"DarkGreen\"><b>[ هََ ل ِ ]</font></b> (ع ص، اِ) ج ِ هالک . (منتهی الارب ).<br></font></div>'),
(268899, 'هوام', '<span class=\"hlight\">هوام .</span> <font color=\"DarkGreen\"><b>[ هََ وام م ]</font></b> (ع اِ) ج ِ هامَّة. (منتهی الارب ). به معنی حشرات الارض مثل مار وکژدم و راسو و مور و هر خزنده و گزنده است . (غیاث ).در فارسی به تخفیف هم به کار رفته است <span class=\"hlight\">:</span> <br>بسا که تو به ره اندر زبهر دانگی سیم <br>شکست خواهی خوردن ز پشه و ز هوام .<br> <font color=\"Red\">فرخی .</font><br>جرم زمین تا قرار یافت ز عدلت <br>بس نفس شکر کز هوام برآمد.<br> <font color=\"Red\">خاقانی .</font><br>اندرافتادند درهم ز ازدحام <br>همچو اندر دوغ گندیده هوام .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(268900, 'هوام', '<span class=\"hlight\">هوام .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع اِمص ) تشنگی سخت . <BR><font color=\"Blue\">◄</font> نوعی از جنون و عشق . (منتهی الارب ).<br></font></div>'),
(268901, 'هوام', '<span class=\"hlight\">هوام .</span> <font color=\"DarkGreen\"><b>[ هََ وْ وا]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268902, 'هوامل', '<span class=\"hlight\">هوامل .</span> <font color=\"DarkGreen\"><b>[ هََ م ِ ]</font></b> (ع ص، اِ) ج ِ هامل . (منتهی الارب ). رجوع به هامل شود.<br></font></div>'),
(268903, 'هوامی', '<span class=\"hlight\">هوامی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص، اِ) هوامی الابل ؛ شتران گم شده در چراگاه . (منتهی الارب ). رجوع به هوافی شود.<br></font></div>'),
(268904, 'هوان', '<span class=\"hlight\">هوان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) ناتوان و درویش گردیدن و برجای ماندن . <BR><font color=\"Blue\">◄</font> خوار گردیدن . (اقرب الموارد). هون . مهانة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِمص ) خواری و بی عزتی . (غیاث ) <span class=\"hlight\">:</span> <br>قسمش از مهرگان سعادت و عز<br>قسم بدخواه او بلا و هوان .<br> <font color=\"Red\">فرخی .</font><br>صدر دیوان وزارت رست از زرق و دروغ <br>رادمردان جهان رستند از ذل و هوان .<br> <font color=\"Red\">فرخی .</font><br>جاودان زین گونه بادا عیش او<br>عیش بدخواهش به تیمار و هوان .<br> <font color=\"Red\">فرخی .</font><br>گر نیستت خبر که چه خواهد همی نمود<br>بدخو جهان، تو را ز غم و رنج و از هوان .<br> <font color=\"Red\">ناصرخسرو.</font><br>آنکه از نیست هست کردندش <br>او به راحت رسد همی ز هوان .<br> <font color=\"Red\">ناصرخسرو.</font><br>دل من با هوا زان پس نیامیخت <br>که زیر هر هوا اندر، هوان دید.<br> <font color=\"Red\">مسعودسعد.</font><br>بدان دم اندر راندم همی ز دیده سرشک <br>دل از هوا رنجور و من از هوان مضطر.<br> <font color=\"Red\">مسعودسعد.</font><br>روزی چه طلب کنم به خواری ؟<br>خود بی طلب وهوان ببینم .<br> <font color=\"Red\">خاقانی .</font><br>نکرد با من از این ناکسان کس احسانی <br>کز آن سپس نه به چشم هوان به من نگریست .<br> <font color=\"Red\">خاقانی .</font><br>پیش تیغش کآتش نمرود را ماند ز چرخ <br>کرکسان پر بر سر خاک هوان افشانده اند.<br> <font color=\"Red\">خاقانی .</font><br>فریاد از آن زمان که تن نازنین ما<br>در بستر هوان فتد و ناتوان شود.<br> <font color=\"Red\">سعدی .</font><br>مسکین اسیر نفس و هوا کاندر آن مقام <br>با صدهزار غصه قرین هوان شود.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(268905, 'هوان', '<span class=\"hlight\">هوان .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از بخش ثلاث شهرستان کرمانشاهان . دارای <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه، آب آن از چاه و محصول عمده اش غله و حبوبات و لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268906, 'هوانله', '<span class=\"hlight\">هوانله .</span> <font color=\"DarkGreen\"><b>[ هَُ ل ِ ]</font></b> (اِخ ) دهی است ازبخش حومه ٔ شهرستان سنندج . دارای <span class=\"hlight\" dir=\"rtl\">٣٤٠</span> تن سکنه و محصول عمده اش غله است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268907, 'هوانورد', '<span class=\"hlight\">هوانورد.</span> <font color=\"DarkGreen\"><b>[ هََ ن َ وَ ]</font></b> (نف مرکب ) طی کننده ٔ هوا. خلبان . راننده ٔ هواپیما. رجوع به فضانورد شود.<br></font></div>'),
(268908, 'هواهی', '<span class=\"hlight\">هواهی .</span> <font color=\"DarkGreen\"><b>[هََ ]</font></b> (ع اِ) سخن باطل و لغو. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نوعی رفتن . (اقرب الموارد).<br></font></div>'),
(268909, 'هواوین', '<span class=\"hlight\">هواوین .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) ج ِ هاون . (منتهی الارب ) (اقرب الموارد). رجوع به هاون و هاوون شود.<br></font></div>'),
(268910, 'هواپرست', '<span class=\"hlight\">هواپرست .</span> <font color=\"DarkGreen\"><b>[ هََ پ َ رَ ]</font></b> (نف مرکب ) آنکه در پی هوای نفس باشد. پیرو هوس . هواباره <span class=\"hlight\">:</span> <br>گفتا چه گمان بری که مستم <br>یا شیفته و هواپرستم .<br> <font color=\"Red\">نظامی .</font><br>گناه کردن پنهان به از عبادت فاش <br>اگر خدای پرستی هواپرست مباش .<br> <font color=\"Red\">سعدی .</font><br>هرزه گرد غماز، هواپرست هوسباز. (گلستان ).<br>هواپرست ز راحت به خویش می بالد<br>که آشکار فزون تر شود به خواب نفس .<br><font color=\"Red\">محسن تأثیر.</font><br></font></div>'),
(268911, 'هواپرستی', '<span class=\"hlight\">هواپرستی .</span> <font color=\"DarkGreen\"><b>[ هََ پ َ رَ ]</font></b> (حامص مرکب ) در پی هوای نفس بودن . هوس رانی <span class=\"hlight\">:</span> <br>طالب زهواپرستی هند<br>برگشت و سوی مطالب آمد.<br><font color=\"Red\">طالب .</font><br></font></div>'),
(268912, 'هواپیما', '<span class=\"hlight\">هواپیما.</span> <font color=\"DarkGreen\"><b>[ هََ پ َ <span class=\"hlight\" dir=\"rtl\">/</span> پ ِ ]</font></b> (نف مرکب ) طی کننده ٔ هوا. که در هوا راه پیماید <span class=\"hlight\">:</span> پیش ِ آسیب ِ صواعق ِ حادثات چه بنگه موری و چه تخت هواپیمای سلیمانی . (منشآت خاقانی چ محمد روشن تهران <span class=\"hlight\" dir=\"rtl\">١٣٤٩</span> هَ . ش . ص <span class=\"hlight\" dir=\"rtl\">١٠</span>) <BR><font color=\"Blue\">◄</font> (اِ مرکب ) طیاره . آویون . آیروپلان . نوعی مرکوب ماشینی که با گردش سریع ملخها به نیروی موتوریا از طریق تخلیه ٔ گاز متراکم (جت ) به حرکت درآید وبار و مسافر به هوا برد و از جایی به جایی رساند.<br></font></div>'),
(268913, 'هواک', '<span class=\"hlight\">هواک .</span> <font color=\"DarkGreen\"><b>[ هََ وْوا ]</font></b> (ع ص ) سرگشته . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268914, 'هواکش', '<span class=\"hlight\">هواکش .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (اِ مرکب ) سوراخ یا لوله ای که بر دیوار اطاق تعبیه کنند تا هوای سنگین را بیرون دهد و هوای سالم به درون اطاق آورد. <BR><font color=\"Blue\">◄</font> امروز نوعی پروانه ٔ الکتریکی را گویند که به پنجره یا در محلی مخصوص از دیوار نصب می شود و با گردش خود هوای درون را تعویض می کند.<br></font></div>'),
(268915, 'هواکشیدن', '<span class=\"hlight\">هواکشیدن .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) هوا خوردن . در اصطلاح فاسد شدن چیزی که مجاورت ممتد با هوا آن را تباه می کند چون روغن و پنیر و... (از یادداشتهای مؤلف ).<br></font></div>'),
(268916, 'هواگون', '<span class=\"hlight\">هواگون .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص مرکب ) به رنگ هوا. به مانند هوا <span class=\"hlight\">:</span> <br>عشق را مرغ هوائی یابد<br>کاین هواگون قفسش نشناسد.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(268917, 'هواگیر', '<span class=\"hlight\">هواگیر.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (نف مرکب ) هواگیرنده . در حال پرواز.<br>- <span class=\"hlight\">هواگیر گشتن </span> ؛ هوا گرفتن . پریدن <span class=\"hlight\">:</span> <br>از راه نظر صید دلم گشت هواگیر<br>ای دیده نگه کن که به دام که درافتاد.<br> <font color=\"Red\">حافظ.</font><br><BR><font color=\"Blue\">◄</font> که آنجا هوا گذاره دارد. که معرض هواست .<br></font></div>'),
(268918, 'هواگیری', '<span class=\"hlight\">هواگیری .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (حامص مرکب ) عمل هواگیر. <BR><font color=\"Blue\">◄</font> (اصطلاح صنعتی ) خالی کردن هوا از درون پیستون دستگاههای پیستونی است تا خوب به کار افتد. در تلمبه های پیستونی و دستگاههای مشابه آن اگر هوا در زیر پیستون باشد دستگاه خاصیت مکیدن مواد را از دست می دهد.<br></font></div>'),
(268919, 'هوای', '<span class=\"hlight\">هوای .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از بخش هوراند شهرستان اهر. دارای <span class=\"hlight\" dir=\"rtl\">٣٠٢</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله، برنج، پنبه، انگور و سردرختی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268920, 'هوای خفتان پوش', '<span class=\"hlight\">هوای خفتان پوش .</span> <font color=\"DarkGreen\"><b>[ هََ ی ِ خ ِ تام ْ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از هوای ابری است . (برهان ).<br></font></div>'),
(268921, 'هوایدرق', '<span class=\"hlight\">هوایدرق .</span> <font color=\"DarkGreen\"><b>[ هَُ دَ رَ ]</font></b> (اِخ ) دهی است از بخش هوراند شهرستان اهر. دارای <span class=\"hlight\" dir=\"rtl\">٣٢٠</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله، گردو و توت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268922, 'هوایی', '<span class=\"hlight\">هوایی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص نسبی ) هوائی . منسوب به هوا.آنچه در هوا باشد یا به هوا تواند رفت <span class=\"hlight\">:</span> <br>سالار سپاهان چو ملک شد به سپاهان <br>برشد به هوا همچو یکی مرغ هوایی .<br> <font color=\"Red\">منوچهری .</font><br>- <span class=\"hlight\">هوایی گشتن </span> ؛ به هوا پریدن . پرواز کردن <span class=\"hlight\">:</span> <br>مرغ سان از قفس خاک هوایی گشتم <br>به هوایی که مگر صید کند شهبازم .<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> مردمی که در پی هوا و هوس نفس باشند. (برهان ) <span class=\"hlight\">:</span> <br>شوریده دلی چنین هوایی <br>تن درندهد به کدخدایی .<br> <font color=\"Red\">نظامی .</font><br>کسانی عیب ما بینند و گویند<br>که روحانی ندانند از هوایی .<br> <font color=\"Red\">سعدی .</font><br>به دست باد صبا زان نمی دهم پیغام <br>که محرم تو شدن کار هر هوایی نیست .<br> <font color=\"Red\">امیرخسرو.</font><br><BR><font color=\"Blue\">◄</font> سخنان هرزه و لغو. <BR><font color=\"Blue\">◄</font> تیر آتشبازی را گفته اند که چون آتش بر آن زنند به هوا رود. <BR><font color=\"Blue\">◄</font> حاصل و درآمدی را گویند که از جای غیرمعین به هم رسد. (برهان ).<br></font></div>'),
(268923, 'هوایی', '<span class=\"hlight\">هوایی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) هوائی . از شعرای قرن نهم و معاصر امیرعلیشیر بوده است . میرعلیشیرنویسد: مولانا هوایی انیس و جلیس مولانا مشرقی است و در نقاشی کاشی نیز صاحب وقوف است . در کتابت دست داشته، اشعار خود را تذهیب و تحریر می کرده و به بهای ارزان می فروخته است و مردم به شوخی به او می گفته اند: این شعر تو صورتی است بی معنی خوب . این مطلع از اوست :<br>به گرد کوی تو با صد نیازمی گردم <br>نظاره می کنم از دور و باز می گردم .<br><font color=\"Red\">(از مجالس النفائس صص <span class=\"hlight\" dir=\"rtl\">٢١٥</span>-<span class=\"hlight\" dir=\"rtl\">٢١٦</span>).</font><br></font></div>'),
(268924, 'هوب', '<span class=\"hlight\">هوب .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِمص ) دوری . <BR><font color=\"Blue\">◄</font> (ص ) مرد گول و بیهوده گوی . <BR><font color=\"Blue\">◄</font> (اِ) فروغ آتش . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268925, 'هوباتو', '<span class=\"hlight\">هوباتو.</span> (اِخ ) جایی است در کردستان میان دیوان دره و سقز و آثاری از حدود دوهزار سال پیش در آنجا هست که در غاری سنگی تراشیده شده و ظاهراً معبد هراکلیس بوده است . (از جغرافیای تاریخی غرب ایران ص <span class=\"hlight\" dir=\"rtl\">٢٥٥</span>).<br></font></div>'),
(268926, 'هوبر', '<span class=\"hlight\">هوبر.</span> <font color=\"DarkGreen\"><b>[ هََ ب َ ]</font></b> (ع اِ) یوز. <BR><font color=\"Blue\">◄</font> بچه یوز.(منتهی الارب ). <BR><font color=\"Blue\">◄</font> سوسن و سوسن سرخ . <BR><font color=\"Blue\">◄</font> کپی بسیارموی . <BR><font color=\"Blue\">◄</font> جایی که در آن درخت قتاد بسیار است . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268927, 'هوبر', '<span class=\"hlight\">هوبر.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِ) دوش و بغل و کنار. <BR><font color=\"Blue\">◄</font> به معنی پشتی و حمایت هم آمده است . (برهان ). مصحف هوبه است . (از حاشیه ٔ برهان چ معین ). رجوع به هوبه شود.<br></font></div>'),
(268928, 'هوبره', '<span class=\"hlight\">هوبره .</span> <font color=\"DarkGreen\"><b>[ ب َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) شوات . چرز. (یادداشت مؤلف ). پرنده ای است که آن را به عربی حباری و به ترکی توغدری گویند. (برهان ). مرغی است بری، خاکستری رنگ و منقارش دراز. (تحفه ٔ حکیم مؤمن ).<br></font></div>'),
(268929, 'هوبره', '<span class=\"hlight\">هوبره .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ب َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص ) سرگشته و حیران . (برهان ). به معنی حیران آورده اند و از طبقات پیر انصاری نقل کرده که شیخ شبلی در حق شیخ یعقوب دعا کرده گفت : خدای تعالی تو را هوبره کند. وی گفت : آمین ... (انجمن آرا). رجوع به حاشیه ٔ برهان چ معین شود.<br></font></div>'),
(268930, 'هوبسیا', '<span class=\"hlight\">هوبسیا.</span> <font color=\"DarkGreen\"><b>[ ب َس ْ ]</font></b> (هزوارش، اِ) بزبان زند و پازند دندان را گویند و به عربی سن خوانند. (برهان ). این کلمه هزوارش کلمه ٔ «دست گرو» پهلوی به معنی سند و پیمان و رهن است و ظاهراً سند را در معنی کلمه ٔ سن عربی خوانده و به معنی دندان گرفته اند. در برهان قاطع چ کلکته آمده که زندان را گویند. (از حاشیه ٔ برهان چ معین ).<br></font></div>'),
(268931, 'هوبه', '<span class=\"hlight\">هوبه .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ) دوش و کتف را گویند. (برهان ). هوبر. هویه . رجوع به هویه شود. <BR><font color=\"Blue\">◄</font> به معنی پشتی و حمایت هم هست و به این معنی بجای بای ابجد یای حطی هم آمده است . (برهان ). رجوع به هوبر و هویه شود.<br></font></div>'),
(268932, 'هوت', '<span class=\"hlight\">هوت .</span> <font color=\"DarkGreen\"><b>[ هَُ وَ ]</font></b>(ع اِ) ج ِ هوتة. (منتهی الارب ). رجوع به هوتة شود.<br></font></div>'),
(268933, 'هوت', '<span class=\"hlight\">هوت .</span> (اِخ ) از طوایف ناحیه ٔ بمپور بلوچستان و مرکب از یکصد خانوار است . (از جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span>).<br></font></div>'),
(268934, 'هوتان', '<span class=\"hlight\">هوتان .</span> (اِخ ) دهی است از بخش کنارک شهرستان چاه بهار. دارای <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> تن سکنه، آب آن از رودخانه و محصول عمده اش غله است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268935, 'هوتانه', '<span class=\"hlight\">هوتانه .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (اِخ ) یا اُتانس . نام جد مادری اردشیر درازدست است که در داستان بردیای دروغین نیز نقشی داشته است . رجوع به ایران باستان ص <span class=\"hlight\" dir=\"rtl\">٩٠٨</span>، <span class=\"hlight\" dir=\"rtl\">١٦٢٥</span> و <span class=\"hlight\" dir=\"rtl\">١٤٦٠</span> شود.<br></font></div>'),
(268936, 'هوتة', '<span class=\"hlight\">هوتة.</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> هََ ت َ ]</font></b> (ع اِ) زمین نشیب . ج، هُوَت . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> راه سرازیر بسوی آب . (اقرب الموارد).<br></font></div>'),
(268937, 'هوتخش', '<span class=\"hlight\">هوتخش .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (پهلوی، ص، اِ) صنعتگر. (ایران در زمان ساسانیان ص <span class=\"hlight\" dir=\"rtl\">٦٠</span> از ترجمه ٔ فارسی ).<br></font></div>'),
(268938, 'هوتخشبد', '<span class=\"hlight\">هوتخشبد.</span> <font color=\"DarkGreen\"><b>[ ت ُ ب َ ]</font></b> (پهلوی، اِ مرکب ) رئیس صنعتگران . رجوع به هوتخش شود.<br></font></div>'),
(268939, 'هوتس', '<span class=\"hlight\">هوتس .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (اِخ ) نام زن گشتاسب معاصر زردشت . رجوع به ترجمه ٔ یشتها ج <span class=\"hlight\" dir=\"rtl\">١</span> و یسنا ص <span class=\"hlight\" dir=\"rtl\">٤٧</span> شود.<br></font></div>'),
(268940, 'هوتسما', '<span class=\"hlight\">هوتسما.</span> (اِخ ) مارتین تئودر. از خاورشناسان هلندی است که اختصار تاریخ سلجوقی البغدادی راطبع کرده است . (از معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">١</span> ستون <span class=\"hlight\" dir=\"rtl\">١٩٠١</span>).<br></font></div>'),
(268941, 'هوتک', '<span class=\"hlight\">هوتک .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) دهی است از بخش مرکزی شهرستان کرمان . دارای <span class=\"hlight\" dir=\"rtl\">١٤٠</span> تن سکنه، آب آن از قنات و محصول عمده اش غله و حبوب و کار دستی مردم آنجا قالی بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268942, 'هوتی', '<span class=\"hlight\">هوتی .</span> (اِخ ) مرکز دهستان سرمشک از بخش ساردوئیه ٔ شهرستان جیرفت . دارای <span class=\"hlight\" dir=\"rtl\">١٤٠</span> تن سکنه، آب آن از رودخانه و محصول عمده اش غله و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268943, 'هوج', '<span class=\"hlight\">هوج .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (ع اِمص ) درازی با اندک گولی و سبکی و شتابزدگی . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268944, 'هوج', '<span class=\"hlight\">هوج .</span> (ع ص، اِ) ج ِ هوجاء.(منتهی الارب ) (اقرب الموارد). رجوع به هوجاء شود.<br></font></div>'),
(268945, 'هوج', '<span class=\"hlight\">هوج .</span> (اِخ ) دهی است از بخش ورزقان شهرستان اهر. دارای <span class=\"hlight\" dir=\"rtl\">١١٩</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله است . در دو محل به نام هوج بالا و پایین بنا شده و سکنه ٔ هوج بالا <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268946, 'هوجرد', '<span class=\"hlight\">هوجرد.</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (اِخ ) دهی از بخش مرکزی شهرستان جیرفت . دارای <span class=\"hlight\" dir=\"rtl\">٤٥٩</span> تن سکنه، آب آن از رودخانه ٔ هلیل و محصول عمده اش غله، مرکبات و برنج است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(268947, 'هوجره', '<span class=\"hlight\">هوجره .</span> <font color=\"DarkGreen\"><b>[ ج َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) گیاهی است که آن را سرخ مرد گویند و به عربی عصی الراعی خوانند و بعضی گویند گیاهی است و آن بیشتر در تبریز به هم رسد و بیخ آن را در مرهمها داخل سازند و سیاه پلاو را بدان رنگ کنند و بعضی گویند گاوزبان تلخ است . (برهان ).<br></font></div>'),
(268948, 'هوجل', '<span class=\"hlight\">هوجل .</span> <font color=\"DarkGreen\"><b>[ هََ ج َ ]</font></b> (ع ص، اِ) دشت دوراطراف بی نشان . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زمین ناهموار. <BR><font color=\"Blue\">◄</font> شتر تیزرو. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ناقه ٔ شتاب زده . <BR><font color=\"Blue\">◄</font> شب دراز. <BR><font color=\"Blue\">◄</font> مرد آهسته و گران . (منتهی الارب )(اقرب الموارد). <BR><font color=\"Blue\">◄</font> زن فراخ فرج . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن تباهکار. <BR><font color=\"Blue\">◄</font> بقیه ٔ خواب و پینکی . <BR><font color=\"Blue\">◄</font> لنگر کشتی . <BR><font color=\"Blue\">◄</font> مرد دراز گول شتاب زده . <BR><font color=\"Blue\">◄</font> نوعی رفتار با فروهشتگی و استرخاء. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268949, 'هوجلة', '<span class=\"hlight\">هوجلة.</span><font color=\"DarkGreen\"><b>[ هََ ج َ ل َ ]</font></b> (ع مص ) خفتن . (منتهی الارب ). به خوابی سبک رفتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> در زمین پست هموار رفتن . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268950, 'هوجویه', '<span class=\"hlight\">هوجویه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِ)گیاهی است برگ آن شبیه کاهو و خاردار و بر زمین نزدیک و دانه ٔ آن سیاه و در تابستان سرخ می گردد مانند رنگ خون و به عربی آن را حمیرا گویند. (انجمن آرا).<br></font></div>'),
(268951, 'هوخ', '<span class=\"hlight\">هوخ .</span> (اِخ ) نام بیت المقدس است . (برهان ). دژهخت . دژگنگ . دژهوخ . رجوع به دژهوخت شود.<br></font></div>'),
(268952, 'هوخت', '<span class=\"hlight\">هوخت .</span> (اِخ ) هوخ . بیت المقدس باشد. (از برهان ). رجوع به هوخ شود.<br></font></div>'),
(268953, 'هوختن', '<span class=\"hlight\">هوختن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص ) برکشیدن و بیرون کشیدن . <BR><font color=\"Blue\">◄</font> آمدن و پیدا شدن . (برهان ).<br></font></div>'),
(268954, 'هوخست', '<span class=\"hlight\">هوخست .</span> (اِخ ) به معنی هوخت که بیت المقدس باشد. (برهان ). ظاهراً مصحف هوخت است . (حاشیه ٔ برهان چ معین ). رجوع به هوخت و دژهوخت شود.<br></font></div>'),
(268955, 'هوخشتر', '<span class=\"hlight\">هوخشتر.</span> <font color=\"DarkGreen\"><b>[ هَُ وَ ش َ رَ ]</font></b> (اِخ ) از پادشاهان معروف سلسله ٔ ماد و پسر فرورتیش یا فراارتس بوده است . هرودت نام این پادشاه را کرآکسار یا کیاکسار نوشته ولی از کتیبه ٔ بیستون داریوش اول معلوم میشود که نامش هوخشتر بوده است . وی از پادشاهان باسیاست بود و چون به پادشاهی رسید دانست که باید بی درنگ اصلاحاتی در کشور کند. ابتدا قشون را با توجه به تجربه ٔ تلخ پدرش در نبرد آسور، اصلاح و منظم کرد. پیاده و سواره ٔ قشون خود را مسلح ساخت و سرانجام آسوررا شکست داد و نینوا پایتخت آسور را گرفت . اما مقارن همان پیشروی های سپاه ماد، سکاها به آسیای غربی حمله کردند و به ناچار پادشاه ماد از محاصره ٔ نینوا دست برداشت و در نزدیکی دریاچه ٔ ارومیه با سکاها روبرو شد. ماجرای سکاها و ماندن آنها در ایران حدود <span class=\"hlight\" dir=\"rtl\">٢٨</span> سال به طول انجامید و پس از پایان آن پادشاه ماد موفق شددر حدود سال <span class=\"hlight\" dir=\"rtl\">٦٠٨</span> تا <span class=\"hlight\" dir=\"rtl\">٦٠٥</span> ق . م . نینوا را تسخیر و آن را با همه ٔ شکوه و عظمتش ویران کند. پس از سقوط آسور، بابل و ماد سرزمینهای آسیای غربی را میان خود تقسیم کردند. گروهی از سکاها که در دربار ماد مانده بودند اختلافی با هوخشتره پیدا کردند و بنزد پادشاه لیدیه رفتند و چون شاه ماد آنها را خواست، دولت لیدیه بازنداد. همین امر سبب جنگ با لیدیه شد و سرانجام با میانجی گری بخت النصر و پادشاه کلیکیه صلح برقرار شد و رود هالیس سرحد دو کشور گردید. هوخشتر از پادشاهان باتدبیر و ارزنده ٔ تاریخ و از قائدین مواقع مهم بوده است . (نقل به اختصار از ایران باستان صص <span class=\"hlight\" dir=\"rtl\">١٨٠</span>-<span class=\"hlight\" dir=\"rtl\">١٩٩</span>).<br></font></div>'),
(268956, 'هوخیدن', '<span class=\"hlight\">هوخیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) برکشیدن و بیرون کشیدن . <BR><font color=\"Blue\">◄</font> پیدا شدن و آمدن . (برهان ). رجوع به هوختن شود.<br></font></div>'),
(268957, 'هود', '<span class=\"hlight\">هود.</span> (ع اِ) جهودان . (منتهی الارب ). یهود، و گفته اند ج ِ هائد است و سپس یهود رابدان خوانده اند و بر این پایه لفظ عربی است . اما نیز گفته اند که مانند الفاظی چون نوح و لوط از زبانهای دیگر به عربی وارد شده است و بعید نیست که در این معنی مخفف «یهود» باشد به حذف یاء. (اقرب الموارد).<br></font></div>'),
(268958, 'هود', '<span class=\"hlight\">هود.</span> (اِخ ) هودبن شالخ بن ارفحشدبن سام بن نوح . این نسبی است که مؤلف حبیب السیر برای او ذکر کرده و نام پدرش را مؤلف منتهی الارب عابر نوشته است . اصطخری نوشته است که قبر این پیامبر در حضرموت است . (یادداشت مؤلف از مسالک اصطخری ). پیامبری است که مطابق آیه ٔ <span class=\"hlight\" dir=\"rtl\">٦٥</span> سوره ٔ اعراف بر قوم عاد فرستاده شده است . ابواسحاق نیشابوری نویسد: «این عادیان مردمانی بودند بلندبالا و ضخیم و اصل ایشان از زعورا بود از مرحاش داماد نوح علیه السلام و مسکن ایشان به ناحیت یمن بود تا به شام . و کافر گشته بودند تا آنگاه که حق تعالی هود را به ایشان فرستاد به رسالت، و ایشان بت پرست بودند و بتان کرده بودند از سنگ کنده شصت ارش به کوه اندر. و هود علیه السلام هم از میان ایشان بود و از دختر نوح بود که نامش زینا بود. ایشان را چهل وهفت سال دعوت کرد، نگرویدند و معجزات می نمود نپذیرفتند... و گویند پیش از رسالت با ملک ایشان دوستی داشت و گویند با ایشان انبازی داشت به تجارت، و انباز را به لغت یمن برادرگویند. در قرآن هود برادر قوم عاد خوانده شده است . هود گفت : یا قوم اعبدوا اﷲ. گفت : مکنید که عذاب آید شما را. گفتند: چه عذاب آید ما را؟ و ما بدین قویی، و خانه های ما بدین قویی، و خانه های ما در کوه است . هرچند پند داد نپذیرفتند و گفتند: تو ما را برهانی بنمای بی حجتی و معجزه ای درست نیاید. ما به گفتار مجردروی از خدایان خویش نگردانیم و به تو نگرویم . آنگاه گفتند نکشیم تو را و در بلا اندازیم تو را که تو خویشی و پیوسته ای ما را ولیکن بر تو می ترسیم از خدایان ما که تو را بلا رسانند... هود گفت که من توکل بر خدای کرده ام (قرآن <span class=\"hlight\" dir=\"rtl\">٥٤/١١</span> و <span class=\"hlight\" dir=\"rtl\">٥٦</span>)... آنگاه گفت : هرچه بتوانید کردن بکنید... شما قول ناصحان را درست ندارید. چون فرمان نکردند و هلاک ایشان نزدیک شد، آنگاه قصد هود کردند به جفا کردن و آزردن . هود دعا کرد، اجابت آمد. چون اثر عذاب بدیدند بگریختند و به دشت بیرون شدند. باد بر ایشان غلبه کرد. پایها بر زمین زدند و دو ارش بر زمین فروبردند گفتند: اکنون باد با ما چه تواند کردن ؟... هفت هشت شب باد بر سر ایشان می جست و همه از سرما خشک شدند و ساقهاشان به زمین بماند. پس چون هلاک شدند، آن تنی چند که گرویده بودند به سلامت بیرون ماندند و آن مالها مانده بود، همه بسوخت و چهارپایان خشک شدند. پس از آن هود بیست وهفت سال بزیست آنگاه بمرد و آن گروه که مسلمان بودند از بقیت عادیان سوی عجم رفتند. و عجم سام بن نوح را بود به یک روایت . و در تفسیر گویند به یمن افتادند و گویند که یمن و زمین کنعان از نسل ایشان بود. و از پس هود و عاد به دویست سال ملک تعالی صالح را به ثمود فرستاد». (قصص الانبیاء چ بنگاه ترجمه و نشر کتاب صص <span class=\"hlight\" dir=\"rtl\">٤٠</span>-<span class=\"hlight\" dir=\"rtl\">٤٢</span>) <span class=\"hlight\">:</span> <br>چنان دان که هود اندر آن روزگار<br>پیمبر بد از داور کردگار.<br> <font color=\"Red\">اسدی .</font><br>کجاست ناقه و کو صالح و کجا شد هود؟<br>که ز آتش اجل اندر امل زدند شرر.<br> <font color=\"Red\">ناصرخسرو.</font><br>هود هدایت است شاه اصل سریر عادیان <br>صرصر رستخیز دان قوت رای شاه را.<br> <font color=\"Red\">خاقانی .</font><br>او هود ملت آمد بر عادیان فتنه <br>الا سپاه خشمش من صرصری ندارم .<br> <font color=\"Red\">خاقانی .</font><br>هود گرد مؤمنان خطی کشید<br>نرم می شد باد کآنجا می رسید.<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(268959, 'هود', '<span class=\"hlight\">هود.</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (ع اِ) ج ِ هَوَدَة. (منتهی الارب ). رجوع به هودة شود.<br></font></div>'),
(268960, 'هود', '<span class=\"hlight\">هود.</span> (اِ) رکو و لته ٔ سوخته را گویند که بر بالای سنگ آتش زنه نهند و چخماق بر آن زنند تا آتش در آن افتد. <BR><font color=\"Blue\">◄</font> جامه ای را نیز گفته اند که نزدیک به سوختن رسیده و زرد شده باشد. (برهان ).<br></font></div>'),
(268961, 'هود', '<span class=\"hlight\">هود.</span> (اِخ ) دهی است از دهستان بیدشهر شهرستان لار. دارای <span class=\"hlight\" dir=\"rtl\">٤٨٩</span> تن سکنه، آب آن از چاه و محصول عمده اش غله و صیفی و کار دستی مردم آنجا گلیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(268962, 'هود', '<span class=\"hlight\">هود.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) توبه کردن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پشیمان شدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> به حق بازگشتن . <BR><font color=\"Blue\">◄</font> جهود شدن . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268963, 'هود', '<span class=\"hlight\">هود.</span> (اِخ ) نام سوره ٔ یازدهم از کلام اﷲ مجید که شامل <span class=\"hlight\" dir=\"rtl\">١٢٣</span> آیه است .<br></font></div>'),
(268964, 'هوداس', '<span class=\"hlight\">هوداس .</span> (اِخ ) اکتاو. یکی از خاورشناسان فرانسوی است که نسخه ٔ عربی سیره ٔ جلال الدین مینکبرنی را به چاپ رسانیده است . تولد او درسال <span class=\"hlight\" dir=\"rtl\">١٨٤٠</span> م . اتفاق افتاده و استاد مدرسه ٔ السنه ٔ شرقی پاریس بوده است . او راست : طرف المغربیة، مکاتیب مخطوطة و چندین کتاب دیگر. (از معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(268965, 'هوداسیون', '<span class=\"hlight\">هوداسیون .</span> (اِ) اسم مغربی نعناع است . (مخزن الادویه ).<br></font></div>'),
(268966, 'هودج', '<span class=\"hlight\">هودج .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو دَ ]</font></b> (ع اِ) چیزی چون سبدی بزرگ و سایبانی بر سر آن که بر پشت اشتر نهند و بر آن نشینند و آن مانند کجاوه و پالکی جفت نیست . (یادداشت مؤلف ). کجاوه ای که در آن زنان نشینند و عماری شتر. (غیاث ). هوده . بارگیر. (منتهی الارب ) <span class=\"hlight\">:</span> <br>ز ایوان شاه جهان تا به دشت <br>همی اشتر و اسب و هودج گذشت .<br> <font color=\"Red\">فردوسی .</font><br>ز هودج فروهشته دیبا جلیل <br>سپاه ایستاده رده خیل خیل .<br> <font color=\"Red\">فردوسی .</font><br>صحن زمین ز کوکبه ٔ هودج آنچنانک <br>گفتی که صدهزار فلک شد مشهرش .<br> <font color=\"Red\">خاقانی .</font><br>آن به که پیش هودج جانان کنی نثار<br>آن جان که وقت صدمه ٔ هجران شود فنا.<br> <font color=\"Red\">خاقانی .</font><br>طالعش را شهسواری دان که بار هودجش <br>کوهه ٔ عرش معلا برنتابد بیش از این .<br> <font color=\"Red\">خاقانی .</font><br>پرده نشینان که درش داشتند<br>هودج او یک تنه بگذاشتند.<br> <font color=\"Red\">نظامی .</font><br>آنکه با یار هودجش نظر است <br>نتواند به ساربان گفتن .<br> <font color=\"Red\">سعدی .</font><br>تو خوش خفته در هودج کاروان <br>مهار شتر در کف کاردان .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هودج خانه </span> ؛ هودج . عماری <span class=\"hlight\">:</span> <br>سرافیل آمد و پر برفشاندش <br>به هودج خانه ٔ زخرف نشاندش .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">هودج نشین </span> ؛ آنکه در هودج نشیند. (یادداشت مؤلف ).<br></font></div>'),
(268967, 'هودر', '<span class=\"hlight\">هودر.</span> <font color=\"DarkGreen\"><b>[ هَُ دَ ]</font></b> (اِخ ) دهی است از بخش سلماس شهرستان خوی . دارای <span class=\"hlight\" dir=\"rtl\">١٥٧</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و کار دستی مردم آنجا جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268968, 'هودر', '<span class=\"hlight\">هودر.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو دَ ]</font></b> (ص ) هر چیز زشت و زبون را گویند. <BR><font color=\"Blue\">◄</font> مردم بدروی و بدقیافه را نیز گفته اند. (برهان ).<br></font></div>'),
(268969, 'هودر یعقوبیه', '<span class=\"hlight\">هودر یعقوبیه .</span> <font color=\"DarkGreen\"><b>[ دَ رِ ی َ بی ی َ]</font></b> (اِخ ) دهی است از بخش طبس شهرستان فردوس . دارای <span class=\"hlight\" dir=\"rtl\">٤٨٧</span> تن سکنه، آب آن از قنات و محصول عمده اش غله، میوه، ذرت و پنبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(268970, 'هودرج', '<span class=\"hlight\">هودرج .</span> <font color=\"DarkGreen\"><b>[ دَ رَ ]</font></b> (اِخ ) دهی است از بخش اسدآباد شهرستان همدان . دارای <span class=\"hlight\" dir=\"rtl\">٥٤٤</span> تن سکنه، آب آن از چشمه ها ومحصول عمده اش انگور، لبنیات، غله و کار دستی زنان آنجا قالی بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268971, 'هودسن', '<span class=\"hlight\">هودسن .</span><font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (اِخ ) هنری . یکی از دریانوردان انگلیس بود که در قرن شانزدهم و اوایل قرن هفدهم میلادی می زیست و در <span class=\"hlight\" dir=\"rtl\">١٦١١</span> م . درگذشت . او موفق به کشف قسمتی از دنیای جدید شد، از جمله خلیج هودسن که در کشور کاناداست و از اقیانوس اطلس انشعاب می یابد و نیز رودی که در مشرق نیویورک جریان دارد به نام او خوانده شده است . (از فرهنگ امریکایی وبستر).<br></font></div>'),
(268972, 'هودع', '<span class=\"hlight\">هودع .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (ع اِ) شترمرغ . (از منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(268973, 'هودعة', '<span class=\"hlight\">هودعة.</span> <font color=\"DarkGreen\"><b>[ هََ دَ ع َ ]</font></b> (ع اِ) یک شترمرغ . (از اقرب الموارد).<br></font></div>'),
(268974, 'هودل', '<span class=\"hlight\">هودل .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِ) به معنی رصد باشد، چه هودل بند رصدبند را گویند. (برهان ). رجوع به رصد شود.<br></font></div>'),
(268975, 'هوده', '<span class=\"hlight\">هوده .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ) به معنی حق و راست و درست باشد چنانکه بی هوده ناحق و باطل و هرزه را گویند. <BR><font color=\"Blue\">◄</font> (ص ) به معنی کهنه هم به نظر آمده است . (برهان ).<br></font></div>'),
(268976, 'هودک', '<span class=\"hlight\">هودک .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (ع ص ) فربه . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268977, 'هودی', '<span class=\"hlight\">هودی .</span> (اِ) قبره . (ملخص اللغات خطیب کرمانی ). و رجوع به قبره شود.<br></font></div>'),
(268978, 'هودی', '<span class=\"hlight\">هودی .</span> (اِخ ) امرای تجیبی و هودی در سرقسطه ٔ اسپانیا از<span class=\"hlight\" dir=\"rtl\">٤١٠</span> تا <span class=\"hlight\" dir=\"rtl\">٥٣٦</span> هَ . ق . سلطنت کردند و به دست عیسویان برافتادند. (ترجمه ٔ طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">٢٢</span>).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(268979, 'هودیة', '<span class=\"hlight\">هودیة.</span> <font color=\"DarkGreen\"><b>[ دی ی َ ]</font></b> (اِخ ) نام سال سیزدهم بعثت رسول (ص ) از سیزده سال توقف آن حضرت در مکه . (یادداشت مؤلف ). نام سال سیزدهم از نزول قرآن . در این سال سوره ٔ هود و یونس و اعراف و انعام نازل شد.<br></font></div>'),
(268980, 'هوذ', '<span class=\"hlight\">هوذ.</span> <font color=\"DarkGreen\"><b>[ هَُ وَ ]</font></b> (ع اِ) ج ِ هوذة. رجوع به هوذة شود.<br></font></div>'),
(268981, 'هوذر', '<span class=\"hlight\">هوذر.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِ) چیزی بد و زشت . (جهانگیری ).<br></font></div>'),
(268982, 'هوذلة', '<span class=\"hlight\">هوذلة.</span> <font color=\"DarkGreen\"><b>[ هََ ذَ ل َ ]</font></b> (ع مص ) شتاب رفتن . <BR><font color=\"Blue\">◄</font> مضطرب شدن در دویدن . <BR><font color=\"Blue\">◄</font> بسوی بالا انداختن کمیز را. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جنبانیده شدن مشک شیر. <BR><font color=\"Blue\">◄</font> سست شدن در جماع . <BR><font color=\"Blue\">◄</font> جنبان بیرون آمدن بول شتر. <BR><font color=\"Blue\">◄</font> جنبیدن دلو. (منتهی الارب ).<br></font></div>'),
(268983, 'هوذی', '<span class=\"hlight\">هوذی .</span> <font color=\"DarkGreen\"><b>[ ذی ی ]</font></b> (ص نسبی )منسوب است به هوذ که بطنی است از عذرة. (سمعانی ).<br></font></div>'),
(268984, 'هور', '<span class=\"hlight\">هور.</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (اِخ ) دهی است از بخش دهلران شهرستان ایلام . دارای <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن سکنه، آب آن از چشمه ها و محصول عمده اش غله و لبنیات و پشم است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268985, 'هور', '<span class=\"hlight\">هور.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) تهمت نهادن بر کسی در کاری . <BR><font color=\"Blue\">◄</font> گمان بردن به چیزی . <BR><font color=\"Blue\">◄</font> بازگردانیدن از چیزی . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برانگیختن کسی را برچیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کشتن قومی را و بر روی درافتادن قوم بر یکدیگر. <BR><font color=\"Blue\">◄</font> نصیحت کردن به غرض . <BR><font color=\"Blue\">◄</font> استوار کردن چیزی را. <BR><font color=\"Blue\">◄</font> بر زمین زدن . <BR><font color=\"Blue\">◄</font> شکستن بنا را. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شکسته و ویران شدن بنا. (منتهی الارب ). فروریخته شدن . (ترجمان القرآن ). ریهیده شدن . (زوزنی ) (تاج المصادر) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) دریای خرد که به ریزش آب به بیشه ها و مانند آن فراخ گردد. ج، اهوار. <BR><font color=\"Blue\">◄</font> گله ٔ گوسپندان بدان جهت که از کثرت بعضی بر بعضی می افتد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(268986, 'هور', '<span class=\"hlight\">هور.</span> (ع مص ) تهمت نهادن بر کسی در کاری . (منتهی الارب ). هَور. رجوع به هَور شود.<br></font></div>'),
(268987, 'هور', '<span class=\"hlight\">هور.</span> (اِ) نامی است از نامهای آفتاب . (برهان ). خور. خورشید. شمس . شارق .ذکاء. شید. بیضا. سور (سانسکریت ). مهر <span class=\"hlight\">:</span> <br>خداوند ماه و خداوند هور<br>خداوند روز و خداوند زور.<br> <font color=\"Red\">فردوسی .</font><br>به نیروی یزدان که او داد زور<br>بلند آفریننده ٔ ماه و هور.<br> <font color=\"Red\">فردوسی .</font><br>بدان گهی که هور قیرگون شود<br>چو روی عاشقان شود ضیای او.<br> <font color=\"Red\">منوچهری .</font><br>تن پیل و یاقوت رخشان چو هور<br>زبرجدش خرطوم و دندان بلور.<br> <font color=\"Red\">اسدی .</font><br>ز عکس می زرد و جام بلور<br>سپهری شد ایوان پر از ماه وهور.<br> <font color=\"Red\">اسدی .</font><br>گیر که گیتی همه چنگ است و نای <br>گیر که گیتی همه ماه است و هور.<br> <font color=\"Red\">انوری .</font><br>درآن رخنه از نور تابنده هور<br>نگه کرد سر تا سرین ستور.<br> <font color=\"Red\">نظامی .</font><br>سروش درفشان چو تابنده هور<br>ز وسواس دیو فریبنده دور.<br> <font color=\"Red\">نظامی .</font><br>باد تا بر سپهر تابد هور<br>دوستت دوستکام و دشمن کور.<br> <font color=\"Red\">نظامی .</font><br>بتابد بسی ماه و پروین و هور<br>که سر برنداری ز بالین گور.<br> <font color=\"Red\">سعدی .</font><br>نور گیتی فروز چشمه ٔ هور<br>زشت باشدبه چشم موشک کور.<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> بخت و طالع. (برهان ). اختر. اقبال . روز <span class=\"hlight\">:</span> <br>ز بیژن فزون بود هومان به زور<br>هنر عیب گردد چو برگشت هور.<br> <font color=\"Red\">فردوسی .</font><br>به هور هندوان آمد خزینه <br>به سنگستان غم رفت آبگینه .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">شبگیر هور</span> ؛ ظاهراً صبحگاه مقارن طلوع خورشید <span class=\"hlight\">:</span> <br>بپرسید از ایشان که شبگیر هور<br>شنیدید آواز نعل ستور .<br> <font color=\"Red\">فردوسی .</font><br>- <span class=\"hlight\">نوروز هور</span>.<br> <BR><font color=\"Blue\">◄</font> در شعر ذیل از ناصرخسرو این کلمه آمده است و در حاشیه ٔ دیوان بدان معنی نگاه و نظر داده شده است اما ظاهراً بموقع و بگاه و بوقت معنی میدهد <span class=\"hlight\">:</span> <br>اکنون نگر به کار که کارت به دست توست <br>برگ سفر بساز و بکن کارها به هور.<br> <font color=\"Red\">ناصرخسرو.</font><br> <BR><font color=\"Blue\">◄</font> نام ستاره ای هم هست که هر هزار سال یک بار طلوع کند. <BR><font color=\"Blue\">◄</font> به هندی به معنی دیگر باشد. (برهان ). <BR><font color=\"Blue\">◄</font> نام روز یازدهم از سی روز ماه نزد پارسیان . خور <span class=\"hlight\">:</span> <br>به آذرمه اندر بد و روز هور<br>که از شیر پردخته شد پشت گور.<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268988, 'هور', '<span class=\"hlight\">هور.</span> (اِخ ) نام یکی از نجبای معاصر با بهرام گور. (ولف ) <span class=\"hlight\">:</span> <br>یکی نامه بنوشت بهروز هور<br>به نزد شهنشاه بهرام گور.<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(268989, 'هور موسی', '<span class=\"hlight\">هور موسی .</span> <font color=\"DarkGreen\"><b>[ رِ سا ]</font></b> (اِخ ) نام مردابی به خوزستان .<br></font></div>'),
(268990, 'هورا', '<span class=\"hlight\">هورا.</span> (اِ صوت ) فریاد و بانگ حاکی از طرفداری و تشویق کسی و معمولاً با فعل کشیدن به کار رود.<br></font></div>'),
(268991, 'هورا کشیدن', '<span class=\"hlight\">هورا کشیدن .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) فریاد و بانگ برآوردن برای دل دادن یا تشویق کسی که به امری خطیر چون مبارزه یا مسابقه اشتغال دارد.<br></font></div>'),
(268992, 'هورات', '<span class=\"hlight\">هورات .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) ج ِ هورة. (منتهی الارب ) (اقرب الموارد). رجوع به هورة شود.<br></font></div>'),
(268993, 'هورازه', '<span class=\"hlight\">هورازه .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِخ ) دهی است از بخش نمشیر شهرستان سقز. دارای <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن سکنه، آب آن از چشمه ها و محصول عمده اش غله، توتون، لبنیات و محصولات جنگلی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(268994, 'هوراس', '<span class=\"hlight\">هوراس .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) نام شاعری به رم قدیم . رجوع به هُراس شود.<br></font></div>'),
(268995, 'هورالعظیم', '<span class=\"hlight\">هورالعظیم .</span> <font color=\"DarkGreen\"><b>[ رُل ْ ع َ]</font></b> (اِخ ) نام مردابی به خوزستان . باطلاقی است که از رودخانه های دویرج و کرخه تشکیل یابد و پوشیده از نیزار و عبور از آن ناممکن است . این باطلاق در سرحد ایران و عراق واقع شده است . (از جغرافیای سیاسی کیهان ).<br></font></div>'),
(268996, 'هورام', '<span class=\"hlight\">هورام .</span> (اِخ ) نام شهریار جازر بود که هنگام گشودن فلسطین بر جازر شهریار بود. (قاموس کتاب مقدس ).<br></font></div>'),
(268997, 'هوراند', '<span class=\"hlight\">هوراند.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) نام یکی از بخشهای پنجگانه ٔ شهرستان اهر که در شمال بخش قره داغ و <span class=\"hlight\" dir=\"rtl\">٢٩</span>هزارگزی مرز ایران و روسیه است . محصول عمده ٔ این بخش غله، برنج، پنبه، توت و میوه است . قراء بخش اغلب در دامنه ها بنا شده و از چشمه سارها و رودخانه های محلی مشروب می شود. رودخانه های دیگری که در این بخش وجود دارد، گچرود و قره چای است . بخش هوراند پنج دهستان دارد که عبارتند از: دودانگه شامل <span class=\"hlight\" dir=\"rtl\">٢٠</span> آبادی با <span class=\"hlight\" dir=\"rtl\">٤١٤٦</span> تن سکنه، چهاردانگه شامل <span class=\"hlight\" dir=\"rtl\">٣٨</span> آبادی با <span class=\"hlight\" dir=\"rtl\">٥٢٧٥</span> تن سکنه، دیکله شامل <span class=\"hlight\" dir=\"rtl\">٤٤</span> آبادی با <span class=\"hlight\" dir=\"rtl\">٧٩٥٦</span> تن سکنه، یافت شامل <span class=\"hlight\" dir=\"rtl\">٣٩</span> آبادی با <span class=\"hlight\" dir=\"rtl\">٤٧٨٢</span> تن سکنه، درگهان شامل <span class=\"hlight\" dir=\"rtl\">١٨</span> آبادی با <span class=\"hlight\" dir=\"rtl\">٢٠٤٠</span> تن سکنه . مجموعاً بخش شامل <span class=\"hlight\" dir=\"rtl\">١٥٩</span> آبادی و دارای <span class=\"hlight\" dir=\"rtl\">٢٤١٩٩</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268998, 'هوراند', '<span class=\"hlight\">هوراند.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) قصبه ٔ مرکزی بخش هوراند شهرستان اهر. دارای <span class=\"hlight\" dir=\"rtl\">٨٠٠</span> تن سکنه، آب آن از چشمه سارها و محصول عمده اش غله و انگور و توت و سردرختی و کار دستی زنان آنجا بافتن فرش و گلیم است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(268999, 'هورخش', '<span class=\"hlight\">هورخش .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) به معنی هور است که نام آفتاب عالمتاب باشد. (برهان ). نخستین کسی که این اصطلاح را در مصنفات خود به کار برده، تا آنجا که می دانیم، شیخ شهاب الدین سهروردی است . وی در کتاب «المشارع و المطارحات »، فصل سوم در کیفیت ظهور مغیبات، این کلمه را به کار برده و نیز در حکمةالاشراق وی این کلمه دیده میشود... از جمله ٔ آثار شیخ اشراق دو گفتار و یا به تعبیر اصح دو نیایش است که به نام هورخش کبیر و هورخش صغیر... در وجه اشتقاق این کلمه سه وجه در نظر است : نخست آنکه مرکب از هو = خوب و رخش به معنی رخشان و روشن و روی هم به معنی نیک روشن و صفتی است که برای آفتاب آمده است ...: انت هورخش الشدید. آقای هنینگ این وجه را مردود دانسته است واما آقای پورداود درست شمرده اند. دوم آنکه این کلمه از هُوَرَخشئته اوستایی است که جزء دوم آن که «خشئته » است در پهلوی و بعد در فارسی کوتاه و «شید» شده است . وجه سوم آنکه هورخش مخفف هوررخش است یعنی آفتاب درخشان و راء اول حذف شده است . این وجه را استاد هنینگ پذیرفته اند. در ادبیات فارسی خورشید بارها به صفاتی بدین مفهوم یاد شده . (از حاشیه ٔ برهان چ معین ).<br></font></div>'),
(269000, 'هورز', '<span class=\"hlight\">هورز.</span> (اِخ ) دهی است از بخش مرکزی شهرستان فیروزآباد فارس . دارای <span class=\"hlight\" dir=\"rtl\">٢٥٨</span> تن سکنه، آب آن از قنات و محصول عمده اش غله، خرما و لیمو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(269001, 'هورزنگی', '<span class=\"hlight\">هورزنگی .</span> <font color=\"DarkGreen\"><b>[ هََ رِ ]</font></b> (اِخ ) نام مردابی به خوزستان . (یادداشت مؤلف ). رجوع به هورالعظیم شود.<br></font></div>'),
(269002, 'هورس', '<span class=\"hlight\">هورس .</span> <font color=\"DarkGreen\"><b>[ هَُ وَ ]</font></b> (اِ) درکوههای اطراف کرج ژونی پروس پلی کارپا به نام هورس موسوم است . ارس . (یادداشت مؤلف ). رجوع به جنگل شناسی ساعی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٣</span> و ارس شود.<br></font></div>'),
(269003, 'هورستار', '<span class=\"hlight\">هورستار.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِ) دستور و موبد و هیربد را گویند و اینان در آئین پارسیان به محافظت شوارع شریعت و حراست حدود دانش و حکمت می پردازند. (از آنندراج ). در انجمن آرا هورستان ضبط شده است .<br></font></div>'),
(269004, 'هورستان', '<span class=\"hlight\">هورستان .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِ) رجوع به هورستار شود.<br></font></div>'),
(269005, 'هورسین', '<span class=\"hlight\">هورسین .</span> <font color=\"DarkGreen\"><b>[ هَُ وَ ]</font></b> (اِخ ) دهی است از بخش صومای شهرستان ارومیه . دارای <span class=\"hlight\" dir=\"rtl\">٣٧٢</span> تن سکنه، آب آن از کوهستان و محصول عمده اش غله و توتون و کار دستی مردم جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269006, 'هورشید', '<span class=\"hlight\">هورشید.</span> (اِ مرکب ) آفتاب . خورشید. هور به معنی آفتاب و شید نور است . (از انجمن آرا).<br></font></div>'),
(269007, 'هورع', '<span class=\"hlight\">هورع .</span> <font color=\"DarkGreen\"><b>[ هََ رَ ]</font></b> (ع ص ) مرد بددل سست بی خیر. <BR><font color=\"Blue\">◄</font> گول . <BR><font color=\"Blue\">◄</font> باد شتاب و تند بسیارغبار. <BR><font color=\"Blue\">◄</font> زن شتاب چست سبک . (منتهی الارب ).<br></font></div>'),
(269008, 'هورقان', '<span class=\"hlight\">هورقان .</span> (اِخ ) از قرای مرو است . (معجم البلدان ).<br></font></div>'),
(269009, 'هورقانی', '<span class=\"hlight\">هورقانی .</span> (ص نسبی ) منسوب به هورقان که قریه ای است در نزدیکی مرو به هفت فرسنگی . (سمعانی ).<br></font></div>'),
(269010, 'هورقلیا', '<span class=\"hlight\">هورقلیا.</span> <font color=\"DarkGreen\"><b>[ هَُ وَ ق ِ <span class=\"hlight\" dir=\"rtl\">/</span> ق َ <span class=\"hlight\" dir=\"rtl\">/</span> هََ وَ ق َ ]</font></b> (اِ) ظاهراً از کلمه ٔ عبری «هبل قرنیم » گرفته شده که هبل به معنی هوای گرم و تنفس و بخار، و قرنیم به معنی درخشش و شعاع است و رویهم ترکیب به معنی تشعشع بخار است ... نخستین کسی که پس از اسلام این کلمه را استعمال کرده است تا آنجا که می دانیم شیخ اشراق سهروردی (<span class=\"hlight\" dir=\"rtl\">٥٤٩</span>-<span class=\"hlight\" dir=\"rtl\">٥٨٧</span> هَ . ق .) است . وی در حکمةالاشراق (چ هَ . کربین ص <span class=\"hlight\" dir=\"rtl\">٢٥٤</span>) گوید: «و قد یصعدون الی السماء مع ابدان فیلتصقون ببعض السادة العلویة و هذه احکام الاقلیم الثامن الذی فیه جابلق و جابرص و هورقلیا ذات العجایب ». شهرزوری و قطب الدین شیرازی نیز عبارت فوق را در شرح حکمةالاشراق توضیح داده اند. شیخ احمد احسائی (<span class=\"hlight\" dir=\"rtl\">١١٦٦</span>-<span class=\"hlight\" dir=\"rtl\">١٢٤١</span> هَ . ق .) در مؤلفات خود بارها این کلمه را به کار برده و شرح داده است، از جمله در جوامعالکلم ج <span class=\"hlight\" dir=\"rtl\">١</span>، رساله ٔ پنجم قسمت اول ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span> و <span class=\"hlight\" dir=\"rtl\">١٢٣</span> رساله ٔ سوم قسمت دوم ص <span class=\"hlight\" dir=\"rtl\">١١٩</span>، <span class=\"hlight\" dir=\"rtl\">١٢٤</span> و <span class=\"hlight\" dir=\"rtl\">١٣٤</span> و رساله ٔ دوم قسمت دوم ص <span class=\"hlight\" dir=\"rtl\">١٠٣</span>، شرح عرشیه چ تبریز ص <span class=\"hlight\" dir=\"rtl\">١١٩</span>. سیدکاظم رشتی و حاج محمدکریم خان و حاج ملاهادی سبزواری نیز این کلمه را در مصنفات خود به کار برده اند: «هورقلیا هم عالمی است از عوالم که خداوند خلق فرموده است . مراد از آن عالم اجمالاً عالم امثال است یعنی عالم صور، اگرچه در مقام تفصیل، سماوات آن عالم را هورقلیا و ارض آن عالم را جابلقا و جابرسا می گوییم، ولی گاه در کلام حکما کل آن عالم را با جمیع مراتب عالم هورقلیا می گویند و گاه اقلیم هشتم می گویند به این مناسبت که حکما و علمای قدیم این زمین را بر هفت اقلیم و هفت قسمت قرار داده اندو عالم هورقلیا چون فوق این اقالیم است و از حدود ظاهر این اقالیم خارج است، اقلیم ثامنش می گویند...». (تنزیه الاولیاء ابراهیمی ص <span class=\"hlight\" dir=\"rtl\">٧٠٢</span>). شیخ احسائی در کتاب شرح الزیارة صص <span class=\"hlight\" dir=\"rtl\">٣٦٥</span>-<span class=\"hlight\" dir=\"rtl\">٣٦٦</span> گوید: «انسان را دو جسم و جسد است : اما جسد اول مرکب از عناصر زمانیه است و این جسد مانند جامه ای است که انسان آن را می پوشد و از تن بیرون می آورد، آن را نه لذتی است و نه المی، نه طاعتی و نه معصیتی ... حاصل آن که این جسد از انسان نیست ... و اما جسد دوم جسد باقی است و آن طینتی است که انسان از آن آفریده شده و در گور او باقی میماند آن گاه که زمین جسد عنصری را بخورد و هر جزء از وی پراکنده گردد و به اصل خویش ملحق شود. پس بخش آتشی به آتش پیوندد و بخش هوائی به هوا و بخش آبی به آب و بخش خاکی به خاک بازگردد. جسد مزبور مستدیراً باقی ماند و این جسد انسان است که نه زیاد و نه کم شود و در قبر پس از زوال جسد عنصری که کثافت و اعراض از آن است، باقی ماند و آن گاه که اعراض مسمی به جسد عنصری زایل گردد دیدگان حسی آن را نبینند. ازاین رو چون جسد پوسیده و محو گردد، چیزی یافته نشود چنان که بعضی گفته اند که جسد معدوم شود و چنین نیست، بلکه در آن در قبر خویش است اما دیدگان مردم دنیا، به علت کثافتی که در ابصار است، آن را ننگرند و چیزی را جز از نوع خویش نبینند و چون خدای سبحانه، بعث آفریدگان را اراده کند بر همه ٔ زمین آبی از دریای زیر عرش ببارد سردتر از برف و آن را صاد گویند و آن در قرآن مذکور است، پس روی زمین را دریایی فراگیرد که به بادها تموج پذیرد و اجزای هر شخص مصفا گردد و اجزای جسد وی در قبر او مستدیر، یعنی به هیأت بنیه ٔ وی در دنیا، جمع گردد... واجزایی از زمین با او مزج شود پس در قبر وی بروید چنان که سماروغ در رستن خویش پس چون اسرافیل در صور بدمد روانها پرواز گیرند، هر روانی بسوی گور جسد خویش، و در آن داخل شود. پس زمین از آن شکافته گردد... آنگاه ایشان ایستاده اند و نظر کنند و این جسد باقی از زمین هورقلیاست و آن جسدی است که بدان حشر و داخل بهشت و دوزخ شوند. در تئوسوفی به جسم مثالی یا نجمی یاهورقلیایی که مخصوص عالم ملکوت یا معنویات است قائل اند». (از حاشیه ٔ برهان چ معین ). وجودی میان جسمانیات و مجردات و ظاهراً این کلمه مأخوذ از نام هراقلیطس  است که وجود را صیرورت می شمارد و منکر وجود ثابت است . (یادداشت مؤلف ).<br>- <span class=\"hlight\">بدن هورقلیائی </span> ؛ قالب مثالی . (یادداشت مؤلف ).<br></font></div>'),
(269011, 'هورمز', '<span class=\"hlight\">هورمز.</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (اِخ ) نام فرشته ای است . هرمزد. هورمزد. رجوع به هرمز شود. <BR><font color=\"Blue\">◄</font> نام کوکب مشتری . <BR><font color=\"Blue\">◄</font> (اِ) نام روز اول از هر ماه شمسی . (برهان ). رجوع به هرمز شود.<br></font></div>'),
(269012, 'هورمزد', '<span class=\"hlight\">هورمزد.</span><font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) به معنی هورمز است که نام فرشته ای است . <BR><font color=\"Blue\">◄</font> نام کوکب مشتری . (برهان ) <span class=\"hlight\">:</span> <br>شیربا گاو و بره گرگ آشتی کرده به طبع<br>آشتی شان هورمزد مهربان انگیخته .<br> <font color=\"Red\">خاقانی .</font><br>رجوع به هرمزد شود.<br><BR><font color=\"Blue\">◄</font> (اِ) روز اول است از هر ماه شمسی . (برهان ).<br></font></div>'),
(269013, 'هورمه', '<span class=\"hlight\">هورمه .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) دهی است از بخش کنگان شهرستان بوشهر. دارای <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه، آب آن از قنات و محصول عمده اش غله و تنباکو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(269014, 'هورمون', '<span class=\"hlight\">هورمون .</span> <font color=\"DarkGreen\"><b>[ هُرْ مُن ْ ]</font></b> (فرانسوی، اِ) رجوع به هرمن شود.<br></font></div>'),
(269015, 'هوره', '<span class=\"hlight\">هوره .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان شهرکرد. دارای <span class=\"hlight\" dir=\"rtl\">١١٤٢</span> تن سکنه، آب آن از قنات و زاینده رود و محصول عمده اش کشمش، بادام، برنج و انگور است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(269016, 'هوره', '<span class=\"hlight\">هوره .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) اسم فارسی خبازی است . (مخزن الادویه ).<br></font></div>'),
(269017, 'هوره عاگول', '<span class=\"hlight\">هوره عاگول .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) دهی است از بخش هویزه ٔ شهرستان دشت میشان . دارای <span class=\"hlight\" dir=\"rtl\">١٢٠٠</span> تن سکنه، آب آن از چاه و مازاد آب کرخه کور و محصول عمده اش غله و کار دستی مردم آن قالیچه بافی است . ساکنان آنجا از طایفه ٔ بنی صالح اند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269018, 'هوز', '<span class=\"hlight\">هوز.</span> <font color=\"DarkGreen\"><b>[ هََ وْ وَ ]</font></b> (اِ) دومین صورت از صور هشتگانه ٔ حروف جُمَّل که شامل سه حرف «هَ» و «و» و «ز» و به ترتیب برابر با پنج و شش و هفت است <span class=\"hlight\">:</span> <br>به هر لغت که تو گویی سخن توانی گفت <br>که اصل هر لغتی را تو ابجد و هوزی .<br> <font color=\"Red\">منوچهری .</font><br>- <span class=\"hlight\">هاء هوز</span> ؛ هاء دوچشم . هاء گرد. مقابل حاء حطی .<br></font></div>'),
(269019, 'هوز', '<span class=\"hlight\">هوز.</span> (اِ) آواز تند و تیز را گویند مانند صدایی که از طاس برنجی و امثال آن برآید. (برهان ) <span class=\"hlight\">:</span> <br>باز بانگ اندراوفتاد به هوز<br>آهو آزاد شد ز پنجه ٔ یوز.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(269020, 'هوز', '<span class=\"hlight\">هوز.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) گله ٔ گوسفند. (مهذب الاسماء).<br></font></div>'),
(269021, 'هوز', '<span class=\"hlight\">هوز.</span> <font color=\"DarkGreen\"><b>[ هََ وْ وَ ]</font></b> (اِخ ) نام ملکی از ملوک حمیر است . (منتهی الارب ).<br></font></div>'),
(269022, 'هوز', '<span class=\"hlight\">هوز.</span> (اِخ ) خوز. رجوع به خوز شود. جمع معرب آن اهواز است و نام قوم ساکن خوزستان . (حاشیه ٔ برهان چ معین ).<br></font></div>'),
(269023, 'هوزان', '<span class=\"hlight\">هوزان .</span> (اِ) نرگس شکفته را گویند. (برهان ). آیا دگرگون شده ٔ کلمه ٔ موژان نیست ؟ (یادداشت مؤلف ).<br></font></div>'),
(269024, 'هوزب', '<span class=\"hlight\">هوزب .</span> <font color=\"DarkGreen\"><b>[ هََ زَ ]</font></b> (ع ص ) شتر توانا بر سیر. <BR><font color=\"Blue\">◄</font> شتر کلانسال . <BR><font color=\"Blue\">◄</font> (اِ) کرکس . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269025, 'هوزمشیر', '<span class=\"hlight\">هوزمشیر.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) نام اهواز است . (برهان ). قال التوزی : الاهواز تسمی بالفارسیة هرمشیر... و ابوزید گوید اهواز را هرمزشهر گویند... و هوزمشیر مبدل هرمزشهر است . (از حاشیه ٔ برهان چ معین ).<br></font></div>'),
(269026, 'هوزن', '<span class=\"hlight\">هوزن .</span> <font color=\"DarkGreen\"><b>[ هََ زَ ]</font></b> (ع اِ) هر گرد و غبار. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرغی است . (منتهی الارب ).<br></font></div>'),
(269027, 'هوزنه', '<span class=\"hlight\">هوزنه .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو زَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) هَوو. وسنی . ضره (در طالقان قزوین ).<br></font></div>'),
(269028, 'هوزوارش', '<span class=\"hlight\">هوزوارش .</span> <font color=\"DarkGreen\"><b>[ هُزْ رِ ]</font></b> (اِ) رجوع به هزوارش شود.<br></font></div>'),
(269029, 'هوس', '<span class=\"hlight\">هوس .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (ع اِ) نوعی از جنون . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> هلاک . (اوبهی ). <BR><font color=\"Blue\">◄</font> خواهش و آرزو و ریژ وهوا و آرزوی نفس . (ناظم الاطباء). پویه . بویه . میل . هوا. خواست دل . میل و خواهش موقت و ناپایدار. در تداول فارسی به معنی خواهش است بی استحکام و از روی سبکی بی رویت و فکر. هر میل و خواهش بی سابقه و گذرا. صاحب آنندراج گوید: خام و فربه از صفات او است و با لفظافتادن و پختن و پیمودن و کردن و بردن و داشتن و آمدن به کار رود و شواهدی بر گفته ٔ خود آرد <span class=\"hlight\">:</span> این چه هوس است که ایشان می گویند. (تاریخ بیهقی ).<br>مجلس وعظرفتنت هوس است <br>مرگ همسایه واعظ تو بس است .<br> <font color=\"Red\">سنائی .</font><br>هوس فضول به خاطر ایشان راه یابد. (کلیله و دمنه ).<br>شاخ امل بزن که چراغی است زودمیر<br>بیخ هوس بکن که درختی است کم بقا.<br> <font color=\"Red\">خاقانی .</font><br>خاک بیزان هوس بی روزی اند<br>چشم و دل زین خاکدان دربسته به .<br> <font color=\"Red\">خاقانی .</font><br>در هوس این دو سه ویرانه ده <br>کار فلک بود گره در گره .<br> <font color=\"Red\">نظامی .</font><br>مرا چون مخزن الاسرار گنجی <br>چه باید در هوس پیمود رنجی .<br> <font color=\"Red\">نظامی .</font><br>معنی قرآن ز قرآن پرس و بس <br>وز کسی کآتش زده ست اندر هوس .<br> <font color=\"Red\">مولوی .</font><br>پیرمردی زن جوان می خواست <br>گفتمش ترک این هوس خوشتر.<br> <font color=\"Red\">ابن یمین .</font><br> <BR><font color=\"Blue\">◄</font> شهوت . (ناظم الاطباء). خواهش نفسانی . مقابل اراده ٔ عقلانی <span class=\"hlight\">:</span> <br>جست از جایگه آنگاه چو خناسی <br>هوس اندر سر و اندر دل وسواسی .<br> <font color=\"Red\">منوچهری .</font><br>یاد بتان تا کی کنم فرش هوس را طی کنم <br>این اسب چوبین پی کنم چون مرد میدان نیستم .<br> <font color=\"Red\">خاقانی .</font><br>گر تو به هوس جمال او خواهی <br>او در طلب و هوس نمی آید.<br> <font color=\"Red\">عطار.</font><br>عنفوان شبابم غالب و هوی و هوس طالب . (گلستان ).<br>ترک دنیا ز شهوت است و هوس <br>پارسایی نه ترک جامه وبس .<br> <font color=\"Red\">سعدی .</font><br>غزل از روی هوس بود و مدایح ز طمع<br>نه طمع ماند کنون در دل تنگم نه هوس .<br> <font color=\"Red\">ابن یمین .</font><br> <BR><font color=\"Blue\">◄</font> عشق <span class=\"hlight\">:</span> <br>هست بر عاشق پوشیده چنانک <br>کس خمار هوسش نشناسد.<br> <font color=\"Red\">خاقانی .</font><br>تا به امروز مرا در سخن این شور نبود<br>که گرفتار نبودم به کمند هوسی .<br> <font color=\"Red\">سعدی .</font><br>به هرچه درنگرم پیش روی، او بینم <br>که دید در همه عالم بدین صفت هوسی .<br> <font color=\"Red\">سعدی .</font><br>گفتم که مگر تخم هوس کاشتنی است <br>معلومم شد که جمله بگذاشتنی است .<br> <font color=\"Red\">اوحدی .</font><br>گفت مگر ز لعل من بوسه نداری آرزو<br>مردم از این هوس ولی قدرت و اختیار کو.<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> اشتیاق و شوق چیزی . (ناظم الاطباء) <span class=\"hlight\">:</span> امیر مرد فرستاد که ختلان بدو دهند و آن هوس در دل وی مانده است . (تاریخ بیهقی ). تا هوس سجاده بر آب افکندن پیش خاطر آورم . (کلیله و دمنه ).<br>خاک درت را هر نفس بر آب حیوان دسترس <br>خصم تو در خاک هوس تخم تمنا ریخته .<br> <font color=\"Red\">خاقانی .</font><br>من قرین گنج و اینان خاک بیزان هوس <br>من چراغ عقل و آنان روزکوران هوا.<br> <font color=\"Red\">خاقانی .</font><br>مرا ذخیره همین یک رشید بود از عمر<br>نتیجه ٔ شب و روزی که در هوس بگذشت .<br> <font color=\"Red\">خاقانی .</font><br> <BR><font color=\"Blue\">◄</font> دیوانه شدن . عشق مفرط داشتن .<br>- <span class=\"hlight\">به هوس آمدن </span> ؛ هوس کردن و خواستن چیزی از روی تمایل نفسانی . خواستن چیزی را که ضرورت ندارد.<br>- <span class=\"hlight\">به هوس آوردن </span> ؛ هوس و میل چیزی رادر دیگری پدیدار کردن . به هوس انداختن .<br>- <span class=\"hlight\">به هوس افتادن </span> ؛ هوس کردن .<br>- <span class=\"hlight\">به هوس انداختن </span> ؛ به هوس آوردن .<br>- <span class=\"hlight\">صاحب هوس </span> ؛ کسی که هوسی دارد و خواهش نفسانی در او بیدار شده است <span class=\"hlight\">:</span> <br>اینجا شکری هست که چندین مگسان اند<br>یا بوالعجبی کاین همه صاحب هوسانند.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هوس آمدن کسی را</span> ؛ به هوس افتادن . هوس کردن <span class=\"hlight\">:</span> <br>مرا چو آرزوی روی آن نگار آید<br>چو بلبلم هوس ناله های زار آید.<br> <font color=\"Red\">سعدی .</font><br>ترکیب ها:<br>- <span class=\"hlight\">هوس آباد</span> . هوس آمدن . هوسانه . هوس انگیز. هوس باختن . هوس باز. هوس بازی . هوس بردن . هوس پختن . هوس پیرای . هوس پیشه . هوس جفت . هوس خانه . هوس داشتن . هوس ران . هوس رانی . هوس رسیده . هوسکاری . هوس کردن . هوس گویی . هوسناک . هوسناکی . هوسنامه . رجوع به هریک از این مدخل ها شود.<br></font></div>'),
(269030, 'هوس', '<span class=\"hlight\">هوس .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) نوعی از رفتار که بر زمین تکیه کنان روند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نرم راندن . (تاج المصادر). <BR><font color=\"Blue\">◄</font> کوفتن . (منتهی الارب ) (دهار) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شکستن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> به شب گشتن . (منتهی الارب ). به شب گردیدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> نیک خوردن . (تاج المصادر) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخت خوردن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تباهی کردن گرگ در گله . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرد گردیدن . (منتهی الارب ). در گرد چیزی گردیدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رفتن بر زمین به اعتمادی سخت . (از اقرب الموارد).<br></font></div>'),
(269031, 'هوس', '<span class=\"hlight\">هوس .</span> <font color=\"DarkGreen\"><b>[ هََ وِ ]</font></b> (ع ص ) گشن تیزشهوت . (منتهی الارب ).<br></font></div>'),
(269032, 'هوس', '<span class=\"hlight\">هوس .</span> (اِ) هوا و هوس باشد. (برهان ) <span class=\"hlight\">:</span> <br>در قدح کن ز حلق بط خونی <br>همچو روی تذرو و چشم خروس <br>رزم بر بزم اختیار مکن <br>هست ما را به خود هزاران هوس .<br><font color=\"Red\">ابن یمین .</font><br></font></div>'),
(269033, 'هوس', '<span class=\"hlight\">هوس .</span> (اِخ ) ژان . از روحانیان چک، متولد <span class=\"hlight\" dir=\"rtl\">١٣٦٨</span> و محروق در <span class=\"hlight\" dir=\"rtl\">١٤١٥</span> م . رجوع به ژان هوس شود.<br></font></div>'),
(269034, 'هوس', '<span class=\"hlight\">هوس .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (اِخ ) دهی است از بخش فریمان شهرستان مشهد. دارای <span class=\"hlight\" dir=\"rtl\">٣٩٠</span> تن سکنه، آب آن از قنات و محصول عمده اش غله، میوه و چغندر است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(269035, 'هوس انگیز', '<span class=\"hlight\">هوس انگیز.</span> <font color=\"DarkGreen\"><b>[ هََ وَ اَ ]</font></b> (نف مرکب ) آنچه یا آنکه در آدمی هوسی پدید آرد. موجب هوس . مشهی .<br></font></div>'),
(269036, 'هوس انگیزی', '<span class=\"hlight\">هوس انگیزی .</span> <font color=\"DarkGreen\"><b>[ هََ وَ اَ ]</font></b> (حامص مرکب ) حالت و عمل هوس انگیز.<br></font></div>'),
(269037, 'هوس باختن', '<span class=\"hlight\">هوس باختن .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ت َ ]</font></b> (مص مرکب ) هوس بازی کردن . در پی هوس رفتن <span class=\"hlight\">:</span> <br>هیچکس عیب هوس باختن ما نکند<br>مگر آن کس که به دام هوسی افتاده ست .<br> <font color=\"Red\">سعدی .</font><br>نشاید هوس باختن با گلی <br>که هر بامدادش بود بلبلی .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(269038, 'هوس باز', '<span class=\"hlight\">هوس باز.</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (نف مرکب ) آنکه در پی هوس رود. هواپرست . (آنندراج ). که هوس باختن خواهد <span class=\"hlight\">:</span> هرزه گردی بی نماز، هواپرست هوس باز.(گلستان ). ضغرس ؛ مرد آزمند هوس باز. (منتهی الارب ).<br></font></div>'),
(269039, 'هوس بازی', '<span class=\"hlight\">هوس بازی .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (حامص مرکب ) در پی هوس رفتن . هوس باختن <span class=\"hlight\">:</span> <br>ببایدهوس کردن از سر به در<br>که دور هوس بازی آمد به سر.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(269040, 'هوس بردن', '<span class=\"hlight\">هوس بردن .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ب ُ دَ ]</font></b> (مص مرکب ) هوس داشتن . خواستن <span class=\"hlight\">:</span> <br>هوس تو هیچ طبعی نبرد که سر نبازد<br>ز پی تو هیچ مرغی نپرد که پر نریزد.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(269041, 'هوس جفت', '<span class=\"hlight\">هوس جفت .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ج ُ ]</font></b> (ص مرکب ) آنکه با هوس جفت و همراه باشد. هوسناک . پرهوس <span class=\"hlight\">:</span> <br>پرستار تو شیرین هوس جفت <br>به لفظ من شهنشه را چنین گفت .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(269042, 'هوس داشتن', '<span class=\"hlight\">هوس داشتن .</span> <font color=\"DarkGreen\"><b>[ هََوَ ت َ ]</font></b> (مص مرکب ) هوس پختن . هوس کردن <span class=\"hlight\">:</span> <br>تا تو بازآمدی ای مونس جان از در غیب <br>هرکه در سر هوسی داشت از آن بازآمد.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(269043, 'هوس ران', '<span class=\"hlight\">هوس ران .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (نف مرکب ) آنکه در پی هوس باشد و بدنبال هوس برود.<br></font></div>'),
(269044, 'هوس راندن', '<span class=\"hlight\">هوس راندن .</span> <font color=\"DarkGreen\"><b>[ هََ وَدَ ]</font></b> (مص مرکب ) هوس باختن . شهوت راندن <span class=\"hlight\">:</span> <br>مگر روزگاری هوس راندمی <br>ز خود گرد محنت بیفشاندمی .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(269045, 'هوس رانی', '<span class=\"hlight\">هوس رانی .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (حامص مرکب ) دنبال هوس رفتن . کار هوس ران .<br></font></div>'),
(269046, 'هوس رسیده', '<span class=\"hlight\">هوس رسیده .</span><font color=\"DarkGreen\"><b>[ هََ وَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) آنکه در هوس باشد. آنکه هوس او برانگیخته شده باشد <span class=\"hlight\">:</span> <br>هر جا که هوس رسیده ای بود<br>تا دیده بر او نزد، نیاسود.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(269047, 'هوس شدن', '<span class=\"hlight\">هوس شدن .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ش ُ دَ ]</font></b> (مص مرکب ) به هوس آمدن . آرزو و خواهانی یافتن <span class=\"hlight\">:</span> <br>طبع تو را تا هوس نحو شد<br>صورت علم از دل ما محو شد.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(269048, 'هوس پختن', '<span class=\"hlight\">هوس پختن .</span> <font color=\"DarkGreen\"><b>[ هََ وَ پ ُ ت َ]</font></b> (مص مرکب ) به فکر هوس رانی بودن . هوس کردن <span class=\"hlight\">:</span> هر دم هوسی پزد و هر لحظه رایی زند. (گلستان ).<br>وان دگرپخت همچنان هوسی <br>این عمارت به سر نبرد کسی .<br><font color=\"Red\">سعدی .</font><br>هوس پختن از کودک ناتمام <br>چنان زشت نبود که از پیر خام .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هوس خام پختن </span> ؛ آرزوی چیزی برنیامدنی داشتن .<br></font></div>'),
(269049, 'هوس کاری', '<span class=\"hlight\">هوس کاری .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (حامص مرکب ) در پی هوس بودن <span class=\"hlight\">:</span> <br>هوس کاری آن فرهاد مسکین <br>نشان جوی شیر و قصرشیرین .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(269050, 'هوس کردن', '<span class=\"hlight\">هوس کردن .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ک َ دَ ]</font></b> (مص مرکب ) هوس داشتن . در هوس افتادن . خواستن . خواهانی و آرزو کردن <span class=\"hlight\">:</span> <br>چنان به پای تو در مردن آرزومندم <br>که زندگانی خویشم چنان هوس نکند.<br> <font color=\"Red\">سعدی .</font><br>هوس کرده بودم که کرمان خورم <br>به آخر بخوردند کرمان سرم .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(269051, 'هوس کیش', '<span class=\"hlight\">هوس کیش .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (ص مرکب ) که تبعیت از خواست دل و خواهانی گذرا دارد.<br></font></div>'),
(269052, 'هوس گوی', '<span class=\"hlight\">هوس گوی .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (نف مرکب )سوفسطایی . اهل سفسطه . (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>شراب حکمت شرعی خورید اندر حریم دین <br>که محرومند ازاین عشرت هوس گویان یونانی .<br><font color=\"Red\">سنائی .</font><br></font></div>'),
(269053, 'هوس گویی', '<span class=\"hlight\">هوس گویی .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (حامص مرکب ) سفسطه .<br></font></div>'),
(269054, 'هوسانه', '<span class=\"hlight\">هوسانه .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) آنچه پزند زن آبستن را به خواهش او. طعام که کسان برای زن آبستن یا ناقهی فرستند مربوط به هوس . آنچه از خوردنی یا میوه که برای بیمار شفایافته یا زن باردار به گاه ویار او برایش بفرستند. ویارانه . (از یادداشتهای مؤلف ). وحام . وحم .<br></font></div>'),
(269055, 'هوسرب', '<span class=\"hlight\">هوسرب .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِ) به لغت زند و پازند به معنی نیک نامی و نام نیک باشد. (برهان ). قرائتی است از کلمه ٔ پهلوی هوسرو به معنی نیک شهرت . (از حاشیه ٔ برهان چ معین ).<br></font></div>'),
(269056, 'هوسم', '<span class=\"hlight\">هوسم .</span> <font color=\"DarkGreen\"><b>[ هََ س َ ]</font></b> (اِخ ) ناحیتی است خرد به دیلمان از دیلم خاصه . (حدود العالم ). از نواحی بلادجبل در پشت طبرستان و دیلم . (معجم البلدان ). نام ولایتی است از مازندران مشهور به رودسر. (انجمن آرا).<br></font></div>'),
(269057, 'هوسمند', '<span class=\"hlight\">هوسمند.</span> <font color=\"DarkGreen\"><b>[ هََ وَ م َ ]</font></b> (ص مرکب ) صاحب هوس .<br></font></div>'),
(269058, 'هوسمندی', '<span class=\"hlight\">هوسمندی .</span> <font color=\"DarkGreen\"><b>[ هََ وَ م َ ]</font></b> (حامص مرکب ) هوسناکی . هوس داری .<br></font></div>'),
(269059, 'هوسناک', '<span class=\"hlight\">هوسناک .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (ص مرکب ) بوالهوس . باهوس .هوسمند. خواهشمند و آرزومند. (آنندراج ). آرزومند و طالب و دارای هوی و هوس . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>گفتم آه آتشین بس کن، نه من خاک توام ؟<br>نه مسلسل همچو آبم تا هوسناک توام ؟<br> <font color=\"Red\">خاقانی .</font><br>به نادیده دیدن هوسناک بود<br>به هر جا که شد چست و چالاک بود.<br> <font color=\"Red\">نظامی .</font><br>در عالم عشق گشته چالاک <br>در خواندن شعرها هوسناک .<br> <font color=\"Red\">نظامی .</font><br>شنیدم کزپی یاری هوسناک <br>به ماتم نوبتی زد بر سر خاک .<br> <font color=\"Red\">نظامی .</font><br>چون ز پی دانه هوسناک شد<br>مقطعاین مزرعه ٔ خاک شد.<br> <font color=\"Red\">نظامی .</font><br>عجب از طبع هوسناک منت می آید<br>من خود از مردم بی طبع عجب می مانم .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(269060, 'هوسک', '<span class=\"hlight\">هوسک .</span> <font color=\"DarkGreen\"><b>[ هََ وَ س َ ]</font></b>(اِ مصغر) رجاء. رجی . میل کاذب . (یادداشت مؤلف ).<br></font></div>'),
(269061, 'هوش', '<span class=\"hlight\">هوش .</span><font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (ع مص ) مضطرب گردیدن . <BR><font color=\"Blue\">◄</font> خردشکم گشتن از لاغری . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269062, 'هوش', '<span class=\"hlight\">هوش .</span> (اِ) زیرکی و آگاهی و شعور و عقل و فهم و فراست را گویند. (برهان ). و خودداری و احساس و تمییز <span class=\"hlight\">:</span> <br>برفتش دک و هوش وز پشت زین <br>فکند از برش خویشتن بر زمین .<br> <font color=\"Red\">دقیقی .</font><br>بشد هوش از آن چار خورشیدچهر<br>خروشان شدند از غم و درد مهر.<br> <font color=\"Red\">فردوسی .</font><br>برآورد بانگ غریو و خروش <br>زمان تا زمان زو همی رفت هوش .<br> <font color=\"Red\">فردوسی .</font><br>شب و روز روشن روانش تویی <br>دل و جان و هوش و توانش تویی .<br> <font color=\"Red\">فردوسی .</font><br>در دل بجای عقلی در تن بجای جانی <br>در سر بجای هوشی در چشم روشنایی .<br> <font color=\"Red\">فرخی .</font><br>بردند به خرگاه و بخوابانیدند و هوش از وی بشد. (تاریخ بیهقی ).<br>این یکی دیو است بی تمییز و هوش <br>خیر کی بیند ز بی هش هوشمند؟<br> <font color=\"Red\">ناصرخسرو.</font><br>در حال به گوش هوش من گفت <br>وصف تو که با ضمیر شد ضم .<br> <font color=\"Red\">خاقانی .</font><br>به گوش هوش من آید ندای اهل بهشت <br>نصیب نفس من آید نویدملک بقا.<br> <font color=\"Red\">خاقانی .</font><br>پنبه درآگنده چوگل گوش تو<br>نرگس چشم آبله ٔ هوش تو.<br> <font color=\"Red\">نظامی .</font><br>دوش مرغی به صبح می نالید<br>عقل و صبرم ببرد و طاقت و هوش .<br> <font color=\"Red\">سعدی .</font><br>هرچه رسد پرخردان را به گوش <br>زود گمارند بر او چشم هوش .<br> <font color=\"Red\">امیرخسرو.</font><br>- <span class=\"hlight\">آشفته هوش </span> ؛ آنکه عقل و ذهن و فهم او پریشان باشد. پریشان خاطر <span class=\"hlight\">:</span> <br>بدو گفتم ای یار آشفته هوش <br>شگفت آمد این داستانم به گوش .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">از هوش بردن </span> ؛ بیخود کردن . بیهوش کردن . (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>گر از این دست زند مطرب مجلس ره عشق <br>شعرحافظ ببرد وقت سماع از هوشم .<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">از هوش بشدن </span> ؛ غشی کردن . (یادداشت مؤلف ). از حال رفتن <span class=\"hlight\">:</span> بگریست، گریستنی سخت چنان که از هوش بشد و ما پنداشتیم که بمرد. (تاریخ بیهقی ).<br>- <span class=\"hlight\">از هوش رفتن </span> ؛ از هوش بشدن . از حال رفتن <span class=\"hlight\">:</span> <br>شبانروز مادر ز می خفته بود<br>ز می خفته و دل ز هش رفته بود.<br> <font color=\"Red\">فردوسی .</font><br>زآن رفتن و آمدن چه گویم <br>می آیی و می روم من از هوش .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">با فر و هوش </span> ؛ باهوش . هوشمند <span class=\"hlight\">:</span> <br>منادی گری برکشیدی خروش <br>که ای نامداران با فر و هوش .<br> <font color=\"Red\">فردوسی .</font><br>- <span class=\"hlight\">باهوش </span> ؛ آنکه هوش و خرد و شعور دارد <span class=\"hlight\">:</span> <br>نمیدانم آن شب که چون روز شد<br>کسی بازداندکه باهوش بد.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">با هوش آمدن </span> ؛ به هوش آمدن . حال ازدست رفته را بازیافتن <span class=\"hlight\">:</span> <br>نشانی زآن پری تا در خیال است <br>نیاید هرگز این دیوانه با هوش .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">بهوش </span> ؛ باهوش .هوشمند <span class=\"hlight\">:</span> <br>گویند مرا صواب رایان بهوش <br>چون دست نمیرسد به خرسندی کوش .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">به هوش آمدن </span> ؛ با هوش آمدن . هوشیار شدن <span class=\"hlight\">:</span> بخفت و تا دیگر روز به هوش نیامد، چون به هوش آمد پیش ملک آوردندش . (نوروزنامه ).<br>شه از مستی غفلت آمد به هوش <br>به گوشش فروکوفت فرخ سروش .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">به هوش بازآمدن </span> ؛ به هوش آمدن <span class=\"hlight\">:</span> <br>مطرب اگر پرده از این ره زند<br>بازنیایند حریفان به هوش .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">بیدارهوش </span> ؛ آنکه هوش و خرد او کامل باشد و خوب کار کند <span class=\"hlight\">:</span> <br>جهاندیده پیران بیدارهوش .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">بیهوش </span> ؛ ازهوش رفته . بی حال <span class=\"hlight\">:</span> <br>تا بود بار غمت بر دل بیهوش مرا<br>سوز عشقت ننشاند جگر از جوش مرا.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">بیهوشی </span> ؛ ازهوش رفتگی . حالتی که در آن عقل و شعور و اراده کار نکند <span class=\"hlight\">:</span> <br>کسی را در این بزم ساغر دهند<br>که داروی بیهوشی اش دردهند.<br> <font color=\"Red\">سعدی .</font><br>- <BR><font color=\"Blue\">◄</font> دارویی که سبب حالت بیهوشی شود<span class=\"hlight\">:</span> <br>جرعه ای خوردیم و کار از دست رفت <br>تا چه بیهوشی که در می کرده اند؟<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">پراگنده هوش </span> ؛ آنکه هوش و عقل او پراگنده باشد. آشفته هوش <span class=\"hlight\">:</span> <br>پریشیده عقل و پراگنده هوش <br>زقول نصیحت گر آگنده گوش .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">تیزهوش </span> ؛ بیدارهوش . که عقل و هوش او خوب و سریع کار کند <span class=\"hlight\">:</span> <br>همه ساله شهزاده ٔ تیزهوش <br>بجز علم را ره ندادی به گوش .<br> <font color=\"Red\">نظامی .</font><br>از آن روشنی مردم تیزهوش <br>پر از لعل و پیروزه کردند گوش .<br> <font color=\"Red\">نظامی .</font><br>چو دانست استادکآن تیزهوش <br>به شهوت پرستی برآورد جوش .<br> <font color=\"Red\">نظامی .</font><br>چنین گفت بیننده ٔ تیزهوش <br>چو فریاد و زاری رسیدش به گوش .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">جمشیدهوش </span> ؛ آنکه هوش او چون جمشید و دیگر بزرگان باشد <span class=\"hlight\">:</span> <br>که چون کرد سالار جمشیدهوش <br>میی چند بر یاد نوشابه نوش .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">مرد هوش </span> ؛ هوشیار. هوشمند <span class=\"hlight\">:</span> <br>ز گفتار او تیز شد مرد هوش <br>بجست و گرفتش یکایک دو گوش .<br> <font color=\"Red\">فردوسی .</font><br>ترکیب ها:<br>- <span class=\"hlight\">هوش آباد</span> . هوش بر. هوش بند. هوش دادن . هوش داشتن . هوش ربا. هوش زدا. هوشمند. هوشوار. هوشیار. رجوع به هریک از این مدخل ها شود.<br> <BR><font color=\"Blue\">◄</font> روح و جان و دل . (برهان ) <span class=\"hlight\">:</span> <br>هوش من آن بسان نوش تو بود<br>تا شدی دور من شدم مدهوش .<br> <font color=\"Red\">ابوالمثل .</font><br>کشنده بدو گفت ما هوش خویش <br>نهادیم ناچاربر دوش خویش .<br> <font color=\"Red\">فردوسی .</font><br>به دست بزرگی برآیدش هوش <br>وگر خفته آید به پیشش سروش .<br> <font color=\"Red\">فردوسی .</font><br>نخواهد می اگرچه نوش باشد<br>کجا در نوش وی را هوش باشد.<br> <font color=\"Red\">فخرالدین اسعد.</font><br>تا ز دل نعره زد سیاست تو<br>فتنه را هیچ هوش در تن نیست .<br> <font color=\"Red\">مسعودسعد.</font><br>دلم از راه گوش بیرون شد<br>بیم آن بر که هوش می بشود.<br> <font color=\"Red\">خاقانی .</font><br> <BR><font color=\"Blue\">◄</font> مرگ و هلاکت . (برهان ). منیه و مرگ . هلاک <span class=\"hlight\">:</span> <br>بگویید هوشت فرازآمده ست <br>به خون و به خاکت نیاز آمده ست .<br> <font color=\"Red\">دقیقی .</font><br>کجا هوش ضحاک بر دست توست <br>گشاده جهان ازکمر بست توست .<br> <font color=\"Red\">فردوسی .</font><br>گر آید مرا هوش بر دست اوست <br>نه دشمن ز من بازدارد نه دوست .<br> <font color=\"Red\">فردوسی .</font><br>ورا هوش در زابلستان بود<br>به دست تهم پور دستان بود.<br> <font color=\"Red\">فردوسی .</font><br>به جان من که گر آید مرا هوش <br>بود چون زندگانی بر دلم نوش .<br> <font color=\"Red\">فخرالدین اسعد.</font><br> <BR><font color=\"Blue\">◄</font> زهر قاتل را نیز گویند. (برهان ) <span class=\"hlight\">:</span> <br>گر از دست تو جام هوش گیرم <br>چنان دانم که جام نوش گیرم .<br> <font color=\"Red\">فخرالدین اسعد.</font><br>چرا با من به تلخی همچو هوشی <br>چو با هرکس به شیرینی چو نوشی .<br><font color=\"Red\">فخرالدین اسعد.</font><br></font></div>'),
(269063, 'هوش', '<span class=\"hlight\">هوش .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ]</font></b> (اِ) کر و فر و خودنمایی . (برهان ). جهانگیری و رشیدی به این معنی آورده اند و ظاهراً مصحف بوش است . (از حاشیه ٔ برهان چ معین ).<br></font></div>'),
(269064, 'هوش', '<span class=\"hlight\">هوش .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) آمیختن و پریشان شدن قوم و فتنه افتادن میان ایشان . (اقرب الموارد). درآمیخته شدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> از حرام جمع کردن مال . <BR><font color=\"Blue\">◄</font> سبک شدن و برخاستن اهل حرب یکی بر دیگری . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) عدد بسیار.<br>- <span class=\"hlight\">هوش هائش </span> ؛ مبالغه است . (منتهی الارب ).<br></font></div>'),
(269065, 'هوش', '<span class=\"hlight\">هوش .</span> (اِخ ) دهی است از بخش الیگودرز شهرستان بروجرد. دارای <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه، آب آن از چشمه و قنات و محصول عمده اش غله، لبنیات و کار دستی مردم آنجا جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269066, 'هوش', '<span class=\"hlight\">هوش .</span> (اِخ ) دهی است از دهستان خرم رود شهرستان تویسرکان . دارای <span class=\"hlight\" dir=\"rtl\">٣٥٩</span> تن سکنه، آب آن از قنات و خرم رود و محصول عمده اش غله، توتون، لبنیات و چوب قلمستان است . کار دستی زنان آنجا قالی بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269067, 'هوش آباد', '<span class=\"hlight\">هوش آباد.</span> (اِ مرکب ) به معنی آسمان است که محل عقل و روح باشد. (انجمن آرا).<br></font></div>'),
(269068, 'هوش بر', '<span class=\"hlight\">هوش بر.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (نف مرکب ) بَرنده ٔ هوش . (لغات شاهنامه ) <span class=\"hlight\">:</span> <br>بفرمود تا داروی هوش بر<br>پرستنده آمیخت با نوش بر.<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(269069, 'هوش بردن', '<span class=\"hlight\">هوش بردن .</span> <font color=\"DarkGreen\"><b>[ ب ُ دَ ]</font></b> (مص مرکب ) کسی را بیهوش کردن <span class=\"hlight\">:</span> <br>ساقیان لاابالی در طواف <br>هوش میخواران مجلس برده اند.<br> <font color=\"Red\">سعدی .</font><br>من نه آن صورت پرستم کز تمنای تو مستم <br>هوش من دانی که برده ست آنکه صورت می نگارد.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(269070, 'هوش بند', '<span class=\"hlight\">هوش بند.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (نف مرکب ) آنچه مانع به کار افتادن هوش و خرد باشد <span class=\"hlight\">:</span> <br>چشم بند است ای عجب یا هوش بند<br>چون نسوزاند چنین شعله ی ْ بلند.<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(269071, 'هوش دادن', '<span class=\"hlight\">هوش دادن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص مرکب ) هوش و خرد خود را متوجه چیزی کردن <span class=\"hlight\">:</span> <br>سخن می گفت و شیرین هوش داده <br>بدان گفتار شیرین گوش داده .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(269072, 'هوش داشتن', '<span class=\"hlight\">هوش داشتن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص مرکب ) باهوش بودن . هشیار بودن <span class=\"hlight\">:</span> <br>نه مطرب که آواز پای ستور<br>سماع است اگر ذوق داری و هوش .<br> <font color=\"Red\">سعدی .</font><br>یکی گفت : هیچ این پسر عقل و هوش <br>ندارد بمالش به تعلیم گوش .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> هوش خودرا متوجه چیزی کردن <span class=\"hlight\">:</span> <br>گفتگویی ظاهر آمد چون غبار<br>مدتی خاموش کن، هین هوش دار.<br> <font color=\"Red\">مولوی .</font><br>سوی قصه گفتنش می داد گوش <br>سوی نبض و جستنش می داشت هوش .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(269073, 'هوش ربا', '<span class=\"hlight\">هوش ربا.</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (نف مرکب ) رباینده ٔ هوش . رجوع به هوش ربای شود.<br></font></div>'),
(269074, 'هوش ربای', '<span class=\"hlight\">هوش ربای .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (نف مرکب ) آن که هوش از سر ببرد. بیهوش کننده <span class=\"hlight\">:</span> <br>گشته صریر کلک تو فتنه نشان مملکت <br>بوده خروش کوس تو هوش ربای معرکه .<br><font color=\"Red\">سلمان ساوجی .</font><br></font></div>'),
(269075, 'هوش ربایی', '<span class=\"hlight\">هوش ربایی .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (حامص مرکب ) عمل هوش ربا.<br></font></div>'),
(269076, 'هوش رفته', '<span class=\"hlight\">هوش رفته .</span> <font color=\"DarkGreen\"><b>[ رَ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف مرکب ) بیهوش . ازهوش شده . مقابل بهوش <span class=\"hlight\">:</span> <br>هوش رفته چو هوش یافته شد<br>سرش از تاب شرم تافته شد.<br><font color=\"Red\">نظامی .</font><br>چون ز گرمی گرفت مغزش جوش <br>در تن هوش رفته آمد هوش .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(269077, 'هوش زدا', '<span class=\"hlight\">هوش زدا.</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ <span class=\"hlight\" dir=\"rtl\">/</span> زُ ]</font></b> (نف مرکب ) زداینده ٔ هوش . رجوع به هوش زدای شود.<br></font></div>'),
(269078, 'هوش زدای', '<span class=\"hlight\">هوش زدای .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ <span class=\"hlight\" dir=\"rtl\">/</span> زُ ]</font></b> (نف مرکب ) محوکننده و ازمیان برنده ٔ هوش . برنده ٔ هوش . <BR><font color=\"Blue\">◄</font> شراب است که زداینده ٔ هوش است . (از انجمن آرا) (از آنندراج ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(269079, 'هوش و بوش', '<span class=\"hlight\">هوش و بوش .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ش ُ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> بُو ]</font></b> (اِ مرکب، از اتباع ) در تداول، هیاهو. اشتلم . (یادداشت مؤلف ). سعی و کوشش .<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">با اینهمه هوش و بوشت </span> <br>پاشنه نداره کوشت <font color=\"DarkGreen\"><b>[ کفشت ]</font></b> .<br></font></div>'),
(269080, 'هوش و هنگ', '<span class=\"hlight\">هوش و هنگ .</span> <font color=\"DarkGreen\"><b>[ ش ُ هََ ]</font></b> (ترکیب عطفی، اِ مرکب ) زیرکی و آگاهی و فراست و دانایی و هشیاری <span class=\"hlight\">:</span> <br>ما را به هوش و هنگ ز دوزخ نجات نیست <br>وز بیم آن نهنگ نه هوشستمان نه هنگ .<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(269081, 'هوش و گوش', '<span class=\"hlight\">هوش و گوش .</span> <font color=\"DarkGreen\"><b>[ ش ُ ]</font></b> (ترکیب عطفی، اِ مرکب ) هوش و حواس .<br>- <span class=\"hlight\">هوش و گوش کسی باز بودن </span> ؛ خوب توجه داشتن . نیک متوجه بودن .<br></font></div>'),
(269082, 'هوش وار', '<span class=\"hlight\">هوش وار.</span> (ص مرکب ) همانند هوش . چون هوش .<br></font></div>'),
(269083, 'هوش واژن', '<span class=\"hlight\">هوش واژن .</span> <font color=\"DarkGreen\"><b>[ ژَ ]</font></b> (اِمرکب ) به معنی صحو است که هشیار شدن باشد و به اصطلاح صوفیه صحو حالتی است میان خواب و بیداری که سالک رادر آن فیضی از عوالم فائض شده و به عالم معنی وصول یابد و بعضی از مغیبات مشاهده کند و این معنی به اختیار او نیست و موقوف است به فرودآمدن فیض و این را کشف و مشاهده گویند. (برهان ) (انجمن آرا) (آنندراج ).<br></font></div>'),
(269084, 'هوش یابنده', '<span class=\"hlight\">هوش یابنده .</span> <font color=\"DarkGreen\"><b>[ ب َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b>(نف مرکب ) بازیابنده ٔ هوش . به هوش آینده <span class=\"hlight\">:</span> <br>چون ز ریحان روز تابنده <br>شد دگر بار هوش یابنده .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(269085, 'هوشا', '<span class=\"hlight\">هوشا.</span> (اِ) هوشاز. تشنگی سخت بهایم را گویند. (یادداشت مؤلف ). رجوع به هوشاز شود.<br></font></div>'),
(269086, 'هوشات', '<span class=\"hlight\">هوشات .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (ع اِ) ج ِ هوشة. (اقرب الموارد). رجوع به هوشة شود.<br></font></div>'),
(269087, 'هوشاز', '<span class=\"hlight\">هوشاز.</span> (اِ) تشنگی بهایم که به غایت رسیده باشد. (انجمن آرا) (برهان ). جهانگیری به این معنی آورده و رشیدی علاوه بر آن مصدر هوشازیدن و نعت هوشازده را هم آورده است . (از حاشیه ٔ برهان چ معین ). و در سروری به نقل از مؤیدالفضلا هوشازیدن به معنی تشنه شدن دواب باشد و ذیل هوشاز نویسد: به معنی تشنگی بهائم باشد که به غایت رسیده باشد و در مؤیدالفضلاء هم کلمه ٔ هوشازیدن و هم هوشازده آمده است .<br></font></div>'),
(269088, 'هوشازده', '<span class=\"hlight\">هوشازده .</span> <font color=\"DarkGreen\"><b>[ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) بسیار تشنه . عطشان . (یادداشت مؤلف ). رجوع به هوشاز شود.<br></font></div>'),
(269089, 'هوشازه', '<span class=\"hlight\">هوشازه .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ) به معنی هوشاز است که تشنگی اسبان و شتران باشد. (برهان ).<br></font></div>'),
(269090, 'هوشازیدن', '<span class=\"hlight\">هوشازیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) به غایت تشنه شدن اسب و شتر و سایر حیوانات باشد. (برهان ). رجوع به هوشاز شود.<br></font></div>'),
(269091, 'هوشدیو', '<span class=\"hlight\">هوشدیو.</span> <font color=\"DarkGreen\"><b>[ وْ ]</font></b> (اِخ ) از پهلوانان ارجاسپ تورانی است که در جنگ با گشتاسپ شاه ساقه دار سپاه بوده است . (یادداشت مؤلف ). نام ترکی بوده است . (لغات شاهنامه ) <span class=\"hlight\">:</span> <br>یکی ترک بد نام او هوشدیو<br>به ساقه فرستاده ترکان خدیو.<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(269092, 'هوشع', '<span class=\"hlight\">هوشع.</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِخ ) لغةً به معنی خداوند کمک کننده است . (از قاموس کتاب مقدس ). ابن الندیم نام او را مبدل «هویعبن بثیری » یا «بسیری » ضبط کرده است . (یادداشت مؤلف ). لفظ هوشع به معنی نجات یا خلاصی به کار رفته و نام چهارمین پیامبر بنی اسرائیل است که <span class=\"hlight\" dir=\"rtl\">٦٠</span> سال نبوت داشته است . (از قاموس کتاب مقدس ). یکی از کتابهای عهد عتیق (تورات ) به نام او و از اوست . (یادداشت مؤلف ).<br></font></div>'),
(269093, 'هوشع', '<span class=\"hlight\">هوشع.</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِخ ) اسم اصلی یوشعبن نون است . (قاموس کتاب مقدس ).<br></font></div>'),
(269094, 'هوشع', '<span class=\"hlight\">هوشع.</span> <font color=\"DarkGreen\"><b>[ش َ ]</font></b> (اِخ ) پسر ایلیه و آخر ملوک اسرائیل است که نسبت به سایرین شرارتش کمتر بود. (قاموس کتاب مقدس ).<br></font></div>'),
(269095, 'هوشمند', '<span class=\"hlight\">هوشمند.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (ص مرکب ) باهوش . خداوند هوش . هوشیار. صاحب هوش . (برهان ) (انجمن آرا) <span class=\"hlight\">:</span> <br>حکیمان داننده و هوشمند<br>رسیدند نزدیک تخت بلند.<br> <font color=\"Red\">فردوسی .</font><br>به دل گفت کاین کودک هوشمند<br>به جایی رسد در بزرگی بلند.<br> <font color=\"Red\">فردوسی .</font><br>بدین دانش و این دل هوشمند<br>بدین برز و بالا و رای بلند.<br> <font color=\"Red\">فردوسی .</font><br>نگر تا خویشتن را چه پسندی <br>به هر کس آن پسند ار هوشمندی .<br> <font color=\"Red\">(ویس و رامین ).</font><br>هوشمندان به باغ دین اندر<br>ای برادر گزیده اشجارند.<br> <font color=\"Red\">ناصرخسرو.</font><br>شاد کی باشد در این زندان تاری هوشمند؟<br>یاد چون آید سرود آن را که تن داردش تب .<br> <font color=\"Red\">ناصرخسرو.</font><br>این یکی دیو است بی تمییز و هوش <br>خیرگی بیند ز بی هش هوشمند.<br> <font color=\"Red\">ناصرخسرو.</font><br>این نیست نشان هوشمندان <br>او خواه به گریه خواه خندان .<br> <font color=\"Red\">نظامی .</font><br>سخن کآن از دماغ هوشمند است <br>گر از تحت الثری آید بلنداست .<br> <font color=\"Red\">نظامی .</font><br>که من در دل آن دارم ای هوشمند<br>که آن اژدها را رسانم گزند.<br> <font color=\"Red\">نظامی .</font><br>چنین گفت فرزانه ٔ هوشمند<br>که دانا نگوید سخن ناپسند.<br> <font color=\"Red\">سعدی .</font><br>صد انداختی تیرو هر صد خطاست <br>اگر هوشمندی یک انداز و راست .<br> <font color=\"Red\">سعدی .</font><br>ندهد مرد هوشمند جواب <br>مگر آن گه کز او سؤال کنند.<br> <font color=\"Red\">سعدی .</font><br>رجوع به هوش شود.<br></font></div>'),
(269096, 'هوشمندی', '<span class=\"hlight\">هوشمندی .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (حامص مرکب ) حالت و چگونگی هوشمند. ذکاء. ذکاوت . فطانت <span class=\"hlight\">:</span> <br>جوانان ورا پاسخ آراستند<br>دل هوشمندی بپیراستند.<br> <font color=\"Red\">فردوسی .</font><br>بالای سرش ز هوشمندی <br>میتافت ستاره ٔ بلندی .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(269097, 'هوشنگ', '<span class=\"hlight\">هوشنگ .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِخ ) آلب خان بن دلاور، دومین از غوریان مالوه ٔ هند از <span class=\"hlight\" dir=\"rtl\">٨٠٨</span> تا <span class=\"hlight\" dir=\"rtl\">٨٣٨</span> هَ . ق . (ترجمه ٔ طبقات سلاطین اسلام ).<br></font></div>'),
(269098, 'هوشنگ', '<span class=\"hlight\">هوشنگ .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِ) به معنی امر اول باشد و هوش و آگاهی و عقل و خرد را نیز گویند. (برهان ).<br></font></div>'),
(269099, 'هوشنگ', '<span class=\"hlight\">هوشنگ .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِخ ) پسر سیامک . نام فرزند چهارم آدم علیه السلام است که یکی از سلاطین پیشدادی بود. گویند آتش و آهن در زمان او به هم رسید وآلات زراعت کردن ساخت و جویها روان کرد و شهر و عمارت بنا نهاد و شیاطین را از مخالطت آدمیان دور گردانید. و بعضی گویند ارفخشدبن سام اوست و پیغمبر است و کتاب جاویدان خرد که به جاوید نام اشتهار دارد از او یادگار مانده است . (برهان ). قسمتی از گفته ٔ صاحب برهان بر اساسی نیست . رجوع به هوشنگ فرزند سیامک شود.<br></font></div>'),
(269100, 'هوشنگ', '<span class=\"hlight\">هوشنگ .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِخ ) دومین پادشاه پیشدادی پسر سیامک بن کیومرز بوده و بعضی نسبت او را چنین تحقیق کرده اند: هوشنگ بن فردادبن سیامک بن میشی بن کیومرز. وی بعد از کیومرز پادشاه شد و از دیماوند که مکان کیومرز بود به پارس رفته در استخر آرامگاه گزید. بنابراین آن زمین را بوم شاه نام نهادند. او پادشاهی دانا و بینا و یزدان ستای و عادل بوده و او را پارسیان پیغمبر بزرگ شمارند و گویند بر وی کتاب آسمانی نازل شده و آن مشتمل بر سی وهشت آیه بوده و ساسان پنجم بعد از او آن را ترجمه کرده و داخل کتب پیغمبران بعد از مه آباد و دساتیر اینک حاضر است و مجمع آن نامها است . و گویند فارس نام پسری داشته که زبان فارسی ملک فارس منسوب بدو است . تصرفات و اختراعات بسیار از او نوشته اند و کلمات حکمت از او نقل کرده اند و شهر سوس و کوفه را از بناهای او دانسته اند. ازهنگام وفات کیومرز تا هوشنگ دویست وبیست وسه سال فاصله بوده و پانصد سال او عمر نموده و کتاب جاودان خرد از تألیفات او است که در حکمت عملی نگاشته . گنجوربن اسفندیار که از سلاطین عجم است آن را از فارسی قدیم به زبان متداول ترجمه نموده، حسن بن سهل برادر فضل ذوالریاستین وزیر مأمون عباسی آن را به زبان عرب نقل نموده و استاد ابوعلی مسکویه به الحاق حکمت های فرس وهند و روم و عرب آن را انجام داد. و آن کتاب را هوشنگ شاه برای پند و اندرز پسر خود و ملوک آینده مرقوم نموده بود و در بعضی تواریخ برخی از آن ثبت است . کتب هوشنگ متعدد بوده است . در زمان خلافت عمربن خطاب به حکم او کتب ایران همه سوختند و از کتاب وی چند ورق به دست شهاب الدین مقتول افتاده بود و بدان عمل مینمود. چون بر انوشیروان عادل معلوم شد که عرب بر عجم غلبه خواهند جست، جاویدان خرد را در جوف شکم آهویی زرین نهاده در ایوان خود مدفون نموده بود و در زمان مأمون ذوبان نام هندی آن را برآورده نزد مأمون برده بعضی را به عربی ترجمه کردند و تتمه را که چهارصد ورق بود به هند برده قدردانان ضبط و ترجمه کردند و به دیگران نشر نمودند. مدت پادشاهی او را چهل سال گفته اند. (انجمن آرا). در داستان ملی ما هوشنگ دومین پادشاه ایران است که پس از کیومرث به پادشاهی هفت کشور نشست . پدرش سیامک در جنگ با دیوان کشته شد و هوشنگ انتقام پدر را از دیوان گرفت و آنگاه که کیومرث رخت از جهان بربست او بجای نیا به فرمانروایی نشست و چهل سال سلطنت راند و آهن و آتش را کشف کرد و جشن سده را آئین نهاد و آب از دریاها برآورد و در جویها روان ساخت و کشاورزی و به دست آوردن پوشیدنیها را از پوست حیوانات به مردم آموخت، اما در اوستا هوشنگ پهلوان بزرگ ومرد پارسای مقدسی است که نامش هئوشینگهه و نزدیک به تمام موارد ملقب به پَرَذات َ است . این کلمه ممکن است به نخستین قانون گزار یا نخستین مخلوق تعبیر شود و همین لفظ است که در پهلوی به پَشدات و در زبان دری به پیشداد مبدل شد. عنوان پیشداد در اوستا تنها خاص هوشنگ است، ولی در مآخذ پهلوی و اسلامی بر دسته ای از شاهان <font color=\"DarkGreen\"><b>[ از هوشنگ تا کیقباد ]</font></b> اطلاق میشود و یقیناً این نام را از همین لقب هوشنگ که مؤسس سلسله ٔ پیشدادی تصور میشد گرفته اند. در اوستا نام هوشنگ چندین بار آمده است و در همه ٔ آنها نام هوشنگ در مقدمه ٔ نام شاهان و پهلوانان ذکر شده مگر در فروردین یشت <font color=\"DarkGreen\"><b>[ یشت <span class=\"hlight\" dir=\"rtl\">١٣</span> ]</font></b> که در مقدمه ٔ نام پهلوانان و شاهان نام ییمه آمده و پس از آنکه از آخرین شاه یعنی کوی هوسروه (کیخسرو) یاد شد نام عده ای از پهلوانان آمده است که هوشنگ هم جزو آنان است و از این طریق باید گفت فروردین یشت وقتی نگاشته شده که هنوز نام پهلوانان و شاهان قدیم در موارد معین بعدی ثبت نشده و سلسله ٔ شاهان و پهلوانان کاملاً مرتب نگردیده بود و ازاین روی سلسله ٔ شاهان فروردین یشت اصیل تر و قدیم تر از یشت های دیگر است، یعنی این یشت خاصه قسمتهای مربوط به شاهان و پهلوانان متعلق به ازمنه ٔ بسیار قدیم و دوره ٔ نزدیک به تدوین گاتاها است . در جزو نسکهای اوستای عهد ساسانی نسکی به نام چهرداد بود که حکم تاریخ داستانی ایران قدیم را داشت و خلاصه ٔ آن در دینکرد <font color=\"DarkGreen\"><b>[ کتاب <span class=\"hlight\" dir=\"rtl\">٨</span> فصل <span class=\"hlight\" dir=\"rtl\">١٣</span> ]</font></b> نقل شد.در چهرداد نسک نسب نامه ٔ هوشنگ فرقی با بندهشن داشت، چه بنابر آنچه در چهرداد نسک آمده بود هوشنگ نواده ٔگیومرد و از فرزندان سه گانه ٔ مشیگ بود و از دو فرزند دیگر یکی ویگرد و دیگری تاز نام داشت، اما در بندهشن میان هوشنگ و گیومرد سه نسل فاصله است و به هرحال در کتاب هشتم دینکرد چنین آمده است که رسم زراعت و دهانکانیه <font color=\"DarkGreen\"><b>[ یا دهکانیه = دهقانی = اصل مالکیت ]</font></b> را وی گرد پیشداد پدید آورد و دهیوپتیه (دهوفذیه ) یعنی اصل حکومت و سلطنت را که مراد از آن حمایت و هدایت و نگاهبانی خلق است، هوشنگ پیشداد ایجاد کرد. آنچه از اوستا راجع به هوشنگ نقل شد قدیمترین احادیثی است که در این باب میان قوم ایرانی وجود داشته و تا این روزگار برجای مانده است . بر روی هم و تا آنجا که از این روایات مستفاد میشود هوشنگ پیشداد را باید چنین تعریف کرد: هئوشینگهه پرذات نخستین کسی است که به خواست اهورمزدا و امشاسپندان ویزتان بر پهنای هفت کشور سلطنت یافت و نه تنها فرمانروای آدمیان بود بلکه بر دیوان و جادوان و بدکیشان و کاویان و کرپانان هم فرمانروایی مینمود. دیوان را منکوب و مقهور کرد و کارشان را به جایی رسانید که از ترس او به تاریکیها پناه بردند. این پادشاه دو بهره از دیوان مازندرانی و بدکیشان وَرِن را بکشت و برای خداوند فرشتگان بر قله ٔ کوه مقدس هرا قربانیها کرد. هوشنگ تقریباً در همه ٔ داستانهای قدیم ایرانی جز بعض معدود نخستین شاه هفت کشور شمرده شده است، ولی بنابر بعض مآخذ اسلامی در ایران قدیم برخی چنین می پنداشتند که تَخم َاُروپ َ (تهمورث ) نخستین شاه جهان و پدیدآرنده ٔ شاهی بود و باید گفت که این سخنان و روایات لاشک اصلی قدیمتر داشته و از منابعی کهن در این آثار راه جسته بود. ریشه ٔ اوستائی نام هوشنگ <font color=\"DarkGreen\"><b>[ هئوشینگهه ]</font></b> کاملاً روشن نیست <span class=\"hlight\">:</span> <br>چهل سال با شادی و کام ساز<br>به داد و دهش بود آن سرفراز<br>زمانه ندادش هم آخر درنگ <br>شده شاه هوشنگ با هوش و هنگ .<br> <font color=\"Red\">فردوسی .</font><br>گرانمایه را نام هوشنگ بود<br>تو گفتی همه هوش و فرهنگ بود.<br> <font color=\"Red\">فردوسی .</font><br>برای تفصیل مطلب رجوع به حماسه سرائی در ایران تألیف ذبیح اﷲ صفا ص <span class=\"hlight\" dir=\"rtl\">٣٨٤</span> به بعد شود.<br></font></div>'),
(269101, 'هوشنگ دژ سلطان آباد', '<span class=\"hlight\">هوشنگ دژ سلطان آباد.</span> <font color=\"DarkGreen\"><b>[ ش َ دِ س ُ ]</font></b> (اِخ ) دهی است از دهستان پایین خواف بخش خواف شهرستان تربت حیدریه . دارای <span class=\"hlight\" dir=\"rtl\">١١٩</span> تن سکنه . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(269102, 'هوشهنج', '<span class=\"hlight\">هوشهنج .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) معرب هوشنگ است . (فارسنامه ٔ ابن بلخی ). رجوع به هوشنگ شود.<br></font></div>'),
(269103, 'هوشهنگ', '<span class=\"hlight\">هوشهنگ .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) هوشنگ . (فارسنامه ٔ ابن بلخی ). رجوع به هوشنگ شود.<br></font></div>'),
(269104, 'هوشور', '<span class=\"hlight\">هوشور.</span> <font color=\"DarkGreen\"><b>[ هوش ْ وَ ]</font></b> (ص مرکب ) صاحب هوش . هوشمند <span class=\"hlight\">:</span> <br>دو پرمایه بیداردل پهلوان <br>یکی هوشور پیر و دیگر جوان .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(269105, 'هوشک', '<span class=\"hlight\">هوشک .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِخ ) از قرای ناحیه ٔ سراوان بلوچستان . (جغرافیای سیاسی کیهان ). نام محلی کنار راه خواش وداورپناه میان کهن داود و بخشان . (یادداشت مؤلف ).<br></font></div>'),
(269106, 'هوشگان', '<span class=\"hlight\">هوشگان .</span> (اِخ ) کوهی است در مغرب چهارمحال بختیاری . (یادداشت مؤلف ).<br></font></div>'),
(269107, 'هوشگون', '<span class=\"hlight\">هوشگون .</span> <font color=\"DarkGreen\"><b>[ هََ ش ِ ]</font></b> (اِخ ) هفشه جان . (یادداشت مؤلف ).<br></font></div>'),
(269108, 'هوشیار', '<span class=\"hlight\">هوشیار.</span> <font color=\"DarkGreen\"><b>[ هوش ْ ]</font></b> (ص مرکب ) عاقل . فطن . بخرد. باهوش .خردمند. هشیار. ذکی . صاحب عقل . هوشمند <span class=\"hlight\">:</span> <br>چنین گفت با رخش کای هوشیار<br>مکن سستی اندر گه کارزار.<br> <font color=\"Red\">فردوسی .</font><br>ز فضل صاحب عباد و جود حاتم طی <br>مثل زنند حکیمان هوشیار قدیم .<br> <font color=\"Red\">سوزنی .</font><br>زنده کدام است بر هوشیار<br>آنکه بمیرد به سر کوی یار.<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> حساس . (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> آنکه مست نیست . مقابل مست . هشیار. <BR><font color=\"Blue\">◄</font> آنکه مغمی علیه نباشد <span class=\"hlight\">:</span> <br>من از رنگ صلاح آن دم به خون دل بشستم دست <br>که چشم باده پیمایش صلا بر هوشیاران زد.<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">هوشیار شدن </span> ؛ افاقه .به هوش آمدن . از حالت مستی یا غشوه بیرون شدن .<br></font></div>'),
(269109, 'هوشیارانه', '<span class=\"hlight\">هوشیارانه .</span> <font color=\"DarkGreen\"><b>[ هوش ْ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب ) همچون هوشیار. از روی کیاست و دانائی و هوشمندی .<br></font></div>'),
(269110, 'هوشیاری', '<span class=\"hlight\">هوشیاری .</span> <font color=\"DarkGreen\"><b>[ هوش ْ ]</font></b> (حامص مرکب ) فطانت . خردمندی . هوشمندی . مقابل بیهوشی . هشیاری <span class=\"hlight\">:</span> <br>ای شاعر سبکدل با من چه اوفتادت <br>پنداشتم که عقلت بیش است و هوشیاری .<br> <font color=\"Red\">منوچهری .</font><br>استن این عالم ای جان غفلت است <br>هوشیاری این جهان را آفت است .<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> حس . (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> صحو. مقابل مستی .<br></font></div>'),
(269111, 'هوشیدن', '<span class=\"hlight\">هوشیدن .</span> <font color=\"DarkGreen\"><b>[ دَ]</font></b> (مص ) تعقل کردن . (برهان ). تعقل و تفکر کردن در کاری . (آنندراج ) (انجمن آرا). <BR><font color=\"Blue\">◄</font> به زبان پهلوی خشک شدن : بهوشید؛ خشک شد. (حاشیه ٔ فرهنگ اسدی ).<br></font></div>'),
(269112, 'هوشیعانا', '<span class=\"hlight\">هوشیعانا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (به معنی تمنای اینکه خلاصی دهی ) کلمه ای بود که در زمان دخول مسیح به اورشلیم به آواز بلند گفته میشد. (قاموس کتاب مقدس ).<br></font></div>'),
(269113, 'هوع', '<span class=\"hlight\">هوع .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) قی کردن . (المصادر زوزنی ). قی کردن بی تکلف . (آنندراج ) (منتهی الارب ) (اقرب الموارد). هیعوعة. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سبک گردیدن و اندوهناک گشتن . <BR><font color=\"Blue\">◄</font> بر یکدیگر برجستن . (آنندراج ) (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آهنگ کردن قوم . (آنندراج ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِمص ) بدی آز و حرص و سختی آن . (آنندراج ) (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دشمنی . (آنندراج ).هوع . (آنندراج ). عداوت . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> قی . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269114, 'هوع', '<span class=\"hlight\">هوع .</span> (ع اِمص ) هَوع . بدی آز و حرص و سختی آن . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دشمنی . (منتهی الارب ) (آنندراج ). عداوت . (اقرب الموارد).<br></font></div>'),
(269115, 'هوغ', '<span class=\"hlight\">هوغ .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) چیز بسیار. (منتهی الارب ). و این لغت مستعمل نیست . (از اقرب الموارد).<br></font></div>'),
(269116, 'هوف', '<span class=\"hlight\">هوف .</span> (ع ص ) مرد تهی بی خیر و گول بددل .(اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) پوست بیضه مانندی . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269117, 'هوف', '<span class=\"hlight\">هوف .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هو ]</font></b> (ع اِ) خانه ٔ عنکبوت . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> باد گرم . <BR><font color=\"Blue\">◄</font> باد سرد. (مهذب الاسماء) (منتهی الارب ) (اقرب الموارد) (آنندراج ). از اضداد است . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269118, 'هوفاریقون', '<span class=\"hlight\">هوفاریقون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به لغت رومی نام دوایی است که آن را دارمی رومی گویند و آن حبی باشد سرخ به رنگ سماق بغدادی و به عربی رمان الانهار خوانند. عرق النسا را نافع است و بول وحیض را براند و آن را هیوفاریقون هم میگویند. (آنندراج ) (برهان ). هزارچشم . و رجوع به مفردات ضریر انطاکی و تحفه ٔ حکیم مؤمن و گیاه شناسی گل گلاب ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span> شود.<br></font></div>'),
(269119, 'هوفسطیداس', '<span class=\"hlight\">هوفسطیداس .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (معرب، اِ) نام عصاره ٔ لحیةالتیس است که به فارسی شنگ و به عربی اذناب الخیل خوانند. (برهان ) (آنندراج ). و رجوع به تذکره ٔ ضریر انطاکی شود.<br></font></div>'),
(269120, 'هوفقیداس', '<span class=\"hlight\">هوفقیداس .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (معرب، اِ) رستنیی باشد سرخ رنگ به سیاهی مایل و به عربی عصی الراعی گویند. داخل قابضات است و خون را ببندد. (برهان ) (آنندراج ).<br></font></div>'),
(269121, 'هوفل', '<span class=\"hlight\">هوفل .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ سوسنگرد شهرستان دشت میشان .کنار رود کرخه قرار دارد و دارای <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269122, 'هوفیلوس', '<span class=\"hlight\">هوفیلوس .</span> (معرب، اِ) گیاهی است که به فارسی آن را شنگار و به عربی حمیرا خوانند، برگ آن سیاه به سرخی مایل است، با سرکه بر بهق طلا کنند نافع باشد. آن را خس الحمار هم میگویند. (آنندراج ) (برهان ).<br></font></div>'),
(269123, 'هوق', '<span class=\"hlight\">هوق .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) ج ِ هَوقَة. (اقرب الموارد). رجوع به هوقة شود.<br></font></div>'),
(269124, 'هول', '<span class=\"hlight\">هول .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) ترس از کاری که راه آن دریافته نشود. (ازاقرب الموارد). ترس . (منتهی الارب ) (آنندراج ) (دهار)(برهان ). خوف . بیم . (برهان ). هراس . رعب . وحشت . هیبت . (آنندراج ). مخافت . (از اقرب الموارد) <span class=\"hlight\">:</span> <br>زان روز که پیش آیدت آن روز پر از هول <br>بنشین و تن اندرده و انگاره به پیش آر.<br> <font color=\"Red\">؟ (فرهنگ اسدی ).</font><br>آن روز در آن هول و فزع بر سر آن جمع<br>پیش شهدا دست من و دامن زهرا.<br> <font color=\"Red\">ناصرخسرو.</font><br>لرزان شده از ترس دم تیغ تو فغفور<br>ترسان شده از هول سر گُرز تو قیصر.<br> <font color=\"Red\">مسعودسعد.</font><br>مخور هول ابلیس تا جان دهد<br>هرآنکس که دندان دهد نان دهد.<br> <font color=\"Red\">سعدی .</font><br>چنانم ز افعال و اعمال بد<br>که از هول دل در برم می طپد.<br> <font color=\"Red\">نزاری قهستانی (از دستورنامه ).</font><br>پیاله بر کفنم بند تا سحرگه حشر<br>به می ز دل ببرم هول روز رستاخیز.<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">هول افتادن </span> ؛ بیم گرفتن . بیم زده شدن . ترسان شدن <span class=\"hlight\">:</span> <br>فلک بر سر کینه جویی است با من <br>از آن در تنم هول جان اوفتاده .<br> <font color=\"Red\">طالب آملی (از آنندراج ).</font><br>- <span class=\"hlight\">هول انگیز</span> ؛ ترس آور. باعث ترس و بیم شونده .<br>- <span class=\"hlight\">هول خوردن از</span> ؛ ترسیدن از. بیم داشتن از <span class=\"hlight\">:</span> <br>مخور هول ابلیس تا جان دهد<br>هرآنکس که دندان دهد نان دهد.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هول زدن </span> ؛ شتاب و عجله کردن در خوردن چیزی و امثال آن . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">هول شدن </span> ؛ ترسیدن . دستپاچه شدن . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">هول کردن </span> ؛ ترسیدن . دستپاچه شدن . سخت ترسیدن از چیزی بد و مانند آن نزدیک بیهوش شدن . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">هول کردن کسی را</span> ؛ او را دستپاچه کردن .<br>- <span class=\"hlight\">هَول ٌ مُهَوِّل </span>؛ تأکید است . (اقرب الموارد).<br>- <span class=\"hlight\">هول نشستن بر</span> ؛ ترس نشستن بر. (منتهی الارب ). بیم زده شدن <span class=\"hlight\">:</span> <br>چنان هول زان حال بر من نشست <br>که ترسیدنم پای رفتن ببست .<br> <font color=\"Red\">سعدی (از آنندراج ).</font><br>- <span class=\"hlight\">هول و تکان </span> ؛ ترس و هراس . ترس و لرز.<br>- <span class=\"hlight\">هول هائل </span> ؛ تأکید است چون لیل لائل . (اقرب الموارد). بیمی سخت . ترسی سخت .<br> <BR><font color=\"Blue\">◄</font> کار بیمناک که راه آن دریافته نشود. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> در تداول فارسی، حرص . شره . آز.<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">از هول حلیم تو دیگ افتادن </span> .<br> <BR><font color=\"Blue\">◄</font> (ص ) هایل . بیم آور. ترس آور <span class=\"hlight\">:</span> <br>چو کوه کوه در او موجهای تندروش <br>چو پیل پیل نهنگان هول مردمخوار.<br> <font color=\"Red\">فرخی .</font><br>جوانمردی را در جنگ تاتار جراحتی هول رسید. (گلستان ). ج، اهوال، هوول . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) گوئی که بدان طفلان بازی کنند. (آنندراج از شرح نصاب ). <BR><font color=\"Blue\">◄</font> (مص ) ترسانیدن کسی را. (منتهی الارب ) (اقرب الموارد) (دهار) (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> تهاویل و رنگهای گوناگون دیدن مست در مستی و ترسیدن از آن . <BR><font color=\"Blue\">◄</font> عجب و خودبینی داشتن زن به زیبایی خود. (از اقرب الموارد).<br></font></div>'),
(269125, 'هول', '<span class=\"hlight\">هول .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) پیکری است به شکل سر مردم نزدیک هرمان به مصر، که گویند طلسم رمل است . (منتهی الارب ).ابوالهول . (اقرب الموارد). رجوع به ابوالهول شود.<br></font></div>'),
(269126, 'هول', '<span class=\"hlight\">هول .</span> (ع ص ) ناقة هول الجنان ؛ ناقه ٔ تیزخاطر و چالاک . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269127, 'هول', '<span class=\"hlight\">هول .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو]</font></b> (ص ) راست و درست . (آنندراج ) (برهان ) <span class=\"hlight\">:</span> <br>گفت که تو زیرککی مست خیالی و شکی <br>گول شدم هول شدم وز همه برکنده شدم .<br> <font color=\"Red\">مولوی (از آنندراج و جهانگیری ).</font><br>صاحب جهانگیری بیت فوق را شاهد برای معنی درست آورده است و در انجمن آرا و آنندراج آمده : در این معنی تأمل است، چه گول ضد زیرکی است و گول شدن مناسب است ولی هول شدن به معنی درست شدن به این مقام نمیسازد و از سبک غزل مولانا دور است . <BR><font color=\"Blue\">◄</font> بلند و رفیع. (برهان ) <span class=\"hlight\">:</span> <br>چگونه هول حیوانی چو بالاور ژیان شیری <br>کجا پیل ژیان زو تا جهان باشد جهان باشد.<br><font color=\"Red\">فرخی (از آنندراج ).</font><br></font></div>'),
(269128, 'هول دادن', '<span class=\"hlight\">هول دادن .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو دَ ]</font></b> (مص مرکب ) دفعةً تکان دادن کسی را به قصد افکندن او و بیشتر از جای بلند به گودال و جایی پست، و ظاهراً این معنی بسبب بیمی که از افکندن کسی او را حاصل آیدبرخاسته است . <BR><font color=\"Blue\">◄</font> تهدید کردن . ترسانیدن .<br></font></div>'),
(269129, 'هول هولکی', '<span class=\"hlight\">هول هولکی .</span> <font color=\"DarkGreen\"><b>[ هََ هََ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> هُو هُو ل َ]</font></b> (ص نسبی، ق مرکب ) با دستپاچگی و با نهایت شتاب .<br></font></div>'),
(269130, 'هول و هراس', '<span class=\"hlight\">هول و هراس .</span> <font color=\"DarkGreen\"><b>[ هََ<span class=\"hlight\" dir=\"rtl\">/</span> هُو ل ُ هََ ]</font></b> (ترکیب عطفی، اِ مرکب ) ترس و بیم .<br>- <span class=\"hlight\">در هول و هراس بودن </span> ؛ با ترس و بیم دست به گریبان بودن .<br></font></div>'),
(269131, 'هولاجو', '<span class=\"hlight\">هولاجو.</span> (اِخ ) معرب هولاکو. رجوع به هولاکوخان شود.<br></font></div>'),
(269132, 'هولاندشت', '<span class=\"hlight\">هولاندشت .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) دهی است از دهستان ده پیر بخش حومه ٔ شهرستان خرم آباد. دارای یکصدوبیست تن سکنه . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269133, 'هولاکوخان', '<span class=\"hlight\">هولاکوخان .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) هولاؤوبن تولی بن چنگیزخان مغول، مؤسس سلسله ٔ ایلخانیان مغول در ایران و برادر کوچک منکوقاآن . از طرف برادر خود که در آن زمان بر ترکستان غربی و ایران و افغانستان و قسمتی از قفقاز فرمانروایی داشت مأمور دفع فرقه ٔ اسماعیلیه و امراء مستقل ایران گردید و به سال <span class=\"hlight\" dir=\"rtl\">٦٥١</span> هَ . ق . با <span class=\"hlight\" dir=\"rtl\">١٥٠</span> هزارتن سپاهی به ایران آمد و به سال <span class=\"hlight\" dir=\"rtl\">٦٥٤</span> قلعه ٔ الموت و سایر قلاع اسماعیلیه را گرفت و ویران کرد و تمام ذخایر اسماعیلیه به تصرف وی درآمد و به سال <span class=\"hlight\" dir=\"rtl\">٦٥٦</span> برای تسخیر بغداد حرکت کرد و آن شهر را در محاصره قرار داد. در این سفر اتابک ابوبکربن سعد اتابک فارس و خواجه نصیرالدین طوسی و عطاءالملک جوینی همراه وی بودند. مستعصم خلیفه ٔ عباسی که شکست خورده بود و قدرت پایداری نداشت با سه پسر خود و قریب سه هزار تن از بزرگان بغداد نزد هلاکو رفت . هلاکو دستور داد تمام مردم از شهر خارج شوند و همین که خارج شدند دستور داد همه را قتل عام کنند و در حدود هشتصدهزار تن کشته شدند. سپس شهربغداد را غارت کرد و خلیفه را با دو پسرش به قتل رسانید و فقط پسر کوچکش را بخشید و حکومت پانصدساله ٔ بنی عباس را منقرض کرد. سپس کوفه و نجف را گرفت و در شهر واسط چهل هزار تن را کشت . حلب و دمشق و الجزیره راهم در سالهای <span class=\"hlight\" dir=\"rtl\">٦٥٧</span> و <span class=\"hlight\" dir=\"rtl\">٦٥٨</span> هَ . ق . فتح کرد. آنگاه به آذربایجان رفت و مراغه را پایتخت خود قرار داد و خواجه نصیر طوسی را در آن شهر مأمور ساختن رصدخانه کردو خواجه به فرمان او زیج ایلخانی را ساخت . هولاکو در<span class=\"hlight\" dir=\"rtl\">٦٦٣</span> هَ . ق . در سن <span class=\"hlight\" dir=\"rtl\">٤٨</span>سالگی در آذربایجان درگذشت و جانشینان وی به نام ایلخانان، قریب یک قرن در ایران حکومت کردند. رجوع به تاریخ گزیده و حبیب السیر شود.<br></font></div>'),
(269134, 'هولة', '<span class=\"hlight\">هولة.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ع اِمص ) خویشتن بینی . (منتهی الارب ). عُجب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناز. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) زن که به شگفت اندازد از حسن خود. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) آتش که به وی سوگند خورند وآن در جاهلیت بوده است . (منتهی الارب ). آتش تهویل و آن آتشی است که در چاهی افروخته میگردید و نمک و کبریت بر آن ریخته میشد و بدان سوگند میخوردند. <BR><font color=\"Blue\">◄</font> آنچه بدان کودک را ترسانند. (اقرب الموارد).<br></font></div>'),
(269135, 'هولدانی', '<span class=\"hlight\">هولدانی .</span><font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ]</font></b> (اِ مرکب ) جای تنگ و تاریک و غیرقابل سکونت . (یادداشت مرحوم دهخدا). هلفدانی . سیاه چال .<br></font></div>'),
(269136, 'هولدرلین', '<span class=\"hlight\">هولدرلین .</span> <font color=\"DarkGreen\"><b>[ هُل ْ دِ ]</font></b> (اِخ ) فریدریش . از شاعران معروف آلمان (<span class=\"hlight\" dir=\"rtl\">١٧٧٠</span>-<span class=\"hlight\" dir=\"rtl\">١٨٤٣</span> م .). قطعات زیبایی از وی باقی مانده است . (از فرهنگ عمید).<br></font></div>'),
(269137, 'هولس', '<span class=\"hlight\">هولس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) جان که به عربی روح گویند. حرکت این کلمه نامعلوم است . (از برهان ) (آنندراج ).<br></font></div>'),
(269138, 'هولشک', '<span class=\"hlight\">هولشک .</span><font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ص ) مردم کثیف و نکبتی را گویند و شخصی که پیوسته رخت خود را ملوث گرداند. (برهان ) (آنندراج ).<br></font></div>'),
(269139, 'هولع', '<span class=\"hlight\">هولع.</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ل َ ]</font></b> (ع ص ) شتابنده . (منتهی الارب ).<br></font></div>'),
(269140, 'هولناک', '<span class=\"hlight\">هولناک .</span> <font color=\"DarkGreen\"><b>[ هََ<span class=\"hlight\" dir=\"rtl\">/</span> هُو ]</font></b> (ص مرکب ) (از: هول عربی + ناک فارسی ) مهیب .ترسناک . (یادداشت مرحوم دهخدا). چیزی که از دیدن آن هیبت و ترس در دل پدید آید. (آنندراج ) <span class=\"hlight\">:</span> <br>یکی باد برخاست بس هولناک <br>دل جنگیان شد از آن پر ز باک .<br> <font color=\"Red\">فردوسی .</font><br>جایی و چه جای از این مغاکی <br>ماننده ٔ گور هولناکی .<br> <font color=\"Red\">نظامی .</font><br>چو گردن کشید آتش هولناک <br>به بیچارگی تن بینداخت خاک .<br> <font color=\"Red\">سعدی (از آنندراج ).</font><br>یکی آتشین وادی هولناک <br>که از هول او دیو گشتی هلاک .<br><font color=\"Red\">عبداﷲ هاتفی (از آنندراج ).</font><br></font></div>'),
(269141, 'هوله', '<span class=\"hlight\">هوله .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) حوله . دستار. دستمال . از ترکی خاولی (از: خاو + لی ). پارچه ٔ پرزدار دارای خاو، دارای پرز. (فرهنگ فارسی معین ).<br></font></div>'),
(269142, 'هوله سو', '<span class=\"hlight\">هوله سو.</span> <font color=\"DarkGreen\"><b>[ هَُ ل َ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش شاهین دژ شهرستان مراغه . در مسیر ارابه رو شاهین دژ به تکاب قرار دارد و دارای <span class=\"hlight\" dir=\"rtl\">١٠٦٩</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269143, 'هولول', '<span class=\"hlight\">هولول .</span> <font color=\"DarkGreen\"><b>[ هََ وَل ْ وَ ]</font></b> (ع ص ) رجل هولول ؛ مرد سبک . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269144, 'هولک', '<span class=\"hlight\">هولک .</span> <font color=\"DarkGreen\"><b>[ هََ ل َ ]</font></b> (اِ) آبله ٔ دست و پا. <BR><font color=\"Blue\">◄</font> هلاکت . (آنندراج ). <BR><font color=\"Blue\">◄</font> مویز که انگور خشک باشد. (آنندراج ) (فرهنگ اسدی ) <span class=\"hlight\">:</span> <br>چو روشن شد انگور همچون چراغ <br>بکردند انگور هولک به باغ .<br> <font color=\"Red\">صیدلانی (از حاشیه ٔ فرهنگ اسدی ).</font><br><BR><font color=\"Blue\">◄</font> نقطه . (حاشیه ٔ فرهنگ اسدی ). لک <span class=\"hlight\">:</span> <br>چو هولک بر دو چشم دلبر افتاد<br>درون آمد ز پا آن سرو آزاد.<br><font color=\"Red\">؟ (از حاشیه ٔ فرهنگ اسدی ).</font><br></font></div>'),
(269145, 'هولک', '<span class=\"hlight\">هولک .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِ) گردکان بازی . (انجمن آرا). جوزبازی و گردکان بازی را گویند و بعضی گردون بازی را گفته اند و آن چرخی باشد که طفلان از چوب و خلاشه سازند و بر آب روان نصب کنند تا آب بر آن خورده به گردش درآید. (آنندراج ) (برهان ).<br></font></div>'),
(269146, 'هولکی', '<span class=\"hlight\">هولکی .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ل َ ]</font></b> (ص نسبی، ق ) در تداول عامه، بشتاب . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">هول هولکی </span> ؛ شتابزده . به شتابی تمام . با دستپاچگی .<br></font></div>'),
(269147, 'هولگی', '<span class=\"hlight\">هولگی .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ص نسبی ) ترسانیده شده و هراسان و مجازاً به معنی مضطرب و این منسوب است به هولة که به فتح باشد به معنی یک بار ترسانیدن، چه وزن فعله به فتح برای مرت باشد، پس به حالت الحاق یای نسبت های هوز موافق قاعده ٔ فارسی به گاف فارسی بدل شده چنانکه در پردگی . (غیاث اللغات ) (آنندراج ). و رجوع به هولکی شود.<br></font></div>'),
(269148, 'هولی', '<span class=\"hlight\">هولی .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ]</font></b> (اِ) کره اسبی که هنوز زین نکرده باشند و به هندی آهسته و هموار باشد. (آنندراج ) (برهان ) (انجمن آرا).<br></font></div>'),
(269149, 'هولی', '<span class=\"hlight\">هولی .</span> (اِخ ) در هندی نام عیدی و جشنی است . (برهان ) (آنندراج ). این جشن را در اوائل فصل بهار برپا می کنند. (فرهنگ عمید).<br></font></div>'),
(269150, 'هولیق', '<span class=\"hlight\">هولیق .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از دهستان هریس بخش مرکزی شهرستان سراب . دارای <span class=\"hlight\" dir=\"rtl\">٦٠١</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269151, 'هولیوود', '<span class=\"hlight\">هولیوود.</span> <font color=\"DarkGreen\"><b>[ هَُ لی ]</font></b> (اِخ ) هالیوود. شهری است که در کالیفرنیای جنوبی واقع است . از شهرهای اتازونی در حومه ٔ شهر لوس آنجلس که از معروفترین شهرهای سینمایی جهان و مرکز تهیه ٔ فیلمهای سینمائی امریکا است . این شهر دارای <span class=\"hlight\" dir=\"rtl\">١٦٠٠٠٠</span> تن جمعیت است .<br></font></div>'),
(269152, 'هوم', '<span class=\"hlight\">هوم .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) شکاف زمین . (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(269153, 'هوم', '<span class=\"hlight\">هوم .</span> (اِ) درختی است که در همه جا به هم رسد شبیه به درخت گز و گره های آن نزدیک به هم باشد و پارسیان زردشتی در وقت زمزمه در دست گیرند. مؤلف انجمن آرا گوید: هوم نباتی است اسفل ساق آن باریک و یک عدد و صلب و گل آن زرد و تیره و شبیه به یاسمین و برگ آن ریزه و شکوفه ٔ آن شبیه به یاسمین . صاحب تحفه گوید: از جنس ارغوان زرد است، بعضی بخور مریم دانسته اند و دیگری گفته که گلی است که آن را جعفری خوانند و به اقسام میباشد، قسمی پنج برگ و قسمی مضاعف و به عربی آن را هوم المجوس گویند.(انجمن آرا) (آنندراج ). و رجوع به هوم المجوس شود.<br></font></div>'),
(269154, 'هوم', '<span class=\"hlight\">هوم .</span> (ترکی، اِ) به ترکی نام گیاهی است شاخه های آن پرگره و بارش شبیه به عنب الثعلب و کبک از آن بسیار محظوظ است و گفته اند از سموم قتاله است، چون پیکان را به آب آلوده ٔ آن خشک نمایند زخمش کشنده است . (تحفه ٔ حکیم مؤمن ) (آنندراج ) (انجمن آرا).<br></font></div>'),
(269155, 'هوم', '<span class=\"hlight\">هوم .</span>(هندی، اِ) به هندی به معنی ضیافت آتش باشد و آن چنان است که انواع گوشتها و روغنها در آتش ریزند و چیزها خوانند و طلب مطالب و مدعیات خود کنند. (برهان ).<br></font></div>'),
(269156, 'هوم', '<span class=\"hlight\">هوم .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) یکی از خمسه ٔ قدمای دین زردشت به نقل صاحب التنبیه و الاشراف و معنی آن طینت، سرشت و خمیره <font color=\"DarkGreen\"><b>[ ماده ]</font></b> است . (یادداشت مؤلف ). و رجوع به امثال و حکم شود.<br></font></div>'),
(269157, 'هوم', '<span class=\"hlight\">هوم .</span> (اِخ ) نام مردی است از آل فریدون که در کوهی عبادت کردی . چون افراسیاب از کیخسرو مغلوب و منکوب، روی پنهان کرده فرار گزید، در اراضی ترکستان و اقصای بلاد تاتار پنهان میزیست، به جانب دربند افتاده در بیغوله ها به سر میبرد تا به کوهسار ارمن و بردع درافتاد. شب به غاری خزید و از غایت محرومی از مال و دولت بر خود نوحه میکرد و ناله میکشید. هوم که در آن حوالی بود به هوای ناله ٔ وی بر سر وی رفت و دانست که افراسیاب است که از بیم سپاه کیخسرو در زوایای جبل و شعاب قلل متواری است . با وی درآویخت و به حکم تقدیر بر وی غلبه یافت و او را بگرفت و ببست و سرانجام به دست کیخسرو کشته شد. (برهان ) (آنندراج ) (انجمن آرا) <span class=\"hlight\">:</span> <br>کجا نام آن نامور هوم بود<br>بسی سال دور از بر و بوم بود.<br> <font color=\"Red\">فردوسی .</font><br>بیاویخته آن دو تن سخت دیر<br>به آخر ورا هوم آورد زیر.<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(269158, 'هوماخس', '<span class=\"hlight\">هوماخس .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (اِخ ) به گفته ٔ صاحب برهان نام پدرارسطو است که معلم اول باشد و این غلط است و نام پدر ارسطو نقوماخس بوده است . (یادداشت مرحوم دهخدا).<br></font></div>'),
(269159, 'هومان', '<span class=\"hlight\">هومان .</span> (اِخ ) از پهلوانان تورانی شاهنامه و برادر پیران ویسه است و ازسران لشکر افراسیاب . وی در جنگ به دست بیژن پسر گیوکشته شد. (از انجمن آرا) (از آنندراج ) (از برهان ).<br></font></div>'),
(269160, 'هومة', '<span class=\"hlight\">هومة.</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (ع اِ) دشت و بیابان . (منتهی الارب ) (آنندراج ). فلات . هوماة. (اقرب الموارد).<br></font></div>'),
(269161, 'هومر', '<span class=\"hlight\">هومر.</span> <font color=\"DarkGreen\"><b>[ هَُ م ِ ]</font></b> (اِخ ) هُمِر. شاعر مشهور یونان قدیم در قرن نهم قبل از میلاد. اشعار حماسی وی معروف است . گویند در آخر عمر نابینا شد و از شهری به شهری میرفت و اشعار رزمی خود را به نوای چنگ می خواند. منظومه های مشهور ایلیاد و ادیسه که به اغلب زبانها ترجمه شده از او است .<br></font></div>'),
(269162, 'هومه', '<span class=\"hlight\">هومه .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) دهی است از دهستان ززوماهروی بخش الیگودرز شهرستان بروجرد. واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی جنوب شوسه ٔ ازنا به درود. با <span class=\"hlight\" dir=\"rtl\">٢١١</span> تن سکنه . آب آن از چاه و قنات و محصول آن غلات، لبنیات، چغندر و پنبه و شغل اهالی آنجا زراعت و گله داری است . راه مالرو دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269163, 'هون', '<span class=\"hlight\">هون .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو]</font></b> (اِ) زمین کشتزاری را گویند که در آن کلوخه بسیاربود. (آنندراج ) (غیاث اللغات ). زمین شیارکرده ٔ کلوخ زار را گویند. (برهان ). <BR><font color=\"Blue\">◄</font> زراعتی را نیز گفته اند که سنگ و کلوخ بسیار داشته باشد. (برهان ).<br></font></div>'),
(269164, 'هون', '<span class=\"hlight\">هون .</span> (صوت ) کلمه ای است که برای تأکید گویند. (آنندراج ). کلمه ٔ تأکید و کلمه ٔ استکراه است . (غیاث اللغات ). هین <span class=\"hlight\">:</span> <br>پیش آمده در رهش دو وادی <br>یک آتش بد یکیش گلگون <br>آواز آمد که رو در آتش <br>تا یافت شوی به گلستان هون .<br><font color=\"Red\">مولوی (از آنندراج ).</font><br></font></div>'),
(269165, 'هون', '<span class=\"hlight\">هون .</span> (ع اِمص ) رسوایی . (منتهی الارب ) (آنندراج ). خزی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خواری . <BR><font color=\"Blue\">◄</font> مشقت . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> خَلق . (اقرب الموارد). تمامی آفرینش . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (مص ) مهانة. هوان . خوار شدن . (ترجمان القرآن جرجانی ). خوار گردیدن . (منتهی الارب ). ذلیل و حقیر گردیدن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سست شدن و آرام و قرار گرفتن . (اقرب الموارد).<br></font></div>'),
(269166, 'هون', '<span class=\"hlight\">هون .</span> (هندی، اِ) به ضم ها و سکون نون و واو غیرملفوظ به معنی زر مسکوک رایج دکن . (غیاث اللغات ) (آنندراج ) (برهان ).<br>- <span class=\"hlight\">هون اچترائی </span> ؛نوعی از هون است که واضع آن اچترائی نام راجه شده باشد. (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(269167, 'هون', '<span class=\"hlight\">هون .</span> (اِخ ) (در تداول، هونها به صورت جمع به کار رود) نام قومی از اقوام زردپوست وحشی که از اوائل قرن دوم میلادی در شمال بحر خزر و حوالی رود ولگا و اورال سکونت اختیار کردند و سپس به طرف اروپا هجوم بردند و در <span class=\"hlight\" dir=\"rtl\">٢٤٧</span> م . دسته ای از آنها روم را تهدید کردند و قبائل ژرمنی را مغلوب ساختند و دولت عظیمی تشکیل دادند که بعد از مرگ آتیلا منقرض گردید. دسته ٔ دیگر به آسیا رفتند و در توران ساکن شدند و در زمان ساسانیان چند دفعه به ایران حمله کردند. این دسته در مشرق به هیاطله مشهور شده اند. هپتال . هیتال .<br></font></div>'),
(269168, 'هون', '<span class=\"hlight\">هون .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) روش و گرانباری . (منتهی الارب ) (آنندراج ). گویند: اًمْش ِ علی هونک ؛ به روش و وقار خویش رو. <BR><font color=\"Blue\">◄</font> (ص ) مرد خرد و حقیر. (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (مص ) آسان گشتن . <BR><font color=\"Blue\">◄</font> سبک گردیدن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> خوار گردیدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِمص ) سکینه و وقار. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بردباری . (منتهی الارب ) (آنندراج ) (ترجمان القرآن جرجانی ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آرامش . (منتهی الارب ). آهستگی . (منتهی الارب ).<br></font></div>'),
(269169, 'هونة', '<span class=\"hlight\">هونة.</span> <font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (ع ص ) آرمیده . <BR><font color=\"Blue\">◄</font> آهسته کار. (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269170, 'هونطاع', '<span class=\"hlight\">هونطاع .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (یوم ...) از ایام عرب است .رجوع به حونطاع و رجوع به مجمعالامثال میدانی شود.<br></font></div>'),
(269171, 'هونقانلو', '<span class=\"hlight\">هونقانلو.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) طایفه ای از طوایف قشقائی . این طایفه مرکب از ششصد خانوار است که در هونقان مسکن دارند. (جغرافیای سیاسی کیهان ).<br></font></div>'),
(269172, 'هونولولو', '<span class=\"hlight\">هونولولو.</span> <font color=\"DarkGreen\"><b>[ هَُ ن ُ ]</font></b> (اِخ ) پایتخت مجمعالجزایر هاوایی در اقیانوس کبیر، دارای مناظر طبیعی زیبا و <span class=\"hlight\" dir=\"rtl\">٣٠٠٠٠٠</span> تن جمعیت .<br></font></div>'),
(269173, 'هونگ', '<span class=\"hlight\">هونگ .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (اِ) در تداول عامه، هاون . رجوع به هاون شود.<br></font></div>'),
(269174, 'هونگ نام', '<span class=\"hlight\">هونگ نام .</span> (اِخ ) از شهرهای کره ٔ شمالی، دارای <span class=\"hlight\" dir=\"rtl\">١٥٠٠٠٠</span> تن جمعیت . (فرهنگ عمید).<br></font></div>'),
(269175, 'هوه', '<span class=\"hlight\">هوه .</span> <font color=\"DarkGreen\"><b>[ هََ وِ ]</font></b> (اِخ ) دهی است از دهستان زلقی بخش الیگودرز شهرستان بروجرد، کنار راه قهره به ایوج، دارای <span class=\"hlight\" dir=\"rtl\">١٩٩</span> تن سکنه . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269176, 'هوهاء', '<span class=\"hlight\">هوهاء.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) مرد ضعیف بددل . (مهذب الاسماء).<br></font></div>'),
(269177, 'هوهو', '<span class=\"hlight\">هوهو.</span> <font color=\"DarkGreen\"><b>[ هَُ وَ هَُ وَ ]</font></b>(اِ مرکب ) لفظی است مرکب که آن را اسم قرار داده اندو به الف و لام تعریف معرف گردانند و مراد از آن اتحاد در ذات است یعنی صدق و آن حمل ایجابی است به مواطات، و گاهی مراد از آن اتحاد مفهومی است و اقسام آن مانند اقسام وحدت است چنانچه شیخ الرئیس در الهیات شفا متعرض شده است و سزاوار است که در هوهو کثرت اعتبار کنند زیرا هوهو بدون اثنینیت تصور نمیشود. برای تفصیل بیشتر رجوع به کشاف اصطلاحات الفنون و شفا شود.<br></font></div>'),
(269178, 'هوهو', '<span class=\"hlight\">هوهو.</span> (اِ صوت ) حکایت آواز از قبیل باد و غیره . (یادداشت مؤلف ). اسم صوت بعضی مرغان چون کبوتر و جز آن .<br>- <span class=\"hlight\">هوهو زدن </span> ؛ آواز برآوردن <span class=\"hlight\">:</span> <br>چو گل نقاب برافکند و مرغ هوهو زد<br>منه ز دست پیاله چه میکنی هی هی .<br><font color=\"Red\">حافظ (از آنندراج ).</font><br></font></div>'),
(269179, 'هوو', '<span class=\"hlight\">هوو.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) دو زن که در نکاح یک مرد میباشند، هریک مر دیگری را هوو خوانند. (برهان ) (غیاث اللغات ). ضرة. (السامی فی الاسامی ). وسنی . بنانج . گولانج . هبو. هم شوی . (یادداشت مؤلف ). انباغ . (آنندراج ) (غیاث اللغات ).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">مثل هوو</span> .<br> <span class=\"hlight\">هوو هوو را خوشگل می کند، جاری جاری را کدبانو</span> .<br><span class=\"hlight\">هوو هووست اگر همه سبوست </span> .<br></font></div>'),
(269180, 'هووخشتر', '<span class=\"hlight\">هووخشتر.</span> <font color=\"DarkGreen\"><b>[ هَُ وَ ش َ رَ ]</font></b> (اِخ ) (<span class=\"hlight\" dir=\"rtl\">٦٣٣</span>-<span class=\"hlight\" dir=\"rtl\">٥٨٥</span> ق . م .) سومین پادشاه از سلسله ٔ مادکه نخستین سلسله ٔ سلاطین ایران است . او مملکت آشور وکرسی آن نینوا را در <span class=\"hlight\" dir=\"rtl\">٦١٢</span> ق . م . بگشود و در سال <span class=\"hlight\" dir=\"rtl\">٥٨٥</span>ق . م . درگذشت . جانشین او ایشتوویگو بود. (یادداشت مؤلف ). هوخشتر یکی از پادشاهان نامی ایران و یکی ازقائدین مهم تاریخ بود. حدود ماد را به رود هالیس رسانید و آن را بزرگترین دولت آسیای غربی ساخت . نام هوخشتر را هرودت کواکسار نوشته ولی از کتیبه ٔ بیستون داریوش اول معلوم است که هووخشتر بود. از شاهان سیاستمدار کم نظیر بوده است . در موقع جلوس او اوضاع ماد خطرناک بود. وی بیدرنگ دست به اصلاحات زد و قشونی به اسلوب آسوری ترتیب داد و با ساز و برگ متداول مسلح ساخت و به آسور حمله کرد. آسوریها سخت پا فشردند ولی سرانجام سردار آسور شکست خورد. (ایران باستان ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span>).<br></font></div>'),
(269181, 'هووخشتره', '<span class=\"hlight\">هووخشتره .</span> <font color=\"DarkGreen\"><b>[ هَُ وَ ش َ رَ ]</font></b> (اِخ ) رجوع به هووخشتر و هوخشتر شود.<br></font></div>'),
(269182, 'هوور', '<span class=\"hlight\">هوور.</span> <font color=\"DarkGreen\"><b>[ هو وِ ]</font></b> (اِخ ) هربرت کلارک . (<span class=\"hlight\" dir=\"rtl\">١٨٧٤</span>-<span class=\"hlight\" dir=\"rtl\">١٩٦٤</span> م .). نام رئیس جمهور اتازونی از سال <span class=\"hlight\" dir=\"rtl\">١٩٢٩</span> تا <span class=\"hlight\" dir=\"rtl\">١٩٣٣</span> م .<br></font></div>'),
(269183, 'هووس', '<span class=\"hlight\">هووس .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (از ع، اِ) هوس <span class=\"hlight\">:</span> <br>در قدح کن ز حلق بط خونی <br>همچو روی تذرو و چشم خروس <br>رزم بر بزم اختیار مکن <br>هست ما را به خود هزار هووس .<br> <font color=\"Red\">ابن یمین (از یادداشت مؤلف ).</font><br>و رجوع به هوس شود.<br></font></div>'),
(269184, 'هوول', '<span class=\"hlight\">هوول .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع اِ) ج ِ هول . (منتهی الارب ) (اقرب الموارد). رجوع به هول شود.<br></font></div>'),
(269185, 'هوپمن', '<span class=\"hlight\">هوپمن .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (هزوارش، اِ) به لغت زند و پازند روی را گویند و به عربی وجه خوانند. (برهان ). هزوارش کلمه ٔ پهلوی ِ«رُد» به معنی روی است . (از حاشیه ٔ برهان چ معین ).<br></font></div>'),
(269186, 'هوپول', '<span class=\"hlight\">هوپول .</span> (اِخ ) دهی است از بخش خوسف شهرستان بیرجند. دارای <span class=\"hlight\" dir=\"rtl\">١٤٠</span> تن سکنه، آب آن از قنات و محصول عمده اش غله است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(269187, 'هوچقان', '<span class=\"hlight\">هوچقان .</span> (اِخ ) دهی است از بخش مرکزی شهرستان مرند، دارای <span class=\"hlight\" dir=\"rtl\">١٦٣٠</span> تن سکنه، آب آن از چشمه و محصول عمده اش غله و پنبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269188, 'هوچی', '<span class=\"hlight\">هوچی .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو]</font></b> (ص مرکب ) آنکه عوام را اغوا کند در ظاهر برای منافع آنان و در باطن برای سود خود. (یادداشت مؤلف ).<br>- <span class=\"hlight\">هوچی بازی </span> ؛ سر و صدای بیهوده به راه انداختن برای سود خود.<br>- <span class=\"hlight\">هوچی گری </span> ؛ هوچی بازی .<br>رجوع به هو شود.<br></font></div>'),
(269189, 'هوژ', '<span class=\"hlight\">هوژ.</span> <font color=\"DarkGreen\"><b>[ هَُ وَ]</font></b> (اِ) مرغی است . (انجمن آرا). رجوع به هوژه شود.<br></font></div>'),
(269190, 'هوژه', '<span class=\"hlight\">هوژه .</span> <font color=\"DarkGreen\"><b>[ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> ژِ ]</font></b> (اِ) پرنده ای است کوچک و آن را به عربی صعوه میگویند. و با زای هوز، صفاهانیان چکاوک را گویند. (برهان ). ابوالملیح .<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(269191, 'هوک', '<span class=\"hlight\">هوک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) احمق و گول با اندکی زیرکی . یهکوک . (آنندراج ) (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(269192, 'هوک', '<span class=\"hlight\">هوک .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (ع اِمص ) گولی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (مص ) گول گردیدن . (منتهی الارب ) (اقرب الموارد) (آنندراج ).<br></font></div>'),
(269193, 'هوک', '<span class=\"hlight\">هوک .</span> <font color=\"DarkGreen\"><b>[ هَِ وَک ک ]</font></b> (ع ص ) گول با اندکی زیرکی . (اقرب الموارد) (منتهی الارب ). یهکوک . (منتهی الارب ).<br></font></div>'),
(269194, 'هوک', '<span class=\"hlight\">هوک .</span> (اِخ ) رابرت . فیزیک دان و منجم معروف انگلیس (<span class=\"hlight\" dir=\"rtl\">١٦٣٥</span>-<span class=\"hlight\" dir=\"rtl\">١٧٠٣</span> م .). در رشته ٔ فیزیک کشفیات و تحقیقاتی به عمل آورده و کاشف قانونی است که به نام قانون هوک معروف است .<br></font></div>'),
(269195, 'هوکاجی', '<span class=\"hlight\">هوکاجی .</span> (اِخ ) به گفته ٔ خواندمیر در حبیب السیر نام یکی از دوازده پسر قوبلاقاآن از خانان مغول است . (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢</span>).<br></font></div>'),
(269196, 'هوکش', '<span class=\"hlight\">هوکش .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هُو ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) کشنده ٔ هو. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) مرهم که بر جراحت ضماد کنند التیام را. ضماد. (یادداشت مؤلف ).<br></font></div>'),
(269197, 'هوکی', '<span class=\"hlight\">هوکی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی است از دهستان ده پیر بخش حومه ٔ شهرستان خرم آباد. دارای <span class=\"hlight\" dir=\"rtl\">١٣٠</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269198, 'هوگو', '<span class=\"hlight\">هوگو.</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b>(اِخ ) ویکتور. مشهورترین شاعر رمانتیک قرن نوزدهم فرانسه (<span class=\"hlight\" dir=\"rtl\">١٨٠٢</span>-<span class=\"hlight\" dir=\"rtl\">١٨٨٥</span> م .). درردیف بزرگترین گویندگان و ادبای اجتماعی جهان است . وی مردی آزادمنش و آزادیخواه و طرفدار جدی اصلاحات اجتماعی به نفع طبقات محروم و رنجبر بود. از سن ده سالگی به شعر گفتن پرداخت و در بیست وپنج سالگی شاعری سرشناس بود. با وجود سن کم به عضویت آکادمی فرانسه و پارلمان و نمایندگی در مجالس مقننه نائل شد. وی براثر مخالفت با ناپلئون سوم از سیاست کناره گیری کرد و مدت بیست سال در تبعید به سر برد. اگرچه پیش از او مکتب رمانتیسم پیشرفتی کرده بود، ولی به دست وی به اوج توانائی و رونق رسید. ازاین رو هوگو را بنیان گذار و پیشرو این مکتب میدانند. نوشته های او در رشته های گوناگون فراوان است . مهمترین آثار او عبارتند از: <span class=\"hlight\" dir=\"rtl\">١</span>- بینوایان  <span class=\"hlight\" dir=\"rtl\">٢</span>- کلیسای نُتْردام ِ پاریس  <span class=\"hlight\" dir=\"rtl\">٣</span>- کارگران دریا <span class=\"hlight\" dir=\"rtl\">٤</span>- تاریخ یک جنایت  <span class=\"hlight\" dir=\"rtl\">٥</span>- مردی که می خندد و غیره، که روی هم رفته از شاهکارهای ادبیات فرانسه به شمار می آیند. (از فرهنگ فارسی معین ).<br></font></div>'),
(269199, 'هوگویک', '<span class=\"hlight\">هوگویک .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِ مرکب ) مرغ شب آویز را گویند که مرغ حقگوی است . (از آنندراج ).<br></font></div>'),
(269200, 'هوگیک', '<span class=\"hlight\">هوگیک .</span> <font color=\"DarkGreen\"><b>[ گ ُ ی َ ]</font></b> (اِ) کالک . (برهان ).<br></font></div>'),
(269201, 'هوی', '<span class=\"hlight\">هوی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) هَو. دوست دارنده . (منتهی الارب ). صاحب هوی . (اقرب الموارد). مؤنث آن هویة است . (اقرب الموارد).<br></font></div>'),
(269202, 'هوی', '<span class=\"hlight\">هوی .</span> (اِ) ترس و بیم . (آنندراج ) (برهان ). <BR><font color=\"Blue\">◄</font> کلمه ٔ افسوس است . (حاشیه ٔ برهان چ معین ). باد سرد. آه <span class=\"hlight\">:</span> <br>همه چشم پر آب و دل پر ز هوی <br>به طوس سپهبد نمودند روی .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(269203, 'هوی', '<span class=\"hlight\">هوی .</span> (اِ صوت ) حکایت صوت گفتن . آواز برآوردن با تفوه به کلمه ٔ هو. مجازاً بانگ و آواز و فریاد <span class=\"hlight\">:</span> <br>جهان پر مشک و عنبر شد ز مویش <br>هوا پر دود و آذر شد ز هویش .<br> <font color=\"Red\">(ویس و رامین ).</font><br>همچون گوزن هوی برآورده در سماع <br>شیران کز آتش شب شبهت رمیده اند.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">های و هوی </span> ؛ فریاد و بانگ <span class=\"hlight\">:</span> <br>هرکه را وقتی دمی بوده ست و روزی مستیی <br>دوست دارد ناله ٔ مستان و های و هوی را.<br> <font color=\"Red\">سعدی .</font><br>مطربان گویی در آوازند و صوفی در سماع <br>شاهدان در حالت و شوریدگان در های و هوی .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> افسوس . (حاشیه ٔ برهان چ معین ) <span class=\"hlight\">:</span> <br>همی کرد هوی و همی کند موی <br>همی ریخت اشک و همی خست روی .<br> <font color=\"Red\">فردوسی .</font><br>گهی از دیده راندی گوهرین جوی <br>گهی از دل کشیدی آذرین هوی .<br> <font color=\"Red\">(ویس و رامین ).</font><br> <BR><font color=\"Blue\">◄</font> (صوت ) کلمه ٔ تنبیه است . (حاشیه ٔ برهان چ معین ) <span class=\"hlight\">:</span> <br>هان مردا هوی و هان جوانمرداهوی <br>مردی کنی و نگاه داری سر کوی .<br><font color=\"Red\">(منسوب به ابوسعید ابوالخیر) (از حاشیه ٔ برهان از فرهنگ نظام ).</font><br></font></div>'),
(269204, 'هوی', '<span class=\"hlight\">هوی .</span> <font color=\"DarkGreen\"><b>[ هَِ وا ]</font></b> (ع مص ) پیش آوردن و نرم گردانیدن . (منتهی الارب ). هِواء. (اقرب الموارد). گویند: الهواء و اللواء؛ أی ان تقبل بالشی ٔ و تدبر أی تلاینه مرة و تشاذه اخری . (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(269205, 'هوی', '<span class=\"hlight\">هوی .</span> <font color=\"DarkGreen\"><b>[ هََ ی وی ی ]</font></b> (ع اِ) پاره ای از شب . <BR><font color=\"Blue\">◄</font> بانگ و فریاد. <BR><font color=\"Blue\">◄</font> (مص ) از بالابه زیر افتادن یا هوی به فتح بالا برآمدن و به ضم فرودافتادن . (منتهی الارب ) (آنندراج ) (اقرب الموارد).<br></font></div>'),
(269206, 'هوی', '<span class=\"hlight\">هوی .</span> <font color=\"DarkGreen\"><b>[ هََ وا ]</font></b> (ع مص ) دوست داشتن . (منتهی الارب ) (آنندراج ) (ترجمان القرآن جرجانی ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) خواست و عشق در خیر باشد یا در شر. (منتهی الارب ) (آنندراج ). عشق . (اقرب الموارد) <span class=\"hlight\">:</span> <br>چنونه هست و نه بود و نه نیز خواهد بود<br>فراق او متواتر هوای او سرمد.<br><font color=\"Red\">منجیک .</font><br>هوای تو را زان گزیدم ز عالم <br>که پاکیزه تر از سرشک هوائی .<br> <font color=\"Red\">زینبی .</font><br><BR><font color=\"Blue\">◄</font> خواهش دل . (اقرب الموارد) (منتهی الارب ) (آنندراج ). آرزو. (دهار). خواست دل به آنچه نشاید. (ترجمان جرجانی ). خواسته . (منتهی الارب ) (آنندراج ). مراد. (حاشیه ٔ فرهنگ اسدی ). کام . (حاشیه ٔ فرهنگ اسدی ) (ملخص اللغات خطیب ). <BR><font color=\"Blue\">◄</font> معشوق . (منتهی الارب ) (آنندراج ). ج، اهواء. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اصطلاح صوفیه ) الغیب الذی یصح شهوده . (تعریفات سید جرجانی ). <BR><font color=\"Blue\">◄</font> هوی گاه به معنی محبت حق است به خصوص و اطاعت و انقیاد به او و این معنی مصطلح صوفیه است . ودر صحائف گوید: هوی از مراتب محبت است و آن چنان است که قلب دائم بسوی محبوب توجه دارد و این مقام را پنج درجه است : اول خضوع، دوم بذل مهجه در طاعت دوست فوق الطاقة، نبینی که پیغمبر ما (ص ) در نماز چندان بایستادی که قدم مبارکش ورم کردی گاه به انگشتان پای ایستادی و گاه خود را بیاویختی و به ذکر مشغول شدی، سوم صبر در شدائد و محن، چهارم تضرع، پنجم رضا و تسلیم . (کشاف اصطلاحات الفنون ).<br></font></div>'),
(269207, 'هوی', '<span class=\"hlight\">هوی .</span> <font color=\"DarkGreen\"><b>[ هَُ وی ی ]</font></b> (ع اِ) پاره ای از شب . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بانگ و فریاد. <BR><font color=\"Blue\">◄</font> (مص ) فرودآمدن عقاب بر شکار و جز آن . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> افتادن چیزی . (منتهی الارب ) (آنندراج ). از بالا به زیر افتادن . (اقرب الموارد) (ترجمان جرجانی ترتیب عادل ). <BR><font color=\"Blue\">◄</font> دراز و بلند شدن دست . <BR><font color=\"Blue\">◄</font> مردن . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آواز نرم شنیدن گوش . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> شتابی کردن . <BR><font color=\"Blue\">◄</font> دهن گشادن زخم نیزه . <BR><font color=\"Blue\">◄</font> وزیدن باد. <BR><font color=\"Blue\">◄</font> درگذشتن و مضی در سیر. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رفتن بر روی زمین . (اقرب الموارد).<br></font></div>'),
(269208, 'هوی و های', '<span class=\"hlight\">هوی و های .</span> <font color=\"DarkGreen\"><b>[ ی ُ ]</font></b> (ترکیب عطفی، اِ صوت مرکب ) های و هوی . جار و جنجال . مشغله . بانگ و فریاد. هلانوش . هیابانگ .<br></font></div>'),
(269209, 'هوی و هوس', '<span class=\"hlight\">هوی و هوس .</span> <font color=\"DarkGreen\"><b>[ هََ وا وُ هََ وَ ]</font></b> (ترکیب عطفی، اِ مرکب ) میل و خواهش نفس <span class=\"hlight\">:</span> <br>حقیقت سرایی ست آراسته <br>هوی و هوس گرد برخاسته .<br> <font color=\"Red\">سعدی .</font><br>رضا و ورع نیکنامان حر<br>هوی و هوس رهزن و کیسه بر.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(269210, 'هوی گنس', '<span class=\"hlight\">هوی گنس .</span> <font color=\"DarkGreen\"><b>[ گ ِ ]</font></b> (اِخ ) کریستیان . از علمای بزرگ ریاضی و منجمین مشهور عالم است . وی در سال <span class=\"hlight\" dir=\"rtl\">١٦٢٩</span> م . در شهرلاهه پایتخت هلند به دنیا آمد. در سال <span class=\"hlight\" dir=\"rtl\">١٦٥٦</span> م . بوسیله ٔ دوربینی که خود ساخته بود یکی از ماههای زحل را دید و سه سال بعد نیز حلقه ای که گرد زحل است را کشف کرد. استعمال پاندول که از اختراعات گالیله بود در تنظیم حرکات ساعتهای دیواری کار هوی گنس است . هوی گنس درسال <span class=\"hlight\" dir=\"rtl\">١٦٩٥</span> م . وفات یافت . او را در مباحث نور و وزن اجسام و شعب مختلف ریاضی کتابها و مقالات بسیار است .<br></font></div>'),
(269211, 'هویان', '<span class=\"hlight\">هویان .</span> <font color=\"DarkGreen\"><b>[ هََ وَ ]</font></b> (ع مص ) از بالا به زیر افتادن . (منتهی الارب ). رجوع به هوی شود.<br></font></div>'),
(269212, 'هویة', '<span class=\"hlight\">هویة.</span> <font color=\"DarkGreen\"><b>[ هََ وی ی َ ]</font></b> (ع ص ) چاه دورتک . (منتهی الارب ) (اقرب الموارد) (آنندراج ). ج، هوایا. (از اقرب الموارد).<br></font></div>'),
(269213, 'هویة', '<span class=\"hlight\">هویة.</span> <font color=\"DarkGreen\"><b>[ هََ ی َ ]</font></b> (ع ص ) مؤنث هَوی . زن صاحب هوی یعنی دوست دارنده . (از اقرب الموارد). رجوع به هوی شود.<br></font></div>'),
(269214, 'هویة', '<span class=\"hlight\">هویة.</span> <font color=\"DarkGreen\"><b>[ هَُ وی ی َ ]</font></b> (ع اِ) هویت . عبارت است از تشخص و همین معنی میان حکیمان و متکلمان مشهور است . (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> هویة گاه بر وجود خارجی اطلاق میگردد. (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> هویة گاه بر ماهیت با تشخص اطلاق میگردد که عبارت است از حقیقت جزئیه . (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> (اصطلاح صوفیه ) هویه مرتبه ٔذات بحت را گویند و مرتبه ٔ احدیت و لاهوت اشارت است از آن . در انسان کامل گوید: هویت حق تعالی عین او است که ممکن نیست ظهور آن . هویت از لفظ هو گرفته شده که اشاره ٔ به غایب است و آن درباره ٔ خدای تعالی اشاره است به کنه ذات او به اعتبار اسماء و صفات او با اشعار به غیبوبت آن . (کشاف اصطلاحات الفنون ) <span class=\"hlight\">:</span> <br>ان الهویة عین ذات الواحد<br>و من المحال ظهورها فی شاهد<br>فکأنها نعت و قد وقعت علی <br>شان البطون و ما له من جاحد.<br> <font color=\"Red\">(از کشاف اصطلاحات الفنون ).</font><br>و رجوع به تعریفات سیدجرجانی و هویت شود.<br></font></div>'),
(269215, 'هویت', '<span class=\"hlight\">هویت .</span> <font color=\"DarkGreen\"><b>[ هَُ وی ی َ ]</font></b> (ع اِ) هُویّة. رجوع به هُویّة شود.<br></font></div>'),
(269216, 'هویج', '<span class=\"hlight\">هویج .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) حَویج . نوعی رستنی که بیخ آن را خام یا پخته خورند همچون چغندر. زردک . گزر. رجوع به گزر شود.<br></font></div>'),
(269217, 'هوید', '<span class=\"hlight\">هوید.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) گلیمی که گرداگرد کوهان شتر کشند. (انجمن آرا) (آنندراج از سروری از سامی ) <span class=\"hlight\">:</span> <br>ورا جای بر زنده پیلی سپید<br>مهان، بر هیونان عودی هوید.<br> <font color=\"Red\">اسدی (گرشاسب نامه ).</font><br>تو هنوز از روی رعنایی ز بهرلاشه ای <br>گاه دربند هویدی گاه دربند مهار.<br><font color=\"Red\">سنایی (از آنندراج ).</font><br></font></div>'),
(269218, 'هوید', '<span class=\"hlight\">هوید.</span> <font color=\"DarkGreen\"><b>[ هَُ وَ <span class=\"hlight\" dir=\"rtl\">/</span>وِ ]</font></b> (اِ) جهاز شتر و آن بمنزله ٔ پالان او است و بعضی گویند این به فتح اول و کسر ثانی است و آن گلیمی است پشم آگنده که آن را بر دور کوهان شتر درآورند. (برهان ). جهاز شتر. (آنندراج ) (انجمن آرا) <span class=\"hlight\">:</span> <br>گاه گویند فلان اشتر گم کرده هوید<br>گاه گویند فلان ترک بیفکنده کلاه .<br> <font color=\"Red\">فرخی .</font><br>برآوردم زمامش تا بناگوش <br>فروهشتم هویدش تا به کاهل .<br> <font color=\"Red\">منوچهری (از آنندراج ).</font><br>به حلم و زیرکی و حکمت شتربانان <br>به شال و تنگ و پلاس و هوید و پوش و نوار.<br> <font color=\"Red\">سوزنی (از آنندراج ).</font><br>رجوع به هَوید شود.<br></font></div>'),
(269219, 'هویدا', '<span class=\"hlight\">هویدا.</span> <font color=\"DarkGreen\"><b>[ هَُ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (ص ) آشکار. (انجمن آرا) (آنندراج ). آشکارا. ظاهر. (برهان ). پیدا. (انجمن آرا). روشن . (برهان ). سخت پیدا. (حاشیه ٔ فرهنگ اسدی ). نمایان . مبین . (حاشیه ٔ فرهنگ اسدی ). بَیِّن . یعنی در نهایت ظهور. (برهان ) <span class=\"hlight\">:</span> <br>درشتی دل شاه و نرمی دلش <br>ندانی هویدا کند حاصلش .<br> <font color=\"Red\">عنصری (از فرهنگ اسدی ).</font><br>- <span class=\"hlight\">هویدا بودن </span> ؛ آشکار بودن . ظاهر و واضح بودن <span class=\"hlight\">:</span> <br>روی نهاده ست کار شاه به بالا<br>دیده ٔ ما روشن است و کار هویدا.<br> <font color=\"Red\">منوچهری .</font><br>ز پیدایی هویدا در هویداست <br>ز پنهانی نهان اندر نهان است .<br> <font color=\"Red\">؟</font><br>- <span class=\"hlight\">هویدا شدن </span> ؛ آشکار شدن . ظاهر و نمایان و واضح گردیدن <span class=\"hlight\">:</span> <br>بسی پرسیده شد پنهان و پیدا<br>نمیشد سرّآن صورت هویدا.<br> <font color=\"Red\">نظامی .</font><br>عیب پاکان زود بر مردم هویدا میشود<br>در میان شیر خالص موی رسوا میشود.<br> <font color=\"Red\">صائب .</font><br>- <span class=\"hlight\">هویدا کردن </span> ؛ واضح کردن . آشکار و نمایان کردن <span class=\"hlight\">:</span> <br>در دل هر قطره نوحی دست و پا گم کرده است <br>از کدامی چشمه این طوفان هویدا کرد عشق .<br><font color=\"Red\">محمدابراهیم قاری (از آنندراج ).</font><br>- <span class=\"hlight\">هویدا گردیدن </span> ؛ آشکار شدن <span class=\"hlight\">:</span> <br>از ته سبزه ٔ خط همچو مه از ابر تنک <br>رفتن حسن به تعجیل هویدا گردد.<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>- <span class=\"hlight\">هویداسخن </span> ؛ فصیح . (مهذب الاسماء).<br></font></div>'),
(269220, 'هویدک', '<span class=\"hlight\">هویدک .</span> <font color=\"DarkGreen\"><b>[ هَُ وَ دَ ]</font></b> (اِخ ) نام یکی از پیشوایان ملحدان است . (برهان ) (آنندراج ). جهانگیری هویدیک آورده گوید: نام یکی از پیشوایان ملحدان بوده که حکیم خاقانی فرماید <span class=\"hlight\">:</span> <br>او کیست که با روان تاریک <br>باشد بمثابه ٔ هویدیک .<br>یوستی این نام را هوویدیک  ضبط کرده به استناد فولرس <span class=\"hlight\" dir=\"rtl\">II</span>، <span class=\"hlight\" dir=\"rtl\">١٤٧٠</span> <span class=\"hlight\" dir=\"rtl\">a</span> و به کتاب اشپیگل ارجاع کرده . (یوستی، نام نامه ص <span class=\"hlight\" dir=\"rtl\">١٤٠</span>). اشپیگل در کتاب مزبور در بحث از کلمه ٔ اوستائی <span class=\"hlight\" dir=\"rtl\">Hunusta</span> (که طبقه ای از دروجان <font color=\"DarkGreen\"><b>[ دروغ پرستان، پیروان کیش باطل ]</font></b> هستند، رجوع به یوستی، فرهنگ اوستا ص <span class=\"hlight\" dir=\"rtl\">٣٢٨</span> شود) گوید: من اکنون ترجیح میدهم که کلمه ٔ مزبور عنوانی باشد برای انگره مینو <font color=\"DarkGreen\"><b>[ اهریمن ]</font></b> . اسپندیارجی مقدم این کلمه را زیانکار <font color=\"DarkGreen\"><b>[ مضر ]</font></b> تعبیر میکند و اسپندیارجی مؤخر آن را هونوچا یا هویدک (رجوع به فولرس، هویدک شود) میداند، که نشانه ای است برای تشخیص بی دینان . و ممکن است احتمال داد هویدک متن مصحف بَوَنْدَگ پهلوی  (در ارمنی بوندک ) به معنی کامل بوندس  = بونده = بوند باشد، نام یکی از مانویه ٔ روم که با کیش رسمی مانویه مخالفت کرد و او پیشرو مزدک بود. رجوع به ایران در زمان ساسانیان کریستنسن ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span> به بعد و <span class=\"hlight\" dir=\"rtl\">٣٦٢</span> به بعد و<span class=\"hlight\" dir=\"rtl\">٣٠٢</span> به بعد (تاریخ سلطنت قباد و ظهور مزدک ) شود. در هر حال خاقانی این اسم را در تحفةالعراقین در عنوان «در هجو ابوالعلای گنجه ای » آورده و هویدیک را مسیحی معرفی کرده <span class=\"hlight\">:</span> <br>او <font color=\"DarkGreen\"><b>[ابوالعلا]</font></b> کیست که با روان تاریک <br>باشد بمثابت هویدیک <br>او جز پی نفی حق نپوید<br>این <font color=\"DarkGreen\"><b>[هویدیک ]</font></b> از اب و ابن و روح گوید<br>او <font color=\"DarkGreen\"><b>[هویدیک ]</font></b> مشرک و این <font color=\"DarkGreen\"><b>[ابوالعلا]</font></b> معطل از دل <br>هم مشرک بهتر از معطّل .<br><font color=\"Red\">(حاشیه ٔ برهان چ معین از تحفةالعراقین چ قریب صص <span class=\"hlight\" dir=\"rtl\">٢٣٥</span>-<span class=\"hlight\" dir=\"rtl\">٢٣٦</span>).</font><br></font></div>'),
(269221, 'هویدیک', '<span class=\"hlight\">هویدیک .</span> <font color=\"DarkGreen\"><b>[ هَُ وَ ]</font></b> (اِخ ) هویدک . (انجمن آرا) <span class=\"hlight\">:</span> <br>او کیست که با روان تاریک <br>باشد بمثابت هویدیک .<br><font color=\"Red\">خاقانی (از انجمن آرا).</font><br></font></div>'),
(269222, 'هویر', '<span class=\"hlight\">هویر.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی است جزء دهستان ابرشیوه و پشت کوه بخش حومه ٔ شهرستان دماوند. دارای <span class=\"hlight\" dir=\"rtl\">٤٦٠</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(269223, 'هویزه', '<span class=\"hlight\">هویزه .</span> <font color=\"DarkGreen\"><b>[ هَُ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ زِ ]</font></b> (اِخ ) مرکز بخش هویزه از شهرستان دشت میشان . در <span class=\"hlight\" dir=\"rtl\">٤٠</span>هزارگزی جنوب خاوری سوسنگرد. آب آن از شعبه ٔ رود کرخه و محصول آن غلات و لبنیات و شغل اهالی زراعت و گله داری است . مرکز ادارات بخش مانند بخشداری، آمار، پست و تلگراف، دارائی و گمرک در این قصبه برقرار است . درمانگاهی در این محل تشکیل گردیده و مورد استفاده ٔ سکنه ٔ بخش است . آب مشروب بوسیله ٔ موتور آب کشی تأمین میشود. دارای دبستان است .از آثار قدیمی یک مسجد و بنای زیارتگاه ابراهیم خلیل و چند امام زاده ٔ دیگر است . ساکنین از طایفه ٔ موالی سیس و کوت هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269224, 'هویزه', '<span class=\"hlight\">هویزه .</span> <font color=\"DarkGreen\"><b>[ هَُ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ زِ ]</font></b> (اِخ ) نام یکی از بخش های شهرستان دشت میشان . این بخش در جنوب سوسنگرد واقع گردیده، موقع طبیعی بخش دشت و هوای آن مانند اغلب نقاط خوزستان گرم سیر است .از <span class=\"hlight\" dir=\"rtl\">١٤</span> قریه ٔ کوچک و بزرگ تشکیل شده است . جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">٢٥٠٠</span> نفر و قراء مهم آن عبارت اند از: ازعمه ورفیع که هر کدام دوهزار نفر جمعیت دارند. آب بخش ازرودخانه تأمین می گردد. شغل عمده ٔ اهالی زراعت و محصول عمده غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269225, 'هویس', '<span class=\"hlight\">هویس .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) اندیشه . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نهانی که در دل پنهان دارند. (منتهی الارب ). آنچه در دل مخفی دارند. (اقرب الموارد).<br></font></div>'),
(269226, 'هویش', '<span class=\"hlight\">هویش .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِ) هویت که تعین و تشخص بوده باشد. (انجمن آرا) (آنندراج ). رجوع به هویت شود.<br></font></div>'),
(269227, 'هویشم', '<span class=\"hlight\">هویشم .</span> <font color=\"DarkGreen\"><b>[ هَُ وَ ش ِ ]</font></b> (اِخ ) یکی از دهستانهای نهر هاشم بخش مرکزی شهرستان اهواز. دارای <span class=\"hlight\" dir=\"rtl\">١٢٠٠</span> تن سکنه، آب آن از چاه و محصول آن غلات دیمی و شغل اهالی زراعت و گله داری و صنایع دستی جوال بافی است . ساکنین از طایفه ٔ هویشم هستند. این طایفه در ساحل رودخانه ٔ کارون زراعت میکنند و در موقع بهار برای تعلیف به حدود باختری راه آهن میروند و چادرنشین هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269228, 'هوین', '<span class=\"hlight\">هوین .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است از دهستان چهاردانگه ٔ بخش هوراند شهرستان اهر، دارای <span class=\"hlight\" dir=\"rtl\">١٠٩</span> تن سکنه . (ازفرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269229, 'هویه', '<span class=\"hlight\">هویه .</span> <font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (اِ) هوبه . (برهان ). دوش و کتف .(آنندراج ) (برهان ). <BR><font color=\"Blue\">◄</font> پشتی و حمایت . (آنندراج ) (برهان ). هوبه . (برهان ). رجوع به هوبه شود.<br></font></div>'),
(269230, 'هویه سنبا', '<span class=\"hlight\">هویه سنبا.</span> <font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ سُم ْ ]</font></b> (نف مرکب ) سنباننده و سوراخ کننده ٔ شانه . <BR><font color=\"Blue\">◄</font> (اِخ ) لقبی است برای شاپور دوم ساسانی آنکه به ذوالاکتاف مشهور است . لقب شابوربن هرمز ساسانی از پادشاهان سلسله ٔ ساسانیان است . (هویه به معنی کتف و سنبا، ثقاب ). ذوالاکتاف . (یادداشت مؤلف از مجمل التواریخ ). این کلمه به صورت هوبر و هوبه هم ضبط شده . لقب شاپور ذوالاکتاف را هویه سنبا نوشته اند. حمزه ٔ اصفهانی در سنی ملوک الارض (ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>) آرد:شاپور ذوالاکتاف و سموه شاپور هویه سنبا. هویه اسم لکتف و سنبا ای نقاب . و در مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٣٤</span> آمده : و او را <font color=\"DarkGreen\"><b>[ شاپور را ]</font></b> عرب ذوالاکتاف لقب کردند زیرا کتفهای عرب سوراخ کرد و حلقه ٔ آهنین در آن کشید. بعد از آنکه بی اندازه قتل کرد پارسیان او را شاپورهویه سنبا خواندندی . کریستنسن (ایران در زمان ساسانیان چ <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦١</span> ح ) نویسد: مصنفین عرب که نوشته های آنها از منابع ساسانی اخذ شده به طور کلی لقب شاپور را به لفظ عربی ذوالاکتاف (صاحب شانه ها) ترجمه کرده اند. نلدکه بر این عقیده است که اصل این لفظ یک لقبی است به معنی چهارشانه یعنی کسی که بارهای بسیار دولت را می کشد معذلک حمزه ٔ اصفهانی و مصنفین دیگر که پیرو او هستند لفظ فارسی این لغت را هوبه سنبا نوشته اند که به معنی «سوراخ کننده ٔ شانه ها» است . نلدکه گمان میکند که این لفظ مجعول است و از روی کلمه ٔ عربی ذوالاکتاف ساخته شده است . اما اینکه بجای کلمه ٔ کتف لفظ عتیق فارسی یعنی هوبه را که به معنی شانه بود آورده اند به نظر من قول حمزه صحیح است و هوبه عیناً نقل از کلمه ٔ پهلوی شده و معنایی هم که از آن کرده اند مطابق روایات قدیم است، وانگهی در تاریخ ساسانیان این تنها نوبتی نیست که صحبت از این مجازات شده باشد. کلمه ٔ سنبا صفت فاعلی (صفت مشبهه ) از سنبیدن است به معنی سوراخ کردن . (حاشیه ٔ برهان چ معین ).<br></font></div>'),
(269231, 'هپاتیک', '<span class=\"hlight\">هپاتیک .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (فرانسوی، اِ) در اصطلاح گیاه شناسی نوعی از خزه است . هپاتیک ها رستنی هایی هستند بسیار شبیه به خزه ها ولی دستگاه زایشی آنها شکل مخصوصی دارد که با خزه ها متفاوت است . یکی از آنها مارکانسیا است که دستگاه رویشی آن ریسه ای است دارای کلروفیل بسیار که بوسیله ٔ کرکهای بسیار نرم به زمین متصل شده است . در موقع زایش فاصله به فاصله در سطح این ریسه، اعضایی شبیه به قارچ های چتری کوچک ساخته میشود. (گیاه شناسی حسین گل گلاب ص <span class=\"hlight\" dir=\"rtl\">١٥٩</span>).<br></font></div>'),
(269232, 'هپارلو', '<span class=\"hlight\">هپارلو.</span> <font color=\"DarkGreen\"><b>[ هَُ ل ُ ]</font></b> (فرانسوی، اِ) اُپارلو. این کلمه ترکیبی از «اُ» و پارلو است که در زبان فرانسه به معنی بلندگو میباشد و صادق هدایت آن را بهمین معنی در فارسی به کار برده است « <span class=\"hlight\">:</span> جلو آنها بلندگو یا هپارلو و پرده های متحرک اعلان میکردند». (سایه روشن صادق هدایت ص <span class=\"hlight\" dir=\"rtl\">١١</span>).<br></font></div>'),
(269233, 'هپاک', '<span class=\"hlight\">هپاک .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَُ ]</font></b> (اِ)فرق سر. تارک سر. (برهان ) (ناظم الاطباء) (لسان العجم ). هباک . چکاد. رجوع به هر یک از این مدخل ها شود.<br></font></div>'),
(269234, 'هپت', '<span class=\"hlight\">هپت .</span> <font color=\"DarkGreen\"><b>[ هََ ت َ]</font></b> (اوستائی، عدد، ص ) صورت اوستایی و فارسی باستان کلمه ٔ هفت است . (فرهنگ ایران باستان پورداود ص <span class=\"hlight\" dir=\"rtl\">٣١٥</span>).<br></font></div>'),
(269235, 'هپتال', '<span class=\"hlight\">هپتال .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) هفتال . هیتال . هیتل . هیطل . هپتالی . هفتالی . ج، هپتالان . هفتالان . هیاطلة. هپتالیان . هفتالیان . در بندهشن ایرانی : هفتالان . به ارمنی : هپتال . فارسی : هیتل . عربی : هیطل . مقایسه شود با بیلی بولتن شرقی، <span class=\"hlight\" dir=\"rtl\">٤</span> و <span class=\"hlight\" dir=\"rtl\">٦</span> (<span class=\"hlight\" dir=\"rtl\">١٩٣٢</span>)، ص <span class=\"hlight\" dir=\"rtl\">٩٤٦</span> و مابعد. نام قومی است که در زمان پیروز پادشاه ساسانی از ایالت کانسوی چین، به نواحی تخارستان که تازه کیداریان از آنجا رفته بودند، هجوم آوردند و پیروز را مغلوب و اسیر ساختند. برای اطلاع بیشتر رجوع به کلمه ٔ هپتالیان شود. قوم هپتال را «هونهای سفید» نیز نامیده اند. اما نمیتوان حقیقةً آنها را از اقوام هون شمردزیر به روایت پروکوپیوس این طایفه از حیث سفیدی پوست و زندگی مدنی، با اقوام هون اختلاف داشتند. و نیز بنا بر قول مارکوارت (ایرانشهر ص <span class=\"hlight\" dir=\"rtl\">٥٥</span> یادداشت <span class=\"hlight\" dir=\"rtl\">٨</span>) ابتدا خیونیان به اسم «هون سفید» خوانده میشدند و این عنوان بعداً به هپتالیان اطلاق شده است . چند سکه از هفتالیان در دست است که روی آن خطوطی با حروف کوشانی، که از الفبای یونانی مشتق شده، منقوش است . چند سکه هم به خط هندی معروف به براهمی موجود است . (ایران در زمان ساسانیان، کریستنسن، ترجمه ٔ رشید یاسمی ص <span class=\"hlight\" dir=\"rtl\">٣١٦</span>).<br></font></div>'),
(269236, 'هپتالی', '<span class=\"hlight\">هپتالی .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ص نسبی ) هفتالی . منسوب به هپتال یا هفتال که قومی ازایالت کانسوی چین بودند. رجوع به هپتال، هپتالیان، هفتال، هفتالیان، هیتل، هیتال، هیطل و هیاطله شود.<br></font></div>'),
(269237, 'هپتالیان', '<span class=\"hlight\">هپتالیان .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) هفتالیان . قومی بودند که از ایالت کانسوی چین به حدود تخارستان هجوم آوردند. پیروز پادشاه ساسانی که تازه از قلع و قمع کردن کیداریان پرداخته بود، به دفع آنان قیام کرد. اما مغلوب و اسیر شدو بناچار شهر طالقان را که قبل از غلبه ٔ او بر کیداریان شهر سرحدی مستحکمی بود بدیشان تسلیم کرد و متعهد شد که از آنجا تجاوز نکند و نیز مجبور شد با پرداخت غرامت جنگ، آزادی خود را بخرد. پسرش کواذ دو سال به عنوان گروگان در دربار پادشاه هفتالیان ماند تا تمام مبلغ پرداخته شد. بعد از آن پیروز با وجود ممانعت سپاهبذ وهرام مجدداً با هفتالیان وارد جنگ شد. این لشکرکشی در سال <span class=\"hlight\" dir=\"rtl\">٤٨٤</span> م . عاقبتی بس وخیم یافت، زیرا سپاه ایران که در بیابانی پیش میرفت، کاملاً مغلوب دشمن، بلکه معدوم گشت و پیروزبه قتل رسید و جسد او هرگز به دست نیامد. به موجب روایات مورخین عرب و ایران، این شاهنشاه با بسیاری ازسربازانش در حفره هایی که هفتالیان کنده بودند، افتادند. راست یا دروغ، این روایت بسیار قدیم است زیرا لازار فرپی، که از مؤلفین معاصر او بوده، به آن قصه اشاره کرده است . یکی از دختران پیروز به دست پادشاه هفتالیان  افتاد که او را به حرم خود فرستاد. هپتالیان داخل مملکت ایران شدند و چندین ایالت را با شهرهای مروالرود و هرات تصرف کردند و خراجی سالیانه بر ایرانیان تحمیل کردند. تسلط هفتالیان بر ایران موجد خواری و ذلت بسیار برای ایرانیان بود، و زیانها و خسارتهای مادی و معنوی جبران ناپذیری به بار آورد. بهمین مناسبت سردار ایرانی به نام گشنسپداذ ملقب به نخوارک که از طرف زرمهر مأمور مذاکره با ارمنیان شده بود، در ضمن صحبت خود با وهن  رئیس ارمنیان چنین گفت : «او (یعنی پیروز) کشوری چندان بزرگ و آبادان و مستقل را تسلیم هفتالیان کرد و تا تسلط این طایفه باقی است، کشور ایران از قید عبودیت و زنجیر هولناک اسارت نجات نخواهد یافت . بهترین افراد سپاه هلاک شده بودند و دولت در خزانه ٔ خود پولی که حقوق سپاهیان را کافی باشد نداشت . مورخان ایرانی نوشته اند که زرمهر از پادشاه هفتالیان انتقام کشید وعاقبت با آن طایفه صلحی شرافتمندانه کرد و پادشاه هفتالان تمام غنائمی را که در جنگ اخیر از پیروز گرفته بود پس داد و دختر او را نیز پس فرستاد. اما این موضوع درست بنظر نمی آید زیرا پادشاه هپتالیان از او دختری پیدا کرد که بعدها همسر قباد اول پادشاه ساسانی گردید . دولت هپتالیان تا حدود <span class=\"hlight\" dir=\"rtl\">٥٦٠</span> م . دوام داشت . در بین سالهای <span class=\"hlight\" dir=\"rtl\">٥٥٨</span> م . و <span class=\"hlight\" dir=\"rtl\">٥٦١</span> م . انوشیروان پادشاه ساسانی، این دولت را که بر اثر حمله ٔ یک قبیله ٔ ترک به سرداری سین جیبو (سیلزیبول ) متزلزل شده بود، برانداخت . (از ایران در زمان ساسانیان، کریستنسن، ترجمه ٔ رشید یاسمی ). و رجوع به هپتال، هفتال، هفتالان، هیتل، هیتال، هیطل و هیاطله شود.<br></font></div>'),
(269238, 'هپتن', '<span class=\"hlight\">هپتن .</span> <font color=\"DarkGreen\"><b>[ هََ ت َ ]</font></b> (عدد، ص ) به لغت زند به معنی هفت . (ناظم الاطباء).<br></font></div>'),
(269239, 'هپد', '<span class=\"hlight\">هپد.</span>  <font color=\"DarkGreen\"><b>[هََ ]</font></b> (اِ) دانه ٔ حنظل . (تحفه ٔ حکیم مؤمن ). هبد.<br></font></div>'),
(269240, 'هپد', '<span class=\"hlight\">هپد.</span> <font color=\"DarkGreen\"><b>[ هََ پ َ ]</font></b> (اِ) ماله ٔ برزگران . هبد. (ناظم الاطباء). ماله ای باشد که زمین شیار کرده شده را بدان هموار کنند و آن تخته ٔ بزرگی بود. (برهان ).<br></font></div>'),
(269241, 'هپر', '<span class=\"hlight\">هپر.</span> <font color=\"DarkGreen\"><b>[ هََ پ َ ]</font></b> (اِ)چرک . ریم . (برهان ) (ناظم الاطباء) (آنندراج ). هبر.<br></font></div>'),
(269242, 'هپرسی', '<span class=\"hlight\">هپرسی .</span> <font color=\"DarkGreen\"><b>[ هََ پ ِ رِ ]</font></b> (اوستایی، اِ) به لغت اوستائی، نام گیاهی است که سوزانیدن آن ممنوع بوده است . نوع این درخت امروز به درستی معلوم نیست . اما نظر به این که در آئین مزدیسنا چوب تر و بدبو را نباید در آتش گذاشت باید که هپرسی از نوع درختانی باشد که چوبشان هنگام سوختن بدبوست . (از یشتها ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣١</span>).<br></font></div>'),
(269243, 'هپرو', '<span class=\"hlight\">هپرو.</span> <font color=\"DarkGreen\"><b>[ هََ پ َ ]</font></b> (اِخ ) دهی است از دهستان میداود (سرگچ ) بخش جانکی گرمسیر شهرستان اهواز، واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی جنوب خاوری باغ ملک و <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی جنوب خاوری راه اتومبیل رو باغ ملک به ایذه . ناحیه ای است کوهستانی معتدل و مالاریایی و دارای <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> تن سکنه است .آب آن از رود و چشمه و محصولاتش غلات و برنج میباشد. اهالی به زراعت مشغولند. راه مالرو دارد. ساکنین آن از طایفه ٔ ممبینی هستند. معدن گچ در آنجا وجود دارد.این آبادی از محلهای کله پیر، دورتو، پس کره و سرسورد تشکیل شده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269244, 'هپرو', '<span class=\"hlight\">هپرو.</span> <font color=\"DarkGreen\"><b>[ هََ پ َ ]</font></b> (اِ) در تداول عامه، قاپیدن .ربودن چیزی از دست کسی . و رجوع به هپرو کردن شود.<br></font></div>'),
(269245, 'هپرو کردن', '<span class=\"hlight\">هپرو کردن .</span> <font color=\"DarkGreen\"><b>[ هََ پ َ ک َ دَ ]</font></b> (مص مرکب ) در تداول عامه، به غصب و دزدی چیزی را متصرف شدن . خوردن مال کسی . (یادداشت مؤلف ). به یغما بردن . غارت کردن .<br></font></div>'),
(269246, 'هپروت', '<span class=\"hlight\">هپروت .</span> <font color=\"DarkGreen\"><b>[ هََ پ َ ]</font></b> (اِ) کلمه ٔ منحوت بر وزن جبروت و ملکوت، که از آن افکار پریشان و مالیخولیایی بنگیان و حشیشیان را اراده کنند. (یادداشت مؤلف ).<br>- <span class=\"hlight\">در عالم هپروت سیر کردن </span> ؛ افکاری چون افکار حشیش و بنگ کشیدگان پروردن . خیالاتی چون خیالات چرسیان و بنگیان کردن . خیالات واهی داشتن : او در عالم هپروت سیر میکند. (یادداشت مؤلف ).<br>- <span class=\"hlight\">عالم هپروت </span> ؛ در تداول عامه، دنیای واهی و خیالی محض .<br></font></div>'),
(269247, 'هپروتی', '<span class=\"hlight\">هپروتی .</span> <font color=\"DarkGreen\"><b>[ هََ پ َ ]</font></b> (ص نسبی ) منسوب به هپروت، که کلمه ای است ساختگی . رجوع به هپروت شود.<br>- <span class=\"hlight\">خیالات هپروتی </span> ؛به معنی واهی و غیر معقول که هیچ نوع مخرج عقلانی ندارند.<br></font></div>'),
(269248, 'هپل هپو', '<span class=\"hlight\">هپل هپو.</span> <font color=\"DarkGreen\"><b>[ هََ پ َ هََ ]</font></b> (ص مرکب )در تداول عامه، بی ترتیب و بی قانون . (فرهنگ نظام ).<br></font></div>'),
(269249, 'هپلیت', '<span class=\"hlight\">هپلیت .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (فرانسوی، اِ) نوعی از بی مهرگانند که دارای غلاف فسیلی می باشند و در طبقات گل سفید یافت میشوند. نزدیک به پنجاه نوع از آنها شناخته شده است . (از لاروس ).<br></font></div>'),
(269250, 'هپلیت', '<span class=\"hlight\">هپلیت .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (یونانی، اِ) اصل این کلمه یونانی است و در آن زبان به معنی سلاح و ساز و برگ کامل میباشد، ولی در یونان باستان به پیاده نظام سنگین اسلحه اطلاق میشده است . هپلیت ها دارای اسلحه ٔ کامل بودند و آنان را کلاه خودی با تاج گل بود و زرهی سرخ رنگ با زانوبند و شمشیر و نیزه، به تن داشتند. هر هپلیت، امربری داشت که به هنگام خدمت، غذا و سلاح جنگی وی را حمل میکرد. (از لاروس ).<br></font></div>'),
(269251, 'هپولو', '<span class=\"hlight\">هپولو.</span> <font color=\"DarkGreen\"><b>[ هَُ پ ُ ]</font></b> (اِخ ) ده کوچکی است از دهستان انگالی بخش برازجان شهرستان بوشهرکه در <span class=\"hlight\" dir=\"rtl\">٢٧</span> هزارگزی باختر برازجان واقع شده و دارای <span class=\"hlight\" dir=\"rtl\">٣٤</span> تن سکنه میباشد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(269252, 'هپوک', '<span class=\"hlight\">هپوک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) نامی است که در مازندران به سنای کاذب دهند. دغدغک . (یادداشت مؤلف ). رجوع به سنای کاذب شود.<br></font></div>'),
(269253, 'هپی', '<span class=\"hlight\">هپی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از دهستان سراجو بخش مرکزی شهرستان مراغه که در <span class=\"hlight\" dir=\"rtl\">٣٤</span> هزارگزی جنوب خاوری مراغه و <span class=\"hlight\" dir=\"rtl\">١٨/٥</span> هزارگزی جنوب باختری شوسه ٔ مراغه به میانه واقع شده . منطقه ای است کوهستانی و دارای هوای معتدل سالم میباشد. جمعیت آن <span class=\"hlight\" dir=\"rtl\">١٦٥</span> تن ترک زبان است . از چشمه مشروب میشود و محصولاتش غلات میباشد. شغل اهالی زراعت و صنایع دستی آنان جاجیم بافی است . راه مالرو دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269254, 'هپیون', '<span class=\"hlight\">هپیون .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ)تریاک . افیون . (برهان ) (آنندراج ). هبیون . (ناظم الاطباء). ابیون . اپیون . از یونانی اُپیُون  مبدل اپوس، لاتینی اپیوم  (به معنی مایع)، و آن شیره ٔ بسته ٔ تخمدانهای نارس خشخاش است . (ازبرهان چ معین حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">٨٦</span>، ذیل : اپیون ) <span class=\"hlight\">:</span> <br>آن فلسفه است و این سخن دینی <br>این شکر است و فلسفه هپیون است .<br> <font color=\"Red\">ناصرخسرو.</font><br>علم است کیمیای بزرگیها<br>شکر کندت اگر همه هپیونی .<br> <font color=\"Red\">ناصرخسرو.</font><br>اینْت نسازد همی مگر همه شکّر<br>وانْت نسازد همی مگر همه هپیون .<br> <font color=\"Red\">ناصرخسرو.</font><br>چه حال است این که مدهوشند یکسر<br>که پنداری که خوردستند هپیون .<br> <font color=\"Red\">ناصرخسرو.</font><br>داد کن ار نام نیک خواهی ازیراک <br>عقل ترا هزل دشمن است چو هپیون .<br> <font color=\"Red\">ناصرخسرو.</font><br>و رجوع به افیون و هبیون شود.<br></font></div>'),
(269255, 'هچ', '<span class=\"hlight\">هچ .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b>(اِ) هج . راست باز کردن چیزی باشد مانند علم و نیزه و ستون و امثال آن . (برهان ). راست بازکردن بود چیزی را چون علم یا نیزه . (اسدی ). راست ایستادن چیزی را نیز گویند بر زمین . (برهان ). و اگر چیزی بر زمین افکنی راست بایستد گویند «هج کرد». (اسدی ) <span class=\"hlight\">:</span> <br>گردون علم محنت بر بام تو هج کرد<br>بینی سخط خویش به کوس و علم اندر.<br><font color=\"Red\">منجیک ترمذی .</font><br></font></div>'),
(269256, 'هچ و مچ', '<span class=\"hlight\">هچ و مچ .</span> <font color=\"DarkGreen\"><b>[ هََ چ ْ چ ُ م َ ]</font></b> (اِ صوت ) آواز بوسه . (آنندراج ) <span class=\"hlight\">:</span> <br>شنیدم از درعشرت سرا که خوش کوک است <br>نوای هچ و مچ بوسه با غزل خوانی .<br><font color=\"Red\">ملافوقی یزدی (از آنندراج ).</font><br></font></div>'),
(269257, 'هچدسپ', '<span class=\"hlight\">هچدسپ .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (اِخ ) هئچت اسپ . رجوع به هئچت اسپ شود.<br></font></div>'),
(269258, 'هچرود', '<span class=\"hlight\">هچرود.</span> <font color=\"DarkGreen\"><b>[ هََ چ ِ ]</font></b> (اِخ ) دهی است از دهستان قشلاق کلارستاق بخش چالوس شهرستان نوشهر، واقع در نه هزارگزی باختر چالوس و کنار راه شوسه ٔ چالوس به شهسوار که در کنار دریا قرار دارد. ناحیه ای است دشت، معتدل، مرطوب و دارای <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن سکنه . از رودخانه ٔ سرداب رود مشروب میشود. محصولش برنج و لبنیات است . شغل اهالی کشاروزی است . دبستان دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(269259, 'هچل', '<span class=\"hlight\">هچل .</span> <font color=\"DarkGreen\"><b>[ هََ چ َ ]</font></b> (اِ) در تداول عوام، مخمصه . کش و واکش . (یادداشت به خط مؤلف ).<br>- <span class=\"hlight\">در هچل افتادن </span> ؛ گرفتار شدن . (یادداشت به خط مؤلف ).<br>- <span class=\"hlight\">در هچل افتادن کسی یا پولی </span> ؛ گرفتار شدن شخص یا از دست رفتن پول چنانکه بازگردانیدنش دشوار بود، یا وصول آن ممتنع باشد. (یادداشت به خط مؤلف ).<br>- <span class=\"hlight\">در هچل انداختن </span> ؛ گرفتار ساختن و یا قرض دادن پول در محلی که صعب الوصول باشد. (یادداشت به خط مؤلف ).<br></font></div>'),
(269260, 'هچوکان', '<span class=\"hlight\">هچوکان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی است از طسوج ابرشتجان . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>).<br></font></div>'),
(269261, 'هچکاره', '<span class=\"hlight\">هچکاره .</span> <font color=\"DarkGreen\"><b>[ هَِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص مرکب ) مخفف هیچکاره . (آنندراج ). رجوع به هیچکاره شود.<br></font></div>'),
(269262, 'هژبر', '<span class=\"hlight\">هژبر.</span> <font color=\"DarkGreen\"><b>[ هَِ ژَ <span class=\"hlight\" dir=\"rtl\">/</span> هَُ ژَ ]</font></b> (اِ) مصحف هِزَبر است به معنی شیر. رجوع به هزبر شود.<br></font></div>'),
(269263, 'هژده', '<span class=\"hlight\">هژده .</span> <font color=\"DarkGreen\"><b>[ هَِ دَه ْ ]</font></b> (عدد، ص، اِ) هیجده . هشتده . (از حاشیه ٔ برهان چ معین ). ده به علاوه ٔ هشت . (از ناظم الاطباء). هیجده . عددی ماقبل نوزده و پس از هفده <span class=\"hlight\">:</span> چون یزدجرد جوان مرد از پس او هژده سال این هرمز برادر کهتر که پیش پدر بود ملک بگرفت . (تاریخ بلعمی ).<br>مرا بود هژده پسر در جهان <br>از ایشان یکی مانده است این زمان .<br> <font color=\"Red\">فردوسی .</font><br>پس بدان کاین حساب باریک است <br>چونکه هفده به هژده نزدیک است .<br> <font color=\"Red\">سنائی .</font><br>عالم خلقت ز غیب هژده هزار آمده ست <br>عالم اعظم تویی از پس هژده هزار.<br><font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">هژده هزار عالم </span> . رجوع به هژده هزار عالم شود.<br></font></div>'),
(269264, 'هژده هزار عالم', '<span class=\"hlight\">هژده هزار عالم .</span> <font color=\"DarkGreen\"><b>[ هَِ دَه ْ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ل َ]</font></b> (اِ مرکب ) صاحب بصائر آورده است که در هر ربعی ازارباع عالم از شرقی و غربی و جنوبی و شمالی چهارهزاروپانصد عالم است که مجموع هژده هزار باشد، و در خلافةالمناقب از سیدعلی همدانی مذکور است که عالم سیصدوشصت هزار باشد، و بعضی گویند هفتادهزار، بعضی هژده عالم گویند چنانکه : عقلیه و نوریه و روحیه و نفسیه و تعبیه و جسمیه و عنصریه و مثالیه و خیالیه و برزخیه و حشریه و جنانیه و جهنمیه و اعرافیه و رؤیتیه و صوریه و جمالیه و کمالیه . مجموع این عوالم در دو عالم ظاهر و باطن، که غیب و شهادت است، مندرج است . و بعضی چنین نوشته اند که عالم عقول و عالم ارواح و عالم افلاک که نُه است و عالم عناصر که چهار است و عالم موالیدکه سه باشد، مجموع هژده می شود. (از غیاث اللغات ).<br></font></div>'),
(269265, 'هژدهم', '<span class=\"hlight\">هژدهم .</span> <font color=\"DarkGreen\"><b>[ هَِدَ هَُ ]</font></b> (عدد ترتیبی، ص نسبی ) چیزی که در مرتبه ٔ هژده واقع گردد. (ناظم الاطباء). هجدهم . هیجدهم <span class=\"hlight\">:</span> امیر سه شنبه هژدهم شهر جمادی الاولی در این صفه ٔ نو خواهد نشست . (تاریخ بیهقی ). رجوع به هژده شود.<br></font></div>'),
(269266, 'هژزیسترات', '<span class=\"hlight\">هژزیسترات .</span> <font color=\"DarkGreen\"><b>[ هَِ ژِ ]</font></b> (اِخ ) غیب گوی یونانی معاصر خشایارشا. وی اهل اله  بود و چون اسپارتیها را از خود آزرده بود او را اسیر کرده بودند و اوبا یک عمل حیرت انگیز از زندان گریخته بود، بدین معنی که با آهن پاره ای پاشنه ٔ پای خود را برید و پایش رااز کُند زنجیر نجات داد و از زندان گریخت . (نقل به اختصار از تاریخ ایران باستان پیرنیا ص <span class=\"hlight\" dir=\"rtl\">٨٤٦</span> و <span class=\"hlight\" dir=\"rtl\">٨٤٧</span>).<br></font></div>'),
(269267, 'هژلوخ', '<span class=\"hlight\">هژلوخ .</span> <font color=\"DarkGreen\"><b>[ هَِ ژِ ]</font></b> (اِخ ) هژلوک .از سرداران اسکندر. (ایران باستان پیرنیا ص <span class=\"hlight\" dir=\"rtl\">١٢٨٤</span>).<br></font></div>'),
(269268, 'هژلوک', '<span class=\"hlight\">هژلوک .</span> <font color=\"DarkGreen\"><b>[ هَِ ژِ ]</font></b> (اِخ ) رجوع به هژلوخ شود.<br></font></div>'),
(269269, 'هژهار', '<span class=\"hlight\">هژهار.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ)نوعی از علتهای اسبان، و آن دندان زیادتی باشد مر اسب را که تا آن را نشکنند یا نکنند اسب علف را به فراغت نمیتواند خورد و فربه نمیشود. (برهان ) (رشیدی ).<br></font></div>'),
(269270, 'هژیر', '<span class=\"hlight\">هژیر.</span> <font color=\"DarkGreen\"><b>[ هَُ <span class=\"hlight\" dir=\"rtl\">/</span> هََ ]</font></b> (ص ) نیکو. (اسدی ).ستوده و پسندیده و خوب و نیک . (برهان ) <span class=\"hlight\">:</span> <br>از ایرانیان هرکه مرد است پیر <br>که شان بند کردن نباشد هژیر.<br> <font color=\"Red\">دقیقی (دیوان چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">٣٧</span>).</font><br>به شاه جهان گفت زردشت پیر<br>که در دین ما این نباشد هژیر.<br> <font color=\"Red\">دقیقی .</font><br>یکی نامه بنوشت خوب و هژیر<br>سوی نامور خسرو دین پذیر.<br> <font color=\"Red\">دقیقی .</font><br>بگشتند هر دو سوار هژیر<br>به گرز و به نیزه، به شمشیر و تیر.<br> <font color=\"Red\">فردوسی .</font><br>نوروز فرخ آمد و نغز آمدو هژیر<br>با طالع سعادت و با کوکب منیر.<br> <font color=\"Red\">منوچهری .</font><br>شهری است پربشارت از این کار و هر کسی <br>سازد همی ز جان و ز دل هدیه ٔ هژیر.<br> <font color=\"Red\">فرخی .</font><br>خاطر و دست تو دبیرانند<br>اینْت کاری بزرگوار و هژیر.<br> <font color=\"Red\">ناصرخسرو.</font><br> <BR><font color=\"Blue\">◄</font> زیبا. خوب چهره . خوبروی <span class=\"hlight\">:</span> <br>دریغ آن سر تخمه ٔ اردشیر<br>دریغ آن سوار جوان هژیر.<br> <font color=\"Red\">فردوسی .</font><br>دست به می شاه را و دل به هژیران <br>دیده به روی نکو و گوش به قوال .<br> <font color=\"Red\">منوچهری .</font><br>خمّیده گشت و سست شدآن قامت چو سرو<br>بی نور ماند و زشت شد آن طلعت هژیر.<br> <font color=\"Red\">ناصرخسرو.</font><br>هژیرت سخن باید ای میرگیر<br>نباشد چه باک است رویت هژیر؟<br> <font color=\"Red\">ناصرخسرو.</font><br><BR><font color=\"Blue\">◄</font> (اِ) جلدی و چابکی . (برهان ). در این معنی هم صفت است به معنی جلد و چابک، نه جلدی و چابکی . <BR><font color=\"Blue\">◄</font> هوشیاری . (برهان ). هوشیار.<br></font></div>'),
(269271, 'هژیره', '<span class=\"hlight\">هژیره .</span> <font color=\"DarkGreen\"><b>[ هََ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) شایستگی و لیاقت . <BR><font color=\"Blue\">◄</font> هرچیز که آن را محترم دارند و خاصگی . <BR><font color=\"Blue\">◄</font> زیبائی . <BR><font color=\"Blue\">◄</font> جلدی و چابکی . <BR><font color=\"Blue\">◄</font> هوشیاری . <BR><font color=\"Blue\">◄</font> (ص ) ستوده و پسندیده و مطبوع و خوب و نیک و سزاوار ستایش . (ناظم الاطباء).<br></font></div>'),
(269272, 'هژینه', '<span class=\"hlight\">هژینه .</span> <font color=\"DarkGreen\"><b>[ هََ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ]</font></b> (اِ) هزینه . (ناظم الاطباء). رجوع به هزینه شود.<br></font></div>'),
(269273, 'هک', '<span class=\"hlight\">هک .</span> <font color=\"DarkGreen\"><b>[ هََ ک ک ]</font></b>(ع مص ) به شمشیر زدن کسی را. <BR><font color=\"Blue\">◄</font> دریافتن کسی را بگنی . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> افکنده شدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> تیزدادن . <BR><font color=\"Blue\">◄</font> پیخال انداختن مرغ و شترمرغ . <BR><font color=\"Blue\">◄</font> سائیدن چیزی را. <BR><font color=\"Blue\">◄</font> برآوردن شیر را. (منتهی الارب ) (از اقرب الموارد). دوشیدن شیر. <BR><font color=\"Blue\">◄</font> چیره شدن بر کسی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> لاغر کردن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخت گاییدن . <BR><font color=\"Blue\">◄</font> بسیار گاییدن .(منتهی الارب ). <BR><font color=\"Blue\">◄</font> پیاپی نیزه زدن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فرودریدن چاه . <BR><font color=\"Blue\">◄</font> سرگین انداختن شوات . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) مرد تباه خرد. ج، هککة، اهکاک . <BR><font color=\"Blue\">◄</font> باران سخت . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269274, 'هکات', '<span class=\"hlight\">هکات .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) به اصطلاح یونانیان، ربةالنوع شکار. (از تعلیقات نصراﷲ فلسفی بر ترجمه ٔ تمدن قدیم فوستل دُ کولانژ).<br></font></div>'),
(269275, 'هکاته', '<span class=\"hlight\">هکاته .</span> <font color=\"DarkGreen\"><b>[ هَِ ت ِ ]</font></b> (اِخ ) از مورخان یونانی قرن ششم ق . م . است که از اهالی می لث بوده و آثار وی بر جای نمانده است . (از ایران باستان پیرنیا ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>).<br></font></div>'),
(269276, 'هکارس', '<span class=\"hlight\">هکارس .</span> <font color=\"DarkGreen\"><b>[ هََرِ ]</font></b> (ع اِ) غوکان . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269277, 'هکاری', '<span class=\"hlight\">هکاری .</span> <font color=\"DarkGreen\"><b>[ هََ ک ْ کا ]</font></b> (ص نسبی ) منسوب به هکاریه که بلده و ناحیه ای است در بالای موصل . (سمعانی ).<br></font></div>'),
(269278, 'هکاع', '<span class=\"hlight\">هکاع .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع اِ) سرفه . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خواب که بعدِ ماندگی آید، و خواهانی جماع از اینجاست . (منتهی الارب ). خواب پس از تعب . (اقرب الموارد).<br></font></div>'),
(269279, 'هکان', '<span class=\"hlight\">هکان .</span> <font color=\"DarkGreen\"><b>[ هََ ک ْ کا ]</font></b> (اِخ ) نام یکی از دهستانهای سه گانه ٔ بخش کوهک شهرستان جهرم است که در باختر بخش در تنگ هکان واقع گردیده و هوای آن گرم و آب مشروب دهستان از باران است و در آب انبارها نگهداری میشود. یک چشمه ٔ آب شیرین هم در چهارهزارگزی دهستان وجود دارد. محصول عمده ٔ بخش غله، خرما، برنج، لیمو و تنباکوی معروف هکان است که به مرغوبیت شهرت دارد. این دهستان از سه آبادی قلات و کناردان و دهکده تشکیل شده و جمعاً <span class=\"hlight\" dir=\"rtl\">١١٠٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(269280, 'هکب', '<span class=\"hlight\">هکب .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> هََ ]</font></b> (ع مص ) فسوس کردن . (منتهی الارب ).<br></font></div>'),
(269281, 'هکتار', '<span class=\"hlight\">هکتار.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (فرانسوی، اِ) واحد سطح برابربا ده هزار متر مربع. (از یادداشتهای مؤلف ). معمولاًواحد سنجش زمین به خصوص در مورد اراضی زراعتی است .<br></font></div>'),
(269282, 'هکتور', '<span class=\"hlight\">هکتور.</span> <font color=\"DarkGreen\"><b>[ هَِ تُرْ ]</font></b> (اِخ ) پسر فیلوناس سردار معروف اسکندر. (از ایران باستان پیرنیا ص <span class=\"hlight\" dir=\"rtl\">١٣٥١</span> و <span class=\"hlight\" dir=\"rtl\">١٦٦٣</span>).<br></font></div>'),
(269283, 'هکذا', '<span class=\"hlight\">هکذا.</span> <font color=\"DarkGreen\"><b>[ها ک َ ]</font></b> (ع ق مرکب ) همچنین . (آنندراج ) (از غیاث ).<br></font></div>'),
(269284, 'هکذی', '<span class=\"hlight\">هکذی .</span> <font color=\"DarkGreen\"><b>[ ها ک َ ]</font></b> (از ع، ق مرکب ) هکذا. رجوع به هکذا شود <span class=\"hlight\">:</span> <br>از حکیمان خراسان کو شهید و رودکی <br>بوشکور بلخی و بوالفتح بُستی هکذی .<br><font color=\"Red\">منوچهری .</font><br></font></div>'),
(269285, 'هکر', '<span class=\"hlight\">هکر.</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هََ ک َ ]</font></b> (ع مص ) سخت شدن خواب . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چرت و پینکی گرفتن کسی را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخت شگفت داشتن . (از منتهی الارب ).<br></font></div>'),
(269286, 'هکر', '<span class=\"hlight\">هکر.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) شگفت داشتن . (منتهی الارب ). سخت عجب داشتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرفتن پینکی کسی را. (منتهی الارب ).<br></font></div>'),
(269287, 'هکر', '<span class=\"hlight\">هکر.</span> <font color=\"DarkGreen\"><b>[ هََ ک ِ ]</font></b> (ع ص ) غنوده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خواب آلوده . <BR><font color=\"Blue\">◄</font> نیک شگفت دارنده . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269288, 'هکر', '<span class=\"hlight\">هکر.</span> <font color=\"DarkGreen\"><b>[ هََ ک ُ ]</font></b> (ع ص ) غنوده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خواب آلوده . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269289, 'هکری', '<span class=\"hlight\">هکری .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِ) دیمه را گویند، و آن زراعتی است که به آب باران حاصل شود. (برهان ). بخس نیز گویند. (انجمن آرا).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(269290, 'هکع', '<span class=\"hlight\">هکع.</span> <font color=\"DarkGreen\"><b>[ هََ ک َ ]</font></b> (ع مص ) ناشکیبا گشتن . (منتهی الارب ). جزع . <BR><font color=\"Blue\">◄</font> خوار شدن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> فروتنی نمودن . (منتهی الارب ). خشوع . (از اقرب الموارد).<br></font></div>'),
(269291, 'هکف', '<span class=\"hlight\">هکف .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ ]</font></b> (ع مص ) شتابی کردن در رفتن یا دویدن . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269292, 'هکل', '<span class=\"hlight\">هکل .</span> <font color=\"DarkGreen\"><b>[ هَُ ک َ ]</font></b> (اِ) سماروغ را گویند، و آن رستنیی باشد که از جاهای نمناک و زیر خمهای آب و شراب و سرکه و مانند آن روید. گویند هرکه آن را در محل جنابت و ناپاکی خورد نسل وی منقطع گردد یعنی او را فرزند نشود، و آن را به عربی بنات الرعد خوانند. (آنندراج ). فقع. (فهرست مخزن الادویه ).<br></font></div>'),
(269293, 'هکلس', '<span class=\"hlight\">هکلس .</span> <font color=\"DarkGreen\"><b>[ هََ ک َل ْ ل َ ]</font></b> (ع ص ) درشت استوار. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شدید. (اقرب الموارد).<br></font></div>'),
(269294, 'هکم', '<span class=\"hlight\">هکم .</span> <font color=\"DarkGreen\"><b>[ هََ ک ِ ]</font></b> (ع ص ) مرد بد. (منتهی الارب ). کسی که به بدی خویش بر مردم تعرض کند. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بی باکانه در کار بی فایده درآینده . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269295, 'هکمه وار', '<span class=\"hlight\">هکمه وار.</span> <font color=\"DarkGreen\"><b>[ هَُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) قطعه زمینی که در آن سبزی کاری کنند. (یادداشت مؤلف ).<br></font></div>'),
(269296, 'هکه', '<span class=\"hlight\">هکه .</span> <font color=\"DarkGreen\"><b>[ هَُ ک ْ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (اِ) مخفف هکچه . (انجمن آرا). به معنی هکک است که جَستن گلو و فواق باشد. (برهان ). سکسکه . زغنگ . فواق . در زبان فرانسه به همین صورت  مأخوذ ازفارسی است . (یادداشت مؤلف ). و رجوع به هکچه شود.<br></font></div>'),
(269297, 'هکهاک', '<span class=\"hlight\">هکهاک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) بسیار گاینده . (منتهی الارب ).<br></font></div>'),
(269298, 'هکهک', '<span class=\"hlight\">هکهک .</span> <font color=\"DarkGreen\"><b>[ هَُ هَُ ]</font></b> (اِ صوت )آواز گریه که در گلو باشد. (انجمن آرا) <span class=\"hlight\">:</span> <br>صوفیا قرّابه از می هکهک گریه گشاد<br>گریه ٔخونین او در سجده گاه او ببین .<br> <font color=\"Red\">امیرخسرو.</font><br>رجوع به هق هق شود.<br></font></div>'),
(269299, 'هکوان', '<span class=\"hlight\">هکوان .</span> <font color=\"DarkGreen\"><b>[ هََ ک ْ ]</font></b> (اِخ ) دهی است از بخش سروستان شهرستان شیراز که <span class=\"hlight\" dir=\"rtl\">١٤٠</span> تن سکنه دارد. آب آن از چشمه و قنات و محصول عمده اش غله، برنج، حبوب و میوه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(269300, 'هکوبا', '<span class=\"hlight\">هکوبا.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دختر سی سیه ئوس پادشاه تراکس و زن پریاموس بوده، ازوی <span class=\"hlight\" dir=\"rtl\">١٩</span> فرزند آورد لکن فرزندان او تقریباً جملگی در محاصره ٔ ترژا به هلاکت رسیدند. بنابر افسانه های یونان هکوبا سرانجام به صورت سگی درآمده است . (از تعلیقات نصراﷲ فلسفی بر ترجمه ٔ تمدن قدیم فوستل دُ کولانژ).<br></font></div>'),
(269301, 'هکوع', '<span class=\"hlight\">هکوع .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع مص ) آرمیدن زیر درخت و جای گرفتن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فرودآمدن به قوم بعدِ شام . (منتهی الارب ). فرودآمدن به قوم پس از فرارسیدن شامگاه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نگونسار افتادن بر زمین . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رفتن . یقال :ماادری أین هکع؛ یعنی نمیدانم کجا رفت . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> سرفیدن شتر. (منتهی الارب ). این معنی در اقرب الموارد برای مصدر هکع و هکاع آمده است . <BR><font color=\"Blue\">◄</font> فروهشتن شب تاریکی خود را. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> باز شکسته شدن استخوان بعدِ درستی . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269302, 'هکوک', '<span class=\"hlight\">هکوک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) مرد شوخ بی باک شتاب زده . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269303, 'هکوک', '<span class=\"hlight\">هکوک .</span> <font color=\"DarkGreen\"><b>[ هََ ک َوْ وَ ]</font></b> (ع ص ) جای درشت سخت . <BR><font color=\"Blue\">◄</font> جای آسان نرم . <BR><font color=\"Blue\">◄</font> فربه . <BR><font color=\"Blue\">◄</font> مرد شوخ چشم بی باک شتاب زده . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269304, 'هکوی', '<span class=\"hlight\">هکوی .</span> <font color=\"DarkGreen\"><b>[ هََ ک ْ <span class=\"hlight\" dir=\"rtl\">/</span> هََ ]</font></b> (ص ) سرگشته و متردد، در نسخه ٔ سروری به فتح هاء و ضم کاف به معنی تردد آمده است . (انجمن آرا). سرگشته و حیران و پریشان . (برهان ).<br></font></div>'),
(269305, 'هکوی', '<span class=\"hlight\">هکوی .</span> <font color=\"DarkGreen\"><b>[ هََ ک ْ ]</font></b> (اِ) شراب . (انجمن آرا). شراب انگوری . (برهان ). <BR><font color=\"Blue\">◄</font> تردد. (برهان ) (سروری ). <BR><font color=\"Blue\">◄</font> خربزه ٔ نارسیده . (انجمن آرا).<br></font></div>'),
(269306, 'هکچه', '<span class=\"hlight\">هکچه .</span> <font color=\"DarkGreen\"><b>[ هَُ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ) جستن گلو را گویند، و به عربی فواق خوانند. (برهان ). و به پارسی هکک نیز نامند، و این حالت از امتلاء و پُری معده روی دهد. (انجمن آرا). رجوع به فواق و سکسکه شود.<br></font></div>'),
(269307, 'هکک', '<span class=\"hlight\">هکک .</span> <font color=\"DarkGreen\"><b>[ هَُ ک َ ]</font></b> (اِ) به معنی هکچه که جستن گلوباشد، و به عربی فواق خوانند. (برهان ) <span class=\"hlight\">:</span> <br>زآب سنان به سینه ٔ دشمن فرونشان <br>چون زامتلای خون دل او را هکک بود.<br><font color=\"Red\">امیرخسرو.</font><br></font></div>'),
(269308, 'هکک', '<span class=\"hlight\">هکک .</span> <font color=\"DarkGreen\"><b>[ هَِ ک َ ]</font></b> (اِ) چیزی را گویند مانند کجاوه . (برهان ).<br></font></div>'),
(269309, 'هکی', '<span class=\"hlight\">هکی .</span> <font color=\"DarkGreen\"><b>[ هََ ک ْ کی ]</font></b> (اِخ ) دهی است از بخش سلوانا از شهرستان ارومیه که <span class=\"hlight\" dir=\"rtl\">١٣٠</span> تن سکنه دارد. آب آن از کوهستان و محصول عمده اش غله و توتون و کاردستی مردم جاجیم بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269310, 'هکیدن', '<span class=\"hlight\">هکیدن .</span> <font color=\"DarkGreen\"><b>[ هَُ دَ ]</font></b> (مص ) سکسکه کردن . هکه کردن . (یادداشتهای مؤلف ). رجوع به هکه شود.<br></font></div>'),
(269311, 'هکیک', '<span class=\"hlight\">هکیک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) سرگین انداختن شوات . <BR><font color=\"Blue\">◄</font> (ص ) مخنث . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269312, 'هگرز', '<span class=\"hlight\">هگرز.</span> <font color=\"DarkGreen\"><b>[ هََ گ َ <span class=\"hlight\" dir=\"rtl\">/</span> گ ِ ]</font></b> (ق ) هرگز. هرگیز. هیچوقت . هیچگاه . ابدا. (یادداشتهای مؤلف ) <span class=\"hlight\">:</span> <br>چنان نبینی تا دل نکرده کار هگرز<br>به چوب رام شود، یوغ را نهد گردن .<br> <font color=\"Red\">اورمزدی .</font><br>همتی دارد بررفته به جایی که هگرز<br>نیست ممکن که رسد طاقت مخلوق بر آن .<br> <font color=\"Red\">فرخی .</font><br>بزرگی و نیکی نیابد هگرز<br>کسی کاو به بد بود همداستان .<br> <font color=\"Red\">فرخی .</font><br>بگذاراد و به روی تو میاراد هگرز<br>زلتی را که نکردی تو بدان استغفار.<br> <font color=\"Red\">فرخی .</font><br>نیابد هگرز آن سه مهمان چهارم <br>نه این دو کبوتر بیابد سدیگر.<br> <font color=\"Red\">ناصرخسرو.</font><br>من دست خویش در رسن دین حق زدم <br>از تو هگرز جُست نخواهم نشان و نام .<br> <font color=\"Red\">ناصرخسرو.</font><br>با آز هگرز دین نیامیزد<br>تو رانده ز دین به لشکر آزی .<br> <font color=\"Red\">ناصرخسرو.</font><br>مرا نشانه ٔ تیر فراق کرد و هگرز<br>کسی شنیده بباشد کمان نشانه ٔ تیر؟<br><font color=\"Red\">مسعودسعد.</font><br></font></div>'),
(269313, 'هگمتان', '<span class=\"hlight\">هگمتان .</span> <font color=\"DarkGreen\"><b>[ هَِ م َ ]</font></b> (اِخ ) نامی است که مادها به پایتخت خود یعنی همدان کنونی داده اند. رجوع به ایران باستان ص <span class=\"hlight\" dir=\"rtl\">١٤٩١</span> و نیز رجوع به مدخل همدان و هنگمتان شود.<br></font></div>'),
(269314, 'هی', '<span class=\"hlight\">هی .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (صوت ) کلمه ای است که بجهت آگاهانیدن و خبردار گردانیدن در مقام تهدید و تخویف و زجر و استهزا گویند و گاهی در مقام تحسین هم گفته اند. (برهان ). کلمه ٔ تنبیه است که برای آگاه کردن گویند و گاهی در مقام تحسین آید. و به معنی افسوس و زجر نیز آمده . (غیاث اللغات ). هی کلمه ای است که بدان تهدید کنند و از کار بازدارند و از برای تنبیه بود اعنی آگاهانیدن . (صحاح الفرس ) <span class=\"hlight\">:</span> <br>هینی بگاه جنگ به تک خاسته ز کوه <br>هین بزرگ بازنگردد به هین و هی .<br> <font color=\"Red\">منوچهری .</font><br>گفت هی کیستی که دلشادی <br>برنشسته به مرکب بادی .<br> <font color=\"Red\">سنایی .</font><br>بانگ زد بر ساقی مجلس که هی <br>می بیار و می بیار و باز می .<br> <font color=\"Red\">مولوی .</font><br>آن یکی میگفت اشتر را که هی <br>از کجا می آیی ای اقبال پی .<br> <font color=\"Red\">مولوی .</font><br>ای چشم و چراغ دیده ٔ حی <br>خون ریختنم چه میکنی هی .<br> <font color=\"Red\">سعدی .</font><br>هشیار شو که مرغ چمن مست گشت هان <br>بیدار شو که خواب عدم در پی است هی .<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">هی زدن به رکاب (بر مرکب )</span> ؛ زجر کردن آن که بدود با گفتن کلمه ٔ هی <span class=\"hlight\">:</span> <br>من به رکاب می همی باده ٔ ناب میزنم <br>چونکه شوم سوار می هی به رکاب میزنم .<br> <font color=\"Red\">؟ (از آنندراج ).</font><br>- هی کردن <span class=\"hlight\">:</span> <br>مرا رساند به کوی تو همچو باد صبا<br>به شوق خویش در این راه بسکه هی کردم .<br><font color=\"Red\">علی خراسانی (از آنندراج ).</font><br></font></div>'),
(269315, 'هی', '<span class=\"hlight\">هی .</span> <font color=\"DarkGreen\"><b>[ی َ ]</font></b> (ع ضمیر) ضمیر مفرد مغایب مؤنث به معنی او، آن زن . هی که گاه به تشدید نیز گفته شود کنایه است از واحد مؤنث غایب و گاهی یاء آن نیز حذف گردد و گویند: حتاه فعلت ؛ أی حتی هی فعلت . (از اقرب الموارد).<br></font></div>'),
(269316, 'هی', '<span class=\"hlight\">هی .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ق ) پیوسته . پیاپی . مدام .دائم . همیشه . همواره . (یادداشت مؤلف ) <span class=\"hlight\">:</span> <br>خیزید و یک قرابه مرا می بیاورید<br>هی من خورم مدام و شما هی بیاورید.<br><font color=\"Red\">؟</font><br></font></div>'),
(269317, 'هی', '<span class=\"hlight\">هی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (فعل ) به زبان دری و هندی به معنی هست . (انجمن آرا) (برهان ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br>هیم به پله ٔ نیکی ز یک سپندان کم <br>به پله ٔ بدی اندر هزار سندانم .<br> <font color=\"Red\">سوزنی .</font><br>گفت یارب گر تو را خاصان هی اند<br>که مبارک دعوت و فرخ پی اند.<br> <font color=\"Red\">مولوی .</font><br>ساقی اگرت هوای ما هی <br>جز باده میار پیش ما شی .<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> مخفف هستی <span class=\"hlight\">:</span> <br>بگفتم که تو بازگو مر مرا<br>اگر مهتری یا که هی کهتری .<br><font color=\"Red\">نجیبی .</font><br></font></div>'),
(269318, 'هی', '<span class=\"hlight\">هی .</span> (ع ق ) لغتی است در اًی . (از اقرب الموارد). هی واﷲ؛ یعنی ای واﷲ. هی و ربی ؛ اًی و ربی . (یادداشت مرحوم دهخدا).<br></font></div>'),
(269319, 'هی', '<span class=\"hlight\">هی .</span> (اِ) نام دیگر حرف هاء. (المعجم ).<br></font></div>'),
(269320, 'هی بن بی', '<span class=\"hlight\">هی بن بی .</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ ی ُ ن ُ ب َی ی ]</font></b> (ع اِ مرکب ) هیان بن بیان . کنایه است از آنکه او را و پدرش را کسی نشناسد. گویند: ماادری أی ﱡ هی بن بی هو؛ أی أی ﱡ الخلق هو. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269321, 'هی مری', '<span class=\"hlight\">هی مری .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ترکی، اِ) لفظ ترکی است از الفاظ بارگیر که ترکان در مخاطبات خود آرند. (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(269322, 'هی هاوند', '<span class=\"hlight\">هی هاوند.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) جزو طایفه ٔ چهارلنگ از ایل بختیاری ایران و مشتمل بر شعب ذیل : بسحاق، پولادوند، عبدالوند، حاجی وند و عیسی وند. (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>).<br></font></div>'),
(269323, 'هی هی', '<span class=\"hlight\">هی هی .</span> <font color=\"DarkGreen\"><b>[ هََ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ هَِ ]</font></b> (صوت ) عجب عجب . سخت عجیب . چه شگفت <span class=\"hlight\">:</span> <br>قصد لب تو کردم زلف تو گفت هی هی <br>از هجر غافلی تو کت از جهان برآرد.<br> <font color=\"Red\">خاقانی .</font><br>گفت هی هی گفت تن زن ای دژم <br>تا در این ویرانه خود فارغ کنم .<br> <font color=\"Red\">مولوی .</font><br>چو گل نقاب برافکند و مرغ زد هوهو<br>منه ز دست پیاله چه میکنی هی هی .<br> <font color=\"Red\">حافظ.</font><br><BR><font color=\"Blue\">◄</font> علامت تحقیر و استخفاف . (یادداشت مؤلف ): هی هی جبلی قم قم .<br></font></div>'),
(269324, 'هی هی', '<span class=\"hlight\">هی هی .</span> <font color=\"DarkGreen\"><b>[ هَِ هَِ ]</font></b> (اِخ ) دهی است از دهستان مزرج بخش حومه ٔ شهرستان قوچان . دارای <span class=\"hlight\" dir=\"rtl\">٤٦٣</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(269325, 'هی کردن', '<span class=\"hlight\">هی کردن .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ک َ دَ ]</font></b> (مص مرکب ) در تداول، راندن اسب و دیگر چارپایان باشد. به رفتن داشتن ستور را.<br></font></div>'),
(269326, 'هی ی سیامین', '<span class=\"hlight\">هی ی سیامین .</span> <font color=\"DarkGreen\"><b>[ هی ُ ]</font></b> (اِ) ماده ای است سمی از بذرالبنج . (یادداشت مؤلف ). رجوع به هیوسیامین شود.<br></font></div>'),
(269327, 'هیا', '<span class=\"hlight\">هیا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع حرف ندا) از حروف ندا است برای بعید و اصل آن ایا است به معنی یا، ای . (از اقرب الموارد).<br></font></div>'),
(269328, 'هیا', '<span class=\"hlight\">هیا.</span> <font color=\"DarkGreen\"><b>[ هی یا ]</font></b> (ع اِ) لغتی است در ایّا. (از اقرب الموارد). رجوع به ایّا شود.<br></font></div>'),
(269329, 'هیاب', '<span class=\"hlight\">هیاب .</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ یا ]</font></b> (ع ص ) ترسان و بددل . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنکه از وی ترسند. (منتهی الارب ).<br></font></div>'),
(269330, 'هیابانگ', '<span class=\"hlight\">هیابانگ .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ مرکب ) هیاهو. هایاهوی . (یادداشت مرحوم دهخدا). ضوضاء.<br></font></div>'),
(269331, 'هیابة', '<span class=\"hlight\">هیابة.</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ یا ب َ ]</font></b> (ع ص ) مبالغه است، ترسان و بددل . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنکه از وی ترسند. (منتهی الارب ) (آنندراج ). رجوع به هیاب شود.<br></font></div>'),
(269332, 'هیاج', '<span class=\"hlight\">هیاج .</span> (ع مص ) خشک شدن نبات . (تاج المصادر بیهقی ) (ترجمان علامه ٔ جرجانی ترتیب عادل بن علی ) (اقرب الموارد). زرد و خشک گردیدن گیاه . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> انگیخته شدن . (تاج المصادر) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> انگیخته شدن جنگ . (ترجمان علامه ٔ جرجانی ترتیب عادل بن علی ). <BR><font color=\"Blue\">◄</font> برانگیختن . (منتهی الارب ) (آنندراج ) (اقرب الموارد). لازم و متعدی استعمال میشود. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کارزار و کُشش کردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مضطرب شدن و به حرکت درآمدن دریا. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جوش زدن خون و جز آن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نشأه شدن شتران . (اقرب الموارد) (منتهی الارب ) (آنندراج ). مست شدن شتران . <BR><font color=\"Blue\">◄</font> به خشم شدن . (منتهی الارب ) (آنندراج ). خشم گرفتن . <BR><font color=\"Blue\">◄</font> حرکت دادن شتران را به شب بسوی آب و علف . <BR><font color=\"Blue\">◄</font> شجاع شدن و حمله ور گردیدن . (از اقرب الموارد).<br>- <span class=\"hlight\">یوم هیاج </span> ؛ روز جنگ .<br></font></div>'),
(269333, 'هیار', '<span class=\"hlight\">هیار.</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ یا ]</font></b> (ع ص ) رجل هَیّار؛ مرد سست . (منتهی الارب ). ضعیف . (اقرب الموارد).<br></font></div>'),
(269334, 'هیار', '<span class=\"hlight\">هیار.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) آنچه بیفتد و فرودریده شود. (از اقرب الموارد) (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269335, 'هیاسه', '<span class=\"hlight\">هیاسه .</span> <font color=\"DarkGreen\"><b>[ هََ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ) دوال . (غیاث اللغات ). دوالی را گویند که بدان تنگ زین اسب را بر پشت اسب و تنگ بالای بار را بر پشت چاروا بکشند. (آنندراج ) (برهان ). و در عربی حیاصه بدین معنی آمده است <span class=\"hlight\">:</span> <br>پس ساخته زان دوال خودرنگ <br>بر اسب فلک هیاسه ٔ تنگ .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(269336, 'هیاط', '<span class=\"hlight\">هیاط.</span> (ع مص ) بانگ وفریاد کردن . مهایطة. (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نزدیک گردیدن . <BR><font color=\"Blue\">◄</font> دور شدن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> ضعیف و ناتوان شمردن . (از اقرب الموارد). هایط هیاطاً فلاناً؛ استضعفه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) اضطراب و رفت و آمد: هم فی هیاط و میاط؛ أی اضطراب و مجی ٔ و ذهاب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) دیوار کشیدنی بلند گرداگرد شهر باشد. (فرهنگ اسدی ).<br></font></div>'),
(269337, 'هیاط و میاط', '<span class=\"hlight\">هیاط و میاط.</span> <font color=\"DarkGreen\"><b>[ طُ ]</font></b> (ترکیب عطفی، اِ مرکب ) اضطراب و رفت و آمد. هم فی هیاط ومیاط؛ أی اضطراب و مجی ٔ و ذهاب . (اقرب الموارد).<br>- <span class=\"hlight\">عام هیاط میاط</span> ؛ سال قحط که در او فتنه و فساد برپا شود. (یادداشت مرحوم دهخدا).<br></font></div>'),
(269338, 'هیاطل', '<span class=\"hlight\">هیاطل .</span> <font color=\"DarkGreen\"><b>[ هََ طِ ]</font></b> (اِخ ) هیاطله . رجوع به هیاطله شود.<br></font></div>'),
(269339, 'هیاطله', '<span class=\"hlight\">هیاطله .</span> <font color=\"DarkGreen\"><b>[هََ طِ ل َ ]</font></b> (اِخ ) ج ِ هیطال . و هیطال به زبان بخارا مرد قوی باشد و نیرو را به زبان بخارا هیتال خوانند و هیتال را به تازی به هیطال گردانیده اند. (ترجمه ٔ تاریخ طبری بلعمی ). اهل طخرستان . (منتهی الارب ). گروهی اند از هندویان . (مهذب الاسماء). قومی که بلاد تخارستان را داشتند و اتراک خلج و گغجینه از بقایای آن قوم اند. (مفاتیح العلوم خوارزمی ). قومی از اقوام زردپوست بودند و قبل از اسلام مکرر به ممالک ایران و روم هجوم میکرده اند <span class=\"hlight\">:</span> <br>ور از هیاطله گویم عجب فرومانی <br>که شاه ایران آنجا چگونه شد به سفر.<br> <font color=\"Red\">عنصری .</font><br>و رجوع به عقد الفرید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٨</span>، <span class=\"hlight\" dir=\"rtl\">٩٩</span> و تاج العروس در ماده ٔ هطل و حبیب السیر و فارسنامه ٔ ابن بلخی و تاریخ سایکس ترجمه ٔ فخر داعی گیلانی ص <span class=\"hlight\" dir=\"rtl\">٥٨٤</span>، <span class=\"hlight\" dir=\"rtl\">٥٩٣</span> و مزدیسنا ص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span> و عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٧</span> و <span class=\"hlight\" dir=\"rtl\">١١٦</span> و ایران در زمان ساسانیان ص <span class=\"hlight\" dir=\"rtl\">٢٩١</span> شود.<br></font></div>'),
(269340, 'هیاع', '<span class=\"hlight\">هیاع .</span> (ع مص ) انتشار. (اقرب الموارد). منتشر شدن . <BR><font color=\"Blue\">◄</font> قی کردن . (المصادر زوزنی ).<br></font></div>'),
(269341, 'هیاع لیاع', '<span class=\"hlight\">هیاع لیاع .</span> <font color=\"DarkGreen\"><b>[ عُن ْ ]</font></b> (ع ص مرکب ) ریح ٌ هیاع ٌ لیاع ٌ؛ باد تند و شتاب . (آنندراج ) (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269342, 'هیاف', '<span class=\"hlight\">هیاف .</span> <font color=\"DarkGreen\"><b>[ هیا <span class=\"hlight\" dir=\"rtl\">/</span> هَُ ]</font></b> (ع مص ) دهان گشاده کردن شتر بسوی باد هیف از شدت تشنگی . (منتهی الارب ) (آنندراج ). و در اقرب الموارد هیاف به کسر هاء و فتح آن به این معنی آمده است .<br></font></div>'),
(269343, 'هیال', '<span class=\"hlight\">هیال .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) آنچه فروریزد از ریگ . (از اقرب الموارد) (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269344, 'هیالج', '<span class=\"hlight\">هیالج .</span> <font color=\"DarkGreen\"><b>[ هََ ل ِ ]</font></b> (ع اِ) ج ِ هیلاج . هیالج خمسة؛ آفتاب و ماه و طالع و سهم السعاده و جزء اجتماع یا استقبال و آنها ادله ٔ عمر باشند در علم احکام نجوم . (یادداشت مؤلف ). رجوع به هیلاج شود.<br></font></div>'),
(269345, 'هیام', '<span class=\"hlight\">هیام .</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع ص، اِ) ج ِ هیمی ̍. (منتهی الارب ) (اقرب الموارد). رجوع به هیمی ̍ وهیماء شود. شیفتگی و شوریدگی از عشق که به دیوانگی ماند یا نوعی از دیوانگی . (آنندراج ) (منتهی الارب ). دیوانگی از عشق . (مهذب الاسماء) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> تشنگی زده اشتر. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> تشنگی سخت . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) تب شتر یا نوعی از بیماری ستور. (آنندراج ) (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ریگ روان و پیوسته ریزان یا ریگستان خشک باریک خاک . (منتهی الارب ) (اقرب الموارد) (آنندراج ). رجوع به هَیام شود.<br></font></div>'),
(269346, 'هیام', '<span class=\"hlight\">هیام .</span> (ع مص ) دوست داشتن . شوریده شدن کسی از عشق و غیر عشق که نداند به کجا میرود. <BR><font color=\"Blue\">◄</font> سخت تشنه شدن شتر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ هیماء. (منتهی الارب ).<br></font></div>'),
(269347, 'هیام', '<span class=\"hlight\">هیام .</span> <font color=\"DarkGreen\"><b>[ هَُ ی ْ یا ]</font></b> (ع ص، اِ) ج ِ هائم . رجوع به هائم شود. (منتهی الارب ). دوست دارندگان و عشاق وسوسه زده . (آنندراج ) (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مردم وسوسه زده . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269348, 'هیام', '<span class=\"hlight\">هیام .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b>(ع اِ) ریگ روان و پیوسته ریزان یا ریگستان خشک باریک خاک . (اقرب الموارد) (آنندراج ). ریگ نرم و باریک . (مهذب الاسماء). ج، هُیُم . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269349, 'هیان', '<span class=\"hlight\">هیان .</span> <font color=\"DarkGreen\"><b>[ هََی ْ یا ]</font></b> (ع اِ) هَیّان بن بَیّان ؛ کنایه از آنکه او را و پدرش را کسی نشناسد. (از اقرب الموارد) (منتهی الارب ). کنایه از بی پدرومادر. رجوع به هی بن بی شود.<br></font></div>'),
(269350, 'هیاه', '<span class=\"hlight\">هیاه .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) از نامهای شیاطین و ازاعلام دیوان است . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269351, 'هیاهو', '<span class=\"hlight\">هیاهو.</span> <font color=\"DarkGreen\"><b>[ هََ یا ]</font></b> (اِ مرکب ) هیابانگ . ضوضاء. هنگامه . غوغا. هایاهوی . قال مقال . سر و صدا. داد و بیداد. بانگ و فریاد. ظاهراً قلب های هو، به معنی شور و غوغا. (آنندراج ) <span class=\"hlight\">:</span> <br>چو از آب آمو گذشت آن سپاه <br>برآمد هیاهو ز ماهی به ماه .<br><font color=\"Red\">عبداﷲ هاتفی (از آنندراج ).</font><br></font></div>'),
(269352, 'هیاهوی', '<span class=\"hlight\">هیاهوی .</span> <font color=\"DarkGreen\"><b>[ هََ یا ]</font></b> (اِ مرکب ) هیاهو. رجوع به هیاهو شود.<br></font></div>'),
(269353, 'هیاهیا', '<span class=\"hlight\">هیاهیا.</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ یا هََ ی ْ یا ]</font></b> (ع اِ فعل ) کلمه ای است که بدان زجر کنند. (منتهی الارب ). از اسماء افعال است به معنی بشتاب . (از اقرب الموارد).<br></font></div>'),
(269354, 'هیاکل', '<span class=\"hlight\">هیاکل .</span> <font color=\"DarkGreen\"><b>[ هََ ک ِ ]</font></b> (ع اِ) ج ِ هیکل . رجوع به هیکل شود.<br></font></div>'),
(269355, 'هیب', '<span class=\"hlight\">هیب .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) ترسیدن کسی را. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269356, 'هیب', '<span class=\"hlight\">هیب .</span> (اِ) به لغت ژند و پاژند عاقبت کار را گویند. (برهان ) (آنندراج ).<br></font></div>'),
(269357, 'هیب', '<span class=\"hlight\">هیب .</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ ی ِ ]</font></b> (ع ص ) ترسان . (منتهی الارب ) (اقرب الموارد). بیمناک . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269358, 'هیبان', '<span class=\"hlight\">هیبان .</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ ی َ ]</font></b> (ع ص ) مرد بسیارترس و بددل . (منتهی الارب )(آنندراج ). <BR><font color=\"Blue\">◄</font> کسی که از مردم میترسد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چست و سبک . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) تکه . (منتهی الارب ). تیس . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شبان . <BR><font color=\"Blue\">◄</font> خاک . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کفک دهن شتر. (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269359, 'هیبان', '<span class=\"hlight\">هیبان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) آنکه از وی ترسند. (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(269360, 'هیبان', '<span class=\"hlight\">هیبان .</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ ی ِ ]</font></b> (ع ص ) رجوع به مدخل قبل شود.<br></font></div>'),
(269361, 'هیبة', '<span class=\"hlight\">هیبة.</span> <font color=\"DarkGreen\"><b>[ هََ ب َ ]</font></b> (ع مص ) ترسیدن . (تاج المصادربیهقی ) (اقرب الموارد) (آنندراج ). هیبت . <BR><font color=\"Blue\">◄</font> شکوه داشتن . (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> توقیرو تعظیم کردن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) ترس و بیم . (آنندراج ) (منتهی الارب ) (اقرب الموارد).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">الهیبة خیبة</span> ؛ ترس مایه ٔ نومیدی است .<br><BR><font color=\"Blue\">◄</font> پرهیز. (آنندراج ) (منتهی الارب ). تقیه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بزرگی . (آنندراج ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اصطلاح صوفیه ) اثر مشاهده ٔ جلال خداوند است در قلب و گاه از اثر جمال است که جمال جلال بوده باشد. (تعریفات سید جرجانی ). و رجوع به هیبت شود.<br></font></div>'),
(269362, 'هیبت', '<span class=\"hlight\">هیبت .</span> <font color=\"DarkGreen\"><b>[ هَِ ب َ ]</font></b> (اِخ ) دهی است از دهستان خروسلوی بخش گرمی شهرستان اردبیل . دارای <span class=\"hlight\" dir=\"rtl\">١٦٢</span> تن سکنه است . این ده در دو محل واقع شده و به نام هیبت بالا و هیبت پائین مشهور است . سکنه ٔ هیبت بالا بیست تن میباشد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269363, 'هیبت', '<span class=\"hlight\">هیبت .</span> <font color=\"DarkGreen\"><b>[ هََ ب َ ]</font></b> (ع اِ) هیبة. ترس و بیم . (منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span> <br>صورت خشمت ار ز هیبت خویش <br>ذره ای را به خاک بنماید<br>خاک دریا شود بسوزد آب <br>بفسرد آفتاب و بشجاید.<br> <font color=\"Red\">دقیقی .</font><br>کجا حمله ٔ او بود چه کوهی چه مصافی <br>کجا هیبت او بود چه شیری چه شکالی .<br> <font color=\"Red\">فرخی .</font><br>ربود هیبت اواز تن سپهر کجی <br>ببرد خنجر او از سر زمانه خمار.<br> <font color=\"Red\">مسعودسعد.</font><br>اندر جهان ز هیبت تیر و کمان تو<br>چون تیر گشت راست بسی کار چون کمان .<br> <font color=\"Red\">امیرمعزی .</font><br>گر فتد ذره ای از خشم تو بر اوج سپهر<br>گردد از هیبت تو شیر سپهر اندر تب .<br> <font color=\"Red\">سنایی .</font><br>هیبت او کوه را بند کمر درشکست <br>صولت او چرخ را سقف گهر درشکست .<br> <font color=\"Red\">خاقانی .</font><br>چه دریایی است این کز هیبت آن <br>جهان هر ساعتی رنگ دگر شد.<br> <font color=\"Red\">عطار.</font><br>هیبتی زان خفته آمد بر رسول <br>حالتی خوش کرده بر جانش نزول .<br> <font color=\"Red\">مولوی .</font><br>- هیبت انگیز <span class=\"hlight\">:</span> <br>خطی دید از سواد هیبت انگیز<br>نوشته از محمد سوی پرویز.<br> <font color=\"Red\">نظامی .</font><br>- هیبت نمودن <span class=\"hlight\">:</span> <br>به هولش بپرسید وهیبت نمود<br>که مرگ منت خواستن از چه بود.<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> شکوه <span class=\"hlight\">:</span> <br>به فرّ و هیبت شمشیر تو قرار گرفت <br>زمانه ای که پرآشوب بود پالاپال .<br> <font color=\"Red\">دقیقی .</font><br>مرغ با هیبت سیمرغ کجا دارد پای .<br> <font color=\"Red\">فرخی .</font><br>این است همان صفه کز هیبت آن بردی <br>بر شیر فلک حمله شیر تن شادروان .<br> <font color=\"Red\">خاقانی .</font><br>تواضع گرچه محمود است و فضل بیکران دارد<br>نشاید کرد بیش از حد که هیبت را زیان دارد.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">باهیبت </span> ؛ باشکوه . با ابهت و جلال <span class=\"hlight\">:</span> <br>تهیدست باهیبت و نام و ننگ <br>زن زشتروی نکوچادر است .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هیبت بردن </span> ؛ شکوه بردن <span class=\"hlight\">:</span> <br>اگر عالمی هیبت خود مبر<br>وگر جاهلی پرده ٔ خود مدر.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هیبت نهادن </span> ؛ <span class=\"hlight\">:</span> و سبب قتل اپرویز آن بود کی پیوسته بدخویی کردی و بزرگان را هیبتی ننهادی . (فارسنامه ٔ ابن بلخی ).<br><BR><font color=\"Blue\">◄</font> (اصطلاح صوفیه ) هیبت و انس دو حالت اند فوق قبض و بسط چنانکه قبض و بسط فوق خوف و رجأاند پس هیبت مقتضای آن غیبت است و انس را مقتضی صحو است و افاقه . (تعریفات سید جرجانی ) (از اقرب الموارد). رجوع به هیبة شود.<br></font></div>'),
(269364, 'هیبت بیگ', '<span class=\"hlight\">هیبت بیگ .</span> <font color=\"DarkGreen\"><b>[ هَِ ب َ ب ِ ]</font></b> (اِخ ) دهی است از دهستان اوزومدل بخش ورزقان شهرستان اهر. واقع در <span class=\"hlight\" dir=\"rtl\">٧</span>هزارگزی شوسه ٔ تبریز و دارای <span class=\"hlight\" dir=\"rtl\">٢٩٣</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269365, 'هیت', '<span class=\"hlight\">هیت .</span> (ع اِ) زمین پست . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269366, 'هیت', '<span class=\"hlight\">هیت .</span> <font color=\"DarkGreen\"><b>[ هََ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> هََ ت ِ <span class=\"hlight\" dir=\"rtl\">/</span> هََ ت ُ <span class=\"hlight\" dir=\"rtl\">/</span> هی ت َ ]</font></b> (ع اِ فعل ) هیت لک ؛ بیار. (منتهی الارب ). و گاهی اول آن مکسور گردد به معنی هَلُم َّ لک و تعال . واحد و جمع و مؤنث در آن یکسانند و ضمیر مابعد آن صرف شود، گویند: هیت لک، هیت لکما، هیت لکم . (اقرب الموارد).<br></font></div>'),
(269367, 'هیت', '<span class=\"hlight\">هیت .</span> (اِخ ) شهری است بر کنار فرات آبادان و حصاری استوار دارد. (نفایس الفنون ). شهری است به عراق . (منتهی الارب ). شهری است <font color=\"DarkGreen\"><b>[ از جزیره ]</font></b> و از گرد وی باره ٔ محکم، آبادان است و بانعمت و تربت عبداﷲبن المبارک آنجااست . (حدود العالم ). و رجوع به معجم البلدان شود.<br></font></div>'),
(269368, 'هیتال', '<span class=\"hlight\">هیتال .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) رجوع به هیاطله شود <span class=\"hlight\">:</span> <br>مناره برآرم به شمشیر و گنج <br>ز هیتال تا کس نماند به رنج <br>نمانم به جایی پی خوشنواز<br>به هیتال و ترک از نشیب وفراز.<br> <font color=\"Red\">فردوسی (از انجمن آرا).</font><br>مر او را سبک شاه در بر گرفت <br>ز هیتال و چین دست بر سر گرفت .<br> <font color=\"Red\">فردوسی .</font><br>سوی شاه هیتال شد ناگهان <br>ابا لشکر و گنج و چندی مهان .<br> <font color=\"Red\">فردوسی .</font><br>که از مرز هیتال تا مرز چین <br>نباید که کس پی نهد بر زمین .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(269369, 'هیتان', '<span class=\"hlight\">هیتان .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (اِ) کذب و دروغ باشد و به کسر اول هم آمده است . (آنندراج ).<br></font></div>'),
(269370, 'هیتلر', '<span class=\"hlight\">هیتلر.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) آدولف . صدراعظم و دیکتاتور آلمان در جنگ دوم جهانی . در سال <span class=\"hlight\" dir=\"rtl\">١٨٨٩</span> م . در اتریش متولد شد. چند سال به نقشه کشی ساختمان مشغول بود. در سال <span class=\"hlight\" dir=\"rtl\">١٩١٢</span> به مونیخ رفت . در جنگ اول جهانی شرکت داشت و ترفیع درجه پیدا کرد. در سال <span class=\"hlight\" dir=\"rtl\">١٩٢١</span> م . به حزب نازی پیوست . این حزب به رهبری او در آلمان نفوذ و قدرت به هم رسانید. در <span class=\"hlight\" dir=\"rtl\">١٩٣٣</span> هندنبورگ رئیس جمهوری آلمان او را به سمت صدراعظم تعیین کرد. پس از فوت هندنبورگ دیکتاتور آلمان شد و مدت <span class=\"hlight\" dir=\"rtl\">١٢</span> سال با نهایت قدرت فرمانروایی کرد و ارتش نیرومندی برای جنگ آماده ساخت . در <span class=\"hlight\" dir=\"rtl\">١٩٣٨</span> به دنبال خروج آلمان از جامعه ٔ ملل پیمان اتحاد میان آلمان، ایتالیا و ژاپن منعقد گردید که به پیمان محور معروف شد. در <span class=\"hlight\" dir=\"rtl\">١٩٣٩</span> هیتلر قراردادی با روسیه منعقد ساخت و به موجب آن لهستان میان آلمان وروسیه تقسیم شد. در همان سال نیروهای آلمان به فرمان هیتلر به لهستان حمله کردند و در اثر آن جنگ میان دول محور (آلمان و ایتالیا و ژاپن ) و متفقین (لهستان، فرانسه و انگلیس ) درگرفت . نیروهای آلمان کشورهای لهستان و دانمارک و نروژ و فرانسه و هلند و بلژیک را اشغال کردند و در سال <span class=\"hlight\" dir=\"rtl\">١٩٤١</span> به روسیه حمله بردند و تامسکو پیش رفتند و در اثر کمکهای انگلیس و فرانسه و آمریکا و پایداری سربازان شوروی نیروهای آلمان شکست خوردند و از مناطقی که اشغال کرده بودند عقب نشینی کردند و سرانجام پیروزی نصیب متفقین گردید و آلمان در <span class=\"hlight\" dir=\"rtl\">١٩٤٥</span> بدون قید و شرط تسلیم شد و هیتلر در آخرین ساعت جنگ خودکشی کرد اما جسدش پیدا نشد. (فرهنگ عمید).<br></font></div>'),
(269371, 'هیتکور', '<span class=\"hlight\">هیتکور.</span> <font color=\"DarkGreen\"><b>[ هََ ت َ ]</font></b> (ع ص ) آنکه بیدار نشود نه در روز و نه در شب . (منتهی الارب ) (اقرب الموارد) (آنندراج ).<br></font></div>'),
(269372, 'هیث', '<span class=\"hlight\">هیث .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) هَیَثان . چیزی اندک دادن . (منتهی الارب ) (آنندراج ). اندک دادن . (تاج المصادر بیهقی ) (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> جنبیدن . <BR><font color=\"Blue\">◄</font> حاجت روا کردن به مال . <BR><font color=\"Blue\">◄</font> تباهی انداختن در مال . <BR><font color=\"Blue\">◄</font> کم کردن دهش را. (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> داخل شدن بعضی در بعض دیگر به هنگام دشمنی . (از اقرب الموارد).<br></font></div>'),
(269373, 'هیثان', '<span class=\"hlight\">هیثان .</span> <font color=\"DarkGreen\"><b>[ هََ ی َ ]</font></b> (ع مص ) چیزی اندک دادن . (منتهی الارب ) (از اقرب الموارد). رجوع به هیث شود.<br></font></div>'),
(269374, 'هیثم', '<span class=\"hlight\">هیثم .</span> <font color=\"DarkGreen\"><b>[ هََ ث َ ]</font></b> (ع اِ) چوزه ٔ کرکس . <BR><font color=\"Blue\">◄</font> چوزه ٔ عقاب . (منتهی الارب ) (آنندراج ). باز شکاری و گویند جوجه ٔ کرکس و گویند جوجه ٔ عقاب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ریگ توده ٔ سرخ یا زمین نرم . (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درختی است از حمض . (از اقرب الموارد).<br></font></div>'),
(269375, 'هیج', '<span class=\"hlight\">هیج .</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ ی ِ ]</font></b> (ع ص ) برانگیزنده . (غیاث اللغات ).<br></font></div>'),
(269376, 'هیج', '<span class=\"hlight\">هیج .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) (یوم ...) روز باد یا ابر یا باران . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> روز کشش و کارزار. (منتهی الارب ). جنگ و این به نام مصدر نامیده شده است . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) غبار. (غیاث اللغات ) (نصاب ). و هیج به معنی گرد و غبار ظاهراً درست نیست . (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> (مص ) برانگیختن . (آنندراج ) (منتهی الارب ) (تاج المصادر بیهقی ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> برانگیخته شدن . (منتهی الارب ) (غیاث اللغات ) (تاج المصادر بیهقی ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> تشنه شدن شتران . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> جوش زدن خون و جز آن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> زرد و خشک گردیدن گیاه . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> به خشم شدن . (منتهی الارب ).<br></font></div>'),
(269377, 'هیج', '<span class=\"hlight\">هیج .</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع صوت ) زجری است مر ناقه را. (منتهی الارب ) (اقرب الموارد). مبنی بر کسر است . (از اقرب الموارد).<br></font></div>'),
(269378, 'هیجا', '<span class=\"hlight\">هیجا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) کارزار. (دهار) (غیاث اللغات ) (السامی ) (مهذب الاسماء). جنگ . (آنندراج ) (غیاث اللغات ). پیکار. حرب . (اقرب الموارد). نبرد. معرکه <span class=\"hlight\">:</span> <br>به هیجا که گردد دلاور بود<br>به رزم اندرش ده برابر بود.<br> <font color=\"Red\">فردوسی .</font><br>مردمان گویند سلطان لشکری دارد قوی <br>پشت لشکراوست در هیجا به حق کردگار.<br> <font color=\"Red\">فرخی .</font><br>نه هر آن کو مال دارد میل زی ملکت کند<br>نه هر آن کو تیغ دارد قصد زی هیجا کند.<br> <font color=\"Red\">منوچهری .</font><br>روز هیجاها بود کشورگشا<br>روز مجلس ها بود کشوردهی .<br> <font color=\"Red\">منوچهری .</font><br>تو اسرار الهی را کجا دانی که تا در تو<br>بود ابلیس با آدم کشیده تیغ در هیجا.<br> <font color=\"Red\">ناصرخسرو.</font><br>کس از لشکر ما ز هیجا برون <br>نیامد جز آغشته خفتان به خون .<br> <font color=\"Red\">سعدی .</font><br>رجوع به هیجاء شود.<br>- <span class=\"hlight\">بانگ هیجا</span> ؛ هیاهوی نبرد. بانگ و فریاد روز جنگ <span class=\"hlight\">:</span> <br>چو پیوستند با هم بانگ هیجا از دو سو برشد<br>سوی هم تاختن کردند گویی از پی هیجا.<br><font color=\"Red\">سروش (از گنج سخن ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢١</span> از فرهنگ فارسی معین ).</font><br></font></div>'),
(269379, 'هیجان', '<span class=\"hlight\">هیجان .</span> <font color=\"DarkGreen\"><b>[ هََ ی َ ]</font></b> (ع مص ) هیج . هیاج . برانگیخته شدن . (غیاث اللغات ) (آنندراج ) (المصادر زوزنی ) (منتهی الارب ) (اقرب الموارد). انگیخته شدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> برانگیختن . (اقرب الموارد). رجوع به هیج و هیاج شود. <BR><font color=\"Blue\">◄</font> (اِمص ) جوش . جوشش . شور. (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">هیجان انگیز</span>؛ شورانگیز.<br>- هیجان دم <span class=\"hlight\">:</span> <br>یک نیمه رخش زرد و دگر نیمه رخش سرخ <br>این را هیجان دم و آن را یرقان است .<br> <font color=\"Red\">؟</font><br><BR><font color=\"Blue\">◄</font> خشم و غضب .(فرهنگ فارسی معین ).<br></font></div>'),
(269380, 'هیجبوس', '<span class=\"hlight\">هیجبوس .</span> <font color=\"DarkGreen\"><b>[ هََ ج َ ]</font></b> (ع ص ) مرد دراز گول و درشت خوی شتاب زده . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269381, 'هیجده', '<span class=\"hlight\">هیجده .</span> <font color=\"DarkGreen\"><b>[ دَه ْ ]</font></b> (عدد، ص، اِ) هجده . هژده . هیژده . یکی از اعداد. ثمانیةعشر. عدد پس از هفده و پیش از نوزده .<br></font></div>'),
(269382, 'هیجدهم', '<span class=\"hlight\">هیجدهم .</span> <font color=\"DarkGreen\"><b>[ دَ هَُ ]</font></b> (عدد ترتیبی، ص نسبی ) هجدهم . عدد ترتیبی برای هیجده .<br></font></div>'),
(269383, 'هیجدهمین', '<span class=\"hlight\">هیجدهمین .</span> <font color=\"DarkGreen\"><b>[ دَ هَُ ]</font></b> (ص نسبی، اِ مرکب ) هجدهمین . هژدهمین .<br></font></div>'),
(269384, 'هیجفل', '<span class=\"hlight\">هیجفل .</span> <font color=\"DarkGreen\"><b>[ هََ ج َ ف ِ ]</font></b> (ع ص ) قوس هیجفل ؛ کمان سبک تیر یا سبک تیرگذار. (از اقرب الموارد) (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269385, 'هیجمانة', '<span class=\"hlight\">هیجمانة.</span> <font color=\"DarkGreen\"><b>[ هََ ج ُ ن َ ]</font></b> (ع اِ) مروارید بزرگ . (منتهی الارب ) (آنندراج ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> عنکبوت نر. (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269386, 'هیجن', '<span class=\"hlight\">هیجن .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) این کلمه را ناصرخسرو در شعر ذیل آورده است، اما در کتب لغت دسترس ما یافته نشد. شاید بتوان گفت که به ضرورت شعری از مصدر هیج و هیجان و هیاج عربی به معنی به خشم شدن و برانگیخته شدن و برانگیختن به صورت مورد اشاره به کار برده باشد <span class=\"hlight\">:</span> <br>اگر نادان خریدار دروغ است <br>تو با نادان مکن همواره هیجن .<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(269387, 'هیجی', '<span class=\"hlight\">هیجی .</span> <font color=\"DarkGreen\"><b>[ هََ جا ]</font></b> (ع اِ) هیجا. هیجاء. جنگ . (منتهی الارب ). رجوع به هیجا شود.<br></font></div>'),
(269388, 'هیخ', '<span class=\"hlight\">هیخ .</span> <font color=\"DarkGreen\"><b>[ هی ی َ ]</font></b> (ع ص ) شتری که چون هیخ ِ گویند آن را بانگ کند. (آنندراج ) (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269389, 'هیخ', '<span class=\"hlight\">هیخ .</span> (اِمص ) از ریشه ٔ هیختن است به معنی کشیدن . رجوع به هیختن شود.<br></font></div>'),
(269390, 'هیخ', '<span class=\"hlight\">هیخ .</span> <font color=\"DarkGreen\"><b>[ خ ِ ]</font></b> (ع اِ فعل ) کلمه ای است که وقت فروخوابانیدن شتر گویند. (آنندراج ) (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269391, 'هیختن', '<span class=\"hlight\">هیختن .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (مص ) کشیدن <span class=\"hlight\">:</span> دایگان کنیزک به سر چاه بودند و آب همی هیختندی . (کارنامه ٔ اردشیر). <BR><font color=\"Blue\">◄</font> فروکشیدن .<br>- <span class=\"hlight\">فروهیختن </span> ؛ فروکشیدن . (یادداشت مؤلف ).<br></font></div>'),
(269392, 'هید', '<span class=\"hlight\">هید.</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (اِ) چیزی باشد که برزگران به آن خرمن کوفته بباد دهند تا کاه از دانه جدا شود. (از برهان ) (آنندراج ). غله برافشان . (انجمن آرا). پنجه . شانه (در تداول مردم قزوین ).<br></font></div>'),
(269393, 'هید', '<span class=\"hlight\">هید.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) مضطرب . (اقرب الموارد) (منتهی الارب ). پریشان . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) جنبش . <BR><font color=\"Blue\">◄</font> زجری است مر شتر را. هاد. (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> هید حالک ؛ چسان است حال تو. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ایام هید؛ روزهای مَوَتان که در جاهلیت بود. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کسی که دور دارند او را و یکسو کنند بجهت چرکینی جامه ٔ وی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (مص ) هاد. ترسانیدن و رنج رسانیدن و جنبانیدن . (منتهی الارب ) (آنندراج ) (تاج المصادر بیهقی ) (از اقرب الموارد) (المصادر). <BR><font color=\"Blue\">◄</font> اصلاح کردن . <BR><font color=\"Blue\">◄</font> از جای برکندن . یقال : «هِدْه ُ یا رجل »؛ أی اَزِلْه ُ عن موضعه . <BR><font color=\"Blue\">◄</font> ویران کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برگردانیدن . (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زجر کردن . (منتهی الارب ) (المصادر زوزنی ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بانگ برزدن شتر را. (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269394, 'هیدان', '<span class=\"hlight\">هیدان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) بددل . (منتهی الارب ) (آنندراج ). جبان و ترسو. <BR><font color=\"Blue\">◄</font> مضطرب و پریشان . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بخیل و احمق . (منتهی الارب ) (از اقرب الموارد). هو یعطی الهیدان و الریدان ؛ یعنی می بخشد مردم شناخته و ناشناخته را. (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(269395, 'هیدب', '<span class=\"hlight\">هیدب .</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (ع ص، اِ) ابر فروهشته دامن . (منتهی الارب ) (آنندراج ). ابر نزدیک زمین . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> ریشه و پرزه ٔ جامه . (منتهی الارب ) (آنندراج ). ریشه ٔ جامه . (مهذب الاسماء) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شرم زن که فروهشته باشد. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> اشک پی هم ریزان . <BR><font color=\"Blue\">◄</font> مرد کندخاطر و عاجز و گران سنگ . (منتهی الارب ) (آنندراج ) (اقرب الموارد). مرد گران جان . (مهذب الاسماء).<br></font></div>'),
(269396, 'هیدبی', '<span class=\"hlight\">هیدبی .</span> <font color=\"DarkGreen\"><b>[ هََ دَ بی ی ]</font></b> (ع ص ) رجل هیدبی الکلام ؛ مرد بسیارسخن . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269397, 'هیدبی', '<span class=\"hlight\">هیدبی .</span> <font color=\"DarkGreen\"><b>[ هََ دَ با ]</font></b> (ع اِ) نوعی از رفتار اسب و مانند آن به کوشش . (از اقرب الموارد) (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269398, 'هیدخ', '<span class=\"hlight\">هیدخ .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَ ِ دَ ]</font></b> (اِ) اسب تند و تیز و جهنده است و به عربی طمر خوانند و بجای خاء جیم هم آمده است . (برهان ) (شعوری ) (آنندراج ). اسبی نیک جنگی . (نسخه ای از اسدی ). هی به معنی اسب و دخ به معنی خوب . (آنندراج ) (انجمن آرا). اسب نوزین . (حاشیه ٔ فرهنگ اسدی ) <span class=\"hlight\">:</span> <br>تو هیدخی و همی نهی مخ <br>بر کره ٔ توسن تخاره <font color=\"DarkGreen\"><b>[ نجاره ]</font></b> .<br> <font color=\"Red\">منجیک (از فرهنگ اسدی ).</font><br>گرنه عشقت بدی از لعب فلک <br>هیدخی یا فرسی داشتمی .<br> <font color=\"Red\">؟ (از جهانگیری ).</font><br>و در شعوری به نام رودکی ضبط شده . فرهنگ نویسان را فرهنگ اسدی به خطا انداخته است از نفهمیدن شعر منجیک که هیدخ نیست، بیدق است به معنی پیاده ٔ شطرنج . (یادداشت مرحوم دهخدا).<br></font></div>'),
(269399, 'هیدروالکتریک', '<span class=\"hlight\">هیدروالکتریک .</span> <font color=\"DarkGreen\"><b>[ رُ اِ ل ِ ت ِ ]</font></b> (فرانسوی، اِ مرکب ) (اصطلاح فیزیک ) تولید برق بوسیله ٔ نیروی آب . برای این منظور معمولاً توربین هایی میسازند که بوسیله ٔ فشار آب میچرخد وتولید الکتریسته مینماید. (از فرهنگ فارسی معین ).<br></font></div>'),
(269400, 'هیدرژن', '<span class=\"hlight\">هیدرژن .</span> <font color=\"DarkGreen\"><b>[ رُ ژِ ]</font></b> (فرانسوی، اِ) (اصطلاح شیمی ) هیدروژن . ئیدروژن . عنصری است گازی شکل که به حالت آزاد در طبیعت بسیار کمیاب است ولی به حالت ترکیب بسیارفراوان مثلاً <span class=\"hlight\" dir=\"rtl\">١٥</span> وزن آب هیدرژن است . در بافت های گیاهی و جانوری و نفت ها و گازهای متصاعد از دهانه های آتشفشانی این عنصر به مقدار زیاد وجود دارد. هیدرژن چون در برابر هوای آزاد خیلی زود آتش میگیرد کیمیاگران آن را هوای سوزا مینامیدند و از اثر جوهر گوگرد بر آهن آن را به دست می آورند. وزن اتمی این عنصر یک و علامت شیمیایی آن <span class=\"hlight\" dir=\"rtl\">H</span> است . برای به دست آوردن هیدرژن معمولاً در آزمایشگاه اسید سولفوریک رقیق با اسید کلوریدریک را بر براده ٔ آهن یا براده ٔ روی اثر میدهند. ترکیب اسید سولفوریک رقیق با روی چنین است : رقیق و سرد<br> <font color=\"Red\">ی <span class=\"hlight\" dir=\"rtl\">H٢</span> + <span class=\"hlight\" dir=\"rtl\">SO٤Zn</span> <span class=\"hlight\" dir=\"rtl\">Zn</span> + <span class=\"hlight\" dir=\"rtl\">SO٤H٢</span></font><br>فلزات قلیایی از قبیل سدیم و پتاسیم نیز آب را به شدت تجزیه کرده و هیدرژن میدهند. در صنعت هیدرژن را از تجزیه ٔ الکتریکی آب به دست می آورند و معمولاً آب را بوسیله ٔ سود محرق هادی الکتریسیته میکنند و در اثر جریان مستقیم آب را تجزیه میکنند. عمل را میتوان با فرمول زیر خلاصه کرد:<br> <font color=\"Red\">ی <span class=\"hlight\" dir=\"rtl\">O٢</span> + ی <span class=\"hlight\" dir=\"rtl\">٢H٢</span> ی <span class=\"hlight\" dir=\"rtl\">٢H٢O</span></font><br>هیدرژن از سبکترین گازها است و تقریباً <span class=\"hlight\" dir=\"rtl\">١٥</span> مرتبه از هوا سبکتر است به همین علت دانشمندان معتقدند که در اطراف خورشید و سایر کرات سنگین تر از زمین هیدرژن به مقدار زیاد وجود دارد. هیدرژن بی رنگ و بی بو و بی طعم است و در آب به مقدار کم حل میشود و قابلیت نفوذ آن از همه ٔ گازها بیشتر است . مهمترین خاصیت شیمیایی هیدرژن میل ترکیبی آن با اکسیژن است . و نتیجه ٔ ترکیب این دو آب است . دیگر از خواص هیدرژن خاصیت احیاکنندگی آن است مثلاً چنانچه گاز هیدرژن را از روی اکسید سیاه مس (<span class=\"hlight\" dir=\"rtl\">CuO</span>) که گرم شده باشد عبور دهند هیدرژن با اکسیژن ترکیب شده و مس آزاد میشود.<br>- <span class=\"hlight\">هیدرژن سنگین </span> ؛ گازی است که با علامت شیمیایی <span class=\"hlight\" dir=\"rtl\">D</span> آن را نمایش میدهند و بنام دوتریوم  نیز خوانده میشود. این گاز به نسبت <span class=\"hlight\" dir=\"rtl\">٢</span> درصد هیدرژن معمولی دارد و از سوختن آن آب سنگین به فرمول <span class=\"hlight\" dir=\"rtl\">O</span> <span class=\"hlight\" dir=\"rtl\">D٢</span> به دست می آید. (از فرهنگ فارسی معین ).<br></font></div>'),
(269401, 'هیدلة', '<span class=\"hlight\">هیدلة.</span> <font color=\"DarkGreen\"><b>[ هََ دَ ل َ ]</font></b> (ع مص ) راندن شتر به سرود. (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(269402, 'هیدوج', '<span class=\"hlight\">هیدوج .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) شعبه ای است از طایفه ٔ ناحیه ٔ سراوان از طوایف کرمان و بلوچستان و مرکب از <span class=\"hlight\" dir=\"rtl\">٢٠٠٠</span> خانوار میباشد. (جغرافیای سیاسی کیهان ).<br></font></div>'),
(269403, 'هیدکر', '<span class=\"hlight\">هیدکر.</span> <font color=\"DarkGreen\"><b>[ هََ دَ ک ُ ]</font></b> (ع ص ) زن بسیارگوشت . (منتهی الارب ) (از اقرب الموارد). زن جوان شگرف اندام نیکوکرشمه . (اقرب الموارد). هیدکور. هیدکورة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> لبن خاثر. (اقرب الموارد). شیر دفزک . (اقرب الموارد) (منتهی الارب ). رجوع به هیدکور شود.<br></font></div>'),
(269404, 'هیدکور', '<span class=\"hlight\">هیدکور.</span> <font color=\"DarkGreen\"><b>[ هََ دَ ]</font></b> (ع ص ) زن بسیارگوشت . هیدکر. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پنهان شونده جهت فریفتن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن جوان شگرف اندام نیکوکرشمه . <BR><font color=\"Blue\">◄</font> شیردفزک . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بیت هیدکورالاساطین ؛ سرای ثابت ستونها. (منتهی الارب ).<br></font></div>'),
(269405, 'هیذار', '<span class=\"hlight\">هیذار.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) بیهوده گوی بسیارسخن . (منتهی الارب ) (آنندراج ). هیذر. (از اقرب الموارد).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(269406, 'هیذام', '<span class=\"hlight\">هیذام .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) بسیارخوار. (منتهی الارب ) (آنندراج ). اکول . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دلیر. (منتهی الارب ) (آنندراج ). شجاع . (اقرب الموارد).<br></font></div>'),
(269407, 'هیذبی', '<span class=\"hlight\">هیذبی .</span> <font color=\"DarkGreen\"><b>[ هََ ذَ با ]</font></b> (ع اِ) نوعی از رفتار اسب به کوشش . (از اقرب الموارد) (منتهی الارب ) (آنندراج ). هیدبی . (از اقرب الموارد). رجوع به هیدبی شود.<br></font></div>'),
(269408, 'هیذم', '<span class=\"hlight\">هیذم .</span> <font color=\"DarkGreen\"><b>[ هََ ذَ ]</font></b> (ع ص ) شتاب رو سریع. (منتهی الارب ) (آنندراج ). سریع. (از اقرب الموارد).<br></font></div>'),
(269409, 'هیذمند', '<span class=\"hlight\">هیذمند.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) هیرمند. (حدود العالم ) <span class=\"hlight\">:</span> کش شهری است ... بر کران رود هیذمند نهاده . (حدود العالم ). هیرمند. رجوع به هیرمند شود.<br></font></div>'),
(269410, 'هیر', '<span class=\"hlight\">هیر.</span> (اِصوت ) آوازی که بدان راندن ستور خواهند <span class=\"hlight\">:</span> <br>در بار هجوشان کشم از گوش تا به دم <br>خواهم به چوب رانم و خواهم به هیر و هر.<br><font color=\"Red\">سوزنی (از یادداشت مؤلف ).</font><br></font></div>'),
(269411, 'هیر', '<span class=\"hlight\">هیر.</span> (اِ) آتش رامیگویند و به عربی نار خوانند. (برهان ) (آنندراج ) (انجمن آرا). <BR><font color=\"Blue\">◄</font> طاعت و عبادت . (آنندراج ) (برهان ). <BR><font color=\"Blue\">◄</font> به زبان علمی اهل هند طلا را گویند. (برهان ) (آنندراج ).<br></font></div>'),
(269412, 'هیر', '<span class=\"hlight\">هیر.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی جزء دهستان رودبر بخش معلم کلایه ٔشهرستان قزوین . کوهستانی و سردسیر، دارای <span class=\"hlight\" dir=\"rtl\">١٠٥٨</span> تن سکنه است . آب آن از نینه رود و محصول آن غلات، ارزن، گردو، زغال اخته و شغل اهالی زراعت است . ذغال سنگ دارد. راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(269413, 'هیر', '<span class=\"hlight\">هیر.</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هی ]</font></b> (ع اِ) اَیر. ایر. (منتهی الارب ). نصف اول از شب . (منتهی الارب ) (از اقرب الموارد). هَیِّر. <BR><font color=\"Blue\">◄</font> باد شمال . (منتهی الارب ) (مهذب الاسماء) (از اقرب الموارد) (منتهی الارب ). و رجوع به هَیِّر شود.<br></font></div>'),
(269414, 'هیر', '<span class=\"hlight\">هیر.</span> (اِخ ) نام یکی از دهستانهای حومه ٔ شهرستان اردبیل .این دهستان از <span class=\"hlight\" dir=\"rtl\">٤٨</span> آبادی بزرگ و کوچک تشکیل شده و جمعیت آن بالغ بر <span class=\"hlight\" dir=\"rtl\">١٦٧٦١</span> تن میباشد. مرکز این دهستان ده هیر و قراء مهم آن عبارتند از: کسالار، ایوریق، بقرآباد <font color=\"DarkGreen\"><b>[ بلقاباد ]</font></b> . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269415, 'هیر', '<span class=\"hlight\">هیر.</span> (اِخ ) دهی از دهستان هیر بخش مرکزی شهرستان اردبیل . دارای <span class=\"hlight\" dir=\"rtl\">١٨٤٢</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269416, 'هیر', '<span class=\"hlight\">هیر.</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ ی ِ ]</font></b> (ع اِ) ایر. هیر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> باد شمال . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) آنکه بی باکانه در هر چیزی درآید. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269417, 'هیر و هر', '<span class=\"hlight\">هیر و هر.</span> <font color=\"DarkGreen\"><b>[ رُ هََ ]</font></b> (اِ صوت مرکب ) آوازی که خربنده خران را دهد برای راندن <span class=\"hlight\">:</span> <br>در بار هجوشان کشم از گوش تا به دم <br>خواهم به چوب رانم وخواهم به هیر و هر.<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(269418, 'هیر و ویر', '<span class=\"hlight\">هیر و ویر.</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِ مرکب ) در تداول عامه آنگاه به کار رود که مردم در آشفتگی و درهمی و انبوهی و ازدحام بوند و کس مر کس را نایستد.<br>- <span class=\"hlight\">امثال </span> :<br><span class=\"hlight\">میان این هیر و ویر بیا زیر ابروم بگیر</span> .<br></font></div>'),
(269419, 'هیراب', '<span class=\"hlight\">هیراب .</span> (اِخ ) نام ملکی است که رب النوع عنصر باد باشد. (آنندراج ) (انجمن آرا).<br></font></div>'),
(269420, 'هیراب', '<span class=\"hlight\">هیراب .</span> (اِخ ) دهی است از دهستان همت آباد شهرستان بروجرد. در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی جنوب شوسه که کوهستانی و معتدل و دارای <span class=\"hlight\" dir=\"rtl\">٢٥٥</span> تن سکنه است . آب آن از قنات و محصول آن غلات و شغل اهالی آنجا زراعت و گله داری است و راه مالرو دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(269421, 'هیراتیک', '<span class=\"hlight\">هیراتیک .</span> <font color=\"DarkGreen\"><b>[ ی ِ را]</font></b> (اِ) یکی از خطهای قدیمی که پس از خط هیروگلیف اختراع شد. (فرهنگ عمید).<br></font></div>'),
(269422, 'هیراد', '<span class=\"hlight\">هیراد.</span> (اِ) خود را به مردم تازه روی و خوشحال وانمودن و به عربی بشیر خوانند. (آنندراج ) (برهان ).<br></font></div>'),
(269423, 'هیرازمای', '<span class=\"hlight\">هیرازمای .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) پودنه ٔ جویباری . پودنه بر سه قسم است کوهی و جویباری و بستانی، کوهی را فوتنج جبلی گویند و مر جویباری را هیرازمای خوانند و بوستانی را نعنع. (الابنیه عن حقایق الادویه ). و در برهان قاطع این کلمه به صورت «هیزارما» آمده است . (یادداشت مؤلف ).<br></font></div>'),
(269424, 'هیراپولس', '<span class=\"hlight\">هیراپولس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (شهر مقدس ) شهری است در آسیای صغیر در نزدیکی نهر لیکس به مسافت پنج میل در شمال لدودکیه در محلی که عقبش کوه بود بنا شده و هیکل مشهور پلوتو نیز در آنجا بود و فعلاً آن را بیوک قلعه سی گویند. (قاموس کتاب مقدس ).<br></font></div>'),
(269425, 'هیربد', '<span class=\"hlight\">هیربد.</span> <font color=\"DarkGreen\"><b>[ ب َ]</font></b> (اِ مرکب ) خادم و خدمتکار آتشکده . (برهان ). بعضی خداوند و بزرگ و حاکم آتشکده را گفته اند. (برهان ). بزرگ آتشخانه و امین ملت . (آنندراج ). <BR><font color=\"Blue\">◄</font> قاضی و مفتی گبران . (برهان ). شخصی که گبرکان او را محتشم دارند و میان ایشان داور باشد و آتش افروزد در گنبدشان . (حاشیه ٔ فرهنگ اسدی ) (انجمن آرا) <span class=\"hlight\">:</span> <br>به آب و به آتش میازید دست <br>مگر هیربد مرد آتش پرست .<br> <font color=\"Red\">فردوسی .</font><br>چو برداشت پرده ز در هیربد<br>سیاوش همی بود لرزان ز بد.<br> <font color=\"Red\">فردوسی .</font><br>اگر هیربد، بد بود بد مکن <br>که گر بد کنی خودتویی هیربد.<br> <font color=\"Red\">ناصرخسرو.</font><br>در هیرکده گر ز مدیح تو بخوانند<br>بیزار شود هیربد از زند و ز پازند.<br> <font color=\"Red\">امیرمعزی (از جهانگیری ).</font><br>صدش هیربد بود با طوق زر<br>به آتش پرستی گره بر کمر.<br> <font color=\"Red\">نظامی .</font><br>بسی آتش هیربد را بکشت <br>بسی هیربد را دوتا کرد پشت .<br> <font color=\"Red\">نظامی .</font><br>این کلمه مرکب از دو جزء است، نخستین که اثرا باشد به معنی آموزش و تعلیم و جزو دوم پئیتی  (= بد، پسوند اتصاف ) است به معنی مولی و صاحب و دارنده . اثریه  در اوستا به معنی شاگرد و آموزنده است کلمات ائثرپئیتی وائثریه هر دو به معنی استاد و آموزگار و هم شاگرد و آموزنده در اوستا بسیار استعمال شده است . رجوع به مهریشت بند <span class=\"hlight\" dir=\"rtl\">١١٦</span>، فروردین یشت بند <span class=\"hlight\" dir=\"rtl\">١٠٥</span> یسنای <span class=\"hlight\" dir=\"rtl\">٢٦</span> بند <span class=\"hlight\" dir=\"rtl\">٧</span> شود. در هیچ جای اوستا (ائترپئیتی ) (هیربد) به معنی آتربان یا موبد نیامده بلکه بعدها بدین معنی به کار رفته در بند <span class=\"hlight\" dir=\"rtl\">٥٩</span> «ائو گمدئچا» کلمه ٔ ائثرپئیتی استعمال شده و در توضیحات آن افزوده اند: مغوپتان مغوپت یعنی موبدان موبد اما بدون شک بعدها از هیربد همیشه پیشوای دینی (علی الاطلاق ) اراده شده چون در ایران پیشوایان دینی استاد و آموزگار بودند و به تعبیر دیگر آموزش و پرورش مردم به عهده ٔ آنان بوده . رجوع به ایران در زمان ساسانیان کریستنسن ص <span class=\"hlight\" dir=\"rtl\">٤١٧</span> شود. به همین مناسبت آنان را آتربانان و هیربدان (هردو) مینامیدند. تنسر پیشوای دینی معروف عهد اردشیر بابکان در تاریخ ایران به هیربدان هیربد مشهور است . کلیةً در ادبیات فارسی هیربد مترادف موبد است . (حاشیه ٔ برهان قاطع چ معین ). <BR><font color=\"Blue\">◄</font> آتش پرست . <BR><font color=\"Blue\">◄</font> صوفی مرتاض که ریاضت کش باشد. (برهان ). <BR><font color=\"Blue\">◄</font> استاد و آموزگار. <BR><font color=\"Blue\">◄</font> شاگرد و آموزنده . <BR><font color=\"Blue\">◄</font> رئیس آتشگاه . (فرهنگ فارسی معین ).<br></font></div>'),
(269426, 'هیربدان هیربد', '<span class=\"hlight\">هیربدان هیربد.</span> <font color=\"DarkGreen\"><b>[ ب َ ب َ ]</font></b> (اِ مرکب ) رئیس هیربدان . هیربد بزرگ .<br></font></div>'),
(269427, 'هیربدسار', '<span class=\"hlight\">هیربدسار.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) نام نامه ای است از مه آبادکه پارسیان ایران او را نخست وخشور یعنی پیغمبر عجم دانند و آذر هوشنگ بزرگ خوانند و آن نامه را پای چمها یعنی ترجمه ٔ تحت اللفظی متعدد کرده اند. یکی از آن ترجمه ها ترجمه ٔ فریدون فرخ بوده و دیگری ترجمه ٔ بزرگمهر است یعنی بوزرجمهر که برای انوشیروان دادگر نگاشته که یزدانیان سهی کیش که سپاهی نیز خوانند برآنند که برترین پیغمبران و بزرگترین پادشاهان و پدر مردم این دور مه آباد است . (انجمن آرا) (آنندراج ). اما این شرح بر اساس برساخته های آذرکیوان است و اساس ندارد.<br></font></div>'),
(269428, 'هیربدستان', '<span class=\"hlight\">هیربدستان .</span> <font color=\"DarkGreen\"><b>[ ب َ دِ ]</font></b> (اِ مرکب ) محل هیربد.<br></font></div>'),
(269429, 'هیردان', '<span class=\"hlight\">هیردان .</span> <font color=\"DarkGreen\"><b>[ هََ رُ ]</font></b> (ع اِ) دزد. (منتهی الارب ). لص . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گیاهی است . (از اقرب الموارد).<br></font></div>'),
(269430, 'هیرسا', '<span class=\"hlight\">هیرسا.</span> (ص ) پارسا و آن شخصی است که در تمام عمر با زنان نزدیکی نکرده است . (برهان ). پرهیزگاری که در مدت حیات با وجود قوت و قدرت با زنان نیامیزد. (انجمن آرا) (آنندراج ).<br></font></div>'),
(269431, 'هیرط', '<span class=\"hlight\">هیرط.</span> <font color=\"DarkGreen\"><b>[ هََ رَ ]</font></b> (ع ص ) نرم . (منتهی الارب ) (اقرب الموارد). رخو. (اقرب الموارد).<br></font></div>'),
(269432, 'هیرع', '<span class=\"hlight\">هیرع .</span> <font color=\"DarkGreen\"><b>[ هََ رَ ]</font></b> (ع ص ) مرد بددل سست بی خیر. (اقرب الموارد) (منتهی الارب )(آنندراج ). <BR><font color=\"Blue\">◄</font> مرد گول و احمق . <BR><font color=\"Blue\">◄</font> باد شتاب و تند بسیارغبار. <BR><font color=\"Blue\">◄</font> زن شتاب سبک چست . (منتهی الارب ) (اقرب الموارد) (آنندراج ).<br></font></div>'),
(269433, 'هیرعة', '<span class=\"hlight\">هیرعة.</span> <font color=\"DarkGreen\"><b>[ هََ رَ ع َ ]</font></b> (ع ص، اِ) نای شبان . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> غبار معرکة. (منتهی الارب ) (آنندراج ). ریح هیرعة؛ بادی که با خود گرد و غبار آرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آوازشوریده ٔ کارزار. <BR><font color=\"Blue\">◄</font> دیو بیابانی . <BR><font color=\"Blue\">◄</font> زن نیک آزمند جماع . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269434, 'هیرقلش', '<span class=\"hlight\">هیرقلش .</span> <font color=\"DarkGreen\"><b>[ رَ ل ِ ]</font></b> (اِخ ) هرقلس . هرکول . رجوع به هرقلس و هرکول شود. (نزهة القلوب چ اروپا مقاله ٔ سوم ص <span class=\"hlight\" dir=\"rtl\">٢٧٧</span>).<br></font></div>'),
(269435, 'هیرقلیطس', '<span class=\"hlight\">هیرقلیطس .</span> <font color=\"DarkGreen\"><b>[ رَ طُ ]</font></b> (اِخ ) هیراکلیت . هراکلیتوس . رجوع به هراکلیتوس شود.<br></font></div>'),
(269436, 'هیرمند', '<span class=\"hlight\">هیرمند.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِ مرکب ) آتش پرست که ملازم آتش باشد. مرکب از هیر به معنی آتش + مند به معنی صاحب و دارای ...<br></font></div>'),
(269437, 'هیرمند', '<span class=\"hlight\">هیرمند.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) نام رودی است عظیم در سیستان . گویند از کوههای غور و غرجستان خیزد و به زمین داور و بست بگذرد و هزار نهر در آن داخل شود و هزار نهر از آن خارج گردد و در هیچ حالت زیاد و کم ننماید. (انجمن آرا) (آنندراج ) <span class=\"hlight\">:</span> <br>از این پس بیامد سوی هیرمند<br>همی بود ترسان ز بیم و گزند<br>سراپرده زد بر لب هیرمند<br>به فرمان پیروز شاه بلند.<br> <font color=\"Red\">فردوسی .</font><br>چو برگردد او از لب هیرمند<br>تو پای اندرآور به رخش بلند.<br> <font color=\"Red\">فردوسی .</font><br>اندر این اندیشه بودم کز کنار شهر بست <br>بانگ آب هیرمند آمد به گوشم ناگهان .<br><font color=\"Red\">فرخی .</font><br></font></div>'),
(269438, 'هیرمند', '<span class=\"hlight\">هیرمند.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) و هیربد، لقب گشتاسب شاه بود. (انجمن آرا) (آنندراج ).<br></font></div>'),
(269439, 'هیره', '<span class=\"hlight\">هیره .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) گویند که کلمه ٔ فارسی است به معنی پس گردن و قفا و استناد به شعر ابونصر فراهی کنند که گوید <span class=\"hlight\">:</span> <br>ریه شش قفا هیره و وجه روی <br>فخذ ران عقب پاشنه رجل پای .<br>لیکن کلمه ٔ هیره در هیچ جا دیده و شنیده نشده است و معنی بیت هم معلوم نیست . (یادداشت مؤلف ). رجوع به حیره و قفاهیر شود.<br></font></div>'),
(269440, 'هیرودوتس', '<span class=\"hlight\">هیرودوتس .</span> <font color=\"DarkGreen\"><b>[ ت ُ ]</font></b> (اِخ ) ابوالمورخین، هرودوت، مورخ معروف یونان قدیم در <span class=\"hlight\" dir=\"rtl\">٤٨٤</span> ق . م . متولد شد. به بابل و مصر و فلسطین رفت و اطلاعاتی راجع به مصریان قدیم کسب کرد. شرح جنگهای ایران و یونان را نوشت . تألیفاتش از گرانبهاترین آثار قدیم و مورد اطمینان شمرده میشود. او را پدر تاریخ لقب داده اند. در <span class=\"hlight\" dir=\"rtl\">٤٢٠</span> ق . م . در ایتالیادرگذشت . (فرهنگ عمید). هردوت . رجوع به هردوت شود.<br></font></div>'),
(269441, 'هیروشیما', '<span class=\"hlight\">هیروشیما.</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِخ ) یکی از شهرهای ژاپن در ساحل جنوبی جزیره ٔ هونشو. در پایان جنگ دوم جهانی (<span class=\"hlight\" dir=\"rtl\">١٩٤٥</span> م .) در اثر نخستین بمب اتمی که از طرف نیروی هوایی امریکا در این شهر انداخته شد ویران گردید و در نتیجه دولت ژاپن بدون قید و شرط تسلیم شد. جمعیت شهر در آن هنگام قریب <span class=\"hlight\" dir=\"rtl\">٤٠٠٠٠٠</span> تن بود که در حدود <span class=\"hlight\" dir=\"rtl\">٩٠٠٠٠</span> تن کشته شدند و در حدود <span class=\"hlight\" dir=\"rtl\">٦٠٠٠٠</span> تن بسختی مجروح گردیدند. (فرهنگ عمید).<br></font></div>'),
(269442, 'هیروغلیفی', '<span class=\"hlight\">هیروغلیفی .</span> <font color=\"DarkGreen\"><b>[ ی ِ رُغ ْ ]</font></b> (اِ) خط هیروگلیف . نام خط قدیم مصر. رجوع به هیروگلیف شود.<br></font></div>'),
(269443, 'هیرون', '<span class=\"hlight\">هیرون .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) نوعی از خرما. (منتهی الارب ) (آنندراج ) (از اقرب الموارد). یکی آن هیرونة است . (از اقرب الموارد).<br></font></div>'),
(269444, 'هیرون', '<span class=\"hlight\">هیرون .</span> (اِ) بر وزن بیرون، نوعی از نی میان پر است که به عربی قصب گویند. (آنندراج ) (انجمن آرا). و آن محکم و میان پر میباشد. گویند اگر بهار و گل آن به گوش رود گوش را کر کند و گل آن به پنبه ٔ برزده میماند. (برهان ).<br></font></div>'),
(269445, 'هیروگلیف', '<span class=\"hlight\">هیروگلیف .</span> <font color=\"DarkGreen\"><b>[ ی ِ رُگ ْ ]</font></b> (اِ) خط وحوش . یکی از خطهای قدیم . یک نوع خط بوده که به جای نوشتن نام اشیاء شکل آنها را میکشیدند. این خط در بین کاهنان مصری برای نوشتن مطالب مذهبی متداول بوده است . رجوع به خط شود.<br></font></div>'),
(269446, 'هیرک', '<span class=\"hlight\">هیرک .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) بچه ٔ بز را گویند که بزغاله باشد وبعضی گفته اند که همچنانکه بچه ٔ گوسفند را بره می خوانند بچه ٔ شتر را هیرک میگویند. (برهان ) (آنندراج ).<br></font></div>'),
(269447, 'هیرکده', '<span class=\"hlight\">هیرکده .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) آتشکده . مرکب است از هیر به معنی آتش + کده به معنی جای آن <span class=\"hlight\">:</span> <br>در هیرکده گر ز مدیح تو بخوانند<br>بیزار شود هیربد از زند و ز پازند.<br><font color=\"Red\">امیرمعزی (از جهانگیری ).</font><br></font></div>'),
(269448, 'هیرگلیف', '<span class=\"hlight\">هیرگلیف .</span> <font color=\"DarkGreen\"><b>[ ی ِ رُ ]</font></b> (اِ) (خط...) رجوع به هیروگلیف شود.<br></font></div>'),
(269449, 'هیری', '<span class=\"hlight\">هیری .</span> (اِ) بر وزن و معنی خیری است که گل شب بو گویند. (انجمن آرا) (آنندراج ). وآن گلی باشد معروف که شبها بوی خوش کند. (برهان ).<br></font></div>'),
(269450, 'هیز', '<span class=\"hlight\">هیز.</span> (ص ) حیز. (حاشیه ٔ فرهنگ اسدی ). مخنث . (برهان ) (فرهنگ اسدی ). بغا. (حاشیه ٔ فرهنگ اسدی ). حیز نیز گویند اما به زبان پهلوی حرف حا، کم آید. (حاشیه ٔ فرهنگ اسدی ). مخنث و پشت پائی . در فارسی «های » هوز با «حای » حطی بدل میشود. (برهان ) <span class=\"hlight\">:</span> <br>گفتم همی چه گویی ای هیز گلخنی <br>گفتا که چه شنیدی ای پیر مسجدی .<br> <font color=\"Red\">عسجدی .</font><br>چه زنی طعنه که با هیزان هیزند همه <br>که توئی هیز و توئی مسخره و شنگ و مشنگ .<br> <font color=\"Red\">خطیری (از فرهنگ اسدی ).</font><br><BR><font color=\"Blue\">◄</font> (اِ) به لغت پهلوی، دول گرمابه بان . (فرهنگ اسدی ) (برهان ). که بدان آب بر اطراف حمام ریزند و شست و شو دهند و در این زمان به دولچه معروف است . (برهان ).<br></font></div>'),
(269451, 'هیزارما', '<span class=\"hlight\">هیزارما.</span> (اِ) هیرازمای . رستنیی باشد که آن را به عربی نعناع گویند. اگر زن پیش از جماع قدری از آن بخود برگیرد آبستن نشود و بعضی گویند این لغت رومی است . (برهان ). رجوع به هیرازمای و رجوع به تذکره ٔ داود ضریر انطاکی شود.<br></font></div>'),
(269452, 'هیزب', '<span class=\"hlight\">هیزب .</span> <font color=\"DarkGreen\"><b>[ هََ زَ ]</font></b> (ع ص ) لیث هیزب ؛ شیر توانا. (منتهی الارب ) (آنندراج ). الحدید. یقال : لیث هیزب ؛ ای حدید. (از اقرب الموارد).<br></font></div>'),
(269453, 'هیزعة', '<span class=\"hlight\">هیزعة.</span> <font color=\"DarkGreen\"><b>[ هََ زَ ع َ ]</font></b> (ع اِ) ترس و خوف . <BR><font color=\"Blue\">◄</font> بانگ و خروش پیکار. (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(269454, 'هیزم', '<span class=\"hlight\">هیزم .</span> <font color=\"DarkGreen\"><b>[ هََ زَ ]</font></b> (ع ص ) درشت و رُست از هر چیزی . <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269455, 'هیزم', '<span class=\"hlight\">هیزم .</span> <font color=\"DarkGreen\"><b>[ زُ ]</font></b> (اِ) وقاد. وقید.وقود. (منتهی الارب ). حطب . هیمه . چوب برای سوختن . چوب خشک سوختنی . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br>شب زمستان بود کپی سرد یافت <br>کرمکی شب تاب ناگاهی بتافت <br>کپیان آتش همی پنداشتند<br>پشته ٔ هیزم بدو برداشتند.<br> <font color=\"Red\">رودکی .</font><br>هیزم خواهم همی دو امنه  ز جودت <br>جو دو جریب و دو خم سیکی چون خون .<br> <font color=\"Red\">ابوالعباس (از فرهنگ اسدی ).</font><br>به صد کاروان اشتر سرخ موی <br>همه هیزم آورد پرخاشجوی .<br> <font color=\"Red\">فردوسی .</font><br>بیامد دوان پهلوان شادکام <br>برآورد هیزم فراوان به بام .<br> <font color=\"Red\">فردوسی .</font><br>بی وفا هست دوخته به دو نخ <br>بدگهر هست هیزم دوزخ .<br> <font color=\"Red\">عنصری .</font><br>عشق آتش تیز و هیزم تاخ منم <br>گر عشق بماند همچنین آخ تنم .<br> <font color=\"Red\">صفار.</font><br>وانکس که بود بی هنر چو هیزم <br>جز درخور نار سقر نباشد.<br> <font color=\"Red\">ناصرخسرو.</font><br>دو عاشق را بهم خوشتر بود روز<br>دو هیزم را بهم خوشتر بود سوز.<br> <font color=\"Red\">سعدی .</font><br>بعضی به کسر زاء ضبط کرده اند به استناد این بیت نظامی <span class=\"hlight\">:</span> <br>همه سختی از بستگی لازم است <br>چو در بشکنی خانه پرهیزم است .<br> <font color=\"Red\">نظامی .</font><br>و این بیت از مولوی <span class=\"hlight\">:</span> <br>آدمی راآدمیت لازم است <br>عود را گر بو نباشد هیزم است .<br> <font color=\"Red\">مولوی .</font><br>و این خطا است زیرا که اختلاف توجیه جائز داشته اند فکیف که روی متحرک گردیده باشد. (آنندراج ).<br>- <span class=\"hlight\">هیزم دان </span> ؛ جای هیزم . محطب . هیزم خانه .<br>- هیزم سوختن <span class=\"hlight\">:</span> <br>یکی هولناک آتش افروختند<br>نشستند و هیزم همی سوختند.<br> <font color=\"Red\">؟</font><br>- <span class=\"hlight\">هیزم شکاف </span> ؛ هیزم شکن <span class=\"hlight\">:</span> <br>هیزم شکاف پیری فرزانه گاه نزع <br>میگفت با قرینش و میمرد ناگزیر.<br> <font color=\"Red\">؟</font><br>- هیزم شکستن <span class=\"hlight\">:</span> <br>ترا تیشه دادم که هیزم شکن <br>ندادم که دیوار مسجد بکن .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هیزم شکن </span> ؛ آنکه هیمه های بزرگ را برای سوختن به قطعات کوچک و خرد شکند <span class=\"hlight\">:</span> <br>هست چو انگشت کژب و بر سر آن کژب <br>غرچه ٔ هیزم شکن تبر زده یک بار.<br> <font color=\"Red\">سوزنی .</font><br>- <span class=\"hlight\">هیزم شکنی </span> ؛ شغل و عمل هیزم شکن .<br>- <span class=\"hlight\">هیزم فروش </span> ؛ حطاب . (دهار) <span class=\"hlight\">:</span> <br>گل از بوستان باده نوشان برند<br>خس و خارهیزم فروشان برند.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هیزم کش </span> ؛ کسی که هیمه جمع میکند و برای سوخت فراهم می آورد. آنکه چوبهای ریزه را در آتش اندازد تا درگیرد. (آنندراج ) <span class=\"hlight\">:</span> <br>میان دو کس جنگ چون آتش است <br>سخن چین بدبخت هیزم کش است .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هیزم کشی </span> ؛ شغل و عمل هیزم کش <span class=\"hlight\">:</span> پیشه ٔ ایشان شبانی و هیزم کشی و مزدوری بودی . (فارسنامه ٔ ابن بلخی ).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">چوب صندل بو ندارد هیزم است </span> .<br> <span class=\"hlight\">دو هیزم را بهم بهتر بود سوز</span> .<br> <font color=\"Red\">سعدی .</font><br> <span class=\"hlight\">هیزم تر به کسی فروختن </span> .<br><span class=\"hlight\">هیزم تر دود برآرد نه نور</span> .<br></font></div>'),
(269456, 'هیزه', '<span class=\"hlight\">هیزه .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ) پشت . قفا. (یادداشت مرحوم دهخدا). مرحوم ادیب پیشاوری میفرمودند هیزه در نواحی پیشاور به معنی پشت و قفا است و کلمه ٔ حیز به معنی اهریمنی آن نیز از اینجا است و لفظ هیره یا حیره ٔ شعر نصاب الصبیان را نیز همین کلمه میدانستند:<br>ریه شش قفا حیره و وجه روی <br>فخذ ران عقب پاشنه رجل پای .<br><font color=\"Red\">(از یادداشت مرحوم دهخدا).</font><br></font></div>'),
(269457, 'هیزی', '<span class=\"hlight\">هیزی .</span> (حامص ) قحبگی . رجوع به هیز شود.<br></font></div>'),
(269458, 'هیس', '<span class=\"hlight\">هیس .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) آماج . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> جمیعاسباب برزیگری از جفت گاو و جز آن . (از اقرب الموارد) (منتهی الارب ) (آنندراج ). لغت عمانی است . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (مص ) به افزونی گرفتن چیزی را.(منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> به پا کوفتن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پراکنده کردن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> رفتن به هر نوع که باشد. (منتهی الارب ) (آنندراج ) (اقرب الموارد). رفتن . (تاج المصادر بیهقی ).<br></font></div>'),
(269459, 'هیس', '<span class=\"hlight\">هیس .</span> (صوت ) در تداول، آهسته گوی . آهسته رو. آواز مده . هیچ مگوی . خاموش ! آهسته ! یواش ! صوتی است که از آن امر به آهسته گفتن یا سکوت کردن خواهند و در آن تحذیر یا تنبیه گونه ای است که مخاطب را از بیدار شدن خفته یا متألم شدن بیماری آگاه کنند یا از شنیدن کسی که نباید بشنود ترسانند. (یادداشت مرحوم دهخدا).<br></font></div>'),
(269460, 'هیس هیس', '<span class=\"hlight\">هیس هیس .</span> <font color=\"DarkGreen\"><b>[ هََ س ِ هََ س ِ ]</font></b> (ع اِ فعل ) کلمه ای است که وقت امکان و برانگیختن بر کاری گویند. (منتهی الارب ). کلمه ای است که به انسان گفته میشود وقت امکان امری و برانگیختن و تحریض بر کاری و گویند در هنگام چپاول کردن و تاراج نمودن گفته میشود وقتی که قریه ای یا قبیله ای مورد تاراج قرار گیرد و هیچ کس از آنان باقی نماند. (از اقرب الموارد).<br></font></div>'),
(269461, 'هیستامین', '<span class=\"hlight\">هیستامین .</span> (اِ) هیستامین یا بتا ایمیدازول اتیل امین  در سال <span class=\"hlight\" dir=\"rtl\">١٩١٩</span> بوسیله ٔ بارژر و دال  کشف گردید. هیستامین دارای هیچ گونه اثر بیحس کننده نمیباشد لیکن تزریق داخل جلدی آن آرام کننده ٔ درد بوده و از راه زیرجلدی در درمان حالات آلرژیک و قرحه ٔ سده و اثناعشر به کار برده میشود. (کتاب درمان شناسی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٠٥</span>).<br></font></div>'),
(269462, 'هیستری', '<span class=\"hlight\">هیستری .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (فرانسوی، اِ) (اصطلاح پزشکی ) مرض عصبی مشخص یا اختلالات دائمی روحی که گاهی با فلج قسمتی از اعضاء همراه است . مبتلایان به این مرض دچار اختلال حواس و گرفتار اوهام (غالباً افکار و اوهام مربوط به غریزه ٔ جنسی ) میباشند و غالباً در موقع حمله مریض قیافه ٔ اشخاص غشی را دارد.<br></font></div>'),
(269463, 'هیسه', '<span class=\"hlight\">هیسه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دختر امیرالمؤمنین علی علیه السلام است و او زوجه ٔ عبداﷲبن عقیل است . (یادداشت مرحوم دهخدا).<br></font></div>'),
(269464, 'هیسپانیا', '<span class=\"hlight\">هیسپانیا.</span> (اِخ ) نام قدیم اسپانیا. رجوع به اسپانیا شود.<br></font></div>'),
(269465, 'هیش', '<span class=\"hlight\">هیش .</span> <font color=\"DarkGreen\"><b>[هََ ]</font></b> (ع مص ) تباهی افکندن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> جنبیدن . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> برانگیختن . <BR><font color=\"Blue\">◄</font> برانگیخته شدن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نرم دوشیدن . <BR><font color=\"Blue\">◄</font> فراهم آوردن . <BR><font color=\"Blue\">◄</font> سخن بسیار گفتن . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> طرب کردن . (از اقرب الموارد).<br></font></div>'),
(269466, 'هیش', '<span class=\"hlight\">هیش .</span> (اِ، ص، ق ) بر وزن و معنی هیچ است که لاشی ٔ و معدوم باشد. (برهان ) (انجمن آرا) (آنندراج ) <span class=\"hlight\">:</span> <br>امروز در این دور دریغی نخورد هیش <br>از عدل تو یک سوخته بر عدل عمربر.<br> <font color=\"Red\">سنایی .</font><br>هرکه آمد هرکه آید میرود<br>این جهان محنت سرایی بیش نیست <br>احمد جامی تو را پندی دهد<br>آخرت را باش دنیا هیش نیست .<br> <font color=\"Red\">احمد ژنده پیل (از آنندراج ).</font><br><BR><font color=\"Blue\">◄</font> (اِ) بافته ای را گویند از کتان که بیشتر در بلاد هندوستان بافند. <BR><font color=\"Blue\">◄</font> آهن جفت و آن آهنی باشد که زمین را به آن شیار کنند. (برهان ) (انجمن آرا). خیش .<br></font></div>'),
(269467, 'هیشر', '<span class=\"hlight\">هیشر.</span> <font color=\"DarkGreen\"><b>[ هََ ش َ ]</font></b> (ع ص ) نرم سست . (منتهی الارب ). نرم و سست و دراز از مردم . <BR><font color=\"Blue\">◄</font> (اِ) گیاهی است سست یا آن کنگر دشتی است که گیاهی باشد یا درختی است ریگستانی یا کوکنار. (اقرب الموارد) (آنندراج ) (منتهی الارب ). کنگر صحرایی است و درازی آن زیاده بر یک گز میشود و شکوفه ٔ آن پهن بود مانند بنفشه و در میان شکوفه ٔ آن مانند پنبه چیزی است اگر در گوش مردم رود کر گرداند. (برهان ).<br></font></div>'),
(269468, 'هیشلة', '<span class=\"hlight\">هیشلة.</span> <font color=\"DarkGreen\"><b>[ هََ ش َ ل َ ]</font></b> (ع ص ) شترماده ٔ کلانسال فربه . (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269469, 'هیشوی', '<span class=\"hlight\">هیشوی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) صنعتکار رومی <span class=\"hlight\">:</span> <br>یکی پیره سر بود هیشوی نام <br>جوانمرد وبیدار و با فر و کام .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(269470, 'هیص', '<span class=\"hlight\">هیص .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) درشتی در چیزی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> سرگین مرغ . <BR><font color=\"Blue\">◄</font> (مص ) گردن کوفتن . <BR><font color=\"Blue\">◄</font> سرگین انداختن مرغ . (از منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> درشتی کردن . (اقرب الموارد).<br></font></div>'),
(269471, 'هیصار', '<span class=\"hlight\">هیصار.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. هیصور و هصر و هیصار و هصار و مهصر و هُصَرَة و هاصر و هصورة و هصور و مهصار و مهصیرو هَصِر و هُصَر و مهتصر، به معنی شیر و اسد زیرا که شکار خود را میکشند و خرد میکند. (اقرب الموارد).<br></font></div>'),
(269472, 'هیصر', '<span class=\"hlight\">هیصر.</span> <font color=\"DarkGreen\"><b>[ هََ ص َ ]</font></b> (ع اِ) شیر شکننده صید را. (مهذب الاسماء) (اقرب الموارد).<br></font></div>'),
(269473, 'هیصم', '<span class=\"hlight\">هیصم .</span> <font color=\"DarkGreen\"><b>[ هََ ص َ ]</font></b> (اِخ ) ابن جابر خارجی، مکنی به ابوبیهس . از خوارج است و گروه بیهسیه از خوارج بدو منسوبند. رجوع به تاج العروس و ملل ونحل شهرستانی و عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧١</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٢</span> شود.<br></font></div>'),
(269474, 'هیصم', '<span class=\"hlight\">هیصم .</span> <font color=\"DarkGreen\"><b>[ هََ ص َ ]</font></b> (ع ص، اِ) ناب هیصم ؛ دندان شکننده ٔ هر چیز. <BR><font color=\"Blue\">◄</font> شیر. (مهذب الاسماء). اسد.شیر بیشه . (منتهی الارب ) (آنندراج ). شیر درنده . (غیاث اللغات ) (قاموس ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مردقوی . (مهذب الاسماء) (اقرب الموارد). مرد دلیر و توانا. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نوعی از سنگ تابان . (منتهی الارب ) (آنندراج ) (اقرب الموارد).<br></font></div>'),
(269475, 'هیصمیة', '<span class=\"hlight\">هیصمیة.</span> <font color=\"DarkGreen\"><b>[ هََ ص َ می ی َ ]</font></b> (اِخ ) فرقه ای از کرامیه، اصحاب محمدبن الهیصم . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(269476, 'هیصور', '<span class=\"hlight\">هیصور.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ) (اقرب الموارد). رجوع به هیصار و هیصر شود.<br></font></div>'),
(269477, 'هیض', '<span class=\"hlight\">هیض .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) شکستن استخوان از پس جبر. (تاج المصادر بیهقی ) (المصادر زوزنی ). باز شکستن استخوان را بعد گرفتگی . (اقرب الموارد) (منتهی الارب ) (آنندراج ). کسر بعد از جبر. (بحر الجواهر). <BR><font color=\"Blue\">◄</font> سرگین انداختن مرغ . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بازگردان کردن بیماری . (منتهی الارب ) (اقرب الموارد) (آنندراج ). دردی بر دردی . (بحر الجواهر). هیض مرض ؛ گرفتار کردن بیماری کسی را پی در پی . (اقرب الموارد).<br></font></div>'),
(269478, 'هیضل', '<span class=\"hlight\">هیضل .</span> <font color=\"DarkGreen\"><b>[ هََ ض َ ]</font></b> (ع ص، اِ) گروه مردم باسلاح . (منتهی الارب ) (اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> لشکر بسیار. (منتهی الارب ) (آنندراج ) (اقرب الموارد). لشکر بسیاری که کار آنان در جنگ یکی باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جمل ٌ هیضل ٌ؛ شتر شگرف دراز بزرگ . (از اقرب الموارد).<br></font></div>'),
(269479, 'هیضلة', '<span class=\"hlight\">هیضلة.</span> <font color=\"DarkGreen\"><b>[ هََ ض َ ل َ ]</font></b> (ع ص، اِ) زن ضخم میانه سال یا چهل ساله . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> ناقه ٔ بسیارشیر. (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر ماده ٔ سطبراندام درازای کلان سال . (منتهی الارب ) (آنندراج ). ماده اشتربزرگ . (مهذب الاسماء) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گروه مردم سلاح پوش . (منتهی الارب ) (آنندراج ) (اقرب الموارد). گروه مردمان . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> بانگ و خروش های مردم . (منتهی الارب ) (آنندراج ). اصوات مردم . (اقرب الموارد). بانگ مردمان . (مهذب الاسماء).<br></font></div>'),
(269480, 'هیط', '<span class=\"hlight\">هیط.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) بانگ و فریاد کردن . <BR><font color=\"Blue\">◄</font> (اِ) فریاد. <BR><font color=\"Blue\">◄</font> بدی . (منتهی الارب ) (آنندراج ) (از اقرب الموارد). مازال فی هیط؛ ای ضجاج و شر و جلبه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شورش و اضطراب . (منتهی الارب ) (آنندراج ). رجوع به هیاط شود.<br></font></div>'),
(269481, 'هیطال', '<span class=\"hlight\">هیطال .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) مرد قوی . مفرد هیاطله است . هیاطله جمع هیطال باشد و هیطال به زبان بخارا مرد قوی باشد و نیرورا به زبان بخارا هیتال خوانند و به تازی گردانیده اند هیتال به هیطال . (ترجمه ٔ طبری بلعمی ). هیطال جمع هیاطله غلط است و صحیح آن هبطال است با باء موحده . (یادداشت مؤلف ). <BR><font color=\"Blue\">◄</font> (اِخ ) هیتال . هپتال .<br></font></div>'),
(269482, 'هیطل', '<span class=\"hlight\">هیطل .</span> <font color=\"DarkGreen\"><b>[ هََ طَ ]</font></b> (اِخ ) نام بلاد ماوراءالنهر است از بخارا و سمرقند و خجند و مابین اینها. (معجم البلدان ). <BR><font color=\"Blue\">◄</font> اهل طخرستان . <BR><font color=\"Blue\">◄</font> قومی از ترک و خلج .(منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> قومی از هند که ایشان را شوکت و منزلتی بود. هیاطل و هیاطله مانند آن است . (منتهی الارب ) (آنندراج ) (اقرب الموارد).<br></font></div>'),
(269483, 'هیطل', '<span class=\"hlight\">هیطل .</span> <font color=\"DarkGreen\"><b>[ هََ طَ ]</font></b> (ع اِ) روباه . (منتهی الارب ) (آنندراج ) (مهذب الاسماء). ثعلب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گروهی اندک از مردم که با آنها غزا نمایند. (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(269484, 'هیطلة', '<span class=\"hlight\">هیطلة.</span> <font color=\"DarkGreen\"><b>[ هََ طَ ل َ ]</font></b> (معرب، اِ) پاتیله . (مهذب الاسماء). پاتیله ٔ روئین . معرب است . (آنندراج ) (از اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(269485, 'هیع', '<span class=\"hlight\">هیع.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) گسترده گردیدن . (منتهی الارب ) (آنندراج ). بر روی زمین پهن و گسترده شدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نالیدن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> گرسنه شدن . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> طپیدن .(منتهی الارب ). <BR><font color=\"Blue\">◄</font> تنگ دل شدن . <BR><font color=\"Blue\">◄</font> گداخته شدن ارزیز. (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به ستم قی نمودن . (منتهی الارب ) (آنندراج ). قی کردن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خواهش آب نمودن شتر. (منتهی الارب ) (آنندراج ) (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> بددل شدن . (المصادر زوزنی ). ترسیدن و فزع و بی تابی کردن . (از اقرب الموارد). بددلی کردن . (تاج المصادر). بددل گشتن . <BR><font color=\"Blue\">◄</font> سخت حریص شدن . <BR><font color=\"Blue\">◄</font> تیز رفتن آنچه بریزند بر زمین از آب و جز آن . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269486, 'هیعان', '<span class=\"hlight\">هیعان .</span> <font color=\"DarkGreen\"><b>[ هََ ی َ ]</font></b> (ع مص ) گرسنه شدن . <BR><font color=\"Blue\">◄</font> بددل گشتن . (منتهی الارب ). ترسیدن و بی تابی کردن . (از اقرب الموارد).<br></font></div>'),
(269487, 'هیعرون', '<span class=\"hlight\">هیعرون .</span> <font color=\"DarkGreen\"><b>[ هََ ع َ ]</font></b> (ع اِ) بلا و سختی . (منتهی الارب ) (آنندراج ). داهیة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) گنده پیر کلانسال . (منتهی الارب ) (آنندراج ) (از اقرب الموارد). ازهری گوید ثبوت و صحت این کلمه را نمیدانم . (از اقرب الموارد).<br></font></div>'),
(269488, 'هیعوعة', '<span class=\"hlight\">هیعوعة.</span> <font color=\"DarkGreen\"><b>[ هََ ع َ ]</font></b> (ع مص ) قی کردن بی تکلف . <BR><font color=\"Blue\">◄</font> ترسیدن و بی تابی کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) قی . (منتهی الارب ).<br></font></div>'),
(269489, 'هیعوعت', '<span class=\"hlight\">هیعوعت .</span> <font color=\"DarkGreen\"><b>[ هََ عو ع َ ]</font></b> (ع مص ) رجوع به هیعوعة شود.<br></font></div>'),
(269490, 'هیف', '<span class=\"hlight\">هیف .</span> (ع ص، اِ) ج ِ اَهیَف . مردان لاغرشکم و میان باریک . (اقرب الموارد). رجوع به اهیف شود.<br></font></div>'),
(269491, 'هیف', '<span class=\"hlight\">هیف .</span> <font color=\"DarkGreen\"><b>[ هََ ی َ ]</font></b> (ع مص ) لاغرشکم و باریک میان گردیدن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گریختن عبد. (منتهی الارب ).<br></font></div>'),
(269492, 'هیف', '<span class=\"hlight\">هیف .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِمص ) سختی تشنگی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (مص ) سخت تشنه شدن . <BR><font color=\"Blue\">◄</font> گریزپا شدن بنده . <BR><font color=\"Blue\">◄</font> لاغرشکم و باریک میان گردیدن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) باد گرم که از جانب یمن وزد و آن نکبا است میان جنوب و دبور و نباتات و آب را خشک گرداند و حیوانات را تشنه کند. (منتهی الارب ). باد گرم و آن باد که میان جنوب و دبور جهد. (مهذب الاسماء). رجوع به هَیَف شود.<br></font></div>'),
(269493, 'هیفان', '<span class=\"hlight\">هیفان .</span> <font color=\"DarkGreen\"><b>[ هََ ی َ ]</font></b> (ع ص ) مرد زود تشنه شونده یا سخت تشنه . (آنندراج ) (منتهی الارب ).<br></font></div>'),
(269494, 'هیفان', '<span class=\"hlight\">هیفان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) رجل هیفان ؛ مرد تشنه . (منتهی الارب ) (آنندراج ). عطشان . <BR><font color=\"Blue\">◄</font> سخت تشنه یا زود تشنه شونده . (اقرب الموارد).<br></font></div>'),
(269495, 'هیفده', '<span class=\"hlight\">هیفده .</span> <font color=\"DarkGreen\"><b>[ دَه ْ ]</font></b> (عدد، ص، اِ) هفده . عدد اصلی مرکب از هفت و ده . آن عدد که پس از شانزده و قبل از هیجده است <span class=\"hlight\">:</span> ده تخت جامه ٔ مرتفع از هر لونی و ده کنیزک و هیفده غلام . (تاریخ بیهقی ). رجوع به هفده شود.<br></font></div>'),
(269496, 'هیفک', '<span class=\"hlight\">هیفک .</span> <font color=\"DarkGreen\"><b>[ هََ ف َ ]</font></b> (ع ص ) زن گول . (منتهی الارب ) (آنندراج ). حمقاء. (اقرب الموارد).<br></font></div>'),
(269497, 'هیق', '<span class=\"hlight\">هیق .</span> (اِخ ) دهی است از دهستان خانمرود بخش هریس شهرستان اهر. واقع در <span class=\"hlight\" dir=\"rtl\">١٩</span>هزارگزی شوسه ٔ تبریز به اهر و دارای <span class=\"hlight\" dir=\"rtl\">٢٥٧</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269498, 'هیق', '<span class=\"hlight\">هیق .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) دهی است از دهستان مواضعخان بخش ورزقان شهرستان اهر. واقع در <span class=\"hlight\" dir=\"rtl\">١١</span>هزارگزی شوسه ٔ تبریز به اهر و دارای <span class=\"hlight\" dir=\"rtl\">٨٢٦</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269499, 'هیق', '<span class=\"hlight\">هیق .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) شترمرغ که برای درازی آن به این نام خوانده شده .(اقرب الموارد). شترمرغ . (منتهی الارب ) (آنندراج ).<br>- <span class=\"hlight\">هیق ازق </span> ؛ اشترمرغ بسیارپر. (مهذب الاسماء).<br><BR><font color=\"Blue\">◄</font> (ص ) مرد دراز سخت دراز و گویند دراز و باریک . ج، اهیاق، هیوق . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> باریک و دراز از هر چیزی . رجوع به هیقم شود.<br></font></div>'),
(269500, 'هیق', '<span class=\"hlight\">هیق .</span> (اِخ )دهی است از دهستان مشکین باختری بخش مرکزی شهرستان خیاو. واقع در یک هزارگزی شوسه ٔ خیاو به اهر و دارای <span class=\"hlight\" dir=\"rtl\">١٩٣٥</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269501, 'هیقل', '<span class=\"hlight\">هیقل .</span> <font color=\"DarkGreen\"><b>[ هََ ق َ ]</font></b> (ع اِ) شترمرغ . (منتهی الارب ) (آنندراج ). ظلیم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سوسمار. (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(269502, 'هیقلة', '<span class=\"hlight\">هیقلة.</span> <font color=\"DarkGreen\"><b>[ هََ ق َ ل َ ]</font></b> (ع اِ) نوعی از رفتار. (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(269503, 'هیقم', '<span class=\"hlight\">هیقم .</span> <font color=\"DarkGreen\"><b>[ هََ ق َ ]</font></b> (ع اِ) آواز موج دریا. (اقرب الموارد) (منتهی الارب ) (آنندراج ). بانگ دریا. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> دریای فراخ دورتک . (منتهی الارب ) (آنندراج ). دریای پهناور. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آواز فروبردن لقمه . (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شترمرغ دراز. (منتهی الارب ). گویند هیق است و آخر کلمه میم زاید است . (از اقرب الموارد). رجوع به هیق شود.<br></font></div>'),
(269504, 'هیقمانی', '<span class=\"hlight\">هیقمانی .</span> <font color=\"DarkGreen\"><b>[ هََ ق َ نی ی ]</font></b> (ع ص ) شترمرغ دراز یا دراز از هر چیز. (از اقرب الموارد).<br></font></div>'),
(269505, 'هیقمانی', '<span class=\"hlight\">هیقمانی .</span> <font color=\"DarkGreen\"><b>[ هََق ُ نی ی ]</font></b> (ع ص ) درازبالا. (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269506, 'هیل', '<span class=\"hlight\">هیل .</span> (اِ) معروف است و به عربی قاقله ٔ صغار میگویند. (برهان ). دوایی است که به هندی الایچی سفید نامند. ظاهراً این معرب هیل است که به یای مجهول باشد و به عربی قاقله ٔصغار را گویند. (غیاث اللغات ). هل . هیل بوا. خیربوا. (یادداشت مؤلف ) (ذخیره ٔ خوارزمشاهی ) <span class=\"hlight\">:</span> <br>فلفل و میخک و بزباز و کبابه ی ْ چینی <br>جوز بویا بود و هیل و قرنفل در کار.<br><font color=\"Red\">بسحاق اطعمه .</font><br></font></div>'),
(269507, 'هیل', '<span class=\"hlight\">هیل .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) فروریختن بر چیزی خاک و ریگ را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> فروریختن آرد در انبان بی وزن و کیل . (منتهی الارب ) (اقرب الموارد). فروریختن .(دهار) (تاج المصادر بیهقی ) (ترجمان القرآن ) (مصادراللغه ). <BR><font color=\"Blue\">◄</font> روان کردن . <BR><font color=\"Blue\">◄</font> (اِ)مال بسیار. (دهار) (اقرب الموارد). مال بسیار یا ریگ یا باد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه فروریزد از ریگ و خاک و آرد و جز آن . و جاء بالهیل و الهیلمان ؛ مال بسیار آورد یا آورد ریگ و باد را. (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> قاقله ٔیمنی است یا فارسی، هندی الاجی است . (منتهی الارب ).<br></font></div>'),
(269508, 'هیل بوا', '<span class=\"hlight\">هیل بوا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ مرکب ) قاقله ٔ صغیره . رجوع به هیل و رجوع به تذکره ٔ ضریر انطاکی شود.<br></font></div>'),
(269509, 'هیل بویا', '<span class=\"hlight\">هیل بویا.</span> (اِ مرکب ) قاقله ٔ صغار. رجوع به هیل و هیل بوا شود.<br></font></div>'),
(269510, 'هیل غراب', '<span class=\"hlight\">هیل غراب .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ مرکب ) قاقله ٔ کبار. رجوع به قاقله شود.<br></font></div>'),
(269511, 'هیل هیل', '<span class=\"hlight\">هیل هیل .</span> (اِخ ) شاخه ای از تیره ٔ حاجی وند هیهاوند از طایفه ٔ چهارلنگ بختیاری . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٧٧</span>).<br></font></div>'),
(269512, 'هیلا', '<span class=\"hlight\">هیلا.</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (اِ) باشه را گویند و آن پرنده ای است شکاری کوچکتر از باز.(برهان ) (انجمن آرا) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِخ ) نام غولی ماده است در شعر ذیل از نظامی <span class=\"hlight\">:</span> <br>ماده هیلاو نام نر غیلاست <br>کارشان کردن بدی و بلاست .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(269513, 'هیلاج', '<span class=\"hlight\">هیلاج .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ <span class=\"hlight\" dir=\"rtl\">/</span> هی ]</font></b> (اِ) این لغت یونانی است و بعضی گویند هندی است ومعنی آن چشمه ٔ زندگانی باشد و آن را منجمان فارس «کدبانو» گویند و آن دلیل جسم مولود است چنانکه کدخدا دلیل روح باشد و کیفیت و کمیت عمر مولود را از این دو دلیل استخراج کنند. (از برهان ). سالی است منجمان را که بدان دلیل عمر را شناسند و مجازاً زایچه ٔ مولودرا نیز گویند. (آنندراج ) (غیاث اللغات ). دلیل جسم . (انجمن آرا). یکی از امور خمسه است، اول صاحب نوبت روز یا شب، دوم قمر به روز و شمس به شب، سوم درجه ٔ طالع، چهارم سهم السعاده، پنجم جزء اجتماع یا استقبال که پیش از تولد واقع شده باشد، یکی از این امور خمسه را در وقتی هیلاج نامند که با شرائط مخصوصه ٔ خود که در کتب نجوم مشروح است جمع آید و مجموع را هیالج یا هیلاجات خمسه خوانند و کدخداه کوکبی است که مستولی باشد بر موضع هیلاج، به این معنی که صاحب خانه ای باشد که هیلاج بالفعل در آن خانه است یا صاحب شرف آن یا صاحب خط دیگر از خطوطی که بدان موضع منسوب است و اگر هیلاجی باشد که کدخداه نداشته باشد و اگر هیچ یک از هیلاجات کدخداه نداشته باشد هیلاجیت از آن درجه ٔ طالع است . مثال هیلاج و کدخداه : اگر در وقت تولد مولود (در روز)قمر در <span class=\"hlight\" dir=\"rtl\">١٩</span> درجه ٔ حمل باشد قمر یکی از هیلاجات خمسه است به شرط اجتماع شرایط مخصوصه ٔ دیگر که در کتب نجوم مشروح است، و کدخداه در مثال مفروض آفتاب است، چه آفتاب مستولی است بر موضع هیلاج یعنی صاحب شرف آن است، چه شرف شمس در <span class=\"hlight\" dir=\"rtl\">١٩</span> درجه ٔ حمل است، و اگر در مثال مفروض درجه ٔ طالع در <span class=\"hlight\" dir=\"rtl\">١٩</span> درجه ٔ حمل باشد هیلاج درجه ٔ طالعخواهد بود و کدخداه باز شمس است و هکذا. و از امتزاج و ازدواج مجموع هیلاج و کدخداه بر سنین عمر مولود وطول و قصر و سعادت و نحوست آن استدلال کنند، علی زعمهم . (از حواشی چهارمقاله ٔ محمد قزوینی ) <span class=\"hlight\">:</span> <br>از طالع میلاد تو دیدند رصدها<br>اخترشمران رومی و یونانی و مائی <br>تسییر براندند براهین بفزودند<br>هیلاج نمودند که جاویدبقائی .<br> <font color=\"Red\">خاقانی (از انجمن آرا).</font><br>باد آن سعادات ابد بیت الحیاتت را مدد<br>هیلاج عمرت را عدد غایات اقصی داشته .<br> <font color=\"Red\">خاقانی .</font><br>نمونه باد در آئینه ٔ تصور خلق <br>ز طول و عرض جمال تو عالم معنی <br>به مهر و ماه که تأثیربخش هیلاج اند<br>دوام عمر تو دارد عطیه ٔ کبری .<br><font color=\"Red\">سیف اسفرنگ (از انجمن آرا).</font><br></font></div>'),
(269514, 'هیلاجیت', '<span class=\"hlight\">هیلاجیت .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هی جی ی َ ]</font></b> (ع مص جعلی، اِمص ) عمل هیلاج . سمت هیلاج .<br></font></div>'),
(269515, 'هیلار', '<span class=\"hlight\">هیلار.</span> (اِخ ) مستشرق فرانسوی (<span class=\"hlight\" dir=\"rtl\">١٨٠٥</span>-<span class=\"hlight\" dir=\"rtl\">١٨٩٥</span> م .). مطالعات و تحقیقاتی درباره ٔ ادیان ملل شرق بعمل آورده . از آثار اوست : <span class=\"hlight\" dir=\"rtl\">١</span>- بودا. <span class=\"hlight\" dir=\"rtl\">٢</span>- محمد و قرآن . (فرهنگ عمید).<br></font></div>'),
(269516, 'هیلان', '<span class=\"hlight\">هیلان .</span> <font color=\"DarkGreen\"><b>[ هََ ی َ ]</font></b> (ع اِ) آنچه فروریزد از ریگ . (از اقرب الموارد) (منتهی الارب ) (آنندراج ). رجوع به هَیل شود.<br></font></div>'),
(269517, 'هیلانیه', '<span class=\"hlight\">هیلانیه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) فرقه ای از فِرَق میان عیسی و محمد علیهماالسلام . (الفهرست ابن الندیم ).<br></font></div>'),
(269518, 'هیلبرت', '<span class=\"hlight\">هیلبرت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) داوید. ریاضی دان معروف آلمانی (<span class=\"hlight\" dir=\"rtl\">١٨٦٢</span>-<span class=\"hlight\" dir=\"rtl\">١٩٤٣</span> م .). در سال <span class=\"hlight\" dir=\"rtl\">١٨٩٩</span> کتابی به نام اصول اساسی هندسه تألیف و منتشر کرد. در علوم ریاضی مطالعات و ابداعاتی کرد. در <span class=\"hlight\" dir=\"rtl\">٨١</span>سالگی در اردوگاههای اسیران در اثر شکنجه ٔ عمال نازی درگذشت . (فرهنگ عمید).<br></font></div>'),
(269519, 'هیلة', '<span class=\"hlight\">هیلة.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ع اِ) ترس و کار هولناک . (منتهی الارب ). مخافة و ترس . (اقرب الموارد).<br></font></div>'),
(269520, 'هیلة', '<span class=\"hlight\">هیلة.</span> <font color=\"DarkGreen\"><b>[ هََ ل َ ]</font></b> (اِخ ) نام بزی که زالی را بود که دوشنده اگر بر وی سختی کردی شیر دادی و الا سرون زدی . (آنندراج ) (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269521, 'هیلع', '<span class=\"hlight\">هیلع.</span><font color=\"DarkGreen\"><b>[ هََ ل َ ]</font></b> (ع ص ) سست و ضعیف . (از اقرب الموارد).<br></font></div>'),
(269522, 'هیللة', '<span class=\"hlight\">هیللة.</span> <font color=\"DarkGreen\"><b>[ هََ ل َ ل َ ]</font></b> (ع مص جعلی ) لااله الااﷲ گفتن . (المصادر زوزنی ) (منتهی الارب ) (دهار). و این مصدری است منحوت چون حوقلة که مصدری است و از لاحول ولاقوة الاباﷲ ریخته و تراشیده شده است . (از اقرب الموارد).<br></font></div>'),
(269523, 'هیلمان', '<span class=\"hlight\">هیلمان .</span> <font color=\"DarkGreen\"><b>[هََ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ُ ]</font></b> (ع اِ) بسیار از مال و جز آن : جاء بالهیل و الهیلمان ؛ مال بسیار آورد یا آورد ریگ و باد را. (منتهی الارب ). هِلِمّان . گویند: جأنا بالهیل و الهیلمان ؛ اذا جاء بالمال الکثیر. (اقرب الموارد).<br></font></div>'),
(269524, 'هیله', '<span class=\"hlight\">هیله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) بر وزن و معنی حیله باشد. <BR><font color=\"Blue\">◄</font> و کلمه ٔ نیک را نیز گویند. (برهان ).<br></font></div>'),
(269525, 'هیلو', '<span class=\"hlight\">هیلو.</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (اِ) هلیو. گردکان بازی .<br></font></div>'),
(269526, 'هیلوی', '<span class=\"hlight\">هیلوی .</span> (اِ) بازی . (برهان ). رجوع به مدخل قبل شود.<br></font></div>'),
(269527, 'هیلوی', '<span class=\"hlight\">هیلوی .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (اِ) چهارمغز بازی و گردکان بازی را گویند و به کسر اول هم آمده است لیکن به معنی بازی لا علی التعیین . (برهان ).<br></font></div>'),
(269528, 'هیلکون', '<span class=\"hlight\">هیلکون .</span> <font color=\"DarkGreen\"><b>[ هََ ل َ ]</font></b> (ع اِ) داس بی دندان . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269529, 'هیلی', '<span class=\"hlight\">هیلی .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) ناحیتی است به هند که سنداپور بدانجا است . رجوع به کلمه ٔ طباشیر در مفردات ابن البیطار شود.<br></font></div>'),
(269530, 'هیلیدن', '<span class=\"hlight\">هیلیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) فروگذاشتن و ترک دادن و فروانداختن . (برهان ) (آنندراج ). هلیدن . رجوع به هلیدن شود.<br></font></div>'),
(269531, 'هیم', '<span class=\"hlight\">هیم .</span> (ع ص، اِ) ج ِ اهیم . (اقرب الموارد). شتران تشنه . (ترجمان القرآن ) (منتهی الارب ).<br></font></div>'),
(269532, 'هیم', '<span class=\"hlight\">هیم .</span> <font color=\"DarkGreen\"><b>[ هَُ ی ُ ]</font></b> (ع ص، اِ) ج ِ هَیام و هُیام . (منتهی الارب ) (از اقرب الموارد). رجوع به هیام شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(269533, 'هیم', '<span class=\"hlight\">هیم .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع مص ) شیفته گشتن به عشق . (دهار). دوست داشتن زن را. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> عاشق گردیدن و سرگشته و شیفته شدن از عشق و رفتن بغیر اراده و مراد. (آنندراج ) (اقرب الموارد). شیفته شدن به عشق و روی بنهادن به جایی . (المصادر زوزنی ). روی به جایی نهادن از عشق و جز آن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> (اِمص ) سرگشتگی . (غیاث اللغات ). رجوع به هیوم و هیام و هیمان شود. <BR><font color=\"Blue\">◄</font> (اِ) هیم اﷲ؛ ایم اﷲ، به ابدال همزه به هاء. (از اقرب الموارد)؛ یعنی سوگند خدای را. (منتهی الارب ).<br></font></div>'),
(269534, 'هیم', '<span class=\"hlight\">هیم .</span> (اِ) هیمه .هیزم سوختنی . (آنندراج ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br>دلم مرگ پسرعم سوخت و در جانم زد آن آتش <br>که هیمش عرق شریان گشت و دودش روح حیوانی .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(269535, 'هیم', '<span class=\"hlight\">هیم .</span> <font color=\"DarkGreen\"><b>[ هََ ی َ ]</font></b> (فعل ) صورتی و تلفظی محلی از کلمه ٔ «هستم » یعنی موجودم و حیات دارم و حاضرم . (از آنندراج ) (از برهان ) <span class=\"hlight\">:</span> <br>هیم به پله ٔ نیکی کم از سپندانی <br>به پله ٔ بدی اندر هزار سندانم .<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(269536, 'هیما', '<span class=\"hlight\">هیما.</span> <font color=\"DarkGreen\"><b>[ هََ]</font></b> (ع ص ) بیابان بی آب . (دهار). رجوع به هیماء شود.<br></font></div>'),
(269537, 'هیمالایا', '<span class=\"hlight\">هیمالایا.</span> (اِخ ) هیمالیا. سلسله ٔ جبالی است در شمال شبه قاره ٔ هند مابین سند و برهماپوترا و هندوستان و تبت به امتداد <span class=\"hlight\" dir=\"rtl\">٢٧٠٠</span> کیلومتر و پهنای <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> کیلومتر. بلندترین قلل آن اوِرِسْت به ارتفاع <span class=\"hlight\" dir=\"rtl\">٨٨٨٢</span> متر بلندترین قلل عالم و کین چین جین گا به ارتفاع <span class=\"hlight\" dir=\"rtl\">٨٥٨١</span> متر. قله های آن همیشه پوشیده از برف و دارای یخچالهای عظیم است . رودهای گنگ وسند از دامنه های آن سرچشمه میگیرد. (فرهنگ عمید).<br></font></div>'),
(269538, 'هیمان', '<span class=\"hlight\">هیمان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) تشنه . (منتهی الارب ) (مهذب الاسماء). عطشان . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیفته و سرگشته . (منتهی الارب ). محب شدیدالوجد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر هیمازده . (منتهی الارب ). شتر مبتلی به مرض هیام . (اقرب الموارد). مؤنث آن هَیمی ̍. (اقرب الموارد).<br></font></div>'),
(269539, 'هیمان', '<span class=\"hlight\">هیمان .</span><font color=\"DarkGreen\"><b>[ هََ ی َ ]</font></b> (ع مص ) دوست داشتن زن را. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عاشق گردیدن و سرگشته و شیفته شدن از عشق و رفتن بر غیر اراده و مراد. (المصادر زوزنی ) (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> هامت الناقة هَیَماناً؛ ذهبت علی وجهه <font color=\"DarkGreen\"><b>[ وجهها ]</font></b> لرعی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) سرگشتگی و حیرانی . (غیاث اللغات از سراج و منتخب ).<br></font></div>'),
(269540, 'هیمغ', '<span class=\"hlight\">هیمغ.</span> <font color=\"DarkGreen\"><b>[ هََ م َ ]</font></b> (ع اِ) درخت مغد. (منتهی الارب ) (آنندراج ). شجرةالمَغد. (اقرب الموارد).<br></font></div>'),
(269541, 'هیمنة', '<span class=\"hlight\">هیمنة.</span> <font color=\"DarkGreen\"><b>[هََ م َ ن َ ]</font></b> (ع مص ) آمین گفتن . <BR><font color=\"Blue\">◄</font> بال گستردن طایر بر بچه ٔ خود. <BR><font color=\"Blue\">◄</font> نگاهبان و رقیب گردیدن بر چیزی . (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) در تداول، شکوه و وقار و مهابت که از بزرگی و عظمت کسی در دل افتد. (یادداشت مؤلف ).<br></font></div>'),
(269542, 'هیمه', '<span class=\"hlight\">هیمه .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ <span class=\"hlight\" dir=\"rtl\">/</span> هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ) هیزم سوختنی . (برهان ). هیزم سوختنی و به فتح نیز آمده است . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br>در او آتشی روشن افروخته <br>بر او هیمه خروارها سوخته .<br> <font color=\"Red\">نظامی .</font><br>در او ده پانزده من عود چون مشک <br>بسوزاندی بجای هیمه ٔ خشک .<br> <font color=\"Red\">نظامی .</font><br>گر هیمه عود گردد و گر سنگ دُر شود<br>مشنو که چشم آدمی از سنگ پر شود.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هیمه انداختن </span> ؛ هیزم افکندن درون تنوری یا آتشدانی .<br>- <span class=\"hlight\">هیمه خانه </span> ؛ جای هیمه . هیمه دان . هیزم دان . (تذکرةالملوک ).<br>- <span class=\"hlight\">هیمه دان </span> ؛ هیمه ستان . محتطب . هیمه خانه . هیزم دان .<br>- <span class=\"hlight\">هیمه فروختن </span> ؛ هیزم فروختن .<br>- <span class=\"hlight\">هیمه کش </span> ؛ هیزم کش . حمال حطب .<br>- <span class=\"hlight\">هیمه کشی </span> ؛ هیزم کشی .<br>- <span class=\"hlight\">هیمه کشیدن </span> ؛ هیزم کشیدن .<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">احمدک به هیمه نمی رفت بردندش </span> .<br> <span class=\"hlight\">چون خانه بسوزانی به هیمه درنمانی </span> . (مثل هندی، نقل از نسخه ٔ خطی شاهد صادق متعلق به مهدیقلی خان هدایت ).<br> <span class=\"hlight\">هیمه ٔ تر به کسی فروختن </span> ؛ کنایه از مکر و حقه و تزویر کردن . (برهان ) (آنندراج ):<br> <span class=\"hlight\">تا کی از شور درون ای سخت جان </span> <br>هیمه ٔ تر میفروشی با کسان .<br><BR><font color=\"Blue\">◄</font> گوشتابه . (برهان ).رجوع به هَیمه شود.<br></font></div>'),
(269543, 'هیمه', '<span class=\"hlight\">هیمه .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ) گوشتابه . (برهان ). رجوع به مدخل بعد شود.<br></font></div>'),
(269544, 'هیمی', '<span class=\"hlight\">هیمی .</span> <font color=\"DarkGreen\"><b>[ هََ ما ]</font></b> (ع ص ) مؤنث هیمان . (منتهی الارب ) (اقرب الموارد) (آنندراج ). شتر مبتلا به هیام . (از اقرب الموارد). رجوع به هیمان شود.<br></font></div>'),
(269545, 'هیمیا', '<span class=\"hlight\">هیمیا.</span> (اِ) علم طلسم است . (غیاث اللغات ). یکی از علوم خفیه است . (یادداشت مؤلف ). رجوع به هیماء شود.<br></font></div>'),
(269546, 'هین', '<span class=\"hlight\">هین .</span> (صوت ) کلمه ای است که بجهت تأکید گویند یعنی بشتاب و زود باش . (انجمن آرا) (آنندراج ). کلمه ای است به معنی زود و شتاب و تعجیل که درمحل تأکید و امر گویند یعنی زود باش و بشتاب . (برهان ). شتاب فرمودن است . (لغت نامه ٔ اسدی ) <span class=\"hlight\">:</span> <br>از کوهسار دوش به رنگ می <br>هین آمد ای نگار می آور هین .<br> <font color=\"Red\">دقیقی .</font><br>هین بگو ای فیض رحمت هین بگو ای ظل حق <br>هین بگو ای حرز امت هین بگو ای مقتدا.<br> <font color=\"Red\">خاقانی .</font><br>به شیرین گفت هین تا رخش تازیم <br>بر این پهنه زمانی گوی بازیم .<br> <font color=\"Red\">نظامی .</font><br>در دلم افتاد آتش ساقیا<br>ساقیا آخر کجایی هین بیا.<br> <font color=\"Red\">عطار.</font><br>گفت هین اکنون چه میخواهی بخواه <br>گفت فرما باد را ای جان پناه .<br> <font color=\"Red\">مولوی .</font><br>هین غذای دل بده ار همدلی <br>رو بجو اقبال را از مقبلی .<br> <font color=\"Red\">مولوی .</font><br>مؤذن گریبان گرفتش که هین <br>سگ ومسجد ای فارغ از عقل و دین .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> (ضمیر، اِ) این و اینک . هذا. (برهان ). <BR><font color=\"Blue\">◄</font> گفتن . (برهان ). در کردی معنی «چه گفتید»دارد. (حواشی برهان چ معین ).<br>- هان و هین <span class=\"hlight\">:</span> <br>وز این بند بگشای و بستان و ده <br>وز این هان و هین و از این گیر و دار.<br> <font color=\"Red\">ناصرخسرو.</font><br>چه داری جواب محمد به محشر<br>چو پیش آیدت هان و هین محمد.<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(269547, 'هین', '<span class=\"hlight\">هین .</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ ی ِ <span class=\"hlight\" dir=\"rtl\">/</span>هََ ی ِ ]</font></b> (ع ص ) نرم و آسان . (منتهی الارب ). سهل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ضعیف و ذلیل . (اقرب الموارد). سست و خوار. <BR><font color=\"Blue\">◄</font> سبک . (منتهی الارب ).<br></font></div>'),
(269548, 'هین', '<span class=\"hlight\">هین .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) نرم . <BR><font color=\"Blue\">◄</font> آسان . <BR><font color=\"Blue\">◄</font> سبک . (منتهی الارب ).<br></font></div>'),
(269549, 'هین', '<span class=\"hlight\">هین .</span> (اِخ ) دهی است جزء دهستان مزدقانچای بخش نوبران شهرستان ساوه . دارای <span class=\"hlight\" dir=\"rtl\">١٣٢</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(269550, 'هین', '<span class=\"hlight\">هین .</span> (اِ) سیل . سیلاب . (فرهنگ اسدی ) (انجمن آرا) (آنندراج ) <span class=\"hlight\">:</span> <br>از کوهسار دوش به رنگ می <br>هین آمد ای نگار می آور هین .<br> <font color=\"Red\">دقیقی .</font><br>هینی به گاه جنگ به تک خاسته ز کوه <br>هین بزرگ بازنگردد به هین و هی .<br> <font color=\"Red\">منوچهری .</font><br>- <span class=\"hlight\">هین آمدن </span> ؛ سیل آمدن . سیل جاری شدن .<br>- <span class=\"hlight\">هین گرفتن </span> ؛ سیل گرفتن . در سیل فرورفتن . غرقه شدن در سیل <span class=\"hlight\">:</span> <br>دم خون چو رود مهین هین گرفت <br>ز غم چهره ٔ شاه چین چین گرفت .<br> <font color=\"Red\">اسدی (گرشاسبنامه ص <span class=\"hlight\" dir=\"rtl\">٤٠٩</span>).</font><br>شل و خشت پرواز شاهین گرفت <br>ز باران خون کوه در هین گرفت .<br><font color=\"Red\">اسدی (گرشاسبنامه ص <span class=\"hlight\" dir=\"rtl\">٨٠</span>).</font><br></font></div>'),
(269551, 'هین', '<span class=\"hlight\">هین .</span> (صوت ) آوازی که بدان خر را زجر کنند <span class=\"hlight\">:</span> <br>هان و هینش کنم از حکمت زیرا خر<br>بازگردد ز ره گمره به هان و هین .<br> <font color=\"Red\">ناصرخسرو.</font><br>- <span class=\"hlight\">هین و هی </span> ؛ حکایت صوت بازداشتن و منع کردن کسی یا چیزی از حرکت <span class=\"hlight\">:</span> <br>هین بزرگ بازنگردد به هین و هی .<br><font color=\"Red\">منوچهری .</font><br></font></div>'),
(269552, 'هین آباد', '<span class=\"hlight\">هین آباد.</span> (اِخ ) دهی است جزء دهستان دهیکله ٔ بخش هوراند شهرستان اهر. دارای <span class=\"hlight\" dir=\"rtl\">٤٤٧</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269553, 'هینام', '<span class=\"hlight\">هینام .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ) هینوم . سخنی که فهمیده نشود. (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269554, 'هیناهین', '<span class=\"hlight\">هیناهین .</span> (اِ مرکب ) شتابزدگی . (صحاح الفرس ). عجله . تعجیل . (برهان ). شتاب در شتاب . (آنندراج ) (انجمن آرا) <span class=\"hlight\">:</span> <br>بکند رخنه نظم حال مرا<br>در چنین گیر و دار و هیناهین .<br><font color=\"Red\">انوری (از آنندراج ) (انجمن آرا).</font><br></font></div>'),
(269555, 'هینة', '<span class=\"hlight\">هینة.</span> <font color=\"DarkGreen\"><b>[هََ ی ْ ی ِ ن َ ]</font></b> (ع ص ) تأنیث هَیِّن و هَیِن، به معنی سهل و آسان . (از اقرب الموارد). رجوع به هین شود.<br></font></div>'),
(269556, 'هینة', '<span class=\"hlight\">هینة.</span> <font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (ع ص ) مؤنث هین . (از اقرب الموارد). رجوع به هین شود.<br></font></div>'),
(269557, 'هینة', '<span class=\"hlight\">هینة.</span><font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (ع اِ) روش . (منتهی الارب ) (آنندراج ). برای نوع است . (از اقرب الموارد). آهستگی و وقار. (منتهی الارب ) (آنندراج ). سکینه و وقار. (از اقرب الموارد).<br></font></div>'),
(269558, 'هیند', '<span class=\"hlight\">هیند.</span> (اِخ ) هند است که هندوستان باشد. (آنندراج ) (برهان ). رجوع به هندوستان شود.<br></font></div>'),
(269559, 'هیند', '<span class=\"hlight\">هیند.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (فعل ) صورتی و تلفظی محلی از کلمه ٔ هستند <span class=\"hlight\">:</span> <br>گفت یارب گر تو را خاصان هیند<br>که مبارک دعوت و فرخ پیند.<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(269560, 'هینم', '<span class=\"hlight\">هینم .</span><font color=\"DarkGreen\"><b>[ هََ ن َ ]</font></b> (ع اِ) پنبه . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269561, 'هینمة', '<span class=\"hlight\">هینمة.</span> <font color=\"DarkGreen\"><b>[ هََ ن َ م َ ]</font></b> (ع اِ) آواز نرم و خفی . (منتهی الارب ) (آنندراج ) (از اقرب الموارد). آواز خفی که به فهم نیاید. آواز پنهان . (مهذب الاسماء). باژ <span class=\"hlight\">:</span> آنگاه که قیس بن نسیبه درک صحبت رسول کرد و به قوم خود بنوسلیم بازگشت گفت : قد سمعت ترجمة الروم و هینمة فارس و اشعار العرب و کهانة الکاهن و... فما یشبه کلام محمد شیئاً من کلامهم . (طبقات ابن سعد در باب وفد سلیم جزء ثانی ص <span class=\"hlight\" dir=\"rtl\">٧١</span> چ قاهره سال <span class=\"hlight\" dir=\"rtl\">١٣٥٨</span>). <BR><font color=\"Blue\">◄</font> تره ای است . (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(269562, 'هینوم', '<span class=\"hlight\">هینوم .</span> <font color=\"DarkGreen\"><b>[ هََ]</font></b> (ع اِ) هینام . سخنی که فهمیده نشود. (از اقرب الموارد) (منتهی الارب ) (آنندراج ). رجوع به هینام شود.<br></font></div>'),
(269563, 'هینون', '<span class=\"hlight\">هینون .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص، اِ) ج ِ هین . (از اقرب الموارد). رجوع به هین شود.<br></font></div>'),
(269564, 'هینون', '<span class=\"hlight\">هینون .</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ ی ِ ]</font></b> (ع ص، اِ) ج ِ هَیِّن . (منتهی الارب ) (از اقرب الموارد). رجوع به هین شود.<br></font></div>'),
(269565, 'هیه', '<span class=\"hlight\">هیه .</span> <font color=\"DarkGreen\"><b>[ هََ ی ْه ْ ]</font></b> (ع ص ) آنکه دور دارند او را و یکسو کنند جهت چرکینی جامه ٔ وی . (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(269566, 'هیه هیه', '<span class=\"hlight\">هیه هیه .</span> <font color=\"DarkGreen\"><b>[ هی هَِ هی هَِ ]</font></b> (ع صوت )کلمه ٔ استزادت است و گاهی بدان چیزی را رانند و طردکنند. (منتهی الارب ) (از اقرب الموارد) (آنندراج ).<br></font></div>'),
(269567, 'هیهات', '<span class=\"hlight\">هیهات .</span> <font color=\"DarkGreen\"><b>[ هََ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ <span class=\"hlight\" dir=\"rtl\">/</span> ت ُ ]</font></b> (ع اِ فعل، صوت ) چه دور است . (ترجمان القرآن جرجانی ). مبنی و معرب است . دور است و در آن لغاتی است . (منتهی الارب ). و فارسیان در مقام تحسر و تأسف استعمال نمایند.(آنندراج ). اسم فعل است و معنی آن دور است و در آن پنجاه ویک لغت آمده است . (اقرب الموارد) <span class=\"hlight\">:</span> <br>امید وفا دارم هیهات که امروز<br>در گوهر آدم بود این گوهر نایاب .<br> <font color=\"Red\">خاقانی .</font><br>روزگارم وفا کند هیهات <br>روزگار این به روزگار کند.<br> <font color=\"Red\">خاقانی .</font><br>درخور تخت و آفرین باشد<br>لیک هیهات اگر چنین باشد.<br> <font color=\"Red\">نظامی .</font><br>دگر سر من و بالین عافیت هیهات <br>بدین هوس که سر خاکسارمن دارد.<br> <font color=\"Red\">سعدی .</font><br>که هیهات قدرتو نشناختم <br>به شکر قدومت نپرداختم .<br> <font color=\"Red\">سعدی .</font><br>رود به خواب دو چشم از خیال تو؟ هیهات <br>بود صبور دل اندر فراق تو؟ حاشاک .<br> <font color=\"Red\">حافظ.</font><br>آنچه در مدت هجر تو کشیدم هیهات <br>در یکی نامه محال است که تحریر کنم .<br> <font color=\"Red\">حافظ.</font><br>سینه ٔ تنگ من و بار غم او؟ هیهات <br>مرد این بار گران نیست دل مسکینم .<br> <font color=\"Red\">حافظ.</font><br>هیهات چگونه سر کند کس <br>ره بر دم تیغ و پای در خس .<br><font color=\"Red\">ابوالفضل فیاضی (از آنندراج ).</font><br></font></div>'),
(269568, 'هیهان', '<span class=\"hlight\">هیهان .</span> <font color=\"DarkGreen\"><b>[هََ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن ُ ]</font></b> (ع اِ فعل ) معرب و مبنی است و به معنی هیهات است . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(269569, 'هیهاه', '<span class=\"hlight\">هیهاه .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع اِ فعل ) به معنی هیهات است . (منتهی الارب ).<br></font></div>'),
(269570, 'هیهای', '<span class=\"hlight\">هیهای .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (اِ مرکب ) هیاهو <span class=\"hlight\">:</span> <br>شهر را بگذاشت وانسو رای کرد<br>قصد جست وجوی آن هیهای کرد.<br> <font color=\"Red\">مولوی .</font><br>دمدمه ی ْ این روح از دمهای اوست <br>های و هوی روح از هیهای اوست .<br> <font color=\"Red\">مولوی .</font><br>و رجوع به های و هوی و هیاهو شود.<br></font></div>'),
(269571, 'هیهنا', '<span class=\"hlight\">هیهنا.</span> <font color=\"DarkGreen\"><b>[ ها هَُ ]</font></b> (ع ق ) اینجا. رجوع به ههنا شود.<br></font></div>'),
(269572, 'هیو', '<span class=\"hlight\">هیو.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) قصبه ای جزء دهستان فشند بخش کرج شهرستان تهران . دارای <span class=\"hlight\" dir=\"rtl\">٢٤٢٩</span> تن سکنه است . آب آن از چشمه سار. محصول آن غلات، بنشن، صیفی، باغات انگور، میوه جات، عسل، لبنیات و شغل اهالی زراعت و گله داری است و برخی در معدن ذغال سنگ کار می کنند. دبستان دارد. مزرعه ٔ سرای حشمت آباد واقع در کنار راه شوسه جزء این ده است . راه مالرو دارد و از قهوه خانه ٔ شاه دوست که سر راه شوسه واقعاست ماشین میرود. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(269573, 'هیوان', '<span class=\"hlight\">هیوان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) شهری است <font color=\"DarkGreen\"><b>[ به هندوستان ]</font></b> بر سر کوه نهاده و از این شهر آبی فرودآید به دامن کوه و اندر کشت به کار شود. (حدود العالم ).<br></font></div>'),
(269574, 'هیوب', '<span class=\"hlight\">هیوب .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) ترسان و بیمناک . (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد بددل . (منتهی الارب ) (آنندراج ). بددل و هراسان . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> آنکه از وی ترسند. (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(269575, 'هیوبة', '<span class=\"hlight\">هیوبة.</span> <font color=\"DarkGreen\"><b>[ هََ ب َ ]</font></b> (ع ص ) مرد بددل . (منتهی الارب ) (از اقرب الموارد). رجوع به هیوب شود.<br></font></div>'),
(269576, 'هیودی', '<span class=\"hlight\">هیودی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) شاخه ای از تیره ٔ پولادوند هیهاوند ازطایفه ٔ چهارلنگ بختیاری . (جغرافیای سیاسی کیهان ).<br></font></div>'),
(269577, 'هیوره', '<span class=\"hlight\">هیوره .</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ی ْ وَ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b>(اِ) ریخت و هیأتی زشت . (یادداشت مؤلف ). هیبره .<br>- <span class=\"hlight\">بدهیوره </span> ؛ ریخت و هیأت زشت و کریه وبد. تأکید و تأییدی در بدی آن است . (یادداشت مؤلف ).<br></font></div>'),
(269578, 'هیوسیامین', '<span class=\"hlight\">هیوسیامین .</span> <font color=\"DarkGreen\"><b>[ هی ُ ]</font></b> (اِ) گردی است بی رنگ به شکل سوزنهای ریز و طعم آن نامطبوع است . در آب کمی حل شده ودر الکل و اتر و کلروفرم بخوبی محلول است . معمولاً سولفات هیوسیامین را که تنها ملح افینیال آن است در تراپوتیک به کار می برند. سولفات هیوسیامین  به شکل سوزنهای ریز سفیدی متبلور شده در آب بخوبی محلول و <span class=\"hlight\" dir=\"rtl\">٨١</span> درصد هیوسیامین دارد. این دارو حدقه را سریعتر از اتروپین متسع میکند و برای این کار چند قطره از محلول پنج سانتی گرم سولفات هیوسیامین در ده گرم آب کفایت میکند. این دارو را در تمام مواردی که ژوسکیام به کار برده میشود میتوان استعمال نمود. میزان معمولی استعمال آن ربع میلی گرم تا نیم میلی گرم و حداکثر مقدار استعمال آن در یک بار نیم میلی گرم و در <span class=\"hlight\" dir=\"rtl\">٢٤</span> ساعت یک گرم است . (درمان شناسی ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(269579, 'هیوع', '<span class=\"hlight\">هیوع .</span> <font color=\"DarkGreen\"><b>[ هَُ]</font></b> (ع مص ) هیع. هیعة. هیعوعة. هیعان . بددل گشتن . (منتهی الارب ) (آنندراج ). بددل شدن . (المصادر زوزنی ). ترسیدن . بددلی کردن . (تاج المصادر بیهقی ). ترسیدن و بی تابی و فزع کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرسنه شدن . (منتهی الارب ). رجوع به هیع و هیعان شود.<br></font></div>'),
(269580, 'هیوف', '<span class=\"hlight\">هیوف .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) مرد زود تشنه شونده یا سخت تشنه . (منتهی الارب ) (از اقرب الموارد) (آنندراج ). هیفان . مهیاف . (اقرب الموارد).<br></font></div>'),
(269581, 'هیوفاریقون', '<span class=\"hlight\">هیوفاریقون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) هوفاریقون . رمان الانهار. اندروسامن . رجوع به هوفاریقون شود.<br></font></div>'),
(269582, 'هیوفاقسطیداس', '<span class=\"hlight\">هیوفاقسطیداس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) هیوفسطیداس . هیوفقطیداس . رجوع به هیوفسطیداس شود.<br></font></div>'),
(269583, 'هیوفسطیداس', '<span class=\"hlight\">هیوفسطیداس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) ابوسهلان و آن نوعی از طراثیث است . (یادداشت مؤلف ).<br></font></div>'),
(269584, 'هیوفقطیداس', '<span class=\"hlight\">هیوفقطیداس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) هیوفسطیداس . نوعی از طرثوث کوچک است . (یادداشت مؤلف ). از قوابض است . (قانون بوعلی کتاب سوم ص <span class=\"hlight\" dir=\"rtl\">٢١١</span>).<br></font></div>'),
(269585, 'هیوق', '<span class=\"hlight\">هیوق .</span><font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (ع اِ) اَهْیاق . ج ِ هیق، به معنی اشترمرغ . (مهذب الاسماء) (از اقرب الموارد). رجوع به هیق شود.<br></font></div>'),
(269586, 'هیول', '<span class=\"hlight\">هیول .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (معرب، اِ) گرد پراکنده روشنی آفتاب که در خانه نمایان گردد. معرب است . (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(269587, 'هیولا', '<span class=\"hlight\">هیولا.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (معرب، اِ) ماده ٔ هر چیز. (غیاث اللغات ) (آنندراج ). مقابل صورت <span class=\"hlight\">:</span> <br>هیولا را اگر وصفی کنی بیرون برد مقدور<br>که باشد بی خلاف آنگه ز خردو واحد و یکتا.<br> <font color=\"Red\">ناصرخسرو.</font><br>گشایم راز لاهوت از تفرد<br>نمایم ساز ناسوت از هیولا.<br> <font color=\"Red\">خاقانی .</font><br>رجوع به هیولی شود.<br></font></div>'),
(269588, 'هیولانی', '<span class=\"hlight\">هیولانی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ص نسبی ) منسوب به هیولی . (از اقرب الموارد). «هیولا» که ماده ٔ هر شی ٔ را گویند و در حالت نسبت نون زاید هم می آورند چنانکه در حقانی و ربانی و روحانی الف و نون زاید است . (غیاث اللغات ). مادی . جسمانی <span class=\"hlight\">:</span> <br>با تو از قوت هیولانی <br>ستد و داد روح حیوانی .<br> <font color=\"Red\">سنایی .</font><br>ز مردمان مشمر خویشتن به هیأت و شکل <br>که مردمی نه همین هیکل هیولانی ست .<br> <font color=\"Red\">انوری .</font><br>تو را که صورت جسم تو را هیولانی ست <br>چو جوهر ملکی در لباس انسانی .<br> <font color=\"Red\">حافظ.</font><br>به کنه جوهر ذات تو چون رسم هیهات <br>هنوز طفل صفت عقل من هیولانی .<br> <font color=\"Red\">طالب آملی (از آنندراج ).</font><br>- <span class=\"hlight\">عقل هیولانی </span> . رجوع به عقل شود.<br></font></div>'),
(269589, 'هیولی', '<span class=\"hlight\">هیولی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (معرب، اِ) ممال هیولی ̍ (هیولا) <span class=\"hlight\">:</span> <br>همیشه تا ز ره عقل بر عقول و نفوس <br>تقدمی نبود صورت و هیولی را.<br><font color=\"Red\">ظهیر فاریابی .</font><br></font></div>'),
(269590, 'هیولی', '<span class=\"hlight\">هیولی .</span> <font color=\"DarkGreen\"><b>[ هََ لا ]</font></b> (معرب، اِ) (اصطلاح فلسفه ) عنصر. مایه . ماده، مقابل صورت . این لفظ یونانی است و به معنی اصل و ماده و در اصطلاح فلسفه آن جوهری است درجسم که آنچه بر جسم عارض میشود از آن اتصال و انفصال می پذیرد و آن محل است برای صورت جسمی و صورت نوعی .(تعریفات سید جرجانی ). هیولی به نزد حکماء چیزی است که صورتها را به طور مطلق می پذیرد بدون تخصیص به صورتی معین و آن را ماده نیز گویند چنانکه در بحرالجواهربدان اشاره رفته است و در کشف اللغات گوید: هیولی چیزی است که صورت اسماء در آن ظاهر گردد و صوفیه آن رااعیان ثابته گویند و متکلمان حقایق اشیاء و حکماء ماهیات اشیاء. (از کشاف اصطلاحات الفنون ) <span class=\"hlight\">:</span> <br>تا از آن جامد اثر گیرد ضمیر<br>حبذا نان بی هیولای خمیر.<br> <font color=\"Red\">مولوی .</font><br>هیولی بر چهار قسم است چنانکه در شرح صحائف نیز آمده است : هیولای اولی، هیولای ثانی، هیولای ثالث و هیولای رابع. (کشاف اصطلاحات الفنون ).<br>- <span class=\"hlight\">هیولای اول </span> ؛ کنایه از جوهر اول . (غیاث اللغات )(آنندراج ) <span class=\"hlight\">:</span> <br>هیولای اول بیان کن که چیست <br>سوءالم ز کم و ز کیف و چراست .<br> <font color=\"Red\">ناصرخسرو.</font><br>- <span class=\"hlight\">هیولای اولی </span>؛ جوهری است غیرجسم محل است برای متصل بذاته و آن صورت جسمیه است . برای تفصیل بیشتر به کشاف اصطلاحات الفنون مراجعه شود.<br>- <span class=\"hlight\">هیولای ثالثه </span> ؛اجسام هستند با صورت نوعیه ٔ آنها که محل است برای صورتهای دیگر چون چوب برای صورت تخت و گل برای صورت کوزه . (کشاف اصطلاحات الفنون ).<br>- <span class=\"hlight\">هیولای ثانی </span> ؛ هیولای ثانیه <span class=\"hlight\">:</span> <br>هیولای ثانی نمودی به من <br>پذیرفتم و هم بر اینم رضاست .<br> <font color=\"Red\">ناصرخسرو.</font><br>رجوع به هیولای ثانیه شود.<br>- <span class=\"hlight\">هیولای ثانیه </span> ؛ جسمی است که صورت بدان قیام دارد چون اجسام نسبت به صورتهای نوعیه ٔ آنها. (کشاف اصطلاحات الفنون ).<br>- <span class=\"hlight\">هیولای رابعه </span> ؛ آن این است که جسم با هردو صورت آن محل باشد برای صورت چون اعضاء برای صورت بدن . بدین ترتیب ملاحظه میشود که هیولای اولی جزو جسم است و هیولای ثانیه خود جسم است و هیولای ثالثه و رابعه، جسم جزو آنها است . (کشاف اصطلاحات الفنون از شرح صحائف ).<br></font></div>'),
(269591, 'هیولی', '<span class=\"hlight\">هیولی .</span> <font color=\"DarkGreen\"><b>[ هََ لا <span class=\"hlight\" dir=\"rtl\">/</span> هََ ی ْ یو لا ]</font></b> (ع اِ) پنبه . (منتهی الارب ) (از اقرب الموارد). قطن . (اقرب الموارد). پیشینیان سرشت جهان را بدان تشبیه کرده اند و نسبت بدان هیولی ّ و هیولانی است . (از اقرب الموارد).<br></font></div>'),
(269592, 'هیولی', '<span class=\"hlight\">هیولی .</span> <font color=\"DarkGreen\"><b>[ هََ لی ی ]</font></b> (ص نسبی ) هیولانی . منسوب به هَیولی ̍. (از اقرب الموارد). رجوع به هَیولی ̍ شود.<br></font></div>'),
(269593, 'هیولیات', '<span class=\"hlight\">هیولیات .</span> <font color=\"DarkGreen\"><b>[ هََ ل َ ]</font></b> (ع اِ) ج ِ هَیولی ̍. (از اقرب الموارد). رجوع به هیولی شود.<br></font></div>'),
(269594, 'هیوم', '<span class=\"hlight\">هیوم .</span> (اِخ ) دیوید. فیلسوف و مورخ انگلیسی (<span class=\"hlight\" dir=\"rtl\">١٧١١</span>-<span class=\"hlight\" dir=\"rtl\">١٧٧٦</span> م .). علاوه بر آثار فلسفی، کتابی نیز در تاریخ انگلستان تألیف کرده است . (از فرهنگ عمید).<br></font></div>'),
(269595, 'هیوم', '<span class=\"hlight\">هیوم .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) سرگشته . (منتهی الارب ) (آنندراج ). متحیر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تشنه . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(269596, 'هیون', '<span class=\"hlight\">هیون .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ) به معنی شتر باشد مطلقاً و به عربی بعیر خوانند و بعضی گویند هیون شتر جمازه است و بعضی شتر بزرگ را گویند و هرجانور بزرگ را نیز گفته اند. (برهان ). شتر بزرگ . (حاشیه ٔ فرهنگ اسدی ). شتر بزرگ جمازه . (صحاح الفرس ). شتر جمازه که به رفتار تند و تیز است و سوار آن به چاپاری به منزل رسد. (آنندراج ) (انجمن آرا) <span class=\"hlight\">:</span> <br>چگونه یابند اعدای او قرار کنون <br>زمانه چون شتری شد هیون و ایشان خار.<br> <font color=\"Red\">دقیقی .</font><br>ز دریا به دریا نبد هیچ راه <br>ز اسب و ز پیل و هیون و سپاه .<br> <font color=\"Red\">فردوسی .</font><br>پراکند هر سو هیونی دوان <br>یکی مرد بیدار و روشن روان .<br> <font color=\"Red\">فردوسی .</font><br>هیون دوکوهه دگر ششهزار<br>همه بارشان آلت کارزار.<br> <font color=\"Red\">اسدی .</font><br>غژغاودم گوزن سرین و غزال چشم <br>پیل زرافه گردن و گور هیون بدن .<br> <font color=\"Red\">لامعی .</font><br>مرکب شعر و هیون علم و ادب را<br>طبع سخن سنج من عنان و مهار است .<br> <font color=\"Red\">ناصرخسرو (از انجمن آرا) (از آنندراج ).</font><br>هایل هیونی تیزدو اندک خور و بسیاررو<br>از آهوان برده گرو در پویه و در تاختن .<br> <font color=\"Red\">امیرمعزی .</font><br>تو را کوه پیکر هیون میبرد<br>چه دانی که بر ما چه شب میرود.<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> اسب . (برهان ) (صحاح الفرس ) (لغت نامه ٔ اسدی ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br>دو بازو بکردار ران هیون <br>برش چون بر شیر و چهرش چو خون .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(269597, 'هیوند', '<span class=\"hlight\">هیوند.</span> <font color=\"DarkGreen\"><b>[ هی وَ ]</font></b> (اِ) بر وزن ریوند، عفت و پرهیزگاری . (برهان ) (آنندراج ).<br></font></div>'),
(269598, 'هیوه', '<span class=\"hlight\">هیوه .</span> <font color=\"DarkGreen\"><b>[ هی وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (اِ) متجدد شدن و تجدد یافتن . <BR><font color=\"Blue\">◄</font> متبدل و متغیر گردیدن . (آنندراج ) (انجمن آرا).<br></font></div>'),
(269599, 'هیوی', '<span class=\"hlight\">هیوی .</span> <font color=\"DarkGreen\"><b>[ هََ ی َ وی ی ]</font></b> (ع ص نسبی ) منسوب به هیأت . <BR><font color=\"Blue\">◄</font> عالم به علم هیأت . اخترشناس . ستاره شناس . ستاره شمر. اخترشمار. رجوع به هیأت شود.<br></font></div>'),
(269600, 'هیپوفیز', '<span class=\"hlight\">هیپوفیز.</span> <font color=\"DarkGreen\"><b>[ پ ُ ]</font></b> (فرانسوی، اِ) (غده ٔ...) غده ای است فرد به اندازه ٔ یک فندق که در خط وسط در داخل زین ترکی  استخوان خفاشی  کاملاً پنهان است . وزن متوسط این غده در مرد <span class=\"hlight\" dir=\"rtl\">٠/٥</span> الی <span class=\"hlight\" dir=\"rtl\">٠/٦</span> گرم و در زن قدری سنگین تر است، یعنی مابین <span class=\"hlight\" dir=\"rtl\">٠/٦</span> تا <span class=\"hlight\" dir=\"rtl\">٠/٧</span> گرم است .قطب فوقانی هیپوفیز بواسطه ٔ استطاله ای به نام ساقه ٔپی تویتر یا قمعالدماغ به برآمدگی واقع در سطح تحتانی مغز موسوم به توبرسینروم  مربوط میگردد. هیپوفیز از اطراف محدود است به نوارک های بینایی  در طرفین و مجمعالنورین  در بالا (که غده را از کف بطن سوم مجزا میسازد)، و پایک های مغزی  در عقب . در مقطع غده سه منطقه ٔ متمایز مشاهده میشود:یکی قدامی به رنگ زرد متمایل به قرمز به نام لب قدامی، دیگری خلفی به رنگ سفید مایل به خاکستری موسوم به لب خلفی و بین این دو منطقه یک تیغه ٔ نسجی وجود دارد موسوم به لب واسطه ای . اعمال غده ٔ هیپوفیز تحت نظارت هسته های خاکستری ناحیه ٔ هیپوتالاموس  میباشد و راه اثر آن بوسیله ٔ الیاف عصبی فراوانی است که به توسط ساقه ٔ پی توویتر وارد هیپوفیز میشود و به لب خلفی آن منتهی میگردد. به نظر می آیدکه لب قدامی هیپوفیز تنها از راه خون تحت تأثیر خارج قرار دارد. لب قدامی به تنهایی <span class=\"hlight\" dir=\"rtl\">٣٤</span> تمام غده را تشکیل میدهد و دارای دو نوع سلولهای رنگ پذیر و رنگ ناپذیر میباشد. در لب خلفی سلولهای عصبی فراوانند و بعلاوه دارای سلولهای نِوْروگلی است . در لب واسطه ای ساختمان غده ای مشاهده میشود و سلولهای بازوفیل  در آن وجود دارد. این سلولها ماده ٔ کلوئیدی ترشح میکنند که درفضاهای بین سلولی جمع میشود. برداشتن غده موجب بروز اختلالات و عوارض شدیدی در بدن میشود و بسته به این است که لب قدامی یا لب خلفی یا تمام غده را بردارند و عوارض این عمل در حیوان بالغ و نابالغ متفاوت است :<br>الف -برداشتن لب قدامی . <span class=\"hlight\" dir=\"rtl\">١</span>- در حیوان جوان، نمو حیوان جوان فوراً متوقف میشود (پیدایش نانیسم  در پستانداران و فقدان دگردیسی در نوزاد قورباغه ) و اعمال سایر غدد مترشحه ٔ داخلی نیز متوقف میگردد. <span class=\"hlight\" dir=\"rtl\">٢</span>- در حیوان بالغ، موجب اختلال متابولیسم مواد غذایی و نقصان اعمال غدد داخلی میشود. از نظر جنسی غدد تناسلی حیوان صغر پیدا کرده و صفات جنسی فرعی از بین میروند. دوره ٔ تخمدانی در حیوان ماده قطع میشود و حیوان دیگر آبستن نخواهد شد.<br>ب - برداشتن لب واسطه ای و خلفی . برداشتن لب خلفی هیپوفیز در پستانداران موجب ازدیاد شدید ترشح ادرار میشود و پوست رنگ پریده میگردد. باید دانست که کلیه ٔ عوارض ناشی از برداشتن لب های مختلف هیپوفیز با پیوند غده و یا تزریق عصاره های آن برطرف میگردد ولی استعمال آنها از راه جهاز هاضمه بی اثر است . غده ٔ زیرمغزی . جبل رمادی دماغ . (فرهنگ فارسی معین ).<br></font></div>'),
(269601, 'هیپوکرات', '<span class=\"hlight\">هیپوکرات .</span> <font color=\"DarkGreen\"><b>[ پ ُ کْرا <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (اِخ ) بقراط. رجوع به بقراط شود.<br></font></div>'),
(269602, 'هیچ', '<span class=\"hlight\">هیچ .</span> (اِ، ص، ق ) چیزی : در این صندوق جزجامه هیچ نبود. (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> <br>آگه شدم که خدمت مخلوق هیچ نیست <br>هست از همه گزیر و ز اﷲ ناگزیر.<br> <font color=\"Red\">سوزنی .</font><br>پس بگفتند پند و هیچ نگفت <br>می کشیدند و او دگر می خفت .<br> <font color=\"Red\">اوحدی .</font><br>- <span class=\"hlight\">به هیچ </span> ؛ به چیزی <span class=\"hlight\">:</span> <br>از یاد تو غافل نتوان کرد به هیچم <br>سرکوفته مارم نتوانم که نپیچم .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">به هیچ داشتن </span> ؛ به هیچ شمردن . به چیزی نشمردن <span class=\"hlight\">:</span> گفت بدانید که ما هیچ زن از آن ِ او نداریم و نبرده ایم و اگر برده بودیمی بگفتیمی و به هیچ داشتیمی . (اسکندرنامه ).<br>- <span class=\"hlight\">به هیچ شمردن </span> ؛ به چیزی شمردن <span class=\"hlight\">:</span> <br>بیچارگیم به چیز نگرفتی <br>درماندگیم به هیچ نشمردی .<br> <font color=\"Red\">سعدی .</font><br>گرت چو من غم عشقی زمانه پیش آرد<br>دگر غم همه عالم به هیچ نشماری .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">به هیچ گرفتن </span> ؛ به چیزی نگرفتن . اعتناء نکردن <span class=\"hlight\">:</span> <br>تو روی از پرستیدن حق مپیچ <br>بهل تا نگیرند خلقت به هیچ .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">بی هیچ </span> . رجوع به بی هیچ شود.<br>- <span class=\"hlight\">هیچ داشتن </span> ؛ چیزی نداشتن <span class=\"hlight\">:</span> <br>بگفتا من دلی پرپیچ دارم <br>اگر این خر بیفتد هیچ دارم .<br> <font color=\"Red\">عطار.</font><br>- <span class=\"hlight\">هیچدان و هیچمدان </span> ؛ نادان و بی علم . (آنندراج ) <span class=\"hlight\">:</span> <br>بسکه هر چیز از می شوق تو بیخود گشته اند<br>لب به توصیف تو بگشاده ست عقل هیچدان .<br> <font color=\"Red\">ظهوری (از آنندراج ).</font><br> <BR><font color=\"Blue\">◄</font> یک <span class=\"hlight\">:</span> <br>تا همی خلق جهان را به جهان عید بود<br>هیچ عیدی که بود بی تو خداوند مباد.<br> <font color=\"Red\">فرخی .</font><br>گر هیچ سخن گویم با تو ز شکر خوشتر<br>صد کینه به دل گیری صد اشک فروباری .<br> <font color=\"Red\">منوچهری .</font><br>- <span class=\"hlight\">هیچ روز</span> ؛ حتی یک روز.<br>- <span class=\"hlight\">هیچ شب </span> ؛ حتی یک شب .<br>- <span class=\"hlight\">هیچگاه </span> ؛ حتی یک گاه .<br> <BR><font color=\"Blue\">◄</font> اصلاً. ابداً. هرگز. مطلقاً. به هیچ وجه . اسم بعداز هیچ غالباً مفرد آید <span class=\"hlight\">:</span> <br>که آخر بدین بارگاه مهی <br>نیامد ز بهرام هیچ آگهی .<br> <font color=\"Red\">فردوسی .</font><br>بخور می مخور هیچ اندوه و غم <br>که از غم فزونی نیاید نه کم .<br> <font color=\"Red\">فردوسی .</font><br>هیچ ندانم به چه شغل اندری <br>ترف همی غنچه کنی یا شکر.<br> <font color=\"Red\">ابوالعباس عباسی .</font><br>تو مکن هیچ درنگ ارچه شتاب از دیو است <br>که فرشته شوی ار هیچ در این بشتابی .<br> <font color=\"Red\">سوزنی .</font><br>ای شغال بی جمال و بی هنر<br>هیچ بر خود ظن طاوسی مبر.<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> باری . کرّتی . (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> <br>از لطف بجایی ست که گر هیچ خرد را<br>پرسند که جان چیست خردگوید جان اوست .<br> <font color=\"Red\">سنایی .</font><br> <BR><font color=\"Blue\">◄</font> برطرف شده و معدوم شده و لاشی ٔ. (برهان ). معدوم . (آنندراج ) <span class=\"hlight\">:</span> <br>این همه هیچ است چون می بگذرد<br>تخت و بخت و امر و نهی و گیر و دار.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هیچ شدن </span> ؛ معدوم شدن . نیست شدن . فنا شدن .<br>- <BR><font color=\"Blue\">◄</font> بی اثر گشتن . در حکم نیست و معدوم درآمدن <span class=\"hlight\">:</span> <br>چو طالع ز ما روی برپیچ شد<br>سپر پیش تیر قضا هیچ شد.<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> ذره ای . کمترین مقداری . اندکی . کمی . یک ذره . کنایه از اندک و قلیل و کم . (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br>وگر هیچ خوی بد آرد پدید<br>بسان پدر سرْش باید برید.<br> <font color=\"Red\">فردوسی .</font><br>گر هیچ سخن گویم با تو ز شکر خوشتر<br>صد کینه به دل گیری صد اشک فروباری . <br> <font color=\"Red\">منوچهری .</font><br>نه در جهان جلال چون جلال او<br>نه هیچ کبریا چو کبریای او.<br> <font color=\"Red\">منوچهری .</font><br>کسی کز خدمتت دوری کند هیچ <br>بر او دشمن شود گردون گردا.<br> <font color=\"Red\">عسجدی .</font><br>نان کشکین اگر بیابم هیچ <br>راست گویی زلیبیا باشد.<br> <font color=\"Red\">مسعودسعد.</font><br>گر آرد ملک هیچ بخشایشی <br>رساند بدین کشور آسایشی .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">هیچ شمردن </span> ؛ حقیر و ناچیز شمردن .<br>- <span class=\"hlight\">هیچ کس </span> ؛ ناکس . (غیاث اللغات از مصطلحات ). بی سروپا. دنی . فرومایه . تمام بی ارز <span class=\"hlight\">:</span> قل بن قل ؛ هیچ کس پسر هیچ کس . (مهذب الاسماء).<br>که صواب این است و راه این است و بس <br>کی زند طعنه مرا جز هیچ کس .<br> <font color=\"Red\">مولوی .</font><br>مکن نماز بر آن هیچ کس که هیچ نکرد<br>که عمر بر سر تحصیل مال کرد و نخورد.<br> <font color=\"Red\">سعدی .</font><br>چند چون گل هوس بزم خسان خواهی کرد<br>چند هم صحبتی هیچ کسان خواهی کرد.<br> <font color=\"Red\">ملک قمی (از آنندراج ).</font><br>- <BR><font color=\"Blue\">◄</font> احدی . کسی . یک تن . کس . دیاری <span class=\"hlight\">:</span> <br>خویشتن پاک دار بی پرخاش <br>هیچ کس را مباش عاشق غاش .<br> <font color=\"Red\">رودکی .</font><br>چو تو نیست اندر جهان هیچ کس <br>جهاندار دانش تو را داد و بس .<br> <font color=\"Red\">دقیقی .</font><br>که نگشاید این دست من هیچ کس <br>بجز جفت گلشهر در دهر و بس .<br> <font color=\"Red\">فردوسی .</font><br>سرانجام از او بهره خاک است و بس <br>رهایی نیابد از آن هیچ کس .<br> <font color=\"Red\">فردوسی .</font><br>تا بدانی که وقت پیچاپیچ <br>هیچ کس مر تو را نباشد هیچ .<br> <font color=\"Red\">سنایی .</font><br>یا نبد هیچ کس از باده فروشان بیدار<br>یا چو من هیچ کسم هیچ کسم در نگشود.<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> گاهی <span class=\"hlight\">:</span> <br>چون با دگری من بگشایم تو ببندی <br>ور با دگری هیچ ببندم تو گشایی .<br> <font color=\"Red\">منوچهری .</font><br>پوستین سازی مر دیده ٔ خود را مانا<br>تا به دی نفسرد ار هیچ به صحرا مانی .<br> <font color=\"Red\">سوزنی .</font><br> <BR><font color=\"Blue\">◄</font> احیاناً. اتفاقاً. (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> <br>هیچ گر ازچشم بد بر تو گزندی رسد<br>خال رخ تو ز تو دفع کند آن گزند.<br> <font color=\"Red\">سوزنی .</font><br>گر هیچ به سیب زنخش بازرسی <br>باری بررس که نرخ شفتالو چیست .<br> <font color=\"Red\">شمس الدین قندهاری .</font><br> <BR><font color=\"Blue\">◄</font> برای استفهام و به معنی هل عربی . آیا: هل لنا من شفعاء. (قرآن <span class=\"hlight\" dir=\"rtl\">٥٣/٧</span>)؛ هیچ شفیعان هستند ما را؟ <BR><font color=\"Blue\">◄</font> در حقیقت . واقعاً. فی الواقع. (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> <br>گفتی احول یکی دو بیند چون <br>من نبینم از آنچه هست فزون <br>احول ار هیچ کج شمارستی <br>بر فلک مه که دوست چارستی .<br> <font color=\"Red\">سنایی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">تا نپرسندت مگر از هیچ باب </span> .<br> <span class=\"hlight\">در هیچ مپیچ </span> .<br> <span class=\"hlight\">هیچ بده را به هیچ بستان کاری نیست </span> .<br> <span class=\"hlight\">هیچ بودی هیچ خواهی شد هم اکنون هیچ باش </span> .<br> <font color=\"Red\">عطار.</font><br> <span class=\"hlight\">هیچ دویی نیست که سه نشود</span> .<br> <span class=\"hlight\">هیچ گنجشک نگردد چو عقاب </span> .<br> <font color=\"Red\">ادیب صابر.</font><br> <span class=\"hlight\">هیچ معشوق رانبوده وفا</span> .<br><font color=\"Red\">ادیب صابر.</font><br></font></div>'),
(269603, 'هیچ مدان', '<span class=\"hlight\">هیچ مدان .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (نف مرکب ) هیچ دان . نادان . جاهل و بی علم . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br>یارم همه دانی و خودم هیچ مدانی <br>یارب چه کند هیچ مدان با همه دانی .<br><font color=\"Red\">؟</font><br></font></div>'),
(269604, 'هیچ مرد', '<span class=\"hlight\">هیچ مرد.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِ مرکب ) کنایه از مرد ضعیف و زبون . (آنندراج ) <span class=\"hlight\">:</span> <br>جهان آن کسی راست کو در نبرد<br>پی مرد نگذاشت بر هیچ مرد.<br><font color=\"Red\">نظامی (از آنندراج ).</font><br></font></div>'),
(269605, 'هیچ ندان', '<span class=\"hlight\">هیچ ندان .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (نف مرکب ) هیچ مدان . جاهل و نادان .<br></font></div>'),
(269606, 'هیچ و پوچ', '<span class=\"hlight\">هیچ و پوچ .</span> <font color=\"DarkGreen\"><b>[ چ ُ ]</font></b> (ترکیب عطفی، اِ مرکب ) کنایه از چیز سهل و بی مغز. (آنندراج ) <span class=\"hlight\">:</span> <br>کرد پهلو خالی از ما یار دیرین چون حباب <br>زد به هیچ و پوچ برهم ربط چندین ساله را.<br> <font color=\"Red\">محسن تأثیر (از آنندراج ).</font><br>- <span class=\"hlight\">به هیچ و پوچ </span> ؛ بی جهت . بی علت : خانه را به هیچ و پوچ از دست داد.<br></font></div>'),
(269607, 'هیچ وجه', '<span class=\"hlight\">هیچ وجه .</span> <font color=\"DarkGreen\"><b>[ وَج ْه ْ ]</font></b> (ق مرکب ) هیچ طور. هیچ گونه .<br></font></div>'),
(269608, 'هیچ وقت', '<span class=\"hlight\">هیچ وقت .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (ق مرکب ) هرگز. هیچ گاه <span class=\"hlight\">:</span> <br>چو من دستگه داشتم هیچ وقت <br>زبان مرا عادت «نه » نبود.<br> <font color=\"Red\">مسعودسعد (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>).</font><br>ای بزرگی که مثل توننمود<br>هیچ وقتی سپهر آینه وار.<br><font color=\"Red\">مسعودسعد.</font><br></font></div>'),
(269609, 'هیچ چیز', '<span class=\"hlight\">هیچ چیز.</span> (ق مرکب ) چیزی . به چیزی . <BR><font color=\"Blue\">◄</font> (ص مرکب ) بی اعتبار. بی ارزش . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">به همه هیچ چیز خریدن </span> ؛ بضاعت فراوان در مقابل متاع بی ارزشی دادن . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">به هیچ چیز برنگرفتن </span> ؛ ارزش ننهادن . به چیزی نشمردن . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">هیچ چیز نشمردن </span> ؛ وقع ننهادن . اهمیت ندادن .(فرهنگ فارسی معین ).<br></font></div>'),
(269610, 'هیچ کاره', '<span class=\"hlight\">هیچ کاره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص مرکب ) ردی . پست . که به هیچ کار نیاید: عسیقة؛ شراب هیچ کاره ٔ بسیارآب . مصران الفار؛ نوعی از خرمای هیچ کاره . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کسی که کاری و شغلی ندارد. آنکه برای کاری شایسته نیست . <BR><font color=\"Blue\">◄</font> کنایه از مردم ضعیف و بی اعتبار و فرومایه . (آنندراج ) <span class=\"hlight\">:</span> <br>ما را ز منع عقل مترسان و می بیار<br>کان شحنه در ولایت ما هیچ کاره نیست .<br> <font color=\"Red\">حافظ.</font><br>در فکر آن دهانم و در یاد آن کمر<br>چون من به روزگار کسی هیچ کاره نیست .<br> <font color=\"Red\">فطرت (از آنندراج ).</font><br>- <span class=\"hlight\">امثال </span> :<br><span class=\"hlight\">همه کاره هیچ کاره </span> ؛ کسی که صلاحیت هیچ کار ندارد و خود را داخل هر کار میکند.<br></font></div>'),
(269611, 'هیچ کس', '<span class=\"hlight\">هیچ کس .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (ضمیر مبهم مرکب ) کسی . شخصی . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> (ص مرکب ) ناچیز. بی چیز. بی ارزش . نالایق . (فرهنگ فارسی معین ). فعل و ضمیر آن مفرد آید. (از مفرد و جمع معین ص <span class=\"hlight\" dir=\"rtl\">٢١٨</span>). رجوع به هیچ و ترکیب هیچ کس شود.<br></font></div>'),
(269612, 'هیچ گاه', '<span class=\"hlight\">هیچ گاه .</span> (ق مرکب ) هیچ وقت . هرگز <span class=\"hlight\">:</span> <br>گر کند هیچ گاه قصد گریز<br>خیز ناگه به گوشش اندر میز.<br><font color=\"Red\">خسروی .</font><br></font></div>'),
(269613, 'هیچ گونه', '<span class=\"hlight\">هیچ گونه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ق مرکب ) هیچ قسم <span class=\"hlight\">:</span> <br>مگردان دل از مهر افراسیاب <br>مکن هیچ گونه به رفتن شتاب .<br> <font color=\"Red\">فردوسی .</font><br>ز فرمان او هیچ گونه مگرد<br>تو پیرایه دان بند بر پای مرد.<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(269614, 'هیچی', '<span class=\"hlight\">هیچی .</span> (ص مرکب، اِ مرکب ) مخفف هیچ چیز. رایگان . مفت . مجان . بلاشی ٔ <span class=\"hlight\">:</span> <br>ثنای منتجب گفتن به هیچی <br>به از خلعت گرفتن زندنیچی <br>مرا در شعر گویی هیچکس داشت <br>پس آنگه هیچکس را داد هیچی .<br> <font color=\"Red\">سوزنی .</font><br>هیچ بودی هیچ خواهی شد هم اکنون هیچ باش <br>زان که گر هیچی نگردی تو ز هیچی کم شوی .<br> <font color=\"Red\">عطار.</font><br>- <span class=\"hlight\">امثال </span> :<br><span class=\"hlight\">کاچی به از هیچی </span> .<br></font></div>'),
(269615, 'هیژده', '<span class=\"hlight\">هیژده .</span> <font color=\"DarkGreen\"><b>[ دَه ْ ]</font></b> (عدد، ص، اِ) هیجده . هجده . ثمانیةعشر.<br></font></div>'),
(269616, 'هیکس', '<span class=\"hlight\">هیکس .</span> <font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (اِخ ) نام قبایلی که مصر را مسخر کردند.<br></font></div>'),
(269617, 'هیکل', '<span class=\"hlight\">هیکل .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ک َ ]</font></b> (اِ) بتخانه . (برهان ) (مهذب الاسماء). عبادت خانه ٔ ترسایان که در آن صور و تماثیل باشد. بتخانه است به زبان پهلوی . (لغت نامه ٔاسدی ). خانه ٔ ترسایان که در آن پیکر مریم علیها سلام باشد. (منتهی الارب ). کلیسیای ترسایان . بهارخانه . بتکده . دارالاصنام . بیت الصنم . (منتهی الارب ). پرستشگاه بت . بیت الصور. (مفاتیح خوارزمی ). بیت النار. آتشکده . معبد. بتخانه . مولانا جلال دوانی گوید: هیکل به معنی صورت و پیکر و حکماء خانه ای چند میساختند در طالعهای خاص در آن خانه طلسمات نقش میکردند بنام کواکب سبعه و آن خانه ها را تعظیم میکردند و عبادت مینمودند و میرغیاث الدین منصور به معنی بدن آورده اما در عربی نیز این لفظ را آورده و به هیاکل جمع بسته اند <span class=\"hlight\">:</span> <br>چنان دان که این هیکل از پهلوی <br>بود نام بتخانه ار بشنوی .<br> <font color=\"Red\">عنصری .</font><br>تو گفتی هیکل زردشت گشته ست <br>ز بس لاله همه صحرا سراسر.<br> <font color=\"Red\">لبیبی .</font><br>- <span class=\"hlight\">هیکل الروم، هیکل روم </span> ؛ نام بتخانه ای که در روم بوده است . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br>دبیرستان کنم در هیکل روم <br>کنم آئین مطران را مطرا.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">هیکل النار</span> ؛ آتشکده .<br> <BR><font color=\"Blue\">◄</font> تعویذ. حرز. دعا که به بازو بندند چشم زخم را <span class=\"hlight\">:</span> <br>حور را حِرز و هیکل است آن خط<br>که سنائی بر آن نهاد نمط.<br> <font color=\"Red\">سنائی .</font><br>هیکل و نشره و حرزی که اجل بازنداشت <br>هم به تعویذدِه شعبده گر باز دهید.<br> <font color=\"Red\">خاقانی .</font><br>این نامه هفت عضو مرا هفت هیکل است <br>کایمن کند ز هول سباع و شرِ هوام .<br> <font color=\"Red\">خاقانی .</font><br>خاص از برای وسوسه ٔ دیو نفس را<br>شاید گر این سخن بنویسی به هیکلی .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هیکل کردن </span> ؛ چون حمائل بندی، حلقه ای را از یک سوی دوش به زیر بغل جانب مقابل بردن : قرآن را هیکل کردن ؛ حمایل کردن قرآن خرد. (یادداشت مؤلف ).<br>- <span class=\"hlight\">هیکل وار</span> ؛ همانند هیکل . حمایل وار <span class=\"hlight\">:</span> <br>دشمنانش همره غولند اگر خود بهر حرز<br>هشت حرفش هفت هیکل واردر بر ساختند.<br> <font color=\"Red\">خاقانی .</font><br> <BR><font color=\"Blue\">◄</font> نقش و تصویر. نقش و نگار<span class=\"hlight\">:</span> <br>بر آن لوح چون خط یونانیان <br>چهل حرف و شش هیکل اندر میان .<br> <font color=\"Red\">اسدی (گرشاسبنامه ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span>).</font><br>- <span class=\"hlight\">هیکل بستن </span> ؛ کستی بستن . زنار بستن . به کمر بستن بندی که نزد زرتشتیان کشتی یا کستی نام دارد و برهمنان و ترسایان زنار اصطلاح کرده اند <span class=\"hlight\">:</span> <br>بدان خانه شد شاه یزدان پرست <br>فرودآمد آنجا و هیکل ببست .<br> <font color=\"Red\">فردوسی .</font><br>- <BR><font color=\"Blue\">◄</font> کنایه از مردن و وفات یافتن . (برهان ).<br></font></div>'),
(269618, 'هیکل', '<span class=\"hlight\">هیکل .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ ]</font></b> (اِخ ) مقصود از هیکل در بیشتر مواضع کتاب مقدس هیکل اورشلیم است که در کوه سوریا بنا شده بود و شباهت چادر جماعت میداشت و در کتاب مقدس سه هیکل مذکور است . اول هیکل سلیمان میباشد. داود اراده داشت که هیکلی از برای خداوند بسازد اما خداوند وعده فرمود که پسرش سلیمان آن هیکل را تمام خواهد کرد. دوم هیکل زروبابل . کوروش پادشاه ایران در سال <span class=\"hlight\" dir=\"rtl\">٥٣٦</span> ق . م . امر فرمودکه بعضی از یهود اسرای بابل مراجعت کنند علیهذا عده ٔ کثیری با زروبابل که حکمران ایشان بود مراجعت نمودند در سال دومین بنای هیکل ثانی را گذاشت . سوم هیکل هیردیس . پس از آنکه هیکل زروبابل تخمیناً <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> سال برپا بود آثار خرابی در او پیدا شد و باعث گردید که هیردیس اعظم آن را تعمیر فرماید. (قاموس کتاب مقدس ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(269619, 'هیکل', '<span class=\"hlight\">هیکل .</span> <font color=\"DarkGreen\"><b>[ هََ ک َ ]</font></b> (ع اِ) هیأت . صورت و تنه ٔ مردم . (برهان ). صورت و شکل . (غیاث اللغات ). ریخت . کالبد. پیکر. (منتهی الارب ).صورت و شخص . ج، هیاکل . (اقرب الموارد) <span class=\"hlight\">:</span> <br>در مسکنی که هیچ نفرساید<br>فرسوده گشت هیکل مسکینم .<br> <font color=\"Red\">ناصرخسرو.</font><br>بحری است ژرف عالم کشتیش هیکل تو<br>عمرت چو باد و گردون چون بادبان کشتی .<br> <font color=\"Red\">ناصرخسرو.</font><br>روح القدس براقش وزقدر هیکل او<br>خورشید میخ زر است اندر پی نعالش .<br> <font color=\"Red\">خاقانی .</font><br>تا شود این هیکل خاکی غبار<br>پای به پایت سپرد روزگار.<br> <font color=\"Red\">نظامی .</font><br>پس چو آهن گرچه تیره هیکلی <br>صیقلی کن صیقلی کن صیقلی .<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">بدهیکل </span>؛ بی اندام . سخت زشت و کریه اندام <span class=\"hlight\">:</span> بدهیکلی که صخر جنی از طلعت او برمیدی . (گلستان ).<br>- <span class=\"hlight\">خوش هیکل </span> ؛ زیبا. قشنگ . باندام .<br>- <span class=\"hlight\">دیوهیکل </span> ؛ به شکل و ریخت و صورت دیو <span class=\"hlight\">:</span> <br>ز لاحولم آن دیوهیکل بجست <br>پری پیکر اندر من آویخت دست .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">هیکل خاکی غبار</span> ؛ کنایه از جسد و قالب آدمی باشد. (برهان ) (آنندراج ).<br>- <span class=\"hlight\">هیکل دار</span> ؛باهیکل . جسیم . درشت . تنومند. ضخیم .<br> <BR><font color=\"Blue\">◄</font> هر بنای بلند. (غیاث اللغات ) (منتهی الارب ) (اقرب الموارد). هر بنایی که عظیم و رفیع باشد. (برهان ). <BR><font color=\"Blue\">◄</font> هر حیوان ضخیم و طویل . (اقرب الموارد). هر حیوانی که گنده و جسیم و ضخیم باشد. (برهان ). خر بزرگ . (مهذب الاسماء). جثه ٔ بزرگ و اسب درازجسم . (غیاث اللغات ). اسب دراز ضخیم . (منتهی الارب ).<br>- <span class=\"hlight\">فرس هیکل </span> ؛ مرتفع. (اقرب الموارد).<br>- <span class=\"hlight\">هیکل رضوان </span> ؛ بهشت . کنایه از بهشت است . (برهان ) (آنندراج ).<br><BR><font color=\"Blue\">◄</font> گیاه دراز تمام بالیده . (منتهی الارب ). گیاهی که دراز و بزرگ و رسیده باشد و همچنین است درخت . (اقرب الموارد) (منتهی الارب ). واحد آن هیکلة است . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شکوه .<br></font></div>'),
(269620, 'هیکل آباد', '<span class=\"hlight\">هیکل آباد.</span> <font color=\"DarkGreen\"><b>[ هََ ک َ ]</font></b> (اِخ ) دهی است از دهستان سهندآباد بخش بستان آباد شهرستان تبریز. دارای <span class=\"hlight\" dir=\"rtl\">١٢٥</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(269621, 'هیکلة', '<span class=\"hlight\">هیکلة.</span> <font color=\"DarkGreen\"><b>[ هََ ک َ ل َ ]</font></b> (ع ص ) زن کلان جثه ٔ دراز. (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (مص ) تمام شدن گیاه . (منتهی الارب ) (آنندراج ). هیکل الزرع هیکلة؛ نما و طال . (اقرب الموارد).<br></font></div>'),
(269622, 'هیکلی', '<span class=\"hlight\">هیکلی .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ک َ ]</font></b> (ص نسبی ) منسوب به هیکل . <BR><font color=\"Blue\">◄</font> حمایلی .<br>- <span class=\"hlight\">قرآن هیکلی </span> ؛ قرآنی خرد که توان آن را حمایل کرد. (یادداشت مؤلف ).<br></font></div>'),
(269623, 'هیگر', '<span class=\"hlight\">هیگر.</span><font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ گ َ <span class=\"hlight\" dir=\"rtl\">/</span> هی گ َ ]</font></b> (اِ) اسب کمیت و معنی ترکیبی آن اسب کهر است چه هی به معنی اسب است و کهر نیز نام رنگ کمیت، اسب سیاهی است که به سرخی زند و یال وزانوهایش سیاه باشد و آن را به ترکی قراکهر گویند یعنی سیاه کهر. (آنندراج ) (انجمن آرا). اسب سرخی که به سیاهی مایل بود و یال و دم وی سیاه باشد. (برهان ).<br></font></div>'),
(269624, 'هیی', '<span class=\"hlight\">هیی ٔ.</span> <font color=\"DarkGreen\"><b>[ هََ ی ْ ی ِءْ ]</font></b> (ع ص ) رجل ٌ هیی ٌٔ مرد نیکو پیکر و هیأت . (منتهی الارب ). حَسَن الهیئة. (اقرب الموارد).<br></font></div>'),
(269625, 'هیی', '<span class=\"hlight\">هیی ٔ.</span> (ع اِمص ) اسم مصدر است هأهاءة را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (مص ) به طعام و شراب خواندن . <BR><font color=\"Blue\">◄</font> بر آب خواندن شتر را. (اقرب الموارد). رجوع به هَیْی ٔ شود.<br></font></div>'),
(269626, 'هیی', '<span class=\"hlight\">هیی ٔ.</span> <font color=\"DarkGreen\"><b>[ هََ ی ْءْ]</font></b> (ع مص ) آماده گردیدن جهت کاری . <BR><font color=\"Blue\">◄</font> ساختن هیأت چیزی را. <BR><font color=\"Blue\">◄</font> نیکو و خوش پیکر گردیدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> به طعام و شراب خواندن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بر آب خواندن شتر را. (منتهی الارب ) (از اقرب الموارد). هی ٔ. <BR><font color=\"Blue\">◄</font> یا هَیْی َٔ مالی ؛ کلمه ٔ تعجب است به معنی آگاه باش، یا اسم فعل است به معنی تنبه چون صَه ْ به معنی اسکت . (منتهی الارب ). کلمه ٔ تأسف و افسوس است بر چیزی که از میان رفته باشد و گویند کلمه ٔ تعجب است و گویند اسم فعل است به معنی آگاه باش که مبنی است بر حرکت در ساکن یا بر فتح . (اقرب الموارد).<br></font></div>'),
(269627, 'هیی', '<span class=\"hlight\">هیی .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (فعل ) صورتی و تلفظی محلی از کلمه ٔ هستی . هستی تو. (انجمن آرا) (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br>خان و مان ساز اگر هیی مردم <br>ور چو مرغی بکن نشیمن خویش .<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(269628, 'هییما', '<span class=\"hlight\">هییما.</span> <font color=\"DarkGreen\"><b>[ هَُ ی َی ْ]</font></b> (اِخ ) (یوم الَ ...) هییمی . رجوع به هییماء شود.<br></font></div>'),
(269629, 'هییی', '<span class=\"hlight\">هییی ٔ.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (ع ص ) رجل ٌ هییی ٌٔ؛ مرد نیکوپیکر. (منتهی الارب ) (آنندراج ) (از اقرب الموارد). رجوع به هَیِّی ٔ شود.<br></font></div>');
